        raise exception 'typed_solution_command_required' using errcode='42501'; end if;
      v_plan:=v_new->'develop';v_prior_plan:=v_old->'develop';
      v_plan:=v_plan-'review'-'authorityRevision';
      if v_prior_plan ? 'review' then
        v_plan:=v_plan||pg_catalog.jsonb_build_object('review',v_prior_plan->'review'); end if;
      if v_prior_plan ? 'authorityRevision' then
        v_plan:=v_plan||pg_catalog.jsonb_build_object(
          'authorityRevision',v_prior_plan->'authorityRevision'); end if;
      v_new:=pg_catalog.jsonb_set(v_new,'{develop}',v_plan);
      v_new:=v_new||pg_catalog.jsonb_build_object('nextAction',
        coalesce(v_control.define_next,v_control.pursuit_next,v_old->>'nextAction'));
    end if;
    v_records:=v_records||pg_catalog.jsonb_build_array(v_new);
  end loop;
  return pg_catalog.jsonb_set(p_submitted,'{records}',v_records);
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.crew_booking_eligibility_v1(p_workspace uuid, p_state jsonb, p_assignment jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item jsonb;v_profile d5o_hosted.connected_crew_profiles%rowtype;
  v_person text;v_hours numeric;v_used numeric;v_shift text;v_start integer;v_end integer;
  v_assignment jsonb;
begin
  v_shift:=p_assignment->>'shift';
  if coalesce(v_shift,'') !~ '^\d\d:\d\d[–-]\d\d:\d\d$' then
    raise exception 'invalid_booking_shift' using errcode='23514'; end if;
  v_start:=left(v_shift,2)::integer*60+substring(v_shift from 4 for 2)::integer;
  v_end:=substring(v_shift from 7 for 2)::integer*60+right(v_shift,2)::integer;
  if v_end<=v_start or v_end-v_start>960 then
    raise exception 'invalid_booking_shift' using errcode='23514'; end if;
  v_hours:=(v_end-v_start-case when v_end-v_start>=360 then 30 else 0 end)::numeric/60;
  for v_item in select value from pg_catalog.jsonb_array_elements(p_assignment->'people') loop
    v_person:=v_item#>>'{}';
    select * into v_profile from d5o_hosted.connected_crew_profiles
      where workspace_id=p_workspace and person=v_person and active;
    if not found or v_profile.actor_user_id is null
      or not exists(select 1 from d5o_hosted.crew_bindings b
        join d5o_hosted.memberships m on m.workspace_id=b.workspace_id
          and m.actor_user_id=b.actor_user_id and m.status='active' and m.role='field_worker'
        where b.workspace_id=p_workspace and b.actor_user_id=v_profile.actor_user_id
          and b.person=v_person and b.active) then
      raise exception 'qualified_bound_worker_required' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(p_state->'availabilityBlocks','[]'::jsonb)) b
        where b->>'person'=v_person and b->>'date'=p_assignment->>'date') then
      raise exception 'worker_unavailable_for_shift' using errcode='23514'; end if;
    v_used:=0;
    for v_assignment in select a from pg_catalog.jsonb_array_elements(
      coalesce(p_state->'assignments','[]'::jsonb)) a
      where a->>'id'<>p_assignment->>'id'
        and (a->>'week')::integer=(p_assignment->>'week')::integer
        and a->'people' ? v_person loop
      v_shift:=v_assignment->>'shift';
      if coalesce(v_shift,'') !~ '^\d\d:\d\d[–-]\d\d:\d\d$' then
        raise exception 'invalid_existing_booking_shift' using errcode='23514'; end if;
      v_start:=left(v_shift,2)::integer*60+substring(v_shift from 4 for 2)::integer;
      v_end:=substring(v_shift from 7 for 2)::integer*60+right(v_shift,2)::integer;
      v_used:=v_used+(v_end-v_start-case when v_end-v_start>=360 then 30 else 0 end)::numeric/60;
    end loop;
    if v_used+v_hours>v_profile.weekly_capacity_hours then
      raise exception 'worker_weekly_capacity_exceeded' using errcode='23514'; end if;
  end loop;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.current_work_acceptance_scope_v1(p_workspace uuid, p_work uuid, p_acceptance jsonb, p_require_receipts boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_design jsonb; v_deploy jsonb; v_catalog jsonb; v_presentation text;
  v_package text; v_detail jsonb; v_release jsonb; v_turnover jsonb;
  v_ids text[] := array[]::text[]; v_count integer := 0;
begin
  if p_acceptance is null or p_acceptance->>'id' is null
    or pg_catalog.jsonb_typeof(p_acceptance->'releaseIds') <> 'array'
    or pg_catalog.jsonb_typeof(p_acceptance->'turnoverIds') <> 'array' then
    return false;
  end if;
  select state into v_design from d5o_hosted.connected_design_states
    where workspace_id=p_workspace and work_id=p_work;
  select state into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=p_workspace and work_id=p_work;
  select presentation_id into v_presentation from d5o_hosted.work_identity_links
    where workspace_id=p_workspace and work_id=p_work limit 1;
  select state_json into v_catalog from d5o_hosted.prototype_states
    where workspace_id=p_workspace and state_key='catalog';
  if v_design is null or v_deploy is null or v_presentation is null then return false; end if;

  for v_package in
    select id from (
      select package_id as id from d5o_hosted.connected_package_states
        where workspace_id=p_workspace and work_id=p_work
      union
      select item->>'id' from pg_catalog.jsonb_array_elements(
        coalesce(v_catalog->'packages','[]'::jsonb)) item
        where item->>'workId'=v_presentation
    ) packages where id is not null
  loop
    v_count := v_count + 1;
    v_ids := pg_catalog.array_append(v_ids,v_package);
    select item into v_detail from pg_catalog.jsonb_array_elements(
      coalesce(v_design->'packages','[]'::jsonb)) item
      where item->>'packageId'=v_package;
    select item into v_release from pg_catalog.jsonb_array_elements(
      coalesce(v_design->'releases','[]'::jsonb)) item
      where item->>'packageId'=v_package
      order by item->>'issuedAt' desc limit 1;
    select item into v_turnover from pg_catalog.jsonb_array_elements(
      coalesce(v_deploy->'turnovers','[]'::jsonb)) item
      where item->>'packageId'=v_package and item->>'status'='Client accepted'
        and item->'releaseIds' ? (v_release->>'id')
        and p_acceptance->'turnoverIds' ? (item->>'id')
      order by item->>'acceptedAt' desc limit 1;
    if v_detail is null or v_release is null or v_turnover is null
      or v_release->>'status'<>'Accepted'
      or v_release->>'packageRevision' is distinct from v_detail->>'revision'
      or not (p_acceptance->'releaseIds' ? (v_release->>'id'))
      or (p_require_receipts and v_turnover->>'receipt'<>'Accepted') then return false; end if;
  end loop;
  if v_count=0 or v_count<>pg_catalog.jsonb_array_length(p_acceptance->'releaseIds')
    or v_count<>pg_catalog.jsonb_array_length(p_acceptance->'turnoverIds')
    or v_count<>(select count(*) from pg_catalog.jsonb_array_elements(
      coalesce(v_design->'packages','[]'::jsonb)) item) then return false; end if;
  return true;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.d5o_hosted_operate_command_prior_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_deploy_revision integer, p_expected_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_role text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'operate_membership_required' using errcode='42501'; end if;
  if p_action='accept-support' then
    select m.role into v_role from d5o_hosted.workspaces w
      join d5o_hosted.memberships m on m.workspace_id=w.id
      join d5o_hosted.work_identity_links l on l.workspace_id=w.id
      where w.workspace_key=p_workspace_key and w.status='active'
        and l.presentation_id=p_presentation_id
        and m.actor_user_id=v_actor and m.status='active';
    if v_role is null then
      raise exception 'workspace_forbidden' using errcode='42501'; end if;
    if v_role<>'operations_leader' then
      raise exception 'support_acceptance_authority_required' using errcode='42501'; end if;
  end if;
  return public.d5o_hosted_operate_command_internal_v1(
    p_workspace_key,p_presentation_id,p_action,p_input,p_command_id,
    p_expected_source_revision,p_expected_deploy_revision,p_expected_operate_revision);
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.design_spend_source_v1(p_workspace uuid, p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d d5o_hosted.connected_define_states%rowtype;
 s d5o_hosted.connected_solution_states%rowtype;
 e d5o_hosted.connected_estimate_states%rowtype;
 o d5o_hosted.connected_offer_states%rowtype;
 r d5o_hosted.connected_rom_design_states%rowtype;
 result jsonb;
begin
 select * into d from d5o_hosted.connected_define_states where workspace_id=p_workspace and work_id=p_work;
 select * into s from d5o_hosted.connected_solution_states where workspace_id=p_workspace and work_id=p_work;
 select * into e from d5o_hosted.connected_estimate_states where workspace_id=p_workspace and work_id=p_work;
 select * into o from d5o_hosted.connected_offer_states where workspace_id=p_workspace and work_id=p_work;
 select * into r from d5o_hosted.connected_rom_design_states where workspace_id=p_workspace and work_id=p_work;
 if d.status is distinct from 'Approved' or d.projection#>>'{developHandoff,status}' is distinct from 'accepted'
  or s.status is distinct from 'Approved' or e.status is distinct from 'Approved'
  or e.estimate#>>'{detailed,input,estimateMaturity}' is distinct from 'ROM'
  or e.definition_revision is distinct from d.definition_revision or e.solution_digest is distinct from s.source_digest
  or o.status is distinct from 'Submitted' or o.estimate_revision is distinct from e.estimate_revision
  or r.status is distinct from 'Design authorized' or r.estimate_revision is distinct from e.estimate_revision
  or r.offer_revision is distinct from o.offer_revision or r.definition_revision is distinct from d.definition_revision
  or r.solution_digest is distinct from s.source_digest or r.design_authorization is null then
  return null; end if;
 result:=pg_catalog.jsonb_build_object('defineRevision',d.definition_revision,'solutionDigest',s.source_digest,
  'estimateRevision',e.estimate_revision,'offerRevision',o.offer_revision,'designDecisionRevision',r.decision_revision,
  'authorization',r.design_authorization,
  'approverRole',e.estimate#>>'{detailed,policySnapshot,proposalApproverRole}');
 return result||pg_catalog.jsonb_build_object('digest',pg_catalog.md5(result::text));
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.enforce_prototype_nested_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_key text;
  v_item jsonb;
  v_publication jsonb;
begin
  select w.workspace_key into v_key from d5o_hosted.workspaces w
    where w.id = new.workspace_id;
  if v_key is null or new.state_json->>'workspace' is distinct from v_key then
    raise exception 'prototype_workspace_mismatch' using errcode = '23514';
  end if;
  if new.state_key in ('work', 'catalog') then
    if pg_catalog.jsonb_typeof(new.state_json->'records') is distinct from 'array' then
      raise exception 'prototype_records_invalid' using errcode = '23514';
    end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(new.state_json->'records') loop
      if pg_catalog.jsonb_typeof(v_item) is distinct from 'object'
        or v_item->>'workspace' is distinct from v_key then
        raise exception 'prototype_record_workspace_mismatch' using errcode = '23514';
      end if;
    end loop;
  end if;
  if new.state_key = 'catalog' then
    if pg_catalog.jsonb_typeof(new.state_json->'packages') is distinct from 'array' then
      raise exception 'prototype_packages_invalid' using errcode = '23514';
    end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(new.state_json->'packages') loop
      if pg_catalog.jsonb_typeof(v_item) is distinct from 'object'
        or pg_catalog.left(v_item->>'workId', pg_catalog.length(v_key) + 1) is distinct from v_key || '-' then
        raise exception 'prototype_package_workspace_mismatch' using errcode = '23514';
      end if;
    end loop;
  end if;
  if new.state_key = 'schedule' then
    if pg_catalog.jsonb_typeof(new.state_json->'assignments') is distinct from 'array'
      or pg_catalog.jsonb_typeof(new.state_json->'packageDemands') is distinct from 'array'
      or pg_catalog.jsonb_typeof(new.state_json->'publications') is distinct from 'array' then
      raise exception 'prototype_schedule_invalid' using errcode = '23514';
    end if;
    for v_item in
      select value from pg_catalog.jsonb_array_elements(new.state_json->'assignments')
      union all select value from pg_catalog.jsonb_array_elements(new.state_json->'packageDemands')
    loop
      if pg_catalog.jsonb_typeof(v_item) is distinct from 'object'
        or pg_catalog.left(v_item->>'workId', pg_catalog.length(v_key) + 1) is distinct from v_key || '-' then
        raise exception 'prototype_schedule_workspace_mismatch' using errcode = '23514';
      end if;
    end loop;
    for v_publication in select value from pg_catalog.jsonb_array_elements(new.state_json->'publications') loop
      if pg_catalog.jsonb_typeof(v_publication) is distinct from 'object'
        or pg_catalog.jsonb_typeof(v_publication->'assignments') is distinct from 'array' then
        raise exception 'prototype_publication_invalid' using errcode = '23514';
      end if;
      for v_item in select value from pg_catalog.jsonb_array_elements(v_publication->'assignments') loop
        if pg_catalog.jsonb_typeof(v_item) is distinct from 'object'
          or pg_catalog.left(v_item->>'workId', pg_catalog.length(v_key) + 1) is distinct from v_key || '-' then
          raise exception 'prototype_publication_workspace_mismatch' using errcode = '23514';
        end if;
      end loop;
    end loop;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION d5o_hosted.freeze_accepted_package_set_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid; v_work uuid; v_acceptance jsonb;
begin
  if tg_op='UPDATE' and (old.workspace_id,old.work_id,old.package_id)
    is distinct from (new.workspace_id,new.work_id,new.package_id) then
    raise exception 'connected_package_identity_immutable' using errcode='23514';
  end if;
  v_workspace:=coalesce(new.workspace_id,old.workspace_id);
  v_work:=coalesce(new.work_id,old.work_id);
  -- The same Work row is locked by package, acceptance and Finance commands.
  perform 1 from d5o_hosted.work_records where id=v_work and workspace_id=v_workspace for update;
  select state->'workAcceptance' into v_acceptance
    from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace and work_id=v_work;
  if v_acceptance is not null then
    raise exception 'post_acceptance_package_set_frozen' using errcode='23514';
  end if;
  return case when tg_op='DELETE' then old else new end;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_combined_work_authority_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; w uuid; cap bigint; design_used bigint; po_used bigint;
 sub_used bigint; labor_used bigint; source jsonb;
begin
 ws:=new.workspace_id; w:=new.work_id;
 if tg_table_name='subcontract_reservations' then
  if new.amount_minor<0 then return new; end if;
 end if;
 if tg_table_name='design_spend_commitments' then
  if new.status<>'Approved' then return new; end if;
 end if;
 if tg_table_name='labor_reservations' then
  if new.status<>'Active' then return new; end if;
 end if;
 source:=d5o_hosted.purchase_basis_v1(ws,w);
 select parent_cap_minor into cap from d5o_hosted.purchase_authorities
  where workspace_id=ws and work_id=w and status='Approved'
   and source_digest=source->>'digest' and current_date between valid_from and valid_until
  order by created_at desc limit 1;
 if cap is null then
  if tg_table_name in ('subcontract_reservations','labor_reservations') then
   raise exception 'current_work_economic_authority_required' using errcode='23514';
  end if;
  return new;
 end if;
 select coalesce(sum(amount_minor),0) into design_used from d5o_hosted.design_spend_commitments
  where workspace_id=ws and work_id=w and status='Approved';
 select coalesce(sum(amount_minor),0) into po_used from d5o_hosted.purchase_reservations
  where workspace_id=ws and work_id=w and status='Reserved';
 select coalesce(sum(amount_minor),0) into sub_used from d5o_hosted.subcontract_reservations
  where workspace_id=ws and work_id=w;
 labor_used:=d5o_hosted.labor_exposure_v1(ws,w);
 if design_used+po_used+sub_used+labor_used>cap then
  raise exception 'work_economic_cap_exceeded' using errcode='23514'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_configuration_child_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_old uuid;v_new uuid;
begin
  if tg_op<>'INSERT' then v_old:=old.configuration_version_id; end if;
  if tg_op<>'DELETE' then v_new:=new.configuration_version_id; end if;
  if exists(select 1 from d5o_hosted.configuration_versions v
    where v.id in (v_old,v_new) and v.status in ('validated','published','superseded')) then
    raise exception 'published_configuration_immutable' using errcode='23514'; end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_connected_identity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_link record;v_record jsonb;v_prior jsonb;v_count integer;
begin
  if new.state_key not in ('work','catalog') or not exists (
    select 1 from d5o_hosted.work_identity_links l
      where l.workspace_id=new.workspace_id) then return new; end if;
  if pg_catalog.jsonb_typeof(new.state_json->'records') is distinct from 'array' then
    raise exception 'connected_records_missing' using errcode='42501'; end if;
  for v_link in select work_id,presentation_id from d5o_hosted.work_identity_links
      where workspace_id=new.workspace_id loop
    select count(*),(pg_catalog.jsonb_agg(item)->0) into v_count,v_record
      from pg_catalog.jsonb_array_elements(new.state_json->'records') item
      where item->>'id'=v_link.presentation_id;
    if v_count<>1 or v_record->>'canonicalWorkId' is distinct from v_link.work_id::text
      or v_record->>'workspace' is distinct from (
        select workspace_key from d5o_hosted.workspaces where id=new.workspace_id) then
      raise exception 'connected_identity_changed' using errcode='42501'; end if;
    if tg_op='UPDATE' then
      select item into v_prior from pg_catalog.jsonb_array_elements(
        old.state_json->'records') item where item->>'id'=v_link.presentation_id;
      if coalesce(v_prior->'packages','[]'::jsonb) is distinct from
        coalesce(v_record->'packages','[]'::jsonb) then
        raise exception 'typed_package_command_required' using errcode='42501'; end if;
      if new.state_key='work' and exists(
        select 1 from d5o_hosted.connected_offer_states o
          where o.workspace_id=new.workspace_id and o.work_id=v_link.work_id)
        and v_prior#>'{discovery,proposal}' is distinct from
          v_record#>'{discovery,proposal}' then
        raise exception 'typed_offer_command_required' using errcode='42501'; end if;
    end if;
  end loop;
  if tg_op='UPDATE' and new.state_key='catalog' and
    (select coalesce(pg_catalog.jsonb_agg(item order by ordinal),'[]'::jsonb)
      from pg_catalog.jsonb_array_elements(coalesce(new.state_json->'packages','[]'::jsonb))
        with ordinality as entries(item,ordinal)
      where item->>'workId' in (select presentation_id from
        d5o_hosted.work_identity_links where workspace_id=new.workspace_id))
    is distinct from
    (select coalesce(pg_catalog.jsonb_agg(item order by ordinal),'[]'::jsonb)
      from pg_catalog.jsonb_array_elements(coalesce(old.state_json->'packages','[]'::jsonb))
        with ordinality as entries(item,ordinal)
      where item->>'workId' in (select presentation_id from
        d5o_hosted.work_identity_links where workspace_id=new.workspace_id)) then
    raise exception 'typed_package_command_required' using errcode='42501'; end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_design_cost_review_delegate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); enabled_at timestamptz; chosen uuid;
begin
 if old.status<>'Prepared' or new.status not in ('Reviewed','Returned') then return new; end if;
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=new.workspace_id and category='design_cost_review';
 if enabled_at is null or old.created_at<enabled_at then return new; end if;
 chosen:=d5o_hosted.spending_delegate_selected_v1(new.workspace_id,new.work_id,
  'design_cost_review','billing_commercial_lead',old.amount_minor,old.currency,
  old.prepared_by,current_date);
 if chosen is null then raise exception 'spending_delegate_or_sponsor_required' using errcode='23514'; end if;
 if actor is distinct from chosen then
  raise exception 'selected_spending_reviewer_required' using errcode='42501'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_design_parent_economic_cap_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb; authority d5o_hosted.purchase_authorities%rowtype; design_used bigint; purchase_used bigint;
begin
 if old.status='Prepared' and new.status='Approved' and exists(
  select 1 from d5o_hosted.purchase_authorities where workspace_id=new.workspace_id and work_id=new.work_id
   and status in ('Approved','Revoked')) then
  source:=d5o_hosted.purchase_basis_v1(new.workspace_id,new.work_id);
  select * into authority from d5o_hosted.purchase_authorities
   where workspace_id=new.workspace_id and work_id=new.work_id and status='Approved'
    and source_digest=source->>'digest' and current_date between valid_from and valid_until
   order by created_at desc limit 1 for update;
  if authority.id is null then raise exception 'current_work_economic_authority_required' using errcode='23514'; end if;
  select coalesce(sum(amount_minor),0) into design_used from d5o_hosted.design_spend_commitments
   where workspace_id=new.workspace_id and work_id=new.work_id and status='Approved';
  select coalesce(sum(amount_minor),0) into purchase_used from d5o_hosted.purchase_reservations
   where workspace_id=new.workspace_id and work_id=new.work_id and status='Reserved';
  if new.amount_minor>authority.parent_cap_minor-design_used-purchase_used then
   raise exception 'work_economic_cap_exceeded' using errcode='23514'; end if;
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_field_change_design_release_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_release jsonb;v_change d5o_hosted.connected_field_changes%rowtype;
begin
  for v_release in select value from pg_catalog.jsonb_array_elements(
    coalesce(new.state->'releases','[]'::jsonb)) loop
    if tg_op='UPDATE' and exists(select 1 from pg_catalog.jsonb_array_elements(
      coalesce(old.state->'releases','[]'::jsonb)) prior
      where prior->>'id'=v_release->>'id') then continue; end if;
    -- A resolved field change remains part of the exact design source. Never
    -- let resolution erase the requirement for its reviewed revised basis.
    for v_change in select * from d5o_hosted.connected_field_changes c
      where c.workspace_id=new.workspace_id and c.work_id=new.work_id
        and c.package_id=v_release->>'packageId' and c.kind='Scope change' loop
      if v_change.status not in ('Customer authorized','Resolved')
        or not (v_change.facts ? 'customerAuthorization') then
        raise exception 'customer_change_authorization_required' using errcode='23514'; end if;
      if (v_release->>'packageRevision')::integer<=v_change.opened_package_revision
        or not exists(select 1 from pg_catalog.jsonb_array_elements(
          coalesce(new.state->'changes','[]'::jsonb)) item
          where item->>'packageId'=v_change.package_id
            and item->>'source'=('field-change:'||(v_change.id::text))
            and item->>'status'='Resolved'
            and (item->>'openedRevision')::integer=v_change.opened_package_revision) then
        raise exception 'field_change_design_revision_required' using errcode='23514'; end if;
    end loop;
  end loop;
  return new;
end; $function$

