CREATE OR REPLACE FUNCTION d5o_hosted.guard_graybar_field_material_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_state jsonb;v_permit jsonb;v_material jsonb;v_received numeric;v_returned numeric;
begin
  select state into v_state from d5o_hosted.graybar_states
    where workspace_id=new.workspace_id and work_id=new.work_id;
  if v_state is null or v_state#>>'{bom,status}'<>'Approved' then return new; end if;
  for v_permit in select value from jsonb_array_elements(coalesce(new.state->'permits','[]'::jsonb))
    where value->>'status'='Authorized' and not exists (
      select 1 from jsonb_array_elements(coalesce(old.state->'permits','[]'::jsonb)) prior
      where prior->>'id'=value->>'id') loop
    for v_material in select value from jsonb_array_elements(v_state#>'{bom,lines}')
      where value->>'packageId'=v_permit->>'packageId' and value->>'supplyResponsibility'='Rybex' loop
      select coalesce(sum((line->>'acceptedQuantity')::numeric),0) into v_received
        from jsonb_array_elements(v_state->'receipts') r
        join lateral jsonb_array_elements(r->'lines') line on true
        join lateral jsonb_array_elements(v_state->'shipments') s on s->>'id'=r->>'shipmentId'
        join lateral jsonb_array_elements(v_state->'orders') o on o->>'id'=s->>'orderId'
        where o->>'bomId'=v_state#>>'{bom,id}' and line->>'materialId'=v_material->>'materialId';
      select coalesce(sum((ret->>'quantity')::numeric),0) into v_returned
        from jsonb_array_elements(coalesce(v_state->'returns','[]'::jsonb)) ret
        where ret->>'materialId'=v_material->>'materialId';
      if v_received-v_returned<(v_material->>'quantity')::numeric then
        raise exception 'graybar_physically_received_material_required' using errcode='23514'; end if;
    end loop;
  end loop;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_graybar_purchase_authority_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); item jsonb; previous jsonb; line jsonb; quote_row jsonb;
 source jsonb; authority d5o_hosted.purchase_authorities%rowtype;
 reservation d5o_hosted.purchase_reservations%rowtype;
 design_used bigint; purchase_used bigint; computed bigint; quote_line jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'purchase_command_authentication_required' using errcode='42501'; end if;
 for item in select value from pg_catalog.jsonb_array_elements(coalesce(new.state->'orders','[]'::jsonb)) loop
  select value into previous from pg_catalog.jsonb_array_elements(coalesce(old.state->'orders','[]'::jsonb))
   where value->>'id'=item->>'id';
  if previous is null then
   if item->>'status'<>'Prepared' then raise exception 'purchase_transition_invalid' using errcode='23514'; end if;
   continue;
  end if;
  if previous->>'status' in ('Approved','Test submitted','Acknowledged') and
   pg_catalog.jsonb_build_array(previous->'lines',previous->'amountMinor',previous->'currency',
    previous->'bomId',previous->'accountReference',previous->'shipTo',previous->'requiredDate')
   <>pg_catalog.jsonb_build_array(item->'lines',item->'amountMinor',item->'currency',
    item->'bomId',item->'accountReference',item->'shipTo',item->'requiredDate') then
   raise exception 'approved_purchase_basis_immutable' using errcode='23514';
  end if;
  if previous->>'status'='Prepared' and item->>'status'='Approved' then
   if not exists(select 1 from d5o_hosted.memberships where workspace_id=new.workspace_id
    and actor_user_id=actor and status='active' and role='admin') or previous->>'preparedBy'=actor::text then
    raise exception 'independent_purchasing_authority_required' using errcode='42501'; end if;
   source:=d5o_hosted.purchase_basis_v1(new.workspace_id,new.work_id);
   if source is null then raise exception 'current_purchase_commercial_basis_required' using errcode='23514'; end if;
   select * into authority from d5o_hosted.purchase_authorities
    where workspace_id=new.workspace_id and work_id=new.work_id and status='Approved'
     and source_digest=source->>'digest' and current_date between valid_from and valid_until
    order by created_at desc limit 1 for update;
   if authority.id is null then raise exception 'approved_purchase_authority_required' using errcode='23514'; end if;
   if item->>'bomId' is distinct from authority.bom_id then
    raise exception 'purchase_authority_bom_changed' using errcode='23514'; end if;
   if item->>'accountReference' is distinct from authority.graybar_account_reference then
    raise exception 'purchasing_account_not_authorized' using errcode='23514'; end if;
   if item->>'bomId'<>new.state#>>'{bom,id}' or item->>'currency'<>'USD'
    or coalesce(item->>'amountMinor','') !~ '^[1-9][0-9]*$'
    or item->>'accountReference'='' then
    raise exception 'current_purchase_scope_required' using errcode='23514'; end if;
   computed:=0;
   for line in select value from pg_catalog.jsonb_array_elements(item->'lines') loop
    select value into quote_row from pg_catalog.jsonb_array_elements(new.state->'quotes')
     where value->>'id'=line->>'quoteId';
    select value into quote_line from pg_catalog.jsonb_array_elements(coalesce(quote_row->'lines','[]'::jsonb))
     where value->>'lineNumber'=line->>'quoteLineNumber';
    if quote_row is null or quote_line is null or quote_row->>'expiresAt'<current_date::text
     or quote_row->>'accountReference'<>item->>'accountReference'
     or coalesce((quote_row->>'freightMinor')::bigint,0)<>0
     or exists(select 1 from pg_catalog.jsonb_array_elements(new.state->'quotes') q
      where q->>'quoteNumber'=quote_row->>'quoteNumber'
       and (q->>'acceptedAt')::timestamptz>(quote_row->>'acceptedAt')::timestamptz)
     or line->>'graybarSku'<>quote_line->>'graybarSku'
     or line->>'unitPriceMinor'<>quote_line->>'unitPriceMinor'
     or line->>'quantity' !~ '^\d+(\.\d{1,3})?$'
     or line->>'packSize'<>quote_line->>'packSize' then
     raise exception 'purchase_quote_or_charge_source_changed' using errcode='23514'; end if;
    computed:=computed+pg_catalog.round((line->>'quantity')::numeric/(line->>'packSize')::numeric
     *(line->>'unitPriceMinor')::bigint)::bigint;
   end loop;
   if computed<>(item->>'amountMinor')::bigint then raise exception 'purchase_total_mismatch' using errcode='23514'; end if;
   select coalesce(sum(amount_minor),0) into design_used from d5o_hosted.design_spend_commitments
    where workspace_id=new.workspace_id and work_id=new.work_id and status='Approved';
   select coalesce(sum(amount_minor),0) into purchase_used from d5o_hosted.purchase_reservations
    where workspace_id=new.workspace_id and work_id=new.work_id and status='Reserved';
   if computed>authority.parent_cap_minor-design_used-purchase_used then
    raise exception 'work_economic_cap_exceeded' using errcode='23514'; end if;
   if computed>authority.purchasing_cap_minor-purchase_used then
    raise exception 'purchasing_sublimit_exceeded' using errcode='23514'; end if;
   insert into d5o_hosted.purchase_reservations(workspace_id,work_id,authority_id,order_id,status,
    amount_minor,currency,bom_id,order_digest,source_digest,approved_by)
    values(new.workspace_id,new.work_id,authority.id,item->>'id','Reserved',computed,'USD',
     item->>'bomId',pg_catalog.md5(item::text),source->>'digest',actor);
  elsif previous->>'status'='Approved' and item->>'status'='Test submitted' then
   source:=d5o_hosted.purchase_basis_v1(new.workspace_id,new.work_id);
   select * into reservation from d5o_hosted.purchase_reservations
    where workspace_id=new.workspace_id and work_id=new.work_id and order_id=item->>'id' for update;
   if reservation.id is null then raise exception 'legacy_purchase_requires_review' using errcode='23514'; end if;
   select * into authority from d5o_hosted.purchase_authorities where id=reservation.authority_id for update;
   if reservation.status<>'Reserved' or authority.status<>'Approved'
    or current_date not between authority.valid_from and authority.valid_until
    or source is null or source->>'digest'<>reservation.source_digest
    or authority.source_digest<>reservation.source_digest
    or pg_catalog.md5(previous::text)<>reservation.order_digest then
    raise exception 'purchase_submission_authority_changed' using errcode='23514'; end if;
   for line in select value from pg_catalog.jsonb_array_elements(previous->'lines') loop
    select value into quote_row from pg_catalog.jsonb_array_elements(new.state->'quotes')
     where value->>'id'=line->>'quoteId';
    if quote_row is null or quote_row->>'expiresAt'<current_date::text then
     raise exception 'purchase_submission_quote_expired' using errcode='23514'; end if;
   end loop;
  end if;
 end loop;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_internal_design_rate_delegate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); enabled_at timestamptz; chosen uuid; valued_minor bigint;
begin
 if old.status<>'Prepared' or new.status not in ('Approved','Returned') then return new; end if;
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=new.workspace_id and category='internal_design_rate';
 if enabled_at is null or old.created_at<enabled_at then return new; end if;
 -- Compare the fully burdened cost per person-hour, rounded upward to a cent.
 valued_minor:=pg_catalog.ceil(old.base_rate_minor::numeric *
  (10000+old.burden_basis_points)::numeric / 10000)::bigint;
 chosen:=d5o_hosted.spending_delegate_selected_workspace_v1(new.workspace_id,
  'internal_design_rate','admin',valued_minor,old.currency,old.prepared_by,old.effective_until);
 if chosen is null then raise exception 'spending_delegate_or_sponsor_required' using errcode='23514'; end if;
 if actor is distinct from chosen then
  raise exception 'selected_spending_reviewer_required' using errcode='42501'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_job_finance_closeout_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_ledger d5o_hosted.connected_job_finance_states%rowtype;
  v_commit bigint;v_billed bigint;v_contract bigint;v_award jsonb;
begin
  if new.state#>>'{finance,status}'='Closed' and
    (tg_op='INSERT' or old.state#>>'{finance,status}' is distinct from 'Closed') then
    select * into v_ledger from d5o_hosted.connected_job_finance_states
      where workspace_id=new.workspace_id and work_id=new.work_id;
    if v_ledger.work_id is null or v_ledger.remaining_forecast_minor is null
      or v_ledger.remaining_forecast_minor<>0 then
      raise exception 'finance_remaining_cost_unresolved' using errcode='23514'; end if;
    v_award:=d5o_hosted.job_finance_award_v1(new.workspace_id,new.work_id);
    if v_award is null then raise exception 'finance_award_missing' using errcode='23514'; end if;
    v_contract:=(v_award#>>'{pricingBasis,priceMinor}')::bigint;
    select v_contract+coalesce(sum(((c.facts#>>'{proposal,priceAmount}')::numeric*100)::bigint),0)
      into v_contract from d5o_hosted.connected_field_changes c
      where c.workspace_id=new.workspace_id and c.work_id=new.work_id
        and c.status='Resolved' and c.kind='Scope change'
        and c.facts ? 'customerAuthorization' and c.facts ? 'revisedReleaseId'
        and c.facts#>>'{proposal,currency}'=v_ledger.currency;
    select coalesce(sum(greatest(0,c.amount_minor-coalesce((select sum(i.amount_minor)
      from d5o_hosted.connected_job_costs i where i.reconciles_id=c.id),0))),0)
      into v_commit from d5o_hosted.connected_job_costs c
      where c.workspace_id=new.workspace_id and c.work_id=new.work_id and c.kind='Committed';
    select coalesce(sum(amount_minor),0) into v_billed
      from d5o_hosted.connected_job_cash_events
      where workspace_id=new.workspace_id and work_id=new.work_id and kind='Billed';
    if v_commit<>0 or v_billed<v_contract
      or not exists(select 1 from d5o_hosted.connected_job_costs
        where workspace_id=new.workspace_id and work_id=new.work_id and kind='Incurred') then
      raise exception 'finance_cost_or_billing_gap' using errcode='23514'; end if;
  end if;
  return new;
end; $function$

