CREATE OR REPLACE FUNCTION d5o_hosted.guard_prototype_snapshot_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_record jsonb; new_record jsonb; old_package jsonb; new_package jsonb;
  catalog_record jsonb; pair record;
begin
  if current_setting('role', true) = 'service_role' then return new; end if;
  if tg_op = 'INSERT' or new.state_key <> 'work' then
    raise exception 'command_only_state' using errcode = '42501'; end if;
  if old.state_json->'pricingPolicies' is distinct from new.state_json->'pricingPolicies'
    or old.state_json->'activePricingPolicy' is distinct from new.state_json->'activePricingPolicy'
    or old.state_json->'pricingPolicyHistory' is distinct from new.state_json->'pricingPolicyHistory' then
    raise exception 'protected_policy_changed' using errcode = '42501'; end if;
  if pg_catalog.jsonb_typeof(new.state_json->'records') is distinct from 'array' then
    raise exception 'invalid_records' using errcode = '22023'; end if;
  if (select count(*) from pg_catalog.jsonb_array_elements(new.state_json->'records'))
    <> (select count(distinct item->>'id') from pg_catalog.jsonb_array_elements(new.state_json->'records') item) then
    raise exception 'duplicate_work_id' using errcode = '22023'; end if;
  for old_record in select value from pg_catalog.jsonb_array_elements(coalesce(old.state_json->'records','[]'::jsonb)) loop
    select value into new_record from pg_catalog.jsonb_array_elements(new.state_json->'records')
      where value->>'id' = old_record->>'id';
    if new_record is null then raise exception 'work_deletion_requires_command' using errcode = '42501'; end if;
    if old_record->'definition' is not null and old_record#>'{definition,revision}' is distinct from new_record#>'{definition,revision}' then
      raise exception 'protected_definition_revision_changed' using errcode = '42501'; end if;
    if old_record->'definition' is null and new_record->'definition' is not null
      and (new_record#>>'{definition,status}' <> 'Draft' or new_record#>>'{definition,revision}' <> '1') then
      raise exception 'protected_definition_import' using errcode = '42501'; end if;
    if d5o_hosted.protected_work_record_v1(old_record) is distinct from d5o_hosted.protected_work_record_v1(new_record) then
      raise exception 'protected_decision_changed' using errcode = '42501'; end if;
    for pair in select key, value from pg_catalog.jsonb_each(coalesce(old_record->'phaseRegisters','{}'::jsonb)) where key like 'design.%' loop
      if pair.value is distinct from new_record->'phaseRegisters'->pair.key then
        raise exception 'protected_design_register_changed' using errcode = '42501'; end if;
    end loop;
    for pair in select key, value from pg_catalog.jsonb_each(coalesce(new_record->'phaseRegisters','{}'::jsonb)) where key like 'design.%' loop
      if pair.value is distinct from old_record->'phaseRegisters'->pair.key then
        raise exception 'protected_design_register_changed' using errcode = '42501'; end if;
    end loop;
    for old_package in select value from pg_catalog.jsonb_array_elements(coalesce(old_record->'packages','[]'::jsonb)) loop
      select value into new_package from pg_catalog.jsonb_array_elements(coalesce(new_record->'packages','[]'::jsonb))
        where value->>'id' = old_package->>'id';
      if new_package is null or pg_catalog.jsonb_build_array(old_package->'installed',old_package->'tested',old_package->'accepted',old_package->'status')
        is distinct from pg_catalog.jsonb_build_array(new_package->'installed',new_package->'tested',new_package->'accepted',new_package->'status') then
        raise exception 'protected_execution_changed' using errcode = '42501'; end if;
    end loop;
  end loop;
  for new_record in select value from pg_catalog.jsonb_array_elements(new.state_json->'records') loop
    if not exists(select 1 from pg_catalog.jsonb_array_elements(coalesce(old.state_json->'records','[]'::jsonb)) item where item->>'id'=new_record->>'id') then
      select item into catalog_record
        from d5o_hosted.prototype_states c,
          lateral pg_catalog.jsonb_array_elements(coalesce(c.state_json->'records', '[]'::jsonb)) item
        where c.workspace_id = new.workspace_id and c.state_key = 'catalog'
          and item->>'id' = new_record->>'id';
      if catalog_record is null or catalog_record->>'workspace' is distinct from new_record->>'workspace'
        or catalog_record->>'stage' is distinct from new_record->>'stage'
        or catalog_record->'progress' is distinct from new_record->'progress'
        or catalog_record->>'status' is distinct from new_record->>'status'
        or catalog_record->>'phaseConfigurationVersionId' is distinct from new_record->>'phaseConfigurationVersionId' then
        raise exception 'unregistered_work_import' using errcode = '42501'; end if;
      if new_record->'design' is not null or new_record->'deploy' is not null or new_record->'operate' is not null
        or new_record->'serviceSource' is not null or new_record->>'status' = 'complete'
        or new_record->'prototypeDecisionRights' is not null or new_record->'heldFrom' is not null
        or (new_record#>>'{definition,status}' is not null and new_record#>>'{definition,status}' <> 'Draft')
        or new_record#>'{definition,reviews}' is not null or new_record#>'{definition,developHandoff}' is not null
        or new_record#>'{definition,approvedBaselines}' is not null or new_record#>'{definition,decisions}' is not null
        or new_record#>'{discovery,pursuitControl}' is not null then
        raise exception 'protected_work_import' using errcode = '42501'; end if;
    end if;
  end loop;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_purchase_order_delegate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); item jsonb; previous jsonb; enabled_at timestamptz;
 chosen uuid; prepared_at timestamptz;
begin
 for item in select value from pg_catalog.jsonb_array_elements(coalesce(new.state->'orders','[]'::jsonb)) loop
  select value into previous from pg_catalog.jsonb_array_elements(coalesce(old.state->'orders','[]'::jsonb))
   where value->>'id'=item->>'id';
  if previous is null or previous->>'status'<>'Prepared' or item->>'status'<>'Approved' then continue; end if;
  select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
   where workspace_id=new.workspace_id and category='purchase_order';
  prepared_at:=nullif(previous->>'preparedAt','')::timestamptz;
  -- An existing draft retains its original administrator review contract.
  if enabled_at is null or prepared_at is null or prepared_at<enabled_at then continue; end if;
  chosen:=d5o_hosted.spending_delegate_selected_v1(new.workspace_id,new.work_id,
   'purchase_order','admin',(previous->>'amountMinor')::bigint,previous->>'currency',
   (previous->>'preparedBy')::uuid,current_date);
  if chosen is null then raise exception 'spending_delegate_or_sponsor_required' using errcode='23514'; end if;
  if actor is distinct from chosen then raise exception 'selected_spending_reviewer_required' using errcode='42501'; end if;
 end loop;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_schedule_hold_package_scope_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_package jsonb;v_previous jsonb;v_release jsonb;
begin
  if new.state->'packages' is not distinct from old.state->'packages' then return new; end if;
  for v_previous in select value from pg_catalog.jsonb_array_elements(
      coalesce(old.state->'packages','[]'::jsonb)) loop
    select item into v_release from pg_catalog.jsonb_array_elements(
      coalesce(old.state->'releases','[]'::jsonb)) item
      where item->>'packageId'=v_previous->>'packageId'
      order by item->>'issuedAt' desc limit 1;
    if v_release->>'holdKind' is distinct from 'Schedule correction'
      or v_release->>'status' not in ('Held','Hold pending acknowledgment') then continue; end if;
    select item into v_package from pg_catalog.jsonb_array_elements(
      coalesce(new.state->'packages','[]'::jsonb)) item
      where item->>'packageId'=v_previous->>'packageId';
    if v_package is null or
      (v_package-'revision'-'status'-'windowStart'-'windowEnd'-'targetReleaseDate')
        is distinct from
          ((v_release->'snapshot')-'revision'-'status'-'windowStart'-'windowEnd'-'targetReleaseDate') then
      raise exception 'schedule_hold_scope_change_denied' using errcode='23514';
    end if;
  end loop;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.guard_subcontract_delegate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); array_key text; review_category text; item jsonb;
 previous jsonb; agreement jsonb; amount bigint; currency text;
 enabled_at timestamptz; prepared_at timestamptz; chosen uuid;
begin
 foreach array_key in array array['allocations','agreements','variations'] loop
  review_category:=case array_key when 'allocations' then 'subcontract_allocation'
   when 'agreements' then 'subcontract_agreement' else 'subcontract_variation' end;
  for item in select value from pg_catalog.jsonb_array_elements(coalesce(new.state->array_key,'[]'::jsonb)) loop
   select value into previous from pg_catalog.jsonb_array_elements(coalesce(old.state->array_key,'[]'::jsonb))
    where value->>'id'=item->>'id';
   if previous is null or previous->>'status'<>'Prepared'
    or item->>'status' not in ('Approved','Returned') then continue; end if;
   select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
    where workspace_id=new.workspace_id and category=review_category;
   prepared_at:=nullif(previous->>'preparedAt','')::timestamptz;
   -- Preserve the review contract of drafts prepared before configuration.
   if enabled_at is null or prepared_at is null or prepared_at<enabled_at then continue; end if;
   if array_key='allocations' then
    amount:=(previous->>'capMinor')::bigint;
    currency:=previous->>'currency';
   elsif array_key='agreements' then
    amount:=(previous->>'amountMinor')::bigint;
    currency:=previous->>'currency';
   else
    amount:=abs((previous->>'deltaMinor')::bigint);
    select value into agreement from pg_catalog.jsonb_array_elements(coalesce(old.state->'agreements','[]'::jsonb))
     where value->>'id'=previous->>'agreementId';
    currency:=agreement->>'currency';
   end if;
   if amount is null or amount<=0 or currency is null then
    raise exception 'subcontract_delegate_basis_invalid' using errcode='23514'; end if;
   chosen:=d5o_hosted.spending_delegate_selected_v1(new.workspace_id,new.work_id,
    review_category,'admin',amount,currency,(previous->>'preparedBy')::uuid,current_date);
   if chosen is null then raise exception 'spending_delegate_or_sponsor_required' using errcode='23514'; end if;
   if actor is distinct from chosen then
    raise exception 'selected_spending_reviewer_required' using errcode='42501'; end if;
  end loop;
 end loop;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.job_finance_legacy_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_member d5o_hosted.memberships%rowtype;
  v_work d5o_hosted.work_records%rowtype;v_state d5o_hosted.connected_job_finance_states%rowtype;
  v_receipt d5o_hosted.connected_job_finance_receipts%rowtype;
  v_award jsonb;v_cost d5o_hosted.connected_job_costs%rowtype;
  v_bill d5o_hosted.connected_job_bills%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_line jsonb;v_release jsonb;v_completion jsonb;v_fingerprint text;v_result jsonb;
  v_quantity numeric;v_existing_quantity numeric;v_allocated bigint;v_contract bigint;
  v_amount bigint;v_total bigint;v_date date;v_id uuid;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('add-cost','set-remaining','draft-bill','submit-bill',
      'review-bill','record-billed','record-paid')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_job_finance_command' using errcode='22023'; end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace and actor_user_id=v_actor and status='active' for share;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace and l.presentation_id=p_presentation_id for update of w;
  if v_member.id is null or v_work.id is null or v_member.role not in
    ('billing_commercial_lead','project_manager') then
    raise exception 'job_finance_role_denied' using errcode='42501'; end if;
  if exists(select 1 from d5o_hosted.connected_operate_states o
    where o.workspace_id=v_workspace and o.work_id=v_work.id
      and o.state#>>'{finance,status}'='Closed') then
    raise exception 'finance_closed_requires_reopen' using errcode='23514'; end if;
  v_award:=d5o_hosted.job_finance_award_v1(v_workspace,v_work.id);
  if v_award is null or v_award#>>'{pricingBasis,currency}'<>'USD'
    or (v_award#>>'{pricingBasis,priceMinor}')::bigint<=0 then
    raise exception 'approved_usd_fixed_price_award_required' using errcode='23514'; end if;
  insert into d5o_hosted.connected_job_finance_states(workspace_id,work_id,currency)
    values(v_workspace,v_work.id,'USD') on conflict do nothing;
  select * into v_state from d5o_hosted.connected_job_finance_states
    where workspace_id=v_workspace and work_id=v_work.id for update;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_input,p_expected_revision)::text);
  select * into v_receipt from d5o_hosted.connected_job_finance_receipts
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  if v_state.revision<>p_expected_revision then
    raise exception 'stale_job_finance' using errcode='23505'; end if;
  if p_action='add-cost' then
    if v_member.role<>'billing_commercial_lead' or
      p_input->>'category' not in ('Labor','Material','Equipment','Subcontract')
      or p_input->>'kind' not in ('Committed','Incurred')
      or coalesce(p_input->>'amountMinor','')!~'^\d+$'
      or length(trim(coalesce(p_input->>'source','')))<8
      or coalesce(p_input->>'costDate','')!~'^\d{4}-\d{2}-\d{2}$' then
      raise exception 'sourced_cost_required' using errcode='22023'; end if;
    v_amount:=(p_input->>'amountMinor')::bigint;v_date:=(p_input->>'costDate')::date;
    if v_amount<=0 or v_amount>1000000000000 then
      raise exception 'cost_amount_invalid' using errcode='22023'; end if;
    if nullif(p_input->>'packageId','') is not null and not exists(select 1 from
      d5o_hosted.connected_package_states p where p.workspace_id=v_workspace
      and p.work_id=v_work.id and p.package_id=p_input->>'packageId') then
      raise exception 'cost_package_scope_invalid' using errcode='23514'; end if;
    if nullif(p_input->>'reconcilesId','') is not null then
      select * into v_cost from d5o_hosted.connected_job_costs
        where workspace_id=v_workspace and work_id=v_work.id
          and id=(p_input->>'reconcilesId')::uuid for update;
      if v_cost.id is null or v_cost.kind<>'Committed'
        or p_input->>'kind'<>'Incurred' or v_cost.category<>p_input->>'category'
        or v_cost.package_id is distinct from nullif(p_input->>'packageId','') then
        raise exception 'commitment_reconciliation_invalid' using errcode='23514'; end if;
      select coalesce(sum(amount_minor),0) into v_total from d5o_hosted.connected_job_costs
        where reconciles_id=v_cost.id;
      if v_total+v_amount>v_cost.amount_minor then
        raise exception 'commitment_over_reconciled' using errcode='23514'; end if;
    end if;
    insert into d5o_hosted.connected_job_costs(workspace_id,work_id,package_id,
      kind,category,amount_minor,cost_date,source,reconciles_id,recorded_by)
    values(v_workspace,v_work.id,nullif(p_input->>'packageId',''),p_input->>'kind',
      p_input->>'category',v_amount,v_date,trim(p_input->>'source'),v_cost.id,v_actor)
    returning id into v_id;
  elsif p_action='set-remaining' then
    if v_member.role<>'billing_commercial_lead'
      or coalesce(p_input->>'amountMinor','')!~'^\d+$'
      or length(trim(coalesce(p_input->>'source','')))<8
      or coalesce(p_input->>'forecastAt','')!~'^\d{4}-\d{2}-\d{2}$' then
      raise exception 'remaining_forecast_source_required' using errcode='22023'; end if;
    v_amount:=(p_input->>'amountMinor')::bigint;
    if v_amount>1000000000000 then raise exception 'forecast_amount_invalid' using errcode='22023'; end if;
    update d5o_hosted.connected_job_finance_states set
      remaining_forecast_minor=v_amount,forecast_source=trim(p_input->>'source'),
      forecast_at=(p_input->>'forecastAt')::date
      where workspace_id=v_workspace and work_id=v_work.id;
  elsif p_action='draft-bill' then
    if p_input->>'lines' is null or pg_catalog.jsonb_typeof(p_input->'lines')<>'array'
      or pg_catalog.jsonb_array_length(p_input->'lines')=0
      or pg_catalog.jsonb_array_length(p_input->'lines')>20 then
      raise exception 'billing_lines_required' using errcode='22023'; end if;
    select * into v_deploy from d5o_hosted.connected_deploy_states
      where workspace_id=v_workspace and work_id=v_work.id for share;
    select * into v_design from d5o_hosted.connected_design_states
      where workspace_id=v_workspace and work_id=v_work.id for share;
    for v_line in select value from pg_catalog.jsonb_array_elements(p_input->'lines') loop
      if coalesce(v_line->>'amountMinor','')!~'^\d+$'
        or (v_line->>'amountMinor')::bigint<=0 or length(coalesce(v_line->>'description',''))<5
        or coalesce(v_line->>'evidenceId','')='' then
        raise exception 'billing_line_invalid' using errcode='22023'; end if;
      select r into v_release from pg_catalog.jsonb_array_elements(
        coalesce(v_design.state->'releases','[]'::jsonb)) r
        where r->>'packageId'=v_line->>'packageId' order by r->>'issuedAt' desc limit 1;
      select c into v_completion from pg_catalog.jsonb_array_elements(
        coalesce(v_deploy.state->'completions','[]'::jsonb)) c
        where c->>'packageId'=v_line->>'packageId' and c->>'releaseId'=v_release->>'id';
      if v_release is null or v_release->>'status'<>'Accepted'
        or not exists(select 1 from pg_catalog.jsonb_array_elements(
          coalesce(v_deploy.state->'turnovers','[]'::jsonb)) t
          where t->>'status'='Client accepted' and t->'releaseIds' ? (v_release->>'id'))
        or v_completion is null
        or not exists(select 1 from pg_catalog.jsonb_array_elements(
          coalesce(v_deploy.state->'evidence','[]'::jsonb)) e
          where e->>'id'=v_line->>'evidenceId' and e->>'packageId'=v_line->>'packageId'
            and e->>'state'='Reviewed') then
        raise exception 'accepted_billing_scope_and_evidence_required' using errcode='23514'; end if;
      if coalesce(v_line->>'quantity','')!~'^\d+(\.\d{1,3})?$'
        or coalesce(v_line->>'unit','')='' then
        raise exception 'billing_quantity_required' using errcode='22023'; end if;
      v_quantity:=(v_line->>'quantity')::numeric;
      if v_quantity<=0 or v_quantity>1000000 then
        raise exception 'billing_quantity_invalid' using errcode='22023'; end if;
      select coalesce(sum((line->>'quantity')::numeric),0) into v_existing_quantity
        from d5o_hosted.connected_job_bills b,
          lateral pg_catalog.jsonb_array_elements(b.lines) line
        where b.workspace_id=v_workspace and b.work_id=v_work.id
          and b.status<>'Returned' and line->>'packageId'=v_line->>'packageId';
      if v_release#>>'{snapshot,completionBasis,kind}'='Measured' then
        if v_line->>'unit' is distinct from v_completion->>'unit'
          or v_existing_quantity+v_quantity>(v_completion->>'reviewedQuantity')::numeric then
          raise exception 'billing_exceeds_accepted_quantity' using errcode='23514'; end if;
      elsif v_quantity<>1 or v_existing_quantity+v_quantity>1 then
        raise exception 'billing_exceeds_accepted_scope' using errcode='23514'; end if;
    end loop;
    v_contract:=(v_award#>>'{pricingBasis,priceMinor}')::bigint;
    select v_contract+coalesce(sum(((c.facts#>>'{proposal,priceAmount}')::numeric*100)::bigint),0)
      into v_contract from d5o_hosted.connected_field_changes c
      where c.workspace_id=v_workspace and c.work_id=v_work.id
        and c.status='Resolved' and c.kind='Scope change'
        and c.facts ? 'customerAuthorization' and c.facts ? 'revisedReleaseId'
        and c.facts#>>'{proposal,currency}'='USD';
    select coalesce(sum((line->>'amountMinor')::bigint),0) into v_allocated
      from d5o_hosted.connected_job_bills b,
        lateral pg_catalog.jsonb_array_elements(b.lines) line
      where b.workspace_id=v_workspace and b.work_id=v_work.id and b.status<>'Returned';
    select v_allocated+coalesce(sum((line->>'amountMinor')::bigint),0) into v_allocated
      from pg_catalog.jsonb_array_elements(p_input->'lines') line;
    if v_allocated>v_contract then
      raise exception 'billing_exceeds_authorized_contract' using errcode='23514'; end if;
    insert into d5o_hosted.connected_job_bills(workspace_id,work_id,status,lines,prepared_by)
      values(v_workspace,v_work.id,'Draft',p_input->'lines',v_actor) returning id into v_id;
  elsif p_action in ('submit-bill','review-bill') then
    select * into v_bill from d5o_hosted.connected_job_bills
      where id=(p_input->>'billId')::uuid and workspace_id=v_workspace and work_id=v_work.id for update;
    if v_bill.id is null then raise exception 'billing_record_missing' using errcode='23503'; end if;
    if p_action='submit-bill' then
      if v_bill.status not in ('Draft','Returned') or v_bill.prepared_by<>v_actor then
        raise exception 'billing_submit_denied' using errcode='42501'; end if;
      update d5o_hosted.connected_job_bills set status='In review',revision=revision+1 where id=v_bill.id;
    else
      if v_member.role<>'billing_commercial_lead' or v_bill.status<>'In review'
        or v_bill.prepared_by=v_actor or p_input->>'decision' not in ('Reviewed','Returned')
        or length(trim(coalesce(p_input->>'reason','')))<10 then
        raise exception 'independent_billing_review_required' using errcode='42501'; end if;
      update d5o_hosted.connected_job_bills set status=p_input->>'decision',
        revision=revision+1,reviewed_by=v_actor,review_reason=p_input->>'reason' where id=v_bill.id;
    end if;
    v_id:=v_bill.id;
  else
    if v_member.role<>'billing_commercial_lead' or
      coalesce(p_input->>'amountMinor','')!~'^\d+$'
      or coalesce(p_input->>'eventDate','')!~'^\d{4}-\d{2}-\d{2}$'
      or length(trim(coalesce(p_input->>'source','')))<8 then
      raise exception 'cash_source_required' using errcode='22023'; end if;
    v_amount:=(p_input->>'amountMinor')::bigint;
    select * into v_bill from d5o_hosted.connected_job_bills
      where id=(p_input->>'billId')::uuid and workspace_id=v_workspace and work_id=v_work.id for update;
    if v_bill.id is null or v_bill.status<>'Reviewed' or v_amount<=0 then
      raise exception 'reviewed_bill_required' using errcode='23514'; end if;
    select coalesce(sum((line->>'amountMinor')::bigint),0) into v_total
      from pg_catalog.jsonb_array_elements(v_bill.lines) line;
    if p_action='record-billed' then
      if exists(select 1 from d5o_hosted.connected_job_cash_events
        where bill_id=v_bill.id and kind='Billed') or v_amount<>v_total then
        raise exception 'bill_amount_mismatch' using errcode='23514'; end if;
    else
      select coalesce(sum(amount_minor),0) into v_total from d5o_hosted.connected_job_cash_events
        where bill_id=v_bill.id and kind='Billed';
      if v_total=0 or v_amount+coalesce((select sum(amount_minor) from
        d5o_hosted.connected_job_cash_events where bill_id=v_bill.id and kind='Paid'),0)>v_total then
        raise exception 'payment_exceeds_billed' using errcode='23514'; end if;
    end if;
    insert into d5o_hosted.connected_job_cash_events(workspace_id,work_id,bill_id,
      kind,amount_minor,event_date,source,recorded_by)
    values(v_workspace,v_work.id,v_bill.id,case when p_action='record-billed' then 'Billed' else 'Paid' end,
      v_amount,(p_input->>'eventDate')::date,p_input->>'source',v_actor) returning id into v_id;
  end if;
  update d5o_hosted.connected_job_finance_states set revision=revision+1
    where workspace_id=v_workspace and work_id=v_work.id;
  v_result:=pg_catalog.jsonb_build_object('id',v_id,'revision',v_state.revision+1,'action',p_action);
  insert into d5o_hosted.connected_job_finance_events(workspace_id,work_id,revision,
    command_id,actor_user_id,membership_id,action,result)
    values(v_workspace,v_work.id,v_state.revision+1,p_command_id,v_actor,v_member.id,p_action,v_result);
  insert into d5o_hosted.connected_job_finance_receipts(workspace_id,command_id,
    actor_user_id,fingerprint,result) values(v_workspace,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.purchase_basis_v1(p_workspace uuid, p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d d5o_hosted.connected_define_states%rowtype; e d5o_hosted.connected_estimate_states%rowtype;
 work d5o_hosted.work_records%rowtype; award jsonb; design jsonb; basis jsonb;
begin
 select * into d from d5o_hosted.connected_define_states where workspace_id=p_workspace and work_id=p_work;
 select * into e from d5o_hosted.connected_estimate_states where workspace_id=p_workspace and work_id=p_work;
 select * into work from d5o_hosted.work_records where workspace_id=p_workspace and id=p_work;
 if d.status is distinct from 'Approved' or e.status is distinct from 'Approved'
  or e.definition_revision is distinct from d.definition_revision then return null; end if;
 award:=d5o_hosted.job_finance_award_v1(p_workspace,p_work);
 if award is not null then
  if award->>'estimateRevision'<>e.estimate_revision::text
   or award#>>'{definitionSource,revision}'<>d.definition_revision::text then return null; end if;
  basis:=pg_catalog.jsonb_build_object('kind','Awarded work','defineRevision',d.definition_revision,
   'estimateRevision',e.estimate_revision,'awardEventId',award->>'awardEventId',
   'awardRevision',award->>'revision','awardCurrency',award#>>'{pricingBasis,currency}',
   'awardPriceMinor',award#>>'{pricingBasis,priceMinor}');
 else
  design:=d5o_hosted.design_spend_source_v1(p_workspace,p_work);
  if design is null then return null; end if;
  basis:=pg_catalog.jsonb_build_object('kind','Funded Design only','defineRevision',d.definition_revision,
   'estimateRevision',e.estimate_revision,'designSourceDigest',design->>'digest',
   'designDecisionRevision',design->>'designDecisionRevision',
   'fundingSource',design#>>'{authorization,fundingSource}',
   'fundingReference',design#>>'{authorization,sourceReference}');
 end if;
 basis:=basis||pg_catalog.jsonb_build_object('workConfigurationVersionId',work.configuration_version_id,
  'workConfigurationDigest',work.configuration_digest,'workType',work.work_type_key);
 return basis||pg_catalog.jsonb_build_object('digest',pg_catalog.md5(basis::text));
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.redact_support_document_read_v1(p_workspace_key text, p_actor uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text;v_records jsonb:='[]'::jsonb;v_record jsonb;
  v_docs jsonb;v_packages jsonb;v_work uuid;v_assignments jsonb;v_events jsonb;
begin
  if p_actor is null or p_result#>'{state,records}' is null then return p_result; end if;
  select m.role into v_role from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.actor_user_id=p_actor and m.status='active';
  if v_role<>'field_supervisor' then return p_result; end if;
  for v_record in select value from pg_catalog.jsonb_array_elements(
    p_result#>'{state,records}') loop
    if pg_catalog.jsonb_typeof(v_record#>'{operate,documentationObligations}')='array' then
      select coalesce(pg_catalog.jsonb_agg(
        case when d->>'uploadedByActorId'=p_actor::text then d
          else pg_catalog.jsonb_build_object('id','','turnoverId',d->>'turnoverId',
            'kind',d->>'kind','basis',d->'basis','status',d->>'status','restricted',true)
        end order by n),'[]'::jsonb) into v_docs
        from pg_catalog.jsonb_array_elements(v_record#>'{operate,documentationObligations}')
          with ordinality as entries(d,n);
      v_record:=pg_catalog.jsonb_set(v_record,'{operate,documentationObligations}',v_docs);
    end if;
    select l.work_id into v_work from d5o_hosted.work_identity_links l
      join d5o_hosted.workspaces w on w.id=l.workspace_id
      where w.workspace_key=p_workspace_key and w.status='active'
        and l.presentation_id=v_record->>'id';
    select coalesce(s.state->'supportDocumentAssignments','[]'::jsonb)
      into v_assignments from d5o_hosted.connected_operate_states s
      join d5o_hosted.workspaces w on w.id=s.workspace_id
      where w.workspace_key=p_workspace_key and s.work_id=v_work;
    select coalesce(pg_catalog.jsonb_agg(a->>'packageId'),'[]'::jsonb)
      into v_packages from pg_catalog.jsonb_array_elements(coalesce(v_assignments,'[]'::jsonb))
        with ordinality as entries(a,n)
      where a->>'status'='Assigned' and a->>'actorId'=p_actor::text
        and (d5o_hosted.support_document_supervisor_scope_v1(
          p_workspace_key,v_record->>'id',a->>'turnoverId','as-built',p_actor)
          or d5o_hosted.support_document_supervisor_scope_v1(
            p_workspace_key,v_record->>'id',a->>'turnoverId','inspection',p_actor))
        and not exists(select 1 from pg_catalog.jsonb_array_elements(v_assignments)
          with ordinality as later(b,m)
          where b->>'turnoverId'=a->>'turnoverId' and m>n);
    -- Other suppliers' assignment identity and email are not a supervisor read.
    if v_record#>'{operate,supportDocumentAssignments}' is not null then
      v_record:=pg_catalog.jsonb_set(v_record,'{operate,supportDocumentAssignments}',
        coalesce((select pg_catalog.jsonb_agg(a order by n)
          from pg_catalog.jsonb_array_elements(v_assignments) with ordinality as entries(a,n)
          where a->>'actorId'=p_actor::text),'[]'::jsonb));
    end if;
    if pg_catalog.jsonb_typeof(v_record#>'{operate,events}')='array' then
      select coalesce(pg_catalog.jsonb_agg(
        case when e->>'actorId'=p_actor::text or
          (e->>'action' not like 'support-document-%' and
           e->>'action' not like 'support-supplier-%') then e
          else pg_catalog.jsonb_build_object('id',e->>'id','at',e->>'at',
            'action',e->>'action','detail','Restricted support document action')
        end order by n),'[]'::jsonb) into v_events
        from pg_catalog.jsonb_array_elements(v_record#>'{operate,events}')
          with ordinality as entries(e,n);
      v_record:=pg_catalog.jsonb_set(v_record,'{operate,events}',v_events);
    end if;
    v_records:=v_records||pg_catalog.jsonb_build_array(
      v_record||pg_catalog.jsonb_build_object(
        'supportDocumentSupplierPackageIds',coalesce(v_packages,'[]'::jsonb)));
  end loop;
  return pg_catalog.jsonb_set(p_result,'{state,records}',v_records);
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.require_design_document_evidence_v1(p_workspace_id uuid, p_work_id uuid, p_document_id text, p_document_revision integer, p_evidence_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_evidence d5o_hosted.design_document_evidence%rowtype;
  v_object storage.objects%rowtype;
begin
  select * into v_evidence from d5o_hosted.design_document_evidence
    where id::text=p_evidence_id and workspace_id=p_workspace_id and work_id=p_work_id
      and document_id=p_document_id and document_revision=p_document_revision;
  if not found then raise exception 'exact_design_document_evidence_required' using errcode='23514'; end if;
  select * into v_object from storage.objects
    where bucket_id='d5o-deploy-evidence' and name=v_evidence.object_path;
  if v_object.id is distinct from v_evidence.storage_object_id
    or v_object.updated_at is distinct from v_evidence.storage_updated_at
    or (v_object.metadata->>'size')::bigint is distinct from v_evidence.size_bytes
    or v_object.metadata->>'mimetype' is distinct from 'application/pdf' then
    raise exception 'design_document_bytes_changed' using errcode='23514'; end if;
  return pg_catalog.jsonb_build_object('evidenceId',v_evidence.id,
    'checksumSha256',v_evidence.checksum_sha256,'filename',v_evidence.filename,
    'sizeBytes',v_evidence.size_bytes,'uploadedBy',v_evidence.uploaded_by,
    'uploadedAt',v_evidence.uploaded_at);
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.spending_delegate_decision_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_category text; required_role text; amount bigint; preparer uuid; needed_until date;
 enabled_at timestamptz;
 chosen uuid; decision_actor uuid:=auth.uid();
begin
 if old.status<>'Prepared' or new.status not in ('Approved','Returned') then return new; end if;
 if tg_table_name='purchase_authorities' then
  v_category:='work_authority'; required_role:='admin'; amount:=new.parent_cap_minor;
  preparer:=new.prepared_by; needed_until:=new.valid_until;
 elsif tg_table_name='design_spend_authorities' then
  v_category:='design_authority'; required_role:=new.source_snapshot->>'approverRole';
  amount:=new.cap_minor; preparer:=new.prepared_by; needed_until:=new.valid_until;
 else
  v_category:='design_commitment'; amount:=new.amount_minor; preparer:=new.prepared_by;
  select a.source_snapshot->>'approverRole',a.valid_until into required_role,needed_until
   from d5o_hosted.design_spend_authorities a where a.id=new.authority_id;
 end if;
 select c.configured_at into enabled_at from d5o_hosted.spending_delegate_categories c
  where c.workspace_id=new.workspace_id and c.category=v_category;
 -- A decision prepared before this feature was configured keeps its original role contract.
 if enabled_at is null or new.created_at<enabled_at then return new; end if;
 chosen:=d5o_hosted.spending_delegate_selected_v1(new.workspace_id,new.work_id,v_category,
  required_role,amount,new.currency,preparer,needed_until);
 if chosen is null then raise exception 'spending_delegate_or_sponsor_required' using errcode='23514'; end if;
 if decision_actor is distinct from chosen then
  raise exception 'selected_spending_reviewer_required' using errcode='42501'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.support_document_basis_v1(p_workspace_id uuid, p_work_id uuid, p_turnover_id text, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_deploy jsonb;v_design jsonb;v_operate jsonb;
  v_turnover jsonb;v_release jsonb;v_acceptance jsonb;v_obligation text;
begin
  if p_kind not in ('as-built','inspection') then return null; end if;
  select state into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=p_workspace_id and work_id=p_work_id;
  select state into v_design from d5o_hosted.connected_design_states
    where workspace_id=p_workspace_id and work_id=p_work_id;
  select state into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=p_workspace_id and work_id=p_work_id;
  v_acceptance:=v_deploy->'workAcceptance';
  select t into v_turnover from pg_catalog.jsonb_array_elements(
    coalesce(v_deploy->'turnovers','[]'::jsonb)) t
    where t->>'id'=p_turnover_id;
  v_obligation:=pg_catalog.lower(coalesce(v_turnover->>'obligations',''));
  if v_turnover is null or v_turnover->>'status'<>'Client accepted'
    or v_turnover->>'receipt'<>'Accepted'
    or v_acceptance->>'receipt'<>'Accepted'
    or not (v_acceptance->'turnoverIds' ? p_turnover_id)
    or v_operate#>>'{source,workAcceptanceId}' is distinct from v_acceptance->>'id'
    or v_operate#>>'{source,revision}' is distinct from v_acceptance->>'revision'
    or (p_kind='as-built' and v_obligation not like '%as-built%')
    or (p_kind='inspection' and v_obligation not like '%inspection%')
    or pg_catalog.jsonb_array_length(coalesce(v_turnover->'releaseIds','[]'::jsonb))<>1
  then return null; end if;
  select r into v_release from pg_catalog.jsonb_array_elements(
    coalesce(v_design->'releases','[]'::jsonb)) r
    where r->>'id'=v_turnover->'releaseIds'->>0 and r->>'status'='Accepted';
  if v_release is null then return null; end if;
  return pg_catalog.jsonb_build_object(
    'turnoverId',p_turnover_id,'turnoverRevision',(v_turnover->>'revision')::integer,
    'packageId',v_release->>'packageId','releaseId',v_release->>'id',
    'releaseRevision',(v_release->>'packageRevision')::integer,
    'workAcceptanceId',v_acceptance->>'id',
    'workAcceptanceRevision',(v_acceptance->>'revision')::integer,
    'kind',p_kind);
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.validate_connected_rom_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_define d5o_hosted.connected_define_states%rowtype;
  v_input jsonb;v_basis jsonb;v_coverage jsonb;v_lines jsonb;v_item jsonb;
  v_obligation jsonb;v_obligations jsonb:='[]'::jsonb;v_row jsonb;
  v_scenario jsonb;v_line jsonb;v_eval_line jsonb;v_policy jsonb;
  v_units numeric;v_base_hours numeric;v_quantity numeric;
  v_direct numeric;v_base_amount numeric;v_new_amount numeric;
  v_overhead numeric;v_contingency numeric;v_target numeric;v_discount numeric;
  v_scenarios jsonb:='{}'::jsonb;v_label text;v_hours numeric;
  v_count integer;v_revision integer;
begin
  if new.status not in ('Pricing review','Approved')
    or new.estimate#>>'{detailed,input,estimateMaturity}' is distinct from 'ROM' then
    return new; end if;
  v_input:=new.estimate#>'{detailed,input}';
  v_basis:=v_input->'romBasis';v_coverage:=v_basis->'coverage';v_lines:=v_input->'lines';
  if pg_catalog.jsonb_typeof(v_coverage)<>'array' or
    pg_catalog.jsonb_typeof(v_lines)<>'array' then
    raise exception 'rom_coverage_required' using errcode='23514'; end if;
  if exists(select 1 from (select value->>'id' as id
      from pg_catalog.jsonb_array_elements(v_lines) value) lines
    group by id having count(*)>1 or nullif(id,'') is null) then
    raise exception 'rom_duplicate_cost_line' using errcode='23514'; end if;
  if length(trim(coalesce(v_basis#>>'{communication,scope}','')))=0 or
    length(trim(coalesce(v_basis#>>'{communication,assumptions}','')))=0 or
    length(trim(coalesce(v_basis#>>'{communication,informationNeeded}','')))=0 or
    length(trim(coalesce(v_basis#>>'{communication,designValidation}','')))=0 or
    coalesce(v_basis#>>'{communication,reviewDate}','') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'rom_communication_basis_missing' using errcode='23514'; end if;
  select * into v_define from d5o_hosted.connected_define_states
    where workspace_id=new.workspace_id and work_id=new.work_id;
  if v_define.status is distinct from 'Approved' or
    v_define.projection#>>'{developHandoff,status}' is distinct from 'accepted' or
    v_define.definition_revision<>new.definition_revision then
    raise exception 'rom_define_source_changed' using errcode='23514'; end if;
  v_revision:=v_define.definition_revision;
  for v_item in select value from pg_catalog.jsonb_array_elements(
    coalesce(v_define.projection#>'{scopeControl,requirements}','[]'::jsonb)) loop
    v_obligations:=v_obligations||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',v_item->>'id',
        'confirmed',v_item->>'state'='Confirmed',
        'customerOwner',coalesce(v_item->>'owner','')~*'customer'));
  end loop;
  v_count:=0;
  for v_item in select value from pg_catalog.jsonb_array_elements(
    coalesce(v_define.projection#>'{registers,acceptance_criteria}','[]'::jsonb))
    loop
    v_count:=v_count+1;
    -- The UI uses a stable fallback identity for older criteria without IDs.
    v_obligations:=v_obligations||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',coalesce(nullif(v_item->>'id',''),
        'acceptance-'||v_count::text),
        'confirmed',true,'customerOwner',false));
  end loop;
  for v_item in select value from pg_catalog.jsonb_array_elements(
    coalesce(v_define.projection#>'{scopeControl,interfaces}','[]'::jsonb)) loop
    v_obligations:=v_obligations||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',v_item->>'id',
        'confirmed',coalesce(v_item->>'agreement','')<>'',
        'customerOwner',coalesce(v_item->>'counterparty','')~*'customer'));
  end loop;
  for v_label in select unnest(array['milestones','dependencies']) loop
    v_count:=0;
    for v_item in select value from pg_catalog.jsonb_array_elements(
      coalesce(v_define.projection->'registers'->v_label,'[]'::jsonb)) loop
      v_count:=v_count+1;
      v_obligations:=v_obligations||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('id',coalesce(nullif(v_item->>'id',''),
          v_label||'-'||v_count::text),'confirmed',true,'customerOwner',false));
    end loop;
  end loop;
  if pg_catalog.jsonb_array_length(v_obligations)=0 then
    raise exception 'rom_define_obligations_missing' using errcode='23514'; end if;
  for v_obligation in select value from pg_catalog.jsonb_array_elements(v_obligations) loop
    select count(*) into v_count
      from pg_catalog.jsonb_array_elements(v_coverage) value
      where value->>'obligationId'=v_obligation->>'id';
    select value into v_row from pg_catalog.jsonb_array_elements(v_coverage) value
      where value->>'obligationId'=v_obligation->>'id' limit 1;
    if v_count<>1 or v_row->>'sourceRevision' is distinct from v_revision::text or
      length(trim(coalesce(v_row->>'owner','')))=0 or
      length(trim(coalesce(v_row->>'rationale','')))=0 then
      raise exception 'rom_obligation_unaddressed:%',v_obligation->>'id' using errcode='23514'; end if;
    if v_row->>'treatment' not in ('Line','Shared allowance','Customer responsibility') or
      v_row->>'treatment'='Excluded' or
      v_row->>'treatment'='Customer responsibility' and
        not (v_obligation->>'customerOwner')::boolean then
      raise exception 'rom_scope_deviation:%',v_obligation->>'id' using errcode='23514'; end if;
    if v_row->>'treatment' in ('Line','Shared allowance') then
      if pg_catalog.jsonb_typeof(v_row->'lineIds')<>'array' or
        pg_catalog.jsonb_array_length(v_row->'lineIds')=0 or exists(
          select 1 from pg_catalog.jsonb_array_elements_text(v_row->'lineIds') id
          where not exists(select 1 from pg_catalog.jsonb_array_elements(v_lines) line
            where line->>'id'=id.value)) then
        raise exception 'rom_cost_link_missing:%',v_obligation->>'id' using errcode='23514'; end if;
    end if;
  end loop;
  if exists(select 1 from pg_catalog.jsonb_array_elements(v_coverage) row
    where not exists(select 1 from pg_catalog.jsonb_array_elements(v_obligations) obligation
      where obligation->>'id'=row->>'obligationId')) then
    raise exception 'rom_stale_coverage' using errcode='23514'; end if;
  for v_line in select value from pg_catalog.jsonb_array_elements(v_lines) loop
    if length(trim(coalesce(v_line->>'quantityBasis','')))=0 or
      coalesce(v_line->>'sourceKind','') not in ('Assumed','Historical','Quoted','Policy rate') or
      coalesce(v_line->>'sourceDate','') !~ '^\d{4}-\d{2}-\d{2}$' or
      (exists(select 1 from pg_catalog.jsonb_array_elements(
        new.estimate#>'{detailed,evaluation,lines}') evaluated
        where evaluated->>'id'=v_line->>'id' and
          coalesce((evaluated->>'amountMinor')::numeric,0)=0) and
        length(trim(coalesce(v_line->>'noCostReason','')))=0) then
      raise exception 'rom_line_basis_missing:%',v_line->>'id' using errcode='23514'; end if;
  end loop;
  v_scenario:=v_basis->'installationScenario';
  if pg_catalog.jsonb_typeof(v_scenario)<>'object' or
    coalesce(v_scenario->>'units','') !~ '^\d+(\.\d+)?$' or
    coalesce(v_scenario->>'lowHoursPerUnit','') !~ '^\d+(\.\d+)?$' or
    coalesce(v_scenario->>'baseHoursPerUnit','') !~ '^\d+(\.\d+)?$' or
    coalesce(v_scenario->>'highHoursPerUnit','') !~ '^\d+(\.\d+)?$' or
    length(trim(coalesce(v_scenario->>'quantitySource','')))=0 or
    length(trim(coalesce(v_scenario->>'rationale','')))=0 then
    raise exception 'rom_scenario_basis_missing' using errcode='23514'; end if;
  v_units:=(v_scenario->>'units')::numeric;
  v_base_hours:=(v_scenario->>'baseHoursPerUnit')::numeric;
  if v_units<=0 or v_base_hours<=0 or
    (v_scenario->>'lowHoursPerUnit')::numeric<=0 or
    (v_scenario->>'highHoursPerUnit')::numeric<v_base_hours or
    (v_scenario->>'lowHoursPerUnit')::numeric>v_base_hours then
    raise exception 'rom_scenario_order_invalid' using errcode='23514'; end if;
  select value into v_line from pg_catalog.jsonb_array_elements(v_lines) value
    where value->>'id'=v_scenario->>'lineId';
  select value into v_eval_line from pg_catalog.jsonb_array_elements(
    new.estimate#>'{detailed,evaluation,lines}') value
    where value->>'id'=v_scenario->>'lineId';
  if v_line is null or v_eval_line is null or v_line->>'category'<>'labor' or
    v_line->>'unit'<>'person-hour' or
    (v_line->>'quantity')::numeric<>v_units*v_base_hours then
    raise exception 'rom_installation_effort_mismatch' using errcode='23514'; end if;
  v_policy:=new.estimate#>'{detailed,policySnapshot}';
  if v_policy->>'method'<>'target-margin' then
    raise exception 'rom_scenarios_need_target_margin_policy' using errcode='23514'; end if;
  v_direct:=(new.estimate#>>'{detailed,evaluation,directCostMinor}')::numeric;
  v_base_amount:=(v_eval_line->>'amountMinor')::numeric;
  v_overhead:=(v_policy->>'overheadPercent')::numeric;
  v_contingency:=(v_policy->>'contingencyPercent')::numeric;
  v_target:=(v_policy->>'targetMarginPercent')::numeric;
  v_discount:=coalesce((v_input->>'discountPercent')::numeric,0);
  for v_label in select unnest(array['low','base','high']) loop
    v_hours:=(v_scenario->>(v_label||'HoursPerUnit'))::numeric;
    v_new_amount:=round(v_base_amount*v_hours/v_base_hours);
    v_quantity:=v_direct-v_base_amount+v_new_amount;
    v_scenarios:=v_scenarios||pg_catalog.jsonb_build_object(v_label,
      pg_catalog.jsonb_build_object('hoursPerUnit',v_hours,
        'directCostMinor',v_quantity,
        'includedCostMinor',v_quantity+round(v_quantity*v_overhead/100)+
          round(v_quantity*v_contingency/100),
        'priceMinor',ceil((v_quantity+round(v_quantity*v_overhead/100)+
          round(v_quantity*v_contingency/100))*100/(100-v_target))-
          round(ceil((v_quantity+round(v_quantity*v_overhead/100)+
          round(v_quantity*v_contingency/100))*100/(100-v_target))*v_discount/100)));
  end loop;
  new.estimate:=pg_catalog.jsonb_set(new.estimate,'{detailed,romScenarios}',
    v_scenarios,true);
  return new;
end; $function$

CREATE OR REPLACE FUNCTION d5o_hosted.validate_job_bill_v2(p_workspace uuid, p_work uuid, p_lines jsonb, p_exclude_bill uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_design d5o_hosted.connected_design_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_award jsonb;v_line jsonb;v_release jsonb;v_completion jsonb;v_turnover jsonb;
  v_evidence jsonb;v_basis jsonb:='[]'::jsonb;v_group record;
  v_quantity numeric;v_reserved numeric;v_mixed boolean;v_capacity numeric;
  v_contract bigint;v_allocated numeric;v_requested numeric;v_index integer:=0;
begin
  if pg_catalog.jsonb_typeof(p_lines)<>'array' or pg_catalog.jsonb_array_length(p_lines) not between 1 and 20 then
    raise exception 'billing_lines_required' using errcode='22023'; end if;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=p_workspace and work_id=p_work;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=p_workspace and work_id=p_work;
  if v_design.work_id is null or v_deploy.work_id is null then
    raise exception 'accepted_billing_scope_and_evidence_required' using errcode='23514'; end if;
  for v_line in select value from pg_catalog.jsonb_array_elements(p_lines) loop
    v_index:=v_index+1;
    if pg_catalog.jsonb_typeof(v_line)<>'object' or
      coalesce(v_line->>'scopeKind','Package')<>'Package' or
      length(coalesce(v_line->>'packageId',''))<3 then
      -- No separately accepted milestone or whole-scope allocation exists in this pilot.
      raise exception 'billing_scope_kind_unsupported' using errcode='23514'; end if;
    if coalesce(v_line->>'amountMinor','')!~'^\d+$' or
      (v_line->>'amountMinor')::numeric not between 1 and 1000000000000 or
      length(trim(coalesce(v_line->>'description','')))<5 or
      coalesce(v_line->>'evidenceId','')='' or
      coalesce(v_line->>'quantity','')!~'^\d+(\.\d{1,3})?$' or
      coalesce(v_line->>'unit','')='' then
      raise exception 'billing_line_invalid' using errcode='22023'; end if;
    v_quantity:=(v_line->>'quantity')::numeric;
    if v_quantity<=0 or v_quantity>1000000 then
      raise exception 'billing_quantity_invalid' using errcode='22023'; end if;
    select r into v_release from pg_catalog.jsonb_array_elements(
      coalesce(v_design.state->'releases','[]'::jsonb)) r
      where r->>'packageId'=v_line->>'packageId'
      order by r->>'issuedAt' desc limit 1;
    select c into v_completion from pg_catalog.jsonb_array_elements(
      coalesce(v_deploy.state->'completions','[]'::jsonb)) c
      where c->>'packageId'=v_line->>'packageId' and c->>'releaseId'=v_release->>'id'
        and c->>'status'='Reviewed' order by c->>'reviewedAt' desc limit 1;
    select t into v_turnover from pg_catalog.jsonb_array_elements(
      coalesce(v_deploy.state->'turnovers','[]'::jsonb)) t
      where t->>'packageId'=v_line->>'packageId' and t->>'status'='Client accepted'
        and t->>'receipt'='Accepted' and t->>'completionId'=v_completion->>'id'
        and t->'releaseIds' ? (v_release->>'id')
      order by t->>'acceptedAt' desc limit 1;
    select e into v_evidence from pg_catalog.jsonb_array_elements(
      coalesce(v_deploy.state->'evidence','[]'::jsonb)) e
      where e->>'id'=v_line->>'evidenceId' and e->>'packageId'=v_line->>'packageId'
        and e->>'releaseId'=v_release->>'id' and e->>'state'='Reviewed';
    if v_release is null or v_release->>'status'<>'Accepted' or
      v_completion is null or v_turnover is null or v_evidence is null then
      raise exception 'accepted_billing_scope_and_evidence_required' using errcode='23514'; end if;
    if v_release#>>'{snapshot,completionBasis,kind}'='Measured' then
      if v_line->>'unit' is distinct from v_completion->>'unit' or
        coalesce(v_completion->>'reviewedQuantity','')!~'^\d+(\.\d{1,3})?$' then
        raise exception 'billing_unit_or_completion_invalid' using errcode='23514'; end if;
    elsif v_quantity<>1 or v_line->>'unit'<>'scope' then
      raise exception 'billing_qualitative_scope_invalid' using errcode='23514'; end if;
    v_basis:=v_basis||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'lineIndex',v_index,'packageId',v_line->>'packageId','release',v_release,
      'completion',v_completion,'turnover',v_turnover,'evidence',v_evidence));
  end loop;
  for v_group in select line->>'packageId' package_id,
      sum((line->>'quantity')::numeric) quantity,
      min(line->>'unit') unit,count(distinct line->>'unit') unit_count
      from pg_catalog.jsonb_array_elements(p_lines) line group by line->>'packageId'
  loop
    if v_group.unit_count<>1 then
      raise exception 'billing_unit_conflict' using errcode='23514'; end if;
    select coalesce(sum((line->>'quantity')::numeric),0),
      coalesce(bool_or(line->>'unit' is distinct from v_group.unit),false)
      into v_reserved,v_mixed
      from d5o_hosted.connected_job_bills b,
        lateral pg_catalog.jsonb_array_elements(b.lines) line
      where b.workspace_id=p_workspace and b.work_id=p_work and b.status<>'Returned'
        and b.id is distinct from p_exclude_bill and line->>'packageId'=v_group.package_id;
    if v_mixed then raise exception 'billing_unit_conflict' using errcode='23514'; end if;
    select case when basis->'release'#>>'{snapshot,completionBasis,kind}'='Measured'
      then (basis->'completion'->>'reviewedQuantity')::numeric else 1 end
      into v_capacity from pg_catalog.jsonb_array_elements(v_basis) basis
      where basis->>'packageId'=v_group.package_id limit 1;
    if v_capacity is null or v_reserved+v_group.quantity>v_capacity then
      raise exception 'billing_exceeds_accepted_quantity' using errcode='23514'; end if;
  end loop;
  v_award:=d5o_hosted.job_finance_award_v1(p_workspace,p_work);
  if v_award is null or v_award#>>'{pricingBasis,currency}'<>'USD' then
    raise exception 'approved_usd_fixed_price_award_required' using errcode='23514'; end if;
  v_contract:=(v_award#>>'{pricingBasis,priceMinor}')::bigint;
  select v_contract+coalesce(sum(((c.facts#>>'{proposal,priceAmount}')::numeric*100)::bigint),0)
    into v_contract from d5o_hosted.connected_field_changes c
    where c.workspace_id=p_workspace and c.work_id=p_work and c.status='Resolved'
      and c.kind='Scope change' and c.facts ? 'customerAuthorization'
      and c.facts ? 'revisedReleaseId' and c.facts#>>'{proposal,currency}'='USD';
  select coalesce(sum((line->>'amountMinor')::numeric),0) into v_allocated
    from d5o_hosted.connected_job_bills b,lateral pg_catalog.jsonb_array_elements(b.lines) line
    where b.workspace_id=p_workspace and b.work_id=p_work and b.status<>'Returned'
      and b.id is distinct from p_exclude_bill;
  select coalesce(sum((line->>'amountMinor')::numeric),0) into v_requested
    from pg_catalog.jsonb_array_elements(p_lines) line;
  if v_allocated+v_requested>v_contract then
    raise exception 'billing_exceeds_authorized_contract' using errcode='23514'; end if;
  return pg_catalog.jsonb_build_object('currency','USD','contractMinor',v_contract,
    'designRevision',v_design.decision_revision,'deployRevision',v_deploy.decision_revision,
    'lines',v_basis);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_design_cost_my_review_v1(p_workspace_key text, p_presentation_id text, p_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; role_name text;
 claim d5o_hosted.design_cost_claims%rowtype; enabled_at timestamptz; enabled boolean; chosen uuid;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name<>'billing_commercial_lead' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 select * into claim from d5o_hosted.design_cost_claims
  where workspace_id=ws and work_id=w and id=p_claim_id;
 if claim.id is null or claim.status<>'Prepared' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=ws and category='design_cost_review';
 enabled:=enabled_at is not null and claim.created_at>=enabled_at;
 if enabled then
  chosen:=d5o_hosted.spending_delegate_selected_v1(ws,w,'design_cost_review',
   'billing_commercial_lead',claim.amount_minor,claim.currency,claim.prepared_by,current_date); end if;
 return pg_catalog.jsonb_build_object('pending',true,'configured',enabled,
  'canReview',case when enabled then coalesce(chosen=actor,false)
   else claim.prepared_by<>actor end,
  'held',enabled and chosen is null,
  'route',case when enabled and chosen is null then 'No eligible Design cost reviewer or sponsor is configured.'
   when enabled and chosen=actor then 'This exact Design cost review is assigned to you.'
   when enabled then 'Waiting for the configured independent Design cost reviewer.'
   else 'Existing independent Finance review applies to this earlier claim.' end);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_design_internal_rate_command_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; member d5o_hosted.memberships%rowtype;
 pos d5o_hosted.design_internal_rate_positions%rowtype; rate d5o_hosted.design_internal_rates%rowtype;
 receipt d5o_hosted.design_internal_rate_receipts%rowtype; fp text; result jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null
  or p_action not in ('prepare','approve','return','retire') or pg_catalog.jsonb_typeof(p_input)<>'object'
  or length(coalesce(p_command_id,'')) not between 8 and 120 or p_expected_revision is null or p_expected_revision<0
  then raise exception 'invalid_internal_rate_command' using errcode='22023'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active' for share;
 if member.id is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_action,p_input,p_expected_revision)::text);
 select * into receipt from d5o_hosted.design_internal_rate_receipts where workspace_id=ws and command_id=p_command_id;
 if found then
  if receipt.actor_user_id<>actor or receipt.fingerprint<>fp then raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return receipt.result; end if;
 insert into d5o_hosted.design_internal_rate_positions(workspace_id) values(ws) on conflict do nothing;
 select * into pos from d5o_hosted.design_internal_rate_positions where workspace_id=ws for update;
 if pos.revision<>p_expected_revision then raise exception 'stale_internal_rate_revision' using errcode='23505'; end if;
 if p_action='prepare' then
  if member.role<>'billing_commercial_lead' then raise exception 'finance_rate_preparer_required' using errcode='42501'; end if;
  if coalesce(p_input->>'rateKey','') !~ '^[a-z][a-z0-9_-]{2,39}$'
   or coalesce(p_input->>'baseRateMinor','') !~ '^[1-9][0-9]*$'
   or coalesce(p_input->>'burdenBasisPoints','') !~ '^(0|[1-9][0-9]*)$'
   or coalesce(p_input->>'effectiveFrom','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or coalesce(p_input->>'effectiveUntil','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or length(trim(coalesce(p_input->>'sourceReference','')))<8
   or length(trim(coalesce(p_input->>'basisNote','')))<10 then
   raise exception 'internal_rate_basis_required' using errcode='22023'; end if;
  if (p_input->>'baseRateMinor')::bigint>100000000 or (p_input->>'burdenBasisPoints')::integer>10000
   or (p_input->>'effectiveFrom')::date>(p_input->>'effectiveUntil')::date
   or (p_input->>'effectiveUntil')::date<current_date then
   raise exception 'internal_rate_basis_invalid' using errcode='23514'; end if;
  insert into d5o_hosted.design_internal_rates(workspace_id,rate_key,status,currency,base_rate_minor,
   burden_basis_points,effective_from,effective_until,source_reference,basis_note,prepared_by)
   values(ws,p_input->>'rateKey','Prepared','USD',(p_input->>'baseRateMinor')::bigint,
    (p_input->>'burdenBasisPoints')::integer,(p_input->>'effectiveFrom')::date,
    (p_input->>'effectiveUntil')::date,trim(p_input->>'sourceReference'),trim(p_input->>'basisNote'),actor)
   returning * into rate;
 else
  if member.role<>'admin' then raise exception 'independent_internal_rate_reviewer_required' using errcode='42501'; end if;
  if coalesce(p_input->>'rateId','') !~ '^[0-9a-fA-F-]{36}$' or length(trim(coalesce(p_input->>'reason','')))<10 then
   raise exception 'internal_rate_decision_basis_required' using errcode='22023'; end if;
  select * into rate from d5o_hosted.design_internal_rates where id=(p_input->>'rateId')::uuid
   and workspace_id=ws for update;
  if rate.id is null then raise exception 'internal_rate_missing' using errcode='23514'; end if;
  if p_action='retire' then
   if rate.status<>'Approved' then raise exception 'approved_internal_rate_required' using errcode='23514'; end if;
  elsif rate.status<>'Prepared' or rate.prepared_by=actor then
   raise exception 'independent_internal_rate_reviewer_required' using errcode='42501'; end if;
  if p_action='approve' then
   if rate.effective_until<current_date or exists(select 1 from d5o_hosted.design_internal_rates x
     where x.workspace_id=ws and x.rate_key=rate.rate_key and x.currency=rate.currency
      and x.status='Approved' and x.id<>rate.id
      and x.effective_from<=rate.effective_until and x.effective_until>=rate.effective_from) then
    raise exception 'overlapping_or_expired_internal_rate' using errcode='23514'; end if;
  end if;
  update d5o_hosted.design_internal_rates set
   status=case p_action when 'approve' then 'Approved' when 'return' then 'Returned' else 'Retired' end,
   reviewed_by=actor,review_note=trim(p_input->>'reason'),decided_at=now() where id=rate.id;
 end if;
 update d5o_hosted.design_internal_rate_positions set revision=revision+1 where workspace_id=ws;
 result:=pg_catalog.jsonb_build_object('revision',pos.revision+1,'rateId',rate.id,
  'status',case p_action when 'prepare' then 'Prepared' when 'approve' then 'Approved'
   when 'return' then 'Returned' else 'Retired' end);
 insert into d5o_hosted.design_internal_rate_events(workspace_id,revision,command_id,action,actor_user_id,membership_id,rate_id,basis)
  values(ws,pos.revision+1,p_command_id,p_action,actor,member.id,rate.id,
   pg_catalog.jsonb_build_object('input',p_input,'rate',to_jsonb(rate)));
 insert into d5o_hosted.design_internal_rate_receipts(workspace_id,command_id,actor_user_id,fingerprint,result)
  values(ws,p_command_id,actor,fp,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_design_internal_rate_read_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null or role_name not in ('admin','project_manager','billing_commercial_lead') then
  raise exception 'internal_rate_scope_denied' using errcode='42501'; end if;
 return pg_catalog.jsonb_build_object(
  'revision',coalesce((select revision from d5o_hosted.design_internal_rate_positions where workspace_id=ws),0),
  'rates',coalesce((select pg_catalog.jsonb_agg(to_jsonb(r) order by r.created_at)
   from d5o_hosted.design_internal_rates r where r.workspace_id=ws
    and (role_name<>'project_manager' or r.status='Approved')),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_field_labor_my_review_v1(p_workspace_key text, p_presentation_id text, p_authority_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; role_name text;
 authority d5o_hosted.labor_authorities%rowtype; enabled_at timestamptz;
 chosen uuid; enabled boolean;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 if role_name is null or w is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name<>'admin' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select * into authority from d5o_hosted.labor_authorities
  where workspace_id=ws and work_id=w and id=p_authority_id;
 if authority.id is null or authority.status<>'Prepared' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=ws and category='field_labor_authority';
 enabled:=enabled_at is not null and authority.created_at>=enabled_at;
 if enabled then
  chosen:=d5o_hosted.spending_delegate_selected_v1(ws,w,'field_labor_authority','admin',
   authority.cap_minor,authority.currency,authority.prepared_by,current_date); end if;
 return pg_catalog.jsonb_build_object('pending',true,'configured',enabled,
  'canReview',case when enabled then coalesce(chosen=actor,false)
   else authority.prepared_by<>actor end,
  'held',enabled and chosen is null,
  'route',case when enabled and chosen is null then 'No eligible field-labor delegate or sponsor is configured.'
   when enabled and chosen=actor then 'This exact field-labor decision is assigned to you.'
   when enabled then 'Waiting for the configured independent field-labor reviewer.'
   else 'Existing independent administrator review applies to this earlier draft.' end);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_actions_pre_purchase_delegation_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_role text;v_row record;v_order jsonb;v_invoice jsonb;
  v_actions jsonb:='[]'::jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  select role into v_role from d5o_hosted.memberships
    where workspace_id=v_workspace and actor_user_id=v_actor and status='active';
  if v_role is null or v_role='field_worker' then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  for v_row in select s.revision,s.state,l.presentation_id,w.title from d5o_hosted.graybar_states s
    join d5o_hosted.work_identity_links l on l.workspace_id=s.workspace_id and l.work_id=s.work_id
    join d5o_hosted.work_records w on w.workspace_id=s.workspace_id and w.id=s.work_id
    where s.workspace_id=v_workspace loop
    if v_row.state#>>'{bom,status}'='Prepared' and v_role in ('admin','operations_leader')
      and v_row.state#>>'{bom,preparedBy}'<>v_actor::text then
      v_actions:=v_actions||jsonb_build_array(jsonb_build_object('kind','Review Design BOM','phase','Procurement',
        'focus','bom','workId',v_row.presentation_id,'revision',v_row.revision,'status','Prepared',
        'title',v_row.title,'ownership','Independent technical reviewer','decisionId',v_row.state#>>'{bom,id}'));
    end if;
    for v_order in select value from jsonb_array_elements(v_row.state->'orders') loop
      if v_order->>'status'='Prepared' and v_role='admin' and v_order->>'preparedBy'<>v_actor::text then
        v_actions:=v_actions||jsonb_build_array(jsonb_build_object('kind','Approve Graybar PO','phase','Procurement',
          'focus','po','workId',v_row.presentation_id,'revision',v_row.revision,'status','Prepared',
          'title',v_row.title,'ownership','Workspace administrator','decisionId',v_order->>'id'));
      end if;
    end loop;
    for v_invoice in select value from jsonb_array_elements(v_row.state->'supplierInvoices') loop
      if v_invoice->>'status' in ('Review','Exception') and v_role in ('admin','billing_commercial_lead')
        and v_invoice->>'recordedBy'<>v_actor::text then
        v_actions:=v_actions||jsonb_build_array(jsonb_build_object('kind','Review supplier invoice','phase','Procurement',
          'focus','invoice','workId',v_row.presentation_id,'revision',v_row.revision,
          'status',v_invoice->>'status','title',v_row.title,'ownership','Independent Finance reviewer',
          'decisionId',v_invoice->>'id',
          'blocker',case when v_invoice->>'status'='Exception' then 'Price or amount mismatch requires a held disposition.' else null end));
      end if;
    end loop;
  end loop;
  return v_actions;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare raw jsonb; entry jsonb; output jsonb:='[]'::jsonb; route jsonb;
begin
 raw:=public.d5o_graybar_actions_pre_purchase_delegation_v1(p_workspace_key);
 for entry in select value from pg_catalog.jsonb_array_elements(raw) loop
  if entry->>'kind'='Approve Graybar PO' then
   route:=public.d5o_purchase_order_my_review_v1(p_workspace_key,entry->>'workId',
    (entry->>'decisionId')::uuid);
   if not coalesce((route->>'canReview')::boolean,false) then continue; end if;
  end if;
  output:=output||pg_catalog.jsonb_build_array(entry);
 end loop;
 return output;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_current d5o_hosted.graybar_states%rowtype;v_receipt d5o_hosted.graybar_receipts%rowtype;
  v_define d5o_hosted.connected_define_states%rowtype;v_design d5o_hosted.connected_design_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_estimate d5o_hosted.connected_estimate_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;v_operate_state jsonb;v_asset jsonb;v_deploy_revision integer;
  v_state jsonb;v_result jsonb;v_source jsonb:='{}'::jsonb;v_item jsonb;v_line jsonb;
  v_quote jsonb;v_bom jsonb;v_order jsonb;v_order_lines jsonb;v_receipt_item jsonb;v_invoice jsonb;
  v_product d5o_hosted.graybar_products%rowtype;v_quote_lines jsonb;
  v_fingerprint text;v_revision integer;v_total bigint;v_sum bigint;v_quantity numeric;
  v_doc uuid;v_id text;v_now timestamptz:=now();v_count integer;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null or p_action not in
    ('accept-quote','assess-product','prepare-bom','approve-bom','prepare-po','cancel-po-draft','approve-po',
     'record-test-submission','record-acknowledgment','record-shipment','record-receipt',
     'record-supplier-invoice','review-supplier-invoice','record-return','record-credit','handoff-installed')
    or jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_graybar_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role='field_worker' then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=md5(jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,p_expected_revision)::text);
  select * into v_receipt from d5o_hosted.graybar_receipts where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_current from d5o_hosted.graybar_states where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if coalesce(v_current.revision,0)<>p_expected_revision then raise exception 'stale_state' using errcode='23505'; end if;
  v_state:=coalesce(v_current.state,'{"quotes":[],"assessments":[],"bom":null,"orders":[],"shipments":[],"receipts":[],"supplierInvoices":[],"returns":[],"credits":[],"installed":[]}'::jsonb);
  select * into v_define from d5o_hosted.connected_define_states where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_design from d5o_hosted.connected_design_states where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_estimate from d5o_hosted.connected_estimate_states where workspace_id=v_workspace.id and work_id=v_work.id for share;
  if p_action in ('prepare-bom','approve-bom','prepare-po','cancel-po-draft','approve-po','record-test-submission') then
    select * into v_deploy from d5o_hosted.connected_deploy_states
      where workspace_id=v_workspace.id and work_id=v_work.id for share;
    if v_deploy.state#>>'{workAcceptance,receipt}'='Accepted' then
      raise exception 'accepted_work_requires_separate_amendment' using errcode='23514'; end if;
  end if;
  if p_action='accept-quote' then
    if v_member.role not in ('admin','project_manager','billing_commercial_lead')
      or v_define.status is distinct from 'Approved' or v_define.projection#>>'{developHandoff,status}' is distinct from 'accepted' then
      raise exception 'approved_define_and_preparer_required' using errcode='42501'; end if;
    if coalesce(p_input->>'quoteNumber','')='' or coalesce(p_input->>'quoteRevision','')=''
      or coalesce(p_input->>'accountReference','')='' or p_input->>'currency'<> 'USD'
      or coalesce(p_input->>'quotedAt','') !~ '^\d{4}-\d{2}-\d{2}$'
      or coalesce(p_input->>'expiresAt','') !~ '^\d{4}-\d{2}-\d{2}$'
      or jsonb_typeof(p_input->'lines')<>'array' or jsonb_array_length(p_input->'lines')=0 then
      raise exception 'quote_header_invalid' using errcode='23514'; end if;
    v_doc:=(p_input->>'documentId')::uuid;
    if not exists(select 1 from d5o_hosted.graybar_documents where workspace_id=v_workspace.id and work_id=v_work.id and id=v_doc and kind='quote') then
      raise exception 'retained_quote_document_required' using errcode='23514'; end if;
    if exists(select 1 from jsonb_array_elements(v_state->'quotes') q where q->>'quoteNumber'=p_input->>'quoteNumber'
      and q->>'quoteRevision'=p_input->>'quoteRevision') then raise exception 'duplicate_quote_revision' using errcode='23505'; end if;
    if exists(select 1 from jsonb_array_elements(v_state->'quotes') q where q->>'documentId'=p_input->>'documentId') then
      raise exception 'duplicate_quote_document' using errcode='23505'; end if;
    if exists(select 1 from jsonb_array_elements(v_state->'quotes') q
      join d5o_hosted.graybar_documents prior on prior.workspace_id=v_workspace.id and prior.work_id=v_work.id
        and prior.id=(q->>'documentId')::uuid
      join d5o_hosted.graybar_documents incoming on incoming.id=v_doc
      where prior.sha256=incoming.sha256) then
      raise exception 'duplicate_quote_bytes' using errcode='23505'; end if;
    if exists(select 1 from (select l->>'lineNumber' as n,count(*) as c from jsonb_array_elements(p_input->'lines') l group by l->>'lineNumber') x
      where x.n is null or x.n='' or x.c>1) then raise exception 'duplicate_quote_line' using errcode='23514'; end if;
    v_sum:=0;v_quote_lines:='[]'::jsonb;
    for v_line in select value from jsonb_array_elements(p_input->'lines') loop
      if coalesce(v_line->>'graybarSku','')='' or coalesce(v_line->>'description','')=''
        or coalesce(v_line->>'unit','')='' or coalesce(v_line->>'quantity','') !~ '^\d+(\.\d{1,3})?$'
        or (v_line->>'quantity')::numeric<=0 or coalesce(v_line->>'packSize','') !~ '^\d+(\.\d{1,3})?$'
        or (v_line->>'packSize')::numeric<=0 or v_line->>'priceBasis' not in ('each','pack','length')
        or coalesce(v_line->>'unitPriceMinor','') !~ '^\d+$' or coalesce(v_line->>'extendedMinor','') !~ '^\d+$'
        or (v_line->>'unitPriceMinor')::bigint=0 and length(trim(coalesce(v_line->>'noCostReason','')))<8
        or (v_line->>'extendedMinor')::bigint<>round((v_line->>'quantity')::numeric/(v_line->>'packSize')::numeric*(v_line->>'unitPriceMinor')::bigint)::bigint then
        raise exception 'quote_line_arithmetic_or_unit_invalid' using errcode='23514'; end if;
      v_sum:=v_sum+(v_line->>'extendedMinor')::bigint;
      select * into v_product from d5o_hosted.graybar_products
        where workspace_id=v_workspace.id and graybar_sku=v_line->>'graybarSku' for update;
      if found then
        if (nullif(v_product.manufacturer,'') is not null and nullif(v_line->>'manufacturer','') is not null
            and v_product.manufacturer<>v_line->>'manufacturer')
          or (nullif(v_product.manufacturer_part_number,'') is not null and nullif(v_line->>'manufacturerPartNumber','') is not null
            and v_product.manufacturer_part_number<>v_line->>'manufacturerPartNumber') then
          raise exception 'product_identity_conflict' using errcode='23514'; end if;
      else
        insert into d5o_hosted.graybar_products(workspace_id,graybar_sku,manufacturer,manufacturer_part_number,
          first_description,first_quote_document_id)
          values(v_workspace.id,v_line->>'graybarSku',nullif(v_line->>'manufacturer',''),
            nullif(v_line->>'manufacturerPartNumber',''),v_line->>'description',v_doc)
          returning * into v_product;
      end if;
      v_quote_lines:=v_quote_lines||jsonb_build_array(v_line||jsonb_build_object('productId',v_product.id));
    end loop;
    if coalesce(p_input->>'freightMinor','') !~ '^\d+$' or coalesce(p_input->>'totalMinor','') !~ '^\d+$'
      or v_sum+(p_input->>'freightMinor')::bigint<>(p_input->>'totalMinor')::bigint then
      raise exception 'quote_total_mismatch' using errcode='23514'; end if;
    v_id:=gen_random_uuid()::text;
    v_item:=p_input||jsonb_build_object('id',v_id,'lines',v_quote_lines,'defineRevision',v_define.definition_revision,
      'acceptedBy',v_actor,'acceptedAt',v_now,'channel','document','status','Accepted');
    v_state:=jsonb_set(v_state,'{quotes}',v_state->'quotes'||jsonb_build_array(v_item));
    update d5o_hosted.graybar_document_extractions set accepted_by=v_actor
      where document_id=v_doc and version=1 and accepted_by is null;
    v_source:=jsonb_build_object('defineRevision',v_define.definition_revision,'documentId',v_doc);
  elsif p_action='assess-product' then
    if v_member.role not in ('admin','operations_leader') then raise exception 'technical_reviewer_required' using errcode='42501'; end if;
    select value into v_quote from jsonb_array_elements(v_state->'quotes') where value->>'id'=p_input->>'quoteId';
    if v_quote is null or v_quote->>'defineRevision'<>v_define.definition_revision::text
      or v_quote->>'acceptedBy'=v_actor::text or p_input->>'result' not in ('Meets','Alternative','Insufficient evidence','Fails')
      or coalesce(p_input->>'requirementId','')='' or coalesce(p_input->>'rationale','')='' or coalesce(p_input->>'specificationSource','')='' then
      raise exception 'product_assessment_invalid' using errcode='23514'; end if;
    if not exists(select 1 from d5o_hosted.graybar_documents where workspace_id=v_workspace.id and work_id=v_work.id
      and id=(p_input->>'specificationDocumentId')::uuid and kind in ('specification','quote')) then
      raise exception 'retained_specification_required' using errcode='23514'; end if;
    if not exists(select 1 from jsonb_array_elements(v_quote->'lines') where value->>'lineNumber'=p_input->>'lineNumber')
      or not exists(select 1 from jsonb_array_elements(coalesce(v_define.projection#>'{scopeControl,requirements}','[]'::jsonb))
        where value->>'id'=p_input->>'requirementId') then raise exception 'product_requirement_mismatch' using errcode='23514'; end if;
    if exists(select 1 from jsonb_array_elements(v_state->'assessments') a where a->>'quoteId'=p_input->>'quoteId'
      and a->>'lineNumber'=p_input->>'lineNumber' and a->>'requirementId'=p_input->>'requirementId') then
      raise exception 'assessment_already_recorded' using errcode='23505'; end if;
    v_item:=p_input||jsonb_build_object('id',gen_random_uuid(),'defineRevision',v_define.definition_revision,'reviewedBy',v_actor,'reviewedAt',v_now);
    v_state:=jsonb_set(v_state,'{assessments}',v_state->'assessments'||jsonb_build_array(v_item));
    v_source:=jsonb_build_object('quoteId',p_input->>'quoteId','defineRevision',v_define.definition_revision);
  elsif p_action='prepare-bom' then
    if v_member.role not in ('admin','project_manager') or v_design.work_id is null
      or v_estimate.status is distinct from 'Approved' or v_define.status is distinct from 'Approved'
      or jsonb_typeof(p_input->'lines')<>'array' or jsonb_array_length(p_input->'lines')=0 then
      raise exception 'current_design_and_rom_required' using errcode='23514'; end if;
    if v_state->'bom' is not null and v_state#>>'{bom,status}'='Approved' then
      raise exception 'approved_bom_locked' using errcode='23514'; end if;
    if exists(select 1 from (select l->>'materialId' as id,count(*) c from jsonb_array_elements(p_input->'lines') l group by l->>'materialId') x
      where x.id is null or x.c>1) then raise exception 'duplicate_bom_allocation' using errcode='23514'; end if;
    for v_line in select value from jsonb_array_elements(p_input->'lines') loop
      select value into v_item from jsonb_array_elements(coalesce(v_design.state->'packages','[]'::jsonb))
        where value->>'packageId'=v_line->>'packageId' and value->>'revision'=v_line->>'packageRevision'
          and value->>'status' in ('In review','Approved');
      if v_item is null or v_item->>'commercialDisposition'='Assessment required'
        or not exists(select 1 from jsonb_array_elements(coalesce(v_item->'materialLines','[]'::jsonb)) m
        where m->>'id'=v_line->>'materialId' and m->>'item'=v_line->>'item'
          and m->>'unit'=v_line->>'unit' and m->>'quantity'=v_line->>'quantity') then
        raise exception 'bom_design_line_mismatch' using errcode='23514'; end if;
      select value into v_quote from jsonb_array_elements(v_state->'quotes') where value->>'id'=v_line->>'quoteId';
      if v_quote is null or v_quote->>'defineRevision'<>v_define.definition_revision::text
        or not exists(select 1 from jsonb_array_elements(v_quote->'lines') q where q->>'lineNumber'=v_line->>'lineNumber'
          and q->>'unit'=v_line->>'unit' and q->>'description'=v_line->>'item')
        or not exists(select 1 from jsonb_array_elements(v_state->'assessments') a
          where a->>'quoteId'=v_line->>'quoteId' and a->>'lineNumber'=v_line->>'lineNumber' and a->>'result'='Meets') then
        raise exception 'bom_quote_or_assessment_invalid' using errcode='23514'; end if;
      if coalesce(v_line->>'supplyResponsibility','') not in ('Rybex','Customer') or
        coalesce(v_line->>'requiredDate','') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception 'bom_supply_basis_invalid' using errcode='23514'; end if;
    end loop;
    if exists(select 1 from jsonb_array_elements(coalesce(v_design.state->'packages','[]'::jsonb)) p
      cross join lateral jsonb_array_elements(coalesce(p->'materialLines','[]'::jsonb)) m
      where exists(select 1 from jsonb_array_elements(coalesce(v_design.state->'releases','[]'::jsonb)) r
        where r->>'packageId'=p->>'packageId' and r->>'packageRevision'=p->>'revision' and r->>'status'='Accepted')
      and not exists(select 1 from jsonb_array_elements(p_input->'lines') l where l->>'materialId'=m->>'id')) then
      raise exception 'bom_released_material_missing' using errcode='23514'; end if;
    v_bom:=jsonb_build_object('id',gen_random_uuid(),'status','Prepared','designRevision',v_design.decision_revision,
      'defineRevision',v_define.definition_revision,'estimateRevision',v_estimate.estimate_revision,
      'lines',p_input->'lines','preparedBy',v_actor,'preparedAt',v_now,'romDifference',coalesce(p_input->>'romDifference',''),
      'unpricedDifferences',coalesce(p_input->>'unpricedDifferences',''));
    v_state:=jsonb_set(v_state,'{bom}',v_bom);
    v_source:=jsonb_build_object('designRevision',v_design.decision_revision,'estimateRevision',v_estimate.estimate_revision);
  elsif p_action='approve-bom' then
    v_bom:=v_state->'bom';
    if v_member.role not in ('admin','operations_leader') or v_bom->>'status'<>'Prepared'
      or v_bom->>'preparedBy'=v_actor::text or v_bom->>'designRevision'<>v_design.decision_revision::text
      or v_bom->>'estimateRevision'<>v_estimate.estimate_revision::text
      or v_bom->>'defineRevision'<>v_define.definition_revision::text
      or coalesce(p_input->>'reviewNote','')='' then
      raise exception 'independent_current_bom_review_required' using errcode='42501'; end if;
    v_bom:=v_bom||jsonb_build_object('status','Approved','approvedBy',v_actor,'approvedAt',v_now,'reviewNote',p_input->>'reviewNote');
    v_state:=jsonb_set(v_state,'{bom}',v_bom);
    v_source:=jsonb_build_object('bomId',v_bom->>'id','designRevision',v_design.decision_revision);
  elsif p_action='prepare-po' then
    v_bom:=v_state->'bom';
    if v_member.role not in ('admin','project_manager') or v_bom->>'status'<>'Approved'
      or v_bom->>'designRevision'<>v_design.decision_revision::text
      or v_bom->>'defineRevision'<>v_define.definition_revision::text
      or v_bom->>'estimateRevision'<>v_estimate.estimate_revision::text
      or jsonb_typeof(p_input->'lines')<>'array' or jsonb_array_length(p_input->'lines')=0
      or coalesce(p_input->>'shipTo','')='' or coalesce(p_input->>'accountReference','')='' then
      raise exception 'approved_current_bom_required' using errcode='23514'; end if;
    if exists(select 1 from (select l->>'materialId' id,count(*) c from jsonb_array_elements(p_input->'lines') l group by l->>'materialId') x
      where x.id is null or x.c>1) then raise exception 'duplicate_po_allocation' using errcode='23514'; end if;
    v_order_lines:='[]'::jsonb;
    v_sum:=0;
    for v_line in select value from jsonb_array_elements(p_input->'lines') loop
      select value into v_item from jsonb_array_elements(v_bom->'lines') where value->>'materialId'=v_line->>'materialId';
      select coalesce(sum((allocated->>'quantity')::numeric),0) into v_quantity
        from jsonb_array_elements(v_state->'orders') prior,
          jsonb_array_elements(prior->'lines') allocated
        where prior->>'bomId'=v_bom->>'id' and prior->>'status'<>'Cancelled'
          and allocated->>'materialId'=v_line->>'materialId';
      if v_item is null or v_item->>'supplyResponsibility'<>'Rybex'
        or coalesce(v_line->>'quantity','') !~ '^\d+(\.\d{1,3})?$'
        or (v_line->>'quantity')::numeric<=0
        or v_quantity+(v_line->>'quantity')::numeric>(v_item->>'quantity')::numeric
        or v_line->>'unit'<>v_item->>'unit' then
        raise exception 'po_bom_allocation_invalid' using errcode='23514'; end if;
      select value into v_quote from jsonb_array_elements(v_state->'quotes') where value->>'id'=v_item->>'quoteId';
      if v_quote is null or v_quote->>'expiresAt'<current_date::text or v_quote->>'accountReference'<>p_input->>'accountReference' then
        raise exception 'quote_expired_or_account_changed' using errcode='23514'; end if;
      if coalesce((v_quote->>'freightMinor')::bigint,0)>0 then raise exception 'freight_disposition_required' using errcode='23514'; end if;
      select value into v_receipt_item from jsonb_array_elements(v_quote->'lines') where value->>'lineNumber'=v_item->>'lineNumber';
      if v_receipt_item is null or v_receipt_item->>'unit'<>v_line->>'unit'
        or (v_receipt_item->>'priceBasis')='pack' and mod((v_line->>'quantity')::numeric,(v_receipt_item->>'packSize')::numeric)<>0 then
        raise exception 'po_pack_or_unit_invalid' using errcode='23514'; end if;
      v_sum:=v_sum+round((v_line->>'quantity')::numeric/(v_receipt_item->>'packSize')::numeric*(v_receipt_item->>'unitPriceMinor')::bigint)::bigint;
      v_order_lines:=v_order_lines||jsonb_build_array(v_line||jsonb_build_object(
        'unitPriceMinor',v_receipt_item->>'unitPriceMinor','packSize',v_receipt_item->>'packSize',
        'graybarSku',v_receipt_item->>'graybarSku','quoteId',v_quote->>'id',
        'quoteLineNumber',v_receipt_item->>'lineNumber'));

    end loop;
    if coalesce(p_input->>'budgetMinor','') !~ '^\d+$' or v_sum>(p_input->>'budgetMinor')::bigint then
      raise exception 'purchase_budget_exceeded' using errcode='23514'; end if;
    v_order:=jsonb_build_object('id',gen_random_uuid(),'status','Prepared','bomId',v_bom->>'id',
      'designRevision',v_design.decision_revision,'accountReference',p_input->>'accountReference',
      'shipTo',p_input->>'shipTo','requiredDate',p_input->>'requiredDate','lines',v_order_lines,
      'amountMinor',v_sum,'currency','USD','budgetMinor',(p_input->>'budgetMinor')::bigint,
      'preparedBy',v_actor,'preparedAt',v_now,'substitutionsPermitted',false);
    v_state:=jsonb_set(v_state,'{orders}',v_state->'orders'||jsonb_build_array(v_order));
    v_source:=jsonb_build_object('bomId',v_bom->>'id','designRevision',v_design.decision_revision);
  elsif p_action='cancel-po-draft' then
    select value into v_order from jsonb_array_elements(v_state->'orders') where value->>'id'=p_input->>'orderId';
    if v_order is null or v_order->>'status'<>'Prepared' or
      not (v_member.role='admin' or v_member.role='project_manager' and v_order->>'preparedBy'=v_actor::text) then
      raise exception 'prepared_purchase_draft_owner_required' using errcode='42501'; end if;
    if length(trim(coalesce(p_input->>'reason','')))<10 then
      raise exception 'purchase_draft_cancellation_reason_required' using errcode='23514'; end if;
    v_order:=v_order||jsonb_build_object('status','Cancelled','cancelledBy',v_actor,
      'cancelledAt',v_now,'cancellationReason',trim(p_input->>'reason'));
    v_state:=jsonb_set(v_state,'{orders}',(select jsonb_agg(
      case when value->>'id'=p_input->>'orderId' then v_order else value end order by ordinality)
      from jsonb_array_elements(v_state->'orders') with ordinality));
    v_source:=jsonb_build_object('orderId',v_order->>'id','reason',p_input->>'reason',
      'budgetEffect','none; draft had no reservation');
  elsif p_action='approve-po' then
    select value into v_order from jsonb_array_elements(v_state->'orders') where value->>'id'=p_input->>'orderId';
    if v_member.role<>'admin' or v_order->>'status'<>'Prepared' or v_order->>'preparedBy'=v_actor::text
      or v_order->>'bomId'<>v_state#>>'{bom,id}' or v_order->>'designRevision'<>v_design.decision_revision::text
      or v_state#>>'{bom,defineRevision}'<>v_define.definition_revision::text
      or v_state#>>'{bom,estimateRevision}'<>v_estimate.estimate_revision::text then
      raise exception 'independent_purchasing_authority_required' using errcode='42501'; end if;
    for v_line in select value from jsonb_array_elements(v_order->'lines') loop
      select value into v_item from jsonb_array_elements(v_state#>'{bom,lines}') where value->>'materialId'=v_line->>'materialId';
      select value into v_quote from jsonb_array_elements(v_state->'quotes') where value->>'id'=v_item->>'quoteId';
      if v_quote->>'expiresAt'<current_date::text then raise exception 'quote_expired' using errcode='23514'; end if;
    end loop;
    v_order:=v_order||jsonb_build_object('status','Approved','approvedBy',v_actor,'approvedAt',v_now,
      'authorityBasis',coalesce(p_input->>'authorityBasis','Workspace administrator'));
    v_state:=jsonb_set(v_state,'{orders}',(select jsonb_agg(case when value->>'id'=p_input->>'orderId' then v_order else value end)
      from jsonb_array_elements(v_state->'orders')));
    v_source:=jsonb_build_object('bomId',v_order->>'bomId','orderId',v_order->>'id');
  elsif p_action='record-test-submission' then
    select value into v_order from jsonb_array_elements(v_state->'orders') where value->>'id'=p_input->>'orderId';
    if v_member.role<>'admin' or v_order->>'status'<>'Approved' or p_input->>'testOnly'<>'true'
      or v_work.title !~* '^(fictional|synthetic)' or length(trim(coalesce(p_input->>'sourceReference','')))<6 then
      raise exception 'test_submission_authority_required' using errcode='42501'; end if;
    v_order:=v_order||jsonb_build_object('status','Test submitted','submissionChannel','controlled local fixture',
      'submissionSource',p_input->>'sourceReference','submittedAt',v_now,'submittedBy',v_actor,
      'supplierAcknowledged',false);
    v_state:=jsonb_set(v_state,'{orders}',(select jsonb_agg(case when value->>'id'=p_input->>'orderId' then v_order else value end)
      from jsonb_array_elements(v_state->'orders')));
    v_source:=jsonb_build_object('orderId',v_order->>'id','channel','controlled local fixture');
  elsif p_action='record-acknowledgment' then
    select value into v_order from jsonb_array_elements(v_state->'orders') where value->>'id'=p_input->>'orderId';
    if v_member.role not in ('admin','operations_leader') or v_order->>'status'<>'Test submitted'
      or coalesce(p_input->>'supplierReference','')='' or jsonb_typeof(p_input->'lines')<>'array'
      or jsonb_array_length(p_input->'lines')<>jsonb_array_length(v_order->'lines') then
      raise exception 'submitted_order_ack_required' using errcode='23514'; end if;
    v_doc:=(p_input->>'documentId')::uuid;
    if not exists(select 1 from d5o_hosted.graybar_documents where workspace_id=v_workspace.id and work_id=v_work.id and id=v_doc and kind='acknowledgment') then
      raise exception 'retained_acknowledgment_required' using errcode='23514'; end if;
    if exists(select 1 from (select l->>'materialId' id,count(*) c from jsonb_array_elements(p_input->'lines') l group by l->>'materialId') x
      where x.id is null or x.c>1) then raise exception 'duplicate_acknowledgment_line' using errcode='23514'; end if;
    for v_line in select value from jsonb_array_elements(p_input->'lines') loop
      select value into v_item from jsonb_array_elements(v_order->'lines') where value->>'materialId'=v_line->>'materialId';
      if v_item is null or coalesce(v_line->>'quantity','') !~ '^\d+(\.\d{1,3})?$'
        or (v_line->>'quantity')::numeric>(v_item->>'quantity')::numeric
        or v_line->>'unit'<>v_item->>'unit' or v_line->>'unitPriceMinor'<>v_item->>'unitPriceMinor'
        or coalesce(v_line->>'promisedDate','') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception 'acknowledgment_variance_requires_disposition' using errcode='23514'; end if;
    end loop;
    v_order:=v_order||jsonb_build_object('status','Acknowledged','acknowledgment',p_input||jsonb_build_object('at',v_now,'actorId',v_actor));
    v_state:=jsonb_set(v_state,'{orders}',(select jsonb_agg(case when value->>'id'=p_input->>'orderId' then v_order else value end)
      from jsonb_array_elements(v_state->'orders')));
    v_source:=jsonb_build_object('orderId',v_order->>'id','documentId',v_doc);
  elsif p_action='record-shipment' then
    select value into v_order from jsonb_array_elements(v_state->'orders') where value->>'id'=p_input->>'orderId';
    if v_member.role not in ('admin','operations_leader') or v_order->>'status'<>'Acknowledged'
      or jsonb_typeof(p_input->'lines')<>'array' or jsonb_array_length(p_input->'lines')=0
      or coalesce(p_input->>'trackingReference','')='' then
      raise exception 'acknowledged_order_required' using errcode='23514'; end if;
    v_doc:=(p_input->>'documentId')::uuid;
    if not exists(select 1 from d5o_hosted.graybar_documents where workspace_id=v_workspace.id and work_id=v_work.id and id=v_doc and kind='delivery') then
      raise exception 'retained_delivery_document_required' using errcode='23514'; end if;
    if exists(select 1 from (select l->>'materialId' id,count(*) c from jsonb_array_elements(p_input->'lines') l group by l->>'materialId') x
      where x.id is null or x.c>1) then raise exception 'duplicate_shipment_line' using errcode='23514'; end if;
    for v_line in select value from jsonb_array_elements(p_input->'lines') loop
      select value into v_item from jsonb_array_elements(v_order->'lines') where value->>'materialId'=v_line->>'materialId';
      select coalesce(sum((sline->>'quantity')::numeric),0) into v_quantity from jsonb_array_elements(v_state->'shipments') s,
        jsonb_array_elements(s->'lines') sline where s->>'orderId'=p_input->>'orderId' and sline->>'materialId'=v_line->>'materialId';
      if v_item is null or coalesce(v_line->>'quantity','') !~ '^\d+(\.\d{1,3})?$'
        or (v_line->>'quantity')::numeric<=0 or v_quantity+(v_line->>'quantity')::numeric>(v_item->>'quantity')::numeric then
        raise exception 'shipment_exceeds_acknowledged_order' using errcode='23514'; end if;
    end loop;
    v_item:=p_input||jsonb_build_object('id',gen_random_uuid(),'at',v_now,'actorId',v_actor);
    v_state:=jsonb_set(v_state,'{shipments}',v_state->'shipments'||jsonb_build_array(v_item));
    v_source:=jsonb_build_object('orderId',p_input->>'orderId','documentId',v_doc);
  elsif p_action='record-receipt' then
    if v_member.role not in ('admin','operations_leader','field_supervisor') or p_input->>'physicallyCounted'<>'true'
      or jsonb_typeof(p_input->'lines')<>'array' or coalesce(p_input->>'location','')='' then
      raise exception 'physical_receiving_authority_required' using errcode='42501'; end if;
    select value into v_item from jsonb_array_elements(v_state->'shipments') where value->>'id'=p_input->>'shipmentId';
    if v_item is null then raise exception 'shipment_required' using errcode='23514'; end if;
    if exists(select 1 from (select l->>'materialId' id,count(*) c from jsonb_array_elements(p_input->'lines') l group by l->>'materialId') x
      where x.id is null or x.c>1) then raise exception 'duplicate_receipt_line' using errcode='23514'; end if;
    for v_line in select value from jsonb_array_elements(p_input->'lines') loop
      select value into v_receipt_item from jsonb_array_elements(v_item->'lines') where value->>'materialId'=v_line->>'materialId';
      select coalesce(sum((rline->>'acceptedQuantity')::numeric+(rline->>'rejectedQuantity')::numeric),0) into v_quantity
        from jsonb_array_elements(v_state->'receipts') r,jsonb_array_elements(r->'lines') rline
        where r->>'shipmentId'=p_input->>'shipmentId' and rline->>'materialId'=v_line->>'materialId';
      if v_receipt_item is null or coalesce(v_line->>'acceptedQuantity','') !~ '^\d+(\.\d{1,3})?$'
        or coalesce(v_line->>'rejectedQuantity','') !~ '^\d+(\.\d{1,3})?$'
        or (v_line->>'acceptedQuantity')::numeric+(v_line->>'rejectedQuantity')::numeric<=0
        or v_quantity+(v_line->>'acceptedQuantity')::numeric+(v_line->>'rejectedQuantity')::numeric>(v_receipt_item->>'quantity')::numeric then
        raise exception 'receipt_exceeds_shipment' using errcode='23514'; end if;
    end loop;
    v_item:=p_input||jsonb_build_object('id',gen_random_uuid(),'at',v_now,'actorId',v_actor,'status','Counted');
    v_state:=jsonb_set(v_state,'{receipts}',v_state->'receipts'||jsonb_build_array(v_item));
    v_source:=jsonb_build_object('shipmentId',p_input->>'shipmentId','physicalReceipt',true);
  elsif p_action='record-return' then
    if v_member.role not in ('admin','operations_leader') or coalesce(p_input->>'reason','')=''
      or coalesce(p_input->>'supplierReturnReference','')='' then
      raise exception 'return_authority_and_source_required' using errcode='42501'; end if;
    select value into v_receipt_item from jsonb_array_elements(v_state->'receipts') where value->>'id'=p_input->>'receiptId';
    if v_receipt_item is null then raise exception 'physical_receipt_required' using errcode='23514'; end if;
    select value into v_line from jsonb_array_elements(v_receipt_item->'lines') where value->>'materialId'=p_input->>'materialId';
    select coalesce(sum((r->>'quantity')::numeric),0) into v_quantity from jsonb_array_elements(coalesce(v_state->'returns','[]'::jsonb)) r
      where r->>'receiptId'=p_input->>'receiptId' and r->>'materialId'=p_input->>'materialId';
    if v_line is null or coalesce(p_input->>'quantity','') !~ '^\d+(\.\d{1,3})?$'
      or (p_input->>'quantity')::numeric<=0 or v_quantity+(p_input->>'quantity')::numeric>(v_line->>'acceptedQuantity')::numeric then
      raise exception 'return_exceeds_accepted_receipt' using errcode='23514'; end if;
    v_item:=p_input||jsonb_build_object('id',gen_random_uuid(),'at',v_now,'actorId',v_actor,'status','Supplier return recorded');
    v_state:=jsonb_set(v_state,'{returns}',coalesce(v_state->'returns','[]'::jsonb)||jsonb_build_array(v_item));
    v_source:=jsonb_build_object('receiptId',p_input->>'receiptId','materialId',p_input->>'materialId');
  elsif p_action='record-credit' then
    if v_member.role not in ('admin','billing_commercial_lead') or coalesce(p_input->>'supplierCreditReference','')=''
      or coalesce(p_input->>'reason','')='' then raise exception 'finance_credit_source_required' using errcode='42501'; end if;
    select value into v_invoice from jsonb_array_elements(v_state->'supplierInvoices') where value->>'id'=p_input->>'invoiceId';
    select coalesce(sum((c->>'amountMinor')::bigint),0) into v_total from jsonb_array_elements(coalesce(v_state->'credits','[]'::jsonb)) c
      where c->>'invoiceId'=p_input->>'invoiceId';
    if v_invoice is null or coalesce(p_input->>'amountMinor','') !~ '^\d+$'
      or (p_input->>'amountMinor')::bigint<=0 or v_total+(p_input->>'amountMinor')::bigint>(v_invoice->>'totalMinor')::bigint then
      raise exception 'credit_exceeds_supplier_invoice' using errcode='23514'; end if;
    v_item:=p_input||jsonb_build_object('id',gen_random_uuid(),'at',v_now,'actorId',v_actor,'currency','USD');
    v_state:=jsonb_set(v_state,'{credits}',coalesce(v_state->'credits','[]'::jsonb)||jsonb_build_array(v_item));
    v_source:=jsonb_build_object('invoiceId',p_input->>'invoiceId','supplierCreditReference',p_input->>'supplierCreditReference');
  elsif p_action='record-supplier-invoice' then
    if v_member.role not in ('admin','billing_commercial_lead') or coalesce(p_input->>'invoiceNumber','')=''
      or p_input->>'currency'<>'USD' or jsonb_typeof(p_input->'lines')<>'array'
      or jsonb_array_length(p_input->'lines')=0
      or exists(select 1 from jsonb_array_elements(v_state->'supplierInvoices') where value->>'invoiceNumber'=p_input->>'invoiceNumber') then
      raise exception 'supplier_invoice_invalid' using errcode='23514'; end if;
    v_doc:=(p_input->>'documentId')::uuid;
    if not exists(select 1 from d5o_hosted.graybar_documents where workspace_id=v_workspace.id and work_id=v_work.id and id=v_doc and kind='supplier_invoice') then
      raise exception 'retained_supplier_invoice_required' using errcode='23514'; end if;
    select value into v_order from jsonb_array_elements(v_state->'orders') where value->>'id'=p_input->>'orderId' and value->>'status'='Acknowledged';
    if v_order is null then raise exception 'acknowledged_order_required' using errcode='23514'; end if;
    v_sum:=0;v_total:=0;
    if exists(select 1 from (select l->>'materialId' id,count(*) c from jsonb_array_elements(p_input->'lines') l group by l->>'materialId') x
      where x.id is null or x.c>1) then raise exception 'duplicate_invoice_allocation' using errcode='23514'; end if;
    for v_line in select value from jsonb_array_elements(p_input->'lines') loop
      select value into v_item from jsonb_array_elements(v_order->'lines') where value->>'materialId'=v_line->>'materialId';
      select coalesce(sum((rline->>'acceptedQuantity')::numeric),0) into v_quantity
        from jsonb_array_elements(v_state->'receipts') r,jsonb_array_elements(r->'lines') rline,
          jsonb_array_elements(v_state->'shipments') s
        where r->>'shipmentId'=s->>'id' and s->>'orderId'=p_input->>'orderId'
          and rline->>'materialId'=v_line->>'materialId';
      select v_quantity-coalesce(sum((iline->>'quantity')::numeric),0) into v_quantity
        from jsonb_array_elements(v_state->'supplierInvoices') prior,jsonb_array_elements(prior->'lines') iline
        where prior->>'orderId'=p_input->>'orderId' and prior->>'status'<>'Hold'
          and iline->>'materialId'=v_line->>'materialId';
      if v_item is null or coalesce(v_line->>'quantity','') !~ '^\d+(\.\d{1,3})?$'
        or coalesce(v_line->>'amountMinor','') !~ '^\d+$' or (v_line->>'quantity')::numeric>v_quantity
        or (v_line->>'quantity')::numeric<=0 then raise exception 'invoice_exceeds_accepted_receipt' using errcode='23514'; end if;
      v_sum:=v_sum+(v_line->>'amountMinor')::bigint;
      v_total:=v_total+round((v_line->>'quantity')::numeric/(v_item->>'packSize')::numeric*(v_item->>'unitPriceMinor')::bigint)::bigint;
    end loop;
    if coalesce(p_input->>'totalMinor','') !~ '^\d+$' or v_sum<=0 or v_sum<>(p_input->>'totalMinor')::bigint then
      raise exception 'supplier_invoice_total_mismatch' using errcode='23514'; end if;
    v_invoice:=p_input||jsonb_build_object('id',gen_random_uuid(),'status',
      case when v_sum<>v_total then 'Exception' else 'Review' end,
      'recordedAt',v_now,'recordedBy',v_actor,'poAmountMinor',v_order->>'amountMinor');
    v_state:=jsonb_set(v_state,'{supplierInvoices}',v_state->'supplierInvoices'||jsonb_build_array(v_invoice));
    v_source:=jsonb_build_object('orderId',v_order->>'id','documentId',v_doc);
  elsif p_action='review-supplier-invoice' then
    if v_member.role not in ('admin','billing_commercial_lead') then raise exception 'finance_authority_required' using errcode='42501'; end if;
    select value into v_invoice from jsonb_array_elements(v_state->'supplierInvoices') where value->>'id'=p_input->>'invoiceId';
    if v_invoice is null or v_invoice->>'recordedBy'=v_actor::text or v_invoice->>'status' not in ('Review','Exception')
      or p_input->>'decision' not in ('Matched','Hold') or p_input->>'decision'='Matched' and v_invoice->>'status'='Exception'
      or coalesce(p_input->>'reason','')='' then raise exception 'independent_invoice_review_required' using errcode='23514'; end if;
    v_invoice:=v_invoice||jsonb_build_object('status',p_input->>'decision','reviewedBy',v_actor,'reviewedAt',v_now,'reason',p_input->>'reason');
    v_state:=jsonb_set(v_state,'{supplierInvoices}',(select jsonb_agg(case when value->>'id'=p_input->>'invoiceId' then v_invoice else value end)
      from jsonb_array_elements(v_state->'supplierInvoices')));
    v_source:=jsonb_build_object('invoiceId',v_invoice->>'id','orderId',v_invoice->>'orderId');
  elsif p_action='handoff-installed' then
    if v_member.role not in ('admin','operations_leader') or coalesce(p_input->>'assetId','')=''
      or coalesce(p_input->>'serialNumber','')='' or coalesce(p_input->>'materialId','')='' then
      raise exception 'installed_equipment_basis_required' using errcode='23514'; end if;
    if not exists(select 1 from d5o_hosted.connected_operate_states o,jsonb_array_elements(coalesce(o.state->'assets','[]'::jsonb)) a
      where o.workspace_id=v_workspace.id and o.work_id=v_work.id and a->>'id'=p_input->>'assetId') then
      raise exception 'supported_asset_required' using errcode='23514'; end if;
    select coalesce(sum((rline->>'acceptedQuantity')::numeric),0) into v_quantity
      from jsonb_array_elements(v_state->'receipts') r,jsonb_array_elements(r->'lines') rline
      where rline->>'materialId'=p_input->>'materialId';
    select v_quantity-coalesce(sum((returned->>'quantity')::numeric),0) into v_quantity
      from jsonb_array_elements(coalesce(v_state->'returns','[]'::jsonb)) returned
      where returned->>'materialId'=p_input->>'materialId';
    if v_quantity<1 or exists(select 1 from jsonb_array_elements(v_state->'installed') i where i->>'serialNumber'=p_input->>'serialNumber') then
      raise exception 'received_unique_equipment_required' using errcode='23514'; end if;
    select * into v_operate from d5o_hosted.connected_operate_states
      where workspace_id=v_workspace.id and work_id=v_work.id for update;
    select value into v_asset from jsonb_array_elements(coalesce(v_operate.state->'assets','[]'::jsonb))
      where value->>'id'=p_input->>'assetId' and value->>'status'='Supported';
    select value into v_receipt_item from jsonb_array_elements(v_state->'receipts')
      where value->>'id'=p_input->>'receiptId';
    if v_asset is null or v_receipt_item is null or not exists(select 1 from jsonb_array_elements(v_receipt_item->'lines') l
      where l->>'materialId'=p_input->>'materialId' and (l->>'acceptedQuantity')::numeric>0) then
      raise exception 'supported_asset_and_received_equipment_required' using errcode='23514'; end if;
    select count(*) into v_count from jsonb_array_elements(v_state->'installed') i
      where i->>'materialId'=p_input->>'materialId';
    if v_count>=v_quantity then raise exception 'equipment_allocation_exceeds_receipt' using errcode='23514'; end if;
    v_item:=p_input||jsonb_build_object('id',gen_random_uuid(),'at',v_now,'actorId',v_actor,'source','Graybar procurement receipt');
    v_state:=jsonb_set(v_state,'{installed}',v_state->'installed'||jsonb_build_array(v_item));
    v_asset:=jsonb_set(v_asset,'{history}',coalesce(v_asset->'history','[]'::jsonb)||jsonb_build_array(
      jsonb_build_object('at',v_now,'action','Installed equipment handoff',
        'source','Graybar receipt '||(p_input->>'receiptId')||' / serial '||(p_input->>'serialNumber'),
        'actorId',v_actor,'procurementEventId',v_item->>'id','warrantyReference',p_input->>'warrantyReference')));
    v_operate_state:=jsonb_set(v_operate.state,'{assets}',(
      select jsonb_agg(case when a->>'id'=p_input->>'assetId' then v_asset else a end order by ordinal)
      from jsonb_array_elements(v_operate.state->'assets') with ordinality entries(a,ordinal)));
    v_operate_state:=v_operate_state||jsonb_build_object('authorityRevision',v_operate.decision_revision+1,
      'events',coalesce(v_operate_state->'events','[]'::jsonb)||jsonb_build_array(jsonb_build_object(
        'id',gen_random_uuid(),'commandId',p_command_id,'fingerprint',v_fingerprint,
        'at',v_now,'actorId',v_actor,'membershipId',v_member.id,'action','installed-equipment-handoff',
        'detail',p_input->>'serialNumber')));
    update d5o_hosted.connected_operate_states set decision_revision=decision_revision+1,
      state=v_operate_state,updated_at=v_now where workspace_id=v_workspace.id and work_id=v_work.id;
    select coalesce(decision_revision,0) into v_deploy_revision from d5o_hosted.connected_deploy_states
      where workspace_id=v_workspace.id and work_id=v_work.id;
    insert into d5o_hosted.connected_operate_events(workspace_id,work_id,decision_revision,command_id,
      action,actor_user_id,membership_id,deploy_revision,snapshot)
      values(v_workspace.id,v_work.id,v_operate.decision_revision+1,p_command_id,
        'installed-equipment-handoff',v_actor,v_member.id,coalesce(v_deploy_revision,0),v_operate_state);
    insert into d5o_hosted.connected_operate_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
      values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_operate_state);
    v_source:=jsonb_build_object('assetId',p_input->>'assetId','materialId',p_input->>'materialId');
  end if;
  v_revision:=coalesce(v_current.revision,0)+1;
  if v_current.work_id is null then
    insert into d5o_hosted.graybar_states(workspace_id,work_id,revision,state) values(v_workspace.id,v_work.id,v_revision,v_state);
  else update d5o_hosted.graybar_states set revision=v_revision,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id; end if;
  insert into d5o_hosted.graybar_events(workspace_id,work_id,revision,command_id,action,actor_user_id,membership_id,source,state)
    values(v_workspace.id,v_work.id,v_revision,p_command_id,p_action,v_actor,v_member.id,v_source,v_state);
  v_result:=public.d5o_graybar_read_v1(p_workspace_key,p_presentation_id);
  insert into d5o_hosted.graybar_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
    values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_document_v1(p_workspace_key text, p_presentation_id text, p_document_id uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_work uuid;v_document d5o_hosted.graybar_documents%rowtype;
begin
  if current_setting('role',true)<>'service_role' or p_actor is null then raise exception 'document_scope_forbidden' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  select work_id into v_work from d5o_hosted.work_identity_links where workspace_id=v_workspace and presentation_id=p_presentation_id;
  if v_work is null or not exists(select 1 from d5o_hosted.memberships where workspace_id=v_workspace and actor_user_id=p_actor and status='active' and role<>'field_worker') then
    raise exception 'document_scope_forbidden' using errcode='42501'; end if;
  select * into v_document from d5o_hosted.graybar_documents where workspace_id=v_workspace and work_id=v_work and id=p_document_id;
  if not found then raise exception 'document_missing' using errcode='23514'; end if;
  return jsonb_build_object('id',v_document.id,'kind',v_document.kind,'filename',v_document.filename,
    'mediaType',v_document.media_type,'storagePath',v_document.storage_path,'sha256',v_document.sha256,
    'byteCount',v_document.byte_count,'uploadedBy',v_document.uploaded_by,'uploadedAt',v_document.uploaded_at);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_job_cost_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_role text;v_row record;v_order jsonb;v_invoice jsonb;
  v_actions jsonb:='[]'::jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  select role into v_role from d5o_hosted.memberships where workspace_id=v_workspace and actor_user_id=v_actor and status='active';
  if v_role is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  if v_role<>'billing_commercial_lead' then return v_actions; end if;
  for v_row in select s.workspace_id,s.work_id,s.revision,s.state,l.presentation_id,w.title
    from d5o_hosted.graybar_states s join d5o_hosted.work_identity_links l
      on l.workspace_id=s.workspace_id and l.work_id=s.work_id
    join d5o_hosted.work_records w on w.workspace_id=s.workspace_id and w.id=s.work_id
    where s.workspace_id=v_workspace loop
    if d5o_hosted.job_finance_award_v1(v_workspace,v_row.work_id) is null or exists(
      select 1 from d5o_hosted.connected_operate_states o where o.workspace_id=v_workspace
        and o.work_id=v_row.work_id and o.state#>>'{finance,status}'='Closed') then continue; end if;
    for v_order in select value from jsonb_array_elements(v_row.state->'orders') loop
      if v_order->>'status' in ('Approved','Test submitted','Acknowledged')
        and not exists(select 1 from d5o_hosted.graybar_job_cost_links c where c.workspace_id=v_workspace
          and c.work_id=v_row.work_id and c.order_id=v_order->>'id' and c.kind='Committed') then
        v_actions:=v_actions||jsonb_build_array(jsonb_build_object('kind','Record Graybar purchase commitment',
          'phase','Procurement','focus','cost-po','workId',v_row.presentation_id,'revision',v_row.revision,
          'decisionId',v_order->>'id','title',v_row.title,'ownership','Finance',
          'blocker','Post the approved PO source to the fixed-price job ledger; no supplier payment is implied.'));
      end if;
    end loop;
    for v_invoice in select value from jsonb_array_elements(v_row.state->'supplierInvoices') loop
      if v_invoice->>'status'='Matched' and exists(select 1 from d5o_hosted.graybar_job_cost_links c
        where c.workspace_id=v_workspace and c.work_id=v_row.work_id and c.order_id=v_invoice->>'orderId' and c.kind='Committed')
        and not exists(select 1 from d5o_hosted.graybar_job_cost_links c where c.workspace_id=v_workspace
          and c.work_id=v_row.work_id and c.invoice_id=v_invoice->>'id' and c.kind='Incurred') then
        v_actions:=v_actions||jsonb_build_array(jsonb_build_object('kind','Reconcile Graybar supplier cost',
          'phase','Procurement','focus','cost-invoice','workId',v_row.presentation_id,'revision',v_row.revision,
          'decisionId',v_invoice->>'id','title',v_row.title,'ownership','Finance',
          'blocker','Match the retained supplier invoice to the exact posted PO commitment.'));
      end if;
    end loop;
  end loop;
  return v_actions;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_job_cost_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_graybar_revision integer, p_finance_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;v_member d5o_hosted.memberships%rowtype;
  v_work d5o_hosted.work_records%rowtype;v_proc d5o_hosted.graybar_states%rowtype;
  v_finance d5o_hosted.connected_job_finance_states%rowtype;v_receipt d5o_hosted.graybar_job_cost_receipts%rowtype;
  v_order jsonb;v_invoice jsonb;v_line jsonb;v_commit d5o_hosted.connected_job_costs%rowtype;
  v_fingerprint text;v_ids jsonb:='[]'::jsonb;v_cost_id uuid;v_amount bigint;v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null or p_action not in ('post-commitment','post-matched-invoice')
    or jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_graybar_revision is null or p_finance_revision is null then
    raise exception 'invalid_supplier_cost_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  select * into v_member from d5o_hosted.memberships where workspace_id=v_workspace.id and actor_user_id=v_actor
    and status='active' for share;
  select w.* into v_work from d5o_hosted.work_records w join d5o_hosted.work_identity_links l
    on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id for update of w;
  if v_member.id is null or v_member.role<>'billing_commercial_lead' or v_work.id is null then
    raise exception 'supplier_cost_finance_role_required' using errcode='42501'; end if;
  if exists(select 1 from d5o_hosted.connected_operate_states o where o.workspace_id=v_workspace.id
    and o.work_id=v_work.id and o.state#>>'{finance,status}'='Closed') then
    raise exception 'finance_closed_requires_reopen' using errcode='23514'; end if;
  if d5o_hosted.job_finance_award_v1(v_workspace.id,v_work.id) is null then
    raise exception 'awarded_job_cost_basis_required' using errcode='23514'; end if;
  insert into d5o_hosted.connected_job_finance_states(workspace_id,work_id,currency)
    values(v_workspace.id,v_work.id,'USD') on conflict do nothing;
  select * into v_proc from d5o_hosted.graybar_states where workspace_id=v_workspace.id and work_id=v_work.id for update;
  select * into v_finance from d5o_hosted.connected_job_finance_states where workspace_id=v_workspace.id and work_id=v_work.id for update;
  v_fingerprint:=md5(jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,p_graybar_revision,p_finance_revision)::text);
  select * into v_receipt from d5o_hosted.graybar_job_cost_receipts where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  if v_proc.revision is distinct from p_graybar_revision or v_finance.revision<>p_finance_revision then
    raise exception 'stale_supplier_cost_basis' using errcode='23505'; end if;
  select value into v_order from jsonb_array_elements(v_proc.state->'orders')
    where value->>'id'=p_input->>'orderId' and value->>'status' in ('Approved','Test submitted','Acknowledged');
  if v_order is null or v_order->>'currency'<>'USD' or v_order->>'bomId'<>v_proc.state#>>'{bom,id}' then
    raise exception 'current_approved_purchase_order_required' using errcode='23514'; end if;
  if p_action='post-commitment' then
    if exists(select 1 from d5o_hosted.graybar_job_cost_links where workspace_id=v_workspace.id and work_id=v_work.id
      and order_id=p_input->>'orderId' and kind='Committed') then
      raise exception 'purchase_commitment_already_posted' using errcode='23505'; end if;
    for v_line in select value from jsonb_array_elements(v_order->'lines') loop
      v_amount:=round((v_line->>'quantity')::numeric/(v_line->>'packSize')::numeric*(v_line->>'unitPriceMinor')::bigint)::bigint;
      if v_amount<=0 or v_amount>1000000000000 then raise exception 'unsupported_purchase_cost' using errcode='23514'; end if;
      insert into d5o_hosted.connected_job_costs(workspace_id,work_id,package_id,kind,category,amount_minor,cost_date,source,recorded_by)
        values(v_workspace.id,v_work.id,(select b->>'packageId' from jsonb_array_elements(v_proc.state#>'{bom,lines}') b
          where b->>'materialId'=v_line->>'materialId'),'Committed','Material',v_amount,current_date,
          'Graybar PO '||(v_order->>'id')||' material '||(v_line->>'materialId'),v_actor) returning id into v_cost_id;
      insert into d5o_hosted.graybar_job_cost_links(workspace_id,work_id,order_id,material_id,kind,cost_id,recorded_by)
        values(v_workspace.id,v_work.id,v_order->>'id',v_line->>'materialId','Committed',v_cost_id,v_actor);
      v_ids:=v_ids||jsonb_build_array(v_cost_id);
    end loop;
  else
    select value into v_invoice from jsonb_array_elements(v_proc.state->'supplierInvoices')
      where value->>'id'=p_input->>'invoiceId' and value->>'orderId'=v_order->>'id' and value->>'status'='Matched';
    if v_invoice is null then raise exception 'matched_supplier_invoice_required' using errcode='23514'; end if;
    if exists(select 1 from d5o_hosted.graybar_job_cost_links where workspace_id=v_workspace.id and work_id=v_work.id
      and invoice_id=p_input->>'invoiceId' and kind='Incurred') then
      raise exception 'supplier_invoice_cost_already_posted' using errcode='23505'; end if;
    for v_line in select value from jsonb_array_elements(v_invoice->'lines') loop
      select c.* into v_commit from d5o_hosted.graybar_job_cost_links l join d5o_hosted.connected_job_costs c on c.id=l.cost_id
        where l.workspace_id=v_workspace.id and l.work_id=v_work.id and l.order_id=v_order->>'id'
          and l.material_id=v_line->>'materialId' and l.kind='Committed' for update of c;
      v_amount:=(v_line->>'amountMinor')::bigint;
      if v_commit.id is null or v_amount<=0 or v_amount>v_commit.amount_minor-
        coalesce((select sum(c.amount_minor) from d5o_hosted.connected_job_costs c where c.reconciles_id=v_commit.id),0) then
        raise exception 'supplier_invoice_commitment_reconciliation_invalid' using errcode='23514'; end if;
      insert into d5o_hosted.connected_job_costs(workspace_id,work_id,package_id,kind,category,amount_minor,cost_date,source,reconciles_id,recorded_by)
        values(v_workspace.id,v_work.id,v_commit.package_id,'Incurred','Material',v_amount,current_date,
          'Graybar invoice '||(v_invoice->>'id')||' material '||(v_line->>'materialId'),v_commit.id,v_actor)
        returning id into v_cost_id;
      insert into d5o_hosted.graybar_job_cost_links(workspace_id,work_id,order_id,invoice_id,material_id,kind,cost_id,recorded_by)
        values(v_workspace.id,v_work.id,v_order->>'id',v_invoice->>'id',v_line->>'materialId','Incurred',v_cost_id,v_actor);
      v_ids:=v_ids||jsonb_build_array(v_cost_id);
    end loop;
  end if;
  update d5o_hosted.connected_job_finance_states set revision=revision+1 where workspace_id=v_workspace.id and work_id=v_work.id;
  v_result:=jsonb_build_object('action',p_action,'financeRevision',v_finance.revision+1,'graybarRevision',v_proc.revision,'costIds',v_ids);
  insert into d5o_hosted.connected_job_finance_events(workspace_id,work_id,revision,command_id,actor_user_id,membership_id,action,result)
    values(v_workspace.id,v_work.id,v_finance.revision+1,p_command_id,v_actor,v_member.id,p_action,v_result);
  insert into d5o_hosted.graybar_job_cost_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
    values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_job_cost_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_work uuid;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then raise exception 'finance_scope_denied' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  if not exists(select 1 from d5o_hosted.memberships where workspace_id=v_workspace and actor_user_id=v_actor and status='active'
      and role in ('admin','project_manager','billing_commercial_lead')) then raise exception 'finance_scope_denied' using errcode='42501'; end if;
  select l.work_id into v_work from d5o_hosted.work_identity_links l where l.workspace_id=v_workspace and l.presentation_id=p_presentation_id;
  if v_work is null then raise exception 'finance_scope_denied' using errcode='42501'; end if;
  return jsonb_build_object('financeRevision',coalesce((select revision from d5o_hosted.connected_job_finance_states
      where workspace_id=v_workspace and work_id=v_work),0),
    'links',coalesce((select jsonb_agg(jsonb_build_object('orderId',l.order_id,'invoiceId',l.invoice_id,
      'materialId',l.material_id,'kind',l.kind,'costId',l.cost_id,'amountMinor',c.amount_minor,'source',c.source)
      order by l.recorded_at,l.cost_id) from d5o_hosted.graybar_job_cost_links l
      join d5o_hosted.connected_job_costs c on c.id=l.cost_id
      where l.workspace_id=v_workspace and l.work_id=v_work),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_work uuid;v_state d5o_hosted.graybar_states%rowtype;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  if not exists(select 1 from d5o_hosted.memberships where workspace_id=v_workspace and actor_user_id=v_actor and status='active' and role<>'field_worker') then
    raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select work_id into v_work from d5o_hosted.work_identity_links where workspace_id=v_workspace and presentation_id=p_presentation_id;
  if v_work is null then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  select * into v_state from d5o_hosted.graybar_states where workspace_id=v_workspace and work_id=v_work;
  return jsonb_build_object('revision',coalesce(v_state.revision,0),
    'state',coalesce(v_state.state,'{"quotes":[],"assessments":[],"bom":null,"orders":[],"shipments":[],"receipts":[],"supplierInvoices":[],"returns":[],"credits":[],"installed":[]}'::jsonb),
    'documents',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'kind',d.kind,'filename',d.filename,'sha256',d.sha256,'byteCount',d.byte_count,'uploadedAt',d.uploaded_at,'uploadedBy',d.uploaded_by) order by d.uploaded_at)
      from d5o_hosted.graybar_documents d where d.workspace_id=v_workspace and d.work_id=v_work),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_graybar_register_document_v1(p_workspace_key text, p_presentation_id text, p_kind text, p_filename text, p_media_type text, p_storage_path text, p_sha256 text, p_byte_count bigint, p_actor uuid, p_extraction jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_work uuid;v_id uuid;
begin
  if current_setting('role',true)<>'service_role' or p_actor is null or p_kind not in ('quote','specification','acknowledgment','delivery','supplier_invoice','other')
    or p_sha256 !~ '^[0-9a-f]{64}$' or p_byte_count<1 or p_byte_count>20000000
    or length(trim(p_filename)) not between 1 and 240 or length(trim(p_storage_path)) not between 10 and 600
    or jsonb_typeof(p_extraction)<>'object' or length(coalesce(p_extraction->>'method',''))<8 then
    raise exception 'document_registration_forbidden' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  select work_id into v_work from d5o_hosted.work_identity_links where workspace_id=v_workspace and presentation_id=p_presentation_id;
  if v_work is null or not exists(select 1 from d5o_hosted.memberships where workspace_id=v_workspace and actor_user_id=p_actor and status='active'
    and role in ('admin','project_manager','operations_leader','billing_commercial_lead')) then
    raise exception 'document_registration_forbidden' using errcode='42501'; end if;
  insert into d5o_hosted.graybar_documents(workspace_id,work_id,kind,filename,media_type,storage_path,sha256,byte_count,uploaded_by)
    values(v_workspace,v_work,p_kind,p_filename,p_media_type,p_storage_path,p_sha256,p_byte_count,p_actor) returning id into v_id;
  insert into d5o_hosted.graybar_document_extractions(document_id,version,extraction)
    values(v_id,1,p_extraction);
  return v_id;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_accept_supported_asset_v1(p_workspace_key text, p_parent_presentation_id text, p_asset_id text, p_documentation_source text, p_reason text, p_command_id text, p_expected_source_revision bigint, p_expected_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_parent d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_receipt d5o_hosted.connected_operate_receipts%rowtype;
  v_asset jsonb;v_state jsonb;v_fingerprint text;v_result jsonb;v_now timestamptz:=now();
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or length(trim(coalesce(p_documentation_source,'')))<10
    or length(trim(coalesce(p_reason,'')))<10
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_operate_revision is null then
    raise exception 'invalid_asset_acceptance' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role<>'operations_leader' then
    raise exception 'operations_asset_authority_required' using errcode='42501'; end if;
  select w.* into v_parent from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_parent_presentation_id
      and l.parent_work_id is null for update of w;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_parent_presentation_id,p_asset_id,
    trim(p_documentation_source),trim(p_reason),p_expected_source_revision,
    p_expected_operate_revision)::text);
  select * into v_receipt from d5o_hosted.connected_operate_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.work_id<>v_parent.id
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_parent.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision then
    raise exception 'stale_asset_acceptance_basis' using errcode='23505'; end if;
  if v_operate.state#>>'{activation,status}'<>'Active'
    or v_operate.state->'support' is null
    or v_operate.state->'source' is null then
    raise exception 'active_support_basis_required' using errcode='23514'; end if;
  select item into v_asset from pg_catalog.jsonb_array_elements(v_operate.state->'assets') item
    where item->>'id'=p_asset_id;
  if v_asset is null or v_asset->>'status'<>'Pending'
    or v_asset->>'sourceTurnoverId' is distinct from
      v_operate.state#>>'{source,workAcceptanceId}'
    or nullif(trim(coalesce(v_asset->>'location','')),'') is null then
    raise exception 'pending_asset_source_required' using errcode='23514'; end if;
  v_asset:=v_asset||pg_catalog.jsonb_build_object('status','Supported',
    'acceptedAt',v_now,'acceptedByActorId',v_actor,
    'acceptanceSource',trim(p_documentation_source),
    'history',coalesce(v_asset->'history','[]'::jsonb)||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('at',v_now,'action','Support accepted',
        'source',trim(p_documentation_source),'actorId',v_actor,'reason',trim(p_reason))));
  v_state:=pg_catalog.jsonb_set(v_operate.state,'{assets}',
    (select pg_catalog.jsonb_agg(case when item->>'id'=p_asset_id then v_asset
      else item end order by ordinal) from pg_catalog.jsonb_array_elements(v_operate.state->'assets')
      with ordinality as entries(item,ordinal)));
  v_state:=v_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_operate.decision_revision+1,
    'events',v_operate.state->'events'||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'commandId',p_command_id,'fingerprint',v_fingerprint,'at',v_now,
        'actorId',v_actor,'membershipId',v_member.id,
        'action','accept-asset','detail',p_asset_id)));
  update d5o_hosted.connected_operate_states set decision_revision=decision_revision+1,
    state=v_state,updated_at=v_now where workspace_id=v_workspace.id and work_id=v_parent.id;
  insert into d5o_hosted.connected_operate_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    deploy_revision,snapshot)
  values(v_workspace.id,v_parent.id,v_operate.decision_revision+1,p_command_id,
    'accept-asset',v_actor,v_member.id,
    (select decision_revision from d5o_hosted.connected_deploy_states
      where workspace_id=v_workspace.id and work_id=v_parent.id),v_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_operate_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_parent.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_acceptance_command_v1(p_workspace_key text, p_presentation_id text, p_package_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_design_revision integer, p_expected_deploy_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_receipt d5o_hosted.connected_deploy_receipts%rowtype;
  v_state jsonb;v_release jsonb;v_turnover jsonb;v_acceptance jsonb;v_evidence jsonb;v_receiving_role text;
  v_item jsonb;v_requirement text;v_package text;v_current jsonb;
  v_all_turnovers jsonb:='[]'::jsonb;v_release_ids jsonb:='[]'::jsonb;
  v_now timestamptz:=now();v_fingerprint text;v_result jsonb;
  v_note text:=trim(coalesce(p_input->>'note',''));
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('assemble-turnover','accept-client','accept-work',
      'respond-operate','respond-operate-work')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_design_revision is null or p_expected_design_revision<1
    or p_expected_deploy_revision is null or p_expected_deploy_revision<1 then
    raise exception 'invalid_acceptance_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'acceptance_membership_required' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id
      and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
      for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_package_id,p_action,p_input,p_expected_source_revision,
    p_expected_design_revision,p_expected_deploy_revision)::text);
  select * into v_receipt from d5o_hosted.connected_deploy_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_schedule from d5o_hosted.connected_schedule_states
    where workspace_id=v_workspace.id for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_design_revision
    or v_deploy.decision_revision is distinct from p_expected_deploy_revision then
    raise exception 'stale_acceptance_basis' using errcode='23505'; end if;
  v_state:=v_deploy.state;
  if p_action in ('assemble-turnover','accept-client','respond-operate') then
    select r into v_release from pg_catalog.jsonb_array_elements(v_design.state->'releases') r
      where r->>'packageId'=p_package_id order by r->>'issuedAt' desc limit 1;
    if v_release is null or v_release->>'status'<>'Accepted'
      or (v_release->>'packageRevision')::integer<>
        (select (p->>'revision')::integer from pg_catalog.jsonb_array_elements(
          v_design.state->'packages') p where p->>'packageId'=p_package_id) then
      raise exception 'current_accepted_release_required' using errcode='23514'; end if;
  end if;
  if p_action='assemble-turnover' then
    if v_member.role not in ('project_manager','field_supervisor')
      or p_input ? 'operateOwner' then
      raise exception 'turnover_assembly_authority_required' using errcode='42501'; end if;
    if not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'completions') c
      where c->>'packageId'=p_package_id and c->>'releaseId'=v_release->>'id'
        and c->>'status'='Reviewed') then
      raise exception 'reviewed_completion_required' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'issues') i
      where i->>'packageId'=p_package_id and i->>'status'='Open') then
      raise exception 'open_issue_blocks_turnover' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'turnovers') t
      where t->'releaseIds' ? (v_release->>'id') and t->>'status' in
        ('Draft','Client accepted','Conditionally accepted')) then
      raise exception 'current_turnover_already_exists' using errcode='23514'; end if;
    v_receiving_role:=d5o_hosted.configured_handoff_role_v1(v_work.configuration_version_id,'deployOperate');
    if not exists(select 1 from d5o_hosted.memberships m
      where m.workspace_id=v_workspace.id and m.status='active'
        and m.role=v_receiving_role and m.actor_user_id<>v_actor) then
      raise exception 'configured_receiver_unavailable' using errcode='23514'; end if;
    v_turnover:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),
      'revision',1,'releaseIds',pg_catalog.jsonb_build_array(v_release->>'id'),
      'packageId',p_package_id,'reportIds',
        (select pg_catalog.jsonb_agg(r->>'id') from pg_catalog.jsonb_array_elements(v_state->'reports') r
          where r->>'packageId'=p_package_id and r->>'releaseId'=v_release->>'id'
            and r->>'status'='Reviewed'),
      'inspectionIds',
        (select pg_catalog.jsonb_agg(i->>'id') from pg_catalog.jsonb_array_elements(v_state->'inspections') i
          where i->>'packageId'=p_package_id and i->>'releaseId'=v_release->>'id'
            and i->>'status'='Verified' and i->>'result'='Pass'),
      'evidenceIds',
        (select pg_catalog.jsonb_agg(e->>'id') from pg_catalog.jsonb_array_elements(v_state->'evidence') e
          where e->>'packageId'=p_package_id and e->>'releaseId'=v_release->>'id'
            and e->>'state'='Reviewed'),
      'completionId',(select c->>'id' from pg_catalog.jsonb_array_elements(v_state->'completions') c
        where c->>'packageId'=p_package_id and c->>'releaseId'=v_release->>'id'
          and c->>'status'='Reviewed'
        order by (c->>'reviewedAt')::timestamptz desc limit 1),
      'assembledAt',v_now,'assembledByActorId',v_actor,
      'membershipId',v_member.id,'status','Draft',
      'operateOwner','Configured '||v_receiving_role||' queue',
      'operateRole',v_receiving_role,
      'obligations',trim(coalesce(p_input->>'obligations','')),'receipt','Awaiting');
    v_state:=pg_catalog.jsonb_set(v_state,'{turnovers}',
      v_state->'turnovers'||pg_catalog.jsonb_build_array(v_turnover));
  elsif p_action='accept-client' then
    if v_member.role not in ('project_manager','operations_leader')
      or length(trim(coalesce(p_input->>'signerName','')))<3
      or length(trim(coalesce(p_input->>'signerOrganization','')))<3
      or length(trim(coalesce(p_input->>'authorityBasis','')))<10
      or length(trim(coalesce(p_input->>'signerRole','')))<3
      or p_input->>'evidenceId' is null then
      raise exception 'customer_acceptance_recording_incomplete' using errcode='42501'; end if;
    select t into v_turnover from pg_catalog.jsonb_array_elements(v_state->'turnovers') t
      where t->>'id'=p_input->>'turnoverId' and t->>'status'='Draft'
        and t->'releaseIds' ? (v_release->>'id');
    if v_turnover is null or v_turnover->>'assembledByActorId'=v_actor::text
      or not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'completions') c
        where c->>'id'=v_turnover->>'completionId' and c->>'status'='Reviewed') then
      raise exception 'independent_current_turnover_required' using errcode='42501'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(
      v_release#>'{snapshot,requirementIds}') loop
      v_requirement:=v_item#>>'{}';
      if not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'inspections') i
        where i->>'id' in (select pg_catalog.jsonb_array_elements_text(v_turnover->'inspectionIds'))
          and i->>'requirementId'=v_requirement and i->>'result'='Pass'
          and i->>'status'='Verified' and i->>'releaseId'=v_release->>'id') then
        raise exception 'turnover_verification_incomplete' using errcode='23514'; end if;
    end loop;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'issues') i
      where i->>'packageId'=p_package_id and i->>'status'='Open') then
      raise exception 'open_issue_blocks_acceptance' using errcode='23514'; end if;
    v_evidence:=d5o_hosted.require_customer_decision_evidence_v1(
      v_workspace.id,v_work.id,p_input->>'evidenceId','package-acceptance',
      v_turnover->>'id',(v_turnover->>'revision')::integer,
      pg_catalog.jsonb_build_object('releaseIds',v_turnover->'releaseIds',
        'designRevision',v_design.decision_revision));
    v_turnover:=v_turnover||pg_catalog.jsonb_build_object(
      'status',case when trim(coalesce(p_input->>'conditions',''))=''
        then 'Client accepted' else 'Conditionally accepted' end,
      'acceptedAt',v_now,'recordedByActorId',v_actor,'signerName',trim(p_input->>'signerName'),
      'signerOrganization',trim(p_input->>'signerOrganization'),
      'signerRole',trim(p_input->>'signerRole'),
      'authorityBasis',trim(p_input->>'authorityBasis'),
      'source','evidence:'||(v_evidence->>'id'),'customerEvidence',v_evidence,
      'conditions',trim(coalesce(p_input->>'conditions','')),
      'exclusions',trim(coalesce(p_input->>'exclusions','')));
    v_state:=pg_catalog.jsonb_set(v_state,'{turnovers}',
      (select pg_catalog.jsonb_agg(case when t->>'id'=v_turnover->>'id' then v_turnover
        else t end order by ordinal) from pg_catalog.jsonb_array_elements(v_state->'turnovers')
          with ordinality as entries(t,ordinal)));
    v_state:=pg_catalog.jsonb_set(v_state,'{signoffs}',v_state->'signoffs'||
      pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'kind','Customer scope acceptance','recordId',v_turnover->>'id',
        'recordRevision',1,'releaseIds',v_turnover->'releaseIds',
        'scope',p_package_id,'statement','Customer acceptance applies only to this exact turnover revision.',
        'signerName',v_turnover->>'signerName',
        'signerOrganization',v_turnover->>'signerOrganization',
        'method','Externally signed document','authorityBasis',v_turnover->>'authorityBasis',
        'source',v_turnover->>'source','capturedByActorId',v_actor,
        'at',v_now,'outcome',case when v_turnover->>'conditions'=''
          then 'Accepted' else 'Conditional' end,
        'conditions',v_turnover->>'conditions','snapshot',v_turnover)));
  elsif p_action='accept-work' then
    if v_member.role not in ('project_manager','operations_leader')
      or v_state->'workAcceptance' is not null
      or length(trim(coalesce(p_input->>'signerName','')))<3
      or length(trim(coalesce(p_input->>'signerOrganization','')))<3
      or length(trim(coalesce(p_input->>'signerRole','')))<3
      or length(trim(coalesce(p_input->>'authorityBasis','')))<10
      or p_input->>'evidenceId' is null
      or trim(coalesce(p_input->>'conditions',''))<>'' then
      raise exception 'whole_work_acceptance_incomplete' using errcode='42501'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_design.state->'packages') loop
      v_package:=v_item->>'packageId';
      select r into v_current from pg_catalog.jsonb_array_elements(v_design.state->'releases') r
        where r->>'packageId'=v_package order by r->>'issuedAt' desc limit 1;
      select t into v_turnover from pg_catalog.jsonb_array_elements(v_state->'turnovers') t
        where t->>'packageId'=v_package and t->>'status'='Client accepted'
          and t->'releaseIds' ? (v_current->>'id');
      if v_current is null or v_current->>'status'<>'Accepted'
        or v_turnover is null or v_turnover->>'assembledByActorId'=v_actor::text
        or not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'completions') c
          where c->>'id'=v_turnover->>'completionId' and c->>'status'='Reviewed') then
        raise exception 'all_current_packages_require_acceptance' using errcode='23514'; end if;
      v_all_turnovers:=v_all_turnovers||pg_catalog.jsonb_build_array(v_turnover->>'id');
      v_release_ids:=v_release_ids||pg_catalog.jsonb_build_array(v_current->>'id');
    end loop;
    if pg_catalog.jsonb_array_length(v_all_turnovers)=0 or
      exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'issues') i
        where i->>'status'='Open') then
      raise exception 'whole_work_scope_incomplete' using errcode='23514'; end if;
    v_evidence:=d5o_hosted.require_customer_decision_evidence_v1(
      v_workspace.id,v_work.id,p_input->>'evidenceId','work-acceptance',
      p_presentation_id,1,pg_catalog.jsonb_build_object(
        'turnoverIds',v_all_turnovers,'releaseIds',v_release_ids,
        'designRevision',v_design.decision_revision));
    v_acceptance:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),
      'revision',1,'turnoverIds',v_all_turnovers,'releaseIds',v_release_ids,
      'acceptedAt',v_now,'recordedByActorId',v_actor,
      'signerName',trim(p_input->>'signerName'),
      'signerOrganization',trim(p_input->>'signerOrganization'),
      'signerRole',trim(p_input->>'signerRole'),
      'authorityBasis',trim(p_input->>'authorityBasis'),
      'source','evidence:'||(v_evidence->>'id'),'customerEvidence',v_evidence,
      'conditions','','receipt','Awaiting',
      'receivingRole',d5o_hosted.configured_handoff_role_v1(v_work.configuration_version_id,'deployOperate'));
    v_state:=pg_catalog.jsonb_set(v_state,'{workAcceptance}',v_acceptance);
    v_state:=pg_catalog.jsonb_set(v_state,'{signoffs}',v_state->'signoffs'||
      pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'kind','Final client acceptance','recordId',v_acceptance->>'id',
        'recordRevision',1,'releaseIds',v_release_ids,'scope',p_presentation_id,
        'statement','Customer accepts the exact listed package turnovers; Operations receipt is separate.',
        'signerName',v_acceptance->>'signerName',
        'signerOrganization',v_acceptance->>'signerOrganization',
        'method','Externally signed document','authorityBasis',v_acceptance->>'authorityBasis',
        'source',v_acceptance->>'source','capturedByActorId',v_actor,
        'at',v_now,'outcome','Accepted','conditions','','snapshot',v_acceptance)));
  elsif p_action='respond-operate' then
    if v_member.role<>d5o_hosted.configured_handoff_role_v1(v_work.configuration_version_id,'deployOperate')
      or p_input->>'decision' not in ('Accepted','Declined') or length(v_note)<15 then
      raise exception 'operations_receipt_authority_required' using errcode='42501'; end if;
    select t into v_turnover from pg_catalog.jsonb_array_elements(v_state->'turnovers') t
      where t->>'id'=p_input->>'turnoverId' and t->>'status'='Client accepted'
        and t->>'receipt'='Awaiting' and t->'releaseIds' ? (v_release->>'id');
    if v_turnover is null or v_turnover->>'recordedByActorId'=v_actor::text
      or v_turnover->>'assembledByActorId'=v_actor::text
      or (v_turnover->>'operateRole' is not null
        and v_member.role is distinct from v_turnover->>'operateRole') then
      raise exception 'independent_exact_turnover_required' using errcode='42501'; end if;
    v_turnover:=v_turnover||pg_catalog.jsonb_build_object('receipt',
      case when p_input->>'decision'='Accepted' then 'Accepted' else 'Returned' end,
      'receivedByActorId',v_actor,'receivedAt',v_now,'receiptNote',v_note);
    v_state:=pg_catalog.jsonb_set(v_state,'{turnovers}',
      (select pg_catalog.jsonb_agg(case when t->>'id'=v_turnover->>'id' then v_turnover
        else t end order by ordinal) from pg_catalog.jsonb_array_elements(v_state->'turnovers')
          with ordinality as entries(t,ordinal)));
  else
    if v_member.role<>d5o_hosted.configured_handoff_role_v1(v_work.configuration_version_id,'deployOperate')
      or p_input->>'decision' not in ('Accepted','Declined') or length(v_note)<15 then
      raise exception 'operations_receipt_authority_required' using errcode='42501'; end if;
    v_acceptance:=v_state->'workAcceptance';
    if v_acceptance is null or v_acceptance->>'receipt'<>'Awaiting'
      or v_acceptance->>'recordedByActorId'=v_actor::text then
      raise exception 'independent_work_receipt_required' using errcode='42501'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'turnovers') t
      where t->>'id' in (select pg_catalog.jsonb_array_elements_text(v_acceptance->'turnoverIds'))
        and t->>'receipt'<>'Accepted') then
      raise exception 'package_receipts_required' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_design.state->'releases') r
      where r->>'status'='Accepted' and not (v_acceptance->'releaseIds' ? (r->>'id'))) then
      raise exception 'work_release_basis_stale' using errcode='23514'; end if;
    v_acceptance:=v_acceptance||pg_catalog.jsonb_build_object(
      'receipt',case when p_input->>'decision'='Accepted' then 'Accepted' else 'Returned' end,
      'receivedByActorId',v_actor,'receivedAt',v_now,'receiptNote',v_note);
    v_state:=pg_catalog.jsonb_set(v_state,'{workAcceptance}',v_acceptance);
  end if;
  v_state:=v_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_deploy.decision_revision+1,
    'events',v_state->'events'||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'commandId',p_command_id,'at',v_now,'actorId',v_actor,
        'membershipId',v_member.id,'action',p_action,
        'packageId',p_package_id,'note',v_note)));
  update d5o_hosted.connected_deploy_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_deploy_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    design_revision,schedule_revision,snapshot)
  values(v_workspace.id,v_work.id,v_deploy.decision_revision+1,p_command_id,
    p_action,v_actor,v_member.id,v_design.decision_revision,
    v_schedule.decision_revision,v_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_deploy_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_actor_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_actor jsonb;
begin
  if v_user is null or p_workspace_key is null then
    raise exception 'workspace_forbidden' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'actorUserId', v_user,
    'workspaceId', w.id,
    'workspaceKey', w.workspace_key,
    'workspaceName', w.display_name,
    'membershipId', m.id,
    'role', m.role
  ) into v_actor
  from d5o_hosted.workspaces w
  join d5o_hosted.memberships m on m.workspace_id = w.id
  where w.workspace_key = p_workspace_key
    and w.status = 'active'
    and m.actor_user_id = v_user
    and m.status = 'active';

  if v_actor is null then
    raise exception 'workspace_forbidden' using errcode = '42501';
  end if;
  return v_actor;
end;
$function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_admin_identity_finish_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_command_id text, p_status text, p_provider_user_id uuid, p_provider_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_request d5o_hosted.admin_identity_requests%rowtype;
begin
  if current_setting('role',true) is distinct from 'service_role'
    or p_status not in ('provider_accepted','provider_rejected','uncertain')
    or length(coalesce(p_provider_message,''))>240 then
    raise exception 'invalid_identity_result' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.id=p_admin_membership_id and m.actor_user_id=p_admin_user_id
      and m.role='admin' and m.status='active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode='42501'; end if;
  select * into v_request from d5o_hosted.admin_identity_requests
    where workspace_id=v_workspace and command_id=p_command_id
      and actor_user_id=p_admin_user_id for update;
  if not found then raise exception 'identity_intent_missing' using errcode='23503'; end if;
  if v_request.status<>'pending' then
    if v_request.status<>p_status or v_request.provider_user_id is distinct from p_provider_user_id then
      raise exception 'identity_result_conflict' using errcode='23505'; end if;
    return pg_catalog.jsonb_build_object('status',v_request.status,'replay',true);
  end if;
  update d5o_hosted.admin_identity_requests set status=p_status,
    provider_user_id=p_provider_user_id,provider_message=p_provider_message,
    resolved_at=now() where workspace_id=v_workspace and command_id=p_command_id;
  return pg_catalog.jsonb_build_object('status',p_status);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_admin_identity_intent_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_action text, p_target_email text, p_reason text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_prior d5o_hosted.admin_identity_requests%rowtype;v_fingerprint text;
begin
  if current_setting('role',true) is distinct from 'service_role'
    or p_action not in ('invite','recovery')
    or lower(trim(coalesce(p_target_email,''))) !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$'
    or length(trim(coalesce(p_reason,''))) not between 8 and 500
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'invalid_identity_request' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.id=p_admin_membership_id and m.actor_user_id=p_admin_user_id
      and m.role='admin' and m.status='active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode='42501'; end if;
  if p_action='recovery' and not exists(select 1 from d5o_hosted.memberships m
      join auth.users u on u.id=m.actor_user_id
      where m.workspace_id=v_workspace and lower(u.email)=lower(trim(p_target_email))) then
    raise exception 'workspace_account_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_admin_user_id,p_action,lower(trim(p_target_email)),trim(p_reason))::text);
  select * into v_prior from d5o_hosted.admin_identity_requests
    where workspace_id=v_workspace and command_id=p_command_id for update;
  if found then
    if v_prior.fingerprint<>v_fingerprint then
      raise exception 'command_id_reused' using errcode='23505'; end if;
    return pg_catalog.jsonb_build_object('fresh',false,'status',v_prior.status);
  end if;
  insert into d5o_hosted.admin_identity_requests
    (workspace_id,command_id,actor_user_id,action,target_email,reason,fingerprint,status)
    values(v_workspace,p_command_id,p_admin_user_id,p_action,
      lower(trim(p_target_email)),trim(p_reason),v_fingerprint,'pending');
  return pg_catalog.jsonb_build_object('fresh',true,'status','pending');
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_admin_identity_intent_v2(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_action text, p_target_email text, p_requested_role text, p_reason text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_prior d5o_hosted.admin_identity_requests%rowtype;
  v_fingerprint text;v_existing uuid;v_confirmed timestamptz;v_status text;
begin
  if current_setting('role',true) is distinct from 'service_role'
    or p_action not in ('invite','recovery')
    or (p_action='invite' and (p_requested_role is null or p_requested_role not in
      ('executive','operations_leader','business_development_lead',
       'project_manager','billing_commercial_lead','field_supervisor',
       'closeout_lead','read_only_auditor','field_worker')))
    or (p_action='recovery' and p_requested_role is not null)
    or lower(trim(coalesce(p_target_email,''))) !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$'
    or length(trim(coalesce(p_reason,''))) not between 8 and 500
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'invalid_identity_request' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.id=p_admin_membership_id and m.actor_user_id=p_admin_user_id
      and m.role='admin' and m.status='active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode='42501'; end if;
  select u.id,u.email_confirmed_at into v_existing,v_confirmed from auth.users u
    where lower(u.email)=lower(trim(p_target_email));
  if p_action='recovery' and not exists(select 1 from d5o_hosted.memberships m
      where m.workspace_id=v_workspace and m.actor_user_id=v_existing) then
    raise exception 'workspace_account_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_admin_user_id,p_action,lower(trim(p_target_email)),
    p_requested_role,trim(p_reason))::text);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'd5o-identity:'||v_workspace::text||':'||p_action||':'||lower(trim(p_target_email)),0));
  select * into v_prior from d5o_hosted.admin_identity_requests
    where workspace_id=v_workspace and command_id=p_command_id for update;
  if found then
    if v_prior.fingerprint<>v_fingerprint then
      raise exception 'command_id_reused' using errcode='23505'; end if;
    return pg_catalog.jsonb_build_object('fresh',false,'status',v_prior.status,
      'requestedRole',v_prior.requested_role);
  end if;
  select * into v_prior from d5o_hosted.admin_identity_requests
    where workspace_id=v_workspace and action=p_action
      and target_email=lower(trim(p_target_email))
      and (status in ('pending','uncertain')
        or (status='provider_accepted' and created_at>now()-interval '10 minutes'))
    order by created_at desc limit 1;
  if found then
    if v_prior.requested_role is distinct from p_requested_role then
      raise exception 'pending_invitation_role_conflict' using errcode='23505'; end if;
    return pg_catalog.jsonb_build_object('fresh',false,'status',v_prior.status,
      'requestedRole',v_prior.requested_role,'priorRequest',true);
  end if;
  v_status:=case when p_action='invite' and v_confirmed is not null
    then 'existing_confirmed' else 'pending' end;
  insert into d5o_hosted.admin_identity_requests
    (workspace_id,command_id,actor_user_id,action,target_email,requested_role,
     reason,fingerprint,status,provider_user_id,resolved_at)
    values(v_workspace,p_command_id,p_admin_user_id,p_action,
      lower(trim(p_target_email)),p_requested_role,trim(p_reason),v_fingerprint,
      v_status,case when v_status='existing_confirmed' then v_existing else null end,
      case when v_status='existing_confirmed' then now() else null end);
  return pg_catalog.jsonb_build_object('fresh',true,'status',v_status,
    'providerRequired',v_status='pending','requestedRole',p_requested_role);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_admin_membership_change_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_member_email text, p_action text, p_role text, p_expected_role text, p_expected_status text, p_reason text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_target uuid;v_current d5o_hosted.memberships%rowtype;
  v_prior d5o_hosted.membership_assignment_events%rowtype;v_annotation d5o_hosted.admin_membership_reasons%rowtype;
  v_fingerprint text;
  v_result jsonb;
begin
  if current_setting('role',true) is distinct from 'service_role'
    or p_action not in ('assign','suspend')
    or length(trim(coalesce(p_reason,''))) not between 8 and 500
    or (p_expected_status is not null and p_expected_status not in ('active','suspended')) then
    raise exception 'invalid_membership_change' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.id=p_admin_membership_id and m.actor_user_id=p_admin_user_id
      and m.role='admin' and m.status='active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode='42501'; end if;
  select id into v_target from auth.users where lower(email)=lower(trim(p_member_email))
    and email_confirmed_at is not null;
  if v_target is null then raise exception 'confirmed_member_missing' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_admin_user_id,p_member_email,p_action,p_role,
    p_expected_role,p_expected_status,trim(p_reason))::text);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'd5o-member:'||v_workspace::text||':'||v_target::text,0));
  select * into v_prior from d5o_hosted.membership_assignment_events
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    select * into v_annotation from d5o_hosted.admin_membership_reasons
      where workspace_id=v_workspace and command_id=p_command_id;
    if v_annotation.fingerprint is distinct from v_fingerprint then
      raise exception 'command_id_reused' using errcode='23505'; end if;
  else
    select * into v_current from d5o_hosted.memberships
      where workspace_id=v_workspace and actor_user_id=v_target for update;
    if (v_current.id is null and p_expected_status is not null)
      or (v_current.id is not null and v_current.status is distinct from p_expected_status) then
      raise exception 'stale_membership' using errcode='23505'; end if;
  end if;
  if p_action='suspend' then
    v_result:=public.d5o_hosted_suspend_member_v1(p_workspace_key,p_admin_user_id,
      p_admin_membership_id,p_member_email,p_expected_role,p_command_id);
  else
    v_result:=public.d5o_hosted_assign_member_v1(p_workspace_key,p_admin_user_id,
      p_admin_membership_id,p_member_email,p_role,p_expected_role,p_command_id);
  end if;
  if exists(select 1 from d5o_hosted.membership_assignment_events
      where workspace_id=v_workspace and command_id=p_command_id) then
    insert into d5o_hosted.admin_membership_reasons(workspace_id,command_id,actor_user_id,reason,fingerprint)
      values(v_workspace,p_command_id,p_admin_user_id,trim(p_reason),v_fingerprint) on conflict do nothing;
  end if;
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_admin_receipt_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid; v_source text; v_result jsonb;
begin
  if current_setting('role',true) is distinct from 'service_role'
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'admin_receipt_denied' using errcode='42501'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.id=p_admin_membership_id and m.actor_user_id=p_admin_user_id
      and m.role='admin' and m.status='active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode='42501'; end if;
  select 'membership',pg_catalog.jsonb_build_object('action',e.action,'subject',e.target_user_id)
    into v_source,v_result from d5o_hosted.membership_assignment_events e
    where e.workspace_id=v_workspace and e.command_id=p_command_id and e.actor_user_id=p_admin_user_id;
  if v_source is null then
    select 'workforce',c.result into v_source,v_result
      from d5o_hosted.connected_workforce_commands c
      where c.workspace_id=v_workspace and c.command_id=p_command_id and c.actor_user_id=p_admin_user_id;
  end if;
  if v_source is null then
    select 'handoff',r.result into v_source,v_result
      from d5o_hosted.handoff_configuration_receipts r
      where r.workspace_id=v_workspace and r.command_id=p_command_id and r.actor_user_id=p_admin_user_id;
  end if;
  if v_source is null then
    select 'delegation',r.result into v_source,v_result
      from d5o_hosted.spending_delegate_receipts r
      where r.workspace_id=v_workspace and r.command_id=p_command_id and r.actor_user_id=p_admin_user_id;
  end if;
  if v_source is null then
    select 'rate',r.result into v_source,v_result
      from d5o_hosted.design_internal_rate_receipts r
      where r.workspace_id=v_workspace and r.command_id=p_command_id and r.actor_user_id=p_admin_user_id;
  end if;
  if v_source is null then
    select 'admin_succession',pg_catalog.jsonb_build_object('subject',e.target_user_id)
      into v_source,v_result from d5o_hosted.admin_succession_events e
      where e.workspace_id=v_workspace and e.command_id=p_command_id
        and e.actor_user_id=p_admin_user_id;
  end if;
  if v_source is null then
    select 'binding_correction',pg_catalog.jsonb_build_object('personId',e.person_id,'revision',e.workforce_revision)
      into v_source,v_result from d5o_hosted.admin_binding_corrections e
      where e.workspace_id=v_workspace and e.command_id=p_command_id
        and e.actor_user_id=p_admin_user_id;
  end if;
  if v_source is null then
    select 'identity',pg_catalog.jsonb_build_object('status',e.status,'action',e.action)
      into v_source,v_result from d5o_hosted.admin_identity_requests e
      where e.workspace_id=v_workspace and e.command_id=p_command_id
        and e.actor_user_id=p_admin_user_id;
  end if;
  return pg_catalog.jsonb_build_object('found',v_source is not null,'source',v_source,'result',v_result);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_admin_succession_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_target_email text, p_reason text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_target uuid;v_member d5o_hosted.memberships%rowtype;
  v_prior d5o_hosted.admin_succession_events%rowtype;
begin
  if current_setting('role',true) is distinct from 'service_role'
    or length(trim(coalesce(p_reason,''))) not between 12 and 500
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'invalid_admin_succession' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.id=p_admin_membership_id and m.actor_user_id=p_admin_user_id
      and m.role='admin' and m.status='active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode='42501'; end if;
  select id into v_target from auth.users where lower(email)=lower(trim(p_target_email))
    and email_confirmed_at is not null;
  if v_target is null or v_target=p_admin_user_id then
    raise exception 'confirmed_independent_account_required' using errcode='23503'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'd5o-member:'||v_workspace::text||':'||v_target::text,0));
  select * into v_prior from d5o_hosted.admin_succession_events
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    if v_prior.actor_user_id<>p_admin_user_id or v_prior.target_user_id<>v_target
      or v_prior.reason<>trim(p_reason) then
      raise exception 'command_id_reused' using errcode='23505'; end if;
    return pg_catalog.jsonb_build_object('userId',v_target,'action','admin_succession','replay',true);
  end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace and actor_user_id=v_target for update;
  if v_member.role='field_worker' or v_member.role='admin' then
    raise exception 'protected_membership' using errcode='42501'; end if;
  if exists(select 1 from d5o_hosted.crew_bindings
      where workspace_id=v_workspace and actor_user_id=v_target and active) then
    raise exception 'worker_binding_conflict' using errcode='23505'; end if;
  if v_member.id is null then
    insert into d5o_hosted.memberships(workspace_id,actor_user_id,role,status)
      values(v_workspace,v_target,'admin','active');
  else
    update d5o_hosted.memberships set role='admin',status='active' where id=v_member.id;
  end if;
  insert into d5o_hosted.admin_succession_events
    (workspace_id,command_id,actor_user_id,target_user_id,previous_role,reason)
    values(v_workspace,p_command_id,p_admin_user_id,v_target,v_member.role,trim(p_reason));
  return pg_catalog.jsonb_build_object('userId',v_target,'action','admin_succession');
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_assign_member_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_member_email text, p_role text, p_expected_role text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace uuid;
  v_target uuid;
  v_member d5o_hosted.memberships%rowtype;
  v_prior_role text;
  v_action text;
  v_fingerprint text;
  v_replay d5o_hosted.membership_assignment_events%rowtype;
begin
  if current_setting('role', true) is distinct from 'service_role'
    or p_admin_user_id is null or p_admin_membership_id is null then
    raise exception 'server_admin_required' using errcode = '42501';
  end if;
  if p_workspace_key is null or p_member_email is null
    or length(trim(p_member_email)) not between 3 and 320
    or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_role is null or p_role not in ('executive', 'operations_leader', 'business_development_lead',
      'project_manager', 'billing_commercial_lead', 'field_supervisor',
      'closeout_lead', 'read_only_auditor') then
    raise exception 'invalid_membership_assignment' using errcode = '22023';
  end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id = w.id
    where w.workspace_key = p_workspace_key and w.status = 'active'
      and m.id = p_admin_membership_id and m.actor_user_id = p_admin_user_id
      and m.role = 'admin' and m.status = 'active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode = '42501'; end if;
  select u.id into v_target from auth.users u
    where lower(u.email) = lower(trim(p_member_email)) and u.email_confirmed_at is not null;
  if v_target is null then raise exception 'confirmed_member_missing' using errcode = '23503'; end if;
  if v_target = p_admin_user_id then raise exception 'self_assignment_denied' using errcode = '42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('d5o-member:' || v_workspace::text || ':' || v_target::text, 0));
  v_fingerprint := pg_catalog.md5(lower(trim(p_member_email)) || ':' || p_role || ':' || coalesce(p_expected_role, 'new') || ':' || p_admin_user_id::text);
  select * into v_replay from d5o_hosted.membership_assignment_events
    where workspace_id = v_workspace and command_id = p_command_id;
  if found then
    if v_replay.fingerprint <> v_fingerprint or v_replay.target_user_id <> v_target then
      raise exception 'command_id_reused' using errcode = '23505';
    end if;
    return pg_catalog.jsonb_build_object('userId', v_target, 'role', v_replay.assigned_role, 'action', v_replay.action, 'replay', true);
  end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id = v_workspace and actor_user_id = v_target for update;
  if found then
    v_prior_role := v_member.role;
    if v_member.role = 'admin' or v_member.role = 'field_worker' then
      raise exception 'protected_membership' using errcode = '42501';
    end if;
    if v_member.role = p_role and v_member.status = 'active' then
      return pg_catalog.jsonb_build_object('userId', v_target, 'role', p_role, 'action', 'already_assigned');
    end if;
    if p_expected_role is distinct from v_member.role then
      raise exception 'stale_membership' using errcode = '23505';
    end if;
    v_action := case when v_member.status = 'suspended' and v_member.role = p_role then 'reactivated' else 'changed' end;
    update d5o_hosted.memberships set role = p_role, status = 'active' where id = v_member.id;
  else
    if p_expected_role is not null then raise exception 'stale_membership' using errcode = '23505'; end if;
    v_action := 'assigned';
    insert into d5o_hosted.memberships(workspace_id, actor_user_id, role, status)
      values(v_workspace, v_target, p_role, 'active');
  end if;
  insert into d5o_hosted.membership_assignment_events(workspace_id, command_id, fingerprint,
    actor_user_id, actor_membership_id, target_user_id, previous_role, assigned_role, action)
    values(v_workspace, p_command_id, v_fingerprint, p_admin_user_id,
      p_admin_membership_id, v_target, v_prior_role, p_role, v_action);
  return pg_catalog.jsonb_build_object('userId', v_target, 'role', p_role, 'action', v_action);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_assign_support_document_supplier_v1(p_workspace_key text, p_presentation_id text, p_turnover_id text, p_action text, p_supervisor_email text, p_reason text, p_command_id text, p_expected_source_revision bigint, p_expected_deploy_revision integer, p_expected_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_target d5o_hosted.memberships%rowtype;
  v_work d5o_hosted.work_records%rowtype;v_raw d5o_hosted.prototype_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_receipt d5o_hosted.connected_operate_receipts%rowtype;
  v_basis jsonb;v_previous jsonb;v_entry jsonb;v_state jsonb;v_result jsonb;
  v_fingerprint text;v_email text:=pg_catalog.lower(pg_catalog.btrim(coalesce(p_supervisor_email,'')));
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'support_assignment_membership_required' using errcode='42501'; end if;
  if p_action not in ('assign','revoke') or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
    or length(pg_catalog.btrim(coalesce(p_reason,'')))<10
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_deploy_revision is null
    or p_expected_operate_revision is null then
    raise exception 'invalid_support_assignment' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role<>'operations_leader' then
    raise exception 'support_assignment_authority_required' using errcode='42501'; end if;
  select m.* into v_target from d5o_hosted.memberships m
    join auth.users u on u.id=m.actor_user_id
    where m.workspace_id=v_workspace.id and m.status='active'
      and m.role='field_supervisor' and pg_catalog.lower(u.email)=v_email for share of m;
  if not found then raise exception 'active_supervisor_account_required' using errcode='23514'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_presentation_id,p_turnover_id,p_action,v_email,
    pg_catalog.btrim(p_reason),p_expected_source_revision,p_expected_deploy_revision,
    p_expected_operate_revision)::text);
  select * into v_receipt from d5o_hosted.connected_operate_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_deploy.decision_revision is distinct from p_expected_deploy_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision then
    raise exception 'stale_support_assignment_basis' using errcode='23505'; end if;
  v_basis:=d5o_hosted.support_document_basis_v1(
    v_workspace.id,v_work.id,p_turnover_id,'as-built');
  if v_basis is null then v_basis:=d5o_hosted.support_document_basis_v1(
    v_workspace.id,v_work.id,p_turnover_id,'inspection'); end if;
  if v_basis is null then raise exception 'accepted_support_obligation_required' using errcode='23514'; end if;
  select a into v_previous from pg_catalog.jsonb_array_elements(
    coalesce(v_operate.state->'supportDocumentAssignments','[]'::jsonb))
    with ordinality as entries(a,n)
    where a->>'turnoverId'=p_turnover_id order by n desc limit 1;
  if p_action='revoke' and (v_previous is null or v_previous->>'status'<>'Assigned'
    or v_previous->>'actorId'<>v_target.actor_user_id::text) then
    raise exception 'current_support_assignment_required' using errcode='23514'; end if;
  if p_action='assign' and v_previous->>'status'='Assigned'
    and v_previous->>'actorId'=v_target.actor_user_id::text then
    raise exception 'support_supplier_already_assigned' using errcode='23505'; end if;
  v_entry:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),'turnoverId',p_turnover_id,
    'packageId',v_basis->>'packageId','releaseId',v_basis->>'releaseId',
    'actorId',v_target.actor_user_id,'email',v_email,
    'status',case when p_action='assign' then 'Assigned' else 'Revoked' end,
    'previousAssignmentId',v_previous->>'id','byActorId',v_actor,
    'byMembershipId',v_member.id,'at',now(),'reason',pg_catalog.btrim(p_reason));
  v_state:=v_operate.state||pg_catalog.jsonb_build_object(
    'supportDocumentAssignments',coalesce(v_operate.state->'supportDocumentAssignments','[]'::jsonb)
      ||pg_catalog.jsonb_build_array(v_entry),
    'authorityRevision',v_operate.decision_revision+1,
    'events',coalesce(v_operate.state->'events','[]'::jsonb)
      ||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'id',gen_random_uuid(),'commandId',p_command_id,'fingerprint',v_fingerprint,
        'at',now(),'actorId',v_actor,'membershipId',v_member.id,
        'action','support-supplier-'||p_action,
        'detail',p_turnover_id||' · '||v_email)));
  update d5o_hosted.connected_operate_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=now()
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_operate_events(
    workspace_id,work_id,decision_revision,command_id,action,actor_user_id,
    membership_id,deploy_revision,snapshot)
  values(v_workspace.id,v_work.id,v_operate.decision_revision+1,p_command_id,
    'support-supplier-'||p_action,v_actor,v_member.id,v_deploy.decision_revision,v_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_operate_receipts(
    workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_availability_command_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_member d5o_hosted.memberships%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;
  v_prior d5o_hosted.connected_schedule_receipts%rowtype;
  v_fingerprint text;v_state jsonb;v_blocks jsonb;v_block jsonb;v_result jsonb;
  v_anchor date;v_week integer;v_day integer;v_date date;v_person text;v_note text;v_id text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('record-unavailability','clear-unavailability')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_availability_command' using errcode='22023'; end if;
  select id into v_workspace from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
  select * into v_member from d5o_hosted.memberships where workspace_id=v_workspace
    and actor_user_id=v_actor and status='active' and role='admin' for share;
  if v_workspace is null or v_member.id is null then
    raise exception 'admin_availability_required' using errcode='42501'; end if;
  insert into d5o_hosted.connected_schedule_states(workspace_id,decision_revision,state)
    values(v_workspace,1,pg_catalog.jsonb_build_object(
      'anchorDate',to_char(date_trunc('week',now()),'YYYY-MM-DD'),
      'draftRevision',1,'assignments','[]'::jsonb,'availabilityBlocks','[]'::jsonb,
      'publications','[]'::jsonb,'receipts','[]'::jsonb)) on conflict do nothing;
  select * into v_schedule from d5o_hosted.connected_schedule_states
    where workspace_id=v_workspace for update;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_action,p_input,p_expected_revision)::text);
  select * into v_prior from d5o_hosted.connected_schedule_receipts
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    if v_prior.actor_user_id<>v_actor or v_prior.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_prior.result;
  end if;
  if v_schedule.decision_revision<>p_expected_revision and not
    (v_schedule.decision_revision=1 and p_expected_revision=0 and
      v_schedule.state->'assignments'='[]'::jsonb and
      v_schedule.state->'publications'='[]'::jsonb) then
    raise exception 'stale_schedule' using errcode='23505'; end if;
  v_state:=v_schedule.state;
  v_blocks:=coalesce(v_state->'availabilityBlocks','[]'::jsonb);
  if p_action='record-unavailability' then
    v_person:=trim(coalesce(p_input->>'person',''));
    v_week:=(p_input->>'week')::integer;
    v_day:=(p_input->>'day')::integer;
    v_date:=(p_input->>'date')::date;
    v_anchor:=(v_state->>'anchorDate')::date;
    v_note:=trim(coalesce(p_input->>'note',''));
    if v_week is null or v_week not between -260 and 260
      or v_day is null or v_day not between 0 and 4
      or v_date is null or v_date<>v_anchor+v_week*7+v_day
      or length(v_note)>140 or v_person='' then
      raise exception 'invalid_unavailability_interval' using errcode='23514'; end if;
    if not exists(select 1 from d5o_hosted.connected_crew_profiles
      where workspace_id=v_workspace and person=v_person and active) then
      raise exception 'person_unavailable' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_blocks) b
      where b->>'person'=v_person and b->>'date'=v_date::text) then
      raise exception 'unavailability_already_recorded' using errcode='23505'; end if;
    v_id:=pg_catalog.gen_random_uuid()::text;
    v_block:=pg_catalog.jsonb_build_object('id',v_id,'person',v_person,
      'week',v_week,'day',v_day,'date',v_date,'reason','Unavailable','note',v_note,
      'timeZone','America/New_York',
      'recordedBy',v_actor,'recordedAt',now());
    v_blocks:=v_blocks||pg_catalog.jsonb_build_array(v_block);
  else
    v_id:=trim(coalesce(p_input->>'id',''));
    if v_id='' or not exists(select 1 from pg_catalog.jsonb_array_elements(v_blocks) b
      where b->>'id'=v_id) then
      raise exception 'unavailability_missing' using errcode='23514'; end if;
    select coalesce(pg_catalog.jsonb_agg(b),'[]'::jsonb) into v_blocks
      from pg_catalog.jsonb_array_elements(v_blocks) b where b->>'id'<>v_id;
  end if;
  v_state:=pg_catalog.jsonb_set(v_state,'{availabilityBlocks}',v_blocks,true);
  v_state:=pg_catalog.jsonb_set(v_state,'{draftRevision}',
    pg_catalog.to_jsonb(coalesce((v_state->>'draftRevision')::integer,0)+1),true);
  update d5o_hosted.connected_schedule_states set decision_revision=decision_revision+1,
    state=v_state,updated_at=now() where workspace_id=v_workspace;
  insert into d5o_hosted.connected_schedule_events(workspace_id,decision_revision,
    command_id,action,actor_user_id,membership_id,snapshot)
    values(v_workspace,v_schedule.decision_revision+1,p_command_id,p_action,
      v_actor,v_member.id,v_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'schedule');
  insert into d5o_hosted.connected_schedule_receipts(workspace_id,command_id,
    actor_user_id,fingerprint,result)
    values(v_workspace,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_bind_worker_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_worker_email text, p_person text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid; v_worker uuid; v_membership d5o_hosted.memberships%rowtype;
  v_binding d5o_hosted.crew_bindings%rowtype; v_action text;
begin
  if current_setting('role', true) is distinct from 'service_role' then
    raise exception 'server_admin_required' using errcode = '42501'; end if;
  if p_person is null or length(trim(p_person)) not between 2 and 120
    or p_worker_email is null or length(trim(p_worker_email)) not between 3 and 320 then
    raise exception 'invalid_worker_identity' using errcode = '22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id = w.id
    where w.workspace_key = p_workspace_key and w.status = 'active'
      and m.id = p_admin_membership_id and m.actor_user_id = p_admin_user_id
      and m.role = 'admin' and m.status = 'active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode = '42501'; end if;
  select u.id into v_worker from auth.users u
    where lower(u.email) = lower(trim(p_worker_email)) and u.email_confirmed_at is not null;
  if v_worker is null then raise exception 'confirmed_worker_missing' using errcode = '23503'; end if;
  if v_worker = p_admin_user_id then raise exception 'worker_separation_required' using errcode = '42501'; end if;
  select * into v_membership from d5o_hosted.memberships
    where workspace_id = v_workspace and actor_user_id = v_worker for update;
  if found and v_membership.role <> 'field_worker' then
    raise exception 'existing_role_conflict' using errcode = '23505'; end if;
  select * into v_binding from d5o_hosted.crew_bindings
    where workspace_id = v_workspace and (actor_user_id = v_worker or person = trim(p_person)) for update;
  if found and (v_binding.actor_user_id <> v_worker or v_binding.person <> trim(p_person)) then
    raise exception 'crew_identity_conflict' using errcode = '23505'; end if;
  if found and v_binding.active and v_membership.status = 'active' then
    return pg_catalog.jsonb_build_object('person', trim(p_person), 'workerUserId', v_worker, 'action', 'already_bound');
  end if;
  if not found then v_action := 'bound'; else v_action := 'reactivated'; end if;
  insert into d5o_hosted.memberships(workspace_id, actor_user_id, role, status)
    values(v_workspace, v_worker, 'field_worker', 'active')
    on conflict(workspace_id, actor_user_id) do update set status = 'active'
      where d5o_hosted.memberships.role = 'field_worker';
  insert into d5o_hosted.crew_bindings(workspace_id, actor_user_id, person, active)
    values(v_workspace, v_worker, trim(p_person), true)
    on conflict(workspace_id, actor_user_id) do update set active = true;
  insert into d5o_hosted.crew_binding_events(workspace_id, actor_user_id, worker_user_id, person, action)
    values(v_workspace, p_admin_user_id, v_worker, trim(p_person), v_action);
  return pg_catalog.jsonb_build_object('person', trim(p_person), 'workerUserId', v_worker, 'action', v_action);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_bootstrap_synthetic_admin_v1(p_workspace_key text, p_target_email text, p_operator_label text, p_reason text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace uuid;
  v_target uuid;
  v_prior d5o_hosted.synthetic_beta_admin_bootstrap%rowtype;
begin
  if current_setting('role', true) is distinct from 'service_role' then
    raise exception 'server_operator_required' using errcode = '42501';
  end if;
  if p_workspace_key is distinct from 'rybex'
    or lower(trim(coalesce(p_target_email, ''))) !~ '^[^@[:space:]]+@example[.]test$'
    or length(trim(coalesce(p_operator_label, ''))) not between 3 and 120
    or length(trim(coalesce(p_reason, ''))) not between 12 and 500
    or length(coalesce(p_command_id, '')) not between 8 and 120 then
    raise exception 'invalid_beta_bootstrap' using errcode = '22023';
  end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key = p_workspace_key and status = 'active' for update;
  if v_workspace is null then raise exception 'workspace_missing' using errcode = '23503'; end if;
  select * into v_prior from d5o_hosted.synthetic_beta_admin_bootstrap
    where workspace_id = v_workspace;
  if found then
    if v_prior.command_id = p_command_id and v_prior.target_email = lower(trim(p_target_email))
      and v_prior.operator_label = trim(p_operator_label) and v_prior.reason = trim(p_reason) then
      return pg_catalog.jsonb_build_object('userId', v_prior.target_user_id, 'replay', true);
    end if;
    raise exception 'beta_admin_already_bootstrapped' using errcode = '23505';
  end if;
  if exists (select 1 from d5o_hosted.work_records where workspace_id = v_workspace)
    or exists (select 1 from d5o_hosted.configuration_versions cv
      join d5o_hosted.configuration_tenants ct on ct.id = cv.tenant_id
      where ct.workspace_id = v_workspace) then
    raise exception 'beta_bootstrap_requires_empty_workspace' using errcode = '23505';
  end if;
  select id into v_target from auth.users where lower(email) = lower(trim(p_target_email))
    and email_confirmed_at is not null;
  if v_target is null then raise exception 'confirmed_member_missing' using errcode = '23503'; end if;
  if exists (select 1 from d5o_hosted.memberships
    where workspace_id = v_workspace and actor_user_id = v_target) then
    raise exception 'target_already_member' using errcode = '23505';
  end if;
  insert into d5o_hosted.memberships(workspace_id, actor_user_id, role, status)
    values (v_workspace, v_target, 'admin', 'active');
  insert into d5o_hosted.synthetic_beta_admin_bootstrap(
    workspace_id, target_user_id, target_email, operator_label, reason, command_id)
    values (v_workspace, v_target, lower(trim(p_target_email)), trim(p_operator_label),
      trim(p_reason), p_command_id);
  return pg_catalog.jsonb_build_object('userId', v_target, 'role', 'admin', 'action', 'synthetic_beta_bootstrap');
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_command_save_v1(p_workspace_key text, p_state_key text, p_expected_revision bigint, p_state jsonb, p_actor_user_id uuid, p_membership_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace uuid; v_revision bigint; v_current jsonb; v_link record;
  v_old jsonb; v_new jsonb;
begin
  if current_setting('role', true) is distinct from 'service_role' then
    raise exception 'server_command_required' using errcode='42501'; end if;
  if p_state_key not in ('work','catalog','schedule') or p_expected_revision < 0
    or p_state is null or pg_catalog.jsonb_typeof(p_state) <> 'object'
    or p_state->>'workspace' is distinct from p_workspace_key
    or p_state->>'schemaVersion' is distinct from '1'
    or pg_catalog.octet_length(p_state::text) > 2000000 then
    raise exception 'invalid_state' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.id=p_membership_id and m.actor_user_id=p_actor_user_id
      and m.status='active';
  if v_workspace is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  if p_state_key='work' and exists(select 1 from d5o_hosted.work_identity_links
      where workspace_id=v_workspace) then
    select state_json into v_current from d5o_hosted.prototype_states
      where workspace_id=v_workspace and state_key='work' for update;
    if pg_catalog.jsonb_typeof(p_state->'records') is distinct from 'array' then
      raise exception 'connected_records_missing' using errcode='42501'; end if;
    for v_link in select presentation_id from d5o_hosted.work_identity_links
        where workspace_id=v_workspace loop
      select item into v_old from pg_catalog.jsonb_array_elements(
        coalesce(v_current->'records','[]'::jsonb)) item
        where item->>'id'=v_link.presentation_id;
      select item into v_new from pg_catalog.jsonb_array_elements(p_state->'records') item
        where item->>'id'=v_link.presentation_id;
      if v_old is null or v_new is null
        or d5o_hosted.protected_work_record_v1(v_old)
          is distinct from d5o_hosted.protected_work_record_v1(v_new) then
        raise exception 'typed_command_required' using errcode='42501'; end if;
    end loop;
  end if;
  if p_expected_revision=0 then
    insert into d5o_hosted.prototype_states(workspace_id,state_key,revision,state_json,updated_by)
      values(v_workspace,p_state_key,1,p_state,p_actor_user_id)
      on conflict(workspace_id,state_key) do nothing returning revision into v_revision;
  else
    update d5o_hosted.prototype_states set revision=revision+1,state_json=p_state,
      updated_by=p_actor_user_id,updated_at=now()
      where workspace_id=v_workspace and state_key=p_state_key
        and revision=p_expected_revision returning revision into v_revision;
  end if;
  if v_revision is null then raise exception 'stale_state' using errcode='23505'; end if;
  insert into d5o_hosted.prototype_state_revisions(workspace_id,state_key,
    revision,state_json,actor_user_id,membership_id)
    values(v_workspace,p_state_key,v_revision,p_state,p_actor_user_id,p_membership_id);
  return pg_catalog.jsonb_build_object('revision',v_revision,'state',p_state);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_configuration_admin_command_v1(p_workspace_key text, p_action text, p_version uuid, p_expected_active uuid, p_expected_revision integer, p_input jsonb, p_reason text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_tenant d5o_hosted.configuration_tenants%rowtype;
  v_active d5o_hosted.configuration_versions%rowtype;v_version d5o_hosted.configuration_versions%rowtype;
  v_receipt d5o_hosted.configuration_admin_receipts%rowtype;
  v_manifest jsonb;v_before jsonb;v_after jsonb;v_result jsonb;v_fp text;
  v_new uuid;v_key text;v_value text;v_type text;v_role text;v_template text;
  v_type_index integer;v_phase_index integer;v_role_count integer;v_work_types jsonb;
  v_contract_type jsonb;v_routes jsonb;v_route record;v_item jsonb;v_entry jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('create-draft','save-policy','save-route','create-work-type',
      'retire-work-type','set-create-role','validate-publish','activate')
    or p_version is null or p_expected_active is null
    or p_expected_revision is null or p_expected_revision<0
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_reason,'')) not between 8 and 500
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'invalid_configuration_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active' for share;
  if not found then raise exception 'configuration_admin_required' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' and role='admin' for share;
  if not found then raise exception 'configuration_admin_required' using errcode='42501'; end if;
  select * into v_tenant from d5o_hosted.configuration_tenants
    where workspace_id=v_workspace.id and status='active' for update;
  if not found then raise exception 'configuration_unavailable' using errcode='23514'; end if;
  v_fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_action,p_version,
    p_expected_active,p_expected_revision,p_input,trim(p_reason))::text);
  select * into v_receipt from d5o_hosted.configuration_admin_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fp then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_active from d5o_hosted.configuration_versions
    where tenant_id=v_tenant.id and status='published' and effective_from<=now()
      and (effective_to is null or effective_to>now()) for update;
  if not found or v_active.id<>p_expected_active then
    raise exception 'stale_configuration_default' using errcode='23505'; end if;
  if p_action='create-draft' then
    if p_version<>v_active.id or p_expected_revision<>v_active.edit_revision
      or exists(select 1 from d5o_hosted.configuration_versions
        where tenant_id=v_tenant.id and status in ('draft','validated')) then
      raise exception 'stale_configuration_draft' using errcode='23505'; end if;
    insert into d5o_hosted.configuration_versions(tenant_id,version_number,status,source_sha256,
      manifest_json,source_version_id)
      values(v_tenant.id,(select max(version_number)+1 from d5o_hosted.configuration_versions
        where tenant_id=v_tenant.id),'draft',v_active.source_sha256,v_active.manifest_json,v_active.id)
      returning id into v_new;
    insert into d5o_hosted.configuration_work_types(configuration_version_id,work_type_key,display_name,status)
      select v_new,work_type_key,display_name,status from d5o_hosted.configuration_work_types
      where configuration_version_id=v_active.id;
    insert into d5o_hosted.configuration_create_rights(configuration_version_id,work_type_key,workspace_role)
      select v_new,work_type_key,workspace_role from d5o_hosted.configuration_create_rights
      where configuration_version_id=v_active.id;
    insert into d5o_hosted.configuration_handoff_roles(configuration_version_id,route_key,receiving_role,revision,configured_by)
      select v_new,route_key,receiving_role,1,v_actor from d5o_hosted.configuration_handoff_roles
      where configuration_version_id=v_active.id;
    v_before:=pg_catalog.jsonb_build_object('activeVersionId',v_active.id);
    v_after:=pg_catalog.jsonb_build_object('draftVersionId',v_new,'status','draft','revision',1);
    v_result:=pg_catalog.jsonb_build_object('versionId',v_new,'status','draft','revision',1);
  else
    select * into v_version from d5o_hosted.configuration_versions
      where id=p_version and tenant_id=v_tenant.id and source_version_id=v_active.id for update;
    if not found or v_version.edit_revision<>p_expected_revision then
      raise exception 'stale_configuration_revision' using errcode='23505'; end if;
    if (p_action='activate' and v_version.status<>'validated') or
       (p_action<>'activate' and v_version.status<>'draft') then
      raise exception 'configuration_state_invalid' using errcode='23514'; end if;
    v_manifest:=v_version.manifest_json;
    v_before:=pg_catalog.jsonb_build_object('revision',v_version.edit_revision,
      'manifestSha256',v_version.source_sha256,'status',v_version.status);
    if p_action='save-policy' then
      v_key:=p_input->>'key';v_value:=p_input->>'value';v_type:=p_input->>'workTypeKey';
      if v_key='phase-label' and p_input->>'phase' in ('discover','define','develop','design','deploy','operate')
        and length(trim(coalesce(v_value,''))) between 2 and 80 then
        v_manifest:=pg_catalog.jsonb_set(v_manifest,'{d5oPresentation,phaseLabels}',
          coalesce(v_manifest#>'{d5oPresentation,phaseLabels}','{}'::jsonb)||
          pg_catalog.jsonb_build_object(p_input->>'phase',trim(v_value)),true);
      else
        select (ordinality-1)::integer into v_type_index from pg_catalog.jsonb_array_elements(
          v_manifest#>'{d5oPresentation,phaseContract,workTypes}') with ordinality x(item,ordinality)
          where item->>'workTypeKey'=v_type;
        if v_type_index is null then raise exception 'unsupported_work_type' using errcode='22023'; end if;
        if v_key='phase-purpose' and p_input->>'phase' in ('discover','define','develop','design','deploy','operate')
          and length(trim(coalesce(v_value,''))) between 8 and 240 then
          select (ordinality-1)::integer into v_phase_index from pg_catalog.jsonb_array_elements(
            v_manifest#>array['d5oPresentation','phaseContract','workTypes',v_type_index::text,'phases']) with ordinality x(item,ordinality)
            where item->>'key'=p_input->>'phase';
          if v_phase_index is null then raise exception 'invalid_phase' using errcode='22023'; end if;
          v_manifest:=pg_catalog.jsonb_set(v_manifest,array['d5oPresentation','phaseContract','workTypes',v_type_index::text,'phases',v_phase_index::text,'purpose'],pg_catalog.to_jsonb(trim(v_value)),false);
        elsif v_key in ('design-require-permit','design-require-access','deploy-require-reviewed-evidence')
          and v_value in ('true','false') then
          v_manifest:=pg_catalog.jsonb_set(v_manifest,array['d5oPresentation','phaseContract','workTypes',v_type_index::text,
            case when v_key like 'design-%' then 'designControls' else 'deployControls' end,
            case v_key when 'design-require-permit' then 'requirePermit' when 'design-require-access' then 'requireAccess'
              else 'requireReviewedEvidence' end],pg_catalog.to_jsonb(v_value::boolean),false);
        elsif v_key in ('design-review-lead','design-procurement-buffer','deploy-start-lead','deploy-max-hours','operate-response-hours')
          and v_value ~ '^[0-9]{1,4}$' and (
            (v_key in ('design-review-lead','design-procurement-buffer') and v_value::integer between 0 and 90) or
            (v_key='deploy-start-lead' and v_value::integer between 0 and 60) or
            (v_key='deploy-max-hours' and v_value::integer between 1 and 24) or
            (v_key='operate-response-hours' and v_value::integer between 1 and 720)) then
          v_manifest:=pg_catalog.jsonb_set(v_manifest,array['d5oPresentation','phaseContract','workTypes',v_type_index::text,
            case when v_key like 'design-%' then 'designControls' when v_key like 'deploy-%' then 'deployControls' else 'operateControls' end,
            case v_key when 'design-review-lead' then 'reviewLeadDays' when 'design-procurement-buffer' then 'procurementBufferDays'
              when 'deploy-start-lead' then 'fieldStartLeadMinutes' when 'deploy-max-hours' then 'maxActualHoursPerShift'
              else 'defaultResponseHours' end],pg_catalog.to_jsonb(v_value::integer),false);
        elsif v_key='operate-timezone' and length(trim(coalesce(v_value,''))) between 3 and 80
          and exists(select 1 from pg_catalog.pg_timezone_names where name=v_value) then
          v_manifest:=pg_catalog.jsonb_set(v_manifest,array['d5oPresentation','phaseContract','workTypes',v_type_index::text,
            'operateControls','timezone'],pg_catalog.to_jsonb(v_value),false);
        else raise exception 'unsupported_policy_change' using errcode='22023'; end if;
      end if;
      if v_manifest=v_version.manifest_json then raise exception 'configuration_unchanged' using errcode='23514'; end if;
      update d5o_hosted.configuration_versions set manifest_json=v_manifest,
        edit_revision=edit_revision+1 where id=v_version.id;
    elsif p_action='save-route' then
      v_key:=p_input->>'key';v_role:=p_input->>'role';
      if v_key not in ('discoverDefine','designDeploy','deployOperate')
        or v_role not in ('admin','project_manager','operations_leader') then
        raise exception 'invalid_receiving_role' using errcode='22023'; end if;
      update d5o_hosted.configuration_handoff_roles set receiving_role=v_role,
        revision=revision+1,configured_by=v_actor,updated_at=now()
        where configuration_version_id=v_version.id and route_key=v_key;
      if not found then raise exception 'missing_receiving_route' using errcode='23514'; end if;
      v_manifest:=pg_catalog.jsonb_set(v_manifest,array['d5oPresentation','handoffRoles',v_key],
        pg_catalog.to_jsonb(v_role),true);
      update d5o_hosted.configuration_versions set manifest_json=v_manifest,
        edit_revision=edit_revision+1 where id=v_version.id;
    elsif p_action='create-work-type' then
      v_key:=p_input->>'key';v_value:=trim(coalesce(p_input->>'label',''));v_template:=p_input->>'templateKey';
      if v_key !~ '^[a-z][a-z0-9-]{1,63}$' or length(v_value) not between 2 and 120
        or v_template not in ('technical-delivery','lifecycle-service')
        or exists(select 1 from d5o_hosted.configuration_work_types t
          join d5o_hosted.configuration_versions v on v.id=t.configuration_version_id
          where v.tenant_id=v_tenant.id and t.work_type_key=v_key) then
        raise exception 'invalid_or_reused_work_type_key' using errcode='22023'; end if;
      select item into v_contract_type from pg_catalog.jsonb_array_elements(
        v_manifest#>'{d5oPresentation,phaseContract,workTypes}') x(item)
        where item->>'workTypeKey'=v_template;
      if v_contract_type is null or v_contract_type->>'version'<>'prototype-v2' then
        raise exception 'unsupported_engine_template' using errcode='22023'; end if;
      v_contract_type:=pg_catalog.jsonb_set(pg_catalog.jsonb_set(v_contract_type,
        '{workTypeKey}',pg_catalog.to_jsonb(v_key),false),'{workTypeLabel}',pg_catalog.to_jsonb(v_value),false)
        || pg_catalog.jsonb_build_object('engineTemplateKey',v_template);
      v_work_types:=v_manifest#>'{d5oPresentation,phaseContract,workTypes}';
      v_manifest:=pg_catalog.jsonb_set(v_manifest,'{d5oPresentation,phaseContract,workTypes}',
        v_work_types||pg_catalog.jsonb_build_array(v_contract_type),false);
      v_manifest:=pg_catalog.jsonb_set(v_manifest,'{workTypes}',
        (v_manifest->'workTypes')||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
          'key',v_key,'label',v_value,'templateKey',v_template,'status','active')),false);
      insert into d5o_hosted.configuration_work_types(configuration_version_id,work_type_key,display_name,status)
        values(v_version.id,v_key,v_value,'active');
      insert into d5o_hosted.configuration_create_rights(configuration_version_id,work_type_key,workspace_role)
        select v_version.id,v_key,workspace_role from d5o_hosted.configuration_create_rights
          where configuration_version_id=v_version.id and work_type_key=v_template;
      update d5o_hosted.configuration_versions set manifest_json=v_manifest,
        edit_revision=edit_revision+1 where id=v_version.id;
    elsif p_action='retire-work-type' then
      v_key:=p_input->>'key';
      if not exists(select 1 from d5o_hosted.configuration_work_types
          where configuration_version_id=v_version.id and work_type_key=v_key and status='active')
        or (select count(*) from d5o_hosted.configuration_work_types
          where configuration_version_id=v_version.id and status='active')<=1 then
        raise exception 'work_type_retirement_unavailable' using errcode='23514'; end if;
      update d5o_hosted.configuration_work_types set status='disabled'
        where configuration_version_id=v_version.id and work_type_key=v_key;
      select (ordinality-1)::integer into v_type_index from pg_catalog.jsonb_array_elements(v_manifest->'workTypes')
        with ordinality x(item,ordinality) where item->>'key'=v_key;
      if v_type_index is null then raise exception 'work_type_manifest_mismatch' using errcode='23514'; end if;
      v_manifest:=pg_catalog.jsonb_set(v_manifest,array['workTypes',v_type_index::text,'status'],'"disabled"'::jsonb,true);
      update d5o_hosted.configuration_versions set manifest_json=v_manifest,
        edit_revision=edit_revision+1 where id=v_version.id;
    elsif p_action='set-create-role' then
      v_key:=p_input->>'key';v_role:=p_input->>'role';
      if v_role not in ('admin','project_manager')
        or not exists(select 1 from d5o_hosted.configuration_work_types
          where configuration_version_id=v_version.id and work_type_key=v_key and status='active')
        or pg_catalog.jsonb_typeof(p_input->'enabled')<>'boolean' then
        raise exception 'invalid_create_role' using errcode='22023'; end if;
      if (p_input->>'enabled')::boolean then
        insert into d5o_hosted.configuration_create_rights(configuration_version_id,work_type_key,workspace_role)
          values(v_version.id,v_key,v_role) on conflict do nothing;
      else
        delete from d5o_hosted.configuration_create_rights where configuration_version_id=v_version.id
          and work_type_key=v_key and workspace_role=v_role;
      end if;
      update d5o_hosted.configuration_versions set edit_revision=edit_revision+1 where id=v_version.id;
    elsif p_action='validate-publish' then
      if (select count(*) from d5o_hosted.configuration_handoff_roles where configuration_version_id=v_version.id)<>3
        or (select count(*) from d5o_hosted.configuration_work_types where configuration_version_id=v_version.id and status='active')<1
        or pg_catalog.jsonb_typeof(v_manifest->'workTypes')<>'array'
        or pg_catalog.jsonb_typeof(v_manifest#>'{d5oPresentation,phaseContract,workTypes}')<>'array'
        or (select count(*) from d5o_hosted.configuration_work_types where configuration_version_id=v_version.id)
           <>pg_catalog.jsonb_array_length(v_manifest->'workTypes')
        or (select count(*) from d5o_hosted.configuration_work_types where configuration_version_id=v_version.id)
           <>pg_catalog.jsonb_array_length(v_manifest#>'{d5oPresentation,phaseContract,workTypes}') then
        raise exception 'incomplete_configuration' using errcode='23514'; end if;
      for v_route in select route_key,receiving_role from d5o_hosted.configuration_handoff_roles
        where configuration_version_id=v_version.id loop
        if not exists(select 1 from d5o_hosted.memberships m where m.workspace_id=v_workspace.id
          and m.status='active' and m.role=v_route.receiving_role) then
          raise exception 'configured_receiver_unavailable' using errcode='23514'; end if;
        if v_manifest#>>array['d5oPresentation','handoffRoles',v_route.route_key] is distinct from v_route.receiving_role then
          raise exception 'route_manifest_mismatch' using errcode='23514'; end if;
      end loop;
      for v_item in select value from pg_catalog.jsonb_array_elements(v_manifest->'workTypes') loop
        v_key:=v_item->>'key';v_template:=coalesce(v_item->>'templateKey',v_key);
        if v_template not in ('technical-delivery','lifecycle-service')
          or not exists(select 1 from d5o_hosted.configuration_work_types t
            where t.configuration_version_id=v_version.id and t.work_type_key=v_key
              and t.display_name=v_item->>'label' and t.status=case when v_item->>'status'='disabled' then 'disabled' else 'active' end)
          or not exists(select 1 from pg_catalog.jsonb_array_elements(
            v_manifest#>'{d5oPresentation,phaseContract,workTypes}') c(value)
            where c.value->>'workTypeKey'=v_key and c.value->>'workTypeLabel'=v_item->>'label'
              and coalesce(c.value->>'engineTemplateKey',v_key)=v_template)
          then raise exception 'work_type_manifest_mismatch' using errcode='23514'; end if;
        if v_item->>'status' is distinct from 'disabled' then
          select count(*) into v_role_count from d5o_hosted.configuration_create_rights
            where configuration_version_id=v_version.id and work_type_key=v_key;
          if v_role_count<1 then raise exception 'work_type_creator_unavailable' using errcode='23514'; end if;
        end if;
      end loop;
      for v_item in select value from pg_catalog.jsonb_array_elements(
        v_manifest#>'{d5oPresentation,phaseContract,workTypes}') c(value) loop
        if v_item->>'version'<>'prototype-v2'
          or (select pg_catalog.jsonb_agg(phase->'key' order by ordinal)
             from pg_catalog.jsonb_array_elements(v_item->'phases') with ordinality p(phase,ordinal))
             <>'["discover","define","develop","design","deploy","operate"]'::jsonb
          or (v_item->'designControls'->>'reviewLeadDays')::integer not between 0 and 90
          or (v_item->'designControls'->>'procurementBufferDays')::integer not between 0 and 90
          or (v_item->'deployControls'->>'fieldStartLeadMinutes')::integer not between 0 and 60
          or (v_item->'deployControls'->>'maxActualHoursPerShift')::integer not between 1 and 24
          or (v_item->'operateControls'->>'timezone') is null then
          raise exception 'invalid_phase_policy' using errcode='23514'; end if;
      end loop;
      v_routes:=(select pg_catalog.jsonb_object_agg(route_key,receiving_role)
        from d5o_hosted.configuration_handoff_roles where configuration_version_id=v_version.id);
      update d5o_hosted.configuration_versions set status='validated',
        source_sha256=pg_catalog.encode(extensions.digest(v_manifest::text||
          coalesce((select pg_catalog.string_agg(work_type_key||':'||workspace_role,',' order by work_type_key,workspace_role)
            from d5o_hosted.configuration_create_rights where configuration_version_id=v_version.id),''),'sha256'),'hex'),
        edit_revision=edit_revision+1 where id=v_version.id;
    elsif p_action='activate' then
      update d5o_hosted.configuration_versions set status='superseded',effective_to=now()
        where id=v_active.id;
      update d5o_hosted.configuration_versions set status='published',effective_from=now(),
        edit_revision=edit_revision+1 where id=v_version.id;
    end if;
    v_after:=pg_catalog.jsonb_build_object('revision',v_version.edit_revision+1,
      'status',case when p_action='validate-publish' then 'validated'
        when p_action='activate' then 'published' else 'draft' end,'change',p_input,
      'activeVersionId',case when p_action='activate' then v_version.id else v_active.id end);
    v_result:=pg_catalog.jsonb_build_object('versionId',v_version.id,
      'status',v_after->>'status','revision',v_version.edit_revision+1,
      'activeVersionId',v_after->>'activeVersionId');
  end if;
  insert into d5o_hosted.configuration_admin_events(workspace_id,version_id,action,
    actor_user_id,membership_id,command_id,reason,before_json,after_json)
    values(v_workspace.id,coalesce(v_new,v_version.id),p_action,v_actor,v_member.id,
      p_command_id,trim(p_reason),v_before,v_after);
  insert into d5o_hosted.configuration_admin_receipts(workspace_id,command_id,
    actor_user_id,fingerprint,result)
    values(v_workspace.id,p_command_id,v_actor,v_fp,v_result);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_configuration_admin_receipt_v1(p_workspace_key text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'configuration_admin_required' using errcode='42501'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.actor_user_id=v_actor and m.status='active' and m.role='admin';
  if v_workspace is null then raise exception 'configuration_admin_required' using errcode='42501'; end if;
  select result into v_result from d5o_hosted.configuration_admin_receipts
    where workspace_id=v_workspace and command_id=p_command_id and actor_user_id=v_actor;
  return pg_catalog.jsonb_build_object('found',v_result is not null,'source','configuration','result',v_result);
end $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_configuration_inventory_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor jsonb; v_tenant uuid; v_count integer; v_active uuid;
  v_versions jsonb; v_active_count integer;
begin
  v_actor := public.d5o_hosted_actor_v1(p_workspace_key);
  select count(*), (array_agg(t.id))[1] into v_count,v_tenant
    from d5o_hosted.configuration_tenants t
    where t.workspace_id=(v_actor->>'workspaceId')::uuid and t.status='active';
  if v_count <> 1 then return pg_catalog.jsonb_build_object(
    'workspaceId',v_actor->>'workspaceId','status',
    case when v_count=0 then 'no_mapping' else 'ambiguous_mapping' end,
    'tenantId',null,'activeVersionId',null,'versions','[]'::jsonb,
    'canAdminister',(v_actor->>'role'='admin')); end if;
  select count(*), (array_agg(id))[1] into v_active_count,v_active
    from d5o_hosted.configuration_versions
    where tenant_id=v_tenant and status='published' and effective_from<=now()
      and (effective_to is null or effective_to>now());
  if v_active_count <> 1 then return pg_catalog.jsonb_build_object(
    'workspaceId',v_actor->>'workspaceId','status',
    case when v_active_count=0 then 'unavailable_version' else 'ambiguous_mapping' end,
    'tenantId',v_tenant,'activeVersionId',null,'versions','[]'::jsonb,
    'canAdminister',(v_actor->>'role'='admin')); end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id',v.id,'tenant_configuration_id',v.tenant_id,
    'version',v.version_number,'status',v.status,
    'base_configuration_version_id',null,'published_at',v.created_at,
    'effective_from',v.effective_from,'effective_to',v.effective_to,
    'config_manifest_json',v.manifest_json) order by v.version_number desc),'[]'::jsonb)
  into v_versions from d5o_hosted.configuration_versions v
  where v.tenant_id=v_tenant and v.status in ('published','superseded');
  return pg_catalog.jsonb_build_object('workspaceId',v_actor->>'workspaceId',
    'status','ready','tenantId',v_tenant,'activeVersionId',v_active,
    'versions',v_versions,'canAdminister',(v_actor->>'role'='admin'));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_configure_handoff_route_v1(p_workspace_key text, p_version uuid, p_route text, p_role text, p_expected_revision integer, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace d5o_hosted.workspaces%rowtype;v_member d5o_hosted.memberships%rowtype;
  v_route d5o_hosted.configuration_handoff_roles%rowtype;v_actor uuid:=auth.uid();
  v_receipt d5o_hosted.handoff_route_receipts%rowtype;v_fingerprint text;v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_route not in ('discoverDefine','designDeploy','deployOperate')
    or p_role not in ('admin','operations_leader','project_manager')
    or (p_route='deployOperate' and p_role<>'operations_leader')
    or p_expected_revision is null or p_expected_revision<0
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'invalid_handoff_route' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active' for share;
  if not found then raise exception 'handoff_route_admin_required' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor
      and status='active' and role='admin' for share;
  if not found then raise exception 'handoff_route_admin_required' using errcode='42501'; end if;
  if not exists(select 1 from d5o_hosted.configuration_versions v
    join d5o_hosted.configuration_tenants t on t.id=v.tenant_id
    where v.id=p_version and t.workspace_id=v_workspace.id
      and v.status in ('published','superseded')) then
    raise exception 'handoff_configuration_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_version,p_route,p_role,p_expected_revision)::text);
  select * into v_receipt from d5o_hosted.handoff_route_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_route from d5o_hosted.configuration_handoff_roles
    where configuration_version_id=p_version and route_key=p_route for update;
  if coalesce(v_route.revision,0)<>p_expected_revision then
    raise exception 'stale_handoff_route' using errcode='23505'; end if;
  if v_route.configuration_version_id is null then
    insert into d5o_hosted.configuration_handoff_roles
      (configuration_version_id,route_key,receiving_role,revision,configured_by)
      values(p_version,p_route,p_role,1,v_actor);
  else
    update d5o_hosted.configuration_handoff_roles set
      receiving_role=p_role,revision=revision+1,configured_by=v_actor,updated_at=now()
      where configuration_version_id=p_version and route_key=p_route;
  end if;
  insert into d5o_hosted.handoff_route_events(workspace_id,configuration_version_id,
    route_key,revision,prior_role,receiving_role,actor_user_id,membership_id,command_id)
    values(v_workspace.id,p_version,p_route,p_expected_revision+1,
      v_route.receiving_role,p_role,v_actor,v_member.id,p_command_id);
  v_result:=pg_catalog.jsonb_build_object('key',p_route,'role',p_role,
    'revision',p_expected_revision+1,'configurationVersionId',p_version);
  insert into d5o_hosted.handoff_route_receipts(workspace_id,command_id,actor_user_id,fingerprint,result)
    values(v_workspace.id,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_correct_work_title_v1(p_workspace_key text, p_presentation_id text, p_command_id text, p_expected_record_version integer, p_expected_work_revision bigint, p_expected_catalog_revision bigint, p_expected_title text, p_new_title text, p_reason text, p_actor_user_id uuid, p_membership_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := p_actor_user_id;
  v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;
  v_link d5o_hosted.work_identity_links%rowtype;
  v_work d5o_hosted.work_records%rowtype;
  v_work_state d5o_hosted.prototype_states%rowtype;
  v_catalog_state d5o_hosted.prototype_states%rowtype;
  v_receipt d5o_hosted.work_command_receipts%rowtype;
  v_fingerprint text;
  v_new_work jsonb;
  v_new_catalog jsonb;
  v_result jsonb;
  v_now timestamptz := pg_catalog.now();
begin
  if current_setting('role',true) is distinct from 'service_role' or v_actor is null or p_membership_id is null then
    raise exception 'server_command_required' using errcode='42501'; end if;
  if p_workspace_key is null or p_presentation_id is null
    or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_expected_record_version is null or p_expected_record_version < 1
    or p_expected_work_revision is null or p_expected_work_revision < 1
    or p_expected_catalog_revision is null or p_expected_catalog_revision < 1
    or p_expected_title is null or length(pg_catalog.btrim(p_expected_title)) not between 1 and 240
    or p_new_title is null or length(pg_catalog.btrim(p_new_title)) not between 1 and 240
    or p_reason is null or length(pg_catalog.btrim(p_reason)) not between 10 and 500
    or pg_catalog.btrim(p_new_title)=pg_catalog.btrim(p_expected_title) then
    raise exception 'invalid_title_correction' using errcode='22023';
  end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:' || v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where id=p_membership_id and workspace_id=v_workspace.id and actor_user_id=v_actor and status='active'
      and role in ('admin','project_manager') for share;
  if not found then raise exception 'work_title_role_denied' using errcode='42501'; end if;
  select * into v_link from d5o_hosted.work_identity_links
    where workspace_id=v_workspace.id and presentation_id=p_presentation_id;
  if not found then raise exception 'work_not_found' using errcode='42501'; end if;
  select * into v_work from d5o_hosted.work_records
    where id=v_link.work_id and workspace_id=v_workspace.id for update;
  if not found then raise exception 'work_not_found' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_presentation_id,v_actor,p_membership_id,p_expected_record_version,
    p_expected_work_revision,p_expected_catalog_revision,p_expected_title,
    pg_catalog.btrim(p_new_title),pg_catalog.btrim(p_reason))::text);
  select * into v_receipt from d5o_hosted.work_command_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id is distinct from v_work.id
      or v_receipt.request_fingerprint is distinct from v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505';
    end if;
    return v_receipt.result;
  end if;
  if v_work.record_version <> p_expected_record_version
    or v_work.title is distinct from p_expected_title then
    raise exception 'stale_work_title' using errcode='23505'; end if;
  select * into v_work_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for update;
  select * into v_catalog_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='catalog' for update;
  if not found or v_work_state.revision <> p_expected_work_revision
    or v_catalog_state.revision <> p_expected_catalog_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  if (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_work_state.state_json->'records') r
      where r->>'id'=p_presentation_id and r->>'title'=p_expected_title
        and r->>'canonicalWorkId'=v_work.id::text) <> 1
    or (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_catalog_state.state_json->'records') r
      where r->>'id'=p_presentation_id and r->>'title'=p_expected_title
        and r->>'canonicalWorkId'=v_work.id::text) <> 1 then
    raise exception 'title_projection_mismatch' using errcode='23514';
  end if;
  select pg_catalog.jsonb_set(v_work_state.state_json,'{records}',
    pg_catalog.jsonb_agg(case when r->>'id'=p_presentation_id
      then pg_catalog.jsonb_set(r,'{title}',pg_catalog.to_jsonb(pg_catalog.btrim(p_new_title)))
      else r end order by ord))
    into v_new_work
    from pg_catalog.jsonb_array_elements(v_work_state.state_json->'records')
      with ordinality as records(r,ord);
  select pg_catalog.jsonb_set(v_catalog_state.state_json,'{records}',
    pg_catalog.jsonb_agg(case when r->>'id'=p_presentation_id
      then pg_catalog.jsonb_set(r,'{title}',pg_catalog.to_jsonb(pg_catalog.btrim(p_new_title)))
      else r end order by ord))
    into v_new_catalog
    from pg_catalog.jsonb_array_elements(v_catalog_state.state_json->'records')
      with ordinality as records(r,ord);
  v_new_work:=pg_catalog.jsonb_set(v_new_work,'{revision}',
    pg_catalog.to_jsonb(v_work_state.revision+1));
  v_new_catalog:=pg_catalog.jsonb_set(v_new_catalog,'{revision}',
    pg_catalog.to_jsonb(v_catalog_state.revision+1));
  update d5o_hosted.work_records set title=pg_catalog.btrim(p_new_title),
    record_version=record_version+1 where id=v_work.id;
  update d5o_hosted.prototype_states set revision=revision+1,
    state_json=v_new_work,updated_by=v_actor,updated_at=v_now
    where workspace_id=v_workspace.id and state_key='work';
  update d5o_hosted.prototype_states set revision=revision+1,
    state_json=v_new_catalog,updated_by=v_actor,updated_at=v_now
    where workspace_id=v_workspace.id and state_key='catalog';
  insert into d5o_hosted.prototype_state_revisions(
    workspace_id,state_key,revision,state_json,actor_user_id,membership_id)
  values(v_workspace.id,'work',v_work_state.revision+1,v_new_work,v_actor,v_member.id),
    (v_workspace.id,'catalog',v_catalog_state.revision+1,v_new_catalog,v_actor,v_member.id);
  insert into d5o_hosted.work_events(workspace_id,work_id,event_type,record_version,
    actor_user_id,membership_id,authority_role,configuration_version_id,
    configuration_digest,payload)
  values(v_workspace.id,v_work.id,'work_title_corrected',v_work.record_version+1,
    v_actor,v_member.id,v_member.role,v_work.configuration_version_id,
    v_work.configuration_digest,pg_catalog.jsonb_build_object(
      'oldTitle',v_work.title,'newTitle',pg_catalog.btrim(p_new_title),
      'reason',pg_catalog.btrim(p_reason),'presentationId',p_presentation_id));
  v_result:=pg_catalog.jsonb_build_object('presentationId',p_presentation_id,
    'oldTitle',v_work.title,'title',pg_catalog.btrim(p_new_title),
    'recordVersion',v_work.record_version+1,'workRevision',v_work_state.revision+1,
    'catalogRevision',v_catalog_state.revision+1);
  insert into d5o_hosted.work_command_receipts(
    workspace_id,command_id,request_fingerprint,work_id,result)
  values(v_workspace.id,p_command_id,v_fingerprint,v_work.id,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_correct_worker_binding_v1(p_workspace_key text, p_person_id uuid, p_new_email text, p_reason text, p_expected_revision integer, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;
  v_profile d5o_hosted.connected_crew_profiles%rowtype;
  v_state d5o_hosted.connected_workforce_states%rowtype;
  v_new_user uuid;v_prior d5o_hosted.admin_binding_corrections%rowtype;
  v_fingerprint text;v_result jsonb;
begin
  if current_setting('role',true) is distinct from 'authenticated' or v_actor is null
    or length(trim(coalesce(p_reason,''))) not between 12 and 500
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_binding_correction' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.actor_user_id=v_actor and m.status='active' and m.role='admin';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode='42501'; end if;
  select * into v_state from d5o_hosted.connected_workforce_states
    where workspace_id=v_workspace for update;
  if not found then raise exception 'workforce_missing' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_person_id,lower(trim(p_new_email)),trim(p_reason),p_expected_revision)::text);
  select * into v_prior from d5o_hosted.admin_binding_corrections
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    if v_prior.actor_user_id<>v_actor or v_prior.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return pg_catalog.jsonb_build_object('personId',p_person_id,
      'newUserId',v_prior.new_user_id,'revision',v_prior.workforce_revision,'replay',true);
  end if;
  if v_state.revision<>p_expected_revision then
    raise exception 'stale_workforce' using errcode='23505'; end if;
  select * into v_profile from d5o_hosted.connected_crew_profiles
    where workspace_id=v_workspace and id=p_person_id for update;
  if not found or v_profile.actor_user_id is null then
    raise exception 'current_binding_required' using errcode='23514'; end if;
  select id into v_new_user from auth.users
    where lower(email)=lower(trim(p_new_email)) and email_confirmed_at is not null;
  if v_new_user is null or v_new_user=v_actor or v_new_user=v_profile.actor_user_id then
    raise exception 'different_confirmed_account_required' using errcode='23503'; end if;
  if exists(select 1 from d5o_hosted.memberships m
      where m.workspace_id=v_workspace and m.actor_user_id=v_new_user
        and m.role<>'field_worker')
    or exists(select 1 from d5o_hosted.connected_crew_profiles p
      where p.workspace_id=v_workspace and p.actor_user_id=v_new_user)
    or exists(select 1 from d5o_hosted.crew_bindings b
      where b.workspace_id=v_workspace and b.actor_user_id=v_new_user) then
    raise exception 'replacement_account_already_bound' using errcode='23505'; end if;
  if exists(select 1 from d5o_hosted.connected_schedule_states s,
      lateral pg_catalog.jsonb_array_elements(coalesce(s.state->'assignments','[]'::jsonb)) a
      where s.workspace_id=v_workspace and a->'people' ? v_profile.person
        and (a->>'date')::date>=current_date)
    or exists(select 1 from d5o_hosted.connected_schedule_states s,
      lateral pg_catalog.jsonb_array_elements(coalesce(s.state->'publications','[]'::jsonb))
        with ordinality pub(value,position),
      lateral pg_catalog.jsonb_array_elements(coalesce(pub.value->'assignments','[]'::jsonb)) a
      where s.workspace_id=v_workspace and a->'people' ? v_profile.person
        and (a->>'date')::date>=current_date
        and not exists(select 1 from pg_catalog.jsonb_array_elements(
          coalesce(s.state->'publications','[]'::jsonb))
          with ordinality newer(value,position)
          where newer.value->>'week'=pub.value->>'week'
            and newer.position>pub.position)) then
    raise exception 'future_booking_requires_schedule_correction' using errcode='23514'; end if;
  update d5o_hosted.memberships set status='suspended'
    where workspace_id=v_workspace and actor_user_id=v_profile.actor_user_id
      and role='field_worker';
  delete from d5o_hosted.crew_bindings where workspace_id=v_workspace
    and actor_user_id=v_profile.actor_user_id and person=v_profile.person;
  insert into d5o_hosted.memberships(workspace_id,actor_user_id,role,status)
    values(v_workspace,v_new_user,'field_worker','active')
    on conflict(workspace_id,actor_user_id) do update set status='active'
      where d5o_hosted.memberships.role='field_worker';
  insert into d5o_hosted.crew_bindings(workspace_id,actor_user_id,person,active)
    values(v_workspace,v_new_user,v_profile.person,v_profile.active);
  update d5o_hosted.connected_crew_profiles set actor_user_id=v_new_user,revision=revision+1
    where workspace_id=v_workspace and id=p_person_id;
  update d5o_hosted.connected_workforce_states set revision=revision+1
    where workspace_id=v_workspace;
  insert into d5o_hosted.admin_binding_corrections
    (workspace_id,command_id,person_id,old_user_id,new_user_id,actor_user_id,
      reason,fingerprint,workforce_revision)
    values(v_workspace,p_command_id,p_person_id,v_profile.actor_user_id,v_new_user,
      v_actor,trim(p_reason),v_fingerprint,v_state.revision+1);
  v_result:=pg_catalog.jsonb_build_object('personId',p_person_id,
    'newUserId',v_new_user,'revision',v_state.revision+1);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_create_connected_package_v2(p_workspace_key text, p_presentation_id text, p_name text, p_owner text, p_command_id text, p_expected_work_revision bigint, p_expected_catalog_revision bigint, p_expected_handoff_revision integer, p_expected_package_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_work_state d5o_hosted.prototype_states%rowtype;
  v_catalog d5o_hosted.prototype_states%rowtype;
  v_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_receipt d5o_hosted.connected_package_receipts%rowtype;
  v_fingerprint text;v_id text;v_package jsonb;v_result jsonb;
  v_record jsonb;v_count integer;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or length(trim(coalesce(p_name,''))) not between 3 and 120
    or length(trim(coalesce(p_owner,''))) not between 2 and 120
    or p_expected_work_revision is null or p_expected_work_revision<1
    or p_expected_catalog_revision is null or p_expected_catalog_revision<1
    or p_expected_handoff_revision is null or p_expected_handoff_revision<1
    or p_expected_package_count is null or p_expected_package_count<0 then
    raise exception 'invalid_package_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('admin','project_manager','operations_leader') then
    raise exception 'package_editor_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,trim(p_name),trim(p_owner),p_expected_work_revision,
    p_expected_catalog_revision,p_expected_handoff_revision,p_expected_package_count)::text);
  select * into v_receipt from d5o_hosted.connected_package_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_work_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_catalog from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='catalog' for share;
  select * into v_handoff from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select count(*) into v_count from d5o_hosted.connected_package_states
    where workspace_id=v_workspace.id and work_id=v_work.id;
  v_count:=v_count+(select count(*) from pg_catalog.jsonb_array_elements(
    coalesce(v_catalog.state_json->'packages','[]'::jsonb)) item
    where item->>'workId'=p_presentation_id);
  if v_work_state.revision is distinct from p_expected_work_revision
    or v_catalog.revision is distinct from p_expected_catalog_revision
    or v_count<>p_expected_package_count
    or v_count>=500 or v_handoff.status is distinct from 'accepted'
    or v_handoff.revision<>p_expected_handoff_revision then
    raise exception 'stale_package_basis' using errcode='23505'; end if;
  select item into v_record from pg_catalog.jsonb_array_elements(
    v_work_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_record is null or v_record->>'phaseConfigurationVersionId' is distinct from
      v_work.configuration_version_id::text
    or v_handoff.handoff#>>'{brief,configurationVersionId}' is distinct from
      v_work.configuration_version_id::text
    or not exists(select 1 from pg_catalog.jsonb_array_elements(
      v_catalog.state_json->'records') item where item->>'id'=p_presentation_id
        and item->>'canonicalWorkId'=v_work.id::text) then
    raise exception 'package_source_unavailable' using errcode='23514'; end if;
  v_id:='wp-'||pg_catalog.replace(gen_random_uuid()::text,'-','');
  v_package:=pg_catalog.jsonb_build_object('id',v_id,'workId',p_presentation_id,
    'name',trim(p_name),'owner',trim(p_owner),'installed',0,'tested',0,
    'accepted',0,'status','planned','createdAt',now(),
    'createdBy',v_actor,'sourceHandoffRevision',v_handoff.revision);
  insert into d5o_hosted.connected_package_states(workspace_id,work_id,
    package_id,snapshot,created_by)
  values(v_workspace.id,v_work.id,v_id,v_package,v_actor);
  v_result:=pg_catalog.jsonb_build_object('created',v_package,
    'workRevision',v_work_state.revision,
    'catalogRevision',v_catalog.revision,
    'packageCount',v_count+1,'canonicalWorkId',v_work.id);
  insert into d5o_hosted.connected_package_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_create_connected_work_v1(p_workspace_key text, p_command_id text, p_expected_work_revision bigint, p_expected_catalog_revision bigint, p_configuration_version_id uuid, p_work_type_key text, p_title text, p_customer text, p_site text, p_owner text, p_actor_user_id uuid, p_membership_id uuid, p_initial_discovery jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace d5o_hosted.workspaces%rowtype;
  v_membership d5o_hosted.memberships%rowtype;
  v_tenant d5o_hosted.configuration_tenants%rowtype;
  v_version d5o_hosted.configuration_versions%rowtype;
  v_type d5o_hosted.configuration_work_types%rowtype;
  v_work_state d5o_hosted.prototype_states%rowtype;
  v_catalog_state d5o_hosted.prototype_states%rowtype;
  v_receipt d5o_hosted.connected_create_receipts%rowtype;
  v_work_id uuid := gen_random_uuid();
  v_alias text;
  v_fingerprint text;
  v_now timestamptz := now();
  v_record jsonb;
  v_catalog_record jsonb;
  v_next_work jsonb;
  v_next_catalog jsonb;
  v_result jsonb;
begin
  if current_setting('role', true) is distinct from 'service_role'
    or p_actor_user_id is null or p_membership_id is null then
    raise exception 'server_command_required' using errcode='42501';
  end if;
  if p_command_id is null or length(p_command_id) not between 8 and 120
    or p_expected_work_revision is null or p_expected_work_revision < 0
    or p_expected_catalog_revision is null or p_expected_catalog_revision < 0
    or p_configuration_version_id is null or p_work_type_key is null
    or p_title is null or length(trim(p_title)) not between 1 and 240
    or p_customer is null or length(trim(p_customer)) not between 1 and 200
    or p_site is null or length(trim(p_site)) not between 1 and 200
    or p_owner is null or length(trim(p_owner)) not between 1 and 120 then
    raise exception 'invalid_connected_work' using errcode='22023';
  end if;
  if p_initial_discovery is not null and (
    pg_catalog.jsonb_typeof(p_initial_discovery) <> 'object'
    or p_initial_discovery - 'source' - 'need' - 'procurement' - 'closeDate' <> '{}'::jsonb
    or length(coalesce(p_initial_discovery->>'source','')) not between 1 and 120
    or length(coalesce(p_initial_discovery->>'need','')) not between 1 and 3000
    or length(coalesce(p_initial_discovery->>'procurement','')) not between 1 and 120
    or length(coalesce(p_initial_discovery->>'closeDate','')) > 10) then
    raise exception 'invalid_discover_draft' using errcode='22023';
  end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:' || v_workspace.id::text, 0));
  select * into v_membership from d5o_hosted.memberships
    where id=p_membership_id and workspace_id=v_workspace.id
      and actor_user_id=p_actor_user_id and status='active' for share;
  if not found or v_membership.role not in
    ('admin','project_manager','business_development_lead','operations_leader') then
    raise exception 'create_authority_denied' using errcode='42501';
  end if;
  v_fingerprint := pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_configuration_version_id,p_work_type_key,
    trim(p_title),trim(p_customer),trim(p_site),trim(p_owner),p_initial_discovery)::text);
  select * into v_receipt from d5o_hosted.connected_create_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id is distinct from p_actor_user_id
      or v_receipt.request_fingerprint is distinct from v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505';
    end if;
    return v_receipt.result;
  end if;
  select * into v_tenant from d5o_hosted.configuration_tenants
    where workspace_id=v_workspace.id and status='active';
  if not found or (select count(*) from d5o_hosted.configuration_tenants
      where workspace_id=v_workspace.id and status='active') <> 1 then
    raise exception 'configuration_mapping_unavailable' using errcode='22023';
  end if;
  select * into v_version from d5o_hosted.configuration_versions
    where id=p_configuration_version_id and tenant_id=v_tenant.id
      and status='published' and effective_from<=v_now
      and (effective_to is null or effective_to>v_now);
  if not found then raise exception 'configuration_or_right_unavailable' using errcode='42501'; end if;
  select * into v_type from d5o_hosted.configuration_work_types
    where configuration_version_id=v_version.id
      and work_type_key=p_work_type_key and status='active';
  if not found or not exists (
    select 1 from d5o_hosted.configuration_create_rights
      where configuration_version_id=v_version.id
        and work_type_key=p_work_type_key
        and workspace_role=v_membership.role) then
    raise exception 'configuration_or_right_unavailable' using errcode='42501';
  end if;
  select * into v_work_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for update;
  select * into v_catalog_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='catalog' for update;
  if coalesce(v_work_state.revision,0) <> p_expected_work_revision
    or coalesce(v_catalog_state.revision,0) <> p_expected_catalog_revision then
    raise exception 'stale_state' using errcode='23505';
  end if;
  if (v_work_state.revision is not null and
      pg_catalog.jsonb_typeof(v_work_state.state_json->'records') <> 'array')
    or (v_catalog_state.revision is not null and
      pg_catalog.jsonb_typeof(v_catalog_state.state_json->'records') <> 'array') then
    raise exception 'invalid_state' using errcode='22023';
  end if;
  v_alias := p_workspace_key || '-' || pg_catalog.replace(v_work_id::text,'-','');
  insert into d5o_hosted.work_records(id,workspace_id,configuration_tenant_id,
    configuration_version_id,configuration_digest,work_type_key,title,created_by)
  values(v_work_id,v_workspace.id,v_tenant.id,v_version.id,v_version.source_sha256,
    p_work_type_key,trim(p_title),p_actor_user_id);
  insert into d5o_hosted.work_events(workspace_id,work_id,event_type,record_version,
    actor_user_id,membership_id,authority_role,configuration_version_id,
    configuration_digest,payload)
  values(v_workspace.id,v_work_id,'work_created',1,p_actor_user_id,p_membership_id,
    v_membership.role,v_version.id,v_version.source_sha256,
    pg_catalog.jsonb_build_object('title',trim(p_title),'customer',trim(p_customer),
      'site',trim(p_site),'workTypeKey',p_work_type_key,'presentationId',v_alias));
  insert into d5o_hosted.work_identity_links(workspace_id,work_id,presentation_id)
    values(v_workspace.id,v_work_id,v_alias);
  v_catalog_record := pg_catalog.jsonb_build_object(
    'id',v_alias,'canonicalWorkId',v_work_id,'workspace',p_workspace_key,
    'title',trim(p_title),'type',v_type.display_name,'customer',trim(p_customer),
    'site',trim(p_site),'stage','Plan','owner',trim(p_owner),
    'nextAction','Complete Discover intake','progress',8,'value','Unpriced',
    'status','moving','proof','[]'::jsonb,'blockers','[]'::jsonb,
    'history',pg_catalog.jsonb_build_array('Work Record started'),
    'phaseConfigurationVersionId',v_version.id,'createdAt',v_now,'createdBy',p_actor_user_id);
  if p_initial_discovery is not null then
    v_catalog_record := pg_catalog.jsonb_set(v_catalog_record,'{nextAction}',
      pg_catalog.to_jsonb('Qualify customer need'::text));
  end if;
  v_record := v_catalog_record - 'createdAt' - 'createdBy';
  if p_initial_discovery is not null then
    v_record := v_record || pg_catalog.jsonb_build_object(
      'nextAction','Qualify customer need','discovery',pg_catalog.jsonb_build_object(
        'source',p_initial_discovery->>'source','need',p_initial_discovery->>'need',
        'procurement',p_initial_discovery->>'procurement','closeDate',p_initial_discovery->>'closeDate',
        'phase','Qualification','fit','Unassessed',
        'estimate',pg_catalog.jsonb_build_object('revision',0,'labor',0,'materials',0,
          'subcontract',0,'travel',0,'contingency',0,'targetMargin',25,
          'sellPrice',0,'status','Not started','assumption',''),
        'proposal',pg_catalog.jsonb_build_object('status','Not started','dueDate','',
          'method','Customer portal','recipient','','response',''),
        'pursuitControl',pg_catalog.jsonb_build_object('revision',0,'status','draft',
          'requester','','intendedOutcome','','roughValue','','currency','USD',
          'requiredDate','','knownRisk','','spend',pg_catalog.jsonb_build_object(
            'status','not_requested','cap',0,'purpose',''),'handoff',pg_catalog.jsonb_build_object(
            'status','not_started','receiver','','brief','','revision',0),
          'history','[]'::jsonb)));
  end if;
  v_next_work := coalesce(v_work_state.state_json,pg_catalog.jsonb_build_object(
    'schemaVersion',1,'workspace',p_workspace_key,'records','[]'::jsonb));
  v_next_catalog := coalesce(v_catalog_state.state_json,pg_catalog.jsonb_build_object(
    'schemaVersion',1,'workspace',p_workspace_key,'records','[]'::jsonb,'packages','[]'::jsonb));
  v_next_work := pg_catalog.jsonb_set(v_next_work,'{records}',
    coalesce(v_next_work->'records','[]'::jsonb) || pg_catalog.jsonb_build_array(v_record));
  v_next_catalog := pg_catalog.jsonb_set(v_next_catalog,'{records}',
    coalesce(v_next_catalog->'records','[]'::jsonb) || pg_catalog.jsonb_build_array(v_catalog_record));
  v_next_work := pg_catalog.jsonb_set(v_next_work,'{revision}',
    pg_catalog.to_jsonb(coalesce(v_work_state.revision,0)+1));
  v_next_catalog := pg_catalog.jsonb_set(v_next_catalog,'{revision}',
    pg_catalog.to_jsonb(coalesce(v_catalog_state.revision,0)+1));
  insert into d5o_hosted.prototype_states(workspace_id,state_key,revision,state_json,updated_by)
    values(v_workspace.id,'work',1,v_next_work,p_actor_user_id)
    on conflict(workspace_id,state_key) do update set
      revision=d5o_hosted.prototype_states.revision+1,state_json=excluded.state_json,
      updated_by=p_actor_user_id,updated_at=v_now;
  insert into d5o_hosted.prototype_states(workspace_id,state_key,revision,state_json,updated_by)
    values(v_workspace.id,'catalog',1,v_next_catalog,p_actor_user_id)
    on conflict(workspace_id,state_key) do update set
      revision=d5o_hosted.prototype_states.revision+1,state_json=excluded.state_json,
      updated_by=p_actor_user_id,updated_at=v_now;
  insert into d5o_hosted.prototype_state_revisions(
    workspace_id,state_key,revision,state_json,actor_user_id,membership_id)
  values(v_workspace.id,'work',coalesce(v_work_state.revision,0)+1,v_next_work,p_actor_user_id,p_membership_id),
    (v_workspace.id,'catalog',coalesce(v_catalog_state.revision,0)+1,v_next_catalog,p_actor_user_id,p_membership_id);
  v_result := pg_catalog.jsonb_build_object(
    'workId',v_work_id,'presentationId',v_alias,'workRevision',coalesce(v_work_state.revision,0)+1,
    'catalogRevision',coalesce(v_catalog_state.revision,0)+1,
    'configurationVersionId',v_version.id,'recordVersion',1);
  insert into d5o_hosted.connected_create_receipts(
    workspace_id,command_id,actor_user_id,request_fingerprint,work_id,result)
  values(v_workspace.id,p_command_id,p_actor_user_id,v_fingerprint,v_work_id,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_create_related_work_v1(p_workspace_key text, p_command_id text, p_action text, p_parent_presentation_id text, p_expected_work_revision bigint, p_expected_catalog_revision bigint, p_parent_after jsonb, p_child jsonb, p_actor_user_id uuid, p_membership_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace d5o_hosted.workspaces%rowtype;
  v_membership d5o_hosted.memberships%rowtype;
  v_parent_link d5o_hosted.work_identity_links%rowtype;
  v_parent d5o_hosted.work_records%rowtype;
  v_work d5o_hosted.prototype_states%rowtype;
  v_catalog d5o_hosted.prototype_states%rowtype;
  v_receipt d5o_hosted.connected_create_receipts%rowtype;
  v_before jsonb; v_child jsonb; v_catalog_child jsonb;
  v_after_work jsonb; v_after_catalog jsonb;
  v_child_id uuid; v_alias text; v_kind text; v_fingerprint text;
  v_event jsonb; v_job jsonb; v_result jsonb; v_work_type_key text;
  v_old_operate jsonb; v_new_operate jsonb; v_action_label text;
  v_item jsonb; v_match jsonb; v_target jsonb;
begin
  if current_setting('role',true) is distinct from 'service_role' then
    raise exception 'server_command_required' using errcode='42501'; end if;
  if p_action not in ('create-job','generate-maintenance','open-lifecycle')
    or p_command_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or pg_catalog.jsonb_typeof(p_parent_after) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_child) is distinct from 'object'
    or p_expected_work_revision < 1 or p_expected_catalog_revision < 1 then
    raise exception 'invalid_related_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_membership from d5o_hosted.memberships
    where id=p_membership_id and workspace_id=v_workspace.id
      and actor_user_id=p_actor_user_id and status='active' for share;
  if not found or v_membership.role not in ('admin','operations_leader','project_manager') then
    raise exception 'related_work_authority_denied' using errcode='42501'; end if;
  select * into v_parent_link from d5o_hosted.work_identity_links
    where workspace_id=v_workspace.id and presentation_id=p_parent_presentation_id;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  select * into v_parent from d5o_hosted.work_records
    where id=v_parent_link.work_id and workspace_id=v_workspace.id for share;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_alias := p_workspace_key||'-'||pg_catalog.replace(p_command_id,'-','');
  v_child_id := p_command_id::uuid;
  if p_child->>'id' is distinct from v_alias
    or p_child->>'workspace' is distinct from p_workspace_key
    or p_child->>'phaseConfigurationVersionId' is distinct from v_parent.configuration_version_id::text
    or p_child->>'customer' is distinct from (select item->>'customer'
      from d5o_hosted.prototype_states s,
        lateral pg_catalog.jsonb_array_elements(s.state_json->'records') item
      where s.workspace_id=v_workspace.id and s.state_key='work'
        and item->>'id'=p_parent_presentation_id limit 1)
    or p_child->'design' is not null or p_child->'deploy' is not null
    or p_child->'operate' is not null or p_child->>'status'='complete' then
    raise exception 'related_work_identity_invalid' using errcode='22023'; end if;
  v_kind := case when p_action='open-lifecycle' then 'lifecycle_opportunity'
    else 'service_visit' end;
  v_fingerprint := pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_action,p_parent_presentation_id,p_parent_after,p_child)::text);
  select * into v_receipt from d5o_hosted.connected_create_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id is distinct from p_actor_user_id
      or v_receipt.request_fingerprint is distinct from v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_work from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for update;
  select * into v_catalog from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='catalog' for update;
  if v_work.revision is distinct from p_expected_work_revision
    or v_catalog.revision is distinct from p_expected_catalog_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_before from pg_catalog.jsonb_array_elements(v_work.state_json->'records') item
    where item->>'id'=p_parent_presentation_id;
  if v_before is null or v_before->>'canonicalWorkId' is distinct from v_parent.id::text
    or p_parent_after->>'id' is distinct from p_parent_presentation_id
    or p_parent_after->>'canonicalWorkId' is distinct from v_parent.id::text
    or p_parent_after - 'operate' - 'history' is distinct from v_before - 'operate' - 'history'
    or pg_catalog.jsonb_typeof(p_parent_after->'history') is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_parent_after->'history')
       <> pg_catalog.jsonb_array_length(coalesce(v_before->'history','[]'::jsonb))+1
    or (p_parent_after->'history') - 0 is distinct from coalesce(v_before->'history','[]'::jsonb)
    or pg_catalog.jsonb_typeof(p_parent_after->'operate') is distinct from 'object' then
    raise exception 'related_parent_changed' using errcode='42501'; end if;
  v_old_operate := v_before->'operate'; v_new_operate := p_parent_after->'operate';
  v_event := v_new_operate#>'{events,0}';
  v_action_label := case p_action when 'create-job' then 'Service job generated'
    when 'generate-maintenance' then 'Maintenance job generated'
    else 'Lifecycle opportunity opened' end;
  if v_event->>'commandId' is distinct from p_command_id
    or v_event->>'actorId' is distinct from p_actor_user_id::text
    or v_event->>'membershipId' is distinct from p_membership_id::text
    or v_event->>'action' is distinct from v_action_label
    or pg_catalog.jsonb_array_length(coalesce(v_new_operate->'events','[]'::jsonb))
       <> pg_catalog.jsonb_array_length(coalesce(v_old_operate->'events','[]'::jsonb))+1
    or (v_new_operate->'events') - 0 is distinct from coalesce(v_old_operate->'events','[]'::jsonb) then
    raise exception 'related_command_event_invalid' using errcode='42501'; end if;
  if p_action='open-lifecycle' then
    v_match := v_new_operate#>'{lifecycleLinks,-1}';
    if v_new_operate - 'events' - 'lifecycleLinks'
       is distinct from v_old_operate - 'events' - 'lifecycleLinks'
      or pg_catalog.jsonb_array_length(v_new_operate->'lifecycleLinks')
       <> pg_catalog.jsonb_array_length(coalesce(v_old_operate->'lifecycleLinks','[]'::jsonb))+1
      or (v_new_operate->'lifecycleLinks') -
        (pg_catalog.jsonb_array_length(v_new_operate->'lifecycleLinks')-1)
        is distinct from coalesce(v_old_operate->'lifecycleLinks','[]'::jsonb)
      or v_new_operate#>>'{lifecycleLinks,-1,opportunityWorkId}' is distinct from v_alias
      or p_child#>>'{discovery,source}' is distinct from 'Lifecycle referral'
      or nullif(pg_catalog.btrim(v_match->>'rationale'),'') is null
      or p_child#>>'{discovery,need}' is distinct from v_match->>'rationale'
      or p_child->>'owner' is distinct from v_match->>'owner'
      or p_child->>'stage' is distinct from 'Qualification'
      or p_child->'serviceSource' is not null then
      raise exception 'related_lifecycle_invalid' using errcode='42501'; end if;
    if (v_match->>'assetId' is not null and not exists (
        select 1 from pg_catalog.jsonb_array_elements(v_old_operate->'assets') item
          where item->>'id'=v_match->>'assetId'))
      or (v_match->>'requestId' is not null and not exists (
        select 1 from pg_catalog.jsonb_array_elements(v_old_operate->'requests') item
          where item->>'id'=v_match->>'requestId'
            and (v_match->>'assetId' is null or item->>'assetId'=v_match->>'assetId'))) then
      raise exception 'related_lifecycle_source_invalid' using errcode='42501'; end if;
  else
    v_job := v_new_operate#>'{jobs,-1}';
    if v_old_operate#>>'{activation,status}' is distinct from 'Active'
      or v_new_operate - 'events' - 'jobs' - 'requests' - 'maintenance'
        is distinct from v_old_operate - 'events' - 'jobs' - 'requests' - 'maintenance'
      or pg_catalog.jsonb_array_length(v_new_operate->'jobs')
        <> pg_catalog.jsonb_array_length(coalesce(v_old_operate->'jobs','[]'::jsonb))+1
      or (v_new_operate->'jobs') -
        (pg_catalog.jsonb_array_length(v_new_operate->'jobs')-1)
        is distinct from coalesce(v_old_operate->'jobs','[]'::jsonb)
      or v_job->>'workId' is distinct from v_alias
      or v_job->>'status' is distinct from 'Generated'
      or p_child->>'stage' is distinct from 'Design'
      or p_child#>>'{serviceSource,parentWorkId}' is distinct from p_parent_presentation_id
      or p_child#>'{serviceSource,assetIds}' is distinct from v_job->'assetIds'
      or p_child#>>'{serviceSource,requestId}' is distinct from v_job->>'requestId'
      or p_child#>>'{serviceSource,maintenancePlanId}' is distinct from v_job->>'planId' then
      raise exception 'related_service_invalid' using errcode='42501'; end if;
    if p_action='create-job' then
      if v_job->>'requestId' is null or v_job->>'planId' is not null
        or v_new_operate->'maintenance' is distinct from v_old_operate->'maintenance'
        or pg_catalog.jsonb_array_length(v_new_operate->'requests')
          <> pg_catalog.jsonb_array_length(v_old_operate->'requests') then
        raise exception 'related_request_invalid' using errcode='42501'; end if;
      select item into v_target from pg_catalog.jsonb_array_elements(v_old_operate->'requests') item
        where item->>'id'=v_job->>'requestId';
      if v_target is null or v_target->>'status' not in ('Triaged','In progress')
        or v_target->>'coverage' not in ('Covered','Partially covered','Chargeable')
        or v_job->'assetIds' is distinct from pg_catalog.jsonb_build_array(v_target->>'assetId') then
        raise exception 'related_request_not_authorized' using errcode='42501'; end if;
      for v_item in select value from pg_catalog.jsonb_array_elements(v_old_operate->'requests') loop
        select item into v_match from pg_catalog.jsonb_array_elements(v_new_operate->'requests') item
          where item->>'id'=v_item->>'id';
        if v_match is null then raise exception 'related_request_changed' using errcode='42501'; end if;
        if v_item->>'id'=v_job->>'requestId' then
          if v_match - 'status' - 'jobIds' - 'currentCycleJobIds'
              is distinct from v_item - 'status' - 'jobIds' - 'currentCycleJobIds'
            or v_match->>'status' is distinct from 'In progress'
            or v_match->'jobIds' is distinct from
              coalesce(v_item->'jobIds','[]'::jsonb)||pg_catalog.jsonb_build_array(v_job->'id')
            or v_match->'currentCycleJobIds' is distinct from
              coalesce(v_item->'currentCycleJobIds',coalesce(v_item->'jobIds','[]'::jsonb))
                ||pg_catalog.jsonb_build_array(v_job->'id') then
            raise exception 'related_request_changed' using errcode='42501'; end if;
        elsif v_match is distinct from v_item then
          raise exception 'unrelated_request_changed' using errcode='42501'; end if;
      end loop;
    else
      if v_job->>'planId' is null or v_job->>'requestId' is not null
        or v_new_operate->'requests' is distinct from v_old_operate->'requests'
        or pg_catalog.jsonb_array_length(v_new_operate->'maintenance')
          <> pg_catalog.jsonb_array_length(v_old_operate->'maintenance') then
        raise exception 'related_plan_invalid' using errcode='42501'; end if;
      select item into v_target from pg_catalog.jsonb_array_elements(v_old_operate->'maintenance') item
        where item->>'id'=v_job->>'planId';
      if v_target is null or v_target->>'status' is distinct from 'Active'
        or v_job->>'dueDate' is distinct from v_target->>'nextDue'
        or v_job->'assetIds' is distinct from pg_catalog.jsonb_build_array(v_target->>'assetId')
        or (v_target->>'nextDue')::date > current_date then
        raise exception 'related_plan_not_due' using errcode='42501'; end if;
      for v_item in select value from pg_catalog.jsonb_array_elements(v_old_operate->'maintenance') loop
        select item into v_match from pg_catalog.jsonb_array_elements(v_new_operate->'maintenance') item
          where item->>'id'=v_item->>'id';
        if v_match is null then raise exception 'related_plan_changed' using errcode='42501'; end if;
        if v_item->>'id'=v_job->>'planId' then
          if v_match - 'generatedDates' - 'nextDue'
              is distinct from v_item - 'generatedDates' - 'nextDue'
            or v_match->'generatedDates' is distinct from
              coalesce(v_item->'generatedDates','[]'::jsonb)
                ||pg_catalog.jsonb_build_array(v_job->'dueDate') then
            raise exception 'related_plan_changed' using errcode='42501'; end if;
        elsif v_match is distinct from v_item then
          raise exception 'unrelated_plan_changed' using errcode='42501'; end if;
      end loop;
    end if;
  end if;
  if exists(select 1 from pg_catalog.jsonb_array_elements(v_work.state_json->'records') item
      where item->>'id'=v_alias)
    or exists(select 1 from pg_catalog.jsonb_array_elements(v_catalog.state_json->'records') item
      where item->>'id'=v_alias) then
    raise exception 'related_work_conflict' using errcode='23505'; end if;
  select work_type_key into v_work_type_key from d5o_hosted.configuration_work_types
    where configuration_version_id=v_parent.configuration_version_id
      and display_name=p_child->>'type' and status='active' limit 1;
  if v_work_type_key is null then raise exception 'related_work_type_unavailable' using errcode='22023'; end if;
  insert into d5o_hosted.work_records(id,workspace_id,configuration_tenant_id,
    configuration_version_id,configuration_digest,work_type_key,title,created_by)
  values(v_child_id,v_workspace.id,v_parent.configuration_tenant_id,
    v_parent.configuration_version_id,v_parent.configuration_digest,v_work_type_key,
    p_child->>'title',p_actor_user_id);
  insert into d5o_hosted.work_identity_links(workspace_id,work_id,presentation_id,
    parent_work_id,relation_kind)
  values(v_workspace.id,v_child_id,v_alias,v_parent.id,v_kind);
  v_child := pg_catalog.jsonb_set(p_child,'{canonicalWorkId}',pg_catalog.to_jsonb(v_child_id::text));
  v_catalog_child := pg_catalog.jsonb_build_object('id',v_alias,
    'canonicalWorkId',v_child_id,'workspace',p_workspace_key,
    'title',v_child->>'title','type',v_child->>'type',
    'customer',v_child->>'customer','site',v_child->>'site',
    'stage',v_child->>'stage','owner',v_child->>'owner',
    'nextAction',v_child->>'nextAction','progress',v_child->'progress',
    'value',v_child->>'value','status',v_child->>'status',
    'proof',coalesce(v_child->'proof','[]'::jsonb),
    'blockers',coalesce(v_child->'blockers','[]'::jsonb),
    'history',coalesce(v_child->'history','[]'::jsonb),
    'phaseConfigurationVersionId',v_parent.configuration_version_id,
    'createdAt',now(),'createdBy',p_actor_user_id);
  v_after_work := pg_catalog.jsonb_set(v_work.state_json,'{records}',
    (select pg_catalog.jsonb_agg(case when item->>'id'=p_parent_presentation_id
      then p_parent_after else item end)
      from pg_catalog.jsonb_array_elements(v_work.state_json->'records') item)
      || pg_catalog.jsonb_build_array(v_child));
  v_after_work := pg_catalog.jsonb_set(v_after_work,'{revision}',
    pg_catalog.to_jsonb(v_work.revision+1));
  v_after_catalog := pg_catalog.jsonb_set(v_catalog.state_json,'{records}',
    v_catalog.state_json->'records'||pg_catalog.jsonb_build_array(v_catalog_child));
  v_after_catalog := pg_catalog.jsonb_set(v_after_catalog,'{revision}',
    pg_catalog.to_jsonb(v_catalog.revision+1));
  update d5o_hosted.prototype_states set revision=revision+1,
    state_json=v_after_work,updated_by=p_actor_user_id,updated_at=now()
    where workspace_id=v_workspace.id and state_key='work';
  update d5o_hosted.prototype_states set revision=revision+1,
    state_json=v_after_catalog,updated_by=p_actor_user_id,updated_at=now()
    where workspace_id=v_workspace.id and state_key='catalog';
  insert into d5o_hosted.prototype_state_revisions(workspace_id,state_key,
    revision,state_json,actor_user_id,membership_id)
  values(v_workspace.id,'work',v_work.revision+1,v_after_work,p_actor_user_id,p_membership_id),
    (v_workspace.id,'catalog',v_catalog.revision+1,v_after_catalog,p_actor_user_id,p_membership_id);
  insert into d5o_hosted.work_events(workspace_id,work_id,event_type,
    record_version,actor_user_id,membership_id,authority_role,
    configuration_version_id,configuration_digest,payload)
  values(v_workspace.id,v_child_id,'work_created',1,p_actor_user_id,
    p_membership_id,v_membership.role,v_parent.configuration_version_id,
    v_parent.configuration_digest,pg_catalog.jsonb_build_object(
      'parentWorkId',v_parent.id,'relationKind',v_kind,
      'presentationId',v_alias,'commandId',p_command_id));
  v_result := pg_catalog.jsonb_build_object('workId',v_child_id,
    'presentationId',v_alias,'workRevision',v_work.revision+1,
    'catalogRevision',v_catalog.revision+1,'parentWorkId',v_parent.id,
    'relationKind',v_kind);
  insert into d5o_hosted.connected_create_receipts(workspace_id,command_id,
    actor_user_id,request_fingerprint,work_id,result)
  values(v_workspace.id,p_command_id,p_actor_user_id,v_fingerprint,v_child_id,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_create_service_package_v1(p_workspace_key text, p_presentation_id text, p_name text, p_owner text, p_command_id text, p_expected_work_revision bigint, p_expected_catalog_revision bigint, p_expected_basis_revision integer, p_expected_package_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_service d5o_hosted.connected_service_work%rowtype;
  v_work_state d5o_hosted.prototype_states%rowtype;
  v_catalog d5o_hosted.prototype_states%rowtype;
  v_basis d5o_hosted.connected_design_handoffs%rowtype;
  v_receipt d5o_hosted.connected_package_receipts%rowtype;
  v_fingerprint text;v_id text;v_package jsonb;v_result jsonb;
  v_count integer;v_source jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or length(trim(coalesce(p_name,''))) not between 3 and 120
    or length(trim(coalesce(p_owner,''))) not between 2 and 120
    or p_expected_work_revision is null or p_expected_work_revision<1
    or p_expected_catalog_revision is null or p_expected_catalog_revision<1
    or p_expected_basis_revision is null or p_expected_basis_revision<1
    or p_expected_package_count is null or p_expected_package_count<0 then
    raise exception 'invalid_service_package_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role<>'project_manager' then
    raise exception 'service_package_editor_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
      and l.relation_kind='service_visit' for update of w;
  if not found then raise exception 'service_work_unavailable' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,trim(p_name),trim(p_owner),p_expected_work_revision,
    p_expected_catalog_revision,p_expected_basis_revision,p_expected_package_count)::text);
  select * into v_receipt from d5o_hosted.connected_package_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_work_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_catalog from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='catalog' for share;
  select * into v_basis from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_service from d5o_hosted.connected_service_work
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select count(*) into v_count from d5o_hosted.connected_package_states
    where workspace_id=v_workspace.id and work_id=v_work.id;
  if v_work_state.revision is distinct from p_expected_work_revision
    or v_catalog.revision is distinct from p_expected_catalog_revision
    or v_count<>p_expected_package_count or v_count>=500
    or v_basis.source_kind is distinct from 'service'
    or v_basis.status is distinct from 'accepted'
    or v_basis.revision<>p_expected_basis_revision
    or v_service.work_id is null
    or v_service.work_projection->>'canonicalWorkId' is distinct from v_work.id::text
    or v_service.work_projection->>'phaseConfigurationVersionId' is distinct from
      v_work.configuration_version_id::text then
    raise exception 'stale_service_package_basis' using errcode='23505'; end if;
  v_source:=d5o_hosted.current_service_source_v1(v_workspace.id,v_work.id);
  if v_basis.source_digest<>pg_catalog.md5(v_source::text)
    or v_basis.handoff#>>'{brief,configurationVersionId}' is distinct from
      v_work.configuration_version_id::text then
    raise exception 'service_source_changed' using errcode='23514'; end if;
  v_id:='wp-'||pg_catalog.replace(gen_random_uuid()::text,'-','');
  v_package:=pg_catalog.jsonb_build_object('id',v_id,'workId',p_presentation_id,
    'name',trim(p_name),'owner',trim(p_owner),'installed',0,'tested',0,
    'accepted',0,'status','planned','createdAt',now(),
    'createdBy',v_actor,'sourceKind','service',
    'sourceId',v_basis.handoff->>'id','sourceHandoffRevision',v_basis.revision);
  insert into d5o_hosted.connected_package_states(workspace_id,work_id,
    package_id,snapshot,created_by)
  values(v_workspace.id,v_work.id,v_id,v_package,v_actor);
  v_result:=pg_catalog.jsonb_build_object('created',v_package,
    'workRevision',v_work_state.revision,'catalogRevision',v_catalog.revision,
    'packageCount',v_count+1,'canonicalWorkId',v_work.id);
  insert into d5o_hosted.connected_package_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_create_work_core_v1(p_workspace_key text, p_command_id text, p_configuration_version_id uuid, p_work_type_key text, p_title text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace d5o_hosted.workspaces%rowtype;
  v_membership d5o_hosted.memberships%rowtype;
  v_tenant d5o_hosted.configuration_tenants%rowtype;
  v_version d5o_hosted.configuration_versions%rowtype;
  v_count integer;
  v_fingerprint text;
  v_receipt d5o_hosted.work_command_receipts%rowtype;
  v_work_id uuid := gen_random_uuid();
  v_result jsonb;
begin
  if v_actor is null or p_workspace_key is null or p_configuration_version_id is null
      or p_work_type_key is null or p_command_id is null
      or length(p_command_id) not between 8 and 120
      or p_title is null or length(trim(p_title)) not between 1 and 240 then
    raise exception 'invalid_work_command' using errcode = '22023';
  end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key = p_workspace_key and status = 'active';
  if not found then raise exception 'workspace_forbidden' using errcode = '42501'; end if;
  select * into v_membership from d5o_hosted.memberships
    where workspace_id = v_workspace.id and actor_user_id = v_actor and status = 'active';
  if not found or v_membership.role = 'read_only_auditor' then
    raise exception 'workspace_forbidden' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('d5o-hosted-work:' || v_workspace.id::text, 0));
  v_fingerprint := pg_catalog.md5(p_configuration_version_id::text || ':' ||
    p_work_type_key || ':' || trim(p_title));
  select * into v_receipt from d5o_hosted.work_command_receipts
    where workspace_id = v_workspace.id and command_id = p_command_id;
  if found then
    if v_receipt.request_fingerprint <> v_fingerprint then
      raise exception 'command_id_reused' using errcode = '23505';
    end if;
    return v_receipt.result;
  end if;
  select count(*) into v_count from d5o_hosted.configuration_tenants
    where workspace_id = v_workspace.id and status = 'active';
  if v_count = 0 then raise exception 'no_tenant_mapping' using errcode = '22023'; end if;
  if v_count <> 1 then raise exception 'ambiguous_tenant_mapping' using errcode = '22023'; end if;
  select * into v_tenant from d5o_hosted.configuration_tenants
    where workspace_id = v_workspace.id and status = 'active';
  select * into v_version from d5o_hosted.configuration_versions
    where id = p_configuration_version_id and tenant_id = v_tenant.id
      and status = 'published' and effective_from <= now()
      and (effective_to is null or effective_to > now());
  if not found then raise exception 'configuration_unavailable' using errcode = '22023'; end if;
  if not exists (select 1 from d5o_hosted.configuration_work_types
      where configuration_version_id = v_version.id
        and work_type_key = p_work_type_key and status = 'active') then
    raise exception 'incompatible_work_type' using errcode = '22023';
  end if;
  insert into d5o_hosted.work_records(id, workspace_id, configuration_tenant_id,
    configuration_version_id, configuration_digest, work_type_key, title, created_by)
  values(v_work_id, v_workspace.id, v_tenant.id, v_version.id,
    v_version.source_sha256, p_work_type_key, trim(p_title), v_actor);
  insert into d5o_hosted.work_events(workspace_id, work_id, event_type, record_version,
    actor_user_id, membership_id, authority_role, configuration_version_id,
    configuration_digest, payload)
  values(v_workspace.id, v_work_id, 'work_created', 1, v_actor, v_membership.id,
    v_membership.role, v_version.id, v_version.source_sha256,
    pg_catalog.jsonb_build_object('title', trim(p_title), 'workTypeKey', p_work_type_key));
  v_result := pg_catalog.jsonb_build_object('workId', v_work_id, 'workspaceId', v_workspace.id,
    'recordVersion', 1, 'configurationVersionId', v_version.id,
    'configurationDigest', v_version.source_sha256);
  insert into d5o_hosted.work_command_receipts(workspace_id, command_id,
    request_fingerprint, work_id, result)
  values(v_workspace.id, p_command_id, v_fingerprint, v_work_id, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_create_work_v1(p_workspace_key text, p_command_id text, p_configuration_version_id uuid, p_work_type_key text, p_title text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace d5o_hosted.workspaces%rowtype;
  v_membership d5o_hosted.memberships%rowtype;
  v_tenant d5o_hosted.configuration_tenants%rowtype;
  v_version d5o_hosted.configuration_versions%rowtype;
  v_count integer;
  v_retry boolean;
begin
  if v_actor is null or p_workspace_key is null or p_configuration_version_id is null
      or p_work_type_key is null or p_command_id is null
      or length(p_command_id) not between 8 and 120
      or p_title is null or length(trim(p_title)) not between 1 and 240 then
    raise exception 'invalid_work_command' using errcode = '22023';
  end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key = p_workspace_key and status = 'active' for share;
  if not found then raise exception 'workspace_forbidden' using errcode = '42501'; end if;
  select * into v_membership from d5o_hosted.memberships
    where workspace_id = v_workspace.id and actor_user_id = v_actor
      and status = 'active' for share;
  if not found or v_membership.role = 'read_only_auditor' then
    raise exception 'workspace_forbidden' using errcode = '42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-hosted-work:' || v_workspace.id::text, 0));
  lock table d5o_hosted.configuration_tenants,
    d5o_hosted.configuration_versions,
    d5o_hosted.configuration_work_types,
    d5o_hosted.configuration_create_rights in share mode;
  select count(*) into v_count from d5o_hosted.configuration_tenants
    where workspace_id = v_workspace.id and status = 'active';
  if v_count = 0 then raise exception 'no_tenant_mapping' using errcode = '22023'; end if;
  if v_count <> 1 then raise exception 'ambiguous_tenant_mapping' using errcode = '22023'; end if;
  select * into v_tenant from d5o_hosted.configuration_tenants
    where workspace_id = v_workspace.id and status = 'active';
  select exists(select 1 from d5o_hosted.work_command_receipts
    where workspace_id = v_workspace.id and command_id = p_command_id) into v_retry;
  select * into v_version from d5o_hosted.configuration_versions
    where id = p_configuration_version_id and tenant_id = v_tenant.id
      and (status = 'published' or (v_retry and status = 'superseded'))
      and (v_retry or (effective_from <= now()
        and (effective_to is null or effective_to > now())));
  if not found then raise exception 'configuration_unavailable' using errcode = '22023'; end if;
  if not exists (select 1 from d5o_hosted.configuration_work_types
      where configuration_version_id = v_version.id
        and work_type_key = p_work_type_key and status = 'active') then
    raise exception 'incompatible_work_type' using errcode = '22023';
  end if;
  if not exists (select 1 from d5o_hosted.configuration_create_rights
      where configuration_version_id = v_version.id
        and work_type_key = p_work_type_key
        and workspace_role = v_membership.role) then
    raise exception 'create_authority_denied' using errcode = '42501';
  end if;
  return public.d5o_hosted_create_work_core_v1(p_workspace_key, p_command_id,
    p_configuration_version_id, p_work_type_key, p_title);
end;
$function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_crew_command_internal_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;
  v_receipt d5o_hosted.connected_schedule_receipts%rowtype;
  v_profile d5o_hosted.connected_crew_profiles%rowtype;
  v_binding d5o_hosted.crew_bindings%rowtype;
  v_work d5o_hosted.work_records%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_assignment jsonb;v_demand jsonb;v_package jsonb;v_state jsonb;
  v_publication jsonb;v_previous jsonb;v_prior_assignment jsonb;
  v_prior_receipt jsonb;v_prior_demand jsonb;v_current_demand jsonb;
  v_item jsonb;v_person text;v_id text;
  v_fingerprint text;v_result jsonb;v_now timestamptz:=now();
  v_week integer;v_day integer;v_date date;v_anchor date;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-booking','publish-week','respond-booking')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_crew_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'crew_membership_required' using errcode='42501'; end if;
  insert into d5o_hosted.connected_schedule_states(workspace_id,decision_revision,state)
    values(v_workspace.id,1,pg_catalog.jsonb_build_object(
      'anchorDate',to_char(date_trunc('week',v_now),'YYYY-MM-DD'),
      'draftRevision',1,'assignments','[]'::jsonb,
      'publications','[]'::jsonb,'receipts','[]'::jsonb))
    on conflict(workspace_id) do nothing;
  select * into v_schedule from d5o_hosted.connected_schedule_states
    where workspace_id=v_workspace.id for update;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_action,p_input,p_expected_revision)::text);
  select * into v_receipt from d5o_hosted.connected_schedule_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  if v_schedule.decision_revision<>p_expected_revision and not
    (v_schedule.decision_revision=1 and p_expected_revision=0 and
      v_schedule.state->'assignments'='[]'::jsonb and
      v_schedule.state->'publications'='[]'::jsonb) then
    raise exception 'stale_schedule' using errcode='23505'; end if;
  v_state:=v_schedule.state;v_anchor:=(v_state->>'anchorDate')::date;
  if p_action='save-booking' then
    if v_member.role not in ('admin','project_manager','operations_leader') then
      raise exception 'scheduling_authority_required' using errcode='42501'; end if;
    v_assignment:=p_input->'assignment';
    if pg_catalog.jsonb_typeof(v_assignment)<>'object'
      or length(coalesce(v_assignment->>'id','')) not between 5 and 100
      or pg_catalog.jsonb_typeof(v_assignment->'people')<>'array'
      or pg_catalog.jsonb_array_length(v_assignment->'people')=0
      or coalesce(v_assignment->>'crew','')=''
      or coalesce(v_assignment->>'shift','') !~ '^\d\d:\d\d[–-]\d\d:\d\d$'
      or coalesce(v_assignment->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'invalid_booking' using errcode='22023'; end if;
    v_week:=(v_assignment->>'week')::integer;
    v_day:=(v_assignment->>'day')::integer;
    v_date:=(v_assignment->>'date')::date;
    if v_week not between -260 and 260 or v_day not between 0 and 4
      or v_date<>v_anchor+v_week*7+v_day then
      raise exception 'booking_date_mismatch' using errcode='23514'; end if;
    select w.* into v_work from d5o_hosted.work_records w
      join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
        and l.work_id=w.id
      where w.workspace_id=v_workspace.id
        and l.presentation_id=v_assignment->>'workId' for share of w;
    if not found then raise exception 'booking_work_unavailable' using errcode='23514'; end if;
    select * into v_design from d5o_hosted.connected_design_states
      where workspace_id=v_workspace.id and work_id=v_work.id for share;
    select d into v_demand from pg_catalog.jsonb_array_elements(
      coalesce(v_design.state->'demands','[]'::jsonb)) d
      where d->>'packageId'=v_assignment->>'packageId'
        and d->>'workId'=v_assignment->>'workId';
    select p into v_package from pg_catalog.jsonb_array_elements(
      coalesce(v_design.state->'packages','[]'::jsonb)) p
      where p->>'packageId'=v_assignment->>'packageId';
    -- A draft may precede release, but must still match the current engineered demand.
    -- Publication below continues to require an accepted release of that same revision.
    if v_demand is null or v_package is null
      or v_demand->>'designPackageRevision'<>v_package->>'revision'
      or not exists(select 1 from pg_catalog.jsonb_array_elements(
        v_demand->'requiredSlots') s where s->>'date'=v_assignment->>'date'
        and s->>'shift'=v_assignment->>'shift')
      or pg_catalog.jsonb_array_length(v_assignment->'people')<
        (v_demand->>'minimumPeople')::integer then
      raise exception 'current_demand_coverage_required' using errcode='23514'; end if;
    if (select count(distinct p#>>'{}') from pg_catalog.jsonb_array_elements(
      v_assignment->'people') p)<>
      pg_catalog.jsonb_array_length(v_assignment->'people') then
      raise exception 'duplicate_crew_person' using errcode='23514'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_assignment->'people') loop
      v_person:=v_item#>>'{}';
      select cp.* into v_profile from d5o_hosted.connected_crew_profiles cp
        join d5o_hosted.crew_bindings b on b.workspace_id=cp.workspace_id
          and b.actor_user_id=cp.actor_user_id and b.person=cp.person and b.active
        join d5o_hosted.memberships m on m.workspace_id=cp.workspace_id
          and m.actor_user_id=cp.actor_user_id and m.status='active'
        where cp.workspace_id=v_workspace.id and cp.person=v_person
          and cp.active and v_demand->>'qualification'=any(cp.qualifications);
      if not found then raise exception 'qualified_bound_worker_required' using errcode='23514'; end if;
      if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'assignments') a
        where a->>'id'<>v_assignment->>'id'
          and a->>'date'=v_assignment->>'date'
          and a->'people' ? v_person) then
        raise exception 'crew_overlap' using errcode='23514'; end if;
    end loop;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'assignments') a
      where a->>'id'=v_assignment->>'id' and
        (a->>'workId'<>v_assignment->>'workId' or
          a->>'packageId'<>v_assignment->>'packageId')) then
      raise exception 'booking_scope_changed' using errcode='23514'; end if;
    v_assignment:=pg_catalog.jsonb_build_object(
      'id',v_assignment->>'id','crew',v_assignment->>'crew',
      'people',v_assignment->'people','workId',v_assignment->>'workId',
      'packageId',v_assignment->>'packageId','week',v_week,'day',v_day,
      'date',v_date,'shift',v_assignment->>'shift') ||
      case when v_assignment ? 'personHoursPerWorker'
        then pg_catalog.jsonb_build_object('personHoursPerWorker',v_assignment->'personHoursPerWorker')
        else '{}'::jsonb end;
    v_state:=pg_catalog.jsonb_set(v_state,'{assignments}',
      (select coalesce(pg_catalog.jsonb_agg(a order by ordinal),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(v_state->'assignments')
          with ordinality as entries(a,ordinal)
        where a->>'id'<>v_assignment->>'id')||
      pg_catalog.jsonb_build_array(v_assignment));
    v_state:=pg_catalog.jsonb_set(v_state,'{draftRevision}',
      pg_catalog.to_jsonb((v_state->>'draftRevision')::integer+1));
  elsif p_action='publish-week' then
    if v_member.role not in ('admin','project_manager','operations_leader') then
      raise exception 'publication_authority_required' using errcode='42501'; end if;
    v_week:=(p_input->>'week')::integer;
    if v_week is null or v_week not between -260 and 260 then
      raise exception 'invalid_publication_week' using errcode='22023'; end if;
    select pub into v_previous from pg_catalog.jsonb_array_elements(
      v_state->'publications') with ordinality entries(pub,ordinal)
      where (pub->>'week')::integer=v_week order by ordinal desc limit 1;
    -- An empty publication withdraws the last published booking from this week.
    -- It cannot invent an empty week or repeat an already withdrawn one.
    if not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'assignments') a
      where (a->>'week')::integer=v_week)
      and (v_previous is null or v_previous->'assignments'='[]'::jsonb) then
      raise exception 'empty_publication' using errcode='23514'; end if;
    for v_assignment in select a from pg_catalog.jsonb_array_elements(
      v_state->'assignments') a where (a->>'week')::integer=v_week loop
      select w.* into v_work from d5o_hosted.work_records w
        join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
          and l.work_id=w.id
        where w.workspace_id=v_workspace.id
          and l.presentation_id=v_assignment->>'workId' for share of w;
      select * into v_design from d5o_hosted.connected_design_states
        where workspace_id=v_workspace.id and work_id=v_work.id for share;
      select d into v_demand from pg_catalog.jsonb_array_elements(
        coalesce(v_design.state->'demands','[]'::jsonb)) d
        where d->>'packageId'=v_assignment->>'packageId';
      select p into v_package from pg_catalog.jsonb_array_elements(
        coalesce(v_design.state->'packages','[]'::jsonb)) p
        where p->>'packageId'=v_assignment->>'packageId';
      if v_work.id is null or v_demand is null or v_package is null
        or v_demand->>'designPackageRevision'<>v_package->>'revision'
        or not exists(select 1 from
        pg_catalog.jsonb_array_elements(v_design.state->'releases') r
        where r->>'packageId'=v_assignment->>'packageId'
          and r->>'status'='Accepted'
          and r->>'packageRevision'=v_demand->>'designPackageRevision') then
        raise exception 'release_changed_before_publication' using errcode='23514'; end if;
      for v_item in select p from pg_catalog.jsonb_array_elements(
        v_assignment->'people') p loop
        v_person:=v_item#>>'{}';
        if not exists(select 1 from d5o_hosted.connected_crew_profiles cp
          join d5o_hosted.crew_bindings b on b.workspace_id=cp.workspace_id
            and b.actor_user_id=cp.actor_user_id and b.active
          join d5o_hosted.memberships m on m.workspace_id=cp.workspace_id
            and m.actor_user_id=cp.actor_user_id and m.status='active'
          where cp.workspace_id=v_workspace.id and cp.person=v_person
            and cp.active and v_demand->>'qualification'=any(cp.qualifications)) then
          raise exception 'crew_qualification_changed_before_publication' using errcode='23514'; end if;
      end loop;
    end loop;
    v_id:=gen_random_uuid()::text;
    v_publication:=pg_catalog.jsonb_build_object('id',v_id,'week',v_week,
      'weekStart',v_anchor+v_week*7,
      'draftRevision',v_state->'draftRevision','publishedAt',v_now,
      'publishedBy',pg_catalog.jsonb_build_object('id',v_actor,
        'name',v_actor::text,'role',v_member.role),
      'assignments',(select coalesce(pg_catalog.jsonb_agg(a order by ordinal),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(v_state->'assignments')
          with ordinality as entries(a,ordinal)
        where (a->>'week')::integer=v_week),
      'packageDemands',coalesce((select pg_catalog.jsonb_agg(d.value)
        from d5o_hosted.connected_design_states ds
        cross join lateral pg_catalog.jsonb_array_elements(
          coalesce(ds.state->'demands','[]'::jsonb)) d
        where ds.workspace_id=v_workspace.id and exists(
          select 1 from pg_catalog.jsonb_array_elements(v_state->'assignments') a
          where (a->>'week')::integer=v_week
            and a->>'packageId'=d.value->>'packageId')),'[]'::jsonb));
    if v_previous is not null and v_previous->'assignments'=v_publication->'assignments' then
      raise exception 'week_already_published' using errcode='23514'; end if;
    if v_previous is not null then
      for v_assignment in select a from pg_catalog.jsonb_array_elements(
        v_publication->'assignments') a loop
        select a into v_prior_assignment from pg_catalog.jsonb_array_elements(
          v_previous->'assignments') a where a->>'id'=v_assignment->>'id';
        if v_prior_assignment is distinct from v_assignment then continue; end if;
        select d into v_prior_demand from pg_catalog.jsonb_array_elements(
          coalesce(v_previous->'packageDemands','[]'::jsonb)) d
          where d->>'packageId'=v_assignment->>'packageId';
        select d into v_current_demand from pg_catalog.jsonb_array_elements(
          coalesce(v_publication->'packageDemands','[]'::jsonb)) d
          where d->>'packageId'=v_assignment->>'packageId';
        if v_prior_demand is null or v_current_demand is null
          or v_prior_demand is distinct from v_current_demand then continue; end if;
        for v_item in select p from pg_catalog.jsonb_array_elements(
          v_assignment->'people') p loop
          v_person:=v_item#>>'{}';
          select r into v_prior_receipt from pg_catalog.jsonb_array_elements(
            v_state->'receipts') r where r->>'publicationId'=v_previous->>'id'
              and r->>'assignmentId'=v_assignment->>'id'
              and r->>'recipient'=v_person;
          if v_prior_receipt is null then continue; end if;
          v_state:=pg_catalog.jsonb_set(v_state,'{receipts}',
            v_state->'receipts'||pg_catalog.jsonb_build_array(
              v_prior_receipt||pg_catalog.jsonb_build_object(
                'id',gen_random_uuid(),'publicationId',v_id,
                'source','carried','carriedFromReceiptId',v_prior_receipt->>'id',
                'statement','The worker response remains valid because this booking did not change in the revised schedule.')));
        end loop;
      end loop;
    end if;
    v_state:=pg_catalog.jsonb_set(v_state,'{publications}',
      v_state->'publications'||pg_catalog.jsonb_build_array(v_publication));
  else
    select * into v_binding from d5o_hosted.crew_bindings
      where workspace_id=v_workspace.id and actor_user_id=v_actor and active;
    if not found or v_member.role not in ('field_worker','field_supervisor') then
      raise exception 'worker_binding_required' using errcode='42501'; end if;
    v_id:=p_input->>'publicationId';
    select pub into v_publication from pg_catalog.jsonb_array_elements(
      v_state->'publications') pub where pub->>'id'=v_id;
    select a into v_assignment from pg_catalog.jsonb_array_elements(
      coalesce(v_publication->'assignments','[]'::jsonb)) a
      where a->>'id'=p_input->>'assignmentId'
        and a->'people' ? v_binding.person;
    if v_assignment is null or p_input->>'response' not in
      ('acknowledged','cannot-attend') or exists(select 1 from
        pg_catalog.jsonb_array_elements(v_state->'receipts') r
        where r->>'publicationId'=v_id
          and r->>'assignmentId'=p_input->>'assignmentId'
          and r->>'recipient'=v_binding.person) then
      raise exception 'worker_response_invalid' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'publications') pub
      where (pub->>'week')::integer=(v_publication->>'week')::integer
        and pub->>'publishedAt'>v_publication->>'publishedAt') then
      raise exception 'publication_superseded' using errcode='23514'; end if;
    v_state:=pg_catalog.jsonb_set(v_state,'{receipts}',
      v_state->'receipts'||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('id',gen_random_uuid(),
          'publicationId',v_id,'assignmentId',p_input->>'assignmentId',
          'recipient',v_binding.person,'recordedAt',v_now,
          'recordedBy',pg_catalog.jsonb_build_object('id',v_actor,
            'name',v_binding.person,'role',v_member.role),
          'statement','Worker response to exact published booking',
          'source','self','response',p_input->>'response')));
  end if;
  update d5o_hosted.connected_schedule_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id;
  insert into d5o_hosted.connected_schedule_events(workspace_id,decision_revision,
    command_id,action,actor_user_id,membership_id,snapshot)
  values(v_workspace.id,v_schedule.decision_revision+1,p_command_id,
    p_action,v_actor,v_member.id,v_state);
  if p_action='respond-booking' then
    v_result:=pg_catalog.jsonb_build_object('person',v_binding.person,
      'revision',v_schedule.decision_revision+1,
      'state',pg_catalog.jsonb_build_object('workspace',p_workspace_key,
        'schemaVersion',1,'anchorDate',v_state->'anchorDate',
        'revision',v_schedule.decision_revision+1,
        'draftRevision',v_state->'draftRevision',
        'assignments',(select coalesce(pg_catalog.jsonb_agg(a),'[]'::jsonb)
          from pg_catalog.jsonb_array_elements(v_state->'assignments') a
          where a->'people' ? v_binding.person),
        'availabilityBlocks','[]'::jsonb,'packageDemands','[]'::jsonb,
        'publications',(select coalesce(pg_catalog.jsonb_agg(
          (pub-'packageDemands')||pg_catalog.jsonb_build_object('assignments',
            (select pg_catalog.jsonb_agg(a) from pg_catalog.jsonb_array_elements(
              pub->'assignments') a where a->'people' ? v_binding.person))),
          '[]'::jsonb)
          from pg_catalog.jsonb_array_elements(v_state->'publications') pub
          where exists(select 1 from pg_catalog.jsonb_array_elements(
            pub->'assignments') a where a->'people' ? v_binding.person)),
        'receipts',(select coalesce(pg_catalog.jsonb_agg(r),'[]'::jsonb)
          from pg_catalog.jsonb_array_elements(v_state->'receipts') r
          where r->>'recipient'=v_binding.person)));
  else v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'schedule'); end if;
  insert into d5o_hosted.connected_schedule_receipts(workspace_id,command_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_crew_command_pre_binding_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text; schedule d5o_hosted.connected_schedule_states%rowtype;
 result jsonb; item jsonb; publication jsonb; person_item jsonb; demand jsonb; release_row jsonb;
 intent d5o_hosted.labor_booking_intents%rowtype; authority d5o_hosted.labor_authorities%rowtype;
 parent d5o_hosted.purchase_authorities%rowtype; v_work_id uuid; person_user uuid;
 source jsonb; hours numeric(8,2); cost bigint; used bigint; digest text; week_start date;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'crew_membership_required' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 if ws is null or role_name is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if p_action not in ('save-booking','publish-week') then
  return public.d5o_hosted_crew_command_pre_labor_v1(
   p_workspace_key,p_action,p_input,p_command_id,p_expected_revision); end if;
 if role_name not in ('admin','project_manager','operations_leader') then
  raise exception 'scheduling_authority_required' using errcode='42501'; end if;
 -- The original receipt owns replay identity; do not re-evaluate or mutate labor.
 if exists(select 1 from d5o_hosted.connected_schedule_receipts
  where workspace_id=ws and command_id=p_command_id) then
  return public.d5o_hosted_crew_command_pre_labor_v1(
   p_workspace_key,p_action,p_input,p_command_id,p_expected_revision); end if;
 if p_action='save-booking' then
  result:=public.d5o_hosted_crew_command_pre_labor_v1(
   p_workspace_key,p_action,p_input,p_command_id,p_expected_revision);
  select * into schedule from d5o_hosted.connected_schedule_states where workspace_id=ws;
  select value into item from pg_catalog.jsonb_array_elements(schedule.state->'assignments')
   where value->>'id'=p_input#>>'{assignment,id}';
  select l.work_id into v_work_id from d5o_hosted.work_identity_links l
   where l.workspace_id=ws and l.presentation_id=item->>'workId';
  if item is null or v_work_id is null then
   raise exception 'booking_labor_source_unavailable' using errcode='23514'; end if;
  select * into intent from d5o_hosted.labor_booking_intents
   where workspace_id=ws and assignment_id=item->>'id';
  if p_input->'assignment' ? 'personHoursPerWorker' then
   if coalesce(p_input#>>'{assignment,personHoursPerWorker}','') !~ '^\d+(\.\d{1,2})?$'
    or (p_input#>>'{assignment,personHoursPerWorker}')::numeric<=0
    or (p_input#>>'{assignment,personHoursPerWorker}')::numeric>24 then
    raise exception 'authorized_person_hours_invalid' using errcode='22023'; end if;
   hours:=(p_input#>>'{assignment,personHoursPerWorker}')::numeric;
  elsif intent.workspace_id is not null and intent.work_id=v_work_id
    and intent.package_id=item->>'packageId' then
   hours:=intent.person_hours_per_worker;
  else
   raise exception 'authorized_person_hours_required' using errcode='23514';
  end if;
  insert into d5o_hosted.labor_booking_intents(workspace_id,assignment_id,work_id,package_id,
   assignment_digest,person_hours_per_worker,schedule_revision,prepared_by)
   values(ws,item->>'id',v_work_id,item->>'packageId',pg_catalog.md5(item::text),
    hours,schedule.decision_revision,actor)
   on conflict(workspace_id,assignment_id) do update set
    work_id=excluded.work_id,package_id=excluded.package_id,
    assignment_digest=excluded.assignment_digest,
    person_hours_per_worker=excluded.person_hours_per_worker,
    schedule_revision=excluded.schedule_revision,prepared_by=excluded.prepared_by,prepared_at=now();  return result;
 end if;
 -- A Work lock is taken before the existing schedule lock. All affected Works
 -- are locked in stable order; PO, subcontract and Design use this same row.
 select * into schedule from d5o_hosted.connected_schedule_states where workspace_id=ws;
 if schedule.workspace_id is null then
  raise exception 'empty_publication' using errcode='23514'; end if;
 for v_work_id in select distinct l.work_id from d5o_hosted.work_identity_links l
  join lateral pg_catalog.jsonb_array_elements(schedule.state->'assignments') a on
   a->>'workId'=l.presentation_id and (a->>'week')::integer=(p_input->>'week')::integer
  where l.workspace_id=ws order by l.work_id loop
  perform 1 from d5o_hosted.work_records w
   where w.workspace_id=ws and w.id=v_work_id for update;
 end loop;
 result:=public.d5o_hosted_crew_command_pre_labor_v1(
  p_workspace_key,p_action,p_input,p_command_id,p_expected_revision);
 select * into schedule from d5o_hosted.connected_schedule_states where workspace_id=ws;
 select value into publication from pg_catalog.jsonb_array_elements(schedule.state->'publications')
  with ordinality as entries(value,ordinal)
  where (value->>'week')::integer=(p_input->>'week')::integer
  order by ordinal desc limit 1;
 if publication is null then raise exception 'publication_labor_basis_unavailable' using errcode='23514'; end if;
 week_start:=(publication->>'weekStart')::date;
 -- Supersede only unworked reservations on the replaced week. Reviewed costs
 -- remain consumed and retain their original published assignment source.
 update d5o_hosted.labor_reservations r set status='Superseded',superseded_at=now()
  where r.workspace_id=ws and r.status='Active'
   and r.work_date>=week_start and r.work_date<week_start+7
   and not exists(select 1 from d5o_hosted.labor_actuals a where a.reservation_id=r.id)
   and not exists(select 1 from pg_catalog.jsonb_array_elements(publication->'assignments') a
    where a->>'id'=r.assignment_id and pg_catalog.md5(a::text)=r.assignment_digest
     and a->'people' ? r.person);
 for item in select value from pg_catalog.jsonb_array_elements(publication->'assignments') loop
  select l.work_id into v_work_id from d5o_hosted.work_identity_links l
   where l.workspace_id=ws and l.presentation_id=item->>'workId';
  select * into intent from d5o_hosted.labor_booking_intents
   where workspace_id=ws and assignment_id=item->>'id';
  digest:=pg_catalog.md5(item::text);
  if intent.workspace_id is null or intent.work_id<>v_work_id
   or intent.package_id<>item->>'packageId' or intent.assignment_digest<>digest then
   -- An unchanged historical publication retains its worker response. Do not
   -- fabricate a rate or consume new labor authority for its prior commitment.
   if intent.workspace_id is null and exists(
    select 1 from pg_catalog.jsonb_array_elements(schedule.state->'publications') old_pub
    cross join lateral pg_catalog.jsonb_array_elements(old_pub->'assignments') old_assignment
    where old_pub->>'id'<>publication->>'id' and old_assignment.value=item
     and exists(select 1 from d5o_hosted.connected_design_states ds
      cross join lateral pg_catalog.jsonb_array_elements(ds.state->'demands') current_demand
      where ds.workspace_id=ws and ds.work_id=v_work_id
       and current_demand.value->>'packageId'=item->>'packageId'
       and old_pub->'packageDemands' @> pg_catalog.jsonb_build_array(current_demand.value))) then
    continue;
   end if;
   raise exception 'authorized_person_hours_required' using errcode='23514'; end if;
  hours:=intent.person_hours_per_worker;
  source:=d5o_hosted.purchase_basis_v1(ws,v_work_id);
  select * into parent from d5o_hosted.purchase_authorities
   where workspace_id=ws and work_id=v_work_id and status='Approved'
    and source_digest=source->>'digest' and current_date between valid_from and valid_until
   order by created_at desc limit 1 for update;
  select * into authority from d5o_hosted.labor_authorities
   where workspace_id=ws and work_id=v_work_id and status='Approved'
    and parent_authority_id=parent.id and source_digest=source->>'digest'
    and (item->>'date')::date between valid_from and valid_until
   order by created_at desc limit 1;
  if authority.id is null then raise exception 'approved_labor_authority_required' using errcode='23514'; end if;
  select d.value into demand from d5o_hosted.connected_design_states ds,
   lateral pg_catalog.jsonb_array_elements(ds.state->'demands') d
   where ds.workspace_id=ws and ds.work_id=v_work_id
    and d->>'packageId'=item->>'packageId';
  select r.value into release_row from d5o_hosted.connected_design_states ds,
   lateral pg_catalog.jsonb_array_elements(ds.state->'releases') r
   where ds.workspace_id=ws and ds.work_id=v_work_id
    and r->>'packageId'=item->>'packageId' and r->>'status'='Accepted'
    and r->>'packageRevision'=demand->>'designPackageRevision'
   order by r->>'issuedAt' desc limit 1;
  if release_row is null then raise exception 'current_release_required' using errcode='23514'; end if;
  for person_item in select value from pg_catalog.jsonb_array_elements(item->'people') loop
   select b.actor_user_id into person_user from d5o_hosted.crew_bindings b
    where b.workspace_id=ws and b.person=person_item#>>'{}' and b.active;
   if person_user is null then raise exception 'qualified_bound_worker_required' using errcode='23514'; end if;
   if exists(select 1 from d5o_hosted.labor_reservations r where r.workspace_id=ws
    and r.assignment_id=item->>'id' and r.person=person_item#>>'{}' and r.status='Active'
    and r.assignment_digest=digest and r.authorized_hours=hours) then continue; end if;
   cost:=pg_catalog.round(hours*authority.rate_minor)::bigint;
   used:=d5o_hosted.labor_exposure_v1(ws,v_work_id);
   if used+cost>authority.cap_minor then
    raise exception 'labor_sublimit_exceeded' using errcode='23514'; end if;
   insert into d5o_hosted.labor_reservations(workspace_id,work_id,labor_authority_id,
    publication_id,assignment_id,assignment_digest,person,person_user_id,package_id,
    design_revision,demand_revision,release_id,work_date,shift,authorized_hours,
    rate_minor,amount_minor,currency,status,approved_by)
    values(ws,v_work_id,authority.id,publication->>'id',item->>'id',digest,person_item#>>'{}',
     person_user,item->>'packageId',
     (select decision_revision from d5o_hosted.connected_design_states
       where workspace_id=ws and work_id=v_work_id),
     (demand->>'designPackageRevision')::integer,release_row->>'id',
     (item->>'date')::date,item->>'shift',hours,authority.rate_minor,cost,'USD','Active',actor);
  end loop;
 end loop;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_crew_command_pre_labor_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_role text;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;v_assignment jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'crew_membership_required' using errcode='42501'; end if;
  select w.id,m.role into v_workspace,v_role from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.actor_user_id=v_actor and m.status='active';
  if v_workspace is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  if p_action in ('save-booking','publish-week') then
    if v_role not in ('admin','project_manager','operations_leader') then
      raise exception 'scheduling_authority_required' using errcode='42501'; end if;
    -- Replay is resolved by the original command before current eligibility is re-evaluated.
    if exists(select 1 from d5o_hosted.connected_schedule_receipts
      where workspace_id=v_workspace and command_id=p_command_id) then
      return public.d5o_hosted_crew_command_internal_v1(
        p_workspace_key,p_action,p_input,p_command_id,p_expected_revision);
    end if;
    select * into v_schedule from d5o_hosted.connected_schedule_states
      where workspace_id=v_workspace for update;
    if found then
      if v_schedule.decision_revision<>p_expected_revision and not
        (v_schedule.decision_revision=1 and p_expected_revision=0 and
          v_schedule.state->'assignments'='[]'::jsonb and
          v_schedule.state->'publications'='[]'::jsonb) then
        raise exception 'stale_schedule' using errcode='23505'; end if;
      if p_action='save-booking' then
        v_assignment:=p_input->'assignment';
        if pg_catalog.jsonb_typeof(v_assignment)='object'
          and pg_catalog.jsonb_typeof(v_assignment->'people')='array' then
          perform d5o_hosted.crew_booking_eligibility_v1(v_workspace,v_schedule.state,v_assignment);
        end if;
      else
        for v_assignment in select a from pg_catalog.jsonb_array_elements(
          coalesce(v_schedule.state->'assignments','[]'::jsonb)) a
          where (a->>'week')::integer=(p_input->>'week')::integer loop
          perform d5o_hosted.crew_booking_eligibility_v1(v_workspace,v_schedule.state,v_assignment);
        end loop;
      end if;
    end if;
  end if;
  return public.d5o_hosted_crew_command_internal_v1(
    p_workspace_key,p_action,p_input,p_command_id,p_expected_revision);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_crew_command_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_binding d5o_hosted.crew_bindings%rowtype;
  v_publication jsonb;v_state jsonb;
begin
  if p_action='respond-booking' then
    if current_setting('role',true)<>'authenticated' or v_actor is null then
      raise exception 'worker_auth_required' using errcode='42501'; end if;
    select b.* into v_binding from d5o_hosted.crew_bindings b
      join d5o_hosted.workspaces w on w.id=b.workspace_id
      join d5o_hosted.memberships m on m.workspace_id=w.id
        and m.actor_user_id=v_actor and m.status='active'
        and m.role in ('field_worker','field_supervisor')
      where w.workspace_key=p_workspace_key and w.status='active'
        and b.actor_user_id=v_actor and b.active;
    if not found then raise exception 'worker_binding_required' using errcode='42501'; end if;
    select s.state into v_state from d5o_hosted.connected_schedule_states s
      where s.workspace_id=v_binding.workspace_id;
    select pub.value into v_publication from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'publications','[]'::jsonb)) pub(value)
      where pub.value->>'id'=p_input->>'publicationId';
    if v_publication is not null and
      (v_publication->>'publishedAt')::timestamptz < v_binding.created_at then
      raise exception 'publication_precedes_account_binding' using errcode='23514'; end if;
  end if;
  return public.d5o_hosted_crew_command_pre_binding_v1(
    p_workspace_key,p_action,p_input,p_command_id,p_expected_revision);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_crew_profile_command_v1(p_workspace_key text, p_person text, p_qualifications text[], p_weekly_capacity_hours numeric, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_binding d5o_hosted.crew_bindings%rowtype;
  v_previous d5o_hosted.connected_crew_profile_events%rowtype;
  v_fingerprint text;v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or length(trim(coalesce(p_person,''))) not between 2 and 120
    or cardinality(p_qualifications) not between 1 and 20
    or p_weekly_capacity_hours<=0 or p_weekly_capacity_hours>80 then
    raise exception 'invalid_crew_profile_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor
      and status='active' and role='admin' for share;
  if not found then raise exception 'admin_profile_authority_required' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_person,p_qualifications,p_weekly_capacity_hours)::text);
  select * into v_previous from d5o_hosted.connected_crew_profile_events
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_previous.actor_user_id<>v_actor or v_previous.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_previous.snapshot; end if;
  select b.* into v_binding from d5o_hosted.crew_bindings b
    join d5o_hosted.memberships m on m.workspace_id=b.workspace_id
      and m.actor_user_id=b.actor_user_id and m.status='active'
      and m.role='field_worker'
    where b.workspace_id=v_workspace.id and b.person=trim(p_person)
      and b.active for update of b;
  if not found or exists(select 1 from unnest(p_qualifications) q
    where length(trim(q))<2 or length(trim(q))>100) then
    raise exception 'bound_worker_and_qualification_required' using errcode='23514'; end if;
  insert into d5o_hosted.connected_crew_profiles(workspace_id,actor_user_id,
    person,qualifications,weekly_capacity_hours)
  values(v_workspace.id,v_binding.actor_user_id,v_binding.person,
    p_qualifications,p_weekly_capacity_hours)
  on conflict(workspace_id,actor_user_id) do update set
    qualifications=excluded.qualifications,
    weekly_capacity_hours=excluded.weekly_capacity_hours,active=true;
  v_result:=pg_catalog.jsonb_build_object('person',v_binding.person,
    'qualifications',p_qualifications,
    'weeklyCapacityHours',p_weekly_capacity_hours,
    'workerUserId',v_binding.actor_user_id);
  insert into d5o_hosted.connected_crew_profile_events(workspace_id,command_id,
    actor_user_id,membership_id,person,fingerprint,snapshot)
  values(v_workspace.id,p_command_id,v_actor,v_member.id,v_binding.person,
    v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_customer_decision_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_offer_revision integer, p_recipient text, p_method text, p_due_date text, p_response_status text, p_received_at text, p_details text, p_source_reference text, p_next_action text, p_follow_up_due text, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype;
  v_estimate d5o_hosted.connected_estimate_states%rowtype;
  v_offer d5o_hosted.connected_offer_states%rowtype;
  v_receipt d5o_hosted.connected_offer_receipts%rowtype;
  v_fingerprint text;v_raw jsonb;v_submission jsonb;v_response jsonb;
  v_proposal jsonb;v_result jsonb;v_now timestamptz:=now();
  v_policy_id text;v_policy_version integer;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('record-customer-submission','record-customer-response')
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<1
    or p_offer_revision is null or p_offer_revision<1 then
    raise exception 'invalid_customer_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('admin','project_manager','operations_leader') then
    raise exception 'customer_recorder_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_offer_revision,p_recipient,p_method,p_due_date,
    p_response_status,p_received_at,p_details,p_source_reference,p_next_action,
    p_follow_up_due,p_expected_source_revision,p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_offer_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_estimate from d5o_hosted.connected_estimate_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_offer from d5o_hosted.connected_offer_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or v_offer.decision_revision is distinct from p_expected_decision_revision
    or v_offer.offer_revision is distinct from p_offer_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_raw from pg_catalog.jsonb_array_elements(v_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_raw is null or v_raw->>'phaseConfigurationVersionId' is distinct from
    v_work.configuration_version_id::text
    or v_estimate.status is distinct from 'Approved'
    or v_estimate.estimate_revision<>v_offer.estimate_revision
    or v_offer.offer_digest<>pg_catalog.md5((v_offer.proposal->'package')::text)
    or v_offer.proposal#>>'{review,decidedAt}' is null then
    raise exception 'approved_current_offer_required' using errcode='23514'; end if;
  v_policy_id:=v_estimate.estimate#>>'{detailed,evaluation,policyId}';
  v_policy_version:=(v_estimate.estimate#>>'{detailed,evaluation,policyVersion}')::integer;
  if not exists(select 1 from d5o_hosted.connected_pricing_policies
    where workspace_id=v_workspace.id and policy_id=v_policy_id
      and version=v_policy_version and status='published') then
    raise exception 'pinned_offer_policy_unavailable' using errcode='23514'; end if;
  if p_action='record-customer-submission' then
    if v_offer.status<>'Approved'
      or length(trim(coalesce(p_recipient,''))) not between 2 and 300
      or p_method not in ('Customer portal','Email','Procurement platform','Direct presentation')
      or p_due_date is null or p_due_date !~ '^\d{4}-\d{2}-\d{2}$'
      or pg_catalog.to_char(p_due_date::date,'YYYY-MM-DD')<>p_due_date then
      raise exception 'submission_input_invalid' using errcode='23514'; end if;
    v_submission:=pg_catalog.jsonb_build_object('revision',v_offer.offer_revision,
      'estimateRevision',v_offer.estimate_revision,'recordedAt',v_now,
      'recipient',trim(p_recipient),'method',p_method,'responseDueDate',p_due_date,
      'packageSnapshot',v_offer.proposal->'package','recordedByActorId',v_actor,
      'recordedByMembershipId',v_member.id);
    v_proposal:=v_offer.proposal||pg_catalog.jsonb_build_object(
      'status','Submitted','recipient',trim(p_recipient),'method',p_method,
      'dueDate',p_due_date,'submission',v_submission,
      'submissionHistory',coalesce(v_offer.proposal->'submissionHistory','[]'::jsonb)||
        pg_catalog.jsonb_build_array(v_submission),
      'authorityRevision',v_offer.decision_revision+1);
  else
    if v_offer.status<>'Submitted'
      or v_offer.proposal#>>'{submission,revision}' is distinct from p_offer_revision::text
      or v_offer.proposal#>'{submission,packageSnapshot}' is distinct from
        v_offer.proposal->'package'
      or v_offer.proposal->'responseEvents'->-1->>'status' in ('Awarded','Not awarded')
      or p_response_status not in ('Clarification requested','Commercial negotiation',
        'Decision deferred','Awarded','Not awarded')
      or p_received_at is null or p_received_at !~ '^\d{4}-\d{2}-\d{2}$'
      or pg_catalog.to_char(p_received_at::date,'YYYY-MM-DD')<>p_received_at
      or length(trim(coalesce(p_details,''))) not between 10 and 4000
      or p_response_status in ('Awarded','Not awarded') and
        length(trim(coalesce(p_source_reference,''))) not between 5 and 1000
      or p_response_status not in ('Awarded','Not awarded') and
        (length(trim(coalesce(p_next_action,''))) not between 5 and 500
          or p_follow_up_due is null or p_follow_up_due !~ '^\d{4}-\d{2}-\d{2}$'
          or pg_catalog.to_char(p_follow_up_due::date,'YYYY-MM-DD')<>p_follow_up_due) then
      raise exception 'response_input_invalid' using errcode='23514'; end if;
    v_response:=pg_catalog.jsonb_build_object('revision',v_offer.offer_revision,
      'status',p_response_status,'receivedAt',p_received_at,
      'details',trim(p_details),'sourceReference',nullif(trim(coalesce(p_source_reference,'')),''),
      'nextAction',case when p_response_status in ('Awarded','Not awarded') then null
        else trim(p_next_action) end,
      'followUpDue',case when p_response_status in ('Awarded','Not awarded') then null
        else p_follow_up_due end,
      'recordedByActorId',v_actor,'recordedByMembershipId',v_member.id);
    v_proposal:=v_offer.proposal||pg_catalog.jsonb_build_object(
      'response',trim(p_details),
      'responseEvents',coalesce(v_offer.proposal->'responseEvents','[]'::jsonb)||
        pg_catalog.jsonb_build_array(v_response),
      'authorityRevision',v_offer.decision_revision+1);
  end if;
  update d5o_hosted.connected_offer_states set
    decision_revision=decision_revision+1,status=case
      when p_action='record-customer-submission' then 'Submitted' else status end,
    proposal=v_proposal,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_offer_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    offer_revision,estimate_revision,policy_id,policy_version,snapshot,reason)
  values(v_workspace.id,v_work.id,v_offer.decision_revision+1,p_command_id,p_action,
    v_actor,v_member.id,v_offer.offer_revision,v_offer.estimate_revision,
    v_policy_id,v_policy_version,v_proposal,
    case when p_action='record-customer-submission' then
      p_method||' · '||trim(p_recipient) else trim(p_details) end);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_offer_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_customer_decision_evidence_read_v1(p_workspace_key text, p_presentation_id text, p_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_evidence d5o_hosted.customer_decision_evidence%rowtype;
begin
  if current_setting('role',true)<>'service_role' then
    raise exception 'server_only' using errcode='42501'; end if;
  select e.* into v_evidence from d5o_hosted.customer_decision_evidence e
    join d5o_hosted.workspaces w on w.id=e.workspace_id
    where w.workspace_key=p_workspace_key and e.presentation_id=p_presentation_id
      and e.id=p_evidence_id;
  if not found then raise exception 'evidence_missing' using errcode='23503'; end if;
  return pg_catalog.jsonb_build_object('objectPath',v_evidence.object_path,
    'checksumSha256',v_evidence.checksum_sha256,'filename',v_evidence.filename,
    'uploadedBy',v_evidence.uploaded_by);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_define_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_review_role text, p_reason text, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid := auth.uid(); v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype; v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype; v_control d5o_hosted.connected_define_states%rowtype;
  v_receipt d5o_hosted.connected_define_receipts%rowtype; v_config d5o_hosted.configuration_versions%rowtype;
  v_raw jsonb; v_definition jsonb; v_phase jsonb; v_fingerprint text; v_now timestamptz:=now();
  v_reviewer uuid; v_next text; v_result jsonb; v_decision jsonb; v_history jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('submit','approve-review','return-review','submit-handoff','accept-handoff','return-handoff','new-revision')
    or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<0
    or length(coalesce(p_reason,''))>2000 then
    raise exception 'invalid_define_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint := pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,
    p_action,p_review_role,trim(coalesce(p_reason,'')),p_expected_source_revision,
    p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_define_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_control from d5o_hosted.connected_define_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or coalesce(v_control.decision_revision,0)<>p_expected_decision_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_raw from pg_catalog.jsonb_array_elements(v_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_raw is null or v_raw->>'phaseConfigurationVersionId' is distinct from v_work.configuration_version_id::text
    then raise exception 'source_identity_changed' using errcode='42501'; end if;
  v_definition := v_raw->'definition';
  if v_definition is null or pg_catalog.jsonb_typeof(v_definition)<>'object' then
    raise exception 'definition_unavailable' using errcode='22023'; end if;
  if v_control.work_id is not null and (v_control.status='Draft' or
    v_control.definition_revision > coalesce((v_definition->>'revision')::integer,0)) then
    v_definition:=v_control.projection;
  end if;
  if v_control.work_id is not null
    and v_control.definition_revision=coalesce((v_raw#>>'{definition,revision}')::integer,0)
    and v_control.source_digest<>pg_catalog.md5((v_raw->'definition')::text) then
    raise exception 'definition_source_changed' using errcode='23505'; end if;
  select * into v_config from d5o_hosted.configuration_versions
    where id=v_work.configuration_version_id and source_sha256=v_work.configuration_digest
      and status in ('published','superseded');
  select ph into v_phase from pg_catalog.jsonb_array_elements(
    coalesce(v_config.manifest_json#>'{d5oPresentation,phaseContract,workTypes}','[]'::jsonb)) wt,
    lateral pg_catalog.jsonb_array_elements(coalesce(wt->'phases','[]'::jsonb)) ph
    where wt->>'workTypeKey'=v_work.work_type_key and ph->>'key'='define';
  if v_phase is null then raise exception 'pinned_define_policy_unavailable' using errcode='42501'; end if;
  if p_action='submit' then
    if (v_control.work_id is not null and v_control.status<>'Draft')
      or v_member.role not in ('admin','project_manager','operations_leader')
      then raise exception 'define_submit_denied' using errcode='42501'; end if;
    if not d5o_hosted.connected_define_ready_v1(
      v_raw||pg_catalog.jsonb_build_object('definition',v_definition),v_phase) then
      raise exception 'definition_incomplete' using errcode='23514'; end if;
    v_next:='Commercial and Delivery: review the Define baseline';
    v_definition := v_definition || pg_catalog.jsonb_build_object('status','In review',
      'reviews',pg_catalog.jsonb_build_object('commercial','Pending','delivery','Pending',
        'revision',(v_definition->>'revision')::integer),
      'configurationVersion',v_config.id::text,
      'configurationWorkTypeKey',v_work.work_type_key);
    if v_control.work_id is null then
      insert into d5o_hosted.connected_define_states(workspace_id,work_id,source_revision,
        source_digest,definition_revision,decision_revision,status,submitted_by,projection,next_action)
      values(v_workspace.id,v_work.id,v_state.revision,pg_catalog.md5((v_raw->'definition')::text),
        (v_definition->>'revision')::integer,1,'In review',v_actor,v_definition,v_next);
    else
      update d5o_hosted.connected_define_states set decision_revision=decision_revision+1,
        status='In review',submitted_by=v_actor,source_revision=v_state.revision,
        source_digest=pg_catalog.md5(v_definition::text),updated_at=v_now
        where workspace_id=v_workspace.id and work_id=v_work.id;
    end if;
  else
    if v_control.work_id is null or v_control.definition_revision is distinct from
      (v_definition->>'revision')::integer then
      raise exception 'define_submission_required' using errcode='23514'; end if;
    v_definition:=v_control.projection;
    if p_action in ('approve-review','return-review') then
      if p_review_role not in ('commercial','delivery') or
        (p_review_role='commercial' and v_member.role not in ('admin','billing_commercial_lead')) or
        (p_review_role='delivery' and v_member.role not in ('admin','operations_leader','project_manager')) then
        raise exception 'define_review_role_denied' using errcode='42501'; end if;
      if v_control.status<>'In review' or v_definition#>>array['reviews',p_review_role]<>'Pending'
        or v_actor=v_control.submitted_by or
        (p_review_role='commercial' and v_actor=v_control.delivery_reviewer) or
        (p_review_role='delivery' and v_actor=v_control.commercial_reviewer) then
        raise exception 'define_independent_review_required' using errcode='42501'; end if;
      if length(trim(coalesce(p_reason,'')))<10 then
        raise exception 'decision_reason_required' using errcode='22023'; end if;
      if p_action='approve-review' and not d5o_hosted.connected_define_ready_v1(
        v_raw||pg_catalog.jsonb_build_object('definition',
          v_definition||pg_catalog.jsonb_build_object('status','Draft')),v_phase) then
        raise exception 'definition_incomplete' using errcode='23514'; end if;
      v_definition:=pg_catalog.jsonb_set(v_definition,array['reviews',p_review_role],
        pg_catalog.to_jsonb(case when p_action='approve-review' then 'Approved' else 'Changes requested' end));
      if p_action='return-review' then
        v_control.status:='Changes requested'; v_next:='Define owner: correct the returned revision';
      elsif v_definition#>>'{reviews,commercial}'='Approved'
        and v_definition#>>'{reviews,delivery}'='Approved' then
        v_control.status:='Approved'; v_next:='Define owner: submit the approved baseline to Develop';
        v_definition:=v_definition || pg_catalog.jsonb_build_object('approvedBaselines',
          coalesce(v_definition->'approvedBaselines','[]'::jsonb) ||
          pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
            'revision',v_control.definition_revision,'approvedAt',v_now,
            'configurationVersion',v_config.id::text,
            'outcome',v_definition->'outcome','excludedScope',v_definition->'excludedScope',
            'deliveryApproach',v_definition->'deliveryApproach','registers',v_definition->'registers',
            'project',v_definition->'project','findings',v_definition->'findings',
            'clarifications',v_definition->'clarifications','scopeControl',v_definition->'scopeControl')));
      else v_next:='Commercial and Delivery: finish the Define reviews'; end if;
      if p_review_role='commercial' then v_control.commercial_reviewer:=v_actor;
      else v_control.delivery_reviewer:=v_actor; end if;
    elsif p_action='new-revision' then
      if v_member.role not in ('admin','project_manager','operations_leader')
        or v_control.status not in ('Changes requested','Approved')
        or v_definition#>>'{developHandoff,status}'='accepted'
        or length(trim(coalesce(p_reason,'')))<10 then
        raise exception 'define_revision_denied' using errcode='42501'; end if;
      v_control.status:='Draft';
      v_control.definition_revision:=v_control.definition_revision+1;
      v_control.commercial_reviewer:=null; v_control.delivery_reviewer:=null;
      v_control.handoff_sender:=null; v_control.handoff_receiver:=null;
      v_definition:=v_definition-'reviews'-'developHandoff'-'configurationVersion'
        -'configurationWorkTypeKey'-'sourceEstimateRevision'-'sourceProposalRevision';
      v_definition:=v_definition||pg_catalog.jsonb_build_object(
        'revision',v_control.definition_revision,'status','Draft');
      v_next:='Define owner: correct and resubmit the new revision';
    elsif p_action='submit-handoff' then
      if v_member.role not in ('admin','project_manager','operations_leader')
        or v_control.status<>'Approved' or v_definition->'approvedBaselines' is null
        or v_definition#>>'{developHandoff,status}' in ('submitted','accepted') then
        raise exception 'define_handoff_denied' using errcode='42501'; end if;
      v_definition:=v_definition || pg_catalog.jsonb_build_object('developHandoff',
        pg_catalog.jsonb_build_object('revision',v_control.definition_revision,
          'status','submitted','receiver','Develop receiver queue',
          'note',coalesce(nullif(trim(p_reason),''),'Approved Define basis submitted'),
          'submittedAt',v_now,'actor',v_actor::text,'submittedByActorId',v_actor,
          'submittedByMembershipId',v_member.id));
      v_control.handoff_sender:=v_actor;
      v_next:='Develop receiver: accept or return the exact Define revision';
    elsif p_action in ('accept-handoff','return-handoff') then
      if v_member.role not in ('admin','project_manager','operations_leader')
        or v_control.status<>'Approved' or v_definition#>>'{developHandoff,status}'<>'submitted'
        or v_definition#>>'{developHandoff,revision}'<>v_control.definition_revision::text
        or v_actor=v_control.handoff_sender or length(trim(coalesce(p_reason,'')))<10 then
        raise exception 'define_receipt_denied' using errcode='42501'; end if;
      v_definition:=pg_catalog.jsonb_set(v_definition,'{developHandoff}',
        (v_definition->'developHandoff') || pg_catalog.jsonb_build_object(
          'status',case when p_action='accept-handoff' then 'accepted' else 'returned' end,
          'note',trim(p_reason),'respondedAt',v_now,'receivedByActorId',v_actor,
          'receivedByMembershipId',v_member.id));
      v_control.handoff_receiver:=v_actor;
      v_next:=case when p_action='accept-handoff' then
        'Develop owner: develop the solution and estimate' else
        'Define owner: revise the returned basis' end;
    end if;
    update d5o_hosted.connected_define_states set decision_revision=decision_revision+1,
      status=v_control.status,definition_revision=v_control.definition_revision,
      commercial_reviewer=v_control.commercial_reviewer,
      delivery_reviewer=v_control.delivery_reviewer,handoff_sender=v_control.handoff_sender,
      handoff_receiver=v_control.handoff_receiver,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
  end if;
  select * into v_control from d5o_hosted.connected_define_states
    where workspace_id=v_workspace.id and work_id=v_work.id;
  v_decision:=pg_catalog.jsonb_build_object('commandId',p_command_id,'action',p_action,
    'definitionRevision',v_control.definition_revision,'reviewRole',p_review_role,
    'actorId',v_actor,'membershipId',v_member.id,'policyVersion',v_config.version_number::text,
    'at',v_now,'reason',trim(coalesce(p_reason,'')));
  v_history:=pg_catalog.jsonb_build_object('at',v_now,'revision',v_control.definition_revision,
    'event',p_action,'note',v_member.role || ' (' || v_actor::text || ') · ' ||
      coalesce(nullif(trim(p_reason),''),'Decision recorded'));
  v_definition:=v_definition || pg_catalog.jsonb_build_object('status',v_control.status,
    'authorityRevision',v_control.decision_revision,
    'decisions',coalesce(v_definition->'decisions','[]'::jsonb)||pg_catalog.jsonb_build_array(v_decision),
    'history',coalesce(v_definition->'history','[]'::jsonb)||pg_catalog.jsonb_build_array(v_history));
  update d5o_hosted.connected_define_states set projection=v_definition,next_action=v_next,
    source_digest=case when v_control.status='Draft' then pg_catalog.md5(v_definition::text)
      else source_digest end
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_define_events(workspace_id,work_id,decision_revision,
    command_id,action,definition_revision,actor_user_id,membership_id,authority_role,
    configuration_version_id,source_digest,reason)
  values(v_workspace.id,v_work.id,v_control.decision_revision,p_command_id,p_action,
    v_control.definition_revision,v_actor,v_member.id,v_member.role,v_config.id,
    v_control.source_digest,trim(coalesce(p_reason,'')));
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_define_receipts(workspace_id,command_id,work_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_actions_pre_delegate_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; member d5o_hosted.memberships%rowtype;
 result jsonb:='[]'::jsonb; work_item record; task_item record; rev integer; current_digest text;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active';
 if member.id is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if member.role not in ('project_manager','billing_commercial_lead') then return result; end if;
 for work_item in select w.id,l.presentation_id,w.created_by from d5o_hosted.work_records w
  join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
  where w.workspace_id=ws and (member.role='billing_commercial_lead' or w.created_by=actor)
   and (exists(select 1 from d5o_hosted.design_spend_commitments c where c.workspace_id=ws and c.work_id=w.id and c.status='Approved')
     or exists(select 1 from d5o_hosted.outlook_assessments a where a.workspace_id=ws and a.work_id=w.id)) loop
  select coalesce(p.revision,0) into rev from d5o_hosted.design_cost_positions p where p.workspace_id=ws and p.work_id=work_item.id;
  rev:=coalesce(rev,0);
  current_digest:=d5o_hosted.outlook_source_v1(ws,work_item.id)->>'digest';
  if member.role='project_manager' then
   if exists(select 1 from d5o_hosted.design_spend_commitments c where c.workspace_id=ws and c.work_id=work_item.id and c.status='Approved'
    and not exists(select 1 from d5o_hosted.design_cost_links x where x.commitment_id=c.id)) then
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Link Design cost source','workId',work_item.presentation_id,
      'revision',rev,'status','Unlinked approved commitment','title','Link approved Design commitment to Finance',
      'phase','Operate','focus','finance','taskKind','design-cost','position','preparation','ownership','Assigned project manager',
      'blocker','Choose the exact approved Design commitment and retain its source.'));
   elsif exists(select 1 from d5o_hosted.design_cost_links x where x.workspace_id=ws and x.work_id=work_item.id) then
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Record Design cost','workId',work_item.presentation_id,
      'revision',rev,'status','Source-backed actual needed','title','Submit actual Design cost or correction',
      'phase','Operate','focus','finance','taskKind','design-cost','position','preparation','ownership','Assigned project manager',
      'blocker','Approval of the commitment does not establish incurred cost.'));
   end if;
   if not exists(select 1 from d5o_hosted.outlook_assessments a where a.workspace_id=ws and a.work_id=work_item.id
      and a.source_digest=current_digest and a.status in ('Prepared','Complete','Reviewed with gaps')) then
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Prepare Work cost outlook','workId',work_item.presentation_id,
      'revision',rev,'status','Missing or stale assessment','title','Prepare cost-outlook completeness assessment',
      'phase','Operate','focus','finance','taskKind','outlook-assessment','position','preparation','ownership','Assigned project manager',
      'blocker','Identify unresolved categories and forecast sources before independent Finance review.'));
   end if;
  else
   if not exists(select 1 from d5o_hosted.connected_job_finance_states f
    where f.workspace_id=ws and f.work_id=work_item.id and f.remaining_forecast_minor is not null) then
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Record Work cost forecast','workId',work_item.presentation_id,
      'revision',rev,'status','Additional cost unknown','title','Record sourced additional Work cost forecast',
      'phase','Operate','focus','finance','taskKind','outlook-assessment','position','action','ownership','Finance reviewer',
      'blocker','Estimate only costs beyond commitments; do not turn an absent cost into zero.'));
   end if;
   for task_item in select c.id,c.work_id,l.presentation_id,c.source_reference from d5o_hosted.design_cost_claims c
    join d5o_hosted.work_identity_links l on l.work_id=c.work_id and l.workspace_id=c.workspace_id
    where c.workspace_id=ws and c.work_id=work_item.id and c.status='Prepared' and c.prepared_by<>actor loop
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Review Design cost','workId',task_item.presentation_id,
      'revision',rev,'decisionId',task_item.id,'status','Prepared','title','Review sourced Design cost',
      'phase','Operate','focus','finance','taskKind','design-cost','position','action','ownership','Finance reviewer',
      'blocker',null));
   end loop;
   for task_item in select a.id,a.work_id,l.presentation_id from d5o_hosted.outlook_assessments a
    join d5o_hosted.work_identity_links l on l.work_id=a.work_id and l.workspace_id=a.workspace_id
    where a.workspace_id=ws and a.work_id=work_item.id and a.status='Prepared'
     and a.prepared_by<>actor and a.source_digest=current_digest loop
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Review Work cost outlook','workId',task_item.presentation_id,
      'revision',rev,'decisionId',task_item.id,'status','Prepared','title','Review cost-outlook completeness',
      'phase','Operate','focus','finance','taskKind','outlook-assessment','position','action','ownership','Finance reviewer',
      'blocker',null));
   end loop;
  end if;
 end loop;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_actions_pre_outlook_delegate_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb; route jsonb; result jsonb:='[]'::jsonb;
begin
 for item in select value from pg_catalog.jsonb_array_elements(
  public.d5o_hosted_design_cost_actions_pre_delegate_v1(p_workspace_key)) loop
  if item->>'kind'='Review Design cost' then
   route:=public.d5o_design_cost_my_review_v1(p_workspace_key,item->>'workId',(item->>'decisionId')::uuid);
   if coalesce((route->>'canReview')::boolean,false) then
    result:=result||pg_catalog.jsonb_build_array(item); end if;
  else result:=result||pg_catalog.jsonb_build_array(item); end if;
 end loop;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb; route jsonb; result jsonb:='[]'::jsonb;
begin
 for item in select value from pg_catalog.jsonb_array_elements(
  public.d5o_hosted_design_cost_actions_pre_outlook_delegate_v1(p_workspace_key)) loop
  if item->>'kind'='Review Work cost outlook' then
   route:=public.d5o_outlook_assessment_my_review_v1(p_workspace_key,item->>'workId',(item->>'decisionId')::uuid);
   if coalesce((route->>'canReview')::boolean,false) then
    result:=result||pg_catalog.jsonb_build_array(item); end if;
  else result:=result||pg_catalog.jsonb_build_array(item); end if;
 end loop;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_command_pre_forecast_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; member d5o_hosted.memberships%rowtype;
 w d5o_hosted.work_records%rowtype; pos d5o_hosted.design_cost_positions%rowtype;
 receipt d5o_hosted.design_cost_receipts%rowtype; commitment d5o_hosted.design_spend_commitments%rowtype;
 link d5o_hosted.design_cost_links%rowtype; claim d5o_hosted.design_cost_claims%rowtype;
 prior d5o_hosted.design_cost_claims%rowtype; assessment d5o_hosted.outlook_assessments%rowtype;
 src jsonb; fingerprint text; result jsonb; subject uuid; amount bigint; category text; item jsonb; category_status text;
begin
 if current_setting('role',true)<>'authenticated' or actor is null
  or p_action not in ('link-commitment','prepare-cost','review-cost','prepare-assessment','review-assessment')
  or pg_catalog.jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then raise exception 'invalid_design_cost_command' using errcode='22023'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active' for share;
 if member.id is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select r.* into w from d5o_hosted.work_records r join d5o_hosted.work_identity_links l on l.workspace_id=r.workspace_id and l.work_id=r.id
  where r.workspace_id=ws and l.presentation_id=p_presentation_id for update of r;
 if w.id is null then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
 fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,p_expected_revision,p_expected_source_digest)::text);
 select * into receipt from d5o_hosted.design_cost_receipts where workspace_id=ws and command_id=p_command_id;
 if receipt.command_id is not null then
  if receipt.work_id<>w.id or receipt.actor_user_id<>actor or receipt.fingerprint<>fingerprint then raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return receipt.result; end if;
 insert into d5o_hosted.design_cost_positions(workspace_id,work_id) values(ws,w.id) on conflict do nothing;
 select * into pos from d5o_hosted.design_cost_positions where workspace_id=ws and work_id=w.id for update;
 if pos.revision<>p_expected_revision then raise exception 'stale_design_cost_revision' using errcode='23505'; end if;
 src:=d5o_hosted.outlook_source_v1(ws,w.id);
 if src->>'digest' is distinct from p_expected_source_digest then raise exception 'outlook_source_changed' using errcode='23514'; end if;
 if p_action in ('link-commitment','prepare-cost','prepare-assessment') then
  if member.role<>'project_manager' or w.created_by<>actor then raise exception 'assigned_pm_required' using errcode='42501'; end if;
 else
  if member.role<>'billing_commercial_lead' then raise exception 'independent_finance_review_required' using errcode='42501'; end if;
 end if;
 if p_action='link-commitment' then
  select * into commitment from d5o_hosted.design_spend_commitments where id=(p_input->>'commitmentId')::uuid
   and workspace_id=ws and work_id=w.id and status='Approved' for update;
  if commitment.id is null or commitment.currency<>'USD' or exists(select 1 from d5o_hosted.design_cost_links where commitment_id=commitment.id)
   then raise exception 'eligible_unlinked_design_commitment_required' using errcode='23514'; end if;
  if length(trim(coalesce(p_input->>'source','')))<8 then raise exception 'design_commitment_source_required' using errcode='22023'; end if;
  insert into d5o_hosted.connected_job_costs(workspace_id,work_id,kind,category,amount_minor,cost_date,source,recorded_by)
   values(ws,w.id,'Committed','Design',commitment.amount_minor,current_date,
    'Design commitment '||commitment.id||' · '||trim(p_input->>'source'),actor) returning id into subject;
  insert into d5o_hosted.design_cost_links(commitment_id,workspace_id,work_id,ledger_cost_id,linked_by)
   values(commitment.id,ws,w.id,subject,actor);
 elsif p_action='prepare-cost' then
  select * into commitment from d5o_hosted.design_spend_commitments where id=(p_input->>'commitmentId')::uuid
   and workspace_id=ws and work_id=w.id and status='Approved';
  select * into link from d5o_hosted.design_cost_links where commitment_id=commitment.id and workspace_id=ws and work_id=w.id;
  if commitment.id is null or link.commitment_id is null then raise exception 'linked_design_commitment_required' using errcode='23514'; end if;
  if coalesce(p_input->>'amountMinor','') !~ '^[1-9][0-9]*$' or coalesce(p_input->>'costDate','') !~ '^\d{4}-\d{2}-\d{2}$'
   or length(trim(coalesce(p_input->>'sourceReference','')))<8 or length(trim(coalesce(p_input->>'evidenceNote','')))<10 then
   raise exception 'sourced_design_cost_required' using errcode='22023'; end if;
  amount:=(p_input->>'amountMinor')::bigint;
  if amount>1000000000000 or (p_input->>'costDate')::date>current_date then raise exception 'design_cost_amount_or_date_invalid' using errcode='23514'; end if;
  if p_input ? 'supersedesId' then
   select * into prior from d5o_hosted.design_cost_claims where id=(p_input->>'supersedesId')::uuid
    and workspace_id=ws and work_id=w.id and commitment_id=commitment.id and status='Reviewed';
   if prior.id is null or exists(select 1 from d5o_hosted.design_cost_claims x where x.supersedes_id=prior.id and x.status='Reviewed')
    then raise exception 'current_reviewed_cost_required' using errcode='23514'; end if;
  end if;
  if exists(select 1 from d5o_hosted.design_cost_claims where workspace_id=ws and work_id=w.id
   and status in ('Prepared','Reviewed') and commitment_id=commitment.id and source_reference=trim(p_input->>'sourceReference')
   and (prior.id is null or id<>prior.id)) then raise exception 'duplicate_design_cost_source' using errcode='23505'; end if;
  insert into d5o_hosted.design_cost_claims(id,workspace_id,work_id,commitment_id,root_id,supersedes_id,status,
   amount_minor,currency,cost_date,source_reference,evidence_note,prepared_by)
   values(gen_random_uuid(),ws,w.id,commitment.id,coalesce(prior.root_id,gen_random_uuid()),prior.id,'Prepared',
    amount,'USD',(p_input->>'costDate')::date,trim(p_input->>'sourceReference'),trim(p_input->>'evidenceNote'),actor)
   returning id into subject;
  if prior.id is null then update d5o_hosted.design_cost_claims set root_id=subject where id=subject; end if;
 elsif p_action='review-cost' then
  select * into claim from d5o_hosted.design_cost_claims where id=(p_input->>'claimId')::uuid
   and workspace_id=ws and work_id=w.id for update;
  if claim.id is null or claim.status<>'Prepared' or claim.prepared_by=actor
   or length(trim(coalesce(p_input->>'reason','')))<10 or p_input->>'decision' not in ('Reviewed','Returned')
   then raise exception 'independent_design_cost_review_required' using errcode='23514'; end if;
  if claim.supersedes_id is not null and not exists(select 1 from d5o_hosted.design_cost_claims
   where id=claim.supersedes_id and status='Reviewed') then raise exception 'design_cost_source_changed' using errcode='23514'; end if;
  update d5o_hosted.design_cost_claims set status=p_input->>'decision',reviewed_by=actor,
   review_note=trim(p_input->>'reason'),reviewed_at=now() where id=claim.id;
  subject:=claim.id;
 elsif p_action='prepare-assessment' then
  if pg_catalog.jsonb_typeof(p_input->'categories')<>'object' or length(trim(coalesce(p_input->>'limitations','')))<10
   or length(trim(coalesce(p_input->>'sourceReference','')))<8
   or coalesce(p_input->>'actualCutoff','') !~ '^\d{4}-\d{2}-\d{2}$'
   then raise exception 'outlook_assessment_basis_required' using errcode='22023'; end if;
  if (p_input->>'actualCutoff')::date>current_date then raise exception 'future_actual_cutoff_invalid' using errcode='23514'; end if;
  foreach category in array array['Design','Material','Equipment','Subcontract','Labor','Other'] loop
   item:=p_input->'categories'->category; category_status:=item->>'status';
   if category_status is null or category_status not in ('Resolved','Unknown','Not applicable') or length(trim(coalesce(item->>'reason','')))<8
    then raise exception 'cost_category_disposition_required: %',category using errcode='23514'; end if;
  end loop;
  insert into d5o_hosted.outlook_assessments(workspace_id,work_id,status,source_digest,source_basis,actual_cutoff,
   category_basis,limitations,source_reference,prepared_by)
   values(ws,w.id,'Prepared',src->>'digest',src->'basis',(p_input->>'actualCutoff')::date,
    p_input->'categories',trim(p_input->>'limitations'),trim(p_input->>'sourceReference'),actor)
   returning id into subject;
 else
  select * into assessment from d5o_hosted.outlook_assessments where id=(p_input->>'assessmentId')::uuid
   and workspace_id=ws and work_id=w.id for update;
  if assessment.id is null or assessment.status<>'Prepared' or assessment.prepared_by=actor
   or assessment.source_digest<>src->>'digest' or p_input->>'decision' not in ('Complete','Reviewed with gaps','Returned')
   or length(trim(coalesce(p_input->>'reason','')))<10 then raise exception 'current_independent_outlook_review_required' using errcode='23514'; end if;
  if p_input->>'decision'='Complete' then
   if exists(select 1 from pg_catalog.jsonb_each(assessment.category_basis) c where c.value->>'status'='Unknown')
    or exists(select 1 from d5o_hosted.design_spend_commitments c where c.workspace_id=ws and c.work_id=w.id and c.status='Approved'
     and not exists(select 1 from d5o_hosted.design_cost_links l where l.commitment_id=c.id))
    or exists(select 1 from d5o_hosted.design_cost_claims c where c.workspace_id=ws and c.work_id=w.id and c.status='Prepared')
    or exists(select 1 from pg_catalog.jsonb_each(assessment.category_basis) c where c.value->>'status'='Not applicable'
      and exists(select 1 from d5o_hosted.connected_job_costs j where j.workspace_id=ws and j.work_id=w.id and j.category=c.key))
    or (assessment.category_basis->'Design'->>'status'='Not applicable' and exists(select 1 from d5o_hosted.design_spend_commitments c
      where c.workspace_id=ws and c.work_id=w.id and c.status='Approved'))
    or (assessment.category_basis->'Labor'->>'status'='Not applicable' and exists(select 1 from d5o_hosted.labor_reservations r
      where r.workspace_id=ws and r.work_id=w.id))
    or exists(select 1 from d5o_hosted.labor_reservations r where r.workspace_id=ws and r.work_id=w.id
      and r.status='Active' and r.work_date<=assessment.actual_cutoff
      and not exists(select 1 from d5o_hosted.labor_actuals a where a.reservation_id=r.id))
    or exists(select 1 from pg_catalog.jsonb_each(assessment.category_basis) c
      where c.value->>'status'='Resolved'
       and not exists(select 1 from d5o_hosted.connected_job_costs j where j.workspace_id=ws and j.work_id=w.id and j.category=c.key)
       and not (c.key='Labor' and exists(select 1 from d5o_hosted.labor_reservations r where r.workspace_id=ws and r.work_id=w.id)))
    or not exists(select 1 from d5o_hosted.connected_job_finance_states f where f.workspace_id=ws and f.work_id=w.id
     and f.remaining_forecast_minor is not null and length(trim(coalesce(f.forecast_source,'')))>=8)
    then raise exception 'outlook_has_unresolved_sources' using errcode='23514'; end if;
  end if;
  update d5o_hosted.outlook_assessments set status=p_input->>'decision',reviewed_by=actor,
   review_note=trim(p_input->>'reason'),reviewed_at=now() where id=assessment.id;
  subject:=assessment.id;
 end if;
 update d5o_hosted.design_cost_positions set revision=revision+1 where workspace_id=ws and work_id=w.id;
 result:=pg_catalog.jsonb_build_object('revision',pos.revision+1,'subjectId',subject,'action',p_action);
 insert into d5o_hosted.design_cost_events(workspace_id,work_id,revision,action,command_id,actor_user_id,membership_id,subject_id,basis)
  values(ws,w.id,pos.revision+1,p_action,p_command_id,actor,member.id,subject,pg_catalog.jsonb_build_object('input',p_input,'sourceDigest',src->>'digest'));
 insert into d5o_hosted.design_cost_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(ws,p_command_id,w.id,actor,fingerprint,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_command_pre_rate_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; pos d5o_hosted.design_cost_positions%rowtype;
 receipt d5o_hosted.design_cost_receipts%rowtype; src jsonb; fingerprint text;
 result jsonb; amount bigint; changed_date date;
begin
 if p_action<>'set-work-forecast' then
  return public.d5o_hosted_design_cost_command_pre_forecast_v1(p_workspace_key,p_presentation_id,
   p_action,p_input,p_command_id,p_expected_revision,p_expected_source_digest);
 end if;
 if current_setting('role',true)<>'authenticated' or actor is null
  or pg_catalog.jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then raise exception 'invalid_work_forecast_command' using errcode='22023'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active' for share;
 if member.id is null or member.role<>'billing_commercial_lead' then raise exception 'finance_forecast_role_required' using errcode='42501'; end if;
 select r.* into work from d5o_hosted.work_records r join d5o_hosted.work_identity_links l
  on l.workspace_id=r.workspace_id and l.work_id=r.id where r.workspace_id=ws and l.presentation_id=p_presentation_id for update of r;
 if work.id is null then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
 fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,p_expected_revision,p_expected_source_digest)::text);
 select * into receipt from d5o_hosted.design_cost_receipts where workspace_id=ws and command_id=p_command_id;
 if receipt.command_id is not null then
  if receipt.work_id<>work.id or receipt.actor_user_id<>actor or receipt.fingerprint<>fingerprint then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return receipt.result; end if;
 insert into d5o_hosted.design_cost_positions(workspace_id,work_id) values(ws,work.id) on conflict do nothing;
 select * into pos from d5o_hosted.design_cost_positions where workspace_id=ws and work_id=work.id for update;
 if pos.revision<>p_expected_revision then raise exception 'stale_design_cost_revision' using errcode='23505'; end if;
 src:=d5o_hosted.outlook_source_v1(ws,work.id);
 if src->>'digest' is distinct from p_expected_source_digest then raise exception 'outlook_source_changed' using errcode='23514'; end if;
 if exists(select 1 from d5o_hosted.connected_operate_states o where o.workspace_id=ws and o.work_id=work.id
   and o.state#>>'{finance,status}'='Closed') then raise exception 'finance_closed_requires_reopen' using errcode='23514'; end if;
 if coalesce(p_input->>'amountMinor','') !~ '^(0|[1-9][0-9]*)$'
  or coalesce(p_input->>'forecastAt','') !~ '^\d{4}-\d{2}-\d{2}$'
  or length(trim(coalesce(p_input->>'source','')))<8 then raise exception 'sourced_work_forecast_required' using errcode='22023'; end if;
 amount:=(p_input->>'amountMinor')::bigint; changed_date:=(p_input->>'forecastAt')::date;
 if amount>1000000000000 or changed_date>current_date then raise exception 'work_forecast_amount_or_date_invalid' using errcode='23514'; end if;
 insert into d5o_hosted.connected_job_finance_states(workspace_id,work_id,currency)
  values(ws,work.id,'USD') on conflict do nothing;
 update d5o_hosted.connected_job_finance_states set revision=revision+1,
  remaining_forecast_minor=amount,forecast_source=trim(p_input->>'source'),forecast_at=changed_date
  where workspace_id=ws and work_id=work.id and currency='USD';
 if not found then raise exception 'forecast_currency_mismatch' using errcode='23514'; end if;
 update d5o_hosted.design_cost_positions set revision=revision+1 where workspace_id=ws and work_id=work.id;
 result:=pg_catalog.jsonb_build_object('revision',pos.revision+1,'action',p_action,'amountMinor',amount);
 insert into d5o_hosted.design_cost_events(workspace_id,work_id,revision,action,command_id,actor_user_id,membership_id,subject_id,basis)
  values(ws,work.id,pos.revision+1,p_action,p_command_id,actor,member.id,work.id,
   pg_catalog.jsonb_build_object('sourceDigest',src->>'digest','amountMinor',amount,'forecastAt',changed_date,'source',trim(p_input->>'source')));
 insert into d5o_hosted.design_cost_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(ws,p_command_id,work.id,actor,fingerprint,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; pos d5o_hosted.design_cost_positions%rowtype;
 commitment d5o_hosted.design_spend_commitments%rowtype; rate d5o_hosted.design_internal_rates%rowtype;
 prior d5o_hosted.design_cost_claims%rowtype; claim d5o_hosted.design_cost_claims%rowtype;
 receipt d5o_hosted.design_cost_receipts%rowtype; src jsonb; fp text; result jsonb;
 rate_revision integer; hours_hundredths bigint; amount bigint;
begin
 if p_action<>'prepare-rated-cost' then
  return public.d5o_hosted_design_cost_command_pre_rate_v1(p_workspace_key,p_presentation_id,
   p_action,p_input,p_command_id,p_expected_revision,p_expected_source_digest); end if;
 if current_setting('role',true)<>'authenticated' or actor is null
  or pg_catalog.jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then
  raise exception 'invalid_design_cost_command' using errcode='22023'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active' for share;
 if member.id is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select x.* into work from d5o_hosted.work_records x join d5o_hosted.work_identity_links l
  on l.workspace_id=x.workspace_id and l.work_id=x.id
  where x.workspace_id=ws and l.presentation_id=p_presentation_id for update of x;
 if work.id is null or member.role<>'project_manager' or work.created_by<>actor then
  raise exception 'assigned_pm_required' using errcode='42501'; end if;
 fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,p_expected_revision,p_expected_source_digest)::text);
 select * into receipt from d5o_hosted.design_cost_receipts where workspace_id=ws and command_id=p_command_id;
 if found then
  if receipt.work_id<>work.id or receipt.actor_user_id<>actor or receipt.fingerprint<>fp then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return receipt.result; end if;
 insert into d5o_hosted.design_cost_positions(workspace_id,work_id) values(ws,work.id) on conflict do nothing;
 select * into pos from d5o_hosted.design_cost_positions where workspace_id=ws and work_id=work.id for update;
 if pos.revision<>p_expected_revision then raise exception 'stale_design_cost_revision' using errcode='23505'; end if;
 src:=d5o_hosted.outlook_source_v1(ws,work.id);
 if src->>'digest' is distinct from p_expected_source_digest then raise exception 'outlook_source_changed' using errcode='23514'; end if;
 if coalesce(p_input->>'commitmentId','') !~ '^[0-9a-fA-F-]{36}$'
  or coalesce(p_input->>'rateId','') !~ '^[0-9a-fA-F-]{36}$'
  or coalesce(p_input->>'hoursHundredths','') !~ '^[1-9][0-9]*$'
  or coalesce(p_input->>'rateRevision','') !~ '^(0|[1-9][0-9]*)$'
  or coalesce(p_input->>'costDate','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or length(trim(coalesce(p_input->>'sourceReference','')))<8
  or length(trim(coalesce(p_input->>'evidenceNote','')))<10
  or p_input ? 'amountMinor' then raise exception 'rated_design_cost_basis_required' using errcode='22023'; end if;
 hours_hundredths:=(p_input->>'hoursHundredths')::bigint;
 rate_revision:=(p_input->>'rateRevision')::integer;
 if hours_hundredths>100000 or (p_input->>'costDate')::date>current_date then
  raise exception 'rated_design_cost_hours_or_date_invalid' using errcode='23514'; end if;
 select * into commitment from d5o_hosted.design_spend_commitments where id=(p_input->>'commitmentId')::uuid
  and workspace_id=ws and work_id=work.id and status='Approved';
 if commitment.id is null or not exists(select 1 from d5o_hosted.design_cost_links l
  where l.commitment_id=commitment.id and l.workspace_id=ws and l.work_id=work.id) then
  raise exception 'linked_design_commitment_required' using errcode='23514'; end if;
 select revision into rate_revision from d5o_hosted.design_internal_rate_positions where workspace_id=ws;
 if rate_revision is distinct from (p_input->>'rateRevision')::integer then
  raise exception 'stale_internal_rate_revision' using errcode='23505'; end if;
 select * into rate from d5o_hosted.design_internal_rates where id=(p_input->>'rateId')::uuid
  and workspace_id=ws and status='Approved' and currency=commitment.currency
  and (p_input->>'costDate')::date between effective_from and effective_until;
 if rate.id is null then raise exception 'approved_effective_internal_rate_required' using errcode='23514'; end if;
 amount:=pg_catalog.round(hours_hundredths::numeric*rate.base_rate_minor::numeric*
  (10000+rate.burden_basis_points)::numeric/1000000,0)::bigint;
 if amount<1 or amount>1000000000000 then raise exception 'rated_design_cost_amount_invalid' using errcode='23514'; end if;
 if p_input ? 'supersedesId' then
  if coalesce(p_input->>'supersedesId','') !~ '^[0-9a-fA-F-]{36}$' then
   raise exception 'current_reviewed_cost_required' using errcode='22023'; end if;
  select * into prior from d5o_hosted.design_cost_claims where id=(p_input->>'supersedesId')::uuid
   and workspace_id=ws and work_id=work.id and commitment_id=commitment.id and status='Reviewed';
  if prior.id is null or exists(select 1 from d5o_hosted.design_cost_claims x
   where x.supersedes_id=prior.id and x.status='Reviewed') then
   raise exception 'current_reviewed_cost_required' using errcode='23514'; end if;
 end if;
 if exists(select 1 from d5o_hosted.design_cost_claims x where x.workspace_id=ws and x.work_id=work.id
  and x.status in ('Prepared','Reviewed') and x.commitment_id=commitment.id
  and x.source_reference=trim(p_input->>'sourceReference') and (prior.id is null or x.id<>prior.id)) then
  raise exception 'duplicate_design_cost_source' using errcode='23505'; end if;
 insert into d5o_hosted.design_cost_claims(id,workspace_id,work_id,commitment_id,root_id,supersedes_id,status,
  amount_minor,currency,cost_date,source_reference,evidence_note,prepared_by)
  values(gen_random_uuid(),ws,work.id,commitment.id,coalesce(prior.root_id,gen_random_uuid()),prior.id,'Prepared',
   amount,'USD',(p_input->>'costDate')::date,trim(p_input->>'sourceReference'),trim(p_input->>'evidenceNote'),actor)
  returning * into claim;
 if prior.id is null then update d5o_hosted.design_cost_claims set root_id=claim.id where id=claim.id; end if;
 insert into d5o_hosted.design_cost_rate_basis(claim_id,workspace_id,work_id,rate_id,rate_revision,
  person_hours_hundredths,base_rate_minor,burden_basis_points,calculated_minor,currency)
  values(claim.id,ws,work.id,rate.id,rate_revision,hours_hundredths,rate.base_rate_minor,
   rate.burden_basis_points,amount,'USD');
 update d5o_hosted.design_cost_positions set revision=revision+1 where workspace_id=ws and work_id=work.id;
 result:=pg_catalog.jsonb_build_object('revision',pos.revision+1,'subjectId',claim.id,
  'action',p_action,'amountMinor',amount,'rateId',rate.id);
 insert into d5o_hosted.design_cost_events(workspace_id,work_id,revision,action,command_id,
  actor_user_id,membership_id,subject_id,basis)
  values(ws,work.id,pos.revision+1,p_action,p_command_id,actor,member.id,claim.id,
   pg_catalog.jsonb_build_object('input',p_input,'sourceDigest',src->>'digest','ratedAmountMinor',amount,'rateId',rate.id));
 insert into d5o_hosted.design_cost_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(ws,p_command_id,work.id,actor,fp,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_evidence_read_v1(p_workspace_key text, p_presentation_id text, p_claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e d5o_hosted.design_cost_evidence%rowtype; obj storage.objects%rowtype;
begin
 if current_setting('role',true)<>'service_role' then raise exception 'server_only' using errcode='42501'; end if;
 select x.* into e from d5o_hosted.design_cost_evidence x
  join d5o_hosted.workspaces ws on ws.id=x.workspace_id
  join d5o_hosted.work_identity_links l on l.workspace_id=x.workspace_id and l.work_id=x.work_id
  where ws.workspace_key=p_workspace_key and l.presentation_id=p_presentation_id and x.claim_id=p_claim_id;
 if e.id is null then return null; end if;
 select * into obj from storage.objects where bucket_id='d5o-deploy-evidence' and name=e.object_path;
 if obj.id is distinct from e.storage_object_id or obj.updated_at is distinct from e.storage_updated_at
  or (obj.metadata->>'size')::bigint is distinct from e.size_bytes
  or obj.metadata->>'mimetype' is distinct from 'application/pdf'
  then raise exception 'design_cost_evidence_changed' using errcode='23514'; end if;
 return pg_catalog.jsonb_build_object('evidenceId',e.id,'claimId',e.claim_id,
  'objectPath',e.object_path,'checksumSha256',e.checksum_sha256,'sizeBytes',e.size_bytes,
  'filename',e.filename,'uploadedBy',e.uploaded_by,'uploadedAt',e.uploaded_at);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_evidence_read_v2(p_workspace_key text, p_presentation_id text, p_claim_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; w d5o_hosted.work_records%rowtype; member d5o_hosted.memberships%rowtype;
begin
 if current_setting('role',true)<>'service_role' or p_actor_id is null
  then raise exception 'server_only' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select r.* into w from d5o_hosted.work_records r join d5o_hosted.work_identity_links l
  on l.workspace_id=r.workspace_id and l.work_id=r.id
  where r.workspace_id=ws and l.presentation_id=p_presentation_id;
 select * into member from d5o_hosted.memberships where workspace_id=ws
  and actor_user_id=p_actor_id and status='active';
 if w.id is null or member.id is null or not (member.role='billing_commercial_lead'
  or (member.role='project_manager' and w.created_by=p_actor_id))
  or not exists(select 1 from d5o_hosted.design_cost_claims c where c.id=p_claim_id
   and c.workspace_id=ws and c.work_id=w.id)
  then raise exception 'design_cost_evidence_scope_denied' using errcode='42501'; end if;
 return public.d5o_hosted_design_cost_evidence_read_v1(p_workspace_key,p_presentation_id,p_claim_id);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_read_pre_rate_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a uuid:=auth.uid(); ws uuid; w uuid; src jsonb;
begin
 if current_setting('role',true)<>'authenticated' or a is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 if not exists(select 1 from d5o_hosted.memberships where workspace_id=ws and actor_user_id=a and status='active'
  and role in ('admin','project_manager','billing_commercial_lead')) then raise exception 'design_cost_scope_denied' using errcode='42501'; end if;
 select work_id into w from d5o_hosted.work_identity_links where workspace_id=ws and presentation_id=p_presentation_id;
 if w is null then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
 src:=d5o_hosted.outlook_source_v1(ws,w);
 return pg_catalog.jsonb_build_object('revision',coalesce((select revision from d5o_hosted.design_cost_positions where workspace_id=ws and work_id=w),0),
  'sourceDigest',src->>'digest','sourceBasis',src->'basis',
  'commitments',coalesce((select pg_catalog.jsonb_agg(to_jsonb(c) order by c.created_at) from d5o_hosted.design_spend_commitments c where c.workspace_id=ws and c.work_id=w and c.status='Approved'),'[]'::jsonb),
  'links',coalesce((select pg_catalog.jsonb_agg(to_jsonb(l)) from d5o_hosted.design_cost_links l where l.workspace_id=ws and l.work_id=w),'[]'::jsonb),
  'claims',coalesce((select pg_catalog.jsonb_agg(to_jsonb(c) order by c.created_at) from d5o_hosted.design_cost_claims c where c.workspace_id=ws and c.work_id=w),'[]'::jsonb),
  'assessments',coalesce((select pg_catalog.jsonb_agg(to_jsonb(x) order by x.created_at) from d5o_hosted.outlook_assessments x where x.workspace_id=ws and x.work_id=w),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_cost_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb; ws uuid; w uuid;
begin
 base:=public.d5o_hosted_design_cost_read_pre_rate_v1(p_workspace_key,p_presentation_id);
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select work_id into w from d5o_hosted.work_identity_links where workspace_id=ws and presentation_id=p_presentation_id;
 return base||pg_catalog.jsonb_build_object('ratedBases',coalesce((select pg_catalog.jsonb_agg(to_jsonb(x) order by x.claim_id)
  from d5o_hosted.design_cost_rate_basis x where x.workspace_id=ws and x.work_id=w),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_demand_command_v1(p_workspace_key text, p_presentation_id text, p_demand jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_receipt d5o_hosted.connected_design_receipts%rowtype;
  v_target jsonb;v_slot jsonb;v_demands jsonb;v_state jsonb;
  v_fingerprint text;v_result jsonb;v_now timestamptz:=now();
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or pg_catalog.jsonb_typeof(p_demand)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<1 then
    raise exception 'invalid_design_demand_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('admin','project_manager','operations_leader') then
    raise exception 'design_demand_role_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_demand,p_expected_source_revision,
    p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_design_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_handoff from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_decision_revision
    or v_handoff.status is distinct from 'accepted'
    or v_design.source_handoff_revision<>v_handoff.revision then
    raise exception 'stale_design_demand_basis' using errcode='23505'; end if;
  perform d5o_hosted.connected_design_source_v1(v_workspace.id,v_work.id,v_raw.state_json);
  select p into v_target from pg_catalog.jsonb_array_elements(v_design.state->'packages') p
    where p->>'packageId'=p_demand->>'packageId';
  if v_target is null or p_demand->>'workId'<>p_presentation_id
    or p_demand->>'qualification' is null
    or coalesce((p_demand->>'minimumPeople')::integer,0)<1
    or coalesce((p_demand->>'estimatedPersonHours')::numeric,0)<=0
    or pg_catalog.jsonb_typeof(p_demand->'requiredSlots')<>'array'
    or pg_catalog.jsonb_array_length(p_demand->'requiredSlots')=0
    or p_demand->>'priority' not in ('Critical','High','Normal') then
    raise exception 'dated_design_demand_invalid' using errcode='23514'; end if;
  for v_slot in select value from pg_catalog.jsonb_array_elements(p_demand->'requiredSlots') loop
    if coalesce(v_slot->>'date','')<v_target->>'windowStart'
      or coalesce(v_slot->>'date','')>v_target->>'windowEnd'
      or coalesce(v_slot->>'shift','')='' then
      raise exception 'demand_outside_package_window' using errcode='23514'; end if;
  end loop;
  if exists(select 1 from pg_catalog.jsonb_array_elements(v_design.state->'releases') r
    where r->>'packageId'=p_demand->>'packageId'
      and r->>'status' in ('Awaiting receipt','Accepted')) then
    raise exception 'released_demand_locked' using errcode='23514'; end if;
  v_demands:=(select coalesce(pg_catalog.jsonb_agg(d order by ordinal),'[]'::jsonb)
    from pg_catalog.jsonb_array_elements(coalesce(v_design.state->'demands','[]'::jsonb))
      with ordinality as entries(d,ordinal)
    where d->>'packageId'<>p_demand->>'packageId');
  v_demands:=v_demands||pg_catalog.jsonb_build_array(
    pg_catalog.jsonb_build_object('workId',p_presentation_id,
      'packageId',p_demand->>'packageId','qualification',p_demand->>'qualification',
      'minimumPeople',(p_demand->>'minimumPeople')::integer,
      'estimatedPersonHours',(p_demand->>'estimatedPersonHours')::numeric,
      'requiredSlots',p_demand->'requiredSlots','priority',p_demand->>'priority',
      'prerequisite',coalesce(p_demand->>'prerequisite',''),
      'crewSchedulable',coalesce((p_demand->>'crewSchedulable')::boolean,true),
      'designPackageRevision',(v_target->>'revision')::integer));
  v_state:=v_design.state||pg_catalog.jsonb_build_object(
    'demands',v_demands,'authorityRevision',v_design.decision_revision+1,
    'history',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'at',v_now,'actorId',v_actor,'membershipId',v_member.id,
      'action','save-demand · '||p_command_id,
      'note','Dated qualified package demand recorded',
      'packageId',p_demand->>'packageId',
      'revision',(v_target->>'revision')::integer))||
      coalesce(v_design.state->'history','[]'::jsonb));
  update d5o_hosted.connected_design_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_design_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    source_handoff_revision,snapshot,reason)
  values(v_workspace.id,v_work.id,v_design.decision_revision+1,p_command_id,
    'save-demand',v_actor,v_member.id,v_handoff.revision,v_state,
    'Dated qualified package demand recorded');
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_design_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_draft_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype;
  v_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_receipt d5o_hosted.connected_design_receipts%rowtype;
  v_fingerprint text;v_source jsonb;v_previous jsonb;v_document jsonb;
  v_package jsonb;v_basis jsonb;v_input jsonb;v_next jsonb;
  v_result jsonb;v_id text;v_revision integer;v_now timestamptz:=now();
  v_item jsonb;v_ref text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-document','save-package')
    or p_input is null or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<0 then
    raise exception 'invalid_design_draft_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('admin','project_manager','operations_leader') then
    raise exception 'design_editor_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_input,p_expected_source_revision,
    p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_design_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_handoff from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or coalesce(v_design.decision_revision,0)<>p_expected_decision_revision
    or v_handoff.status is distinct from 'accepted'
    or v_design.source_handoff_revision is not null and
      v_design.source_handoff_revision<>v_handoff.revision then
    raise exception 'stale_design_basis' using errcode='23505'; end if;
  v_source:=d5o_hosted.connected_design_source_v1(v_workspace.id,v_work.id,v_state.state_json);
  v_next:=coalesce(v_design.state,pg_catalog.jsonb_build_object(
    'documents','[]'::jsonb,'packages','[]'::jsonb,'reviews','[]'::jsonb,
    'releases','[]'::jsonb,'history','[]'::jsonb));
  if p_action='save-document' then
    v_input:=p_input->'document';
    if pg_catalog.jsonb_typeof(v_input) is distinct from 'object'
      or length(trim(coalesce(v_input->>'title',''))) not between 3 and 200
      or length(trim(coalesce(v_input->>'type',''))) not between 2 and 100
      or length(trim(coalesce(v_input->>'source',''))) not between 5 and 2000
      or pg_catalog.jsonb_typeof(v_input->'packageIds')<>'array'
      or pg_catalog.jsonb_typeof(v_input->'requirementIds') is distinct from 'array' then
      raise exception 'document_draft_invalid' using errcode='22023'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_input->'packageIds') loop
      if pg_catalog.jsonb_typeof(v_item)<>'string' or not exists(
        select 1 from pg_catalog.jsonb_array_elements(v_source->'packages') p
          where p->>'id'=v_item#>>'{}') then
        raise exception 'document_package_reference_invalid' using errcode='23514'; end if;
    end loop;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_input->'requirementIds') loop
      if pg_catalog.jsonb_typeof(v_item)<>'string' or not exists(
        select 1 from pg_catalog.jsonb_array_elements(
          d5o_hosted.connected_design_requirements_v1(v_source)) r
          where r->>'id'=v_item#>>'{}') then
        raise exception 'document_requirement_reference_invalid' using errcode='23514'; end if;
    end loop;
    v_id:=coalesce(nullif(trim(v_input->>'id'),''),gen_random_uuid()::text);
    select max((d->>'revision')::integer) into v_revision
      from pg_catalog.jsonb_array_elements(v_next->'documents') d where d->>'id'=v_id;
    v_revision:=coalesce(v_revision,0)+1;
    v_document:=pg_catalog.jsonb_build_object('id',v_id,'revision',v_revision,
      'type',trim(v_input->>'type'),'title',trim(v_input->>'title'),
      'source',trim(v_input->>'source'),
      'owner',coalesce(nullif(trim(v_input->>'owner'),''),v_actor::text),
      'packageIds',v_input->'packageIds',
      'requirementIds',v_input->'requirementIds',
      'status','Draft','dueDate',coalesce(v_input->>'dueDate',''),
      'createdAt',v_now,'createdByActorId',v_actor);
    v_next:=pg_catalog.jsonb_set(v_next,'{documents}',
      v_next->'documents'||pg_catalog.jsonb_build_array(v_document));
  else
    v_input:=p_input->'package';
    v_id:=v_input->>'packageId';
    if pg_catalog.jsonb_typeof(v_input)<>'object' or v_id is null
      or not exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_source->'packages','[]'::jsonb)) p where p->>'id'=v_id)
      or pg_catalog.jsonb_typeof(v_input->'requirementIds')<>'array'
      or pg_catalog.jsonb_typeof(v_input->'predecessorIds') is distinct from 'array'
      or pg_catalog.jsonb_typeof(v_input->'documentRefs') is distinct from 'array'
      or v_input#>>'{completionBasis,kind}' is null or v_input#>>'{completionBasis,kind}' not in ('Measured','Qualitative')
      or v_input#>>'{completionBasis,kind}'='Measured' and
        (coalesce((v_input#>>'{completionBasis,plannedQuantity}')::numeric,0)<=0
          or length(trim(coalesce(v_input#>>'{completionBasis,unit}','')))=0)
      or v_input#>>'{completionBasis,kind}'='Qualitative' and
        length(trim(coalesce(v_input#>>'{completionBasis,criterion}','')))<10 then
      raise exception 'package_draft_invalid' using errcode='22023'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_input->'predecessorIds') loop
      if v_item#>>'{}'=v_id or not exists(select 1 from
        pg_catalog.jsonb_array_elements(v_source->'packages') p
        where p->>'id'=v_item#>>'{}') then
        raise exception 'package_predecessor_invalid' using errcode='23514'; end if;
    end loop;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_input->'requirementIds') loop
      if not exists(select 1 from pg_catalog.jsonb_array_elements(
        d5o_hosted.connected_design_requirements_v1(v_source)) r
        where r->>'id'=v_item#>>'{}') then
        raise exception 'package_requirement_invalid' using errcode='23514'; end if;
    end loop;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_input->'documentRefs') loop
      v_ref:=v_item#>>'{}';
      if not exists(select 1 from pg_catalog.jsonb_array_elements(v_next->'documents') d
        where (d->>'id')||'@'||(d->>'revision')=v_ref
          and d->'packageIds' ? v_id) then
        raise exception 'package_document_invalid' using errcode='23514'; end if;
    end loop;
    if v_input->>'commercialDisposition' is null or v_input->>'commercialDisposition' not in ('None','Assessment required',
      'Routed to Develop') or v_input->>'materialStatus' is null or v_input->>'materialStatus' not in
      ('Unknown','Planned','Ordered','Supplier confirmed','Received','Available','Not required') then
      raise exception 'package_status_invalid' using errcode='22023'; end if;
    if v_input->>'materialStatus'='Not required' then
      if pg_catalog.jsonb_typeof(v_input->'materialLines') is distinct from 'array'
        or length(trim(coalesce(v_input->>'materials','')))<20
        or length(trim(coalesce(v_input->>'materialSource','')))<8
        or length(trim(coalesce(v_input->>'materialRequiredDate','')))>0
        or length(trim(coalesce(v_input->>'materialForecastDate','')))>0 then
        raise exception 'no_material_basis_invalid' using errcode='23514'; end if;
      if pg_catalog.jsonb_array_length(v_input->'materialLines')<>0 then
        raise exception 'no_material_basis_invalid' using errcode='23514'; end if;
    end if;
    select p into v_previous from pg_catalog.jsonb_array_elements(v_next->'packages') p
      where p->>'packageId'=v_id;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_next->'releases') r
      where r->>'packageId'=v_id and r->>'status' in ('Awaiting receipt','Accepted')) then
      raise exception 'released_package_locked' using errcode='23514'; end if;
    v_revision:=coalesce((v_previous->>'revision')::integer,0)+1;
    v_basis:=v_input->'completionBasis';
    v_package:=pg_catalog.jsonb_build_object(
      'packageId',v_id,'revision',v_revision,'scope',coalesce(v_input->>'scope',''),
      'location',coalesce(v_input->>'location',''),
      'systems',coalesce(v_input->>'systems',''),
      'completionBasis',v_basis,'requirementIds',v_input->'requirementIds',
      'predecessorIds',v_input->'predecessorIds',
      'documentRefs',v_input->'documentRefs',
      'materials',coalesce(v_input->>'materials',''),
      'materialLines',coalesce(v_input->'materialLines','[]'::jsonb),
      'materialStatus',v_input->>'materialStatus',
      'materialRequiredDate',coalesce(v_input->>'materialRequiredDate',''),
      'materialForecastDate',coalesce(v_input->>'materialForecastDate',''),
      'materialSource',coalesce(v_input->>'materialSource',''),
      'access',coalesce(v_input->>'access',''),
      'permit',coalesce(v_input->>'permit',''),
      'safetyControls',coalesce(v_input->>'safetyControls',''),
      'equipment',coalesce(v_input->>'equipment',''),
      'method',coalesce(v_input->>'method',''),
      'rollback',coalesce(v_input->>'rollback',''),
      'verification',coalesce(v_input->>'verification',''),
      'proof',coalesce(v_input->>'proof',''),
      'acceptingAuthority',coalesce(v_input->>'acceptingAuthority',''),
      'windowStart',coalesce(v_input->>'windowStart',''),
      'windowEnd',coalesce(v_input->>'windowEnd',''),
      'targetReleaseDate',coalesce(v_input->>'targetReleaseDate',''),
      'crewDemandRequired',coalesce((v_input->>'crewDemandRequired')::boolean,true),
      'crewExemptionReason',coalesce(v_input->>'crewExemptionReason',''),
      'commercialImpact',coalesce(v_input->>'commercialImpact',''),
      'commercialDisposition',v_input->>'commercialDisposition',
      'status','Draft');
    v_next:=pg_catalog.jsonb_set(v_next,'{packages}',
      (select coalesce(pg_catalog.jsonb_agg(p order by ordinal),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(v_next->'packages')
          with ordinality as entries(p,ordinal) where p->>'packageId'<>v_id)
        ||pg_catalog.jsonb_build_array(v_package));
  end if;
  v_next:=v_next||pg_catalog.jsonb_build_object(
    'authorityRevision',coalesce(v_design.decision_revision,0)+1,
    'history',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'at',v_now,'actorId',v_actor,'membershipId',v_member.id,
      'action',p_action||' · '||p_command_id,'note',coalesce(p_input->>'note',''),
      'packageId',case when p_action='save-package' then v_id else null end,
      'revision',v_revision))||coalesce(v_next->'history','[]'::jsonb));
  if v_design.work_id is null then
    insert into d5o_hosted.connected_design_states(workspace_id,work_id,
      decision_revision,source_handoff_revision,state)
    values(v_workspace.id,v_work.id,1,v_handoff.revision,v_next);
  else
    update d5o_hosted.connected_design_states set
      decision_revision=decision_revision+1,state=v_next,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
  end if;
  insert into d5o_hosted.connected_design_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    source_handoff_revision,snapshot,reason)
  values(v_workspace.id,v_work.id,coalesce(v_design.decision_revision,0)+1,
    p_command_id,p_action,v_actor,v_member.id,v_handoff.revision,v_next,
    coalesce(p_input->>'note',''));
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_design_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_field_change_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_source d5o_hosted.prototype_states%rowtype;
  v_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_receipt d5o_hosted.connected_design_receipts%rowtype;
  v_field d5o_hosted.connected_field_changes%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_state jsonb;v_target jsonb;v_item jsonb;v_change jsonb;v_release jsonb;
  v_changes jsonb;v_releases jsonb;v_result jsonb;
  v_package text;v_source_id text;v_note text;v_fingerprint text;v_timezone text;
  v_now timestamptz:=clock_timestamp();v_revision integer;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('record-change','record-schedule-hold','acknowledge-hold','resolve-change')
    or p_input is null or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<1 then
    raise exception 'invalid_design_change_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  if p_action in ('record-change','record-schedule-hold','resolve-change') and
      v_member.role not in ('admin','project_manager','operations_leader')
    or p_action='acknowledge-hold' and
      v_member.role not in ('admin','field_supervisor','operations_leader') then
    raise exception 'design_change_role_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_input,p_expected_source_revision,
    p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_design_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_source from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_handoff from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if not found or v_source.revision is distinct from p_expected_source_revision
    or v_design.decision_revision<>p_expected_decision_revision
    or v_handoff.status is distinct from 'accepted'
    or v_design.source_handoff_revision<>v_handoff.revision then
    raise exception 'stale_design_basis' using errcode='23505'; end if;
  v_state:=v_design.state;
  v_note:=trim(coalesce(p_input->>'note',''));
  if p_action='record-change' then
    v_package:=trim(coalesce(p_input->>'packageId',''));
    v_source_id:=trim(coalesce(p_input->>'source',''));
    if v_source_id !~ '^field-change:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or length(trim(coalesce(p_input->>'reason','')))<20
      or length(trim(coalesce(p_input->>'technicalImpact','')))<10
      or length(trim(coalesce(p_input->>'scheduleImpact','')))<5 then
      raise exception 'design_change_incomplete' using errcode='22023'; end if;
    select * into v_field from d5o_hosted.connected_field_changes
      where workspace_id=v_workspace.id and work_id=v_work.id
        and id=substring(v_source_id from 14)::uuid and package_id=v_package
      for share;
    if not found or v_field.kind<>'Scope change'
      or v_field.status<>'Customer authorized' then
      raise exception 'customer_change_authorization_required' using errcode='23514'; end if;
    select item into v_target from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'packages','[]'::jsonb)) item
      where item->>'packageId'=v_package;
    if v_target is null or (v_target->>'revision')::integer<>v_field.opened_package_revision
      or exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_state->'changes','[]'::jsonb)) c
        where c->>'packageId'=v_package and c->>'status'='Open') then
      raise exception 'field_change_package_revision_mismatch' using errcode='23514'; end if;
    v_change:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),
      'packageId',v_package,'openedRevision',(v_target->>'revision')::integer,
      'sourceHandoffRevision',v_handoff.revision,'source',v_source_id,
      'sourceFieldRevision',v_field.revision,'reason',trim(p_input->>'reason'),
      'affectedRequirementIds',coalesce(p_input->'affectedRequirementIds','[]'::jsonb),
      'affectedDocumentRefs',coalesce(p_input->'affectedDocumentRefs','[]'::jsonb),
      'technicalImpact',trim(p_input->>'technicalImpact'),
      'commercialImpact',coalesce(p_input->>'commercialImpact',''),
      'scheduleImpact',trim(p_input->>'scheduleImpact'),
      'status','Open','openedAt',v_now,'openedByActorId',v_actor);
    v_changes:=coalesce(v_state->'changes','[]'::jsonb)||pg_catalog.jsonb_build_array(v_change);
    v_state:=pg_catalog.jsonb_set(v_state,'{changes}',v_changes);
    select coalesce(pg_catalog.jsonb_agg(case when item->>'packageId'=v_package
      and item->>'status' in ('Accepted','Awaiting receipt') then
        item||pg_catalog.jsonb_build_object('status','Hold pending acknowledgment',
          'holdAt',v_now,'holdByActorId',v_actor,'holdReason',p_input->>'reason')
      else item end order by ordinal),'[]'::jsonb) into v_releases
      from pg_catalog.jsonb_array_elements(coalesce(v_state->'releases','[]'::jsonb))
        with ordinality as releases(item,ordinal);
    v_state:=pg_catalog.jsonb_set(v_state,'{releases}',v_releases);
  elsif p_action='record-schedule-hold' then
    v_package:=trim(coalesce(p_input->>'packageId',''));
    -- A same-day future shift is valid. Compare the proposed local date with
    -- the Work-pinned time zone, while later demand/publication/start commands
    -- continue to enforce exact shift, release and real-time eligibility.
    if v_work.configuration_version_id is not null then
      select wt#>>'{operateControls,timezone}' into v_timezone
        from d5o_hosted.configuration_versions c,
          lateral pg_catalog.jsonb_array_elements(
            c.manifest_json#>'{d5oPresentation,phaseContract,workTypes}') wt
        where c.id=v_work.configuration_version_id
          and wt->>'workTypeKey'=v_work.work_type_key;
      if coalesce(v_timezone,'')='' then
        raise exception 'schedule_timezone_unavailable' using errcode='23514'; end if;
    else
      v_timezone:=current_setting('TimeZone');
    end if;
    if length(v_note)<20
      or coalesce(p_input->>'proposedDate','') !~ '^\d{4}-\d{2}-\d{2}$'
      or (p_input->>'proposedDate')::date<(v_now at time zone v_timezone)::date then
      raise exception 'schedule_correction_incomplete' using errcode='22023'; end if;
    select item into v_release from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'releases','[]'::jsonb)) item
      where item->>'id'=p_input->>'releaseId'
        and item->>'packageId'=v_package and item->>'status'='Accepted';
    select item into v_target from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'packages','[]'::jsonb)) item
      where item->>'packageId'=v_package;
    if v_release is null or v_target is null
      or (v_release->>'packageRevision')::integer<>(v_target->>'revision')::integer
      or exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_state->'releases','[]'::jsonb)) r
        where r->>'packageId'=v_package and r->>'id'<>v_release->>'id'
          and r->>'status' in ('Accepted','Awaiting receipt','Hold pending acknowledgment')) then
      raise exception 'current_accepted_release_required' using errcode='23514'; end if;
    select * into v_deploy from d5o_hosted.connected_deploy_states
      where workspace_id=v_workspace.id and work_id=v_work.id for share;
    if v_deploy.state#>>'{workAcceptance,receipt}'='Accepted'
      or exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_deploy.state->'reports','[]'::jsonb)) report
        where report->>'releaseId'=v_release->>'id')
      or exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_deploy.state->'permits','[]'::jsonb)) permit
        where permit->>'releaseId'=v_release->>'id' and permit->>'status'='Authorized') then
      raise exception 'schedule_hold_after_execution_denied' using errcode='23514'; end if;
    select coalesce(pg_catalog.jsonb_agg(case when item->>'id'=v_release->>'id'
      then item||pg_catalog.jsonb_build_object('status','Hold pending acknowledgment',
        'holdKind','Schedule correction','holdAt',v_now,'holdByActorId',v_actor,
        'holdReason',v_note,'proposedDate',p_input->>'proposedDate')
      else item end order by ordinal),'[]'::jsonb) into v_releases
      from pg_catalog.jsonb_array_elements(v_state->'releases')
        with ordinality as releases(item,ordinal);
    v_state:=pg_catalog.jsonb_set(v_state,'{releases}',v_releases);
  elsif p_action='acknowledge-hold' then
    if length(v_note)<15 then raise exception 'hold_acknowledgment_reason_required' using errcode='22023'; end if;
    select item into v_release from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'releases','[]'::jsonb)) item
      where item->>'id'=p_input->>'releaseId'
        and item->>'status'='Hold pending acknowledgment';
    if v_release is null or v_release->>'holdByActorId'=v_actor::text then
      raise exception 'independent_hold_acknowledgment_required' using errcode='23514'; end if;
    v_package:=v_release->>'packageId';
    select coalesce(pg_catalog.jsonb_agg(case when item->>'id'=p_input->>'releaseId'
      then item||pg_catalog.jsonb_build_object('status','Held',
        'holdAcknowledgedAt',v_now,'holdAcknowledgedByActorId',v_actor,
        'responseNote',v_note) else item end order by ordinal),'[]'::jsonb)
      into v_releases from pg_catalog.jsonb_array_elements(v_state->'releases')
        with ordinality as releases(item,ordinal);
    v_state:=pg_catalog.jsonb_set(v_state,'{releases}',v_releases);
  else
    if length(v_note)<20 then raise exception 'change_resolution_reason_required' using errcode='22023'; end if;
    select item into v_change from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'changes','[]'::jsonb)) item
      where item->>'id'=p_input->>'changeId' and item->>'status'='Open';
    if v_change is null then raise exception 'open_design_change_required' using errcode='23514'; end if;
    v_package:=v_change->>'packageId';
    select item into v_target from pg_catalog.jsonb_array_elements(v_state->'packages') item
      where item->>'packageId'=v_package;
    select * into v_field from d5o_hosted.connected_field_changes
      where workspace_id=v_workspace.id and work_id=v_work.id
        and id=substring(v_change->>'source' from 14)::uuid for share;
    if v_target is null or (v_target->>'revision')::integer<=(v_change->>'openedRevision')::integer
      or not found or v_field.status<>'Customer authorized'
      or exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'releases') r
        where r->>'packageId'=v_package and r->>'status'='Hold pending acknowledgment') then
      raise exception 'change_resolution_premature' using errcode='23514'; end if;
    select coalesce(pg_catalog.jsonb_agg(case when item->>'id'=p_input->>'changeId'
      then item||pg_catalog.jsonb_build_object('status','Resolved',
        'resolvedAt',v_now,'resolvedByActorId',v_actor,'resolution',v_note)
      else item end order by ordinal),'[]'::jsonb) into v_changes
      from pg_catalog.jsonb_array_elements(v_state->'changes')
        with ordinality as changes(item,ordinal);
    v_state:=pg_catalog.jsonb_set(v_state,'{changes}',v_changes);
  end if;
  v_revision:=v_design.decision_revision+1;
  v_state:=v_state||pg_catalog.jsonb_build_object('authorityRevision',v_revision,
    'history',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'at',v_now,'actorId',v_actor,'membershipId',v_member.id,
      'action',p_action||' · '||p_command_id,'note',v_note,
      'packageId',v_package,'revision',coalesce((v_target->>'revision')::integer,0)))
      ||coalesce(v_state->'history','[]'::jsonb));
  update d5o_hosted.connected_design_states set decision_revision=v_revision,
    state=v_state,updated_at=v_now where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_design_events(workspace_id,work_id,decision_revision,
    command_id,action,actor_user_id,membership_id,source_handoff_revision,snapshot,reason)
  values(v_workspace.id,v_work.id,v_revision,p_command_id,p_action,v_actor,v_member.id,
    v_handoff.revision,v_state,coalesce(nullif(v_note,''),p_input->>'reason'));
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_design_receipts(workspace_id,command_id,work_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_release_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_receipt d5o_hosted.connected_design_receipts%rowtype;
  v_policy jsonb;v_state jsonb;v_source jsonb;v_target jsonb;
  v_demand jsonb;v_release jsonb;v_review jsonb;v_doc jsonb;
  v_item jsonb;v_ref text;v_package text;v_revision integer;
  v_id text;v_receiving_role text;v_note text:=trim(coalesce(p_input->>'note',''));
  v_now timestamptz:=now();v_fingerprint text;v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('release-package','respond-receipt')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<1 then
    raise exception 'invalid_design_release_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('admin','project_manager','operations_leader') then
    raise exception 'design_release_role_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_input,p_expected_source_revision,
    p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_design_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_handoff from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_decision_revision
    or v_handoff.status is distinct from 'accepted'
    or v_design.source_handoff_revision<>v_handoff.revision then
    raise exception 'stale_design_release_basis' using errcode='23505'; end if;
  select wt->'designControls' into v_policy
    from d5o_hosted.configuration_versions c,
      lateral pg_catalog.jsonb_array_elements(
        c.manifest_json#>'{d5oPresentation,phaseContract,workTypes}') wt
    where c.id=v_work.configuration_version_id
      and wt->>'workTypeKey'=v_work.work_type_key;
  if v_policy is null or v_policy->>'schemaVersion'<>'1' then
    raise exception 'pinned_design_policy_unavailable' using errcode='23514'; end if;
  v_source:=d5o_hosted.connected_design_source_v1(v_workspace.id,v_work.id,v_raw.state_json);
  v_state:=v_design.state;
  if p_action='release-package' then
    if v_member.role not in ('project_manager','operations_leader','admin') then
      raise exception 'delivery_release_authority_required' using errcode='42501'; end if;
    if v_policy->>'allowPartialRelease'<>'true' then
      raise exception 'partial_release_policy_denied' using errcode='23514'; end if;
    v_package:=p_input->>'packageId';
    select p into v_target from pg_catalog.jsonb_array_elements(v_state->'packages') p
      where p->>'packageId'=v_package;
    if v_target is null or not exists(select 1 from
      pg_catalog.jsonb_array_elements(v_source->'packages') p
        where p->>'id'=v_package) then
      raise exception 'release_package_unavailable' using errcode='23514'; end if;
    v_revision:=(v_target->>'revision')::integer;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'releases') r
      where r->>'packageId'=v_package and r->>'status' in ('Awaiting receipt','Accepted')) then
      raise exception 'active_release_exists' using errcode='23514'; end if;
    if p_input ? 'receivingOwner' or
      coalesce(p_input->>'dueDate','') !~ '^\d{4}-\d{2}-\d{2}$' or
      length(v_note)<15 then
      raise exception 'release_receiver_and_reason_required' using errcode='22023'; end if;
    if v_target->>'scope'='' or v_target->>'location'=''
      or v_target->>'systems'='' or v_target->>'safetyControls'=''
      or v_target->>'verification'='' or v_target->>'proof'=''
      or v_target->>'acceptingAuthority'=''
      or (v_policy->>'requireAccess'='true' and v_target->>'access'='')
      or (v_policy->>'requirePermit'='true' and v_target->>'permit'='')
      or (v_policy->>'requireMop'='true' and v_target->>'method'='')
      or (v_policy->>'requireRollback'='true' and v_target->>'rollback'='')
      or coalesce(v_target->>'commercialDisposition','')<>'None'
      or coalesce(v_target->>'commercialImpact','')<>''
      or v_target->>'windowStart'='' or v_target->>'windowEnd'=''
      or v_target->>'windowEnd'<v_target->>'windowStart'
      or pg_catalog.jsonb_array_length(v_target->'requirementIds')=0
      or pg_catalog.jsonb_array_length(v_target->'documentRefs')=0
      or v_target#>>'{completionBasis,kind}' not in ('Measured','Qualitative') then
      raise exception 'package_release_readiness_blocked' using errcode='23514'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_target->'predecessorIds') loop
      if not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'releases') r
        where r->>'packageId'=v_item#>>'{}' and r->>'status'='Accepted'
          and (r->>'packageRevision')::integer=(select (p->>'revision')::integer
            from pg_catalog.jsonb_array_elements(v_state->'packages') p
              where p->>'packageId'=v_item#>>'{}')) then
        raise exception 'predecessor_receipt_required' using errcode='23514'; end if;
    end loop;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_target->'requirementIds') loop
      if not exists(select 1 from pg_catalog.jsonb_array_elements(
        d5o_hosted.connected_design_requirements_v1(v_source)) r
          where r->>'id'=v_item#>>'{}') then
        raise exception 'package_requirement_stale' using errcode='23514'; end if;
    end loop;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_target->'documentRefs') loop
      v_ref:=v_item#>>'{}';
      select d into v_doc from pg_catalog.jsonb_array_elements(v_state->'documents') d
        where (d->>'id')||'@'||(d->>'revision')=v_ref and
          d->>'status'='Issued for use' and d->'packageIds' ? v_package;
      if v_doc is null then
        raise exception 'issued_document_revision_required' using errcode='23514'; end if;
    end loop;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_policy->'requiredReviews') loop
      select r into v_review from pg_catalog.jsonb_array_elements(v_state->'reviews') r
        where r->>'packageId'=v_package
          and (r->>'revision')::integer=v_revision
          and r->>'discipline'=v_item#>>'{}' and r->>'status'='Approved';
      if v_review is null then
        raise exception 'package_independent_review_required' using errcode='23514'; end if;
      if v_item#>>'{}'='Engineering' and v_review->>'decidedByActorId'=v_actor::text then
        raise exception 'release_separation_required' using errcode='42501'; end if;
    end loop;
    if v_policy->>'requireMaterialAvailability'='true' then
      if v_target->>'materialStatus'='Not required' then
        if pg_catalog.jsonb_array_length(coalesce(v_target->'materialLines','[]'::jsonb))<>0
          or pg_catalog.length(pg_catalog.btrim(coalesce(v_target->>'materials','')))<20
          or pg_catalog.length(pg_catalog.btrim(coalesce(v_target->>'materialSource','')))<8 then
          raise exception 'approved_no_material_basis_required' using errcode='23514'; end if;
      else
        if pg_catalog.jsonb_array_length(coalesce(v_target->'materialLines','[]'::jsonb))=0 then
          raise exception 'physical_material_basis_required' using errcode='23514'; end if;
      end if;
      for v_item in select value from pg_catalog.jsonb_array_elements(v_target->'materialLines') loop
        if coalesce(v_item->>'item','')='' or coalesce(v_item->>'unit','')=''
          or coalesce(v_item->>'source','')='' or coalesce(v_item->>'requiredDate','')=''
          or coalesce(v_item->>'confidence','')<>'Physically counted'
          or v_item->>'status' not in ('Received','Available')
          or coalesce((v_item->>'quantity')::numeric,0)<=0
          or coalesce((v_item->>'receivedQuantity')::numeric,0)<
            (v_item->>'quantity')::numeric
          or (v_item->>'status'='Available' and
            coalesce((v_item->>'availableQuantity')::numeric,0)<
              (v_item->>'quantity')::numeric) then
          raise exception 'physical_material_availability_required' using errcode='23514'; end if;
      end loop;
    end if;
    if v_policy->>'requireCrewDemand'='true' then
      select d into v_demand from pg_catalog.jsonb_array_elements(
        coalesce(v_state->'demands','[]'::jsonb)) d
        where d->>'workId'=p_presentation_id and d->>'packageId'=v_package;
      if v_demand is null or coalesce(v_demand->>'qualification','')=''
        or (v_demand->>'designPackageRevision')::integer<>v_revision
        or coalesce((v_demand->>'minimumPeople')::integer,0)<1
        or coalesce((v_demand->>'estimatedPersonHours')::numeric,0)<=0
        or pg_catalog.jsonb_array_length(coalesce(v_demand->'requiredSlots','[]'::jsonb))=0 then
        raise exception 'dated_crew_demand_required' using errcode='23514'; end if;
      for v_item in select value from pg_catalog.jsonb_array_elements(v_demand->'requiredSlots') loop
        if coalesce(v_item->>'date','')<v_target->>'windowStart'
          or coalesce(v_item->>'date','')>v_target->>'windowEnd'
          or coalesce(v_item->>'shift','')='' then
          raise exception 'crew_demand_outside_window' using errcode='23514'; end if;
      end loop;
    end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'changes','[]'::jsonb)) c
        where c->>'packageId'=v_package and c->>'status'='Open') then
      raise exception 'open_design_change_blocks_release' using errcode='23514'; end if;
    v_receiving_role:=d5o_hosted.configured_handoff_role_v1(v_work.configuration_version_id,'designDeploy');
    if not exists(select 1 from d5o_hosted.memberships m
      where m.workspace_id=v_workspace.id and m.status='active'
        and m.role=v_receiving_role and m.actor_user_id<>v_actor) then
      raise exception 'configured_receiver_unavailable' using errcode='23514'; end if;
    v_id:=gen_random_uuid()::text;
    v_release:=pg_catalog.jsonb_build_object('id',v_id,'packageId',v_package,
      'packageRevision',v_revision,'documentRefs',v_target->'documentRefs',
      'sourceHandoffRevision',v_handoff.revision,
      'sourceKind',v_handoff.source_kind,
      'sourceId',v_handoff.handoff->>'id',
      'sourceDigest',v_handoff.source_digest,
      'definitionRevision',(v_source#>>'{definition,revision}')::integer,
      'configurationVersionId',v_work.configuration_version_id,
      'assessment',pg_catalog.jsonb_build_object('evaluatedAt',v_now,
        'packageId',v_package,'packageRevision',v_revision,
        'policyVersion',v_work.configuration_version_id,
        'recommendation','Ready for release','findings','[]'::jsonb),
      'issuedAt',v_now,'issuedByActorId',v_actor,
      'issuedByMembershipId',v_member.id,
      'receivingOwner','Configured '||v_receiving_role||' queue',
      'receivingRole',v_receiving_role,
      'responseDueDate',p_input->>'dueDate','status','Awaiting receipt',
      'snapshot',v_target,'documentSnapshots',
        (select coalesce(pg_catalog.jsonb_agg(d),'[]'::jsonb)
          from pg_catalog.jsonb_array_elements(v_state->'documents') d
          where v_target->'documentRefs' ? ((d->>'id')||'@'||(d->>'revision'))),
      'sourceSnapshot',v_handoff.handoff->'brief',
      'crewDemandSnapshot',v_demand);
    v_state:=pg_catalog.jsonb_set(v_state,'{releases}',
      v_state->'releases'||pg_catalog.jsonb_build_array(v_release));
    v_state:=pg_catalog.jsonb_set(v_state,'{packages}',
      (select pg_catalog.jsonb_agg(case when p->>'packageId'=v_package
        then p||pg_catalog.jsonb_build_object('status','Approved') else p end
        order by ordinal) from pg_catalog.jsonb_array_elements(v_state->'packages')
          with ordinality as entries(p,ordinal)));
  else
    v_id:=p_input->>'releaseId';
    select r into v_release from pg_catalog.jsonb_array_elements(v_state->'releases') r
      where r->>'id'=v_id and r->>'status'='Awaiting receipt';
    if v_release is null or p_input->>'response' not in ('Accepted','Returned')
      or length(v_note)<15 or v_release->>'issuedByActorId'=v_actor::text
      or (v_release->>'receivingRole' is not null
        and v_member.role is distinct from v_release->>'receivingRole') then
      raise exception 'independent_release_receipt_required' using errcode='42501'; end if;
    if p_input->>'response'='Accepted' then
      for v_item in select value from pg_catalog.jsonb_array_elements(
        v_release#>'{snapshot,predecessorIds}') loop
        if not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'releases') r
          where r->>'packageId'=v_item#>>'{}' and r->>'status'='Accepted'
            and (r->>'packageRevision')::integer=(select (p->>'revision')::integer
              from pg_catalog.jsonb_array_elements(v_state->'packages') p
              where p->>'packageId'=v_item#>>'{}')) then
          raise exception 'predecessor_receipt_required' using errcode='23514'; end if;
      end loop;
    end if;
    v_package:=v_release->>'packageId';
    v_revision:=(v_release->>'packageRevision')::integer;
    v_release:=v_release||pg_catalog.jsonb_build_object(
      'status',p_input->>'response','receivedAt',v_now,
      'receivedByActorId',v_actor,'receivedByMembershipId',v_member.id,
      'responseNote',v_note);
    v_state:=pg_catalog.jsonb_set(v_state,'{releases}',
      (select pg_catalog.jsonb_agg(case when r->>'id'=v_id then v_release
        else r end order by ordinal) from pg_catalog.jsonb_array_elements(
          v_state->'releases') with ordinality as entries(r,ordinal)));
  end if;
  v_state:=v_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_design.decision_revision+1,
    'history',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'at',v_now,'actorId',v_actor,'membershipId',v_member.id,
      'action',p_action||' · '||p_command_id,'note',v_note,
      'packageId',v_package,'revision',v_revision))||
      coalesce(v_state->'history','[]'::jsonb));
  update d5o_hosted.connected_design_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_design_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    source_handoff_revision,snapshot,reason)
  values(v_workspace.id,v_work.id,v_design.decision_revision+1,p_command_id,
    p_action,v_actor,v_member.id,v_handoff.revision,v_state,v_note);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_design_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_review_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_receipt d5o_hosted.connected_design_receipts%rowtype;
  v_fingerprint text;v_state jsonb;v_result jsonb;v_target jsonb;v_evidence jsonb;
  v_documents jsonb;v_reviews jsonb;v_packages jsonb;v_policy jsonb;
  v_now timestamptz:=now();v_id text;v_revision integer;v_package text;
  v_discipline text;v_note text:=trim(coalesce(p_input->>'note',''));
  v_due text;v_decision text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('submit-document','return-document','approve-document','issue-document',
      'request-review','decide-review')
    or p_input is null or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<1 then
    raise exception 'invalid_design_review_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'design_review_role_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_input,p_expected_source_revision,
    p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_design_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_handoff from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_decision_revision
    or v_handoff.status is distinct from 'accepted'
    or v_design.source_handoff_revision<>v_handoff.revision then
    raise exception 'stale_design_review_basis' using errcode='23505'; end if;
  select wt->'designControls' into v_policy
    from d5o_hosted.configuration_versions c,
      lateral pg_catalog.jsonb_array_elements(
        c.manifest_json#>'{d5oPresentation,phaseContract,workTypes}') wt
    where c.id=v_work.configuration_version_id
      and wt->>'workTypeKey'=v_work.work_type_key;
  if v_policy is null or v_policy->>'schemaVersion'<>'1' then
    raise exception 'pinned_design_policy_unavailable' using errcode='23514'; end if;
  v_state:=v_design.state;
  v_documents:=v_state->'documents';v_reviews:=v_state->'reviews';
  v_packages:=v_state->'packages';
  if p_action in ('submit-document','return-document','approve-document','issue-document') then
    v_id:=p_input->>'documentId';
    v_revision:=(p_input->>'documentRevision')::integer;
    select d into v_target from pg_catalog.jsonb_array_elements(v_documents) d
      where d->>'id'=v_id and (d->>'revision')::integer=v_revision;
    if v_target is null then raise exception 'document_revision_missing' using errcode='23514'; end if;
    if p_action='submit-document' then
      if v_member.role not in ('project_manager','admin')
        or v_target->>'status'<>'Draft' then
        raise exception 'document_submission_denied' using errcode='42501'; end if;
      v_evidence:=d5o_hosted.require_design_document_evidence_v1(
        v_workspace.id,v_work.id,v_id,v_revision,p_input->>'evidenceId');
      v_target:=v_target||pg_catalog.jsonb_build_object('status','In review',
        'submittedByActorId',v_actor,'submittedAt',v_now,
        'evidenceId',v_evidence->>'evidenceId',
        'evidenceChecksumSha256',v_evidence->>'checksumSha256');
    elsif p_action='return-document' then
      if v_member.role<>'operations_leader'
        or v_target->>'status'<>'In review'
        or v_target->>'submittedByActorId'=v_actor::text
        or length(v_note)<15 then
        raise exception 'independent_document_return_required' using errcode='42501'; end if;
      v_target:=v_target||pg_catalog.jsonb_build_object('status','Returned',
        'returnedByActorId',v_actor,'returnedAt',v_now,'returnNote',v_note);
    elsif p_action='approve-document' then
      if v_member.role<>'operations_leader'
        or v_target->>'status'<>'In review'
        or v_target->>'submittedByActorId'=v_actor::text
        or length(v_note)<15 then
        raise exception 'independent_document_review_required' using errcode='42501'; end if;
      v_evidence:=d5o_hosted.require_design_document_evidence_v1(
        v_workspace.id,v_work.id,v_id,v_revision,v_target->>'evidenceId');
      if v_target->>'evidenceChecksumSha256'<>v_evidence->>'checksumSha256' then
        raise exception 'design_document_checksum_changed' using errcode='23514'; end if;
      v_target:=v_target||pg_catalog.jsonb_build_object('status','Approved',
        'approvedByActorId',v_actor,'approvedByMembershipId',v_member.id,
        'approvedAt',v_now,'reviewNote',v_note);
    else
      if v_member.role not in ('project_manager','admin')
        or v_target->>'status'<>'Approved'
        or v_target->>'approvedByActorId'=v_actor::text then
        raise exception 'independent_document_issue_required' using errcode='42501'; end if;
      v_evidence:=d5o_hosted.require_design_document_evidence_v1(
        v_workspace.id,v_work.id,v_id,v_revision,v_target->>'evidenceId');
      if v_target->>'evidenceChecksumSha256'<>v_evidence->>'checksumSha256' then
        raise exception 'design_document_checksum_changed' using errcode='23514'; end if;
      if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'releases') r
        where r->>'status' in ('Awaiting receipt','Accepted')
          and r->'documentRefs' ? (v_id||'@'||v_revision::text)) then
        raise exception 'active_field_revision_locked' using errcode='23514'; end if;
      v_target:=v_target||pg_catalog.jsonb_build_object('status','Issued for use',
        'issuedAt',v_now,'issuedBy',v_actor);
    end if;
    v_documents:=(select pg_catalog.jsonb_agg(case when d->>'id'=v_id
      and (d->>'revision')::integer=v_revision then v_target else d end order by ordinal)
      from pg_catalog.jsonb_array_elements(v_documents)
        with ordinality as entries(d,ordinal));
    v_state:=pg_catalog.jsonb_set(v_state,'{documents}',v_documents);
  elsif p_action='request-review' then
    v_package:=p_input->>'packageId';
    v_discipline:=p_input->>'discipline';
    v_due:=p_input->>'dueDate';
    select p into v_target from pg_catalog.jsonb_array_elements(v_packages) p
      where p->>'packageId'=v_package;
    if v_member.role not in ('project_manager','admin') or v_target is null
      or v_discipline is null or not (v_policy->'requiredReviews' ? v_discipline)
      or v_due is null or v_due !~ '^\d{4}-\d{2}-\d{2}$'
      or p_input->>'assignee' is distinct from v_discipline||' review queue'
      or exists(select 1 from pg_catalog.jsonb_array_elements(v_reviews) r
        where r->>'packageId'=v_package
          and r->>'revision'=v_target->>'revision'
          and r->>'discipline'=v_discipline and r->>'status'='Requested') then
      raise exception 'package_review_request_invalid' using errcode='23514'; end if;
    v_id:=gen_random_uuid()::text;
    v_revision:=(v_target->>'revision')::integer;
    v_reviews:=v_reviews||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',v_id,'packageId',v_package,
        'revision',v_revision,'discipline',v_discipline,'status','Requested',
        'assignee',v_discipline||' review queue','dueDate',v_due,
        'requestedAt',v_now,'requestedByActorId',v_actor,
        'requestedByMembershipId',v_member.id));
    v_state:=pg_catalog.jsonb_set(v_state,'{reviews}',v_reviews);
    v_packages:=(select pg_catalog.jsonb_agg(case when p->>'packageId'=v_package
      then p||pg_catalog.jsonb_build_object('status','In review') else p end order by ordinal)
      from pg_catalog.jsonb_array_elements(v_packages)
        with ordinality as entries(p,ordinal));
    v_state:=pg_catalog.jsonb_set(v_state,'{packages}',v_packages);
  else
    v_id:=p_input->>'reviewId';
    v_decision:=p_input->>'decision';
    select r into v_target from pg_catalog.jsonb_array_elements(v_reviews) r
      where r->>'id'=v_id;
    v_package:=v_target->>'packageId';
    v_revision:=(v_target->>'revision')::integer;
    if v_member.role<>'operations_leader' or v_target is null
      or v_target->>'status'<>'Requested'
      or v_target->>'requestedByActorId'=v_actor::text
      or v_decision not in ('Approved','Returned')
      or length(v_note)<15
      or not exists(select 1 from pg_catalog.jsonb_array_elements(v_packages) p
        where p->>'packageId'=v_package
          and (p->>'revision')::integer=v_revision) then
      raise exception 'independent_package_review_required' using errcode='42501'; end if;
    v_target:=v_target||pg_catalog.jsonb_build_object('status',v_decision,
      'decidedAt',v_now,'decidedByActorId',v_actor,
      'decidedByMembershipId',v_member.id,'note',v_note);
    v_reviews:=(select pg_catalog.jsonb_agg(case when r->>'id'=v_id
      then v_target else r end order by ordinal)
      from pg_catalog.jsonb_array_elements(v_reviews)
        with ordinality as entries(r,ordinal));
    v_state:=pg_catalog.jsonb_set(v_state,'{reviews}',v_reviews);
    if v_decision='Returned' then
      v_packages:=(select pg_catalog.jsonb_agg(case when p->>'packageId'=v_package
        then p||pg_catalog.jsonb_build_object('status','Returned') else p end order by ordinal)
        from pg_catalog.jsonb_array_elements(v_packages)
          with ordinality as entries(p,ordinal));
      v_state:=pg_catalog.jsonb_set(v_state,'{packages}',v_packages);
    end if;
  end if;
  v_state:=v_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_design.decision_revision+1,
    'history',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'at',v_now,'actorId',v_actor,'membershipId',v_member.id,
      'action',p_action||' · '||p_command_id,'note',v_note,
      'packageId',v_package,'revision',v_revision))||
      coalesce(v_state->'history','[]'::jsonb));
  update d5o_hosted.connected_design_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_design_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    source_handoff_revision,snapshot,reason)
  values(v_workspace.id,v_work.id,v_design.decision_revision+1,p_command_id,
    p_action,v_actor,v_member.id,v_handoff.revision,v_state,v_note);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_design_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_spend_actions_pre_delegation_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text; item record; src jsonb;
 authority d5o_hosted.design_spend_authorities%rowtype;
 pending_authority d5o_hosted.design_spend_authorities%rowtype;
 pending_commit d5o_hosted.design_spend_commitments%rowtype;
 used bigint; remaining bigint; result jsonb:='[]'::jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name not in ('admin','project_manager','operations_leader') then return result; end if;
 for item in select w.id,w.title,w.created_by,l.presentation_id,coalesce(p.revision,0) revision
  from d5o_hosted.connected_rom_design_states r
  join d5o_hosted.work_records w on w.id=r.work_id and w.workspace_id=r.workspace_id
  join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
  left join d5o_hosted.design_spend_positions p on p.work_id=w.id and p.workspace_id=w.workspace_id
  where r.workspace_id=ws and r.status='Design authorized' loop
  src:=d5o_hosted.design_spend_source_v1(ws,item.id);
  if src is null then continue; end if;
  select * into authority from d5o_hosted.design_spend_authorities
   where workspace_id=ws and work_id=item.id and status='Approved' and source_digest=src->>'digest'
   order by created_at desc limit 1;
  select * into pending_authority from d5o_hosted.design_spend_authorities
   where workspace_id=ws and work_id=item.id and status='Prepared' and source_digest=src->>'digest'
   order by created_at desc limit 1;
  if pending_authority.id is not null and role_name=src->>'approverRole' and pending_authority.prepared_by<>actor then
   result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Review Design spending window',
    'phase','Develop','focus','design-spend-authority-review','workId',item.presentation_id,'workTitle',item.title,
    'revision',item.revision,'decisionId',pending_authority.id,'dueDate',pending_authority.valid_until,
    'status','Prepared','ownership','Eligible independent Design spending authority',
    'blocker','Confirm activity, funding source, expiry and cap against the approved Design permission.'));
  elsif authority.id is null and pending_authority.id is null and role_name='project_manager' and item.created_by=actor then
   result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Prepare Design spending window',
    'phase','Develop','focus','design-spend-authority-prep','workId',item.presentation_id,'workTitle',item.title,
    'revision',item.revision,'status','Preparation','ownership','Assigned project manager',
    'blocker','Propose the permitted activity and expiry within the independently approved Design cap.'));
  end if;
  if authority.id is not null and current_date between authority.valid_from and authority.valid_until then
   select coalesce(sum(amount_minor),0) into used from d5o_hosted.design_spend_commitments
    where workspace_id=ws and work_id=item.id and status='Approved';
   remaining:=least(authority.cap_minor,(src#>>'{authorization,spendCapMinor}')::bigint)-used;
   select * into pending_commit from d5o_hosted.design_spend_commitments
    where workspace_id=ws and work_id=item.id and authority_id=authority.id and status='Prepared'
    order by created_at desc limit 1;
   if pending_commit.id is not null and role_name=src->>'approverRole' and pending_commit.prepared_by<>actor then
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Review Design effort commitment',
     'phase','Develop','focus','design-spend-commitment-review','workId',item.presentation_id,'workTitle',item.title,
     'revision',item.revision,'decisionId',pending_commit.id,'dueDate',authority.valid_until,
     'status','Prepared','ownership','Eligible independent Design spending authority',
     'blocker',case when pending_commit.amount_minor>remaining then 'Prepared amount exceeds the remaining authorized cap; return for correction.' else null end));
   elsif pending_commit.id is null and remaining>0 and role_name='project_manager' and item.created_by=actor then
    result:=result||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('kind','Prepare Design effort commitment',
     'phase','Develop','focus','design-spend-commitment-prep','workId',item.presentation_id,'workTitle',item.title,
     'revision',item.revision,'decisionId',authority.id,'dueDate',authority.valid_until,
     'status','Preparation','ownership','Assigned project manager',
     'blocker','A draft does not commit spend; independent approval consumes the cap.'));
   end if;
  end if;
 end loop;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_spend_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare raw jsonb; entry jsonb; output jsonb:='[]'::jsonb; route jsonb; category text;
begin
 raw:=public.d5o_hosted_design_spend_actions_pre_delegation_v1(p_workspace_key);
 for entry in select value from pg_catalog.jsonb_array_elements(raw) loop
  category:=case entry->>'focus' when 'design-spend-authority-review' then 'design_authority'
   when 'design-spend-commitment-review' then 'design_commitment' else null end;
  if category is not null then
   route:=public.d5o_spending_delegate_my_review_v1(p_workspace_key,entry->>'workId',
    category,(entry->>'decisionId')::uuid);
   if not coalesce((route->>'canReview')::boolean,false) then continue; end if;
  end if;
  output:=output||pg_catalog.jsonb_build_array(entry);
 end loop;
 return output;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_spend_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws d5o_hosted.workspaces%rowtype; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; pos d5o_hosted.design_spend_positions%rowtype;
 authz d5o_hosted.design_spend_authorities%rowtype; commitment d5o_hosted.design_spend_commitments%rowtype;
 prior_authz d5o_hosted.design_spend_authorities%rowtype; prior_commit d5o_hosted.design_spend_commitments%rowtype;
 receipt d5o_hosted.design_spend_receipts%rowtype; src jsonb; fingerprint text; subject uuid;
 amount bigint; cap bigint; used bigint; result jsonb; next_revision integer; approver text;
begin
 if current_setting('role',true)<>'authenticated' or actor is null or p_action not in
  ('prepare-authority','approve-authority','return-authority','revoke-authority',
   'prepare-commitment','approve-commitment','return-commitment')
  or pg_catalog.jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then
  raise exception 'invalid_design_spend_command' using errcode='22023'; end if;
 select * into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select * into member from d5o_hosted.memberships where workspace_id=ws.id and actor_user_id=actor and status='active' for share;
 if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select w.* into work from d5o_hosted.work_records w join d5o_hosted.work_identity_links l
  on l.workspace_id=w.workspace_id and l.work_id=w.id
  where w.workspace_id=ws.id and l.presentation_id=p_presentation_id for update of w;
 if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
 fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,
  p_expected_revision,p_expected_source_digest)::text);
 select * into receipt from d5o_hosted.design_spend_receipts where workspace_id=ws.id and command_id=p_command_id;
 if found then
  if receipt.work_id<>work.id or receipt.actor_user_id<>actor or receipt.fingerprint<>fingerprint then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return receipt.result; end if;
 insert into d5o_hosted.design_spend_positions(workspace_id,work_id,revision)
  values(ws.id,work.id,0) on conflict do nothing;
 select * into pos from d5o_hosted.design_spend_positions where workspace_id=ws.id and work_id=work.id for update;
 if pos.revision<>p_expected_revision then raise exception 'stale_design_spend_revision' using errcode='23505'; end if;
 src:=d5o_hosted.design_spend_source_v1(ws.id,work.id);
 if p_action<>'revoke-authority' and (src is null or src->>'digest' is distinct from p_expected_source_digest) then
  raise exception 'design_spend_source_changed' using errcode='23514'; end if;
 approver:=src->>'approverRole';
 if p_action='revoke-authority' then
  select * into authz from d5o_hosted.design_spend_authorities
   where id=(p_input->>'authorityId')::uuid and workspace_id=ws.id and work_id=work.id;
  approver:=authz.source_snapshot->>'approverRole';
 end if;
 if p_action in ('prepare-authority','prepare-commitment') then
  if member.role<>'project_manager' or work.created_by<>actor then
   raise exception 'design_spend_preparer_required' using errcode='42501'; end if;
 else
  if member.role<>approver or approver not in ('admin','operations_leader') then
   raise exception 'independent_design_spend_authority_required' using errcode='42501'; end if;
 end if;
 if p_action='prepare-authority' then
  if coalesce(p_input->>'capMinor','') !~ '^[1-9][0-9]*$'
   or coalesce(p_input->>'validFrom','') !~ '^\d{4}-\d{2}-\d{2}$'
   or coalesce(p_input->>'validUntil','') !~ '^\d{4}-\d{2}-\d{2}$'
   or length(trim(coalesce(p_input->>'extent',''))) not between 10 and 2000
   or length(trim(coalesce(p_input->>'sourceReference',''))) not between 5 and 500 then
   raise exception 'invalid_design_spend_authority_basis' using errcode='22023'; end if;
  cap:=(p_input->>'capMinor')::bigint;
  if cap>(src#>>'{authorization,spendCapMinor}')::bigint
   or (p_input->>'validFrom')::date>(p_input->>'validUntil')::date
   or (p_input->>'validUntil')::date<current_date
   or src#>>'{authorization,currency}' !~ '^[A-Z]{3}$' then
   raise exception 'design_spend_cap_or_dates_invalid' using errcode='23514'; end if;
  if exists(select 1 from d5o_hosted.design_spend_authorities
    where workspace_id=ws.id and work_id=work.id and status='Approved' and source_digest=src->>'digest' and valid_until>=current_date) then
   raise exception 'active_design_spend_authority_exists' using errcode='23514'; end if;
  if p_input ? 'supersedesId' then
   select * into prior_authz from d5o_hosted.design_spend_authorities
    where id=(p_input->>'supersedesId')::uuid and workspace_id=ws.id and work_id=work.id;
   if prior_authz.id is null or not (prior_authz.status in ('Returned','Revoked') or (prior_authz.status='Approved' and prior_authz.valid_until<current_date)) then
    raise exception 'returned_revoked_or_expired_authority_required' using errcode='23514'; end if;
  end if;
  insert into d5o_hosted.design_spend_authorities(workspace_id,work_id,status,cap_minor,currency,extent,
   valid_from,valid_until,funding_source,source_reference,source_digest,source_snapshot,prepared_by,supersedes_id)
   values(ws.id,work.id,'Prepared',cap,src#>>'{authorization,currency}',trim(p_input->>'extent'),
    (p_input->>'validFrom')::date,(p_input->>'validUntil')::date,
    src#>>'{authorization,fundingSource}',trim(p_input->>'sourceReference'),src->>'digest',src,actor,prior_authz.id)
   returning * into authz;
  subject:=authz.id;
 elsif p_action in ('approve-authority','return-authority','revoke-authority') then
  select * into authz from d5o_hosted.design_spend_authorities
   where id=(p_input->>'authorityId')::uuid and workspace_id=ws.id and work_id=work.id for update;
  if authz.id is null then raise exception 'design_spend_authority_not_found' using errcode='23514'; end if;
  if p_action='revoke-authority' then
   if authz.status<>'Approved' or length(trim(coalesce(p_input->>'reason',''))) < 10 then
    raise exception 'approved_authority_and_reason_required' using errcode='23514'; end if;
   update d5o_hosted.design_spend_authorities set status='Revoked',reviewed_by=actor,
    review_note=trim(p_input->>'reason'),decided_at=now() where id=authz.id;
  else
   if authz.status<>'Prepared' or authz.prepared_by=actor
    or length(trim(coalesce(p_input->>'reason',''))) < 10 then
    raise exception 'independent_authority_review_required' using errcode='42501'; end if;
   if p_action='approve-authority' then
    if authz.source_digest<>src->>'digest' or authz.valid_until<current_date
     or exists(select 1 from d5o_hosted.design_spend_authorities
      where workspace_id=ws.id and work_id=work.id and status='Approved' and source_digest=src->>'digest' and valid_until>=current_date) then
     raise exception 'design_spend_authority_stale_or_duplicate' using errcode='23514'; end if;
   end if;
   update d5o_hosted.design_spend_authorities set
    status=case when p_action='approve-authority' then 'Approved' else 'Returned' end,
    reviewed_by=actor,review_note=trim(p_input->>'reason'),decided_at=now() where id=authz.id;
  end if;
  subject:=authz.id;
 elsif p_action='prepare-commitment' then
  select * into authz from d5o_hosted.design_spend_authorities
   where id=(p_input->>'authorityId')::uuid and workspace_id=ws.id and work_id=work.id for update;
  if authz.id is null or authz.status<>'Approved' or authz.source_digest<>src->>'digest'
   or current_date not between authz.valid_from and authz.valid_until then
   raise exception 'current_design_spend_authority_required' using errcode='23514'; end if;
  if coalesce(p_input->>'amountMinor','') !~ '^[1-9][0-9]*$'
   or length(trim(coalesce(p_input->>'activity',''))) not between 10 and 1000
   or length(trim(coalesce(p_input->>'sourceReference',''))) not between 5 and 500 then
   raise exception 'invalid_design_spend_commitment_basis' using errcode='22023'; end if;
  if p_input ? 'supersedesId' then
   select * into prior_commit from d5o_hosted.design_spend_commitments
    where id=(p_input->>'supersedesId')::uuid and workspace_id=ws.id and work_id=work.id and authority_id=authz.id;
   if prior_commit.id is null or prior_commit.status<>'Returned' then
    raise exception 'returned_commitment_required' using errcode='23514'; end if;
  end if;
  insert into d5o_hosted.design_spend_commitments(workspace_id,work_id,authority_id,status,amount_minor,
   currency,activity,source_reference,prepared_by,supersedes_id)
   values(ws.id,work.id,authz.id,'Prepared',(p_input->>'amountMinor')::bigint,authz.currency,
    trim(p_input->>'activity'),trim(p_input->>'sourceReference'),actor,prior_commit.id)
   returning * into commitment;
  subject:=commitment.id;
 else
  select * into commitment from d5o_hosted.design_spend_commitments
   where id=(p_input->>'commitmentId')::uuid and workspace_id=ws.id and work_id=work.id for update;
  if commitment.id is null or commitment.status<>'Prepared' or commitment.prepared_by=actor
   or length(trim(coalesce(p_input->>'reason',''))) < 10 then
   raise exception 'independent_commitment_review_required' using errcode='42501'; end if;
  select * into authz from d5o_hosted.design_spend_authorities where id=commitment.authority_id for update;
  if p_action='approve-commitment' then
   if authz.status<>'Approved' or authz.source_digest<>src->>'digest'
    or current_date not between authz.valid_from and authz.valid_until then
    raise exception 'current_design_spend_authority_required' using errcode='23514'; end if;
   select coalesce(sum(amount_minor),0) into used from d5o_hosted.design_spend_commitments
    where workspace_id=ws.id and work_id=work.id and status='Approved';
   if commitment.amount_minor>authz.cap_minor-used
    or commitment.amount_minor>(src#>>'{authorization,spendCapMinor}')::bigint-used then
    raise exception 'design_spend_cap_exceeded' using errcode='23514'; end if;
  end if;
  update d5o_hosted.design_spend_commitments set
   status=case when p_action='approve-commitment' then 'Approved' else 'Returned' end,
   reviewed_by=actor,review_note=trim(p_input->>'reason'),decided_at=now() where id=commitment.id;
  subject:=commitment.id;
 end if;
 next_revision:=pos.revision+1;
 update d5o_hosted.design_spend_positions set revision=next_revision,updated_at=now()
  where workspace_id=ws.id and work_id=work.id;
 insert into d5o_hosted.design_spend_events(workspace_id,work_id,revision,action,command_id,
  actor_user_id,membership_id,subject_id,basis)
  values(ws.id,work.id,next_revision,p_action,p_command_id,actor,member.id,subject,
   pg_catalog.jsonb_build_object('input',p_input,'source',src));
 result:=pg_catalog.jsonb_build_object('revision',next_revision,'subjectId',subject,'action',p_action,
  'status',case when p_action like 'prepare-%' then 'Prepared'
   when p_action like 'approve-%' then 'Approved'
   when p_action='revoke-authority' then 'Revoked' else 'Returned' end);
 insert into d5o_hosted.design_spend_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(ws.id,p_command_id,work.id,actor,fingerprint,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_design_spend_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a uuid:=auth.uid(); ws uuid; w uuid; rev integer; src jsonb; cap bigint; window_cap bigint; used bigint;
begin
 if current_setting('role',true)<>'authenticated' or a is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 if not exists(select 1 from d5o_hosted.memberships where workspace_id=ws and actor_user_id=a and status='active'
  and role in ('admin','project_manager','operations_leader','billing_commercial_lead')) then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select work_id into w from d5o_hosted.work_identity_links where workspace_id=ws and presentation_id=p_presentation_id;
 if w is null then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
 select revision into rev from d5o_hosted.design_spend_positions where workspace_id=ws and work_id=w;
 src:=d5o_hosted.design_spend_source_v1(ws,w);
 select coalesce(sum(amount_minor),0) into used from d5o_hosted.design_spend_commitments
  where workspace_id=ws and work_id=w and status='Approved';
 cap:=case when src is not null then (src#>>'{authorization,spendCapMinor}')::bigint else null end;
 select cap_minor into window_cap from d5o_hosted.design_spend_authorities
  where workspace_id=ws and work_id=w and status='Approved' and source_digest=src->>'digest'
    and current_date between valid_from and valid_until order by created_at desc limit 1;
 return pg_catalog.jsonb_build_object('revision',coalesce(rev,0),'source',src,'committedMinor',used,
  'remainingMinor',case when cap is null then null else least(cap,coalesce(window_cap,cap))-used end,
  'designCapMinor',cap,'windowCapMinor',window_cap,
  'authorities',coalesce((select pg_catalog.jsonb_agg(to_jsonb(x) order by x.created_at) from d5o_hosted.design_spend_authorities x
    where x.workspace_id=ws and x.work_id=w),'[]'::jsonb),
  'commitments',coalesce((select pg_catalog.jsonb_agg(to_jsonb(x) order by x.created_at) from d5o_hosted.design_spend_commitments x
    where x.workspace_id=ws and x.work_id=w),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_estimate_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_due_date text, p_reason text, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer, p_estimate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype;
  v_solution d5o_hosted.connected_solution_states%rowtype;
  v_define d5o_hosted.connected_define_states%rowtype;
  v_control d5o_hosted.connected_estimate_states%rowtype;
  v_receipt d5o_hosted.connected_estimate_receipts%rowtype;
  v_raw jsonb;v_policy jsonb;v_rate jsonb;v_line jsonb;v_lines jsonb:='[]'::jsonb;
  v_snapshot jsonb;v_evaluation jsonb;v_review jsonb;v_issues jsonb:='[]'::jsonb;
  v_fingerprint text;v_result jsonb;v_now timestamptz:=now();v_next text;
  v_digits integer;v_factor numeric;v_qty numeric;v_unit_cost numeric;
  v_burden numeric;v_line_minor numeric;v_direct numeric:=0;
  v_overhead numeric;v_contingency numeric;v_included numeric;
  v_price numeric;v_discount numeric;v_profit numeric;v_margin numeric;
  v_annual numeric:=0;v_recurring numeric:=0;v_floor numeric;
  v_target numeric;v_discount_pct numeric;v_method text;
  v_rate_rank integer;v_rate_count integer;v_scope_rank integer;
  v_policy_id text;v_policy_version integer;v_category text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-detailed-estimate','submit-pricing',
      'approve-pricing','return-pricing')
    or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<0
    or p_estimate_revision is null or p_estimate_revision<1
    or length(coalesce(p_reason,''))>2000 then
    raise exception 'invalid_estimate_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active'
    for share;
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_input,p_due_date,trim(coalesce(p_reason,'')),
    p_expected_source_revision,p_expected_decision_revision,p_estimate_revision)::text);
  select * into v_receipt from d5o_hosted.connected_estimate_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_control from d5o_hosted.connected_estimate_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or coalesce(v_control.decision_revision,0)<>p_expected_decision_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_raw from pg_catalog.jsonb_array_elements(v_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_raw is null or v_raw->>'phaseConfigurationVersionId' is distinct from
    v_work.configuration_version_id::text then
    raise exception 'source_identity_changed' using errcode='42501'; end if;
  select * into v_define from d5o_hosted.connected_define_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_solution from d5o_hosted.connected_solution_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  if v_define.status is distinct from 'Approved'
    or v_define.projection#>>'{developHandoff,status}'<>'accepted'
    or v_solution.status is distinct from 'Approved'
    or v_solution.source_digest is distinct from
      d5o_hosted.connected_solution_digest_v1(v_raw->'develop') then
    raise exception 'approved_solution_basis_required' using errcode='23514'; end if;
  select p.payload into v_policy from d5o_hosted.connected_pricing_active a
    join d5o_hosted.connected_pricing_policies p on p.workspace_id=a.workspace_id
      and p.policy_id=a.policy_id and p.version=a.version
    where a.workspace_id=v_workspace.id and p.status='published'
      and (p.payload->>'effectiveFrom')::date<=v_now::date
      and (p.payload->>'effectiveTo' is null or
        (p.payload->>'effectiveTo')::date>=v_now::date);
  if v_policy is null then raise exception 'pricing_policy_unavailable' using errcode='23514'; end if;
  v_policy_id:=v_policy->>'id';v_policy_version:=(v_policy->>'version')::integer;
  if v_solution.review->>'policyId' is distinct from v_policy_id
    or (v_solution.review->>'policyVersion')::integer is distinct from v_policy_version then
    raise exception 'solution_policy_changed' using errcode='23514'; end if;
  if p_action='save-detailed-estimate' then
    if v_member.role not in ('admin','project_manager','operations_leader')
      or p_input is null or pg_catalog.jsonb_typeof(p_input)<>'object'
      or p_estimate_revision<>coalesce(v_control.estimate_revision,0)+1
      or v_control.status='Pricing review'
      or pg_catalog.jsonb_typeof(p_input->'lines')<>'array'
      or pg_catalog.jsonb_array_length(p_input->'lines') not between 1 and 100
      or p_input->>'currency' is distinct from v_policy->>'currency'
      or p_input->>'workType' is distinct from v_raw->>'type'
      or p_input->>'customer' is distinct from v_raw->>'customer'
      or p_input->>'definitionRevision' is distinct from
        v_define.definition_revision::text
      or p_input->>'solutionRevision' is distinct from
        v_solution.solution_revision::text
      or coalesce(p_input->>'pricedAt','') !~ '^\d{4}-\d{2}-\d{2}$'
      or p_input->>'pricedAt' < v_policy->>'effectiveFrom'
      or (v_policy->>'effectiveTo' is not null and
        p_input->>'pricedAt'>v_policy->>'effectiveTo')
      or coalesce(p_input->>'riskBasis','')=''
      or coalesce(p_input->>'estimateMaturity','') not in ('ROM','Budgetary','Firm') then
      raise exception 'invalid_estimate_basis' using errcode='23514'; end if;
    v_digits:=case when p_input->>'currency'='JPY' then 0 else 2 end;
    v_factor:=power(10,v_digits);
    v_method:=coalesce(p_input->>'method',v_policy->>'method');
    if v_method is distinct from v_policy->>'method'
      or v_method not in ('target-margin','markup','fixed-price')
      or coalesce(p_input->>'discountPercent','') !~ '^[0-9]+(\.[0-9]+)?$'
      or (p_input->>'discountPercent')::numeric>
        (v_policy->>'maxDiscountPercent')::numeric then
      raise exception 'invalid_estimate_pricing_method' using errcode='23514'; end if;
    v_discount_pct:=(p_input->>'discountPercent')::numeric;
    for v_line in select value from pg_catalog.jsonb_array_elements(p_input->'lines') loop
      v_category:=v_line->>'category';
      if coalesce(v_category,'') not in ('labor','material','equipment','subcontract',
        'travel','mobilization','setup','recurring','other')
        or length(trim(coalesce(v_line->>'id','')))=0
        or length(trim(coalesce(v_line->>'scopeRef','')))=0
        or length(trim(coalesce(v_line->>'description','')))=0
        or length(trim(coalesce(v_line->>'source','')))=0
        or length(trim(coalesce(v_line->>'assumption','')))=0
        or length(trim(coalesce(v_line->>'unit','')))=0
        or coalesce(v_line->>'quantity','') !~ '^[0-9]+(\.[0-9]{1,3})?$'
        or (v_line->>'quantity')::numeric<=0
        or v_line ? 'procurement' then
        raise exception 'invalid_or_unassessed_estimate_line' using errcode='23514'; end if;
      v_qty:=(v_line->>'quantity')::numeric;
      v_rate:=null;v_rate_count:=0;
      if length(coalesce(v_line->>'rateId',''))>0 then
        select value into v_rate from pg_catalog.jsonb_array_elements(v_policy->'rates') value
          where value->>'id'=v_line->>'rateId'
            and value->>'category'=v_category and value->>'unit'=v_line->>'unit'
            and value->>'effectiveFrom'<=p_input->>'pricedAt'
            and (value->>'effectiveTo' is null or value->>'effectiveTo'>=p_input->>'pricedAt')
            and (value#>>'{scope,kind}'='default' or
              value#>>'{scope,value}'=case value#>>'{scope,kind}'
                when 'customer' then p_input->>'customer'
                when 'workType' then p_input->>'workType'
                when 'region' then p_input->>'region' end)
          order by case value#>>'{scope,kind}' when 'customer' then 0
            when 'workType' then 1 when 'region' then 2 else 3 end
          limit 1;
        if v_rate is null then raise exception 'estimate_rate_missing' using errcode='23514'; end if;
        v_scope_rank:=case v_rate#>>'{scope,kind}' when 'customer' then 0
          when 'workType' then 1 when 'region' then 2 else 3 end;
        select count(*) into v_rate_count from pg_catalog.jsonb_array_elements(v_policy->'rates') value
          where value->>'id'=v_line->>'rateId' and value->>'category'=v_category
            and value->>'unit'=v_line->>'unit'
            and value->>'effectiveFrom'<=p_input->>'pricedAt'
            and (value->>'effectiveTo' is null or value->>'effectiveTo'>=p_input->>'pricedAt')
            and case value#>>'{scope,kind}' when 'customer' then 0
              when 'workType' then 1 when 'region' then 2 else 3 end=v_scope_rank
            and (value#>>'{scope,kind}'='default' or
              value#>>'{scope,value}'=case value#>>'{scope,kind}'
                when 'customer' then p_input->>'customer'
                when 'workType' then p_input->>'workType'
                when 'region' then p_input->>'region' end);
        if v_rate_count<>1 then raise exception 'estimate_rate_ambiguous' using errcode='23514'; end if;
        v_unit_cost:=(v_rate->>'amount')::numeric;
      else
        if coalesce(v_line->>'manualRate','') !~ (case when v_digits=0 then
          '^[0-9]+$' else '^[0-9]+(\.[0-9]{1,2})?$' end) then
          raise exception 'estimate_cost_missing' using errcode='23514'; end if;
        v_unit_cost:=(v_line->>'manualRate')::numeric;
      end if;
      if v_line->>'validUntil' is not null and
        (v_line->>'validUntil'<p_input->>'pricedAt' or
          (p_input->>'expectedAwardDate' is not null and
            v_line->>'validUntil'<p_input->>'expectedAwardDate')) then
        raise exception 'estimate_quote_expired' using errcode='23514'; end if;
      v_burden:=case when v_category='labor' then
        coalesce((v_rate->>'burdenPercent')::numeric,0) else 0 end;
      if v_burden<0 or v_burden>=100 then
        raise exception 'invalid_labor_burden' using errcode='23514'; end if;
      v_line_minor:=round(v_qty*v_unit_cost*v_factor*(1+v_burden/100));
      if v_category='recurring' then
        if coalesce(v_line->>'recurringMonths','') !~ '^[0-9]+$'
          or (v_line->>'recurringMonths')::integer not between 1 and 600 then
          raise exception 'invalid_recurring_period' using errcode='23514'; end if;
        v_annual:=v_annual+v_line_minor*least((v_line->>'recurringMonths')::integer,12);
        v_line_minor:=v_line_minor*(v_line->>'recurringMonths')::integer;
        v_recurring:=v_recurring+v_line_minor;
      end if;
      v_direct:=v_direct+v_line_minor;
      v_lines:=v_lines||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'id',v_line->>'id','category',v_category,'amountMinor',v_line_minor,
        'rateId',v_rate->>'id','rateSource',coalesce(v_rate->>'source',v_line->>'source')));
    end loop;
    if v_direct>9000000000000 then
      raise exception 'estimate_overflow' using errcode='22003'; end if;
    v_overhead:=round(v_direct*(v_policy->>'overheadPercent')::numeric/100);
    v_contingency:=round(v_direct*(v_policy->>'contingencyPercent')::numeric/100);
    v_included:=v_direct+v_overhead+v_contingency;
    v_target:=(v_policy->>'targetMarginPercent')::numeric;
    v_floor:=(v_policy->>'floorMarginPercent')::numeric;
    v_price:=case v_method
      when 'target-margin' then ceil(v_included*100/(100-v_target))
      when 'markup' then round(v_included*(100+(v_policy->>'markupPercent')::numeric)/100)
      else (coalesce(p_input->>'fixedPrice',v_policy->>'fixedPrice'))::numeric*v_factor end;
    if v_price is null or v_price<=0 then
      raise exception 'estimate_price_missing' using errcode='23514'; end if;
    v_discount:=round(v_price*v_discount_pct/100);
    v_price:=v_price-v_discount;
    v_profit:=v_price-v_included;v_margin:=round(v_profit*100/v_price,6);
    if v_margin<v_floor then
      v_issues:=pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'code','below_floor','message','Price falls below the policy margin floor',
        'action','Revise price or seek the configured exception'));
    end if;
    v_evaluation:=pg_catalog.jsonb_build_object(
      'policyId',v_policy_id,'policyVersion',v_policy_version,
      'currency',p_input->>'currency','input',p_input,'lines',v_lines,
      'directCostMinor',v_direct,'overheadMinor',v_overhead,
      'contingencyMinor',v_contingency,'includedCostMinor',v_included,
      'proposedPriceMinor',v_price,'discountMinor',v_discount,
      'grossProfitMinor',v_profit,'marginPercent',v_margin,
      'annualRecurringMinor',v_annual,'totalRecurringMinor',v_recurring,
      'minimumFloorPriceMinor',ceil(v_included*100/(100-v_floor)),
      'minimumTargetPriceMinor',ceil(v_included*100/(100-v_target)),
      'absorbableCostMinor',v_price-ceil(v_price*v_floor/100)-v_included,
      'issues',v_issues,'recommendation',case when v_margin<v_floor then
        'Escalate for margin decision' else 'Ready for pricing review' end,
      'calculatedAt',v_now);
    v_snapshot:=pg_catalog.jsonb_build_object('revision',p_estimate_revision,
      'status','Draft','labor',coalesce((select sum((x->>'amountMinor')::numeric)
        from pg_catalog.jsonb_array_elements(v_lines) x where x->>'category'='labor'),0)/v_factor,
      'materials',coalesce((select sum((x->>'amountMinor')::numeric)
        from pg_catalog.jsonb_array_elements(v_lines) x where x->>'category' in
          ('material','equipment')),0)/v_factor,
      'subcontract',coalesce((select sum((x->>'amountMinor')::numeric)
        from pg_catalog.jsonb_array_elements(v_lines) x where x->>'category'='subcontract'),0)/v_factor,
      'travel',coalesce((select sum((x->>'amountMinor')::numeric)
        from pg_catalog.jsonb_array_elements(v_lines) x where x->>'category' in
          ('travel','mobilization','setup','recurring','other')),0)/v_factor,
      'contingency',(v_overhead+v_contingency)/v_factor,
      'targetMargin',v_target,'sellPrice',v_price/v_factor,
      'assumption',p_input->>'riskBasis',
      'definitionSource',pg_catalog.jsonb_build_object(
        'revision',v_define.definition_revision,
        'configurationVersionId',v_work.configuration_version_id,
        'workTypeKey',v_define.projection->>'configurationWorkTypeKey',
        'capturedAt',v_now),
      'detailed',pg_catalog.jsonb_build_object('input',p_input,
        'evaluation',v_evaluation,'policySnapshot',v_policy,'savedAt',v_now),
      'revisionHistory',case when v_control.work_id is null then '[]'::jsonb
        else coalesce(v_control.estimate->'revisionHistory','[]'::jsonb)||
          pg_catalog.jsonb_build_array(v_control.estimate) end,
      'authorityRevision',coalesce(v_control.decision_revision,0)+1);
    v_next:=case when v_margin<v_floor then 'Resolve estimate margin floor'
      else 'Submit detailed estimate for pricing review' end;
    if v_control.work_id is null then
      insert into d5o_hosted.connected_estimate_states(workspace_id,work_id,
        estimate_revision,decision_revision,solution_digest,definition_revision,
        status,estimate,next_action)
      values(v_workspace.id,v_work.id,p_estimate_revision,1,
        v_solution.source_digest,v_define.definition_revision,'Draft',
        v_snapshot,v_next);
    else
      update d5o_hosted.connected_estimate_states set
        estimate_revision=p_estimate_revision,decision_revision=decision_revision+1,
        solution_digest=v_solution.source_digest,
        definition_revision=v_define.definition_revision,status='Draft',
        estimate=v_snapshot,submitter=null,reviewer=null,next_action=v_next,
        updated_at=v_now where workspace_id=v_workspace.id and work_id=v_work.id;
    end if;
  else
    if p_input is not null or v_control.work_id is null
      or v_control.estimate_revision<>p_estimate_revision
      or v_control.solution_digest<>v_solution.source_digest
      or v_control.definition_revision<>v_define.definition_revision
      or v_control.estimate#>>'{detailed,evaluation,policyId}'<>v_policy_id
      or (v_control.estimate#>>'{detailed,evaluation,policyVersion}')::integer<>
        v_policy_version then
      raise exception 'estimate_basis_changed' using errcode='23514'; end if;
    if p_action='submit-pricing' then
      if v_member.role not in ('admin','project_manager','operations_leader')
        or v_control.status<>'Draft' or p_due_date is null
        or p_due_date !~ '^\d{4}-\d{2}-\d{2}$'
        or pg_catalog.jsonb_array_length(
          v_control.estimate#>'{detailed,evaluation,issues}')>0 then
        raise exception 'estimate_submit_denied' using errcode='42501'; end if;
      v_review:=pg_catalog.jsonb_build_object('revision',p_estimate_revision,
        'submittedAt',v_now,'submittedBy',v_raw->>'owner',
        'submittedByActorId',v_actor,
        'submittedByMembershipId',v_member.id,'dueDate',p_due_date,
        'authorityRole',v_policy->>'pricingApproverRole',
        'policyId',v_policy_id,'policyVersion',v_policy_version);
      v_snapshot:=v_control.estimate||pg_catalog.jsonb_build_object(
        'status','Pricing review','review',v_review,
        'authorityRevision',v_control.decision_revision+1);
      v_next:='Review estimate revision '||p_estimate_revision::text;
      update d5o_hosted.connected_estimate_states set
        decision_revision=decision_revision+1,status='Pricing review',
        estimate=v_snapshot,submitter=v_actor,reviewer=null,next_action=v_next,
        updated_at=v_now where workspace_id=v_workspace.id and work_id=v_work.id;
    else
      if v_control.status<>'Pricing review' or v_actor=v_control.submitter
        or v_member.role<>v_control.estimate#>>'{review,authorityRole}'
        or length(trim(coalesce(p_reason,'')))<10 then
        raise exception 'independent_pricing_review_required' using errcode='42501'; end if;
      v_review:=v_control.estimate->'review'||pg_catalog.jsonb_build_object(
        'decidedAt',v_now,'decisionNote',trim(p_reason),
        'actorId',v_actor,'membershipId',v_member.id);
      v_snapshot:=v_control.estimate||pg_catalog.jsonb_build_object(
        'status',case when p_action='approve-pricing' then 'Approved'
          else 'Changes requested' end,'review',v_review,
        'authorityRevision',v_control.decision_revision+1);
      v_next:=case when p_action='approve-pricing' then
        'Prepare customer proposal' else 'Revise estimate and resubmit' end;
      update d5o_hosted.connected_estimate_states set
        decision_revision=decision_revision+1,
        status=case when p_action='approve-pricing' then 'Approved'
          else 'Changes requested' end,
        estimate=v_snapshot,reviewer=v_actor,next_action=v_next,updated_at=v_now
        where workspace_id=v_workspace.id and work_id=v_work.id;
    end if;
  end if;
  select * into v_control from d5o_hosted.connected_estimate_states
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_estimate_events(workspace_id,work_id,
    decision_revision,command_id,action,estimate_revision,actor_user_id,
    membership_id,solution_digest,configuration_version_id,policy_id,
    policy_version,snapshot,reason)
  values(v_workspace.id,v_work.id,v_control.decision_revision,p_command_id,p_action,
    p_estimate_revision,v_actor,v_member.id,v_solution.source_digest,
    v_work.configuration_version_id,v_policy_id,v_policy_version,
    v_control.estimate,trim(coalesce(p_reason,'')));
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_estimate_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_field_change_command_v1(p_workspace_key text, p_presentation_id text, p_package_id text, p_change_id uuid, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_design_revision integer, p_expected_deploy_revision integer, p_expected_change_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_member d5o_hosted.memberships%rowtype;
  v_work d5o_hosted.work_records%rowtype;v_raw d5o_hosted.prototype_states%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_change d5o_hosted.connected_field_changes%rowtype;
  v_receipt d5o_hosted.connected_field_change_receipts%rowtype;
  v_release jsonb;v_new_release jsonb;v_report jsonb;v_evidence jsonb;
  v_facts jsonb;v_status text;v_kind text;v_result jsonb;v_document jsonb;
  v_fingerprint text;v_now timestamptz:=now();v_due date;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('raise','assess','answer-query','propose','submit-review',
      'review','record-customer','resolve')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or length(coalesce(p_package_id,'')) not between 2 and 120
    or p_expected_source_revision is null or p_expected_design_revision is null
    or p_expected_deploy_revision is null or p_expected_change_revision is null then
    raise exception 'invalid_field_change_command' using errcode='22023'; end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace and actor_user_id=v_actor and status='active' for share;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace and l.presentation_id=p_presentation_id for update of w;
  if v_member.id is null or v_work.id is null then
    raise exception 'field_change_scope_denied' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_package_id,p_change_id,p_action,p_input,
    p_expected_source_revision,p_expected_design_revision,
    p_expected_deploy_revision,p_expected_change_revision)::text);
  select * into v_receipt from d5o_hosted.connected_field_change_receipts
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace and state_key='work' for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace and work_id=v_work.id for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_design_revision
    or coalesce(v_deploy.decision_revision,0)<>p_expected_deploy_revision then
    raise exception 'stale_field_change_basis' using errcode='23505'; end if;
  select r into v_release from pg_catalog.jsonb_array_elements(
    coalesce(v_design.state->'releases','[]'::jsonb)) r
    where r->>'packageId'=p_package_id order by r->>'issuedAt' desc limit 1;
  if v_release is null or v_release->>'status'<>'Accepted' then
    raise exception 'accepted_release_required' using errcode='23514'; end if;
  if p_action='raise' then
    if v_deploy.state ? 'workAcceptance' then
      raise exception 'accepted_work_requires_service_or_amendment' using errcode='23514'; end if;
    if p_change_id is not null or p_expected_change_revision<>0
      or length(trim(coalesce(p_input->>'title','')))<8
      or length(trim(coalesce(p_input->>'impact','')))<10 then
      raise exception 'field_issue_incomplete' using errcode='22023'; end if;
    if v_member.role='field_worker' then
      if not exists(select 1 from d5o_hosted.crew_bindings b
        join d5o_hosted.connected_schedule_states s on s.workspace_id=b.workspace_id
        where b.workspace_id=v_workspace and b.actor_user_id=v_actor and b.active
          and exists(select 1 from pg_catalog.jsonb_array_elements(
            coalesce(s.state->'publications','[]'::jsonb)) pub,
            lateral pg_catalog.jsonb_array_elements(pub->'assignments') a
            where a->>'workId'=p_presentation_id and a->>'packageId'=p_package_id
              and a->'people' ? b.person)) then
        raise exception 'assignment_required' using errcode='42501'; end if;
    elsif v_member.role not in ('field_supervisor','operations_leader','project_manager','admin') then
      raise exception 'field_issue_role_denied' using errcode='42501'; end if;
    if nullif(p_input->>'reportId','') is not null then
      select r into v_report from pg_catalog.jsonb_array_elements(
        coalesce(v_deploy.state->'reports','[]'::jsonb)) r
        where r->>'id'=p_input->>'reportId' and r->>'packageId'=p_package_id
          and r->>'releaseId'=v_release->>'id';
      if v_report is null then raise exception 'issue_report_scope_invalid' using errcode='23514'; end if;
    end if;
    for v_evidence in select value from pg_catalog.jsonb_array_elements(
      coalesce(p_input->'evidenceIds','[]'::jsonb)) loop
      if not exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_deploy.state->'evidence','[]'::jsonb)) e
        where e->>'id'=v_evidence#>>'{}' and e->>'packageId'=p_package_id
          and e->>'releaseId'=v_release->>'id') then
        raise exception 'issue_evidence_scope_invalid' using errcode='23514'; end if;
    end loop;
    insert into d5o_hosted.connected_field_changes(workspace_id,work_id,
      package_id,opened_release_id,opened_package_revision,report_id,evidence_ids,
      status,title,impact,owner_role,due_date,created_by)
    values(v_workspace,v_work.id,p_package_id,v_release->>'id',
      (v_release->>'packageRevision')::integer,nullif(p_input->>'reportId',''),
      coalesce(p_input->'evidenceIds','[]'::jsonb),'Open',trim(p_input->>'title'),
      trim(p_input->>'impact'),'operations_leader',
      nullif(p_input->>'dueDate','')::date,v_actor) returning * into v_change;
    -- The separate guard rejects new authorization while the issue is open.
    -- Existing factual reports remain available for truthful historical reporting.
  else
    select * into v_change from d5o_hosted.connected_field_changes
      where workspace_id=v_workspace and work_id=v_work.id and id=p_change_id
        and package_id=p_package_id for update;
    if v_change.id is null or v_change.revision<>p_expected_change_revision then
      raise exception 'stale_field_change' using errcode='23505'; end if;
    if v_change.status='Resolved' then raise exception 'change_already_resolved' using errcode='23514'; end if;
    v_facts:=v_change.facts;v_status:=v_change.status;v_kind:=v_change.kind;
    if p_action='assess' then
      if v_change.status<>'Open' or v_actor=v_change.created_by
        or v_member.role not in ('field_supervisor','operations_leader','project_manager')
        or p_input->>'kind' not in ('Correction','Clarification','Scope change')
        or length(trim(coalesce(p_input->>'reason','')))<15 then
        raise exception 'independent_issue_assessment_required' using errcode='42501'; end if;
      v_kind:=p_input->>'kind';v_status:=case when v_kind='Clarification' then 'Query' else 'Open' end;
      v_facts:=v_facts||pg_catalog.jsonb_build_object('assessment',p_input->>'reason',
        'assessedBy',v_actor,'assessedAt',v_now);
    elsif p_action='answer-query' then
      if v_change.status<>'Query' or v_member.role not in ('admin','project_manager')
        or length(trim(coalesce(p_input->>'response','')))<15 then
        raise exception 'technical_response_required' using errcode='42501'; end if;
      v_status:='Open';v_facts:=v_facts||pg_catalog.jsonb_build_object(
        'queryResponse',p_input->>'response','queryRespondedBy',v_actor,
        'queryRespondedAt',v_now);
    elsif p_action='propose' then
      if v_deploy.state ? 'workAcceptance' then
        raise exception 'accepted_scope_requires_amendment_work' using errcode='23514'; end if;
      if v_kind<>'Scope change' or v_change.status not in ('Open','Returned')
        or v_member.role not in ('project_manager','billing_commercial_lead')
        or length(trim(coalesce(p_input->>'scopeDifference','')))<15
        or length(trim(coalesce(p_input->>'costBasis','')))<10
        or length(trim(coalesce(p_input->>'priceBasis','')))<10
        or coalesce(p_input->>'currency','')!~'^[A-Z]{3}$'
        or coalesce(p_input->>'priceAmount','')!~'^\d+(\.\d{1,2})?$'
        or length(trim(coalesce(p_input->>'scheduleImpact','')))<5 then
        raise exception 'change_proposal_incomplete' using errcode='22023'; end if;
      v_status:='Proposed';v_facts:=v_facts||pg_catalog.jsonb_build_object(
        'proposal',pg_catalog.jsonb_build_object('revision',v_change.revision+1,
          'scopeDifference',p_input->>'scopeDifference','costBasis',p_input->>'costBasis',
          'priceBasis',p_input->>'priceBasis','priceAmount',p_input->>'priceAmount',
          'currency',p_input->>'currency','scheduleImpact',p_input->>'scheduleImpact',
          'assumptions',p_input->>'assumptions','proposedBy',v_actor,'at',v_now));
    elsif p_action='submit-review' then
      if v_status<>'Proposed' or v_member.role not in ('project_manager','billing_commercial_lead')
        or length(trim(coalesce(p_input->>'reason','')))<10 then
        raise exception 'change_submission_denied' using errcode='42501'; end if;
      v_status:='Internal review';v_facts:=v_facts||pg_catalog.jsonb_build_object(
        'submittedBy',v_actor,'submittedAt',v_now,'submissionReason',p_input->>'reason');
    elsif p_action='review' then
      if v_status<>'Internal review' or v_actor::text=v_facts->>'submittedBy'
        or v_member.role not in ('billing_commercial_lead','admin')
        or p_input->>'decision' not in ('Approved','Returned')
        or length(trim(coalesce(p_input->>'reason','')))<15 then
        raise exception 'independent_change_review_required' using errcode='42501'; end if;
      v_status:=case when p_input->>'decision'='Approved' then 'Internally approved' else 'Returned' end;
      v_facts:=v_facts||pg_catalog.jsonb_build_object('internalReview',
        pg_catalog.jsonb_build_object('decision',p_input->>'decision','actorId',v_actor,
          'at',v_now,'reason',p_input->>'reason'));
    elsif p_action='record-customer' then
      if v_status<>'Internally approved' or v_member.role not in ('project_manager','operations_leader')
        or length(trim(coalesce(p_input->>'customerRepresentative','')))<4
        or length(trim(coalesce(p_input->>'authorityBasis','')))<10
        or nullif(p_input->>'evidenceId','') is null then
        raise exception 'customer_change_source_required' using errcode='42501'; end if;
      v_document:=d5o_hosted.require_customer_decision_evidence_v1(
        v_workspace,v_work.id,p_input->>'evidenceId','field-change-authorization',
        v_change.id::text,v_change.revision,
        pg_catalog.jsonb_build_object('packageId',p_package_id,
          'proposal',v_facts->'proposal','internalReview',v_facts->'internalReview'));
      v_status:='Customer authorized';v_facts:=v_facts||pg_catalog.jsonb_build_object(
        'customerAuthorization',pg_catalog.jsonb_build_object(
          'representative',p_input->>'customerRepresentative',
          'organization',p_input->>'organization','authorityBasis',p_input->>'authorityBasis',
          'source','evidence:'||(p_input->>'evidenceId'),'document',v_document,
          'recordedBy',v_actor,'at',v_now));
    elsif p_action='resolve' then
      if v_member.role not in ('project_manager','operations_leader')
        or v_actor=v_change.created_by or length(trim(coalesce(p_input->>'reason','')))<15 then
        raise exception 'independent_change_resolution_required' using errcode='42501'; end if;
      if v_kind='Scope change' then
        if v_status<>'Customer authorized' then
          raise exception 'customer_change_authorization_required' using errcode='23514'; end if;
        select r into v_new_release from pg_catalog.jsonb_array_elements(
          coalesce(v_design.state->'releases','[]'::jsonb)) r
          where r->>'packageId'=p_package_id order by r->>'issuedAt' desc limit 1;
        if v_new_release->>'status'<>'Accepted' or
          (v_new_release->>'packageRevision')::integer<=v_change.opened_package_revision
          or v_new_release->>'id'=v_change.opened_release_id then
          raise exception 'revised_design_receipt_required' using errcode='23514'; end if;
        v_facts:=v_facts||pg_catalog.jsonb_build_object('revisedReleaseId',v_new_release->>'id',
          'revisedPackageRevision',v_new_release->>'packageRevision');
      elsif v_kind='Clarification' and coalesce(v_facts->>'queryResponse','')='' then
        raise exception 'technical_response_required' using errcode='23514'; end if;
      v_status:='Resolved';v_facts:=v_facts||pg_catalog.jsonb_build_object(
        'resolution',p_input->>'reason','resolvedBy',v_actor,'resolvedAt',v_now);
    end if;
    update d5o_hosted.connected_field_changes set kind=v_kind,status=v_status,
      owner_role=case when v_status in ('Proposed','Internal review') then 'billing_commercial_lead'
        when v_status='Internally approved' then 'project_manager'
        when v_status='Query' then 'project_manager'
        else 'operations_leader' end,
      facts=v_facts,revision=revision+1,updated_at=v_now
      where id=v_change.id returning * into v_change;
  end if;
  v_result:=pg_catalog.jsonb_build_object('id',v_change.id,'revision',v_change.revision,
    'status',v_change.status,'packageId',v_change.package_id,'facts',v_change.facts);
  insert into d5o_hosted.connected_field_change_events(workspace_id,change_id,
    revision,command_id,actor_user_id,membership_id,action,snapshot)
    values(v_workspace,v_change.id,v_change.revision,p_command_id,v_actor,
      v_member.id,p_action,pg_catalog.to_jsonb(v_change));
  insert into d5o_hosted.connected_field_change_receipts(
    workspace_id,command_id,actor_user_id,fingerprint,result)
    values(v_workspace,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_field_evidence_command_v1(p_workspace_key text, p_presentation_id text, p_package_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_design_revision integer, p_expected_schedule_revision integer, p_expected_deploy_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_receipt d5o_hosted.connected_deploy_receipts%rowtype;
  v_binding d5o_hosted.crew_bindings%rowtype;
  v_release jsonb;v_publication jsonb;v_booking jsonb;
  v_state jsonb;v_evidence jsonb;v_path text;v_id uuid;
  v_object storage.objects%rowtype;v_now timestamptz:=now();
  v_fingerprint text;v_result jsonb;v_note text:=trim(coalesce(p_input->>'note',''));
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('register-upload','review-evidence')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_design_revision is null or p_expected_design_revision<1
    or p_expected_schedule_revision is null or p_expected_schedule_revision<1
    or p_expected_deploy_revision is null or p_expected_deploy_revision<1 then
    raise exception 'invalid_evidence_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'evidence_membership_required' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id
      and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
      for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_package_id,p_action,p_input,p_expected_source_revision,
    p_expected_design_revision,p_expected_schedule_revision,
    p_expected_deploy_revision)::text);
  select * into v_receipt from d5o_hosted.connected_deploy_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    if v_member.role='field_worker' then
      return pg_catalog.jsonb_build_object('accepted',true,
        'packageId',p_package_id,'commandId',p_command_id,'replay',true);
    end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_schedule from d5o_hosted.connected_schedule_states
    where workspace_id=v_workspace.id for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_design_revision
    or v_schedule.decision_revision is distinct from p_expected_schedule_revision
    or v_deploy.decision_revision is distinct from p_expected_deploy_revision then
    raise exception 'stale_evidence_basis' using errcode='23505'; end if;
  v_state:=v_deploy.state;
  select r into v_release from pg_catalog.jsonb_array_elements(v_design.state->'releases') r
    where r->>'packageId'=p_package_id order by r->>'issuedAt' desc limit 1;
  if v_release is null or v_release->>'status'<>'Accepted'
    or (v_release->>'packageRevision')::integer<>
      (select (p->>'revision')::integer from pg_catalog.jsonb_array_elements(
        v_design.state->'packages') p where p->>'packageId'=p_package_id) then
    raise exception 'current_release_required' using errcode='23514'; end if;
  if p_action='register-upload' then
    select * into v_binding from d5o_hosted.crew_bindings
      where workspace_id=v_workspace.id and actor_user_id=v_actor and active for share;
    select pub into v_publication from pg_catalog.jsonb_array_elements(
      v_schedule.state->'publications') pub
      where exists(select 1 from pg_catalog.jsonb_array_elements(pub->'assignments') a
        where a->>'workId'=p_presentation_id and a->>'packageId'=p_package_id)
      order by pub->>'publishedAt' desc limit 1;
    select a into v_booking from pg_catalog.jsonb_array_elements(
      coalesce(v_publication->'assignments','[]'::jsonb)) a
      where a->>'id'=p_input->>'bookingId' and a->>'workId'=p_presentation_id
        and a->>'packageId'=p_package_id;
    if v_member.role<>'field_worker' or v_binding.person is null
      or v_booking is null or not (v_booking->'people' ? v_binding.person) then
      raise exception 'assigned_worker_required' using errcode='42501'; end if;
    begin v_id:=(p_input->>'evidenceId')::uuid;
    exception when invalid_text_representation then
      raise exception 'invalid_evidence_id' using errcode='22023'; end;
    if v_id is null or length(trim(coalesce(p_input->>'caption','')))<5
      or length(trim(coalesce(p_input->>'purpose','')))<3 then
      raise exception 'evidence_description_required' using errcode='22023'; end if;
    v_path:=p_workspace_key||'/'||pg_catalog.encode(
      extensions.digest(p_presentation_id,'sha256'),'hex')||'/'||v_id::text;
    select * into v_object from storage.objects
      where bucket_id='d5o-deploy-evidence' and name=v_path;
    if not found or v_object.metadata->>'mimetype' not in
      ('image/jpeg','image/png','image/webp','application/pdf')
      or (v_object.metadata->>'size')::bigint not between 1 and 10485760 then
      raise exception 'uploaded_object_missing_or_invalid' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'evidence') e
      where e->>'id'=v_id::text) then
      raise exception 'evidence_already_registered' using errcode='23505'; end if;
    v_evidence:=pg_catalog.jsonb_build_object('id',v_id,'packageId',p_package_id,
      'releaseId',v_release->>'id','bookingId',v_booking->>'id',
      'purpose',trim(p_input->>'purpose'),'caption',trim(p_input->>'caption'),
      'filename',left(coalesce(p_input->>'filename','field-file'),200),
      'mimeType',v_object.metadata->>'mimetype',
      'sizeBytes',(v_object.metadata->>'size')::bigint,
      'checksumSha256',p_input->>'checksumSha256',
      'objectPath',v_path,'uploaderId',v_actor,
      'uploadedAt',v_now,'state','Uploaded');
    v_state:=pg_catalog.jsonb_set(v_state,'{evidence}',
      v_state->'evidence'||pg_catalog.jsonb_build_array(v_evidence));
  else
    if v_member.role not in ('operations_leader','field_supervisor')
      or p_input->>'decision' not in ('Reviewed','Returned')
      or length(v_note)<15 then
      raise exception 'evidence_review_authority_required' using errcode='42501'; end if;
    select e into v_evidence from pg_catalog.jsonb_array_elements(v_state->'evidence') e
      where e->>'id'=p_input->>'evidenceId' and e->>'packageId'=p_package_id;
    if v_evidence is null or v_evidence->>'state'<>'Uploaded'
      or v_evidence->>'uploaderId'=v_actor::text
      or v_evidence->>'releaseId'<>v_release->>'id' then
      raise exception 'independent_current_evidence_required' using errcode='23514'; end if;
    select * into v_object from storage.objects
      where bucket_id='d5o-deploy-evidence' and name=v_evidence->>'objectPath';
    if not found then raise exception 'evidence_object_unavailable' using errcode='23514'; end if;
    v_evidence:=v_evidence||pg_catalog.jsonb_build_object(
      'state',p_input->>'decision','reviewerId',v_actor,
      'reviewedAt',v_now,'reviewNote',v_note);
    v_state:=pg_catalog.jsonb_set(v_state,'{evidence}',
      (select pg_catalog.jsonb_agg(case when e->>'id'=v_evidence->>'id'
        then v_evidence else e end order by ordinal)
        from pg_catalog.jsonb_array_elements(v_state->'evidence')
          with ordinality as entries(e,ordinal)));
  end if;
  v_state:=v_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_deploy.decision_revision+1,
    'events',v_state->'events'||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'commandId',p_command_id,'at',v_now,'actorId',v_actor,
        'membershipId',v_member.id,'action',p_action,
        'packageId',p_package_id,'evidenceId',v_evidence->>'id')));
  update d5o_hosted.connected_deploy_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_deploy_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    design_revision,schedule_revision,snapshot)
  values(v_workspace.id,v_work.id,v_deploy.decision_revision+1,p_command_id,
    p_action,v_actor,v_member.id,v_design.decision_revision,
    v_schedule.decision_revision,v_state);
  v_result:=case when v_member.role='field_worker' then
    pg_catalog.jsonb_build_object('accepted',true,
      'decisionRevision',v_deploy.decision_revision+1,
      'packageId',p_package_id,'commandId',p_command_id)
    else public.d5o_hosted_prototype_read_v1(p_workspace_key,'work') end;
  insert into d5o_hosted.connected_deploy_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_field_fact_command_v1(p_workspace_key text, p_presentation_id text, p_package_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_design_revision integer, p_expected_schedule_revision integer, p_expected_deploy_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_receipt d5o_hosted.connected_deploy_receipts%rowtype;
  v_binding d5o_hosted.crew_bindings%rowtype;
  v_policy jsonb;v_state jsonb;v_release jsonb;v_publication jsonb;
  v_booking jsonb;v_permit jsonb;v_report jsonb;v_inspection jsonb;
  v_item jsonb;v_prior jsonb;v_id text;v_note text:=trim(coalesce(p_input->>'note',''));
  v_now timestamptz:=now();v_fingerprint text;v_result jsonb;
  v_quantity numeric;v_hours numeric;v_planned numeric;v_total numeric;
  v_requirement text;v_has_pass boolean;v_failed boolean;v_evidence_ids jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-report','submit-report','review-report',
      'record-inspection','review-inspection','review-completion')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_design_revision is null or p_expected_design_revision<1
    or p_expected_schedule_revision is null or p_expected_schedule_revision<1
    or p_expected_deploy_revision is null or p_expected_deploy_revision<1 then
    raise exception 'invalid_field_fact_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'field_membership_required' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id
      and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
      for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_package_id,p_action,p_input,p_expected_source_revision,
    p_expected_design_revision,p_expected_schedule_revision,
    p_expected_deploy_revision)::text);
  select * into v_receipt from d5o_hosted.connected_deploy_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    if v_member.role='field_worker' then
      return pg_catalog.jsonb_build_object('accepted',true,
        'packageId',p_package_id,'commandId',p_command_id,'replay',true);
    end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_schedule from d5o_hosted.connected_schedule_states
    where workspace_id=v_workspace.id for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_design_revision
    or v_schedule.decision_revision is distinct from p_expected_schedule_revision
    or v_deploy.decision_revision is distinct from p_expected_deploy_revision then
    raise exception 'stale_field_fact_basis' using errcode='23505'; end if;
  select wt->'deployControls' into v_policy
    from d5o_hosted.configuration_versions c,
      lateral pg_catalog.jsonb_array_elements(
        c.manifest_json#>'{d5oPresentation,phaseContract,workTypes}') wt
    where c.id=v_work.configuration_version_id
      and wt->>'workTypeKey'=v_work.work_type_key;
  if v_policy is null or v_policy->>'schemaVersion'<>'1' then
    raise exception 'pinned_deploy_policy_unavailable' using errcode='23514'; end if;
  v_state:=v_deploy.state;
  select r into v_release from pg_catalog.jsonb_array_elements(v_design.state->'releases') r
    where r->>'packageId'=p_package_id order by r->>'issuedAt' desc limit 1;
  if v_release is null or v_release->>'status'<>'Accepted'
    or (v_release->>'packageRevision')::integer<>
      (select (p->>'revision')::integer from pg_catalog.jsonb_array_elements(
        v_design.state->'packages') p where p->>'packageId'=p_package_id) then
    raise exception 'current_release_required' using errcode='23514'; end if;
  -- An uploaded file is only a candidate source. Link IDs only when the same
  -- assigned worker can read the exact package and accepted-release evidence.
  if p_action in ('save-report','record-inspection') then
    v_evidence_ids:=coalesce(p_input->'evidenceIds','[]'::jsonb);
    if pg_catalog.jsonb_typeof(v_evidence_ids)<>'array' or
      pg_catalog.jsonb_array_length(v_evidence_ids)>20 then
      raise exception 'field_evidence_scope_invalid' using errcode='23514'; end if;
    if (select count(*) from pg_catalog.jsonb_array_elements_text(v_evidence_ids))<>
      (select count(distinct value) from pg_catalog.jsonb_array_elements_text(v_evidence_ids)) then
      raise exception 'field_evidence_scope_invalid' using errcode='23514'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(v_evidence_ids) loop
      if pg_catalog.jsonb_typeof(v_item)<>'string' or not exists(select 1 from
        pg_catalog.jsonb_array_elements(coalesce(v_state->'evidence','[]'::jsonb)) e
        where e->>'id'=v_item#>>'{}' and e->>'packageId'=p_package_id
          and e->>'releaseId'=v_release->>'id' and e->>'uploaderId'=v_actor::text
          and e->>'state' in ('Uploaded','Reviewed')) then
        raise exception 'field_evidence_scope_invalid' using errcode='23514'; end if;
    end loop;
  end if;
  select pub into v_publication from pg_catalog.jsonb_array_elements(
    v_schedule.state->'publications') pub
    where exists(select 1 from pg_catalog.jsonb_array_elements(pub->'assignments') a
      where a->>'workId'=p_presentation_id and a->>'packageId'=p_package_id)
    order by pub->>'publishedAt' desc limit 1;
  select a into v_booking from pg_catalog.jsonb_array_elements(
    coalesce(v_publication->'assignments','[]'::jsonb)) a
    where a->>'id'=p_input->>'bookingId' and a->>'workId'=p_presentation_id
      and a->>'packageId'=p_package_id;
  if p_action in ('save-report','submit-report','record-inspection') then
    select * into v_binding from d5o_hosted.crew_bindings
      where workspace_id=v_workspace.id and actor_user_id=v_actor
        and active for share;
    if v_member.role<>'field_worker' or v_binding.person is null
      or v_booking is null or not (v_booking->'people' ? v_binding.person) then
      raise exception 'assigned_worker_required' using errcode='42501'; end if;
  end if;
  select p into v_permit from pg_catalog.jsonb_array_elements(v_state->'permits') p
    where p->>'packageId'=p_package_id order by p->>'at' desc limit 1;
  if p_action='save-report' then
    v_quantity:=(p_input->>'quantity')::numeric;
    v_hours:=(p_input->>'laborHours')::numeric;
    if v_quantity<0 or v_hours<0 or v_hours>
      (v_policy->>'maxActualHoursPerShift')::numeric
      or p_input->>'unit' is distinct from
        v_release#>>'{snapshot,completionBasis,unit}'
      or length(trim(coalesce(p_input->>'summary','')))<10 then
      raise exception 'measured_report_invalid' using errcode='22023'; end if;
    v_id:=coalesce(nullif(p_input->>'reportId',''),gen_random_uuid()::text);
    select r into v_prior from pg_catalog.jsonb_array_elements(v_state->'reports') r
      where r->>'id'=v_id;
    if v_prior is not null and (v_prior->>'authorId'<>v_actor::text
      or v_prior->>'status' not in ('Draft','Returned')
      or v_prior->>'bookingId'<>v_booking->>'id') then
      raise exception 'report_correction_denied' using errcode='42501'; end if;
    v_report:=pg_catalog.jsonb_build_object('id',v_id,
      'revision',coalesce((v_prior->>'revision')::integer,0)+1,
      'packageId',p_package_id,'releaseId',v_release->>'id',
      'bookingId',v_booking->>'id','date',v_booking->>'date',
      'quantity',v_quantity,'unit',p_input->>'unit',
      'laborHours',v_hours,'material',coalesce(p_input->>'material',''),
      'summary',trim(p_input->>'summary'),
      'evidenceIds',v_evidence_ids,'capturedAt',coalesce(p_input->>'capturedAt',v_now::text),
      'receivedAt',v_now,'authorId',v_actor,'status','Draft',
      'history',coalesce(v_prior->'history','[]'::jsonb)||
        pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
          'revision',coalesce((v_prior->>'revision')::integer,0)+1,
          'at',v_now,'reason',coalesce(nullif(v_note,''),'Field draft saved'))));
    v_state:=pg_catalog.jsonb_set(v_state,'{reports}',
      (select coalesce(pg_catalog.jsonb_agg(r order by ordinal),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(v_state->'reports')
          with ordinality as entries(r,ordinal) where r->>'id'<>v_id)
        ||pg_catalog.jsonb_build_array(v_report));
  elsif p_action='submit-report' then
    select r into v_report from pg_catalog.jsonb_array_elements(v_state->'reports') r
      where r->>'id'=p_input->>'reportId' and r->>'packageId'=p_package_id;
    if v_report is null or v_report->>'status'<>'Draft'
      or v_report->>'authorId'<>v_actor::text
      or v_permit->>'status'<>'Authorized'
      or v_permit->>'releaseId'<>v_release->>'id'
      or v_permit->>'publicationId'<>v_publication->>'id'
      or (v_permit->>'scheduleRevision')::integer<>
        v_schedule.decision_revision then
      raise exception 'current_start_and_author_required' using errcode='23514'; end if;
    v_report:=v_report||pg_catalog.jsonb_build_object('status','Submitted');
    v_state:=pg_catalog.jsonb_set(v_state,'{reports}',
      (select pg_catalog.jsonb_agg(case when r->>'id'=v_report->>'id'
        then v_report else r end order by ordinal)
        from pg_catalog.jsonb_array_elements(v_state->'reports')
          with ordinality as entries(r,ordinal)));
  elsif p_action='review-report' then
    if v_member.role not in ('field_supervisor','operations_leader')
      or p_input->>'decision' not in ('Reviewed','Returned')
      or length(v_note)<15 then
      raise exception 'report_review_authority_required' using errcode='42501'; end if;
    select r into v_report from pg_catalog.jsonb_array_elements(v_state->'reports') r
      where r->>'id'=p_input->>'reportId' and r->>'packageId'=p_package_id;
    if v_report is null or v_report->>'status'<>'Submitted'
      or v_report->>'authorId'=v_actor::text then
      raise exception 'independent_submitted_report_required' using errcode='42501'; end if;
    v_report:=v_report||pg_catalog.jsonb_build_object(
      'status',p_input->>'decision','reviewerId',v_actor,
      'reviewNote',v_note,'reviewedAt',v_now);
    v_state:=pg_catalog.jsonb_set(v_state,'{reports}',
      (select pg_catalog.jsonb_agg(case when r->>'id'=v_report->>'id'
        then v_report else r end order by ordinal)
        from pg_catalog.jsonb_array_elements(v_state->'reports')
          with ordinality as entries(r,ordinal)));
  elsif p_action='record-inspection' then
    select r into v_report from pg_catalog.jsonb_array_elements(v_state->'reports') r
      where r->>'id'=p_input->>'reportId' and r->>'packageId'=p_package_id
        and r->>'status'='Reviewed';
    v_requirement:=p_input->>'requirementId';
    if v_report is null or not (v_release#>'{snapshot,requirementIds}' ? v_requirement)
      or p_input->>'result' not in ('Pass','Fail')
      or length(trim(coalesce(p_input->>'method','')))<5 then
      raise exception 'inspection_basis_invalid' using errcode='23514'; end if;
    if p_input->>'supersedesId' is not null and not exists(select 1 from
      pg_catalog.jsonb_array_elements(v_state->'inspections') i
      where i->>'id'=p_input->>'supersedesId'
        and i->>'packageId'=p_package_id
        and i->>'requirementId'=v_requirement
        and i->>'result'='Fail' and i->>'status'='Verified') then
      raise exception 'failed_inspection_reference_required' using errcode='23514'; end if;
    v_inspection:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),
      'packageId',p_package_id,'releaseId',v_release->>'id',
      'reportId',v_report->>'id','requirementId',v_requirement,
      'requirement',coalesce(p_input->>'requirement',v_requirement),
      'method',trim(p_input->>'method'),'result',p_input->>'result',
      'note',v_note,'evidenceIds',v_evidence_ids,'at',v_now,
      'actorId',v_actor,'status','Submitted',
      'supersedesId',p_input->>'supersedesId');
    v_state:=pg_catalog.jsonb_set(v_state,'{inspections}',
      v_state->'inspections'||pg_catalog.jsonb_build_array(v_inspection));
  elsif p_action='review-inspection' then
    if v_member.role<>'operations_leader' or
      p_input->>'decision' not in ('Verified','Returned')
      or length(v_note)<15 then
      raise exception 'quality_review_authority_required' using errcode='42501'; end if;
    select i into v_inspection from pg_catalog.jsonb_array_elements(
      v_state->'inspections') i where i->>'id'=p_input->>'inspectionId'
        and i->>'packageId'=p_package_id;
    if v_inspection is null or v_inspection->>'status'<>'Submitted'
      or v_inspection->>'actorId'=v_actor::text then
      raise exception 'independent_inspection_required' using errcode='42501'; end if;
    v_inspection:=v_inspection||pg_catalog.jsonb_build_object(
      'status',p_input->>'decision','reviewerId',v_actor,
      'reviewNote',v_note,'reviewedAt',v_now);
    v_state:=pg_catalog.jsonb_set(v_state,'{inspections}',
      (select pg_catalog.jsonb_agg(case when i->>'id'=v_inspection->>'id'
        then v_inspection else i end order by ordinal)
        from pg_catalog.jsonb_array_elements(v_state->'inspections')
          with ordinality as entries(i,ordinal)));
  else
    if v_member.role<>'operations_leader' or length(v_note)<15 then
      raise exception 'quality_completion_authority_required' using errcode='42501'; end if;
    v_planned:=(v_release#>>'{snapshot,completionBasis,plannedQuantity}')::numeric;
    if v_release#>>'{snapshot,completionBasis,kind}'<>'Measured'
      or v_planned<=0 then
      raise exception 'unsupported_completion_basis' using errcode='23514'; end if;
    select coalesce(sum((r->>'quantity')::numeric),0) into v_total
      from pg_catalog.jsonb_array_elements(v_state->'reports') r
      where r->>'packageId'=p_package_id and r->>'releaseId'=v_release->>'id'
        and r->>'status'='Reviewed' and r->>'unit'=
          v_release#>>'{snapshot,completionBasis,unit}';
    if v_total<>v_planned then
      raise exception 'measured_scope_incomplete_or_exceeded' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'reports') r
      where r->>'packageId'=p_package_id and r->>'releaseId'=v_release->>'id'
        and r->>'status'='Reviewed' and r->>'authorId'=v_actor::text) then
      raise exception 'completion_reviewer_independence_required' using errcode='42501'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'issues') i
      where i->>'packageId'=p_package_id and i->>'status'='Open') then
      raise exception 'open_issue_blocks_completion' using errcode='23514'; end if;
    for v_item in select value from pg_catalog.jsonb_array_elements(
      v_release#>'{snapshot,requirementIds}') loop
      v_requirement:=v_item#>>'{}';
      select exists(select 1 from pg_catalog.jsonb_array_elements(
        v_state->'inspections') i
        where i->>'packageId'=p_package_id and i->>'releaseId'=v_release->>'id'
          and i->>'requirementId'=v_requirement and i->>'result'='Pass'
          and i->>'status'='Verified') into v_has_pass;
      select exists(select 1 from pg_catalog.jsonb_array_elements(
        v_state->'inspections') i
        where i->>'packageId'=p_package_id and i->>'releaseId'=v_release->>'id'
          and i->>'requirementId'=v_requirement and i->>'result'='Fail'
          and i->>'status'='Verified' and not exists(select 1 from
            pg_catalog.jsonb_array_elements(v_state->'inspections') retest
            where retest->>'supersedesId'=i->>'id'
              and retest->>'result'='Pass' and retest->>'status'='Verified'))
        into v_failed;
      if not v_has_pass or v_failed then
        raise exception 'verified_requirement_or_retest_missing' using errcode='23514'; end if;
    end loop;
    if v_policy->>'requireReviewedEvidence'='true' and not exists(select 1 from
      pg_catalog.jsonb_array_elements(v_state->'evidence') e
      where e->>'packageId'=p_package_id and e->>'releaseId'=v_release->>'id'
        and e->>'state'='Reviewed') then
      raise exception 'reviewed_evidence_required' using errcode='23514'; end if;
    -- Prior reviewed decisions remain in history. A new fact set needs its
    -- own independent review, but issued turnover freezes this package basis.
    if v_state->'workAcceptance' is not null or exists(select 1 from
      pg_catalog.jsonb_array_elements(coalesce(v_state->'turnovers','[]'::jsonb)) t
      where t->'releaseIds' ? (v_release->>'id')) then
      raise exception 'completion_scope_frozen' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'completions','[]'::jsonb)) c
      where c->>'packageId'=p_package_id and c->>'releaseId'=v_release->>'id'
        and c->>'status'='Reviewed' and (c->>'reviewedQuantity')::numeric is not distinct from v_total
        and c->'reportIds'=(select coalesce(pg_catalog.jsonb_agg(r->>'id'),'[]'::jsonb)
          from pg_catalog.jsonb_array_elements(v_state->'reports') r
          where r->>'packageId'=p_package_id and r->>'releaseId'=v_release->>'id'
            and r->>'status'='Reviewed')
        and c->'inspectionIds'=(select coalesce(pg_catalog.jsonb_agg(i->>'id'),'[]'::jsonb)
          from pg_catalog.jsonb_array_elements(v_state->'inspections') i
          where i->>'packageId'=p_package_id and i->>'releaseId'=v_release->>'id'
            and i->>'status'='Verified' and i->>'result'='Pass')) then
      raise exception 'completion_already_reviewed' using errcode='23514'; end if;
    v_state:=pg_catalog.jsonb_set(v_state,'{completions}',
      coalesce(v_state->'completions','[]'::jsonb)||
        pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
          'id',gen_random_uuid(),
          'revision',1+(select count(*) from pg_catalog.jsonb_array_elements(
            coalesce(v_state->'completions','[]'::jsonb)) c
            where c->>'packageId'=p_package_id and c->>'releaseId'=v_release->>'id'),
          'supersedesId',(select c->>'id' from pg_catalog.jsonb_array_elements(
            coalesce(v_state->'completions','[]'::jsonb)) c
            where c->>'packageId'=p_package_id and c->>'releaseId'=v_release->>'id'
            order by (c->>'reviewedAt')::timestamptz desc limit 1),
          'packageId',p_package_id,
          'releaseId',v_release->>'id',
          'packageRevision',(v_release->>'packageRevision')::integer,
          'basis',v_release#>'{snapshot,completionBasis}',
          'reviewedQuantity',v_total,
          'unit',v_release#>>'{snapshot,completionBasis,unit}',
          'reportIds',(select pg_catalog.jsonb_agg(r->>'id') from
            pg_catalog.jsonb_array_elements(v_state->'reports') r
            where r->>'packageId'=p_package_id and r->>'releaseId'=v_release->>'id'
              and r->>'status'='Reviewed'),
          'inspectionIds',(select pg_catalog.jsonb_agg(i->>'id') from
            pg_catalog.jsonb_array_elements(v_state->'inspections') i
            where i->>'packageId'=p_package_id and i->>'releaseId'=v_release->>'id'
              and i->>'status'='Verified' and i->>'result'='Pass'),
          'reviewedAt',v_now,'reviewerId',v_actor,
          'membershipId',v_member.id,'reason',v_note,'status','Reviewed')));
  end if;
  v_state:=v_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_deploy.decision_revision+1,
    'events',v_state->'events'||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'commandId',p_command_id,'at',v_now,'actorId',v_actor,
        'membershipId',v_member.id,'action',p_action,
        'packageId',p_package_id,'note',v_note)));
  update d5o_hosted.connected_deploy_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_deploy_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    design_revision,schedule_revision,snapshot)
  values(v_workspace.id,v_work.id,v_deploy.decision_revision+1,p_command_id,
    p_action,v_actor,v_member.id,v_design.decision_revision,
    v_schedule.decision_revision,v_state);
  v_result:=case when v_member.role='field_worker' then
    pg_catalog.jsonb_build_object('accepted',true,
      'decisionRevision',v_deploy.decision_revision+1,
      'packageId',p_package_id,'commandId',p_command_id)
    else public.d5o_hosted_prototype_read_v1(p_workspace_key,'work') end;
  insert into d5o_hosted.connected_deploy_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_field_start_command_v1(p_workspace_key text, p_presentation_id text, p_package_id text, p_action text, p_reason text, p_command_id text, p_expected_source_revision bigint, p_expected_design_revision integer, p_expected_schedule_revision integer, p_expected_deploy_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_receipt d5o_hosted.connected_deploy_receipts%rowtype;
  v_policy jsonb;v_release jsonb;v_package jsonb;v_publication jsonb;
  v_current_source jsonb;v_current_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_booking jsonb;v_person jsonb;v_predecessor jsonb;v_material jsonb;
  v_state jsonb;v_permit jsonb;v_result jsonb;v_now timestamptz:=now();
  v_fingerprint text;v_timezone text;v_shift_start timestamptz;
  v_shift_end timestamptz;v_shift_start_text text;v_shift_end_text text;v_start_lead_minutes integer;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('authorize-start','hold','resume')
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or length(trim(coalesce(p_reason,'')))<15
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_design_revision is null or p_expected_design_revision<1
    or p_expected_schedule_revision is null or p_expected_schedule_revision<1
    or p_expected_deploy_revision is null or p_expected_deploy_revision<0 then
    raise exception 'invalid_field_start_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('field_supervisor','operations_leader') then
    raise exception 'field_start_authority_required' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id
      and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
      for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_package_id,p_action,p_reason,p_expected_source_revision,
    p_expected_design_revision,p_expected_schedule_revision,
    p_expected_deploy_revision)::text);
  select * into v_receipt from d5o_hosted.connected_deploy_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_schedule from d5o_hosted.connected_schedule_states
    where workspace_id=v_workspace.id for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_design.decision_revision is distinct from p_expected_design_revision
    or v_schedule.decision_revision is distinct from p_expected_schedule_revision
    or coalesce(v_deploy.decision_revision,0)<>p_expected_deploy_revision then
    raise exception 'stale_field_start_basis' using errcode='23505'; end if;
  select wt->'deployControls' into v_policy
    from d5o_hosted.configuration_versions c,
      lateral pg_catalog.jsonb_array_elements(
        c.manifest_json#>'{d5oPresentation,phaseContract,workTypes}') wt
    where c.id=v_work.configuration_version_id
      and wt->>'workTypeKey'=v_work.work_type_key;
  if v_policy is null or v_policy->>'schemaVersion'<>'1' then
    raise exception 'pinned_deploy_policy_unavailable' using errcode='23514'; end if;
  v_state:=coalesce(v_deploy.state,pg_catalog.jsonb_build_object(
    'permits','[]'::jsonb,'reports','[]'::jsonb,'inspections','[]'::jsonb,
    'issues','[]'::jsonb,'evidence','[]'::jsonb,'signoffs','[]'::jsonb,
    'turnovers','[]'::jsonb,'completions','[]'::jsonb,'events','[]'::jsonb));
  select r into v_release from pg_catalog.jsonb_array_elements(v_design.state->'releases') r
    where r->>'packageId'=p_package_id order by r->>'issuedAt' desc limit 1;
  if v_release is null or v_release->>'status'<>'Accepted'
    or (v_release->>'packageRevision')::integer<>
      (select (p->>'revision')::integer from pg_catalog.jsonb_array_elements(
        v_design.state->'packages') p where p->>'packageId'=p_package_id) then
    raise exception 'current_accepted_release_required' using errcode='23514'; end if;
  -- A service receipt remains historical; start and resume require the same
  -- accepted request/asset/coverage basis to be current at commit time.
  if p_action in ('authorize-start','resume') and exists (
    select 1 from d5o_hosted.work_identity_links l
    where l.workspace_id=v_workspace.id and l.work_id=v_work.id
      and l.relation_kind='service_visit') then
    if v_release->>'sourceKind'<>'service' then
      raise exception 'service_release_source_required' using errcode='23514'; end if;
    v_current_source:=d5o_hosted.connected_design_source_v1(
      v_workspace.id,v_work.id,v_raw.state_json);
    select * into v_current_handoff from d5o_hosted.connected_design_handoffs
      where workspace_id=v_workspace.id and work_id=v_work.id for share;
    if v_release->>'sourceId'<>v_current_handoff.handoff->>'id'
      or v_release->>'sourceDigest'<>v_current_handoff.source_digest
      or v_release->>'sourceId'<>v_current_source#>>'{serviceExecutionBasis,id}' then
      raise exception 'stale_service_field_basis' using errcode='23514'; end if;
  end if;
  v_package:=v_release->'snapshot';
  select pub into v_publication from pg_catalog.jsonb_array_elements(
    v_schedule.state->'publications') pub
    where exists(select 1 from pg_catalog.jsonb_array_elements(
      pub->'assignments') a where a->>'workId'=p_presentation_id
        and a->>'packageId'=p_package_id)
    order by pub->>'publishedAt' desc limit 1;
  select a into v_booking from pg_catalog.jsonb_array_elements(
    coalesce(v_publication->'assignments','[]'::jsonb)) a
    where a->>'workId'=p_presentation_id and a->>'packageId'=p_package_id;
  if v_booking is null or not exists(select 1 from pg_catalog.jsonb_array_elements(
    v_schedule.state->'assignments') a where a=v_booking)
    or pg_catalog.jsonb_array_length(v_booking->'people')<
      (v_release#>>'{crewDemandSnapshot,minimumPeople}')::integer then
    raise exception 'current_published_crew_required' using errcode='23514'; end if;
  if p_action in ('authorize-start','resume') then
    -- Serialize with roster and membership changes before allowing new work.
    for v_person in select value from pg_catalog.jsonb_array_elements(v_booking->'people') loop
      perform 1 from d5o_hosted.connected_crew_profiles cp
        join d5o_hosted.crew_bindings b on b.workspace_id=cp.workspace_id
          and b.actor_user_id=cp.actor_user_id and b.person=cp.person and b.active
        join d5o_hosted.memberships m on m.workspace_id=cp.workspace_id
          and m.actor_user_id=cp.actor_user_id and m.status='active'
          and m.role='field_worker'
        where cp.workspace_id=v_workspace.id and cp.person=v_person#>>'{}'
          and cp.active
          and (coalesce(v_release#>>'{crewDemandSnapshot,qualification}','')=''
            or v_release#>>'{crewDemandSnapshot,qualification}'=any(cp.qualifications))
        for share of cp,b,m;
      if not found then
        raise exception 'current_crew_eligibility_required' using errcode='23514'; end if;
    end loop;
    perform d5o_hosted.crew_booking_eligibility_v1(v_workspace.id,v_schedule.state,v_booking);
  end if;
  if p_action in ('authorize-start','resume') then
    -- A published booking is planning evidence. Start authority must match the
    -- immutable released demand and the actual shift in the pinned time zone.
    select wt#>>'{operateControls,timezone}' into v_timezone
      from d5o_hosted.configuration_versions c,
        lateral pg_catalog.jsonb_array_elements(
          c.manifest_json#>'{d5oPresentation,phaseContract,workTypes}') wt
      where c.id=v_work.configuration_version_id
        and wt->>'workTypeKey'=v_work.work_type_key;
    if coalesce(v_timezone,'')='' then
      raise exception 'field_timezone_unavailable' using errcode='23514'; end if;
    if coalesce(v_booking->>'date','') !~ '^\d{4}-\d{2}-\d{2}$'
      or not exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_release#>'{crewDemandSnapshot,requiredSlots}','[]'::jsonb)) slot
        where slot->>'date'=v_booking->>'date'
          and slot->>'shift'=v_booking->>'shift')
      or coalesce(v_package->>'windowStart','')<>''
        and v_booking->>'date'<v_package->>'windowStart'
      or coalesce(v_package->>'windowEnd','')<>''
        and v_booking->>'date'>v_package->>'windowEnd' then
      raise exception 'booking_outside_released_demand' using errcode='23514'; end if;
    v_shift_start_text:=substring(v_booking->>'shift' from '^([0-2][0-9]:[0-5][0-9])');
    v_shift_end_text:=substring(v_booking->>'shift' from '([0-2][0-9]:[0-5][0-9])$');
    if v_shift_start_text is null or v_shift_end_text is null
      or v_shift_start_text>'23:59' or v_shift_end_text>'23:59' then
      raise exception 'field_shift_window_unavailable' using errcode='23514'; end if;
    v_shift_start:=((v_booking->>'date')::date+v_shift_start_text::time)
      at time zone v_timezone;
    v_shift_end:=((v_booking->>'date')::date+
      case when v_shift_end_text<=v_shift_start_text then 1 else 0 end+
      v_shift_end_text::time) at time zone v_timezone;
    v_start_lead_minutes:=coalesce((v_policy->>'fieldStartLeadMinutes')::integer,60);
    if v_start_lead_minutes<0 or v_start_lead_minutes>60 then
      raise exception 'invalid_field_start_lead_policy' using errcode='23514'; end if;
    if v_now<v_shift_start-pg_catalog.make_interval(mins => v_start_lead_minutes) or v_now>v_shift_end then
      raise exception 'field_shift_not_current' using errcode='23514'; end if;
  end if;
  for v_person in select value from pg_catalog.jsonb_array_elements(
    v_booking->'people') loop
    if v_policy->>'requireWorkerAcknowledgment'='true' and not exists(
      select 1 from pg_catalog.jsonb_array_elements(v_schedule.state->'receipts') r
        where r->>'publicationId'=v_publication->>'id'
          and r->>'assignmentId'=v_booking->>'id'
          and r->>'recipient'=v_person#>>'{}'
          and r->>'response'='acknowledged') then
      raise exception 'worker_acknowledgment_required' using errcode='23514'; end if;
  end loop;
  for v_predecessor in select value from pg_catalog.jsonb_array_elements(
    v_package->'predecessorIds') loop
    if not exists(select 1 from pg_catalog.jsonb_array_elements(
      coalesce(v_state->'completions','[]'::jsonb)) c
      where c->>'packageId'=v_predecessor#>>'{}'
        and c->>'status'='Reviewed'
        and exists(select 1 from pg_catalog.jsonb_array_elements(
          v_design.state->'releases') r where r->>'id'=c->>'releaseId'
            and r->>'status'='Accepted')) then
      raise exception 'predecessor_reviewed_completion_required' using errcode='23514'; end if;
  end loop;
  if v_policy->>'requirePhysicalMaterials'='true' then
    for v_material in select value from pg_catalog.jsonb_array_elements(
      coalesce(v_package->'materialLines','[]'::jsonb)) loop
      if v_material->>'status'<>'Available' or
        coalesce((v_material->>'availableQuantity')::numeric,0)<
          (v_material->>'quantity')::numeric then
        raise exception 'physical_material_shortage' using errcode='23514'; end if;
    end loop;
  end if;
  if v_policy->>'requireAccess'='true' and coalesce(v_package->>'access','')=''
    or v_policy->>'requirePermit'='true' and coalesce(v_package->>'permit','')=''
    or coalesce(v_package->>'safetyControls','')=''
    or coalesce(v_package->>'method','')='' then
    raise exception 'field_controls_incomplete' using errcode='23514'; end if;
  if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'issues') i
    where i->>'packageId'=p_package_id and i->>'status'='Open') then
    raise exception 'open_issue_blocks_start' using errcode='23514'; end if;
  if p_action='authorize-start' then
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'permits') p
      where p->>'packageId'=p_package_id and p->>'releaseId'=v_release->>'id'
        and p->>'status'='Authorized') then
      raise exception 'already_authorized' using errcode='23514'; end if;
  elsif p_action='hold' then
    if not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'permits') p
      where p->>'packageId'=p_package_id and p->>'releaseId'=v_release->>'id'
        and p->>'status'='Authorized') then
      raise exception 'active_start_required' using errcode='23514'; end if;
    v_state:=pg_catalog.jsonb_set(v_state,'{permits}',
      (select pg_catalog.jsonb_agg(case when p->>'packageId'=p_package_id and p->>'releaseId'=v_release->>'id'
        and p->>'status'='Authorized' then p||pg_catalog.jsonb_build_object(
          'status','Held','heldAt',v_now) else p end order by ordinal)
        from pg_catalog.jsonb_array_elements(v_state->'permits')
          with ordinality as entries(p,ordinal)));
  else
    if not exists(select 1 from pg_catalog.jsonb_array_elements(v_state->'permits') p
      where p->>'packageId'=p_package_id and p->>'releaseId'=v_release->>'id'
        and p->>'status'='Held') then
      raise exception 'held_start_required' using errcode='23514'; end if;
  end if;
  if p_action in ('authorize-start','resume') then
    v_permit:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),
      'packageId',p_package_id,'releaseId',v_release->>'id',
      'packageRevision',(v_release->>'packageRevision')::integer,
      'publicationId',v_publication->>'id',
      'scheduleRevision',v_schedule.decision_revision,
      'policyVersionId',v_work.configuration_version_id,
      'status','Authorized','at',v_now,'actorId',v_actor,
      'reason',trim(p_reason));
    v_state:=pg_catalog.jsonb_set(v_state,'{permits}',
      v_state->'permits'||pg_catalog.jsonb_build_array(v_permit));
  end if;
  v_state:=v_state||pg_catalog.jsonb_build_object(
    'authorityRevision',coalesce(v_deploy.decision_revision,0)+1,
    'events',v_state->'events'||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'commandId',p_command_id,'at',v_now,'actorId',v_actor,
        'membershipId',v_member.id,'action',p_action,
        'packageId',p_package_id,'note',trim(p_reason))));
  if v_deploy.work_id is null then
    insert into d5o_hosted.connected_deploy_states(workspace_id,work_id,
      decision_revision,state) values(v_workspace.id,v_work.id,1,v_state);
  else
    update d5o_hosted.connected_deploy_states set
      decision_revision=decision_revision+1,state=v_state,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
  end if;
  insert into d5o_hosted.connected_deploy_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    design_revision,schedule_revision,snapshot)
  values(v_workspace.id,v_work.id,coalesce(v_deploy.decision_revision,0)+1,
    p_command_id,p_action,v_actor,v_member.id,v_design.decision_revision,
    v_schedule.decision_revision,v_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_deploy_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_handoff_configuration_command_v1(p_workspace_key text, p_action text, p_version uuid, p_route text, p_role text, p_expected_revision integer, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_tenant d5o_hosted.configuration_tenants%rowtype;
  v_active d5o_hosted.configuration_versions%rowtype;v_version d5o_hosted.configuration_versions%rowtype;
  v_receipt d5o_hosted.handoff_configuration_receipts%rowtype;
  v_prior_role text;v_current_revision integer;v_result jsonb;v_routes jsonb;
  v_fingerprint text;v_new_id uuid;v_route record;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('create-draft','save-route','publish','activate')
    or p_version is null or p_expected_revision is null or p_expected_revision<0
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or (p_action='save-route' and (p_route not in ('discoverDefine','designDeploy','deployOperate')
      or p_role not in ('admin','operations_leader','project_manager')
      ))
    or (p_action<>'save-route' and (p_route is not null or p_role is not null or p_expected_revision<>0))
  then raise exception 'invalid_handoff_configuration_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active' for share;
  if not found then raise exception 'handoff_route_admin_required' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' and role='admin' for share;
  if not found then raise exception 'handoff_route_admin_required' using errcode='42501'; end if;
  select * into v_tenant from d5o_hosted.configuration_tenants
    where workspace_id=v_workspace.id and status='active' for update;
  if not found then raise exception 'handoff_configuration_unavailable' using errcode='23514'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_action,p_version,
    p_route,p_role,p_expected_revision)::text);
  select * into v_receipt from d5o_hosted.handoff_configuration_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_active from d5o_hosted.configuration_versions
    where tenant_id=v_tenant.id and status='published'
      and effective_from<=now() and (effective_to is null or effective_to>now()) for update;
  if not found then raise exception 'handoff_configuration_unavailable' using errcode='23514'; end if;
  if p_action='create-draft' then
    if p_version<>v_active.id or exists(select 1 from d5o_hosted.configuration_versions
      where tenant_id=v_tenant.id and status in ('draft','validated')) then
      raise exception 'stale_handoff_configuration' using errcode='23505'; end if;
    insert into d5o_hosted.configuration_versions(tenant_id,version_number,status,source_sha256,
      manifest_json,source_version_id)
      values(v_tenant.id,(select max(version_number)+1 from d5o_hosted.configuration_versions
        where tenant_id=v_tenant.id),'draft',v_active.source_sha256,v_active.manifest_json,v_active.id)
      returning id into v_new_id;
    insert into d5o_hosted.configuration_work_types(configuration_version_id,work_type_key,display_name,status)
      select v_new_id,work_type_key,display_name,status from d5o_hosted.configuration_work_types
      where configuration_version_id=v_active.id;
    insert into d5o_hosted.configuration_create_rights(configuration_version_id,work_type_key,workspace_role)
      select v_new_id,work_type_key,workspace_role from d5o_hosted.configuration_create_rights
      where configuration_version_id=v_active.id;
    insert into d5o_hosted.configuration_handoff_roles(configuration_version_id,route_key,receiving_role,revision,configured_by)
      select v_new_id,route_key,receiving_role,1,v_actor from d5o_hosted.configuration_handoff_roles
      where configuration_version_id=v_active.id;
    v_result:=pg_catalog.jsonb_build_object('versionId',v_new_id,'status','draft');
  else
    select * into v_version from d5o_hosted.configuration_versions
      where id=p_version and tenant_id=v_tenant.id and source_version_id=v_active.id for update;
    if not found then raise exception 'stale_handoff_configuration' using errcode='23505'; end if;
    if p_action='save-route' then
      if v_version.status<>'draft' then raise exception 'handoff_draft_required' using errcode='23514'; end if;
      select receiving_role,revision into v_prior_role,v_current_revision
        from d5o_hosted.configuration_handoff_roles
        where configuration_version_id=v_version.id and route_key=p_route for update;
      if coalesce(v_current_revision,0)<>p_expected_revision then
        raise exception 'stale_handoff_route' using errcode='23505'; end if;
      if v_current_revision is null then
        insert into d5o_hosted.configuration_handoff_roles(configuration_version_id,route_key,receiving_role,revision,configured_by)
          values(v_version.id,p_route,p_role,1,v_actor);
      else
        update d5o_hosted.configuration_handoff_roles set receiving_role=p_role,
          revision=revision+1,configured_by=v_actor,updated_at=now()
          where configuration_version_id=v_version.id and route_key=p_route;
      end if;
      v_result:=pg_catalog.jsonb_build_object('versionId',v_version.id,'status','draft',
        'route',p_route,'role',p_role,'revision',p_expected_revision+1);
    elsif p_action='publish' then
      if v_version.status<>'draft' or (select count(*) from d5o_hosted.configuration_handoff_roles
        where configuration_version_id=v_version.id)<>3 then
        raise exception 'incomplete_handoff_routes' using errcode='23514'; end if;
      for v_route in select route_key,receiving_role from d5o_hosted.configuration_handoff_roles
        where configuration_version_id=v_version.id loop
        if not exists(select 1 from d5o_hosted.memberships m where m.workspace_id=v_workspace.id
          and m.status='active' and m.role=v_route.receiving_role) then
          raise exception 'configured_receiver_unavailable' using errcode='23514'; end if;
      end loop;
      select pg_catalog.jsonb_object_agg(route_key,receiving_role) into v_routes
        from d5o_hosted.configuration_handoff_roles where configuration_version_id=v_version.id;
      update d5o_hosted.configuration_versions set status='validated',
        source_sha256=pg_catalog.encode(extensions.digest(v_active.source_sha256||v_routes::text,'sha256'),'hex'),
        manifest_json=v_version.manifest_json||pg_catalog.jsonb_build_object('d5oPresentation',
          coalesce(v_version.manifest_json->'d5oPresentation','{}'::jsonb)||
          pg_catalog.jsonb_build_object('handoffRoles',v_routes))
        where id=v_version.id;
      v_result:=pg_catalog.jsonb_build_object('versionId',v_version.id,'status','validated');
    elsif p_action='activate' then
      if v_version.status<>'validated' then
        raise exception 'validated_handoff_configuration_required' using errcode='23514'; end if;
      update d5o_hosted.configuration_versions set status='superseded',effective_to=now()
        where id=v_active.id;
      update d5o_hosted.configuration_versions set status='published',effective_from=now()
        where id=v_version.id;
      v_result:=pg_catalog.jsonb_build_object('versionId',v_version.id,'status','published',
        'supersededVersionId',v_active.id);
    end if;
  end if;
  insert into d5o_hosted.handoff_configuration_events(workspace_id,configuration_version_id,
    action,route_key,prior_role,receiving_role,actor_user_id,membership_id,command_id)
    values(v_workspace.id,coalesce(v_new_id,v_version.id),p_action,p_route,v_prior_role,p_role,
      v_actor,v_member.id,p_command_id);
  insert into d5o_hosted.handoff_configuration_receipts(workspace_id,command_id,actor_user_id,fingerprint,result)
    values(v_workspace.id,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_identity_setup_completed_v1(p_workspace_key text, p_command_id text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_request d5o_hosted.admin_identity_requests%rowtype;
  v_email text;v_confirmed timestamptz;
begin
  if current_setting('role',true) is distinct from 'service_role'
    or length(coalesce(p_command_id,'')) not between 8 and 120 then
    raise exception 'identity_setup_denied' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select * into v_request from d5o_hosted.admin_identity_requests
    where workspace_id=v_workspace and command_id=p_command_id and action='invite'
      for update;
  select lower(email),email_confirmed_at into v_email,v_confirmed from auth.users
    where id=p_user_id;
  if v_request.command_id is null or v_email is distinct from v_request.target_email
    or v_confirmed is null or v_request.provider_user_id is distinct from p_user_id then
    raise exception 'identity_setup_denied' using errcode='42501'; end if;
  if v_request.status='setup_completed' then
    return pg_catalog.jsonb_build_object('status','setup_completed','replay',true); end if;
  if v_request.status<>'provider_accepted' then
    raise exception 'identity_setup_not_ready' using errcode='23503'; end if;
  update d5o_hosted.admin_identity_requests
    set status='setup_completed',setup_completed_at=now()
    where workspace_id=v_workspace and command_id=p_command_id;
  return pg_catalog.jsonb_build_object('status','setup_completed','replay',false);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_job_finance_command_pre_labor_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_member d5o_hosted.memberships%rowtype;
  v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.connected_job_finance_states%rowtype;
  v_bill d5o_hosted.connected_job_bills%rowtype;
  v_receipt d5o_hosted.connected_job_finance_receipts%rowtype;
  v_fingerprint text;v_basis jsonb;v_result jsonb;v_id uuid;v_closed boolean;v_amount bigint;v_billed numeric;v_paid numeric;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null or
    p_action not in ('add-cost','set-remaining','draft-bill','revise-bill',
      'submit-bill','review-bill','return-unbilled','record-billed','record-paid') or
    pg_catalog.jsonb_typeof(p_input)<>'object' or
    length(coalesce(p_command_id,'')) not between 8 and 120 or
    p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_job_finance_command' using errcode='22023'; end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace and actor_user_id=v_actor and status='active' for share;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace and l.presentation_id=p_presentation_id for update of w;
  if v_member.id is null or v_work.id is null or
    v_member.role not in ('project_manager','billing_commercial_lead') then
    raise exception 'job_finance_role_denied' using errcode='42501'; end if;
  select * into v_state from d5o_hosted.connected_job_finance_states
    where workspace_id=v_workspace and work_id=v_work.id for update;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_input,p_expected_revision)::text);
  select * into v_receipt from d5o_hosted.connected_job_finance_receipts
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  if coalesce(v_state.revision,0)<>p_expected_revision then
    raise exception 'stale_job_finance' using errcode='23505'; end if;
  select coalesce(o.state#>>'{finance,status}'='Closed',false) into v_closed
    from d5o_hosted.connected_operate_states o
    where o.workspace_id=v_workspace and o.work_id=v_work.id;
  if coalesce(v_closed,false) and p_action<>'record-paid' then
    raise exception 'finance_closed_requires_reopen' using errcode='23514'; end if;
  if p_action in ('revise-bill','submit-bill','review-bill','return-unbilled',
    'record-billed','record-paid') then
    if coalesce(p_input->>'billRevision','')!~'^\d+$' then
      raise exception 'bill_revision_required' using errcode='22023'; end if;
    select * into v_bill from d5o_hosted.connected_job_bills
      where workspace_id=v_workspace and work_id=v_work.id
        and id=(p_input->>'billId')::uuid for update;
    if v_bill.id is null then
      raise exception 'billing_record_missing' using errcode='23503'; end if;
    if v_bill.revision<>(p_input->>'billRevision')::integer then
      raise exception 'stale_bill_revision' using errcode='23505'; end if;
  end if;
  if p_action='record-paid' then
    if v_member.role<>'billing_commercial_lead' then
      raise exception 'finance_payment_role_denied' using errcode='42501'; end if;
    if v_bill.status<>'Reviewed' then
      raise exception 'payment_invoice_not_reviewed' using errcode='23514'; end if;
    if coalesce(p_input->>'amountMinor','')!~'^[0-9]+$' or
      length(p_input->>'amountMinor')>13 or
      coalesce(p_input->>'eventDate','')!~'^\d{4}-\d{2}-\d{2}$' or
      length(trim(coalesce(p_input->>'source',''))) not between 8 and 500 then
      raise exception 'invalid_payment_fact' using errcode='22023'; end if;
    v_amount:=(p_input->>'amountMinor')::bigint;
    if v_amount<=0 or v_amount>1000000000000 then
      raise exception 'invalid_payment_amount' using errcode='22023'; end if;
    -- The canonical Work and ledger rows above serialize all payment decisions.
    -- Historical invoice events, not live scope, establish this receivable.
    select coalesce(sum(amount_minor) filter(where kind='Billed'),0),
      coalesce(sum(amount_minor) filter(where kind='Paid'),0)
      into v_billed,v_paid from d5o_hosted.connected_job_cash_events
      where workspace_id=v_workspace and work_id=v_work.id and bill_id=v_bill.id;
    if v_billed<=0 or v_paid<0 or v_paid>v_billed or v_amount>v_billed-v_paid then
      raise exception 'payment_exceeds_billed' using errcode='23514'; end if;
    insert into d5o_hosted.connected_job_cash_events(workspace_id,work_id,bill_id,
      kind,amount_minor,event_date,source,recorded_by)
      values(v_workspace,v_work.id,v_bill.id,'Paid',v_amount,
        (p_input->>'eventDate')::date,trim(p_input->>'source'),v_actor)
      returning id into v_id;
    update d5o_hosted.connected_job_finance_states set revision=revision+1
      where workspace_id=v_workspace and work_id=v_work.id;
    v_result:=pg_catalog.jsonb_build_object('id',v_id,'revision',v_state.revision+1,
      'action',p_action,'billId',v_bill.id);
    insert into d5o_hosted.connected_job_finance_events(workspace_id,work_id,revision,
      command_id,actor_user_id,membership_id,action,result)
      values(v_workspace,v_work.id,v_state.revision+1,p_command_id,v_actor,v_member.id,p_action,v_result);
    insert into d5o_hosted.connected_job_finance_receipts(workspace_id,command_id,
      actor_user_id,fingerprint,result)
      values(v_workspace,p_command_id,v_actor,v_fingerprint,v_result);
    return v_result;
  end if;
  if p_action in ('revise-bill','return-unbilled') then
    insert into d5o_hosted.connected_job_bill_history(workspace_id,work_id,bill_id,
      revision,status,lines,basis,reviewed_by,review_reason,actor_user_id)
      values(v_workspace,v_work.id,v_bill.id,v_bill.revision,v_bill.status,
        v_bill.lines,v_bill.basis,v_bill.reviewed_by,v_bill.review_reason,v_actor)
      on conflict do nothing;
    if p_action='revise-bill' then
      if v_bill.prepared_by<>v_actor or v_bill.status not in ('Draft','Returned') or
        exists(select 1 from d5o_hosted.connected_job_cash_events
          where bill_id=v_bill.id) then
        raise exception 'billing_correction_denied' using errcode='42501'; end if;
      v_basis:=d5o_hosted.validate_job_bill_v2(v_workspace,v_work.id,
        p_input->'lines',v_bill.id);
      update d5o_hosted.connected_job_bills set lines=p_input->'lines',basis=v_basis,
        status='Draft',revision=revision+1,reviewed_by=null,review_reason=null
        where id=v_bill.id;
    else
      if v_member.role<>'billing_commercial_lead' or v_bill.status<>'Reviewed' or
        length(trim(coalesce(p_input->>'reason','')))<10 or
        exists(select 1 from d5o_hosted.connected_job_cash_events
          where bill_id=v_bill.id) then
        raise exception 'unbilled_return_denied' using errcode='42501'; end if;
      update d5o_hosted.connected_job_bills set status='Returned',revision=revision+1,
        reviewed_by=v_actor,review_reason=trim(p_input->>'reason') where id=v_bill.id;
    end if;
    update d5o_hosted.connected_job_finance_states set revision=revision+1
      where workspace_id=v_workspace and work_id=v_work.id;
    v_result:=pg_catalog.jsonb_build_object('id',v_bill.id,
      'revision',v_state.revision+1,'action',p_action);
    insert into d5o_hosted.connected_job_finance_events(workspace_id,work_id,revision,
      command_id,actor_user_id,membership_id,action,result)
      values(v_workspace,v_work.id,v_state.revision+1,p_command_id,v_actor,v_member.id,p_action,v_result);
    insert into d5o_hosted.connected_job_finance_receipts(workspace_id,command_id,
      actor_user_id,fingerprint,result)
      values(v_workspace,p_command_id,v_actor,v_fingerprint,v_result);
  else
    if p_action='draft-bill' then
      v_basis:=d5o_hosted.validate_job_bill_v2(v_workspace,v_work.id,p_input->'lines');
    elsif p_action='submit-bill' or
      p_action='review-bill' and p_input->>'decision'='Reviewed' or
      p_action='record-billed' then
      if v_bill.basis is null then
        raise exception 'billing_basis_missing_revise_required' using errcode='23514'; end if;
      v_basis:=d5o_hosted.validate_job_bill_v2(v_workspace,v_work.id,v_bill.lines,v_bill.id);
      if v_basis is distinct from v_bill.basis then
        raise exception 'stale_billing_source_basis' using errcode='23505'; end if;
    end if;
    v_result:=d5o_hosted.job_finance_legacy_command_v1(p_workspace_key,
      p_presentation_id,p_action,p_input,p_command_id,p_expected_revision);
    if p_action='draft-bill' then
      update d5o_hosted.connected_job_bills set basis=v_basis
        where id=(v_result->>'id')::uuid and workspace_id=v_workspace and work_id=v_work.id;
      v_bill.id:=(v_result->>'id')::uuid;
    end if;
  end if;
  if p_action in ('draft-bill','revise-bill','submit-bill','review-bill','return-unbilled') then
    select * into v_bill from d5o_hosted.connected_job_bills
      where id=coalesce(v_bill.id,(v_result->>'id')::uuid) and workspace_id=v_workspace;
    insert into d5o_hosted.connected_job_bill_history(workspace_id,work_id,bill_id,
      revision,status,lines,basis,reviewed_by,review_reason,actor_user_id)
      values(v_workspace,v_work.id,v_bill.id,v_bill.revision,v_bill.status,
        v_bill.lines,v_bill.basis,v_bill.reviewed_by,v_bill.review_reason,v_actor)
      on conflict do nothing;
  end if;
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_job_finance_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; ws uuid; w uuid;
begin
 result:=public.d5o_hosted_job_finance_command_pre_labor_v1(
  p_workspace_key,p_presentation_id,p_action,p_input,p_command_id,p_expected_revision);
 if p_action='add-cost' and p_input->>'category'='Labor' then
  select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key;
  select work_id into w from d5o_hosted.work_identity_links
   where workspace_id=ws and presentation_id=p_presentation_id;
  if exists(select 1 from d5o_hosted.labor_authorities
   where workspace_id=ws and work_id=w and status='Approved') then
   raise exception 'reviewed_labor_cost_is_field_sourced' using errcode='23514';
  end if;
 end if;
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_job_finance_read_pre_design_cost_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb; ws uuid; w uuid;
begin
 base:=public.d5o_hosted_job_finance_read_pre_labor_visibility_v1(
  p_workspace_key,p_presentation_id);
 select id into ws from d5o_hosted.workspaces
  where workspace_key=p_workspace_key and status='active';
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 return base||pg_catalog.jsonb_build_object(
  'governedLabor',exists(select 1 from d5o_hosted.labor_authorities
   where workspace_id=ws and work_id=w and status='Approved'));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_job_finance_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb; ws uuid; w uuid; actuals jsonb;
begin
 base:=public.d5o_hosted_job_finance_read_pre_design_cost_v1(p_workspace_key,p_presentation_id);
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select work_id into w from d5o_hosted.work_identity_links where workspace_id=ws and presentation_id=p_presentation_id;
 select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
  'id',c.id,'kind','Incurred','category','Design','amount_minor',c.amount_minor,
  'cost_date',c.cost_date,'package_id',null,'source',c.source_reference,
  'reconciles_id',l.ledger_cost_id) order by c.reviewed_at),'[]'::jsonb) into actuals
 from d5o_hosted.design_cost_claims c join d5o_hosted.design_cost_links l on l.commitment_id=c.commitment_id
 where c.workspace_id=ws and c.work_id=w and c.status='Reviewed'
  and not exists(select 1 from d5o_hosted.design_cost_claims n where n.root_id=c.root_id and n.supersedes_id=c.id and n.status='Reviewed');
 return base||pg_catalog.jsonb_build_object('costs',coalesce(base->'costs','[]'::jsonb)||actuals);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_link_existing_asset_v1(p_workspace_key text, p_target_presentation_id text, p_owner_presentation_id text, p_asset_id text, p_note text, p_command_id text, p_expected_source_revision bigint, p_expected_target_deploy_revision integer, p_expected_target_operate_revision integer, p_expected_owner_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_target uuid;v_owner uuid;
  v_lock uuid;v_raw d5o_hosted.prototype_states%rowtype;
  v_target_operate d5o_hosted.connected_operate_states%rowtype;
  v_owner_operate d5o_hosted.connected_operate_states%rowtype;
  v_target_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_owner_deploy_revision integer;v_receipt d5o_hosted.connected_operate_receipts%rowtype;
  v_target_record jsonb;v_owner_record jsonb;v_target_state jsonb;v_owner_state jsonb;
  v_acceptance jsonb;v_asset jsonb;v_link jsonb;v_note text:=pg_catalog.btrim(coalesce(p_note,''));
  v_now timestamptz:=now();v_fingerprint text;v_result jsonb;v_asset_uuid uuid;
  v_external_identity text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or length(coalesce(p_command_id,'')) not between 8 and 90
    or length(v_note) not between 20 and 2000
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_target_deploy_revision is null or p_expected_target_deploy_revision<1
    or p_expected_target_operate_revision is null or p_expected_target_operate_revision<1
    or p_expected_owner_operate_revision is null or p_expected_owner_operate_revision<1
    or p_target_presentation_id=p_owner_presentation_id then
    raise exception 'invalid_asset_link_command' using errcode='22023';
  end if;
  begin v_asset_uuid:=p_asset_id::uuid;
  exception when invalid_text_representation then
    raise exception 'invalid_asset_link_command' using errcode='22023'; end;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role<>'operations_leader' then
    raise exception 'asset_link_owner_authority_required' using errcode='42501'; end if;
  select work_id into v_target from d5o_hosted.work_identity_links
    where workspace_id=v_workspace.id and presentation_id=p_target_presentation_id;
  select work_id into v_owner from d5o_hosted.work_identity_links
    where workspace_id=v_workspace.id and presentation_id=p_owner_presentation_id;
  if v_target is null or v_owner is null or v_target=v_owner then
    raise exception 'asset_link_work_unavailable' using errcode='42501'; end if;
  -- Both canonical Work rows are locked in a stable order before either state.
  for v_lock in select id from d5o_hosted.work_records
      where workspace_id=v_workspace.id and id in (v_target,v_owner)
      order by id for update loop null; end loop;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_target_presentation_id,p_owner_presentation_id,p_asset_id,
    v_note,p_expected_source_revision,p_expected_target_deploy_revision,
    p_expected_target_operate_revision,p_expected_owner_operate_revision)::text);
  select * into v_receipt from d5o_hosted.connected_operate_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_target or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_target_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_target for share;
  select * into v_target_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_target for update;
  select * into v_owner_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_owner for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_target_deploy.decision_revision is distinct from p_expected_target_deploy_revision
    or v_target_operate.decision_revision is distinct from p_expected_target_operate_revision
    or v_owner_operate.decision_revision is distinct from p_expected_owner_operate_revision then
    raise exception 'stale_asset_link_basis' using errcode='23505'; end if;
  v_target_state:=v_target_operate.state;v_owner_state:=v_owner_operate.state;
  v_acceptance:=v_target_deploy.state->'workAcceptance';
  if v_target_state#>>'{source,kind}'<>'Accepted Deploy'
    or v_acceptance->>'receipt'<>'Accepted'
    or v_target_state#>>'{source,workAcceptanceId}' is distinct from v_acceptance->>'id'
    or v_target_state#>>'{source,revision}' is distinct from v_acceptance->>'revision'
    or v_target_state#>>'{source,acceptedByActorId}'=v_actor::text
    or not d5o_hosted.current_work_acceptance_scope_v1(
      v_workspace.id,v_target,v_acceptance,true) then
    raise exception 'current_received_scope_required' using errcode='23514'; end if;
  select item into v_target_record from pg_catalog.jsonb_array_elements(
    coalesce(v_raw.state_json->'records','[]'::jsonb)) item
    where item->>'id'=p_target_presentation_id;
  select item into v_owner_record from pg_catalog.jsonb_array_elements(
    coalesce(v_raw.state_json->'records','[]'::jsonb)) item
    where item->>'id'=p_owner_presentation_id;
  if v_target_record is null or v_owner_record is null
    or v_target_record#>>'{serviceSource,parentWorkId}' is not null
    or pg_catalog.lower(pg_catalog.btrim(coalesce(v_target_record->>'customer','')))
      is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(v_owner_record->>'customer','')))
    or pg_catalog.lower(pg_catalog.btrim(coalesce(v_target_record->>'site','')))
      is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(v_owner_record->>'site','')))
    or v_owner_state#>>'{support,ownerActorId}' is distinct from v_actor::text
    or v_owner_state#>>'{activation,status}'<>'Active' then
    raise exception 'supported_asset_owner_required' using errcode='42501'; end if;
  select item into v_asset from pg_catalog.jsonb_array_elements(
    coalesce(v_owner_state->'assets','[]'::jsonb)) item
    where item->>'id'=v_asset_uuid::text and item->>'status'='Supported';
  if v_asset is null or pg_catalog.lower(pg_catalog.btrim(coalesce(v_asset->>'customer','')))
      is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(v_target_record->>'customer','')))
    or pg_catalog.lower(pg_catalog.btrim(coalesce(v_asset->>'site','')))
      is distinct from pg_catalog.lower(pg_catalog.btrim(coalesce(v_target_record->>'site',''))) then
    raise exception 'supported_asset_identity_required' using errcode='23514'; end if;
  -- The prior add-asset command serializes this same tenant/identity pair.
  -- A retained duplicate cannot become an arbitrary accepted contribution.
  v_external_identity:=pg_catalog.lower(pg_catalog.btrim(coalesce(v_asset->>'externalId','')));
  if v_external_identity<>'' then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      v_workspace.id::text||':asset:'||v_external_identity,0));
    if (select count(*) from d5o_hosted.connected_operate_states o,
        lateral pg_catalog.jsonb_array_elements(coalesce(o.state->'assets','[]'::jsonb)) a
        where o.workspace_id=v_workspace.id
          and pg_catalog.lower(pg_catalog.btrim(coalesce(a->>'externalId','')))=v_external_identity) <> 1 then
      raise exception 'ambiguous_asset_identity' using errcode='23514';
    end if;
  end if;
  if exists(select 1 from pg_catalog.jsonb_array_elements(
      coalesce(v_target_state->'assetLinks','[]'::jsonb)) item
      where item->>'assetId'=v_asset_uuid::text and item->>'status'='Accepted')
    or coalesce(v_asset->'sourceWorkIds','[]'::jsonb) ? p_target_presentation_id then
    raise exception 'asset_contribution_exists' using errcode='23505'; end if;
  v_link:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),
    'status','Accepted','assetId',v_asset_uuid,'ownerWorkId',p_owner_presentation_id,
    'workAcceptanceId',v_acceptance->>'id',
    'workAcceptanceRevision',(v_acceptance->>'revision')::integer,
    'acceptedAt',v_now,'acceptedByActorId',v_actor,'reason',v_note);
  v_target_state:=pg_catalog.jsonb_set(v_target_state,'{assetLinks}',
    coalesce(v_target_state->'assetLinks','[]'::jsonb)||pg_catalog.jsonb_build_array(v_link));
  v_target_state:=v_target_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_target_operate.decision_revision+1,
    'events',coalesce(v_target_state->'events','[]'::jsonb)||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),'commandId',p_command_id,
        'fingerprint',v_fingerprint,'at',v_now,'actorId',v_actor,
        'membershipId',v_member.id,'action','link-existing-asset','detail',v_note)));
  v_asset:=pg_catalog.jsonb_set(v_asset,'{sourceWorkIds}',
    coalesce(v_asset->'sourceWorkIds','[]'::jsonb)||pg_catalog.jsonb_build_array(p_target_presentation_id));
  v_asset:=pg_catalog.jsonb_set(v_asset,'{history}',
    coalesce(v_asset->'history','[]'::jsonb)||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('at',v_now,'action','Accepted delivery contribution',
        'source',p_target_presentation_id,'actorId',v_actor,
        'workAcceptanceId',v_acceptance->>'id','reason',v_note)));
  v_owner_state:=pg_catalog.jsonb_set(v_owner_state,'{assets}',
    (select pg_catalog.jsonb_agg(case when item->>'id'=v_asset_uuid::text
      then v_asset else item end order by ordinal)
      from pg_catalog.jsonb_array_elements(v_owner_state->'assets')
        with ordinality as entries(item,ordinal)));
  v_owner_state:=v_owner_state||pg_catalog.jsonb_build_object(
    'authorityRevision',v_owner_operate.decision_revision+1,
    'events',coalesce(v_owner_state->'events','[]'::jsonb)||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'commandId',p_command_id||':owner','fingerprint',v_fingerprint,
        'at',v_now,'actorId',v_actor,'membershipId',v_member.id,
        'action','accept-delivery-contribution','detail',v_note)));
  update d5o_hosted.connected_operate_states set
    decision_revision=v_target_operate.decision_revision+1,
    state=v_target_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_target;
  update d5o_hosted.connected_operate_states set
    decision_revision=v_owner_operate.decision_revision+1,
    state=v_owner_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_owner;
  insert into d5o_hosted.connected_operate_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    deploy_revision,snapshot)
  values(v_workspace.id,v_target,v_target_operate.decision_revision+1,
    p_command_id,'link-existing-asset',v_actor,v_member.id,
    v_target_deploy.decision_revision,v_target_state);
  select coalesce(decision_revision,0) into v_owner_deploy_revision
    from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_owner;
  insert into d5o_hosted.connected_operate_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    deploy_revision,snapshot)
  values(v_workspace.id,v_owner,v_owner_operate.decision_revision+1,
    p_command_id||':owner','accept-delivery-contribution',v_actor,v_member.id,
    coalesce(v_owner_deploy_revision,0),v_owner_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_operate_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_target,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_offer_review_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_due_date text, p_reason text, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer, p_offer_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype;
  v_estimate d5o_hosted.connected_estimate_states%rowtype;
  v_offer d5o_hosted.connected_offer_states%rowtype;
  v_receipt d5o_hosted.connected_offer_receipts%rowtype;
  v_raw jsonb;v_package jsonb;v_proposal jsonb;v_review jsonb;
  v_fingerprint text;v_result jsonb;v_now timestamptz:=now();
  v_policy_id text;v_policy_version integer;v_approver text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('submit-proposal','approve-proposal','return-proposal')
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<0
    or p_offer_revision is null or p_offer_revision<1
    or length(coalesce(p_reason,''))>2000 then
    raise exception 'invalid_offer_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_action,p_due_date,trim(coalesce(p_reason,'')),
    p_expected_source_revision,p_expected_decision_revision,p_offer_revision)::text);
  select * into v_receipt from d5o_hosted.connected_offer_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_estimate from d5o_hosted.connected_estimate_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_offer from d5o_hosted.connected_offer_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or coalesce(v_offer.decision_revision,0)<>p_expected_decision_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_raw from pg_catalog.jsonb_array_elements(v_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_raw is null or v_raw->>'phaseConfigurationVersionId' is distinct from
    v_work.configuration_version_id::text or v_estimate.status is distinct from 'Approved'
    or v_estimate.estimate#>>'{review,decidedAt}' is null then
    raise exception 'approved_offer_basis_required' using errcode='23514'; end if;
  v_policy_id:=v_estimate.estimate#>>'{detailed,evaluation,policyId}';
  v_policy_version:=(v_estimate.estimate#>>'{detailed,evaluation,policyVersion}')::integer;
  v_approver:=v_estimate.estimate#>>'{detailed,policySnapshot,proposalApproverRole}';
  if v_approver is null or not exists(select 1 from d5o_hosted.connected_pricing_policies
    where workspace_id=v_workspace.id and policy_id=v_policy_id
      and version=v_policy_version and status='published') then
    raise exception 'pinned_offer_policy_unavailable' using errcode='23514'; end if;
  v_package:=case when v_offer.work_id is null then
    v_raw#>'{discovery,proposal,package}' else v_offer.proposal->'package' end;
  if p_action='submit-proposal' then
    if v_member.role not in ('admin','project_manager','operations_leader')
      or v_offer.status='Internal review'
      or coalesce(v_offer.status,v_raw#>>'{discovery,proposal,status}')<>'Draft'
      or v_package is null or (v_package->>'revision')::integer<>p_offer_revision
      or v_package->>'estimateRevision' is distinct from v_estimate.estimate_revision::text
      or coalesce(trim(v_package->>'scope'),'')=''
      or coalesce(trim(v_package->>'commercialTerms'),'')=''
      or v_package#>>'{pricingBasis,policyId}' is distinct from v_policy_id
      or (v_package#>>'{pricingBasis,policyVersion}')::integer is distinct from v_policy_version
      or (v_package#>>'{pricingBasis,priceMinor}')::numeric is distinct from
        (v_estimate.estimate#>>'{detailed,evaluation,proposedPriceMinor}')::numeric
      or (v_package#>>'{pricingBasis,includedCostMinor}')::numeric is distinct from
        (v_estimate.estimate#>>'{detailed,evaluation,includedCostMinor}')::numeric
      or v_package#>>'{pricingBasis,currency}' is distinct from
        v_estimate.estimate#>>'{detailed,input,currency}'
      or v_package#>>'{pricingBasis,solutionRevision}' is distinct from
        v_estimate.estimate#>>'{detailed,input,solutionRevision}'
      or (v_package->>'sellPrice')::numeric is distinct from
        (v_estimate.estimate->>'sellPrice')::numeric
      or (v_package#>>'{definitionSource,revision}')::integer is distinct from
        (v_estimate.estimate#>>'{definitionSource,revision}')::integer
      or p_due_date is null or p_due_date !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'offer_submission_denied' using errcode='23514'; end if;
    v_review:=pg_catalog.jsonb_build_object('revision',p_offer_revision,
      'submittedAt',v_now,'submittedBy',v_raw->>'owner',
      'submittedByActorId',v_actor,'submittedByMembershipId',v_member.id,
      'dueDate',p_due_date,'authorityRole',v_approver,
      'authorityProfileId','policy-'||v_policy_id||'-v'||v_policy_version::text,
      'grossMarginPercent',v_estimate.estimate#>>'{detailed,evaluation,marginPercent}');
    v_proposal:=coalesce(v_offer.proposal,v_raw#>'{discovery,proposal}')||
      pg_catalog.jsonb_build_object(
      'status','Internal review','review',v_review,
      'authorityRevision',coalesce(v_offer.decision_revision,0)+1);
    if v_offer.work_id is null then
      insert into d5o_hosted.connected_offer_states(workspace_id,work_id,
        offer_revision,decision_revision,estimate_revision,offer_digest,status,
        proposal,submitter)
      values(v_workspace.id,v_work.id,p_offer_revision,1,v_estimate.estimate_revision,
        pg_catalog.md5(v_package::text),'Internal review',v_proposal,v_actor);
    else
      if v_offer.status<>'Draft' or p_offer_revision<>v_offer.offer_revision then
        raise exception 'new_offer_revision_required' using errcode='23514'; end if;
      update d5o_hosted.connected_offer_states set offer_revision=p_offer_revision,
        decision_revision=decision_revision+1,estimate_revision=v_estimate.estimate_revision,
        offer_digest=pg_catalog.md5(v_package::text),status='Internal review',
        proposal=v_proposal,submitter=v_actor,reviewer=null,updated_at=v_now
        where workspace_id=v_workspace.id and work_id=v_work.id;
    end if;
  else
    if v_offer.status<>'Internal review' or v_offer.offer_revision<>p_offer_revision
      or v_estimate.estimate_revision<>v_offer.estimate_revision
      or pg_catalog.md5(v_package::text)<>v_offer.offer_digest
      or v_actor=v_offer.submitter or v_member.role<>v_approver
      or length(trim(coalesce(p_reason,'')))<10 then
      raise exception 'independent_offer_review_required' using errcode='42501'; end if;
    v_review:=v_offer.proposal->'review'||pg_catalog.jsonb_build_object(
      'decidedAt',v_now,'decisionNote',trim(p_reason),'actorId',v_actor,
      'membershipId',v_member.id);
    v_proposal:=v_offer.proposal||pg_catalog.jsonb_build_object(
      'status',case when p_action='approve-proposal' then 'Approved'
        else 'Changes requested' end,'review',v_review,
      'authorityRevision',v_offer.decision_revision+1);
    update d5o_hosted.connected_offer_states set decision_revision=decision_revision+1,
      status=case when p_action='approve-proposal' then 'Approved'
        else 'Changes requested' end,proposal=v_proposal,reviewer=v_actor,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
  end if;
  select * into v_offer from d5o_hosted.connected_offer_states
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_offer_events(workspace_id,work_id,decision_revision,
    command_id,action,actor_user_id,membership_id,offer_revision,estimate_revision,
    policy_id,policy_version,snapshot,reason)
  values(v_workspace.id,v_work.id,v_offer.decision_revision,p_command_id,p_action,
    v_actor,v_member.id,p_offer_revision,v_estimate.estimate_revision,v_policy_id,
    v_policy_version,v_offer.proposal,trim(coalesce(p_reason,'')));
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_offer_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_offer_revision_command_v1(p_workspace_key text, p_presentation_id text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer, p_offer_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype;
  v_estimate d5o_hosted.connected_estimate_states%rowtype;
  v_offer d5o_hosted.connected_offer_states%rowtype;
  v_receipt d5o_hosted.connected_offer_receipts%rowtype;
  v_raw jsonb;v_package jsonb;v_proposal jsonb;v_result jsonb;
  v_fingerprint text;v_now timestamptz:=now();
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_input is null or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<1
    or p_offer_revision is null or p_offer_revision<2
    or length(trim(coalesce(p_input->>'scope',''))) not between 10 and 4000
    or length(trim(coalesce(p_input->>'commercialTerms',''))) not between 10 and 4000
    or length(trim(coalesce(p_input->>'changeReason',''))) not between 10 and 2000
    or length(coalesce(p_input->>'assumptions',''))>4000
    or length(coalesce(p_input->>'exclusions',''))>4000 then
    raise exception 'invalid_offer_revision_input' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('admin','project_manager','operations_leader') then
    raise exception 'offer_editor_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,
    p_presentation_id,p_input,p_expected_source_revision,
    p_expected_decision_revision,p_offer_revision)::text);
  select * into v_receipt from d5o_hosted.connected_offer_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_estimate from d5o_hosted.connected_estimate_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_offer from d5o_hosted.connected_offer_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or v_offer.decision_revision is distinct from p_expected_decision_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_raw from pg_catalog.jsonb_array_elements(v_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_raw is null or v_raw->>'phaseConfigurationVersionId' is distinct from
      v_work.configuration_version_id::text
    or v_estimate.status is distinct from 'Approved'
    or v_offer.status is distinct from 'Changes requested'
    or v_offer.estimate_revision<>v_estimate.estimate_revision
    or p_offer_revision<>v_offer.offer_revision+1
    or v_actor<>v_offer.submitter then
    raise exception 'returned_offer_revision_required' using errcode='23514'; end if;
  v_package:=pg_catalog.jsonb_build_object(
    'revision',p_offer_revision,'estimateRevision',v_estimate.estimate_revision,
    'scope',trim(p_input->>'scope'),
    'assumptions',trim(coalesce(p_input->>'assumptions','')),
    'exclusions',trim(coalesce(p_input->>'exclusions','')),
    'commercialTerms',trim(p_input->>'commercialTerms'),
    'sellPrice',v_estimate.estimate->'sellPrice','preparedAt',v_now,
    'definitionSource',v_estimate.estimate->'definitionSource',
    'changeReason',trim(p_input->>'changeReason'),
    'pricingBasis',pg_catalog.jsonb_build_object(
      'policyId',v_estimate.estimate#>>'{detailed,evaluation,policyId}',
      'policyVersion',v_estimate.estimate#>'{detailed,evaluation,policyVersion}',
      'solutionRevision',v_estimate.estimate#>'{detailed,input,solutionRevision}',
      'currency',v_estimate.estimate#>>'{detailed,input,currency}',
      'includedCostMinor',v_estimate.estimate#>'{detailed,evaluation,includedCostMinor}',
      'priceMinor',v_estimate.estimate#>'{detailed,evaluation,proposedPriceMinor}'));
  v_proposal:=(v_offer.proposal-'review')||pg_catalog.jsonb_build_object(
    'status','Draft','package',v_package,
    'packageHistory',coalesce(v_offer.proposal->'packageHistory','[]'::jsonb)||
      pg_catalog.jsonb_build_array(v_package),
    'authorityRevision',v_offer.decision_revision+1);
  update d5o_hosted.connected_offer_states set offer_revision=p_offer_revision,
    decision_revision=decision_revision+1,offer_digest=pg_catalog.md5(v_package::text),
    status='Draft',proposal=v_proposal,reviewer=null,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_offer_events(workspace_id,work_id,decision_revision,
    command_id,action,actor_user_id,membership_id,offer_revision,estimate_revision,
    policy_id,policy_version,snapshot,reason)
  values(v_workspace.id,v_work.id,v_offer.decision_revision+1,p_command_id,
    'save-proposal-revision',v_actor,v_member.id,p_offer_revision,
    v_estimate.estimate_revision,
    v_estimate.estimate#>>'{detailed,evaluation,policyId}',
    (v_estimate.estimate#>>'{detailed,evaluation,policyVersion}')::integer,
    v_proposal,trim(p_input->>'changeReason'));
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_offer_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_operate_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_deploy_revision integer, p_expected_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace_id uuid;v_work_id uuid;
  v_role text;v_external_id text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'operate_membership_required' using errcode='42501';
  end if;
  if p_action='add-asset' then
    select w.id,l.work_id,m.role into v_workspace_id,v_work_id,v_role
      from d5o_hosted.workspaces w
      join d5o_hosted.work_identity_links l on l.workspace_id=w.id
      join d5o_hosted.memberships m on m.workspace_id=w.id
      where w.workspace_key=p_workspace_key and w.status='active'
        and l.presentation_id=p_presentation_id
        and m.actor_user_id=v_actor and m.status='active';
    if v_workspace_id is null or v_role not in ('project_manager','operations_leader') then
      raise exception 'asset_authority_required' using errcode='42501';
    end if;
    -- Let the existing command validate an identical replay (or reject a
    -- conflicting replay) before considering the asset now present.
    if exists(select 1 from d5o_hosted.connected_operate_receipts
      where workspace_id=v_workspace_id and command_id=p_command_id) then
      return d5o_hosted.d5o_hosted_operate_command_prior_v1(
        p_workspace_key,p_presentation_id,p_action,p_input,p_command_id,
        p_expected_source_revision,p_expected_deploy_revision,p_expected_operate_revision);
    end if;
    v_external_id:=pg_catalog.lower(pg_catalog.btrim(coalesce(p_input->>'externalId','')));
    if v_external_id<>'' then
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        v_workspace_id::text||':asset:'||v_external_id,0));
      if exists(select 1 from d5o_hosted.connected_operate_states o,
          lateral pg_catalog.jsonb_array_elements(
            coalesce(o.state->'assets','[]'::jsonb)) a
        where o.workspace_id=v_workspace_id
          and pg_catalog.lower(pg_catalog.btrim(coalesce(a->>'externalId','')))=v_external_id)
      then raise exception 'asset_identity_conflict' using errcode='23505'; end if;
    end if;
  end if;
  return d5o_hosted.d5o_hosted_operate_command_prior_v1(
    p_workspace_key,p_presentation_id,p_action,p_input,p_command_id,
    p_expected_source_revision,p_expected_deploy_revision,p_expected_operate_revision);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_pricing_policy_command_v1(p_workspace_key text, p_action text, p_policy jsonb, p_policy_id text, p_policy_version integer, p_command_id text, p_expected_work_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.prototype_states%rowtype;
  v_prior d5o_hosted.connected_pricing_policies%rowtype;
  v_receipt d5o_hosted.connected_pricing_receipts%rowtype;
  v_policy jsonb;v_rate jsonb;v_fingerprint text;v_result jsonb;v_now timestamptz:=now();
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-draft','publish','activate')
    or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_expected_work_revision is null or p_expected_work_revision<1
    or p_policy_id is null or length(trim(p_policy_id)) not between 1 and 120
    or p_policy_version is null or p_policy_version<1 then
    raise exception 'invalid_pricing_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role<>'admin' then
    raise exception 'pricing_config_forbidden' using errcode='42501'; end if;
  select * into v_work from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_action,
    p_policy,p_policy_id,p_policy_version,p_expected_work_revision)::text);
  select * into v_receipt from d5o_hosted.connected_pricing_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  if v_work.revision is distinct from p_expected_work_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select * into v_prior from d5o_hosted.connected_pricing_policies
    where workspace_id=v_workspace.id and policy_id=p_policy_id
      and version=p_policy_version for update;
  if p_action='save-draft' then
    if p_policy is null or pg_catalog.jsonb_typeof(p_policy)<>'object'
      or p_policy->>'id' is distinct from p_policy_id
      or p_policy->>'version' is distinct from p_policy_version::text
      or p_policy->>'workspace' is distinct from p_workspace_key
      or p_policy->>'status'<>'draft' or v_prior.status in ('published','superseded')
      or length(trim(coalesce(p_policy->>'name','')))=0
      or p_policy->>'currency' !~ '^[A-Z]{3}$'
      or p_policy->>'effectiveFrom' !~ '^\d{4}-\d{2}-\d{2}$'
      or coalesce(p_policy->>'method','') not in ('target-margin','markup','fixed-price')
      or coalesce(p_policy->>'solutionApproverRole','operations_leader')
        not in ('admin','operations_leader')
      or coalesce(p_policy->>'pricingApproverRole','') not in ('admin','operations_leader')
      or coalesce(p_policy->>'proposalApproverRole','') not in ('admin','operations_leader')
      or pg_catalog.jsonb_typeof(p_policy->'rates')<>'array' then
      raise exception 'invalid_pricing_draft' using errcode='22023'; end if;
    insert into d5o_hosted.connected_pricing_policies(
      workspace_id,policy_id,version,status,payload)
    values(v_workspace.id,p_policy_id,p_policy_version,'draft',p_policy)
    on conflict(workspace_id,policy_id,version) do update set
      payload=excluded.payload,updated_at=v_now;
  elsif p_action='publish' then
    if v_prior.status<>'draft' or p_policy is not null
      or pg_catalog.jsonb_array_length(coalesce(v_prior.payload->'rates','[]'::jsonb))=0
      or (v_prior.payload->>'targetMarginPercent') is null
      or (v_prior.payload->>'floorMarginPercent') is null
      or (v_prior.payload->>'targetMarginPercent')::numeric not between 0 and 95
      or (v_prior.payload->>'floorMarginPercent')::numeric not between 0 and
        (v_prior.payload->>'targetMarginPercent')::numeric then
      raise exception 'invalid_pricing_publication' using errcode='23514'; end if;
    for v_rate in select value from pg_catalog.jsonb_array_elements(v_prior.payload->'rates') loop
      if length(trim(coalesce(v_rate->>'id','')))=0
        or length(trim(coalesce(v_rate->>'unit','')))=0
        or length(trim(coalesce(v_rate->>'source','')))=0
        or coalesce(v_rate->>'category','') not in
          ('labor','material','equipment','subcontract','travel','mobilization',
            'setup','recurring','other')
        or coalesce(v_rate->>'amount','') !~ (case
          when v_prior.payload->>'currency'='JPY' then '^([0-9]+)$'
          else '^([0-9]+)(\.[0-9]{1,2})?$' end)
        or (v_rate->>'amount')::numeric<0 then
        raise exception 'invalid_pricing_rate' using errcode='23514'; end if;
    end loop;
    v_policy:=v_prior.payload||pg_catalog.jsonb_build_object('status','published',
      'publishedAt',v_now,'publishedBy',v_actor);
    update d5o_hosted.connected_pricing_policies set status='published',payload=v_policy,
      updated_at=v_now where workspace_id=v_workspace.id
        and policy_id=p_policy_id and version=p_policy_version;
  else
    if v_prior.status<>'published' or p_policy is not null
      or (v_prior.payload->>'effectiveFrom')::date>v_now::date
      or (v_prior.payload->>'effectiveTo' is not null and
        (v_prior.payload->>'effectiveTo')::date<v_now::date) then
      raise exception 'pricing_activation_denied' using errcode='23514'; end if;
    insert into d5o_hosted.connected_pricing_active(workspace_id,policy_id,version)
      values(v_workspace.id,p_policy_id,p_policy_version)
      on conflict(workspace_id) do update set policy_id=excluded.policy_id,
        version=excluded.version;
  end if;
  insert into d5o_hosted.connected_pricing_events(workspace_id,command_id,action,
    policy_id,version,actor_user_id,membership_id)
  values(v_workspace.id,p_command_id,p_action,p_policy_id,p_policy_version,v_actor,v_member.id);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_pricing_receipts(workspace_id,command_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_prototype_read_internal_v1(p_workspace_key text, p_state_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_state d5o_hosted.prototype_states%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;v_projected jsonb;
begin
  if auth.uid() is null or p_workspace_key is null
    or p_state_key not in ('work','catalog','schedule') then
    raise exception 'prototype_scope_forbidden' using errcode='42501'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.actor_user_id=auth.uid() and m.status='active' and m.role<>'field_worker';
  if v_workspace is null then raise exception 'prototype_scope_forbidden' using errcode='42501'; end if;
  if p_state_key='schedule' then
    select * into v_state from d5o_hosted.prototype_states
      where workspace_id=v_workspace and state_key='schedule';
    select * into v_schedule from d5o_hosted.connected_schedule_states
      where workspace_id=v_workspace;
    return pg_catalog.jsonb_build_object(
      'revision',coalesce(v_schedule.decision_revision,v_state.revision,0),
      'state',d5o_hosted.connected_schedule_projection_v1(
        v_workspace,p_workspace_key,v_state.state_json)); end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace and state_key=p_state_key;
  if not found then return pg_catalog.jsonb_build_object('revision',0,'state',null); end if;
  v_projected:=case when p_state_key='work' then
    d5o_hosted.connected_operate_projection_v1(v_workspace,
      d5o_hosted.connected_deploy_projection_v1(v_workspace,
        d5o_hosted.connected_design_projection_v1(v_workspace,
          d5o_hosted.connected_define_projection_v1(v_workspace,
            d5o_hosted.connected_service_projection_v1(
              v_workspace,v_state.state_json,p_state_key)))))
    else d5o_hosted.connected_service_projection_v1(
      v_workspace,v_state.state_json,p_state_key) end;
  return pg_catalog.jsonb_build_object('revision',v_state.revision,'state',
    d5o_hosted.connected_package_projection_v1(v_workspace,v_projected,p_state_key));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_prototype_read_v1(p_workspace_key text, p_state_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'prototype_scope_forbidden' using errcode='42501'; end if;
  v_result:=public.d5o_hosted_prototype_read_internal_v1(
    p_workspace_key,p_state_key);
  if p_state_key<>'work' then return v_result; end if;
  return d5o_hosted.redact_support_document_read_v1(
    p_workspace_key,v_actor,v_result);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_prototype_save_internal_v1(p_workspace_key text, p_state_key text, p_expected_revision bigint, p_state jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_membership d5o_hosted.memberships%rowtype;
  v_prior d5o_hosted.prototype_states%rowtype;v_state jsonb;v_input jsonb;
  v_projection jsonb;v_define_projection jsonb;v_revision bigint;v_field text;
begin
  if auth.uid() is null or p_state_key is distinct from 'work'
    or p_expected_revision is null or p_expected_revision<1 or p_state is null
    or pg_catalog.jsonb_typeof(p_state)<>'object'
    or p_state->>'workspace' is distinct from p_workspace_key
    or p_state->>'schemaVersion' is distinct from '1'
    or pg_catalog.octet_length(p_state::text)>2000000 then
    raise exception 'invalid_prototype_state' using errcode='22023'; end if;
  select m.* into v_membership from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.actor_user_id=auth.uid() and m.status='active';
  v_workspace:=v_membership.workspace_id;
  if v_workspace is null or v_membership.role not in
    ('admin','operations_leader','project_manager','field_supervisor') then
    raise exception 'prototype_write_forbidden' using errcode='42501'; end if;
  select * into v_prior from d5o_hosted.prototype_states
    where workspace_id=v_workspace and state_key='work' for update;
  if not found or v_prior.revision<>p_expected_revision then
    raise exception 'stale_prototype_state' using errcode='23505'; end if;
  v_define_projection:=d5o_hosted.connected_define_projection_v1(v_workspace,v_prior.state_json);
  v_projection:=d5o_hosted.connected_package_projection_v1(v_workspace,
    d5o_hosted.connected_operate_projection_v1(v_workspace,
      d5o_hosted.connected_deploy_projection_v1(v_workspace,
        d5o_hosted.connected_design_projection_v1(v_workspace,v_define_projection))),'work');
  v_input:=d5o_hosted.connected_service_draft_rebase_v1(v_workspace,p_state);
  foreach v_field in array array['pricingPolicies','activePricingPolicy','pricingPolicyHistory'] loop
    if p_state->v_field is distinct from v_projection->v_field then
      raise exception 'typed_policy_command_required' using errcode='42501'; end if;
    v_input:=v_input-v_field;
    if v_prior.state_json ? v_field then
      v_input:=v_input||pg_catalog.jsonb_build_object(v_field,v_prior.state_json->v_field);
    end if;
  end loop;
  v_input:=d5o_hosted.connected_operate_draft_rebase_v1(v_workspace,v_prior.state_json,v_input);
  v_input:=d5o_hosted.connected_deploy_draft_rebase_v1(v_workspace,v_prior.state_json,v_input);
  v_input:=d5o_hosted.connected_design_draft_rebase_cached_v1(v_workspace,v_prior.state_json,v_input,v_define_projection);
  v_input:=d5o_hosted.connected_package_draft_rebase_cached_v1(v_workspace,v_prior.state_json,v_input,v_define_projection);
  v_input:=d5o_hosted.connected_handoff_draft_rebase_cached_v1(v_workspace,v_prior.state_json,v_input,v_define_projection);
  v_input:=d5o_hosted.connected_offer_draft_rebase_cached_v1(v_workspace,v_prior.state_json,v_input,v_define_projection);
  v_input:=d5o_hosted.connected_estimate_draft_rebase_cached_v1(v_workspace,v_prior.state_json,v_input,v_define_projection);
  v_input:=d5o_hosted.connected_solution_draft_rebase_cached_v1(v_workspace,v_prior.state_json,v_input,v_define_projection);
  v_state:=d5o_hosted.connected_draft_snapshot_v1(v_workspace,v_prior.state_json,v_input,v_prior.revision+1);
  update d5o_hosted.prototype_states set revision=revision+1,state_json=v_state,
    updated_by=auth.uid(),updated_at=now()
    where workspace_id=v_workspace and state_key='work' returning revision into v_revision;
  insert into d5o_hosted.prototype_state_revisions(
    workspace_id,state_key,revision,state_json,actor_user_id,membership_id)
  values(v_workspace,'work',v_revision,v_state,auth.uid(),v_membership.id);
  return pg_catalog.jsonb_build_object('revision',v_revision,'state',
    d5o_hosted.connected_package_projection_v1(v_workspace,
      d5o_hosted.connected_operate_projection_v1(v_workspace,
        d5o_hosted.connected_deploy_projection_v1(v_workspace,
          d5o_hosted.connected_design_projection_v1(v_workspace,
            d5o_hosted.connected_define_projection_v1(v_workspace,
              d5o_hosted.connected_service_projection_v1(
                v_workspace,v_state,'work'))))),'work'));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_prototype_save_v1(p_workspace_key text, p_state_key text, p_expected_revision bigint, p_state jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or auth.uid() is null then
    raise exception 'prototype_scope_forbidden' using errcode='42501'; end if;
  v_result:=public.d5o_hosted_prototype_save_internal_v1(
    p_workspace_key,p_state_key,p_expected_revision,p_state);
  if p_state_key='work' then
    return d5o_hosted.redact_support_document_read_v1(
      p_workspace_key,auth.uid(),v_result); end if;
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_publish_initial_configuration_v1(p_workspace_key text, p_command_id text, p_manifest jsonb, p_work_types jsonb, p_create_roles jsonb, p_routes jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;
  v_receipt d5o_hosted.initial_configuration_receipts%rowtype;
  v_tenant uuid := gen_random_uuid();
  v_version uuid := gen_random_uuid();
  v_digest text;
  v_fingerprint text;
  v_result jsonb;
  v_type jsonb;
  v_contract_type jsonb;
  v_role text;
  v_route text;
  v_type_key text;
  v_type_label text;
  v_supported text[];
  v_phase_keys jsonb;
begin
  if current_setting('role', true) <> 'authenticated' or v_actor is null then
    raise exception 'configuration_admin_required' using errcode='42501';
  end if;
  if length(coalesce(p_command_id,'')) not between 8 and 120
    or length(trim(coalesce(p_reason,''))) not between 8 and 240
    or pg_catalog.jsonb_typeof(p_manifest) <> 'object'
    or pg_catalog.jsonb_typeof(p_work_types) <> 'array'
    or pg_catalog.jsonb_typeof(p_create_roles) <> 'array'
    or pg_catalog.jsonb_typeof(p_routes) <> 'object'
  then raise exception 'invalid_initial_configuration' using errcode='22023'; end if;

  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active' for update;
  if not found then raise exception 'configuration_admin_required' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor
      and status='active' and role='admin' for share;
  if not found then raise exception 'configuration_admin_required' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_manifest,p_work_types,p_create_roles,p_routes,trim(p_reason))::text);
  select * into v_receipt from d5o_hosted.initial_configuration_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;

  if exists(select 1 from d5o_hosted.configuration_tenants
      where workspace_id=v_workspace.id)
    or exists(select 1 from d5o_hosted.work_records
      where workspace_id=v_workspace.id) then
    raise exception 'initial_configuration_already_exists' using errcode='23505';
  end if;
  v_supported:=case p_workspace_key
    when 'rybex' then array['technical-delivery','lifecycle-service']
    when 'rotork' then array['modernization-service','lifecycle-service']
    else null end;
  if v_supported is null or pg_catalog.jsonb_array_length(p_work_types)<>2
    or pg_catalog.jsonb_typeof(p_manifest->'workTypes')<>'array'
    or p_manifest->'workTypes'<>p_work_types
    or p_manifest#>>'{d5oPresentation,schemaVersion}'<>'1'
    or p_manifest#>>'{d5oPresentation,phaseContract,schemaVersion}'<>'1'
    or pg_catalog.jsonb_typeof(p_manifest#>'{d5oPresentation,phaseContract,workTypes}')<>'array'
    or pg_catalog.jsonb_array_length(p_manifest#>'{d5oPresentation,phaseContract,workTypes}')<>2
    or p_manifest#>'{d5oPresentation,handoffRoles}'<>p_routes
    or (select count(*) from pg_catalog.jsonb_object_keys(p_routes))<>3
    or pg_catalog.jsonb_array_length(p_create_roles)=0
  then raise exception 'invalid_initial_configuration' using errcode='22023'; end if;

  for v_type in select value from pg_catalog.jsonb_array_elements(p_work_types) loop
    v_type_key:=v_type->>'key'; v_type_label:=v_type->>'label';
    if v_type_key is null or v_type_key<>all(v_supported)
      or length(trim(coalesce(v_type_label,''))) not between 2 and 120 then
      raise exception 'unsupported_work_type' using errcode='22023'; end if;
    select value into v_contract_type from pg_catalog.jsonb_array_elements(
      p_manifest#>'{d5oPresentation,phaseContract,workTypes}')
      where value->>'workTypeKey'=v_type_key;
    if not found or v_contract_type->>'workTypeLabel'<>v_type_label
      or v_contract_type->>'version'<>'prototype-v2'
      or pg_catalog.jsonb_typeof(v_contract_type->'phases')<>'array' then
      raise exception 'invalid_phase_contract' using errcode='22023'; end if;
    select pg_catalog.jsonb_agg(phase->'key' order by ordinal)
      into v_phase_keys from pg_catalog.jsonb_array_elements(v_contract_type->'phases')
        with ordinality as stages(phase,ordinal);
    if v_phase_keys<>'["discover","define","develop","design","deploy","operate"]'::jsonb then
      raise exception 'invalid_phase_contract' using errcode='22023'; end if;
  end loop;
  if (select count(distinct value->>'key') from pg_catalog.jsonb_array_elements(p_work_types))<>2
    or (select count(distinct value->>'workTypeKey') from pg_catalog.jsonb_array_elements(
      p_manifest#>'{d5oPresentation,phaseContract,workTypes}'))<>2 then
    raise exception 'invalid_initial_configuration' using errcode='22023'; end if;

  for v_role in select value #>> '{}' from pg_catalog.jsonb_array_elements(p_create_roles) loop
    if v_role not in ('admin','project_manager','business_development_lead',
      'operations_leader','billing_commercial_lead','field_supervisor',
      'closeout_lead','executive') then
      raise exception 'invalid_create_role' using errcode='22023'; end if;
  end loop;
  if (select count(distinct value #>> '{}') from pg_catalog.jsonb_array_elements(p_create_roles))
     <>pg_catalog.jsonb_array_length(p_create_roles) then
    raise exception 'invalid_create_role' using errcode='22023'; end if;

  foreach v_route in array array['discoverDefine','designDeploy','deployOperate'] loop
    v_role:=p_routes->>v_route;
    if v_role not in ('admin','project_manager','operations_leader')
      or not exists(select 1 from d5o_hosted.memberships m
        where m.workspace_id=v_workspace.id and m.status='active' and m.role=v_role) then
      raise exception 'configured_receiver_unavailable' using errcode='23514'; end if;
  end loop;
  if exists(select 1 from pg_catalog.jsonb_object_keys(p_routes) as route(key)
    where route.key not in ('discoverDefine','designDeploy','deployOperate')) then
    raise exception 'invalid_initial_configuration' using errcode='22023'; end if;

  v_digest:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_manifest::text,'UTF8')),'hex');
  insert into d5o_hosted.configuration_tenants(id,workspace_id,status)
    values(v_tenant,v_workspace.id,'active');
  insert into d5o_hosted.configuration_versions(
    id,tenant_id,version_number,status,source_sha256,manifest_json)
    values(v_version,v_tenant,1,'draft',v_digest,p_manifest);
  insert into d5o_hosted.configuration_work_types(
    configuration_version_id,work_type_key,display_name,status)
    select v_version,value->>'key',value->>'label','active'
      from pg_catalog.jsonb_array_elements(p_work_types);
  insert into d5o_hosted.configuration_create_rights(
    configuration_version_id,work_type_key,workspace_role)
    select v_version,t.value->>'key',r.value #>> '{}'
      from pg_catalog.jsonb_array_elements(p_work_types) t(value)
      cross join pg_catalog.jsonb_array_elements(p_create_roles) r(value);
  insert into d5o_hosted.configuration_handoff_roles(
    configuration_version_id,route_key,receiving_role,revision,configured_by)
    select v_version,key,value #>> '{}',1,v_actor
      from pg_catalog.jsonb_each(p_routes);
  update d5o_hosted.configuration_versions
    set status='published',effective_from=now() where id=v_version;
  v_result:=pg_catalog.jsonb_build_object('workspaceId',v_workspace.id,
    'tenantId',v_tenant,'versionId',v_version,'version',1,'status','published',
    'manifestSha256',v_digest);
  insert into d5o_hosted.initial_configuration_events(
    workspace_id,tenant_id,version_id,actor_user_id,membership_id,
    command_id,reason,manifest_sha256)
    values(v_workspace.id,v_tenant,v_version,v_actor,v_member.id,
      p_command_id,trim(p_reason),v_digest);
  insert into d5o_hosted.initial_configuration_receipts(
    workspace_id,command_id,actor_user_id,fingerprint,result)
    values(v_workspace.id,p_command_id,v_actor,v_fingerprint,v_result);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_pursuit_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_intent jsonb, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype; v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype; v_control d5o_hosted.connected_pursuit_states%rowtype;
  v_receipt d5o_hosted.connected_pursuit_receipts%rowtype; v_raw jsonb;
  v_projection jsonb; v_fingerprint text; v_source_digest text;
  v_next text; v_fit text; v_reason text; v_result jsonb; v_receiving_role text;
  v_now timestamptz:=now();
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-intake','submit','decide','submit-handoff','respond-handoff')
    or p_intent is null or pg_catalog.jsonb_typeof(p_intent)<>'object'
    or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<0 then
    raise exception 'invalid_pursuit_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,
    p_action,p_intent,p_expected_source_revision,p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_pursuit_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_control from d5o_hosted.connected_pursuit_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or coalesce(v_control.decision_revision,0)<>p_expected_decision_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_raw from pg_catalog.jsonb_array_elements(v_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_raw is null or v_raw->>'phaseConfigurationVersionId' is distinct from v_work.configuration_version_id::text
    then raise exception 'source_identity_changed' using errcode='42501'; end if;
  v_source_digest:=d5o_hosted.connected_pursuit_source_digest_v1(v_raw);
  if v_control.work_id is not null and v_control.source_digest<>v_source_digest
    and p_action<>'save-intake' then
    raise exception 'pursuit_source_changed' using errcode='23505'; end if;
  v_projection:=coalesce(v_control.projection,v_raw#>'{discovery,pursuitControl}');
  if v_projection is null then raise exception 'pursuit_draft_unavailable' using errcode='22023'; end if;
  v_reason:=trim(coalesce(p_intent->>'reason',''));
  if p_action='save-intake' then
    if v_member.role not in ('admin','project_manager','business_development_lead')
      or coalesce(v_control.status,'draft') not in ('draft','returned','held')
      or p_intent-'requester'-'intendedOutcome'-'roughValue'-'currency'-'requiredDate'-'knownRisk'
        -'customer'-'site'-'owner'-'need'<>'{}'::jsonb
      or p_intent->>'customer' is distinct from v_raw->>'customer'
      or p_intent->>'site' is distinct from v_raw->>'site'
      or p_intent->>'owner' is distinct from v_raw->>'owner'
      or p_intent->>'need' is distinct from v_raw#>>'{discovery,need}'
      or length(trim(coalesce(p_intent->>'requester','')))=0
      or length(trim(coalesce(p_intent->>'intendedOutcome','')))=0
      or (p_intent->>'roughValue') !~ '^[0-9]+(\.[0-9]{1,2})?$'
      or (p_intent->>'roughValue')::numeric<=0
      or (p_intent->>'currency') !~ '^[A-Z]{3}$'
      or (p_intent->>'requiredDate') !~ '^\d{4}-\d{2}-\d{2}$'
      or length(trim(coalesce(p_intent->>'knownRisk','')))=0 then
      raise exception 'invalid_pursuit_intake' using errcode='22023'; end if;
    v_projection:=v_projection||pg_catalog.jsonb_build_object('status','draft',
      'requester',trim(p_intent->>'requester'),
      'intendedOutcome',trim(p_intent->>'intendedOutcome'),
      'roughValue',p_intent->>'roughValue','currency',p_intent->>'currency',
      'requiredDate',p_intent->>'requiredDate','knownRisk',trim(p_intent->>'knownRisk'));
    v_next:='Submit intake for pursuit decision'; v_fit:='Unassessed';
  elsif p_action='submit' then
    if v_member.role not in ('admin','project_manager','business_development_lead')
      or coalesce(v_control.status,'draft')<>'draft'
      or length(trim(coalesce(v_projection->>'requester','')))=0
      or length(trim(coalesce(v_projection->>'intendedOutcome','')))=0
      or length(trim(coalesce(v_projection->>'roughValue','')))=0
      or length(trim(coalesce(v_projection->>'requiredDate','')))=0
      or length(trim(coalesce(v_projection->>'knownRisk','')))=0
      or length(trim(coalesce(v_raw->>'customer','')))=0
      or length(trim(coalesce(v_raw->>'site','')))=0
      or length(trim(coalesce(v_raw->>'owner','')))=0
      or length(trim(coalesce(v_raw#>>'{discovery,need}','')))=0 then
      raise exception 'pursuit_intake_incomplete' using errcode='23514'; end if;
    v_projection:=v_projection||pg_catalog.jsonb_build_object('status','submitted',
      'submission',pg_catalog.jsonb_build_object('revision',p_expected_decision_revision+1,
        'at',v_now,'actor',v_actor::text,'actorId',v_actor));
    v_control.status:='submitted'; v_control.submitter:=v_actor;
    v_next:='Qualification authority: decide pursuit';
    v_fit:='Unassessed';
  elsif p_action='decide' then
    if v_member.role not in ('admin','billing_commercial_lead','business_development_lead')
      or v_control.status<>'submitted' or v_actor=v_control.submitter
      or p_intent-'outcome'-'reason'<>'{}'::jsonb
      or p_intent->>'outcome' not in ('qualified','returned','held','declined')
      or length(v_reason)<10 then
      raise exception 'pursuit_decision_denied' using errcode='42501'; end if;
    if p_intent->>'outcome'='qualified' and v_raw#>'{discovery,crm}' is not null
      and (v_raw#>>'{discovery,crm,disqualifier}'<>'None'
        or (v_raw#>'{discovery,crm,assessmentHistory}'->-1)->>'recommendation'
          not in ('Pursue','Pursue with conditions')) then
      raise exception 'pursuit_assessment_unfavorable' using errcode='23514'; end if;
    v_control.status:=p_intent->>'outcome'; v_control.decider:=v_actor;
    v_projection:=v_projection||pg_catalog.jsonb_build_object('status',v_control.status,
      'decision',pg_catalog.jsonb_build_object('revision',v_projection#>'{submission,revision}',
        'outcome',v_control.status,'reason',v_reason,'at',v_now,'actor',v_actor::text,
        'actorId',v_actor,'policyVersion',v_work.configuration_version_id));
    v_fit:=case when v_control.status='qualified' then 'Qualified'
      when v_control.status='declined' then 'Disqualified' else 'Unassessed' end;
    v_next:=case when v_control.status='qualified' then
      'Request bounded pursuit spend or send Define handoff' else
      'Correct intake or retain the pursuit decision' end;
  elsif p_action='submit-handoff' then
    if v_member.role not in ('admin','project_manager','business_development_lead')
      or v_control.status<>'qualified' or v_projection#>>'{handoff,status}' in ('submitted','accepted')
      or p_intent-'brief'<>'{}'::jsonb
      or length(trim(coalesce(p_intent->>'brief','')))<20 then
      raise exception 'pursuit_handoff_denied' using errcode='42501'; end if;
    v_receiving_role:=d5o_hosted.configured_handoff_role_v1(v_work.configuration_version_id,'discoverDefine');
    if not exists(select 1 from d5o_hosted.memberships m
      where m.workspace_id=v_workspace.id and m.status='active'
        and m.role=v_receiving_role and m.actor_user_id<>v_actor) then
      raise exception 'configured_receiver_unavailable' using errcode='23514'; end if;
    v_projection:=pg_catalog.jsonb_set(v_projection,'{handoff}',
      pg_catalog.jsonb_build_object('status','submitted',
        'receiver','Configured '||v_receiving_role||' queue',
        'receiverRole',v_receiving_role,'brief',trim(p_intent->>'brief'),
        'revision',coalesce((v_projection#>>'{handoff,revision}')::integer,0)+1,
        'actor',v_actor::text,'actorId',v_actor,'at',v_now));
    v_control.handoff_sender:=v_actor; v_next:='Define receiver: accept or return the pursuit brief';
    v_fit:='Qualified';
  elsif p_action='respond-handoff' then
    if v_member.role not in ('admin','operations_leader','project_manager')
      or v_control.status<>'qualified' or v_projection#>>'{handoff,status}'<>'submitted'
      or v_actor=v_control.handoff_sender
      or (case when v_projection#>>'{handoff,receiverRole}' is not null
          then v_member.role is distinct from v_projection#>>'{handoff,receiverRole}'
          else v_actor::text is distinct from v_projection#>>'{handoff,receiverActorId}' end)
      or p_intent-'outcome'-'reason'<>'{}'::jsonb
      or p_intent->>'outcome' not in ('accepted','returned')
      or length(v_reason)<10 then
      raise exception 'pursuit_receipt_denied' using errcode='42501'; end if;
    v_projection:=pg_catalog.jsonb_set(v_projection,'{handoff}',
      (v_projection->'handoff')||pg_catalog.jsonb_build_object(
        'status',p_intent->>'outcome','reason',v_reason,'actor',v_actor::text,
        'actorId',v_actor,'at',v_now));
    v_control.handoff_receiver:=v_actor;
    v_next:=case when p_intent->>'outcome'='accepted' then
      'Define owner: establish scope baseline' else
      'Pursuit owner: correct Define brief' end;
    v_fit:='Qualified';
  end if;
  v_projection:=v_projection||pg_catalog.jsonb_build_object(
    'revision',p_expected_decision_revision+1,
    'history',coalesce(v_projection->'history','[]'::jsonb)||
      pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'revision',p_expected_decision_revision+1,'action',p_action,
        'actor',v_actor::text,'at',v_now,'note',coalesce(nullif(v_reason,''),p_action))));
  if v_control.work_id is null then
    insert into d5o_hosted.connected_pursuit_states(workspace_id,work_id,source_digest,
      decision_revision,status,projection,fit,next_action)
    values(v_workspace.id,v_work.id,v_source_digest,1,'draft',v_projection,v_fit,v_next);
  else
    update d5o_hosted.connected_pursuit_states set source_digest=v_source_digest,
      decision_revision=decision_revision+1,
      status=v_projection->>'status',submitter=coalesce(v_control.submitter,submitter),
      decider=coalesce(v_control.decider,decider),
      handoff_sender=coalesce(v_control.handoff_sender,handoff_sender),
      handoff_receiver=coalesce(v_control.handoff_receiver,handoff_receiver),
      projection=v_projection,fit=v_fit,next_action=v_next,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  end if;
  insert into d5o_hosted.connected_pursuit_events(workspace_id,work_id,decision_revision,
    command_id,action,actor_user_id,membership_id,authority_role,configuration_version_id,
    source_digest,reason)
  values(v_workspace.id,v_work.id,p_expected_decision_revision+1,p_command_id,p_action,
    v_actor,v_member.id,v_member.role,v_work.configuration_version_id,v_source_digest,v_reason);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_pursuit_receipts(workspace_id,command_id,work_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_register_customer_decision_evidence_v1(p_workspace_key text, p_presentation_id text, p_evidence_id uuid, p_purpose text, p_scope_id text, p_scope_revision integer, p_basis jsonb, p_checksum_sha256 text, p_filename text, p_uploader_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace d5o_hosted.workspaces%rowtype;
  v_work d5o_hosted.work_records%rowtype;
  v_member d5o_hosted.memberships%rowtype;
  v_object storage.objects%rowtype;v_path text;v_source jsonb;
begin
  if current_setting('role',true)<>'service_role' or p_evidence_id is null
    or p_purpose not in ('package-acceptance','work-acceptance','service-authorization',
      'field-change-authorization','service-billing-terms')
    or p_scope_revision<1 or pg_catalog.jsonb_typeof(p_basis)<>'object'
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$' or p_uploader_id is null then
    raise exception 'invalid_customer_evidence_registration' using errcode='42501'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=p_uploader_id and status='active';
  if v_work.id is null or v_member.id is null or v_member.role not in
    ('project_manager','operations_leader','field_supervisor') then
    raise exception 'customer_evidence_scope_denied' using errcode='42501'; end if;
  if p_purpose='service-billing-terms' then
    if v_member.role<>'project_manager' then
      raise exception 'service_billing_terms_role_required' using errcode='42501'; end if;
    v_source:=d5o_hosted.service_billing_terms_source_v1(
      v_workspace.id,v_work.id,p_scope_id);
    if v_source->>'eligibleForFinanceReview'<>'true'
      or p_scope_revision is distinct from (v_source->>'estimateRevision')::integer
      or p_basis is distinct from v_source then
      raise exception 'stale_service_billing_terms_source' using errcode='23505'; end if;
  end if;
  v_path:=p_workspace_key||'/'||pg_catalog.encode(
    extensions.digest(p_presentation_id,'sha256'),'hex')||'/customer-decisions/'||p_evidence_id::text;
  select * into v_object from storage.objects
    where bucket_id='d5o-deploy-evidence' and name=v_path;
  if v_object.id is null or v_object.metadata->>'mimetype'<>'application/pdf'
    or (v_object.metadata->>'size')::bigint not between 1 and 10485760 then
    raise exception 'customer_evidence_object_missing' using errcode='23514'; end if;
  insert into d5o_hosted.customer_decision_evidence(
    id,workspace_id,work_id,presentation_id,purpose,scope_id,scope_revision,basis,
    object_path,storage_object_id,storage_updated_at,checksum_sha256,size_bytes,
    mime_type,filename,uploaded_by)
  values(p_evidence_id,v_workspace.id,v_work.id,p_presentation_id,p_purpose,
    p_scope_id,p_scope_revision,p_basis,v_path,v_object.id,v_object.updated_at,
    p_checksum_sha256,(v_object.metadata->>'size')::bigint,'application/pdf',
    left(p_filename,200),p_uploader_id);
  return pg_catalog.jsonb_build_object('evidenceId',p_evidence_id,
    'checksumSha256',p_checksum_sha256,'sizeBytes',(v_object.metadata->>'size')::bigint);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_register_design_cost_evidence_v1(p_workspace_key text, p_presentation_id text, p_claim_id uuid, p_evidence_id uuid, p_checksum_sha256 text, p_filename text, p_uploader_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ws uuid; w d5o_hosted.work_records%rowtype;
 c d5o_hosted.design_cost_claims%rowtype; m d5o_hosted.memberships%rowtype;
 obj storage.objects%rowtype; path text;
begin
 if current_setting('role',true)<>'service_role' or p_evidence_id is null or p_claim_id is null
  or p_checksum_sha256 !~ '^[0-9a-f]{64}$' or length(coalesce(p_filename,'')) not between 1 and 200
  then raise exception 'invalid_design_cost_evidence' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select r.* into w from d5o_hosted.work_records r join d5o_hosted.work_identity_links l
  on l.workspace_id=r.workspace_id and l.work_id=r.id
  where r.workspace_id=ws and l.presentation_id=p_presentation_id for share of r;
 select * into m from d5o_hosted.memberships where workspace_id=ws and actor_user_id=p_uploader_id
  and status='active' and role='project_manager' for share;
 select * into c from d5o_hosted.design_cost_claims where id=p_claim_id and workspace_id=ws
  and work_id=w.id for update;
 if w.id is null or m.id is null or w.created_by<>p_uploader_id or c.id is null
  or c.status<>'Prepared' or c.prepared_by<>p_uploader_id
  then raise exception 'design_cost_evidence_scope_denied' using errcode='42501'; end if;
 path:=p_workspace_key||'/'||pg_catalog.encode(extensions.digest(p_presentation_id,'sha256'),'hex')
  ||'/design-cost/'||p_evidence_id::text;
 select * into obj from storage.objects where bucket_id='d5o-deploy-evidence' and name=path;
 if obj.id is null or obj.metadata->>'mimetype'<>'application/pdf'
  or (obj.metadata->>'size')::bigint not between 1 and 10485760
  then raise exception 'design_cost_evidence_object_missing' using errcode='23514'; end if;
 insert into d5o_hosted.design_cost_evidence(id,workspace_id,work_id,claim_id,object_path,
  storage_object_id,storage_updated_at,checksum_sha256,size_bytes,filename,uploaded_by)
 values(p_evidence_id,ws,w.id,p_claim_id,path,obj.id,obj.updated_at,p_checksum_sha256,
  (obj.metadata->>'size')::bigint,p_filename,p_uploader_id);
 return pg_catalog.jsonb_build_object('evidenceId',p_evidence_id,'claimId',p_claim_id,
  'checksumSha256',p_checksum_sha256,'filename',p_filename);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_register_design_document_evidence_v1(p_workspace_key text, p_presentation_id text, p_document_id text, p_document_revision integer, p_evidence_id uuid, p_checksum_sha256 text, p_filename text, p_uploader_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace d5o_hosted.workspaces%rowtype;
  v_work d5o_hosted.work_records%rowtype;
  v_member d5o_hosted.memberships%rowtype;
  v_design d5o_hosted.connected_design_states%rowtype;
  v_document jsonb;v_object storage.objects%rowtype;v_path text;
begin
  if current_setting('role',true)<>'service_role' or p_evidence_id is null
    or p_document_revision<1 or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
    or p_uploader_id is null or length(coalesce(p_filename,'')) not between 1 and 200 then
    raise exception 'invalid_design_document_registration' using errcode='42501'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id for share of w;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=p_uploader_id
      and status='active' and role in ('project_manager','admin') for share;
  select * into v_design from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select d into v_document from pg_catalog.jsonb_array_elements(
    coalesce(v_design.state->'documents','[]'::jsonb)) d
    where d->>'id'=p_document_id and (d->>'revision')::integer=p_document_revision;
  if v_work.id is null or v_member.id is null or v_document is null
    or v_document->>'status'<>'Draft' then
    raise exception 'design_document_upload_denied' using errcode='42501'; end if;
  v_path:=p_workspace_key||'/'||pg_catalog.encode(
    extensions.digest(p_presentation_id,'sha256'),'hex')||'/design-documents/'||p_evidence_id::text;
  select * into v_object from storage.objects
    where bucket_id='d5o-deploy-evidence' and name=v_path;
  if v_object.id is null or v_object.metadata->>'mimetype'<>'application/pdf'
    or (v_object.metadata->>'size')::bigint not between 1 and 10485760 then
    raise exception 'design_document_object_missing' using errcode='23514'; end if;
  insert into d5o_hosted.design_document_evidence(id,workspace_id,work_id,
    presentation_id,document_id,document_revision,object_path,storage_object_id,
    storage_updated_at,checksum_sha256,size_bytes,filename,uploaded_by)
  values(p_evidence_id,v_workspace.id,v_work.id,p_presentation_id,p_document_id,
    p_document_revision,v_path,v_object.id,v_object.updated_at,p_checksum_sha256,
    (v_object.metadata->>'size')::bigint,left(p_filename,200),p_uploader_id);
  return pg_catalog.jsonb_build_object('evidenceId',p_evidence_id,
    'checksumSha256',p_checksum_sha256,'filename',left(p_filename,200));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_register_support_document_internal_v1(p_workspace_key text, p_presentation_id text, p_evidence_id uuid, p_turnover_id text, p_kind text, p_basis jsonb, p_checksum_sha256 text, p_filename text, p_uploader_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace d5o_hosted.workspaces%rowtype;
  v_work d5o_hosted.work_records%rowtype;v_member d5o_hosted.memberships%rowtype;
  v_object storage.objects%rowtype;v_path text;v_exact jsonb;
begin
  if current_setting('role',true)<>'service_role' or p_evidence_id is null
    or p_kind not in ('as-built','inspection') or p_uploader_id is null
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_support_document' using errcode='42501'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
      and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=p_uploader_id
      and status='active';
  if v_work.id is null or v_member.role not in ('project_manager','field_supervisor') then
    raise exception 'support_document_supplier_required' using errcode='42501'; end if;
  v_exact:=d5o_hosted.support_document_basis_v1(
    v_workspace.id,v_work.id,p_turnover_id,p_kind);
  if v_exact is null or p_basis is distinct from v_exact then
    raise exception 'stale_support_document_basis' using errcode='23505'; end if;
  v_path:=p_workspace_key||'/'||pg_catalog.encode(
    extensions.digest(p_presentation_id,'sha256'),'hex')
    ||'/customer-decisions/'||p_evidence_id::text;
  select * into v_object from storage.objects
    where bucket_id='d5o-deploy-evidence' and name=v_path;
  if v_object.id is null or v_object.metadata->>'mimetype'<>'application/pdf'
    or (v_object.metadata->>'size')::bigint not between 1 and 10485760 then
    raise exception 'support_document_object_missing' using errcode='23514'; end if;
  insert into d5o_hosted.customer_decision_evidence(
    id,workspace_id,work_id,presentation_id,purpose,scope_id,scope_revision,
    basis,object_path,storage_object_id,storage_updated_at,checksum_sha256,
    size_bytes,mime_type,filename,uploaded_by)
  values(p_evidence_id,v_workspace.id,v_work.id,p_presentation_id,
    'support-'||p_kind,p_turnover_id,(v_exact->>'turnoverRevision')::integer,
    v_exact,v_path,v_object.id,v_object.updated_at,p_checksum_sha256,
    (v_object.metadata->>'size')::bigint,'application/pdf',
    left(p_filename,200),p_uploader_id);
  return pg_catalog.jsonb_build_object('evidenceId',p_evidence_id,
    'checksumSha256',p_checksum_sha256,'basis',v_exact);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_rom_design_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_work uuid;
  v_source bigint;v_state d5o_hosted.connected_rom_design_states%rowtype;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not exists(select 1 from d5o_hosted.memberships where workspace_id=v_workspace
    and actor_user_id=v_actor and status='active'
    and role in ('admin','project_manager','operations_leader','billing_commercial_lead')) then
    raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select work_id into v_work from d5o_hosted.work_identity_links
    where workspace_id=v_workspace and presentation_id=p_presentation_id;
  if v_work is null then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  select revision into v_source from d5o_hosted.prototype_states
    where workspace_id=v_workspace and state_key='work';
  select * into v_state from d5o_hosted.connected_rom_design_states
    where workspace_id=v_workspace and work_id=v_work;
  return pg_catalog.jsonb_build_object('sourceRevision',v_source,
    'decisionRevision',coalesce(v_state.decision_revision,0),
    'status',v_state.status,'estimateRevision',v_state.estimate_revision,
    'offerRevision',v_state.offer_revision,'acknowledgment',v_state.acknowledgment,
    'authorization',v_state.design_authorization,'reconciliation',v_state.reconciliation);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_server_connected_read_v1(p_workspace_key text, p_state_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_state d5o_hosted.prototype_states%rowtype;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;v_projected jsonb;
begin
  if current_setting('role',true)<>'service_role'
    or p_state_key not in ('work','schedule') then
    raise exception 'server_connected_read_forbidden' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if v_workspace is null then raise exception 'workspace_unavailable' using errcode='42501'; end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace and state_key=p_state_key;
  if p_state_key='schedule' then
    select * into v_schedule from d5o_hosted.connected_schedule_states
      where workspace_id=v_workspace;
    return pg_catalog.jsonb_build_object('revision',
      coalesce(v_schedule.decision_revision,v_state.revision,0),
      'state',d5o_hosted.connected_schedule_projection_v1(
        v_workspace,p_workspace_key,v_state.state_json)); end if;
  if v_state.workspace_id is null then
    -- Empty is truthful only when this workspace has no canonical Work.
    if exists(select 1 from d5o_hosted.work_records where workspace_id=v_workspace) then
      raise exception 'work_projection_unavailable' using errcode='23514'; end if;
    return pg_catalog.jsonb_build_object('revision',0,'state',
      pg_catalog.jsonb_build_object('schemaVersion',1,'workspace',p_workspace_key,
        'revision',0,'records','[]'::jsonb)); end if;
  v_projected:=d5o_hosted.connected_operate_projection_v1(v_workspace,
    d5o_hosted.connected_deploy_projection_v1(v_workspace,
      d5o_hosted.connected_design_projection_v1(v_workspace,
        d5o_hosted.connected_define_projection_v1(v_workspace,
          d5o_hosted.connected_service_projection_v1(
            v_workspace,v_state.state_json,'work')))));
  return pg_catalog.jsonb_build_object('revision',v_state.revision,'state',
    d5o_hosted.connected_package_projection_v1(v_workspace,v_projected,'work'));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_server_read_v1(p_workspace_key text, p_state_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_state d5o_hosted.prototype_states%rowtype;
begin
  if p_state_key not in ('work', 'catalog', 'schedule') then raise exception 'invalid_state' using errcode = '22023'; end if;
  select s.* into v_state from d5o_hosted.prototype_states s
  join d5o_hosted.workspaces w on w.id = s.workspace_id
  where w.workspace_key = p_workspace_key and w.status = 'active' and s.state_key = p_state_key;
  if not found then return pg_catalog.jsonb_build_object('revision', 0, 'state', null); end if;
  return pg_catalog.jsonb_build_object('revision', v_state.revision, 'state', v_state.state_json);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid(); v_workspace uuid; v_member d5o_hosted.memberships%rowtype;
  v_row record; v_request jsonb; v_estimate jsonb; v_auth jsonb; v_fin jsonb;
  v_cycle text; v_kind text; v_status text; v_blocker text; v_role text;
  v_child text; v_actionable boolean; v_ownership text; v_items jsonb:='[]'::jsonb;
  v_customer text;
  v_inv d5o_hosted.connected_service_invoices%rowtype;v_paid bigint;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'membership_required' using errcode='42501'; end if;
  select id into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace and actor_user_id=v_actor and status='active';
  if v_member.id is null then raise exception 'queue_scope_denied' using errcode='42501'; end if;
  if v_member.role not in ('project_manager','billing_commercial_lead',
    'operations_leader','admin','executive') then return v_items; end if;
  for v_row in
    select l.work_id,l.presentation_id,w.title,o.state
    from d5o_hosted.connected_operate_states o
    join d5o_hosted.work_identity_links l on l.workspace_id=o.workspace_id
      and l.work_id=o.work_id and l.parent_work_id is null
    join d5o_hosted.work_records w on w.workspace_id=o.workspace_id and w.id=o.work_id
    where o.workspace_id=v_workspace
    order by w.created_at desc,l.presentation_id
  loop
    select item->>'customer' into v_customer
      from d5o_hosted.prototype_states p,
        lateral pg_catalog.jsonb_array_elements(coalesce(p.state_json->'records','[]'::jsonb)) item
      where p.workspace_id=v_workspace and p.state_key='work'
        and item->>'id'=v_row.presentation_id limit 1;
    for v_request in select item from pg_catalog.jsonb_array_elements(
      coalesce(v_row.state->'requests','[]'::jsonb)) item
    loop
      if coalesce(v_request->>'coverage','') not in ('Chargeable','Partially covered') then continue; end if;
      v_cycle:=coalesce(v_request->>'reopenedAt',v_request->>'reportedAt');
      v_estimate:=v_request->'serviceEstimate';
      v_auth:=v_request->'serviceAuthorization';
      v_fin:=null; v_inv:=null; v_child:=null; v_kind:=null; v_status:=null; v_blocker:=null;
      v_role:=null;
      select job->>'workId' into v_child
        from pg_catalog.jsonb_array_elements(coalesce(v_row.state->'jobs','[]'::jsonb)) job
        where job->>'requestId'=v_request->>'id'
          and job->>'requestCycleAt'=v_cycle
          and coalesce(v_request->'currentCycleJobIds','[]'::jsonb) ? (job->>'id')
        order by job->>'createdAt' desc limit 1;
      if v_estimate is null or v_estimate->>'requestCycleAt' is distinct from v_cycle
        or v_estimate->>'status' not in ('Approved','Pricing review') then
        v_kind:='Service pricing';v_role:='project_manager';
        v_status:=coalesce(v_estimate->>'status','Missing');
        v_blocker:='Prepare and submit a current-cycle estimate for uncovered scope.';
      elsif v_estimate->>'status'='Pricing review' then
        v_kind:='Service pricing review';
        v_role:=v_estimate#>>'{policySnapshot,pricingApproverRole}';
        v_status:='Pricing review';
        v_blocker:='Independent review of the submitted estimate revision is pending.';
      elsif v_auth is null or v_auth->>'estimateRevision' is distinct from v_estimate->>'revision'
        or v_auth->>'amountMinor' is distinct from v_estimate#>>'{evaluation,proposedPriceMinor}'
        or v_auth->>'currency' is distinct from v_estimate#>>'{evaluation,currency}' then
        v_kind:='Customer service authorization';v_role:='operations_leader';
        v_status:='Awaiting customer source';
        v_blocker:='Record the retained customer decision for this approved estimate.';
      elsif v_request->>'coverage'='Partially covered' and v_request->>'status'='Closed' then
        v_fin:=public.d5o_hosted_service_finance_read_v1(
          p_workspace_key,v_row.presentation_id,v_request->>'id');
        select * into v_inv from d5o_hosted.connected_service_invoices
          where workspace_id=v_workspace and parent_work_id=v_row.work_id
            and request_id=v_request->>'id'
          order by prepared_at desc limit 1;
        if v_inv.status='Issued' then
          select coalesce(sum(amount_minor),0) into v_paid
            from d5o_hosted.connected_service_invoice_payments
            where workspace_id=v_workspace and invoice_id=v_inv.invoice_id;
          if v_paid<v_inv.amount_minor then
            v_kind:='Service payment recording';v_role:='billing_commercial_lead';
            v_status:='Issued · receivable';
            v_blocker:='Retained invoice '||v_inv.invoice_number||' has '||
              ((v_inv.amount_minor-v_paid)::numeric/100)::text||' USD outstanding. Record only a sourced payment fact.';
          else
            v_kind:='Service invoice paid';v_role:='billing_commercial_lead';
            v_status:='Paid in full';v_blocker:='Invoice and payment events remain available for review.';
          end if;
        elsif v_inv.status='Reviewed' then
          v_kind:='Service invoice issuance';v_role:='billing_commercial_lead';
          v_status:='Reviewed';
          v_blocker:='Record issuance only while the exact reviewed Finance and service sources remain current.';
        elsif v_inv.status='In review' then
          v_kind:='Service invoice review';v_role:='billing_commercial_lead';
          v_status:='In review';
          v_blocker:='Independently review the submitted USD fixed-fee invoice and its retained terms.';
        elsif v_inv.status in ('Draft','Returned') then
          v_kind:='Service invoice preparation';v_role:='project_manager';
          v_status:=v_inv.status;
          v_blocker:='Submit or correct the exact uncovered-scope draft for Finance review.';
        elsif v_fin->'basis'->>'eligibleForFinanceReview' is distinct from 'true' then
          v_kind:='Service Finance source';v_role:='project_manager';
          v_status:='Source changed';
          v_blocker:='Reconcile the current service execution and commercial source before preparation.';
        elsif (v_fin->>'decisionCurrent')='true'
          and v_fin#>>'{decision,status}'='Ready for billing' then
          v_kind:='Service invoice drafting';v_role:='project_manager';
          v_status:='Ready for billing';
          v_blocker:='Draft one invoice for the exact approved USD uncovered fixed fee.';
        elsif (v_fin->>'decisionCurrent')='true'
          and v_fin#>>'{decision,status}'='Prepared' then
          v_kind:='Service Finance review';v_role:='billing_commercial_lead';
          v_status:='Prepared';
          v_blocker:='Review the exact prepared basis independently; retained billing terms are required for Ready.';
        elsif (v_fin->>'decisionCurrent')='true'
          and v_fin#>>'{decision,status}'='Hold' then
          v_kind:='Service terms follow-up';v_role:='project_manager';
          v_status:='Finance Hold';
          v_blocker:=coalesce(v_fin#>>'{decision,review_reason}',
            'Finance requires a current retained billing-terms source.');
        else
          v_kind:=case when v_fin->>'decision' is null then 'Service Finance preparation'
            else 'Service Finance reassessment' end;
          v_role:='project_manager';
          v_status:=case when v_fin->>'decision' is null then 'Not prepared'
            else 'Historical decision' end;
          v_blocker:=case when v_fin->>'decision' is null then
            'Prepare the current service basis for independent Finance review.'
            else 'The source changed; prepare a new basis before Finance can rely on the historical decision.' end;
        end if;
      end if;
      if v_kind is null then continue; end if;
      v_actionable:=v_member.role=v_role and not (
        v_kind='Service Finance review' and
        v_fin#>>'{decision,prepared_by}'=v_actor::text)
        and v_kind<>'Service invoice paid' and
        not (v_kind='Service invoice review' and v_inv.prepared_by=v_actor) and
        not (v_kind='Service pricing review' and
          v_estimate->>'submittedByActorId'=v_actor::text);
      v_ownership:=case when v_kind='Service invoice paid' then 'Information only'
        when v_actionable then 'Available to your role'
        else 'Waiting on another role' end;
      v_items:=v_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'kind',v_kind,'workId',v_row.presentation_id,'workTitle',v_row.title,
        'requestId',v_request->>'id','requestTitle',v_request->>'title',
        'customer',v_customer,'childWorkId',v_child,
        'requestCycleAt',v_cycle,'coverage',v_request->>'coverage',
        'requestStatus',v_request->>'status','revision',
          coalesce(v_inv.revision,(v_fin->>'revision')::integer,(v_estimate->>'revision')::integer,0),
        'status',v_status,'blocker',v_blocker,'responsibleRole',v_role,
        'actionable',v_actionable,'ownership',v_ownership,
        'dueDate',case when v_inv.status='Issued' then v_inv.due_date::text else null end,'serviceResolutionDueAt',v_request->>'resolutionDueAt',
        'panel',case when v_kind like 'Service Finance%' or v_kind in
          ('Service terms follow-up','Service invoice drafting','Service invoice preparation',
            'Service invoice review','Service invoice issuance','Service payment recording','Service invoice paid') then 'finance' else 'pricing' end));
    end loop;
  end loop;
  return v_items;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_basis_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_work_revision bigint, p_expected_operate_revision integer, p_expected_decision_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_service d5o_hosted.connected_service_work%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_parent d5o_hosted.connected_operate_states%rowtype;
  v_handoff d5o_hosted.connected_design_handoffs%rowtype;
  v_receipt d5o_hosted.connected_design_handoff_receipts%rowtype;
  v_source jsonb;v_basis jsonb;v_brief jsonb;v_next jsonb;
  v_digest text;v_fingerprint text;v_result jsonb;
  v_revision integer;v_now timestamptz:=now();v_reason text:=trim(coalesce(p_input->>'reason',''));
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-service-basis','revise-service-basis',
      'submit-service-basis','accept-service-basis','return-service-basis')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_work_revision is null or p_expected_work_revision<1
    or p_expected_operate_revision is null or p_expected_operate_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<0 then
    raise exception 'invalid_service_basis_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('project_manager','operations_leader') then
    raise exception 'service_basis_role_denied' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
      and l.relation_kind='service_visit' for update of w;
  if not found then raise exception 'service_work_unavailable' using errcode='23503'; end if;
  select * into v_service from d5o_hosted.connected_service_work
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  if not found then raise exception 'service_source_unavailable' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_presentation_id,p_action,p_input,p_expected_work_revision,
    p_expected_operate_revision,p_expected_decision_revision)::text);
  select * into v_receipt from d5o_hosted.connected_design_handoff_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_parent from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_service.parent_work_id for share;
  select * into v_handoff from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_work_revision
    or v_parent.decision_revision is distinct from p_expected_operate_revision
    or coalesce(v_handoff.decision_revision,0)<>p_expected_decision_revision
    or v_handoff.work_id is not null and v_handoff.source_kind<>'service' then
    raise exception 'stale_service_basis' using errcode='23505'; end if;
  v_source:=d5o_hosted.current_service_source_v1(v_workspace.id,v_work.id);
  v_digest:=pg_catalog.md5(v_source::text);
  if p_action in ('save-service-basis','revise-service-basis') then
    if v_member.role<>'project_manager'
      or p_action='revise-service-basis' and v_handoff.status<>'accepted'
      or p_action='save-service-basis' and v_handoff.status not in ('draft','returned')
      or exists(select 1 from d5o_hosted.connected_design_states d,
        lateral pg_catalog.jsonb_array_elements(coalesce(d.state->'releases','[]'::jsonb)) r
        where d.workspace_id=v_workspace.id and d.work_id=v_work.id
          and r->>'status' in ('Awaiting receipt','Accepted')) then
      raise exception 'service_basis_revision_denied' using errcode='23514'; end if;
    if length(trim(coalesce(p_input->>'scope','')))<20
      or length(trim(coalesce(p_input->>'completionCriteria','')))<15
      or length(trim(coalesce(p_input->>'verification','')))<15
      or length(trim(coalesce(p_input->>'coverageRationale','')))<20
      or length(trim(coalesce(p_input->>'safety','')))<10
      or length(trim(coalesce(p_input->>'access','')))<10
      or length(trim(coalesce(p_input->>'resources','')))<10
      or p_input->>'serviceCategory' is distinct from
        v_source#>>'{request,serviceCategory}' then
      raise exception 'service_scope_and_coverage_basis_required' using errcode='23514'; end if;
    if v_source#>>'{request,coverage}'='Partially covered' and
      (length(trim(coalesce(p_input->>'coveredScope','')))<20
        or length(trim(coalesce(p_input->>'uncoveredScope','')))<20
        or p_input->>'uncoveredScope' is distinct from v_source#>>'{pricing,uncoveredScope}') then
      raise exception 'partial_scope_price_boundary_required' using errcode='23514'; end if;
    v_revision:=coalesce(v_handoff.revision,0)+1;
    v_brief:=pg_catalog.jsonb_build_object(
      'sourceKind','service','source',v_source,'scope',trim(p_input->>'scope'),
      'exclusions',trim(coalesce(p_input->>'exclusions','')),
      'completionCriteria',trim(p_input->>'completionCriteria'),
      'verification',trim(p_input->>'verification'),
      'coverageRationale',trim(p_input->>'coverageRationale'),
      'coveredScope',trim(coalesce(p_input->>'coveredScope','')),
      'uncoveredScope',trim(coalesce(p_input->>'uncoveredScope','')),
      'safety',trim(p_input->>'safety'),'access',trim(p_input->>'access'),
      'resources',trim(p_input->>'resources'),
      'serviceCategory',p_input->>'serviceCategory',
      'configurationVersionId',v_work.configuration_version_id);
    v_next:=pg_catalog.jsonb_build_object('id',gen_random_uuid(),
      'revision',v_revision,'status','draft','sourceKind','service',
      'brief',v_brief,'submittedBy',v_actor,'authorityRevision',
      p_expected_decision_revision+1,'updatedAt',v_now);
    if v_handoff.work_id is null then
      insert into d5o_hosted.connected_design_handoffs(
        workspace_id,work_id,revision,decision_revision,status,source_digest,
        handoff,submitted_by,source_kind)
      values(v_workspace.id,v_work.id,v_revision,1,'draft',v_digest,v_next,v_actor,'service');
    else
      update d5o_hosted.connected_design_handoffs set
        revision=v_revision,decision_revision=decision_revision+1,status='draft',
        source_digest=v_digest,handoff=v_next,submitted_by=v_actor,
        received_by=null,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
    end if;
  elsif p_action='submit-service-basis' then
    if v_member.role<>'project_manager' or v_handoff.status<>'draft'
      or v_handoff.submitted_by<>v_actor or v_handoff.source_digest<>v_digest
      or length(v_reason)<15 then
      raise exception 'service_basis_submission_denied' using errcode='23514'; end if;
    v_revision:=v_handoff.revision;
    v_next:=v_handoff.handoff||pg_catalog.jsonb_build_object(
      'status','submitted','submittedAt',v_now,
      'authorityRevision',v_handoff.decision_revision+1);
    update d5o_hosted.connected_design_handoffs set status='submitted',
      decision_revision=decision_revision+1,handoff=v_next,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
  else
    if v_member.role<>'operations_leader' or v_handoff.status<>'submitted'
      or v_handoff.submitted_by=v_actor or v_handoff.source_digest<>v_digest
      or length(v_reason)<20 then
      raise exception 'independent_current_service_review_required' using errcode='42501'; end if;
    v_revision:=v_handoff.revision;
    v_next:=v_handoff.handoff||pg_catalog.jsonb_build_object(
      'status',case when p_action='accept-service-basis' then 'accepted' else 'returned' end,
      'receivedAt',v_now,'receivedByActorId',v_actor,
      'reviewReason',v_reason,'authorityRevision',v_handoff.decision_revision+1);
    update d5o_hosted.connected_design_handoffs set
      status=v_next->>'status',decision_revision=decision_revision+1,
      handoff=v_next,received_by=v_actor,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
  end if;
  insert into d5o_hosted.connected_design_handoff_events(workspace_id,work_id,
    decision_revision,command_id,action,actor_user_id,membership_id,
    handoff_revision,source_digest,snapshot,reason)
  values(v_workspace.id,v_work.id,p_expected_decision_revision+1,p_command_id,
    p_action,v_actor,v_member.id,v_revision,v_digest,v_next,v_reason);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_design_handoff_receipts(workspace_id,command_id,
    work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_billing_terms_command_v1(p_workspace_key text, p_parent_presentation_id text, p_request_id text, p_input jsonb, p_command_id text, p_expected_work_revision bigint, p_expected_operate_revision integer, p_expected_design_revision integer, p_expected_deploy_revision integer, p_expected_terms_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_parent d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_current d5o_hosted.connected_service_billing_terms%rowtype;
  v_receipt d5o_hosted.connected_service_billing_terms_receipts%rowtype;
  v_source jsonb;v_digest text;v_fingerprint text;v_doc jsonb;
  v_terms jsonb;v_result jsonb;v_revision integer;v_child uuid;
  v_evidence_id text:=trim(coalesce(p_input->>'evidenceId',''));
  v_basis text:=trim(coalesce(p_input->>'billingBasis',''));
  v_trigger text:=trim(coalesce(p_input->>'billingTrigger',''));
  v_payment text:=trim(coalesce(p_input->>'paymentTerms',''));
  v_party text:=trim(coalesce(p_input->>'customerParty',''));
  v_organization text:=trim(coalesce(p_input->>'customerOrganization',''));
  v_role text:=trim(coalesce(p_input->>'customerRole',''));
  v_authority text:=trim(coalesce(p_input->>'authorityBasis',''));
  v_note text:=trim(coalesce(p_input->>'note',''));
  v_now timestamptz:=now();
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_work_revision is null or p_expected_operate_revision is null
    or p_expected_design_revision is null or p_expected_deploy_revision is null
    or p_expected_terms_revision is null
    or length(coalesce(p_expected_source_digest,''))<>32
    or v_evidence_id !~ '^[0-9a-f-]{36}$'
    or p_input - 'evidenceId' - 'billingBasis' - 'billingTrigger'
      - 'paymentTerms' - 'customerParty' - 'customerOrganization'
      - 'customerRole' - 'authorityBasis' - 'note' <> '{}'::jsonb
    or v_basis<>'Fixed fee for approved uncovered scope'
    or v_trigger<>'Accepted service scope'
    or v_payment !~ '^(Net [1-9][0-9]{0,2} days from invoice|Due on receipt of invoice)$'
    or length(v_party)<5 or length(v_organization)<5 or length(v_role)<5
    or length(v_authority)<15 or length(v_note)<15 then
    raise exception 'invalid_service_billing_terms_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor
      and status='active' for share;
  if not found or v_member.role<>'project_manager' then
    raise exception 'service_billing_terms_role_required' using errcode='42501'; end if;
  select w.* into v_parent from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
      and l.work_id=w.id and l.parent_work_id is null
    where w.workspace_id=v_workspace.id and l.presentation_id=p_parent_presentation_id
    for update of w;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_parent_presentation_id,p_request_id,p_input,p_expected_work_revision,
    p_expected_operate_revision,p_expected_design_revision,p_expected_deploy_revision,
    p_expected_terms_revision,p_expected_source_digest)::text);
  select * into v_receipt from d5o_hosted.connected_service_billing_terms_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.parent_work_id<>v_parent.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_parent.id for share;
  select s.work_id into v_child from d5o_hosted.connected_service_work s
    where s.workspace_id=v_workspace.id and s.parent_work_id=v_parent.id
      and s.request_id=p_request_id for share;
  perform 1 from d5o_hosted.work_records
    where workspace_id=v_workspace.id and id=v_child for share;
  perform 1 from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_child for share;
  perform 1 from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_child for share;
  perform 1 from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_child for share;
  select * into v_current from d5o_hosted.connected_service_billing_terms
    where workspace_id=v_workspace.id and parent_work_id=v_parent.id
      and request_id=p_request_id for update;
  v_source:=d5o_hosted.service_billing_terms_source_v1(
    v_workspace.id,v_parent.id,p_request_id);
  v_digest:=pg_catalog.md5(v_source::text);
  if v_raw.revision is distinct from p_expected_work_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision
    or (v_source->>'designRevision')::integer is distinct from p_expected_design_revision
    or (v_source->>'deployRevision')::integer is distinct from p_expected_deploy_revision
    or coalesce(v_current.revision,0)<>p_expected_terms_revision
    or v_digest<>p_expected_source_digest then
    raise exception 'stale_service_billing_terms_source' using errcode='23505'; end if;
  if v_source->>'eligibleForFinanceReview'<>'true'
    or v_source->>'coverage'<>'Partially covered'
    or v_source->>'uncoveredAmountMinor' !~ '^[0-9]+$'
    or (v_source->>'uncoveredAmountMinor')::bigint<1
    or v_source->>'currency'<>'USD' then
    raise exception 'unsupported_service_billing_terms_basis' using errcode='23514'; end if;
  v_doc:=d5o_hosted.require_customer_decision_evidence_v1(
    v_workspace.id,v_parent.id,v_evidence_id,'service-billing-terms',
    p_request_id,(v_source->>'estimateRevision')::integer,v_source);
  v_revision:=coalesce(v_current.revision,0)+1;
  v_terms:=pg_catalog.jsonb_build_object(
    'billingBasis',v_basis,'billingTrigger',v_trigger,'paymentTerms',v_payment,
    'customerParty',v_party,'customerOrganization',v_organization,
    'customerRole',v_role,'authorityBasis',v_authority,'note',v_note,
    'requestCycleAt',v_source->>'requestCycleAt',
    'childWorkId',v_source->>'childWorkId',
    'coveredScope',v_source->>'coveredScope',
    'uncoveredScope',v_source->>'uncoveredScope',
    'uncoveredAmountMinor',v_source->>'uncoveredAmountMinor',
    'currency',v_source->>'currency',
    'recordedBy',v_actor,'recordedAt',v_now);
  insert into d5o_hosted.connected_service_billing_terms(
    workspace_id,parent_work_id,request_id,revision,source_basis,source_digest,
    terms,evidence_id,evidence_checksum,recorded_by,recorded_at)
  values(v_workspace.id,v_parent.id,p_request_id,v_revision,v_source,v_digest,
    v_terms,(v_doc->>'id')::uuid,v_doc->>'checksumSha256',v_actor,v_now)
  on conflict(workspace_id,parent_work_id,request_id) do update set
    revision=excluded.revision,source_basis=excluded.source_basis,
    source_digest=excluded.source_digest,terms=excluded.terms,
    evidence_id=excluded.evidence_id,evidence_checksum=excluded.evidence_checksum,
    recorded_by=excluded.recorded_by,recorded_at=excluded.recorded_at;
  v_result:=pg_catalog.jsonb_build_object('revision',v_revision,
    'sourceDigest',v_digest,'terms',v_terms,'evidence',v_doc);
  insert into d5o_hosted.connected_service_billing_terms_events(
    workspace_id,parent_work_id,request_id,revision,command_id,actor_user_id,
    membership_id,source_digest,snapshot)
  values(v_workspace.id,v_parent.id,p_request_id,v_revision,p_command_id,
    v_actor,v_member.id,v_digest,v_result);
  insert into d5o_hosted.connected_service_billing_terms_receipts(
    workspace_id,command_id,parent_work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_parent.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_cost_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();v_workspace uuid;v_role text;v_row record;
  v_request jsonb;v_basis jsonb;v_active_count integer;v_unallocated bigint;
  v_items jsonb:='[]'::jsonb;v_customer text;v_kind text;v_blocker text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null then
    raise exception 'membership_required' using errcode='42501'; end if;
  select w.id,m.role into v_workspace,v_role from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
      and m.actor_user_id=v_actor and m.status='active'
    where w.workspace_key=p_workspace_key and w.status='active';
  if v_workspace is null then raise exception 'queue_scope_denied' using errcode='42501'; end if;
  if v_role not in ('project_manager','billing_commercial_lead','operations_leader','admin','executive')
    then return v_items; end if;
  for v_row in select l.work_id,l.presentation_id,w.title,o.state
    from d5o_hosted.connected_operate_states o
    join d5o_hosted.work_identity_links l on l.workspace_id=o.workspace_id
      and l.work_id=o.work_id and l.parent_work_id is null
    join d5o_hosted.work_records w on w.workspace_id=o.workspace_id and w.id=o.work_id
    where o.workspace_id=v_workspace loop
    select item->>'customer' into v_customer from d5o_hosted.prototype_states p,
      lateral pg_catalog.jsonb_array_elements(coalesce(p.state_json->'records','[]'::jsonb)) item
      where p.workspace_id=v_workspace and p.state_key='work'
        and item->>'id'=v_row.presentation_id limit 1;
    for v_request in select item from pg_catalog.jsonb_array_elements(
      coalesce(v_row.state->'requests','[]'::jsonb)) item loop
      if v_request->>'coverage'<>'Partially covered' or v_request->>'status'<>'Closed' then continue; end if;
      v_basis:=d5o_hosted.current_service_finance_basis_v1(
        v_workspace,v_row.work_id,v_request->>'id');
      if v_basis->>'eligibleForFinanceReview'<>'true' then continue; end if;
      select count(*),coalesce(sum(e.amount_minor) filter (where e.allocation='Unallocated'),0)
        into v_active_count,v_unallocated
        from d5o_hosted.connected_service_cost_entries e
        where e.workspace_id=v_workspace and e.parent_work_id=v_row.work_id
          and e.request_id=v_request->>'id'
          and e.kind in ('Original','Replacement') and not exists (
            select 1 from d5o_hosted.connected_service_cost_entries r
            where r.workspace_id=e.workspace_id and r.kind='Reversal'
              and r.reverses_entry_id=e.entry_id);
      if v_active_count=0 then
        v_kind:='Service cost source';
        v_blocker:='No sourced actual cost has been recorded; Finance must establish the incurred-cost position.';
      elsif v_unallocated<>0 then
        v_kind:='Service cost allocation';
        v_blocker:='Recorded cost remains unallocated between covered and uncovered service scope.';
      else continue; end if;
      v_items:=v_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'kind',v_kind,'workId',v_row.presentation_id,'workTitle',v_row.title,
        'requestId',v_request->>'id','requestTitle',v_request->>'title',
        'customer',v_customer,'childWorkId',v_basis->>'childPresentationId',
        'requestCycleAt',v_basis->>'requestCycleAt','coverage','Partially covered',
        'requestStatus','Closed','revision',coalesce((select revision
          from d5o_hosted.connected_service_cost_states s
          where s.workspace_id=v_workspace and s.parent_work_id=v_row.work_id
            and s.request_id=v_request->>'id'),0),
        'status',case when v_active_count=0 then 'Cost unknown' else 'Allocation needed' end,
        'blocker',v_blocker,'responsibleRole','billing_commercial_lead',
        'actionable',v_role='billing_commercial_lead',
        'ownership',case when v_role='billing_commercial_lead'
          then 'Available to your role' else 'Waiting on another role' end,
        'dueDate',null,'panel','finance'));
    end loop;
  end loop;
  return v_items;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_cost_command_v1(p_workspace_key text, p_parent_presentation_id text, p_request_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_work_revision bigint, p_expected_operate_revision integer, p_expected_cycle text, p_expected_child_work_id text, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_parent d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.connected_service_cost_states%rowtype;
  v_receipt d5o_hosted.connected_service_cost_receipts%rowtype;
  v_original d5o_hosted.connected_service_cost_entries%rowtype;
  v_basis jsonb;v_digest text;v_fingerprint text;v_result jsonb;
  v_work_revision bigint;v_operate_revision integer;
  v_amount bigint;v_child uuid;v_entry uuid;v_reversal uuid;
  v_category text:=coalesce(p_input->>'category','');
  v_allocation text:=coalesce(p_input->>'allocation','');
  v_source text:=trim(coalesce(p_input->>'source',''));
  v_rationale text:=trim(coalesce(p_input->>'rationale',''));
  v_date date;v_original_id uuid;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('record-cost','correct-cost')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_service_cost_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role<>'billing_commercial_lead' then
    raise exception 'service_cost_finance_role_required' using errcode='42501'; end if;
  select w.* into v_parent from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
      and l.work_id=w.id and l.parent_work_id is null
    where w.workspace_id=v_workspace.id and l.presentation_id=p_parent_presentation_id
    for update of w;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_parent_presentation_id,p_request_id,p_action,p_input,
    p_expected_revision,p_expected_work_revision,p_expected_operate_revision,
    p_expected_cycle,p_expected_child_work_id,p_expected_source_digest)::text);
  select * into v_receipt from d5o_hosted.connected_service_cost_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.parent_work_id<>v_parent.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select revision into v_work_revision from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select decision_revision into v_operate_revision from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_parent.id for share;
  perform 1 from d5o_hosted.connected_service_work s
    where s.workspace_id=v_workspace.id and s.parent_work_id=v_parent.id
      and s.request_id=p_request_id for share;
  perform 1 from d5o_hosted.connected_deploy_states d
    where d.workspace_id=v_workspace.id and d.work_id in
      (select s.work_id from d5o_hosted.connected_service_work s
       where s.workspace_id=v_workspace.id and s.parent_work_id=v_parent.id
         and s.request_id=p_request_id) for share;
  v_basis:=d5o_hosted.current_service_finance_basis_v1(
    v_workspace.id,v_parent.id,p_request_id);
  v_digest:=pg_catalog.md5(v_basis::text);
  if v_work_revision is distinct from p_expected_work_revision
    or v_operate_revision is distinct from p_expected_operate_revision
    or v_basis->>'requestCycleAt' is distinct from p_expected_cycle
    or v_basis->>'childWorkId' is distinct from p_expected_child_work_id
    or v_digest is distinct from p_expected_source_digest then
    raise exception 'stale_service_cost_source' using errcode='23505'; end if;
  if v_basis->>'eligibleForFinanceReview' is distinct from 'true'
    or v_basis->>'coverage' is distinct from 'Partially covered'
    or v_basis->>'currency' is distinct from 'USD'
    or coalesce(v_basis->>'childWorkId','') !~ '^[0-9a-f-]{36}$' then
    raise exception 'completed_service_cost_basis_required' using errcode='23514'; end if;
  v_child:=(v_basis->>'childWorkId')::uuid;
  select * into v_state from d5o_hosted.connected_service_cost_states
    where workspace_id=v_workspace.id and parent_work_id=v_parent.id
      and request_id=p_request_id for update;
  if coalesce(v_state.revision,0)<>p_expected_revision then
    raise exception 'stale_service_cost_revision' using errcode='23505'; end if;
  if v_state.revision is not null and (v_state.request_cycle_at<>p_expected_cycle
    or v_state.child_work_id<>v_child) then
    raise exception 'service_cost_cycle_changed' using errcode='23514'; end if;
  if coalesce(p_input->>'amountMinor','') !~ '^[1-9][0-9]{0,12}$'
    or p_input->>'currency' is distinct from 'USD'
    or v_category not in ('Labor','Material','Equipment','Subcontract','Travel','Other')
    or v_allocation not in ('Covered','Uncovered','Unallocated')
    or coalesce(p_input->>'incurredDate','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or length(v_source)<12 or length(v_source)>240
    or length(v_rationale)<12 or length(v_rationale)>1000 then
    raise exception 'invalid_service_cost_input' using errcode='22023'; end if;
  v_amount:=(p_input->>'amountMinor')::bigint;
  v_date:=(p_input->>'incurredDate')::date;
  if v_date>current_date+1 then
    raise exception 'service_cost_future_date' using errcode='23514'; end if;
  if exists(select 1 from d5o_hosted.connected_service_cost_entries e
      where e.workspace_id=v_workspace.id and e.parent_work_id=v_parent.id
        and e.request_id=p_request_id and e.kind in ('Original','Replacement')
        and lower(e.source_ref)=lower(v_source)) then
    raise exception 'service_cost_duplicate_source' using errcode='23505'; end if;
  if p_action='correct-cost' then
    if coalesce(p_input->>'originalId','') !~ '^[0-9a-f-]{36}$' then
      raise exception 'service_cost_original_required' using errcode='22023'; end if;
    v_original_id:=(p_input->>'originalId')::uuid;
    select * into v_original from d5o_hosted.connected_service_cost_entries
      where workspace_id=v_workspace.id and parent_work_id=v_parent.id
        and request_id=p_request_id and request_cycle_at=p_expected_cycle
        and child_work_id=v_child and entry_id=v_original_id
        and kind in ('Original','Replacement') for share;
    if not found or exists(select 1 from d5o_hosted.connected_service_cost_entries r
        where r.workspace_id=v_workspace.id and r.kind='Reversal'
          and r.reverses_entry_id=v_original_id) then
      raise exception 'current_service_cost_entry_required' using errcode='23514'; end if;
  elsif p_input->>'originalId' is not null then
    raise exception 'unexpected_service_cost_original' using errcode='22023';
  end if;
  if v_state.revision is null then
    insert into d5o_hosted.connected_service_cost_states(
      workspace_id,parent_work_id,request_id,request_cycle_at,child_work_id)
    values(v_workspace.id,v_parent.id,p_request_id,p_expected_cycle,v_child);
  end if;
  if p_action='correct-cost' then
    insert into d5o_hosted.connected_service_cost_entries(
      workspace_id,parent_work_id,request_id,request_cycle_at,child_work_id,
      kind,root_id,reverses_entry_id,amount_minor,currency,category,allocation,
      incurred_date,source_ref,rationale,source_basis,source_digest,recorded_by)
    values(v_workspace.id,v_parent.id,p_request_id,p_expected_cycle,v_child,
      'Reversal',coalesce(v_original.root_id,v_original.entry_id),v_original.entry_id,
      -v_original.amount_minor,'USD',v_original.category,v_original.allocation,
      v_original.incurred_date,v_original.source_ref,
      'Reversed by sourced correction: '||v_rationale,
      v_original.source_basis,v_original.source_digest,v_actor)
    returning entry_id into v_reversal;
  end if;
  insert into d5o_hosted.connected_service_cost_entries(
    workspace_id,parent_work_id,request_id,request_cycle_at,child_work_id,
    kind,root_id,amount_minor,currency,category,allocation,incurred_date,
    source_ref,rationale,source_basis,source_digest,recorded_by)
  values(v_workspace.id,v_parent.id,p_request_id,p_expected_cycle,v_child,
    case when p_action='correct-cost' then 'Replacement' else 'Original' end,
    case when p_action='correct-cost' then coalesce(v_original.root_id,v_original.entry_id) else null end,
    v_amount,'USD',v_category,v_allocation,v_date,
    v_source,v_rationale,v_basis,v_digest,v_actor)
  returning entry_id into v_entry;
  update d5o_hosted.connected_service_cost_states set revision=revision+1
    where workspace_id=v_workspace.id and parent_work_id=v_parent.id and request_id=p_request_id;
  v_result:=pg_catalog.jsonb_build_object('entryId',v_entry,'reversalId',v_reversal,
    'correctedEntryId',v_original_id,'revision',p_expected_revision+1,
    'requestCycleAt',p_expected_cycle,'childWorkId',v_child,
    'amountMinor',v_amount,'currency','USD','allocation',v_allocation);
  insert into d5o_hosted.connected_service_cost_events(
    workspace_id,parent_work_id,request_id,command_id,action,actor_user_id,
    membership_id,revision,snapshot)
  values(v_workspace.id,v_parent.id,p_request_id,p_command_id,p_action,v_actor,
    v_member.id,p_expected_revision+1,v_result||pg_catalog.jsonb_build_object(
      'source',v_source,'rationale',v_rationale,'sourceDigest',v_digest));
  insert into d5o_hosted.connected_service_cost_receipts(
    workspace_id,command_id,parent_work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_parent.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_finance_command_v1(p_workspace_key text, p_parent_presentation_id text, p_request_id text, p_action text, p_input jsonb, p_command_id text, p_expected_work_revision bigint, p_expected_operate_revision integer, p_expected_design_revision integer, p_expected_deploy_revision integer, p_expected_finance_revision integer, p_expected_basis_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_parent d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_current d5o_hosted.connected_service_finance_states%rowtype;
  v_receipt d5o_hosted.connected_service_finance_receipts%rowtype;
  v_basis jsonb;v_digest text;v_fingerprint text;v_next jsonb;v_result jsonb;
  v_child uuid;
  v_revision integer;v_note text:=trim(coalesce(p_input->>'note',''));
  v_terms text:=nullif(trim(coalesce(p_input->>'billingTermsStatement','')),'');
  v_terms_id uuid;v_now timestamptz:=now();
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('prepare','review-ready','review-hold')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_work_revision is null or p_expected_operate_revision is null
    or p_expected_design_revision is null or p_expected_deploy_revision is null
    or p_expected_finance_revision is null
    or length(coalesce(p_expected_basis_digest,''))<>32 then
    raise exception 'invalid_service_finance_command' using errcode='22023'; end if;
  if nullif(p_input->>'billingTermsEvidenceId','') is not null then
    if (p_input->>'billingTermsEvidenceId') !~ '^[0-9a-f-]{36}$' then
      raise exception 'invalid_billing_terms_evidence' using errcode='22023'; end if;
    v_terms_id:=(p_input->>'billingTermsEvidenceId')::uuid;
  end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or p_action='prepare' and v_member.role<>'project_manager'
    or p_action<>'prepare' and v_member.role<>'billing_commercial_lead' then
    raise exception 'service_finance_role_required' using errcode='42501'; end if;
  select w.* into v_parent from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
      and l.work_id=w.id and l.parent_work_id is null
    where w.workspace_id=v_workspace.id and l.presentation_id=p_parent_presentation_id
    for update of w;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_parent_presentation_id,p_request_id,p_action,p_input,
    p_expected_work_revision,p_expected_operate_revision,p_expected_design_revision,
    p_expected_deploy_revision,p_expected_finance_revision,p_expected_basis_digest)::text);
  select * into v_receipt from d5o_hosted.connected_service_finance_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.parent_work_id<>v_parent.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_parent.id for share;
  select s.work_id into v_child from d5o_hosted.connected_service_work s
    where s.workspace_id=v_workspace.id and s.parent_work_id=v_parent.id
      and s.request_id=p_request_id for share;
  if v_child is null then
    raise exception 'service_finance_execution_incomplete' using errcode='23514'; end if;
  perform 1 from d5o_hosted.work_records
    where workspace_id=v_workspace.id and id=v_child for share;
  perform 1 from d5o_hosted.connected_design_handoffs
    where workspace_id=v_workspace.id and work_id=v_child for share;
  perform 1 from d5o_hosted.connected_design_states
    where workspace_id=v_workspace.id and work_id=v_child for share;
  perform 1 from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_child for share;
  select * into v_current from d5o_hosted.connected_service_finance_states
    where workspace_id=v_workspace.id and parent_work_id=v_parent.id
      and request_id=p_request_id for update;
  v_basis:=d5o_hosted.current_service_finance_basis_v1(
    v_workspace.id,v_parent.id,p_request_id);
  v_digest:=pg_catalog.md5(v_basis::text);
  if v_raw.revision is distinct from p_expected_work_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision
    or (v_basis->>'designRevision')::integer is distinct from p_expected_design_revision
    or (v_basis->>'deployRevision')::integer is distinct from p_expected_deploy_revision
    or coalesce(v_current.revision,0)<>p_expected_finance_revision
    or v_digest<>p_expected_basis_digest then
    raise exception 'stale_service_finance_basis' using errcode='23505'; end if;
  if v_basis->>'eligibleForFinanceReview'<>'true' then
    raise exception 'service_finance_execution_incomplete' using errcode='23514'; end if;
  v_revision:=coalesce(v_current.revision,0)+1;
  if p_action='prepare' then
    if length(v_note)<15
      or (v_terms is null)<>(v_terms_id is null)
      or (v_basis->>'billingTermsKnown'='true' and
        (v_terms is distinct from v_basis->>'billingTermsStatement'
          or v_terms_id::text is distinct from v_basis->>'billingTermsEvidenceId'))
      or (v_basis->>'billingTermsKnown'<>'true' and v_terms is not null) then
      raise exception 'service_finance_preparation_invalid' using errcode='23514'; end if;
    v_next:=pg_catalog.jsonb_build_object('status','Prepared','revision',v_revision,
      'basis',v_basis,'basisDigest',v_digest,'preparedBy',v_actor,
      'preparedAt',v_now,'billingTermsEvidenceId',v_terms_id,
      'billingTermsStatement',v_terms,'note',v_note);
  else
    if v_current.status<>'Prepared' or v_current.basis_digest<>v_digest
      or v_current.prepared_by=v_actor or length(v_note)<20 then
      raise exception 'independent_service_finance_review_required' using errcode='42501'; end if;
    if p_action='review-ready' and (v_basis->>'billingTermsKnown'<>'true'
      or v_current.billing_terms_evidence_id is null
      or length(coalesce(v_current.billing_terms_statement,''))<20
      or v_current.billing_terms_evidence_id::text is distinct from
        v_basis->>'billingTermsEvidenceId'
      or v_current.billing_terms_statement is distinct from
        v_basis->>'billingTermsStatement') then
      raise exception 'service_billing_terms_missing' using errcode='23514'; end if;
    v_next:=pg_catalog.jsonb_build_object(
      'status',case when p_action='review-ready' then 'Ready for billing' else 'Hold' end,
      'revision',v_revision,'basis',v_basis,'basisDigest',v_digest,
      'preparedBy',v_current.prepared_by,'preparedAt',v_current.prepared_at,
      'billingTermsEvidenceId',v_current.billing_terms_evidence_id,
      'billingTermsStatement',v_current.billing_terms_statement,
      'reviewedBy',v_actor,'reviewedAt',v_now,'reviewReason',v_note);
  end if;
  insert into d5o_hosted.connected_service_finance_states(
    workspace_id,parent_work_id,request_id,revision,basis,basis_digest,status,
    prepared_by,prepared_at,billing_terms_evidence_id,billing_terms_statement,
    reviewed_by,reviewed_at,review_reason)
  values(v_workspace.id,v_parent.id,p_request_id,v_revision,v_basis,v_digest,
    v_next->>'status',(v_next->>'preparedBy')::uuid,
    (v_next->>'preparedAt')::timestamptz,
    nullif(v_next->>'billingTermsEvidenceId','')::uuid,
    v_next->>'billingTermsStatement',
    nullif(v_next->>'reviewedBy','')::uuid,
    nullif(v_next->>'reviewedAt','')::timestamptz,v_next->>'reviewReason')
  on conflict(workspace_id,parent_work_id,request_id) do update set
    revision=excluded.revision,basis=excluded.basis,
    basis_digest=excluded.basis_digest,status=excluded.status,
    prepared_by=excluded.prepared_by,prepared_at=excluded.prepared_at,
    billing_terms_evidence_id=excluded.billing_terms_evidence_id,
    billing_terms_statement=excluded.billing_terms_statement,
    reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,
    review_reason=excluded.review_reason;
  insert into d5o_hosted.connected_service_finance_events(
    workspace_id,parent_work_id,request_id,revision,command_id,action,
    actor_user_id,membership_id,basis_digest,snapshot)
  values(v_workspace.id,v_parent.id,p_request_id,v_revision,p_command_id,p_action,
    v_actor,v_member.id,v_digest,v_next);
  v_result:=pg_catalog.jsonb_build_object('basis',v_basis,'basisDigest',v_digest,
    'decision',v_next,'decisionCurrent',true,'revision',v_revision);
  insert into d5o_hosted.connected_service_finance_receipts(
    workspace_id,command_id,parent_work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_parent.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_finance_read_v1(p_workspace_key text, p_parent_presentation_id text, p_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_workspace uuid;v_parent uuid;v_basis jsonb;
  v_decision d5o_hosted.connected_service_finance_states%rowtype;
  v_history jsonb;v_work_revision bigint;v_operate_revision integer;
  v_source jsonb;v_terms_revision integer;
begin
  if current_setting('role',true)<>'authenticated' or auth.uid() is null then
    raise exception 'service_finance_auth_required' using errcode='42501'; end if;
  select w.id,l.work_id into v_workspace,v_parent
    from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
      and m.actor_user_id=auth.uid() and m.status='active'
    join d5o_hosted.work_identity_links l on l.workspace_id=w.id
      and l.presentation_id=p_parent_presentation_id and l.parent_work_id is null
    where w.workspace_key=p_workspace_key and w.status='active'
      and m.role in ('project_manager','billing_commercial_lead',
        'operations_leader','admin','executive');
  if v_parent is null then raise exception 'service_finance_scope_forbidden' using errcode='42501'; end if;
  v_basis:=d5o_hosted.current_service_finance_basis_v1(v_workspace,v_parent,p_request_id);
  v_source:=d5o_hosted.service_billing_terms_source_v1(v_workspace,v_parent,p_request_id);
  select revision into v_terms_revision from d5o_hosted.connected_service_billing_terms
    where workspace_id=v_workspace and parent_work_id=v_parent and request_id=p_request_id;
  select revision into v_work_revision from d5o_hosted.prototype_states
    where workspace_id=v_workspace and state_key='work';
  select decision_revision into v_operate_revision
    from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace and work_id=v_parent;
  select * into v_decision from d5o_hosted.connected_service_finance_states
    where workspace_id=v_workspace and parent_work_id=v_parent and request_id=p_request_id;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'revision',e.revision,'action',e.action,'actorId',e.actor_user_id,
    'at',e.at,'snapshot',e.snapshot) order by e.revision),'[]'::jsonb)
    into v_history from d5o_hosted.connected_service_finance_events e
    where e.workspace_id=v_workspace and e.parent_work_id=v_parent
      and e.request_id=p_request_id;
  return pg_catalog.jsonb_build_object(
    'basis',v_basis,'basisDigest',pg_catalog.md5(v_basis::text),
    'termsSource',v_source,'termsSourceDigest',pg_catalog.md5(v_source::text),
    'termsRevision',coalesce(v_terms_revision,0),
    'decision',case when v_decision.parent_work_id is null then null else
      pg_catalog.to_jsonb(v_decision) end,
    'decisionCurrent',v_decision.parent_work_id is not null and
      v_decision.basis_digest=pg_catalog.md5(v_basis::text),
    'revision',coalesce(v_decision.revision,0),
    'workRevision',v_work_revision,'operateRevision',v_operate_revision,
    'history',v_history);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_job_command_v1(p_workspace_key text, p_parent_presentation_id text, p_request_id text, p_due_date date, p_owner text, p_command_id text, p_expected_work_revision bigint, p_expected_catalog_revision bigint, p_expected_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_parent d5o_hosted.work_records%rowtype;
  v_work d5o_hosted.prototype_states%rowtype;v_catalog d5o_hosted.prototype_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_receipt d5o_hosted.connected_create_receipts%rowtype;
  v_parent_raw jsonb;v_request jsonb;v_asset jsonb;v_child jsonb;
  v_catalog_child jsonb;v_after_operate jsonb;
  v_job jsonb;v_fingerprint text;v_result jsonb;v_child_id uuid:=gen_random_uuid();
  v_job_id uuid:=gen_random_uuid();v_alias text;v_type d5o_hosted.configuration_work_types%rowtype;
  v_now timestamptz:=now();v_request_cycle text;v_estimate jsonb;v_auth jsonb;v_pricing jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_request_id is null or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_due_date is null or p_due_date<current_date
    or length(trim(coalesce(p_owner,''))) not between 3 and 120
    or p_expected_work_revision is null or p_expected_catalog_revision is null
    or p_expected_operate_revision is null then
    raise exception 'invalid_service_job_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or v_member.role not in ('project_manager','operations_leader') then
    raise exception 'service_job_authority_required' using errcode='42501'; end if;
  select w.* into v_parent from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_parent_presentation_id
      and l.parent_work_id is null for update of w;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_parent_presentation_id,p_request_id,p_due_date,p_owner)::text);
  select * into v_receipt from d5o_hosted.connected_create_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.actor_user_id<>v_actor or v_receipt.request_fingerprint<>v_fingerprint
      then raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_work from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for update;
  select * into v_catalog from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='catalog' for update;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_parent.id for update;
  if v_work.revision is distinct from p_expected_work_revision
    or v_catalog.revision is distinct from p_expected_catalog_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision then
    raise exception 'stale_service_job_basis' using errcode='23505'; end if;
  select item into v_parent_raw from pg_catalog.jsonb_array_elements(v_work.state_json->'records') item
    where item->>'id'=p_parent_presentation_id and item->>'canonicalWorkId'=v_parent.id::text;
  if v_parent_raw is null or v_parent_raw->>'phaseConfigurationVersionId'
      is distinct from v_parent.configuration_version_id::text
    or v_operate.state#>>'{activation,status}'<>'Active' then
    raise exception 'active_canonical_support_required' using errcode='23514'; end if;
  select item into v_request from pg_catalog.jsonb_array_elements(v_operate.state->'requests') item
    where item->>'id'=p_request_id and item->>'status' in ('Triaged','In progress');
  if v_request is null then raise exception 'triaged_request_required' using errcode='23514'; end if;
  if v_request->>'coverage' not in ('Covered','Partially covered') then
    raise exception 'authoritative_service_pricing_required' using errcode='23514'; end if;
  if v_request->>'coverage'='Partially covered' then
    v_estimate:=v_request->'serviceEstimate';
    v_auth:=v_request->'serviceAuthorization';
    if v_estimate->>'status'<>'Approved'
      or v_estimate->>'requestCycleAt' is distinct from
        coalesce(v_request->>'reopenedAt',v_request->>'reportedAt')
      or v_auth->>'estimateRevision' is distinct from v_estimate->>'revision'
      or v_auth->>'amountMinor' is distinct from v_estimate#>>'{evaluation,proposedPriceMinor}'
      or v_auth->>'currency' is distinct from v_estimate#>>'{evaluation,currency}' then
      raise exception 'exact_partial_customer_authorization_required' using errcode='23514'; end if;
    v_pricing:=pg_catalog.jsonb_build_object('estimateRevision',(v_estimate->>'revision')::integer,
      'policyId',v_estimate#>>'{policySnapshot,id}',
      'policyVersion',(v_estimate#>>'{policySnapshot,version}')::integer,
      'currency',v_auth->>'currency','amountMinor',(v_auth->>'amountMinor')::bigint,
      'customerAuthorizationSource',v_auth->>'source');
  end if;
  select item into v_asset from pg_catalog.jsonb_array_elements(v_operate.state->'assets') item
    where item->>'id'=v_request->>'assetId' and item->>'status'='Supported';
  if v_asset is null then raise exception 'supported_asset_required' using errcode='23514'; end if;
  v_request_cycle:=coalesce(v_request->>'reopenedAt',v_request->>'reportedAt');
  if exists(select 1 from pg_catalog.jsonb_array_elements(v_operate.state->'jobs') item
    where item->>'requestId'=p_request_id and item->>'requestCycleAt'=v_request_cycle
      and item->>'dueDate'=p_due_date::text and item->>'status'<>'Cancelled') then
    raise exception 'duplicate_service_visit' using errcode='23505'; end if;
  select * into v_type from d5o_hosted.configuration_work_types
    where configuration_version_id=v_parent.configuration_version_id
      and display_name='Lifecycle service' and status='active';
  if not found or not exists(select 1 from d5o_hosted.configuration_create_rights
      where configuration_version_id=v_parent.configuration_version_id
        and work_type_key=v_type.work_type_key and workspace_role=v_member.role) then
    raise exception 'service_work_type_right_unavailable' using errcode='42501'; end if;
  v_alias:=p_workspace_key||'-'||pg_catalog.replace(v_child_id::text,'-','');
  v_job:=pg_catalog.jsonb_build_object('id',v_job_id,'workId',v_alias,
    'assetIds',pg_catalog.jsonb_build_array(v_asset->>'id'),'requestId',p_request_id,
    'requestCycleAt',v_request_cycle,'dueDate',p_due_date,'status','Generated',
    'evidence','[]'::jsonb,'createdAt',v_now,'createdByActorId',v_actor);
  v_child:=pg_catalog.jsonb_build_object('id',v_alias,'canonicalWorkId',v_child_id,
    'workspace',p_workspace_key,'title',(v_request->>'title')||' · '||(v_asset->>'name'),
    'type',v_type.display_name,'customer',v_parent_raw->>'customer',
    'site',v_parent_raw->>'site','stage','Design','owner',trim(p_owner),
    'nextAction','Prepare and approve service execution basis before Design release',
    'progress',0,'value',case when v_pricing is null then 'Covered service obligation' else 'Partially covered service · priced uncovered scope' end,'status','attention',
    'proof','[]'::jsonb,'blockers','[]'::jsonb,
    'history',pg_catalog.jsonb_build_array(v_now::text||' · Service visit created from accepted support; field execution is not authorized.'),
    'phaseConfigurationVersionId',v_parent.configuration_version_id,
    'serviceSource',pg_catalog.jsonb_build_object('parentWorkId',p_parent_presentation_id,
      'assetIds',pg_catalog.jsonb_build_array(v_asset->>'id'),'requestId',p_request_id,
      'requestCycleAt',v_request_cycle,'coverage',v_request->>'coverage',
      'pricing',v_pricing));
  v_catalog_child:=v_child-'serviceSource'||pg_catalog.jsonb_build_object(
    'createdAt',v_now,'createdBy',v_actor);
  insert into d5o_hosted.work_records(id,workspace_id,configuration_tenant_id,
    configuration_version_id,configuration_digest,work_type_key,title,created_by)
  values(v_child_id,v_workspace.id,v_parent.configuration_tenant_id,
    v_parent.configuration_version_id,v_parent.configuration_digest,v_type.work_type_key,
    v_child->>'title',v_actor);
  insert into d5o_hosted.work_identity_links(workspace_id,work_id,presentation_id,
    parent_work_id,relation_kind)
  values(v_workspace.id,v_child_id,v_alias,v_parent.id,'service_visit');
  insert into d5o_hosted.connected_service_work(workspace_id,work_id,parent_work_id,
    presentation_id,request_id,asset_id,work_projection,catalog_projection)
  values(v_workspace.id,v_child_id,v_parent.id,v_alias,p_request_id,
    v_asset->>'id',v_child,v_catalog_child);
  v_request:=v_request||pg_catalog.jsonb_build_object('status','In progress',
    'jobIds',coalesce(v_request->'jobIds','[]'::jsonb)||pg_catalog.jsonb_build_array(v_job_id),
    'currentCycleJobIds',coalesce(v_request->'currentCycleJobIds','[]'::jsonb)
      ||pg_catalog.jsonb_build_array(v_job_id));
  v_after_operate:=pg_catalog.jsonb_set(v_operate.state,'{requests}',
    (select pg_catalog.jsonb_agg(case when item->>'id'=p_request_id then v_request
      else item end order by ordinal) from pg_catalog.jsonb_array_elements(v_operate.state->'requests')
      with ordinality as entries(item,ordinal)));
  v_after_operate:=pg_catalog.jsonb_set(v_after_operate,'{jobs}',
    v_operate.state->'jobs'||pg_catalog.jsonb_build_array(v_job));
  v_after_operate:=v_after_operate||pg_catalog.jsonb_build_object(
    'authorityRevision',v_operate.decision_revision+1,
    'events',v_operate.state->'events'||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),'commandId',p_command_id,
        'fingerprint',v_fingerprint,'at',v_now,'actorId',v_actor,
        'membershipId',v_member.id,'action','create-job','detail',v_alias)));
  update d5o_hosted.connected_operate_states set decision_revision=decision_revision+1,
    state=v_after_operate,updated_at=v_now where workspace_id=v_workspace.id and work_id=v_parent.id;
  insert into d5o_hosted.connected_operate_events(workspace_id,work_id,decision_revision,
    command_id,action,actor_user_id,membership_id,deploy_revision,snapshot)
  values(v_workspace.id,v_parent.id,v_operate.decision_revision+1,p_command_id,
    'create-job',v_actor,v_member.id,
    (select decision_revision from d5o_hosted.connected_deploy_states
      where workspace_id=v_workspace.id and work_id=v_parent.id),v_after_operate);
  insert into d5o_hosted.work_events(workspace_id,work_id,event_type,record_version,
    actor_user_id,membership_id,authority_role,configuration_version_id,
    configuration_digest,payload) values(v_workspace.id,v_child_id,'work_created',1,
    v_actor,v_member.id,v_member.role,v_parent.configuration_version_id,
    v_parent.configuration_digest,pg_catalog.jsonb_build_object('parentWorkId',v_parent.id,
      'relationKind','service_visit','presentationId',v_alias,'requestId',p_request_id,
      'requestCycleAt',v_request_cycle,'commandId',p_command_id));
  v_result:=pg_catalog.jsonb_build_object('workId',v_child_id,'presentationId',v_alias,
    'parentWorkId',v_parent.id,'jobId',v_job_id,'workRevision',v_work.revision,
    'catalogRevision',v_catalog.revision,'operateRevision',v_operate.decision_revision+1);
  insert into d5o_hosted.connected_create_receipts(workspace_id,command_id,
    actor_user_id,request_fingerprint,work_id,result)
  values(v_workspace.id,p_command_id,v_actor,v_fingerprint,v_child_id,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_pricing_command_v1(p_workspace_key text, p_parent_presentation_id text, p_request_id text, p_action text, p_input jsonb, p_command_id text, p_expected_work_revision bigint, p_expected_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_parent d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_receipt d5o_hosted.connected_operate_receipts%rowtype;
  v_request jsonb;v_policy jsonb;v_rate jsonb;v_line jsonb;v_input jsonb;
  v_estimate jsonb;v_eval jsonb;v_auth jsonb;v_state jsonb;v_result jsonb;v_evidence jsonb;
  v_cycle text;v_fingerprint text;v_now timestamptz:=now();
  v_qty numeric;v_cost numeric;v_direct bigint;v_overhead bigint;
  v_contingency bigint;v_included bigint;v_price bigint;v_base bigint;
  v_discount bigint;v_margin numeric;v_target numeric;v_floor numeric;
  v_discount_pct numeric;v_revision integer;v_reason text:=trim(coalesce(p_input->>'note',''));
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-service-estimate','submit-service-pricing',
      'approve-service-pricing','return-service-pricing','record-service-authorization')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_work_revision is null or p_expected_work_revision<1
    or p_expected_operate_revision is null or p_expected_operate_revision<1 then
    raise exception 'invalid_service_pricing_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'service_pricing_authority_required' using errcode='42501'; end if;
  select w.* into v_parent from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
      and l.work_id=w.id and l.parent_work_id is null
    where w.workspace_id=v_workspace.id and l.presentation_id=p_parent_presentation_id
      for update of w;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_parent_presentation_id,p_request_id,p_action,p_input,
    p_expected_work_revision,p_expected_operate_revision)::text);
  select * into v_receipt from d5o_hosted.connected_operate_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_parent.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_parent.id for update;
  if v_raw.revision is distinct from p_expected_work_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision then
    raise exception 'stale_service_pricing_basis' using errcode='23505'; end if;
  select item into v_request from pg_catalog.jsonb_array_elements(v_operate.state->'requests') item
    where item->>'id'=p_request_id;
  if v_request is null or v_request->>'status' not in ('Triaged','In progress')
    or v_request->>'coverage' not in ('Partially covered','Chargeable')
    or v_request->>'agreementId' is null then
    raise exception 'current_partial_request_required' using errcode='23514'; end if;
  v_cycle:=coalesce(v_request->>'reopenedAt',v_request->>'reportedAt');
  v_estimate:=v_request->'serviceEstimate';
  if p_action='save-service-estimate' then
    if v_member.role<>'project_manager' then
      raise exception 'service_estimator_required' using errcode='42501'; end if;
    v_input:=p_input->'pricingInput';
    if pg_catalog.jsonb_typeof(v_input->'lines')<>'array'
      or pg_catalog.jsonb_array_length(v_input->'lines')<>1
      or length(trim(coalesce(v_input->>'riskBasis','')))<10 then
      raise exception 'sourced_single_line_required' using errcode='23514'; end if;
    v_line:=v_input->'lines'->0;
    if v_line->>'category'<>'labor' or length(trim(coalesce(v_line->>'description','')))<8
      or length(trim(coalesce(v_line->>'source','')))<8
      or length(trim(coalesce(v_line->>'assumption','')))<8
      or v_line->>'rateId' is null or v_line->>'manualRate' is not null
      or v_line->>'scopeRef'<>p_request_id or v_line->>'unit'<>'hour'
      or v_line->'procurement' is not null then
      raise exception 'published_labor_rate_required' using errcode='23514'; end if;
    select p.payload into v_policy from d5o_hosted.connected_pricing_policies p
      join d5o_hosted.connected_pricing_active a on a.workspace_id=p.workspace_id
        and a.policy_id=p.policy_id and a.version=p.version
      where p.workspace_id=v_workspace.id and p.status='published';
    if v_policy is null or v_policy->>'method'<>'target-margin'
      or v_policy->>'currency' is distinct from v_input->>'currency'
      or (v_policy->>'effectiveFrom')::date>current_date then
      raise exception 'active_published_service_policy_required' using errcode='23514'; end if;
    select item into v_rate from pg_catalog.jsonb_array_elements(v_policy->'rates') item
      where item->>'id'=v_line->>'rateId' and item->>'category'='labor'
        and item->>'unit'='hour' and item#>>'{scope,kind}'='default'
        and (item->>'effectiveFrom')::date<=current_date
        and (item->>'effectiveTo' is null or (item->>'effectiveTo')::date>=current_date);
    if v_rate is null then raise exception 'effective_labor_rate_missing' using errcode='23514'; end if;
    begin
      v_qty:=(v_line->>'quantity')::numeric;
      v_cost:=(v_rate->>'amount')::numeric;
      v_target:=(v_policy->>'targetMarginPercent')::numeric;
      v_floor:=(v_policy->>'floorMarginPercent')::numeric;
      v_discount_pct:=(v_input->>'discountPercent')::numeric;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'invalid_service_money_input' using errcode='22023'; end;
    if v_qty<=0 or v_qty>10000 or v_cost<=0 or v_cost>100000
      or v_target<0 or v_target>=100 or v_floor<0 or v_floor>=100
      or v_discount_pct<0 or v_discount_pct>(v_policy->>'maxDiscountPercent')::numeric then
      raise exception 'service_pricing_policy_limit' using errcode='23514'; end if;
    v_direct:=pg_catalog.round(v_qty*v_cost*100*
      (100+coalesce((v_rate->>'burdenPercent')::numeric,0))/100)::bigint;
    v_overhead:=pg_catalog.round(v_direct*(v_policy->>'overheadPercent')::numeric/100)::bigint;
    v_contingency:=pg_catalog.round(v_direct*(v_policy->>'contingencyPercent')::numeric/100)::bigint;
    v_included:=v_direct+v_overhead+v_contingency;
    v_base:=pg_catalog.ceil(v_included*100/(100-v_target))::bigint;
    v_discount:=pg_catalog.round(v_base*v_discount_pct/100)::bigint;
    v_price:=v_base-v_discount;
    v_margin:=(v_price-v_included)*100.0/v_price;
    if v_margin<v_floor then raise exception 'service_margin_below_floor' using errcode='23514'; end if;
    v_revision:=coalesce((v_estimate->>'revision')::integer,0)+1;
    v_input:=v_input||pg_catalog.jsonb_build_object('workType','Lifecycle service',
      'pricedAt',current_date,'definitionRevision',0,'solutionRevision',0);
    v_eval:=pg_catalog.jsonb_build_object('policyId',v_policy->>'id',
      'policyVersion',(v_policy->>'version')::integer,'currency',v_policy->>'currency',
      'input',v_input,'lines',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'id',v_line->>'id','category','labor','amountMinor',v_direct,
        'rateId',v_rate->>'id','rateSource',v_rate->>'source')),
      'directCostMinor',v_direct,'overheadMinor',v_overhead,
      'contingencyMinor',v_contingency,'includedCostMinor',v_included,
      'proposedPriceMinor',v_price,'discountMinor',v_discount,
      'grossProfitMinor',v_price-v_included,'marginPercent',v_margin,
      'annualRecurringMinor',0,'totalRecurringMinor',0,
      'minimumFloorPriceMinor',pg_catalog.ceil(v_included*100/(100-v_floor)),
      'minimumTargetPriceMinor',v_base,
      'absorbableCostMinor',v_price-pg_catalog.ceil(v_price*v_floor/100)-v_included,
      'issues','[]'::jsonb,'recommendation','Ready for pricing review',
      'calculatedAt',v_now);
    v_estimate:=pg_catalog.jsonb_build_object('revision',v_revision,
      'requestCycleAt',v_cycle,'status','Draft','input',v_input,
      'evaluation',v_eval,'policySnapshot',v_policy,'savedAt',v_now,
      'savedByActorId',v_actor,'history',coalesce(v_estimate->'history','[]'::jsonb)
        ||case when v_estimate is null then '[]'::jsonb else
          pg_catalog.jsonb_build_array(v_estimate) end);
    v_request:=v_request||pg_catalog.jsonb_build_object('serviceEstimate',v_estimate);
  elsif p_action='submit-service-pricing' then
    if v_member.role<>'project_manager' then
      raise exception 'service_estimator_required' using errcode='42501'; end if;
    if v_estimate->>'status'<>'Draft' or v_estimate->>'requestCycleAt'<>v_cycle
      or (v_estimate->>'revision')::integer is distinct from (p_input->>'estimateRevision')::integer then
      raise exception 'stale_service_estimate' using errcode='23505'; end if;
    v_estimate:=v_estimate||pg_catalog.jsonb_build_object('status','Pricing review',
      'submittedByActorId',v_actor,'submittedAt',v_now);
    v_request:=v_request||pg_catalog.jsonb_build_object('serviceEstimate',v_estimate);
  elsif p_action in ('approve-service-pricing','return-service-pricing') then
    if v_estimate->>'status'<>'Pricing review' or v_estimate->>'requestCycleAt'<>v_cycle
      or (v_estimate->>'revision')::integer is distinct from (p_input->>'estimateRevision')::integer then
      raise exception 'stale_service_pricing_review' using errcode='23505'; end if;
    if v_member.role<>v_estimate#>>'{policySnapshot,pricingApproverRole}'
      or v_actor::text=v_estimate->>'submittedByActorId' or length(v_reason)<10 then
      raise exception 'independent_pricing_review_required' using errcode='42501'; end if;
    v_estimate:=v_estimate||pg_catalog.jsonb_build_object('status',
      case when p_action='approve-service-pricing' then 'Approved' else 'Returned' end,
      'reviewedByActorId',v_actor,'reviewedAt',v_now,'reviewNote',v_reason);
    v_request:=v_request||pg_catalog.jsonb_build_object('serviceEstimate',v_estimate);
  else
    if v_member.role<>'operations_leader' or v_estimate->>'status'<>'Approved'
      or v_estimate->>'requestCycleAt'<>v_cycle
      or (v_estimate->>'revision')::integer is distinct from (p_input->>'estimateRevision')::integer
      or v_request#>>'{serviceAuthorization,estimateRevision}'=v_estimate->>'revision'
      or p_input->>'evidenceId' is null
      or length(trim(coalesce(p_input->>'customerParty','')))<3
      or length(trim(coalesce(p_input->>'customerOrganization','')))<3
      or length(trim(coalesce(p_input->>'customerRole','')))<3
      or length(trim(coalesce(p_input->>'authorityBasis','')))<10
      or p_input->>'outcome'<>'Authorized' or length(v_reason)<10 then
      raise exception 'exact_customer_service_authorization_required' using errcode='23514'; end if;
    v_evidence:=d5o_hosted.require_customer_decision_evidence_v1(
      v_workspace.id,v_parent.id,p_input->>'evidenceId',
      'service-authorization',p_request_id,(v_estimate->>'revision')::integer,
      pg_catalog.jsonb_build_object(
        'estimateRevision',(v_estimate->>'revision')::integer,
        'amountMinor',v_estimate#>'{evaluation,proposedPriceMinor}',
        'currency',v_estimate#>>'{evaluation,currency}',
        'requestCycleAt',v_cycle));
    v_auth:=pg_catalog.jsonb_build_object('estimateRevision',(v_estimate->>'revision')::integer,
      'amountMinor',v_estimate#>'{evaluation,proposedPriceMinor}',
      'currency',v_estimate#>>'{evaluation,currency}',
      'source','evidence:'||(v_evidence->>'id'),'customerEvidence',v_evidence,
      'customerParty',p_input->>'customerParty',
      'customerOrganization',p_input->>'customerOrganization',
      'customerRole',p_input->>'customerRole',
      'authorityBasis',p_input->>'authorityBasis',
      'outcome',p_input->>'outcome',
      'conditions',trim(coalesce(p_input->>'conditions','')),
      'exclusions',trim(coalesce(p_input->>'exclusions','')),
      'recordedByActorId',v_actor,'recordedAt',v_now);
    v_request:=v_request||pg_catalog.jsonb_build_object('serviceAuthorization',v_auth,
      'serviceAuthorizationHistory',coalesce(v_request->'serviceAuthorizationHistory','[]'::jsonb));
  end if;
  v_request:=pg_catalog.jsonb_set(v_request,'{history}',
    coalesce(v_request->'history','[]'::jsonb)||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('at',v_now,'action',p_action,
        'actorId',v_actor,'note',v_reason)));
  v_state:=pg_catalog.jsonb_set(v_operate.state,'{requests}',
    (select pg_catalog.jsonb_agg(case when item->>'id'=p_request_id then v_request
      else item end order by ordinal) from pg_catalog.jsonb_array_elements(v_operate.state->'requests')
      with ordinality as entries(item,ordinal)));
  v_state:=v_state||pg_catalog.jsonb_build_object('authorityRevision',
    v_operate.decision_revision+1,'events',coalesce(v_operate.state->'events','[]'::jsonb)
      ||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('id',gen_random_uuid(),
        'commandId',p_command_id,'fingerprint',v_fingerprint,'at',v_now,
        'actorId',v_actor,'membershipId',v_member.id,'action',p_action,
        'detail',p_request_id)));
  update d5o_hosted.connected_operate_states set decision_revision=decision_revision+1,
    state=v_state,updated_at=v_now where workspace_id=v_workspace.id and work_id=v_parent.id;
  insert into d5o_hosted.connected_operate_events(workspace_id,work_id,decision_revision,
    command_id,action,actor_user_id,membership_id,deploy_revision,snapshot)
  values(v_workspace.id,v_parent.id,v_operate.decision_revision+1,p_command_id,p_action,
    v_actor,v_member.id,coalesce((select decision_revision from d5o_hosted.connected_deploy_states
      where workspace_id=v_workspace.id and work_id=v_parent.id),0),v_state);
  v_result:=pg_catalog.jsonb_build_object('state',
    d5o_hosted.connected_operate_projection_v1(v_workspace.id,v_raw.state_json),
    'revision',v_raw.revision,'operateRevision',v_operate.decision_revision+1);
  insert into d5o_hosted.connected_operate_receipts(workspace_id,command_id,work_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_parent.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_service_return_command_v1(p_workspace_key text, p_parent_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_work_revision bigint, p_expected_operate_revision integer, p_expected_child_deploy_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;
  v_parent_work d5o_hosted.work_records%rowtype;
  v_child_work d5o_hosted.work_records%rowtype;
  v_service d5o_hosted.connected_service_work%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_receipt d5o_hosted.connected_operate_receipts%rowtype;
  v_state jsonb;v_job jsonb;v_request jsonb;v_asset jsonb;
  v_evidence jsonb:='[]'::jsonb;v_completions jsonb:='[]'::jsonb;
  v_result jsonb;v_fingerprint text;v_now timestamptz:=now();
  v_job_id text;v_request_id text;v_note text:=trim(coalesce(p_input->>'note',''));
  v_item jsonb;v_release_id text;v_revision integer;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('link-execution','complete-job','resolve-request','close-request')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_work_revision is null or p_expected_work_revision<1
    or p_expected_operate_revision is null or p_expected_operate_revision<1
    or p_expected_child_deploy_revision is null or p_expected_child_deploy_revision<1 then
    raise exception 'invalid_service_return_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('d5o-connected:'||v_workspace.id::text,0));
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found or (p_action in ('link-execution','complete-job','close-request')
      and v_member.role<>'operations_leader')
    or (p_action='resolve-request' and v_member.role<>'project_manager') then
    raise exception 'service_return_authority_required' using errcode='42501'; end if;
  select w.* into v_parent_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
      and l.work_id=w.id and l.parent_work_id is null
    where w.workspace_id=v_workspace.id and l.presentation_id=p_parent_presentation_id
      for update of w;
  if not found then raise exception 'canonical_parent_required' using errcode='23503'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_parent_presentation_id,p_action,p_input,
    p_expected_work_revision,p_expected_operate_revision,
    p_expected_child_deploy_revision)::text);
  select * into v_receipt from d5o_hosted.connected_operate_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_parent_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result; end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_parent_work.id for update;
  if v_raw.revision is distinct from p_expected_work_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision then
    raise exception 'stale_service_return_basis' using errcode='23505'; end if;
  v_state:=v_operate.state;
  if p_action in ('link-execution','complete-job') then
    v_job_id:=p_input->>'jobId';
    select item into v_job from pg_catalog.jsonb_array_elements(v_state->'jobs') item
      where item->>'id'=v_job_id and item->>'requestId' is not null;
    v_request_id:=v_job->>'requestId';
  else
    v_request_id:=p_input->>'requestId';
    select item into v_request from pg_catalog.jsonb_array_elements(v_state->'requests') item
      where item->>'id'=v_request_id;
    if v_request is null or pg_catalog.jsonb_array_length(
      coalesce(v_request->'currentCycleJobIds','[]'::jsonb))<>1 then
      raise exception 'single_current_service_job_required' using errcode='23514'; end if;
    v_job_id:=v_request->'currentCycleJobIds'->>0;
    select item into v_job from pg_catalog.jsonb_array_elements(v_state->'jobs') item
      where item->>'id'=v_job_id and item->>'requestId'=v_request_id;
  end if;
  if v_job is null then raise exception 'service_job_missing' using errcode='23514'; end if;
  if v_request is null then
    select item into v_request from pg_catalog.jsonb_array_elements(v_state->'requests') item
      where item->>'id'=v_request_id;
  end if;
  if v_request is null or not (coalesce(v_request->'currentCycleJobIds','[]'::jsonb) ? v_job_id)
    or v_job->>'requestCycleAt' is distinct from
      coalesce(v_request->>'reopenedAt',v_request->>'reportedAt')
    or v_job->>'assetIds' is not null and not (v_job->'assetIds' ? (v_request->>'assetId')) then
    raise exception 'current_service_cycle_required' using errcode='23514'; end if;
  select * into v_service from d5o_hosted.connected_service_work
    where workspace_id=v_workspace.id and presentation_id=v_job->>'workId'
      and parent_work_id=v_parent_work.id and request_id=v_request_id
      and asset_id=v_request->>'assetId';
  select * into v_child_work from d5o_hosted.work_records
    where workspace_id=v_workspace.id and id=v_service.work_id for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_child_work.id for share;
  if v_service.work_id is null or v_child_work.id is null
    or v_deploy.decision_revision is distinct from p_expected_child_deploy_revision then
    raise exception 'stale_service_execution' using errcode='23505'; end if;
  if p_action='link-execution' then
    if v_job->>'status'<>'Generated' or v_request->>'status'<>'In progress'
      or v_request->>'coverage' not in ('Covered','Partially covered')
      or v_deploy.state#>>'{workAcceptance,receipt}'<>'Accepted' then
      raise exception 'accepted_service_execution_required' using errcode='23514'; end if;
    perform d5o_hosted.connected_design_source_v1(v_workspace.id,
      v_child_work.id,v_raw.state_json);
    for v_item in select value from pg_catalog.jsonb_array_elements(
      v_deploy.state#>'{workAcceptance,releaseIds}') loop
      v_release_id:=v_item#>>'{}';
      if not exists(select 1 from pg_catalog.jsonb_array_elements(v_deploy.state->'completions') c
        where c->>'releaseId'=v_release_id and c->>'status'='Reviewed')
        or not exists(select 1 from pg_catalog.jsonb_array_elements(v_deploy.state->'inspections') i
          where i->>'releaseId'=v_release_id and i->>'status'='Verified'
            and i->>'result'='Pass') then
        raise exception 'verified_service_completion_required' using errcode='23514'; end if;
      v_completions:=v_completions||coalesce((select pg_catalog.jsonb_agg(
        (v_job->>'workId')||':completion:'||(c->>'id')||':release:'||v_release_id)
        from pg_catalog.jsonb_array_elements(v_deploy.state->'completions') c
        where c->>'releaseId'=v_release_id and c->>'status'='Reviewed'),'[]'::jsonb);
    end loop;
    v_evidence:=coalesce((select pg_catalog.jsonb_agg(
      (v_job->>'workId')||':report:'||(r->>'id')||':r'||(r->>'revision'))
      from pg_catalog.jsonb_array_elements(v_deploy.state->'reports') r
      where r->>'status'='Reviewed' and v_deploy.state#>'{workAcceptance,releaseIds}'
        ? (r->>'releaseId')),'[]'::jsonb);
    if pg_catalog.jsonb_array_length(v_evidence)=0
      or not exists(select 1 from pg_catalog.jsonb_array_elements(v_deploy.state->'evidence') e
        where e->>'state'='Reviewed') then
      raise exception 'reviewed_service_evidence_required' using errcode='23514'; end if;
    v_job:=v_job||pg_catalog.jsonb_build_object('status','Execution linked',
      'evidence',v_evidence,'completionRefs',v_completions,
      'linkedByActorId',v_actor,'linkedAt',v_now,
      'workAcceptanceId',v_deploy.state#>>'{workAcceptance,id}');
    select item into v_asset from pg_catalog.jsonb_array_elements(v_state->'assets') item
      where item->>'id'=v_request->>'assetId' and item->>'status'='Supported';
    if v_asset is null then raise exception 'supported_asset_required' using errcode='23514'; end if;
    v_asset:=pg_catalog.jsonb_set(v_asset,'{history}',
      coalesce(v_asset->'history','[]'::jsonb)||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('at',v_now,'action','Reviewed service execution linked',
          'source',v_job->>'workId','actorId',v_actor,
          'reports',v_evidence,'completions',v_completions)));
    v_state:=pg_catalog.jsonb_set(v_state,'{assets}',
      (select pg_catalog.jsonb_agg(case when a->>'id'=v_asset->>'id' then v_asset else a end order by ordinal)
       from pg_catalog.jsonb_array_elements(v_state->'assets') with ordinality as entries(a,ordinal)));
  elsif p_action='complete-job' then
    if v_job->>'status'<>'Execution linked' or v_job->>'linkedByActorId'=v_actor::text
      or v_deploy.state#>>'{workAcceptance,id}'<>v_job->>'workAcceptanceId'
      or v_deploy.state#>>'{workAcceptance,receipt}'<>'Accepted'
      or pg_catalog.jsonb_array_length(coalesce(v_job->'completionRefs','[]'::jsonb))=0
      or length(v_note)<20 then
      raise exception 'independent_service_completion_required' using errcode='42501'; end if;
    v_job:=v_job||pg_catalog.jsonb_build_object('status','Completed',
      'completedAt',v_now,'completedByActorId',v_actor,'completionReason',v_note);
  elsif p_action='resolve-request' then
    if v_job->>'status'<>'Completed' or v_request->>'status'<>'In progress'
      or coalesce(v_request->>'activePause','') not in ('','null')
      or length(trim(coalesce(p_input->>'resolution','')))<20 then
      raise exception 'reviewed_request_resolution_required' using errcode='23514'; end if;
    v_request:=v_request||pg_catalog.jsonb_build_object('status','Resolved',
      'resolution',trim(p_input->>'resolution'),
      'resolutionSource','Reviewed service job '||v_job_id,
      'resolutionEvidence',pg_catalog.jsonb_build_object('jobId',v_job_id,
        'workId',v_job->>'workId','reports',v_job->'evidence',
        'completions',v_job->'completionRefs'),
      'reviewedBy',v_actor,'resolvedAt',v_now);
  else
    if v_job->>'status'<>'Completed' or v_request->>'status'<>'Resolved'
      or v_request->>'reviewedBy'=v_actor::text or length(v_note)<20 then
      raise exception 'independent_request_close_required' using errcode='42501'; end if;
    v_request:=v_request||pg_catalog.jsonb_build_object('status','Closed',
      'closedByActorId',v_actor,'closedAt',v_now,'closeReason',v_note);
  end if;
  if p_action in ('link-execution','complete-job') then
    v_state:=pg_catalog.jsonb_set(v_state,'{jobs}',
      (select pg_catalog.jsonb_agg(case when j->>'id'=v_job_id then v_job else j end order by ordinal)
       from pg_catalog.jsonb_array_elements(v_state->'jobs') with ordinality as entries(j,ordinal)));
  else
    v_request:=pg_catalog.jsonb_set(v_request,'{history}',
      coalesce(v_request->'history','[]'::jsonb)||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('at',v_now,'action',p_action,'actorId',v_actor,
          'note',case when p_action='resolve-request' then p_input->>'resolution' else v_note end)));
    v_state:=pg_catalog.jsonb_set(v_state,'{requests}',
      (select pg_catalog.jsonb_agg(case when r->>'id'=v_request_id then v_request else r end order by ordinal)
       from pg_catalog.jsonb_array_elements(v_state->'requests') with ordinality as entries(r,ordinal)));
  end if;
  v_revision:=v_operate.decision_revision+1;
  v_state:=v_state||pg_catalog.jsonb_build_object('authorityRevision',v_revision,
    'events',coalesce(v_state->'events','[]'::jsonb)||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('id',gen_random_uuid(),'at',v_now,'commandId',p_command_id,
        'action',p_action,'actorId',v_actor,'membershipId',v_member.id,
        'sourceId',v_job_id,'note',v_note)));
  update d5o_hosted.connected_operate_states set decision_revision=v_revision,
    state=v_state,updated_at=v_now where workspace_id=v_workspace.id and work_id=v_parent_work.id;
  insert into d5o_hosted.connected_operate_events(workspace_id,work_id,decision_revision,
    command_id,action,actor_user_id,membership_id,deploy_revision,snapshot)
  values(v_workspace.id,v_parent_work.id,v_revision,p_command_id,p_action,
    v_actor,v_member.id,v_deploy.decision_revision,v_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_operate_receipts(workspace_id,command_id,work_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_parent_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_solution_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_due_date text, p_reason text, p_command_id text, p_expected_source_revision bigint, p_expected_decision_revision integer, p_solution_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_state d5o_hosted.prototype_states%rowtype;
  v_define d5o_hosted.connected_define_states%rowtype;
  v_control d5o_hosted.connected_solution_states%rowtype;
  v_receipt d5o_hosted.connected_solution_receipts%rowtype;
  v_raw jsonb;v_plan jsonb;v_option jsonb;v_requirement jsonb;
  v_policy jsonb;v_review jsonb;v_digest text;
  v_fingerprint text;v_next text;v_result jsonb;v_now timestamptz:=now();
  v_policy_id text;v_policy_version integer;v_approver_role text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('submit-solution','approve-solution','return-solution')
    or p_command_id is null or length(p_command_id) not between 8 and 120
    or p_expected_source_revision is null or p_expected_source_revision<1
    or p_expected_decision_revision is null or p_expected_decision_revision<0
    or p_solution_revision is null or p_solution_revision<1
    or length(coalesce(p_reason,''))>2000 then
    raise exception 'invalid_solution_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active' for share;
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,
    p_action,p_due_date,trim(coalesce(p_reason,'')),p_expected_source_revision,
    p_expected_decision_revision,p_solution_revision)::text);
  select * into v_receipt from d5o_hosted.connected_solution_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_state from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_control from d5o_hosted.connected_solution_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_state.revision is distinct from p_expected_source_revision
    or coalesce(v_control.decision_revision,0)<>p_expected_decision_revision then
    raise exception 'stale_state' using errcode='23505'; end if;
  select item into v_raw from pg_catalog.jsonb_array_elements(v_state.state_json->'records') item
    where item->>'id'=p_presentation_id and item->>'canonicalWorkId'=v_work.id::text;
  if v_raw is null or v_raw->>'phaseConfigurationVersionId' is distinct from
    v_work.configuration_version_id::text then
    raise exception 'source_identity_changed' using errcode='42501'; end if;
  select * into v_define from d5o_hosted.connected_define_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  if not found or v_define.status<>'Approved'
    or v_define.projection#>>'{developHandoff,status}'<>'accepted'
    or v_define.projection#>>'{developHandoff,revision}'<>
       v_define.definition_revision::text then
    raise exception 'accepted_define_basis_required' using errcode='23514'; end if;
  v_plan:=v_raw->'develop';
  if v_plan is null or (v_plan->>'revision')::integer is distinct from p_solution_revision
    or v_raw#>'{develop,review}' is not null then
    raise exception 'solution_revision_unavailable' using errcode='23514'; end if;
  v_digest:=d5o_hosted.connected_solution_digest_v1(v_plan);
  select p.payload into v_policy from d5o_hosted.connected_pricing_active a
    join d5o_hosted.connected_pricing_policies p on p.workspace_id=a.workspace_id
      and p.policy_id=a.policy_id and p.version=a.version
    where a.workspace_id=v_workspace.id and p.status='published'
      and (p.payload->>'effectiveFrom')::date<=v_now::date
      and (p.payload->>'effectiveTo' is null or
        (p.payload->>'effectiveTo')::date>=v_now::date);
  if v_policy is null then raise exception 'pricing_policy_unavailable' using errcode='23514'; end if;
  v_policy_id:=v_policy->>'id';v_policy_version:=(v_policy->>'version')::integer;
  v_approver_role:=coalesce(v_policy->>'solutionApproverRole','operations_leader');
  if v_approver_role not in ('admin','operations_leader') then
    raise exception 'pricing_policy_invalid' using errcode='23514'; end if;
  if p_action='submit-solution' then
    if v_member.role not in ('admin','project_manager','operations_leader')
      or p_due_date is null or p_due_date !~ '^\d{4}-\d{2}-\d{2}$'
      or (v_control.work_id is not null and
        (v_control.status='Submitted' or p_solution_revision<=v_control.solution_revision)) then
      raise exception 'solution_submit_denied' using errcode='42501'; end if;
    select item into v_option from pg_catalog.jsonb_array_elements(
      coalesce(v_plan->'options','[]'::jsonb)) item
      where item->>'id'=v_plan->>'selectedOptionId';
    if v_option is null or v_option->>'status'<>'Viable'
      or length(trim(coalesce(v_option->>'unmetRequirements','')))>0
      or length(trim(coalesce(v_plan->>'selectionRationale','')))=0
      or exists(select 1 from pg_catalog.jsonb_array_elements(
        coalesce(v_define.projection#>'{scopeControl,requirements}','[]'::jsonb)) r
        where r->>'state'='Confirmed' and not
          coalesce(v_option->'requirementIds','[]'::jsonb) ? (r->>'id')) then
      raise exception 'solution_infeasible' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.unnest(array['laborStrategy','procurementStrategy',
      'scheduleStrategy','safetyStrategy','qualityStrategy','riskMitigation']) field
      where length(trim(coalesce(v_plan->>field,'')))=0) then
      raise exception 'strategy_incomplete' using errcode='23514'; end if;
    v_review:=pg_catalog.jsonb_build_object('revision',p_solution_revision,
      'status','Submitted','dueDate',p_due_date,'submittedAt',v_now,
      'submittedByActorId',v_actor,'submittedByMembershipId',v_member.id,
      'approverRole',v_approver_role,'policyId',v_policy_id,
      'policyVersion',v_policy_version,'defineRevision',v_define.definition_revision);
    v_next:='Review solution revision '||p_solution_revision::text;
    if v_control.work_id is null then
      insert into d5o_hosted.connected_solution_states(workspace_id,work_id,
        source_digest,solution_revision,decision_revision,status,submitter,review,next_action)
      values(v_workspace.id,v_work.id,v_digest,p_solution_revision,1,'Submitted',
        v_actor,v_review,v_next);
    else
      update d5o_hosted.connected_solution_states set source_digest=v_digest,
        solution_revision=p_solution_revision,decision_revision=decision_revision+1,
        status='Submitted',submitter=v_actor,reviewer=null,review=v_review,
        next_action=v_next,updated_at=v_now
        where workspace_id=v_workspace.id and work_id=v_work.id;
    end if;
  else
    if v_control.status<>'Submitted' or v_control.solution_revision<>p_solution_revision
      or v_control.source_digest<>v_digest or v_actor=v_control.submitter
      or v_member.role<>v_control.review->>'approverRole'
      or v_policy_id is distinct from v_control.review->>'policyId'
      or v_policy_version is distinct from
        (v_control.review->>'policyVersion')::integer
      or length(trim(coalesce(p_reason,'')))<10 then
      raise exception 'independent_solution_review_required' using errcode='42501'; end if;
    v_review:=v_control.review||pg_catalog.jsonb_build_object(
      'status',case when p_action='approve-solution' then 'Approved' else 'Returned' end,
      'decidedAt',v_now,'decidedByActorId',v_actor,
      'decidedByMembershipId',v_member.id,'note',trim(p_reason));
    v_next:=case when p_action='approve-solution' then
      'Complete and submit detailed estimate' else 'Revise the selected solution' end;
    update d5o_hosted.connected_solution_states set
      decision_revision=decision_revision+1,
      status=case when p_action='approve-solution' then 'Approved' else 'Returned' end,
      reviewer=v_actor,review=v_review,next_action=v_next,updated_at=v_now
      where workspace_id=v_workspace.id and work_id=v_work.id;
  end if;
  select * into v_control from d5o_hosted.connected_solution_states
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_solution_events(workspace_id,work_id,decision_revision,
    command_id,action,solution_revision,actor_user_id,membership_id,authority_role,
    configuration_version_id,pricing_policy_id,pricing_policy_version,source_digest,reason)
  values(v_workspace.id,v_work.id,v_control.decision_revision,p_command_id,p_action,
    p_solution_revision,v_actor,v_member.id,v_member.role,v_work.configuration_version_id,
    v_policy_id,v_policy_version,v_digest,trim(coalesce(p_reason,'')));
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_solution_receipts(workspace_id,command_id,work_id,
    actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_support_document_command_internal_v1(p_workspace_key text, p_presentation_id text, p_action text, p_turnover_id text, p_kind text, p_evidence_id uuid, p_decision text, p_note text, p_command_id text, p_expected_source_revision bigint, p_expected_deploy_revision integer, p_expected_operate_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace d5o_hosted.workspaces%rowtype;
  v_member d5o_hosted.memberships%rowtype;v_work d5o_hosted.work_records%rowtype;
  v_raw d5o_hosted.prototype_states%rowtype;
  v_deploy d5o_hosted.connected_deploy_states%rowtype;
  v_operate d5o_hosted.connected_operate_states%rowtype;
  v_receipt d5o_hosted.connected_operate_receipts%rowtype;
  v_doc d5o_hosted.customer_decision_evidence%rowtype;
  v_basis jsonb;v_docs jsonb;v_item jsonb;v_state jsonb;v_result jsonb;
  v_fingerprint text;v_now timestamptz:=now();v_supersedes text;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('submit','review') or p_kind not in ('as-built','inspection')
    or p_evidence_id is null or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_source_revision is null or p_expected_deploy_revision is null
    or p_expected_operate_revision is null then
    raise exception 'invalid_support_document_command' using errcode='22023'; end if;
  select * into v_workspace from d5o_hosted.workspaces
    where workspace_key=p_workspace_key and status='active';
  if not found then raise exception 'workspace_forbidden' using errcode='42501'; end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace.id and actor_user_id=v_actor and status='active'
    for share;
  if not found then raise exception 'support_document_membership_required' using errcode='42501'; end if;
  if (p_action='submit' and v_member.role not in ('project_manager','field_supervisor'))
    or (p_action='review' and v_member.role<>'operations_leader') then
    raise exception 'support_document_authority_required' using errcode='42501'; end if;
  select w.* into v_work from d5o_hosted.work_records w
    join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id
      and l.work_id=w.id
    where w.workspace_id=v_workspace.id and l.presentation_id=p_presentation_id
    for update of w;
  if not found then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_presentation_id,p_action,p_turnover_id,p_kind,
    p_evidence_id,p_decision,trim(coalesce(p_note,'')),p_expected_source_revision,
    p_expected_deploy_revision,p_expected_operate_revision)::text);
  select * into v_receipt from d5o_hosted.connected_operate_receipts
    where workspace_id=v_workspace.id and command_id=p_command_id;
  if found then
    if v_receipt.work_id<>v_work.id or v_receipt.actor_user_id<>v_actor
      or v_receipt.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_receipt.result;
  end if;
  select * into v_raw from d5o_hosted.prototype_states
    where workspace_id=v_workspace.id and state_key='work' for share;
  select * into v_deploy from d5o_hosted.connected_deploy_states
    where workspace_id=v_workspace.id and work_id=v_work.id for share;
  select * into v_operate from d5o_hosted.connected_operate_states
    where workspace_id=v_workspace.id and work_id=v_work.id for update;
  if v_raw.revision is distinct from p_expected_source_revision
    or v_deploy.decision_revision is distinct from p_expected_deploy_revision
    or v_operate.decision_revision is distinct from p_expected_operate_revision then
    raise exception 'stale_support_document_basis' using errcode='23505'; end if;
  v_basis:=d5o_hosted.support_document_basis_v1(
    v_workspace.id,v_work.id,p_turnover_id,p_kind);
  if v_basis is null then
    raise exception 'accepted_support_obligation_required' using errcode='23514'; end if;
  select * into v_doc from d5o_hosted.customer_decision_evidence
    where id=p_evidence_id and workspace_id=v_workspace.id and work_id=v_work.id
      and purpose='support-'||p_kind and scope_id=p_turnover_id
      and scope_revision=(v_basis->>'turnoverRevision')::integer and basis=v_basis;
  if not found then raise exception 'exact_support_document_required' using errcode='23514'; end if;
  perform d5o_hosted.require_customer_decision_evidence_v1(
    v_workspace.id,v_work.id,p_evidence_id::text,'support-'||p_kind,
    p_turnover_id,(v_basis->>'turnoverRevision')::integer,v_basis);
  v_docs:=coalesce(v_operate.state->'documentationObligations','[]'::jsonb);
  if p_action='submit' then
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_docs) d
      where d->>'id'=p_evidence_id::text) then
      raise exception 'support_document_already_submitted' using errcode='23505'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(v_docs) d
      where d->>'turnoverId'=p_turnover_id and d->>'kind'=p_kind
        and d->>'status'='Submitted') then
      raise exception 'support_document_review_pending' using errcode='23514'; end if;
    select d->>'id' into v_supersedes from pg_catalog.jsonb_array_elements(v_docs) d
      where d->>'turnoverId'=p_turnover_id and d->>'kind'=p_kind
      order by d->>'submittedAt' desc limit 1;
    v_item:=pg_catalog.jsonb_build_object('id',p_evidence_id,
      'turnoverId',p_turnover_id,'kind',p_kind,'basis',v_basis,
      'status','Submitted','filename',v_doc.filename,
      'checksumSha256',v_doc.checksum_sha256,
      'uploadedAt',v_doc.uploaded_at,'uploadedByActorId',v_doc.uploaded_by,
      'submittedAt',v_now,'submittedByActorId',v_actor,
      'submittedByMembershipId',v_member.id,
      'supersedesId',v_supersedes,'note',trim(coalesce(p_note,'')));
    v_docs:=v_docs||pg_catalog.jsonb_build_array(v_item);
  else
    if p_decision not in ('Reviewed','Returned')
      or length(trim(coalesce(p_note,'')))<10 then
      raise exception 'support_document_review_reason_required' using errcode='23514'; end if;
    select d into v_item from pg_catalog.jsonb_array_elements(v_docs) d
      where d->>'id'=p_evidence_id::text and d->>'turnoverId'=p_turnover_id
        and d->>'kind'=p_kind and d->>'status'='Submitted';
    if v_item is null then
      raise exception 'current_support_document_review_required' using errcode='23514'; end if;
    if v_item->>'submittedByActorId'=v_actor::text
      or v_doc.uploaded_by=v_actor then
      raise exception 'independent_support_document_review_required'
        using errcode='42501'; end if;
    v_item:=v_item||pg_catalog.jsonb_build_object('status',p_decision,
      'reviewedAt',v_now,'reviewedByActorId',v_actor,
      'reviewedByMembershipId',v_member.id,'reviewReason',trim(p_note));
    v_docs:=(select pg_catalog.jsonb_agg(
      case when d->>'id'=p_evidence_id::text then v_item else d end order by ordinal)
      from pg_catalog.jsonb_array_elements(v_docs)
        with ordinality as entries(d,ordinal));
  end if;
  v_state:=v_operate.state||pg_catalog.jsonb_build_object(
    'documentationObligations',v_docs,
    'authorityRevision',v_operate.decision_revision+1,
    'events',coalesce(v_operate.state->'events','[]'::jsonb)
      ||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'id',gen_random_uuid(),'commandId',p_command_id,
        'fingerprint',v_fingerprint,'at',v_now,'actorId',v_actor,
        'membershipId',v_member.id,'action','support-document-'||p_action,
        'detail',p_turnover_id||' · '||p_kind||' · '||p_evidence_id::text)));
  update d5o_hosted.connected_operate_states set
    decision_revision=decision_revision+1,state=v_state,updated_at=v_now
    where workspace_id=v_workspace.id and work_id=v_work.id;
  insert into d5o_hosted.connected_operate_events(
    workspace_id,work_id,decision_revision,command_id,action,actor_user_id,
    membership_id,deploy_revision,snapshot)
  values(v_workspace.id,v_work.id,v_operate.decision_revision+1,p_command_id,
    'support-document-'||p_action,v_actor,v_member.id,
    v_deploy.decision_revision,v_state);
  v_result:=public.d5o_hosted_prototype_read_v1(p_workspace_key,'work');
  insert into d5o_hosted.connected_operate_receipts(
    workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(v_workspace.id,p_command_id,v_work.id,v_actor,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_suspend_member_v1(p_workspace_key text, p_admin_user_id uuid, p_admin_membership_id uuid, p_member_email text, p_expected_role text, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace uuid;
  v_target uuid;
  v_member d5o_hosted.memberships%rowtype;
  v_replay d5o_hosted.membership_assignment_events%rowtype;
  v_fingerprint text;
begin
  if current_setting('role', true) is distinct from 'service_role'
    or p_admin_user_id is null or p_admin_membership_id is null then
    raise exception 'server_admin_required' using errcode = '42501';
  end if;
  if p_workspace_key is null or p_member_email is null
    or length(trim(p_member_email)) not between 3 and 320
    or p_expected_role is null
    or p_command_id is null or length(p_command_id) not between 8 and 120 then
    raise exception 'invalid_membership_suspension' using errcode = '22023';
  end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id = w.id
    where w.workspace_key = p_workspace_key and w.status = 'active'
      and m.id = p_admin_membership_id and m.actor_user_id = p_admin_user_id
      and m.role = 'admin' and m.status = 'active';
  if v_workspace is null then raise exception 'admin_membership_required' using errcode = '42501'; end if;
  select u.id into v_target from auth.users u
    where lower(u.email) = lower(trim(p_member_email)) and u.email_confirmed_at is not null;
  if v_target is null then raise exception 'confirmed_member_missing' using errcode = '23503'; end if;
  if v_target = p_admin_user_id then raise exception 'self_suspension_denied' using errcode = '42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('d5o-member:' || v_workspace::text || ':' || v_target::text, 0));
  v_fingerprint := pg_catalog.md5('suspend:' || lower(trim(p_member_email)) || ':' || p_expected_role || ':' || p_admin_user_id::text);
  select * into v_replay from d5o_hosted.membership_assignment_events
    where workspace_id = v_workspace and command_id = p_command_id;
  if found then
    if v_replay.fingerprint <> v_fingerprint or v_replay.target_user_id <> v_target
      or v_replay.action <> 'suspended' then
      raise exception 'command_id_reused' using errcode = '23505';
    end if;
    return pg_catalog.jsonb_build_object('userId', v_target, 'role', v_replay.assigned_role,
      'action', 'suspended', 'replay', true);
  end if;
  select * into v_member from d5o_hosted.memberships
    where workspace_id = v_workspace and actor_user_id = v_target for update;
  if not found or v_member.role is distinct from p_expected_role
    or v_member.status is distinct from 'active' then
    raise exception 'stale_membership' using errcode = '23505';
  end if;
  if v_member.role in ('admin', 'field_worker') then
    raise exception 'protected_membership' using errcode = '42501';
  end if;
  update d5o_hosted.memberships set status = 'suspended' where id = v_member.id;
  insert into d5o_hosted.membership_assignment_events(workspace_id, command_id, fingerprint,
    actor_user_id, actor_membership_id, target_user_id, previous_role, assigned_role, action)
    values(v_workspace, p_command_id, v_fingerprint, p_admin_user_id,
      p_admin_membership_id, v_target, v_member.role, v_member.role, 'suspended');
  return pg_catalog.jsonb_build_object('userId', v_target, 'role', v_member.role, 'action', 'suspended');
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_workforce_command_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;v_member d5o_hosted.memberships%rowtype;
  v_state d5o_hosted.connected_workforce_states%rowtype;
  v_prior d5o_hosted.connected_workforce_commands%rowtype;
  v_profile d5o_hosted.connected_crew_profiles%rowtype;
  v_worker uuid;v_email text;v_person text;v_name text;v_quals text[];
  v_capacity numeric;v_id uuid;v_fingerprint text;v_result jsonb;
begin
  if current_setting('role',true)<>'authenticated' or v_actor is null
    or p_action not in ('save-person','bind-person','set-active')
    or pg_catalog.jsonb_typeof(p_input)<>'object'
    or length(coalesce(p_command_id,'')) not between 8 and 120
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'invalid_workforce_command' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    where w.workspace_key=p_workspace_key and w.status='active';
  select * into v_member from d5o_hosted.memberships
    where workspace_id=v_workspace and actor_user_id=v_actor
      and status='active' and role='admin' for share;
  if v_workspace is null or v_member.id is null then raise exception 'admin_workforce_required' using errcode='42501'; end if;
  insert into d5o_hosted.connected_workforce_states(workspace_id) values(v_workspace)
    on conflict do nothing;
  select * into v_state from d5o_hosted.connected_workforce_states
    where workspace_id=v_workspace for update;
  v_fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(
    p_workspace_key,p_action,p_input,p_expected_revision)::text);
  select * into v_prior from d5o_hosted.connected_workforce_commands
    where workspace_id=v_workspace and command_id=p_command_id;
  if found then
    if v_prior.actor_user_id<>v_actor or v_prior.fingerprint<>v_fingerprint then
      raise exception 'command_reuse_conflict' using errcode='23505'; end if;
    return v_prior.result; end if;
  if v_state.revision<>p_expected_revision then
    raise exception 'stale_workforce' using errcode='23505'; end if;

  if p_action='save-person' then
    v_person:=trim(coalesce(p_input->>'person',''));
    v_name:=trim(coalesce(p_input->>'displayName',''));
    v_capacity:=(p_input->>'weeklyCapacityHours')::numeric;
    select pg_catalog.array_agg(distinct trim(value)) into v_quals
      from pg_catalog.jsonb_array_elements_text(p_input->'qualifications');
    if length(v_person) not between 2 and 120
      or length(v_name) not between 2 and 120
      or cardinality(v_quals) not between 1 and 20
      or exists(select 1 from unnest(v_quals) q where length(q) not between 2 and 100)
      or v_capacity<=0 or v_capacity>80 then
      raise exception 'invalid_workforce_profile' using errcode='22023'; end if;
    if nullif(p_input->>'id','') is not null then
      v_id:=(p_input->>'id')::uuid;
      select * into v_profile from d5o_hosted.connected_crew_profiles
        where workspace_id=v_workspace and id=v_id for update;
      if not found or v_profile.person<>v_person then
        raise exception 'stable_person_identity_required' using errcode='23514'; end if;
      update d5o_hosted.connected_crew_profiles set display_name=v_name,
        qualifications=v_quals,weekly_capacity_hours=v_capacity,
        active=coalesce((p_input->>'active')::boolean,active),revision=revision+1
        where workspace_id=v_workspace and id=v_id;
      if p_input ? 'active' and v_profile.actor_user_id is not null then
        update d5o_hosted.crew_bindings set active=(p_input->>'active')::boolean
          where workspace_id=v_workspace and actor_user_id=v_profile.actor_user_id;
      end if;
    else
      insert into d5o_hosted.connected_crew_profiles(
        workspace_id,person,display_name,qualifications,weekly_capacity_hours)
        values(v_workspace,v_person,v_name,v_quals,v_capacity)
        returning id into v_id;
    end if;
  else
    v_id:=(p_input->>'id')::uuid;
    select * into v_profile from d5o_hosted.connected_crew_profiles
      where workspace_id=v_workspace and id=v_id for update;
    if not found then raise exception 'person_missing' using errcode='23503'; end if;
    if p_action='set-active' then
      update d5o_hosted.connected_crew_profiles set active=(p_input->>'active')::boolean,
        revision=revision+1 where workspace_id=v_workspace and id=v_id;
      if v_profile.actor_user_id is not null then
        update d5o_hosted.crew_bindings set active=(p_input->>'active')::boolean
          where workspace_id=v_workspace and actor_user_id=v_profile.actor_user_id;
      end if;
    else
      v_email:=lower(trim(coalesce(p_input->>'email','')));
      select id into v_worker from auth.users
        where lower(email)=v_email and email_confirmed_at is not null;
      if v_worker is null then raise exception 'confirmed_account_missing' using errcode='23503'; end if;
      if v_worker=v_actor or not v_profile.active or
        (v_profile.actor_user_id is not null and v_profile.actor_user_id<>v_worker) then
        raise exception 'worker_binding_conflict' using errcode='23505'; end if;
      if exists(select 1 from d5o_hosted.memberships
        where workspace_id=v_workspace and actor_user_id=v_worker
          and role<>'field_worker') or exists(select 1 from d5o_hosted.crew_bindings
        where workspace_id=v_workspace and
          (actor_user_id=v_worker or person=v_profile.person)
          and (actor_user_id<>v_worker or person<>v_profile.person)) then
        raise exception 'worker_binding_conflict' using errcode='23505'; end if;
      insert into d5o_hosted.memberships(workspace_id,actor_user_id,role,status)
        values(v_workspace,v_worker,'field_worker','active')
        on conflict(workspace_id,actor_user_id) do update set status='active'
          where d5o_hosted.memberships.role='field_worker';
      insert into d5o_hosted.crew_bindings(workspace_id,actor_user_id,person,active)
        values(v_workspace,v_worker,v_profile.person,true)
        on conflict(workspace_id,actor_user_id) do update set active=true;
      update d5o_hosted.connected_crew_profiles set actor_user_id=v_worker,
        revision=revision+1 where workspace_id=v_workspace and id=v_id;
      insert into d5o_hosted.crew_binding_events(
        workspace_id,actor_user_id,worker_user_id,person,action)
        values(v_workspace,v_actor,v_worker,v_profile.person,'bound');
    end if;
  end if;
  update d5o_hosted.connected_workforce_states set revision=revision+1
    where workspace_id=v_workspace;
  select pg_catalog.jsonb_build_object('id',id,'person',person,
    'displayName',display_name,'qualifications',qualifications,
    'weeklyCapacityHours',weekly_capacity_hours,'active',active,
    'profileRevision',revision,'workerUserId',actor_user_id)
    into v_result from d5o_hosted.connected_crew_profiles
    where workspace_id=v_workspace and id=v_id;
  v_result:=v_result||pg_catalog.jsonb_build_object('revision',v_state.revision+1);
  insert into d5o_hosted.connected_workforce_commands(
    workspace_id,command_id,actor_user_id,membership_id,action,fingerprint,result)
    values(v_workspace,p_command_id,v_actor,v_member.id,p_action,v_fingerprint,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_hosted_workforce_impact_command_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_schedule_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid();v_workspace uuid;
  v_schedule d5o_hosted.connected_schedule_states%rowtype;
  v_existing boolean;v_urgent boolean;
begin
  if current_setting('role',true) is distinct from 'authenticated' or v_actor is null
    or p_workspace_key is null or p_action not in
      ('save-person','bind-person','set-active','correct-binding')
    or pg_catalog.jsonb_typeof(p_input)<>'object' then
    raise exception 'invalid_workforce_impact_command' using errcode='22023'; end if;
  select w.id into v_workspace from d5o_hosted.workspaces w
    join d5o_hosted.memberships m on m.workspace_id=w.id
      and m.actor_user_id=v_actor and m.role='admin' and m.status='active'
    where w.workspace_key=p_workspace_key and w.status='active';
  if v_workspace is null then
    raise exception 'admin_membership_required' using errcode='42501'; end if;
  v_existing:=nullif(p_input->>'id','') is not null;
  v_urgent:=p_action='set-active' and p_input->>'active'='false';
  -- Existing command receipts still govern replay. A changed schedule may not
  -- make an already-committed command appear to have failed.
  if not exists(select 1 from d5o_hosted.connected_workforce_commands c
      where c.workspace_id=v_workspace and c.command_id=p_command_id)
    and not exists(select 1 from d5o_hosted.admin_binding_corrections c
      where c.workspace_id=v_workspace and c.command_id=p_command_id) then
    if v_existing and not v_urgent and p_expected_schedule_revision is null then
      raise exception 'schedule_impact_review_required' using errcode='23514'; end if;
    if not v_urgent and v_existing then
      select * into v_schedule from d5o_hosted.connected_schedule_states
        where workspace_id=v_workspace for share;
      if (not found and p_expected_schedule_revision <> 0)
        or (found and v_schedule.decision_revision is distinct from p_expected_schedule_revision) then
        raise exception 'stale_schedule_impact' using errcode='23505'; end if;
    end if;
  end if;
  if p_action='correct-binding' then
    return public.d5o_hosted_correct_worker_binding_v1(p_workspace_key,
      (p_input->>'id')::uuid,p_input->>'email',p_input->>'reason',
      p_expected_revision,p_command_id);
  end if;
  return public.d5o_hosted_workforce_command_v1(p_workspace_key,p_action,
    p_input,p_command_id,p_expected_revision);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_internal_design_rate_my_review_v1(p_workspace_key text, p_rate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text;
 rate d5o_hosted.design_internal_rates%rowtype; enabled_at timestamptz;
 chosen uuid; enabled boolean; valued_minor bigint;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name<>'admin' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select * into rate from d5o_hosted.design_internal_rates
  where workspace_id=ws and id=p_rate_id;
 if rate.id is null or rate.status<>'Prepared' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=ws and category='internal_design_rate';
 enabled:=enabled_at is not null and rate.created_at>=enabled_at;
 valued_minor:=pg_catalog.ceil(rate.base_rate_minor::numeric *
  (10000+rate.burden_basis_points)::numeric / 10000)::bigint;
 if enabled then
  chosen:=d5o_hosted.spending_delegate_selected_workspace_v1(ws,'internal_design_rate',
   'admin',valued_minor,rate.currency,rate.prepared_by,rate.effective_until); end if;
 return pg_catalog.jsonb_build_object('pending',true,'configured',enabled,
  'fullyBurdenedRateMinor',valued_minor,
  'canReview',case when enabled then coalesce(chosen=actor,false)
   else rate.prepared_by<>actor end,
  'held',enabled and chosen is null,
  'route',case when enabled and chosen is null then 'No eligible internal-rate delegate or sponsor is configured.'
   when enabled and chosen=actor then 'This exact internal-rate review is assigned to you.'
   when enabled then 'Waiting for the configured independent internal-rate reviewer.'
   else 'Existing independent administrator review applies to this earlier rate.' end);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_labor_authority_actions_pre_delegation_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text; item record; source jsonb;
 parent d5o_hosted.purchase_authorities%rowtype;
 approved d5o_hosted.labor_authorities%rowtype; pending d5o_hosted.labor_authorities%rowtype;
 actions jsonb:='[]'::jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name not in ('admin','project_manager') then return actions; end if;
 for item in select w.id,w.title,w.created_by,l.presentation_id,coalesce(p.revision,0) revision
  from d5o_hosted.work_records w
  join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
  left join d5o_hosted.labor_authority_positions p on p.workspace_id=w.workspace_id and p.work_id=w.id
  where w.workspace_id=ws loop
  source:=d5o_hosted.purchase_basis_v1(ws,item.id);
  if source is null then continue; end if;
  select * into parent from d5o_hosted.purchase_authorities
   where workspace_id=ws and work_id=item.id and status='Approved'
    and source_digest=source->>'digest' and current_date between valid_from and valid_until
   order by created_at desc limit 1;
  if parent.id is null then continue; end if;
  select * into approved from d5o_hosted.labor_authorities
   where workspace_id=ws and work_id=item.id and status='Approved'
    and parent_authority_id=parent.id and source_digest=source->>'digest'
    and current_date between valid_from and valid_until
   order by created_at desc limit 1;
  select * into pending from d5o_hosted.labor_authorities
   where workspace_id=ws and work_id=item.id and status='Prepared'
    and parent_authority_id=parent.id and source_digest=source->>'digest'
   order by created_at desc limit 1;
  if pending.id is not null and role_name='admin' and pending.prepared_by<>actor then
   actions:=actions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
    'kind','Review field labor authority','phase','Labor','focus','review',
    'workId',item.presentation_id,'workTitle',item.title,'revision',item.revision,
    'decisionId',pending.id,'status','Prepared','dueDate',pending.valid_until,
    'ownership','Independent workspace administrator',
    'blocker','Review the Work and labor caps, rate source, scope, conditions and expiry.'));
  elsif approved.id is null and pending.id is null and role_name='project_manager' and item.created_by=actor
   and source->>'kind'='Awarded work' then
   actions:=actions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
    'kind','Prepare field labor authority','phase','Labor','focus','prepare',
    'workId',item.presentation_id,'workTitle',item.title,'revision',item.revision,
    'status','Preparation','position','preparation','ownership','Assigned project manager',
    'blocker','Published worker assignments require a reviewed rate and labor allocation. Draft booking remains available.'));
  end if;
 end loop;
 return actions;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_labor_authority_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare raw jsonb; entry jsonb; output jsonb:='[]'::jsonb; route jsonb;
begin
 raw:=public.d5o_labor_authority_actions_pre_delegation_v1(p_workspace_key);
 for entry in select value from pg_catalog.jsonb_array_elements(raw) loop
  if entry->>'kind'='Review field labor authority' then
   route:=public.d5o_field_labor_my_review_v1(p_workspace_key,entry->>'workId',
    (entry->>'decisionId')::uuid);
   if not coalesce((route->>'canReview')::boolean,false) then continue; end if;
  end if;
  output:=output||pg_catalog.jsonb_build_array(entry);
 end loop;
 return output;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_labor_authority_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws d5o_hosted.workspaces%rowtype; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; parent d5o_hosted.purchase_authorities%rowtype;
 authority d5o_hosted.labor_authorities%rowtype; prior d5o_hosted.labor_authorities%rowtype;
 existing d5o_hosted.labor_authority_receipts%rowtype; source jsonb; fp text; result jsonb;
 rev integer; used bigint;
begin
 if current_setting('role',true)<>'authenticated' or actor is null
  or p_action not in ('prepare','approve','return','revoke')
  or pg_catalog.jsonb_typeof(p_input)<>'object'
  or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then
  raise exception 'invalid_labor_authority_command' using errcode='22023'; end if;
 select * into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws.id
  and actor_user_id=actor and status='active' for share;
 select w.* into work from d5o_hosted.work_records w
  join d5o_hosted.work_identity_links l on l.workspace_id=w.workspace_id and l.work_id=w.id
  where w.workspace_id=ws.id and l.presentation_id=p_presentation_id for update of w;
 if member.id is null or work.id is null then raise exception 'labor_scope_denied' using errcode='42501'; end if;
 fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,
  p_expected_revision,p_expected_source_digest)::text);
 select * into existing from d5o_hosted.labor_authority_receipts
  where workspace_id=ws.id and command_id=p_command_id;
 if found then
  if existing.work_id<>work.id or existing.actor_user_id<>actor or existing.fingerprint<>fp then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return existing.result;
 end if;
 insert into d5o_hosted.labor_authority_positions(workspace_id,work_id)
  values(ws.id,work.id) on conflict do nothing;
 select revision into rev from d5o_hosted.labor_authority_positions
  where workspace_id=ws.id and work_id=work.id for update;
 if rev<>p_expected_revision then raise exception 'stale_labor_authority_revision' using errcode='23505'; end if;
 source:=d5o_hosted.purchase_basis_v1(ws.id,work.id);
 if source is null or source->>'digest' is distinct from p_expected_source_digest then
  raise exception 'labor_authority_source_changed' using errcode='23514'; end if;
 select * into parent from d5o_hosted.purchase_authorities
  where workspace_id=ws.id and work_id=work.id and status='Approved'
   and source_digest=source->>'digest' and current_date between valid_from and valid_until
  order by created_at desc limit 1 for update;
 if parent.id is null then raise exception 'current_work_economic_authority_required' using errcode='23514'; end if;
 if p_action='prepare' then
  if member.role<>'project_manager' or work.created_by<>actor then
   raise exception 'labor_authority_preparer_required' using errcode='42501'; end if;
  if coalesce(p_input->>'capMinor','') !~ '^[1-9][0-9]*$'
   or coalesce(p_input->>'rateMinor','') !~ '^[1-9][0-9]*$'
   or coalesce(p_input->>'validFrom','') !~ '^\d{4}-\d{2}-\d{2}$'
   or coalesce(p_input->>'validUntil','') !~ '^\d{4}-\d{2}-\d{2}$'
   or length(trim(coalesce(p_input->>'rateVersion',''))) not between 4 and 120
   or length(trim(coalesce(p_input->>'rateSource',''))) not between 8 and 500
   or length(trim(coalesce(p_input->>'rateBasis',''))) not between 10 and 1000
   or length(trim(coalesce(p_input->>'scope',''))) not between 10 and 2000
   or length(trim(coalesce(p_input->>'conditions',''))) not between 10 and 2000 then
   raise exception 'labor_rate_and_scope_required' using errcode='22023'; end if;
  if (p_input->>'validFrom')::date>(p_input->>'validUntil')::date
   or (p_input->>'validUntil')::date<current_date
   or (p_input->>'capMinor')::bigint>parent.parent_cap_minor
   or (p_input->>'validFrom')::date<parent.valid_from
   or (p_input->>'validUntil')::date>parent.valid_until then
   raise exception 'labor_authority_cap_or_dates_invalid' using errcode='23514'; end if;
  if exists(select 1 from d5o_hosted.labor_authorities
   where workspace_id=ws.id and work_id=work.id and status='Approved') then
   raise exception 'active_labor_authority_exists' using errcode='23514'; end if;
  if p_input ? 'supersedesId' and nullif(p_input->>'supersedesId','') is not null then
   select * into prior from d5o_hosted.labor_authorities
    where id=(p_input->>'supersedesId')::uuid and workspace_id=ws.id and work_id=work.id;
   if prior.id is null or prior.status not in ('Returned','Revoked') then
    raise exception 'returned_or_revoked_labor_authority_required' using errcode='23514'; end if;
  end if;
  insert into d5o_hosted.labor_authorities(workspace_id,work_id,parent_authority_id,status,
   currency,cap_minor,rate_minor,rate_version,rate_source,rate_basis,scope,conditions,
   valid_from,valid_until,source_digest,prepared_by,supersedes_id)
   values(ws.id,work.id,parent.id,'Prepared','USD',(p_input->>'capMinor')::bigint,
    (p_input->>'rateMinor')::bigint,trim(p_input->>'rateVersion'),trim(p_input->>'rateSource'),
    trim(p_input->>'rateBasis'),trim(p_input->>'scope'),trim(p_input->>'conditions'),
    (p_input->>'validFrom')::date,(p_input->>'validUntil')::date,source->>'digest',actor,prior.id)
   returning * into authority;
 else
  if member.role<>'admin' then raise exception 'independent_labor_authority_required' using errcode='42501'; end if;
  select * into authority from d5o_hosted.labor_authorities
   where id=(p_input->>'authorityId')::uuid and workspace_id=ws.id and work_id=work.id for update;
  if authority.id is null or length(trim(coalesce(p_input->>'reason','')))<10 then
   raise exception 'labor_authority_and_reason_required' using errcode='23514'; end if;
  if p_action='revoke' then
   if authority.status<>'Approved' then raise exception 'approved_labor_authority_required' using errcode='23514'; end if;
  elsif authority.status<>'Prepared' or authority.prepared_by=actor then
   raise exception 'independent_labor_authority_required' using errcode='42501'; end if;
  if p_action='approve' then
   if authority.parent_authority_id<>parent.id or authority.source_digest<>source->>'digest'
    or current_date not between authority.valid_from and authority.valid_until then
    raise exception 'labor_authority_source_changed' using errcode='23514'; end if;
   if exists(select 1 from d5o_hosted.labor_authorities
     where workspace_id=ws.id and work_id=work.id and status='Approved') then
    raise exception 'active_labor_authority_exists' using errcode='23514'; end if;
   used:=d5o_hosted.labor_exposure_v1(ws.id,work.id);
   if used>authority.cap_minor then raise exception 'labor_sublimit_below_commitments' using errcode='23514'; end if;
  end if;
  update d5o_hosted.labor_authorities set
   status=case p_action when 'approve' then 'Approved' when 'return' then 'Returned' else 'Revoked' end,
   reviewed_by=actor,review_reason=trim(p_input->>'reason'),decided_at=now() where id=authority.id;
 end if;
 update d5o_hosted.labor_authority_positions set revision=revision+1
  where workspace_id=ws.id and work_id=work.id;
 insert into d5o_hosted.labor_authority_events(workspace_id,work_id,revision,action,command_id,
  actor_user_id,membership_id,subject_id,basis)
  values(ws.id,work.id,rev+1,p_action,p_command_id,actor,member.id,authority.id,
   pg_catalog.jsonb_build_object('input',p_input,'source',source,'parentAuthorityId',parent.id));
 result:=pg_catalog.jsonb_build_object('revision',rev+1,'subjectId',authority.id,
  'status',case p_action when 'prepare' then 'Prepared' when 'approve' then 'Approved'
   when 'return' then 'Returned' else 'Revoked' end);
 insert into d5o_hosted.labor_authority_receipts(workspace_id,command_id,work_id,
  actor_user_id,fingerprint,result) values(ws.id,p_command_id,work.id,actor,fp,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_labor_authority_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; role_name text; source jsonb;
 parent d5o_hosted.purchase_authorities%rowtype; labor d5o_hosted.labor_authorities%rowtype;
 used bigint; design_used bigint; po_used bigint; sub_used bigint;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'labor_scope_denied' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 if w is null or role_name not in ('admin','project_manager','operations_leader','billing_commercial_lead') then
  raise exception 'labor_scope_denied' using errcode='42501'; end if;
 source:=d5o_hosted.purchase_basis_v1(ws,w);
 select * into parent from d5o_hosted.purchase_authorities
  where workspace_id=ws and work_id=w and status='Approved'
   and source_digest=source->>'digest' and current_date between valid_from and valid_until
  order by created_at desc limit 1;
 select * into labor from d5o_hosted.labor_authorities
  where workspace_id=ws and work_id=w and status='Approved'
   and parent_authority_id=parent.id and source_digest=source->>'digest'
   and current_date between valid_from and valid_until
  order by created_at desc limit 1;
 used:=d5o_hosted.labor_exposure_v1(ws,w);
 select coalesce(sum(amount_minor),0) into design_used from d5o_hosted.design_spend_commitments
  where workspace_id=ws and work_id=w and status='Approved';
 select coalesce(sum(amount_minor),0) into po_used from d5o_hosted.purchase_reservations
  where workspace_id=ws and work_id=w and status='Reserved';
 select coalesce(sum(amount_minor),0) into sub_used from d5o_hosted.subcontract_reservations
  where workspace_id=ws and work_id=w;
 return pg_catalog.jsonb_build_object(
  'revision',coalesce((select revision from d5o_hosted.labor_authority_positions
    where workspace_id=ws and work_id=w),0),
  'source',source,'parentAuthorityId',parent.id,'parentCapMinor',parent.parent_cap_minor,
  'parentRemainingMinor',case when parent.id is null then null
    else parent.parent_cap_minor-design_used-po_used-sub_used-used end,
  'laborAuthorityId',labor.id,'laborCapMinor',labor.cap_minor,
  'laborRemainingMinor',case when labor.id is null then null else labor.cap_minor-used end,
  'laborExposureMinor',used,'designConsumedMinor',design_used,
  'purchaseConsumedMinor',po_used,'subcontractConsumedMinor',sub_used,
  'authorities',coalesce((select pg_catalog.jsonb_agg(to_jsonb(a) order by a.created_at)
    from d5o_hosted.labor_authorities a where a.workspace_id=ws and a.work_id=w),'[]'::jsonb),
  'reservations',coalesce((select pg_catalog.jsonb_agg(
    to_jsonb(r)||pg_catalog.jsonb_build_object(
     'reviewedHours',coalesce((select sum(latest.reviewed_hours) from (
       select distinct on (a.report_id) a.report_id,a.reviewed_hours
       from d5o_hosted.labor_actuals a where a.reservation_id=r.id
       order by a.report_id,a.report_revision desc) latest),0),
     'incurredMinor',coalesce((select sum(latest.amount_minor) from (
       select distinct on (a.report_id) a.report_id,a.amount_minor
       from d5o_hosted.labor_actuals a where a.reservation_id=r.id
       order by a.report_id,a.report_revision desc) latest),0))
    order by r.approved_at) from d5o_hosted.labor_reservations r
    where r.workspace_id=ws and r.work_id=w),'[]'::jsonb),
  'actuals',coalesce((select pg_catalog.jsonb_agg(to_jsonb(a) order by a.reviewed_at)
    from d5o_hosted.labor_actuals a where a.workspace_id=ws and a.work_id=w),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_outlook_assessment_my_review_v1(p_workspace_key text, p_presentation_id text, p_assessment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; role_name text;
 assessment d5o_hosted.outlook_assessments%rowtype; enabled_at timestamptz; enabled boolean; chosen uuid;
 current_source boolean;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name<>'billing_commercial_lead' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 select * into assessment from d5o_hosted.outlook_assessments
  where workspace_id=ws and work_id=w and id=p_assessment_id;
 if assessment.id is null or assessment.status<>'Prepared' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 current_source:=assessment.source_digest=(d5o_hosted.outlook_source_v1(ws,w)->>'digest');
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=ws and category='outlook_assessment';
 enabled:=enabled_at is not null and assessment.created_at>=enabled_at;
 if enabled then
  chosen:=d5o_hosted.outlook_reviewer_selected_v1(ws,w,assessment.prepared_by,current_date); end if;
 return pg_catalog.jsonb_build_object('pending',true,'configured',enabled,
  'canReview',current_source and case when enabled then coalesce(chosen=actor,false)
   else assessment.prepared_by<>actor end,
  'held',enabled and chosen is null,
  'route',case when not current_source then 'This assessment source changed. Refresh the Work outlook before reviewing.'
   when enabled and chosen is null then 'No eligible independent cost-outlook reviewer or sponsor is configured.'
   when enabled and chosen=actor then 'This exact cost-outlook assessment is assigned to you.'
   when enabled then 'Waiting for the configured independent cost-outlook reviewer.'
   else 'Existing independent Finance review applies to this earlier assessment.' end);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_purchase_authority_actions_pre_delegation_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text; item record; source jsonb;
 current_authority d5o_hosted.purchase_authorities%rowtype; pending d5o_hosted.purchase_authorities%rowtype;
 actions jsonb:='[]'::jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name not in ('admin','project_manager') then return actions; end if;
 for item in select w.id,w.title,w.created_by,l.presentation_id,coalesce(p.revision,0) revision
  from d5o_hosted.work_records w
  join d5o_hosted.work_identity_links l on l.work_id=w.id and l.workspace_id=w.workspace_id
  left join d5o_hosted.purchase_authority_positions p on p.work_id=w.id and p.workspace_id=w.workspace_id
  where w.workspace_id=ws and exists(select 1 from d5o_hosted.connected_estimate_states e
   where e.workspace_id=ws and e.work_id=w.id and e.status='Approved') loop
  source:=d5o_hosted.purchase_basis_v1(ws,item.id);
  if source is null then continue; end if;
  if exists(select 1 from d5o_hosted.graybar_states g
   cross join lateral pg_catalog.jsonb_array_elements(coalesce(g.state->'orders','[]'::jsonb)) historical
   where g.workspace_id=ws and g.work_id=item.id
    and historical->>'status' in ('Approved','Test submitted','Acknowledged')
    and not exists(select 1 from d5o_hosted.purchase_reservations r
     where r.workspace_id=ws and r.work_id=item.id and r.order_id=historical->>'id')) then
   if role_name='project_manager' and item.created_by=actor then
    actions:=actions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Historical PO authority transition','phase','Procurement','focus','authority-legacy',
     'workId',item.presentation_id,'workTitle',item.title,'revision',item.revision,
     'status','Waiting','position','waiting','ownership','Workspace administrator',
     'blocker','An earlier approved PO has no reviewed Work reservation. Historical costs remain; new purchasing waits for a governed transition.'));
   end if;
   continue;
  end if;
  select * into current_authority from d5o_hosted.purchase_authorities
   where workspace_id=ws and work_id=item.id and status='Approved' and source_digest=source->>'digest'
    and current_date between valid_from and valid_until order by created_at desc limit 1;
  select * into pending from d5o_hosted.purchase_authorities
   where workspace_id=ws and work_id=item.id and status='Prepared' and source_digest=source->>'digest'
   order by created_at desc limit 1;
  if pending.id is not null and role_name='admin' and pending.prepared_by<>actor then
   actions:=actions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
    'kind','Review Work economic authority','phase','Procurement','focus','authority-review',
    'workId',item.presentation_id,'workTitle',item.title,'revision',item.revision,
    'decisionId',pending.id,'status','Prepared','dueDate',pending.valid_until,
    'ownership','Independent workspace administrator',
    'blocker','Review exact Work and purchasing limits, funding source, conditions and expiry.'));
  elsif current_authority.id is null and pending.id is null and role_name='project_manager' and item.created_by=actor then
   actions:=actions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
    'kind','Prepare Work economic authority','phase','Procurement','focus','authority-prepare',
    'workId',item.presentation_id,'workTitle',item.title,'revision',item.revision,
    'status','Preparation','ownership','Assigned project manager',
    'blocker','Prepare a reviewed Work cap and applicable category allocation; a draft grants no spending permission.'));
  end if;
 end loop;
 return actions;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_purchase_authority_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare raw jsonb; entry jsonb; output jsonb:='[]'::jsonb; route jsonb;
begin
 raw:=public.d5o_purchase_authority_actions_pre_delegation_v1(p_workspace_key);
 for entry in select value from pg_catalog.jsonb_array_elements(raw) loop
  if entry->>'focus'='authority-review' then
   route:=public.d5o_spending_delegate_my_review_v1(p_workspace_key,entry->>'workId',
    'work_authority',(entry->>'decisionId')::uuid);
   if not coalesce((route->>'canReview')::boolean,false) then continue; end if;
  end if;
  output:=output||pg_catalog.jsonb_build_array(entry);
 end loop;
 return output;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_purchase_authority_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws d5o_hosted.workspaces%rowtype; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; pos d5o_hosted.purchase_authority_positions%rowtype;
 authority d5o_hosted.purchase_authorities%rowtype; prior d5o_hosted.purchase_authorities%rowtype;
 receipt d5o_hosted.purchase_authority_receipts%rowtype; source jsonb; fp text; result jsonb;
 next_rev integer; subject uuid; design_used bigint; purchase_used bigint; current_bom jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null
  or p_action not in ('prepare','approve','return','revoke')
  or pg_catalog.jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then
  raise exception 'invalid_purchase_authority_command' using errcode='22023'; end if;
 select * into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws.id and actor_user_id=actor and status='active' for share;
 select w.* into work from d5o_hosted.work_records w join d5o_hosted.work_identity_links l
  on l.workspace_id=w.workspace_id and l.work_id=w.id
  where w.workspace_id=ws.id and l.presentation_id=p_presentation_id for update of w;
 if member.id is null or work.id is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,p_expected_revision,p_expected_source_digest)::text);
 select * into receipt from d5o_hosted.purchase_authority_receipts where workspace_id=ws.id and command_id=p_command_id;
 if found then
  if receipt.work_id<>work.id or receipt.actor_user_id<>actor or receipt.fingerprint<>fp then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return receipt.result; end if;
 insert into d5o_hosted.purchase_authority_positions(workspace_id,work_id) values(ws.id,work.id) on conflict do nothing;
 select * into pos from d5o_hosted.purchase_authority_positions where workspace_id=ws.id and work_id=work.id for update;
 if pos.revision<>p_expected_revision then raise exception 'stale_purchase_authority_revision' using errcode='23505'; end if;
 source:=d5o_hosted.purchase_basis_v1(ws.id,work.id);
 if p_action<>'revoke' and (source is null or source->>'digest' is distinct from p_expected_source_digest) then
  raise exception 'purchase_authority_source_changed' using errcode='23514'; end if;
 if p_action='prepare' then
  if member.role<>'project_manager' or work.created_by<>actor then
   raise exception 'purchase_authority_preparer_required' using errcode='42501'; end if;
  if coalesce(p_input->>'parentCapMinor','') !~ '^[1-9][0-9]*$'
   or coalesce(p_input->>'purchaseCapMinor','') !~ '^(0|[1-9][0-9]*)$'
   or coalesce(p_input->>'validFrom','') !~ '^\d{4}-\d{2}-\d{2}$'
   or coalesce(p_input->>'validUntil','') !~ '^\d{4}-\d{2}-\d{2}$'
   or length(trim(coalesce(p_input->>'purchasingEntity',''))) not between 4 and 200
   or length(trim(coalesce(p_input->>'graybarAccountReference',''))) not between 3 and 200
   or length(trim(coalesce(p_input->>'scope',''))) not between 10 and 2000
   or length(trim(coalesce(p_input->>'fundingSource',''))) not between 8 and 1000
   or length(trim(coalesce(p_input->>'sourceReference',''))) not between 5 and 500
   or length(trim(coalesce(p_input->>'conditions',''))) < 10 then
   raise exception 'purchase_authority_basis_invalid' using errcode='22023'; end if;
  if (p_input->>'purchaseCapMinor')::bigint>(p_input->>'parentCapMinor')::bigint
   or (p_input->>'validFrom')::date>(p_input->>'validUntil')::date
   or (p_input->>'validUntil')::date<current_date then
   raise exception 'purchase_authority_cap_or_dates_invalid' using errcode='23514'; end if;
  select state->'bom' into current_bom from d5o_hosted.graybar_states
   where workspace_id=ws.id and work_id=work.id for share;
  if (p_input->>'purchaseCapMinor')::bigint>0 and current_bom->>'status' is distinct from 'Approved' then raise exception 'approved_design_bom_required' using errcode='23514'; end if;
  if exists(select 1 from d5o_hosted.graybar_states g
   cross join lateral pg_catalog.jsonb_array_elements(coalesce(g.state->'orders','[]'::jsonb)) historical
   where g.workspace_id=ws.id and g.work_id=work.id
    and historical->>'status' in ('Approved','Test submitted','Acknowledged')
    and not exists(select 1 from d5o_hosted.purchase_reservations r
     where r.workspace_id=ws.id and r.work_id=work.id and r.order_id=historical->>'id')) then
   raise exception 'legacy_purchase_transition_required' using errcode='23514'; end if;
  if exists(select 1 from d5o_hosted.purchase_authorities where workspace_id=ws.id and work_id=work.id
   and status='Approved' and source_digest=source->>'digest' and valid_until>=current_date) then
   raise exception 'active_purchase_authority_exists' using errcode='23514'; end if;
  if p_input ? 'supersedesId' then
   select * into prior from d5o_hosted.purchase_authorities where id=(p_input->>'supersedesId')::uuid
    and workspace_id=ws.id and work_id=work.id;
   if prior.id is null or not (prior.status in ('Returned','Revoked')
    or prior.status='Approved' and prior.valid_until<current_date) then
    raise exception 'returned_revoked_or_expired_authority_required' using errcode='23514'; end if;
  end if;
  insert into d5o_hosted.purchase_authorities(workspace_id,work_id,status,parent_cap_minor,purchasing_cap_minor,subcontract_enabled,
   currency,purchasing_entity,graybar_account_reference,bom_id,scope,conditions,funding_source,source_reference,valid_from,valid_until,source_digest,source_snapshot,
   prepared_by,supersedes_id)
   values(ws.id,work.id,'Prepared',(p_input->>'parentCapMinor')::bigint,(p_input->>'purchaseCapMinor')::bigint,coalesce((p_input->>'subcontractEnabled')::boolean,false),
    'USD',trim(p_input->>'purchasingEntity'),trim(p_input->>'graybarAccountReference'),
    current_bom->>'id',trim(p_input->>'scope'),trim(p_input->>'conditions'),trim(p_input->>'fundingSource'),
    trim(p_input->>'sourceReference'),(p_input->>'validFrom')::date,(p_input->>'validUntil')::date,
    source->>'digest',source,actor,prior.id) returning * into authority;
 else
  if member.role<>'admin' then raise exception 'independent_purchasing_authority_required' using errcode='42501'; end if;
  select * into authority from d5o_hosted.purchase_authorities
   where id=(p_input->>'authorityId')::uuid and workspace_id=ws.id and work_id=work.id for update;
  if authority.id is null or length(trim(coalesce(p_input->>'reason',''))) < 10 then
   raise exception 'purchase_authority_and_reason_required' using errcode='23514'; end if;
  if p_action='revoke' then
   if authority.status<>'Approved' then raise exception 'approved_purchase_authority_required' using errcode='23514'; end if;
  elsif authority.status<>'Prepared' or authority.prepared_by=actor then
   raise exception 'independent_purchasing_authority_required' using errcode='42501';
  end if;
  if p_action='approve' then
   select state->'bom' into current_bom from d5o_hosted.graybar_states
    where workspace_id=ws.id and work_id=work.id for share;
   if authority.purchasing_cap_minor>0 and (authority.bom_id is distinct from current_bom->>'id' or current_bom->>'status' is distinct from 'Approved') then
    raise exception 'purchase_authority_bom_changed' using errcode='23514'; end if;
   if authority.source_digest<>source->>'digest' or authority.valid_until<current_date
    or exists(select 1 from d5o_hosted.purchase_authorities where workspace_id=ws.id and work_id=work.id
     and status='Approved' and source_digest=source->>'digest' and valid_until>=current_date) then
    raise exception 'purchase_authority_stale_or_duplicate' using errcode='23514'; end if;
   select coalesce(sum(amount_minor),0) into design_used from d5o_hosted.design_spend_commitments
    where workspace_id=ws.id and work_id=work.id and status='Approved';
   select coalesce(sum(amount_minor),0) into purchase_used from d5o_hosted.purchase_reservations
    where workspace_id=ws.id and work_id=work.id and status='Reserved';
   if design_used+purchase_used>authority.parent_cap_minor or purchase_used>authority.purchasing_cap_minor then
    raise exception 'purchase_authority_below_existing_commitments' using errcode='23514'; end if;
  end if;
  update d5o_hosted.purchase_authorities set status=case p_action when 'approve' then 'Approved'
   when 'return' then 'Returned' else 'Revoked' end,
   reviewed_by=actor,review_note=trim(p_input->>'reason'),decided_at=now() where id=authority.id;
 end if;
 subject:=authority.id; next_rev:=pos.revision+1;
 update d5o_hosted.purchase_authority_positions set revision=next_rev,updated_at=now()
  where workspace_id=ws.id and work_id=work.id;
 insert into d5o_hosted.purchase_authority_events(workspace_id,work_id,revision,action,command_id,actor_user_id,
  membership_id,subject_id,basis) values(ws.id,work.id,next_rev,p_action,p_command_id,actor,member.id,subject,
   pg_catalog.jsonb_build_object('input',p_input,'source',source));
 result:=pg_catalog.jsonb_build_object('revision',next_rev,'action',p_action,'subjectId',subject,
  'status',case p_action when 'prepare' then 'Prepared' when 'approve' then 'Approved'
   when 'return' then 'Returned' else 'Revoked' end);
 insert into d5o_hosted.purchase_authority_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(ws.id,p_command_id,work.id,actor,fp,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_purchase_authority_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; source jsonb; rev integer;
 design_used bigint; purchase_used bigint; sub_used bigint; parent_cap bigint; purchase_cap bigint;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 if not exists(select 1 from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor
  and status='active' and role in ('admin','project_manager','operations_leader','billing_commercial_lead'))
  then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select work_id into w from d5o_hosted.work_identity_links where workspace_id=ws and presentation_id=p_presentation_id;
 if w is null then raise exception 'connected_work_unavailable' using errcode='42501'; end if;
 select revision into rev from d5o_hosted.purchase_authority_positions where workspace_id=ws and work_id=w;
 source:=d5o_hosted.purchase_basis_v1(ws,w);
 select coalesce(sum(amount_minor),0) into design_used from d5o_hosted.design_spend_commitments
  where workspace_id=ws and work_id=w and status='Approved';
 select coalesce(sum(amount_minor),0) into purchase_used from d5o_hosted.purchase_reservations
  where workspace_id=ws and work_id=w and status='Reserved';
 select coalesce(sum(amount_minor),0) into sub_used from d5o_hosted.subcontract_reservations where workspace_id=ws and work_id=w;
 select parent_cap_minor,purchasing_cap_minor into parent_cap,purchase_cap
  from d5o_hosted.purchase_authorities where workspace_id=ws and work_id=w and status='Approved'
   and source_digest=source->>'digest' and current_date between valid_from and valid_until
  order by created_at desc limit 1;
 return pg_catalog.jsonb_build_object('revision',coalesce(rev,0),'source',source,
  'legacyPurchaseHold',exists(select 1 from d5o_hosted.graybar_states g
   cross join lateral pg_catalog.jsonb_array_elements(coalesce(g.state->'orders','[]'::jsonb)) historical
   where g.workspace_id=ws and g.work_id=w
    and historical->>'status' in ('Approved','Test submitted','Acknowledged')
    and not exists(select 1 from d5o_hosted.purchase_reservations r
     where r.workspace_id=ws and r.work_id=w and r.order_id=historical->>'id')),
  'currentBomId',(select state#>>'{bom,id}' from d5o_hosted.graybar_states
    where workspace_id=ws and work_id=w and state#>>'{bom,status}'='Approved'),
  'designCommittedMinor',design_used,'purchaseReservedMinor',purchase_used,'subcontractReservedMinor',sub_used,
  'parentCapMinor',parent_cap,'purchaseCapMinor',purchase_cap,
  'parentRemainingMinor',case when parent_cap is null then null else parent_cap-design_used-purchase_used-sub_used end,
  'purchaseRemainingMinor',case when purchase_cap is null then null else purchase_cap-purchase_used end,
  'authorities',coalesce((select pg_catalog.jsonb_agg(to_jsonb(a) order by a.created_at)
    from d5o_hosted.purchase_authorities a where a.workspace_id=ws and a.work_id=w),'[]'::jsonb),
  'reservations',coalesce((select pg_catalog.jsonb_agg(to_jsonb(r) order by r.approved_at)
    from d5o_hosted.purchase_reservations r where r.workspace_id=ws and r.work_id=w),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_purchase_cancel_unsent_v1(p_workspace_key text, p_presentation_id text, p_order_id text, p_reason text, p_command_id text, p_expected_graybar_revision integer, p_expected_authority_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; gray d5o_hosted.graybar_states%rowtype;
 position d5o_hosted.purchase_authority_positions%rowtype;
 reservation d5o_hosted.purchase_reservations%rowtype; existing d5o_hosted.purchase_authority_receipts%rowtype;
 item jsonb; updated_orders jsonb; updated_state jsonb; fingerprint text; result jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null or length(coalesce(p_reason,''))<10
  or length(coalesce(p_command_id,'')) not between 8 and 120 or p_expected_graybar_revision<1
  or p_expected_authority_revision<1 then raise exception 'invalid_purchase_cancellation' using errcode='22023'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active' for share;
 select w.* into work from d5o_hosted.work_records w join d5o_hosted.work_identity_links l
  on l.workspace_id=w.workspace_id and l.work_id=w.id
  where w.workspace_id=ws and l.presentation_id=p_presentation_id for update of w;
 if member.role<>'admin' or work.id is null then raise exception 'purchasing_cancellation_authority_required' using errcode='42501'; end if;
 fingerprint:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_order_id,p_reason,
  p_expected_graybar_revision,p_expected_authority_revision)::text);
 select * into existing from d5o_hosted.purchase_authority_receipts
  where workspace_id=ws and command_id=p_command_id;
 if found then
  if existing.work_id<>work.id or existing.actor_user_id<>actor or existing.fingerprint<>fingerprint then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return existing.result;
 end if;
 select * into position from d5o_hosted.purchase_authority_positions
  where workspace_id=ws and work_id=work.id for update;
 select * into gray from d5o_hosted.graybar_states where workspace_id=ws and work_id=work.id for update;
 if position.revision<>p_expected_authority_revision or gray.revision<>p_expected_graybar_revision then
  raise exception 'stale_purchase_cancellation' using errcode='23505'; end if;
 select * into reservation from d5o_hosted.purchase_reservations
  where workspace_id=ws and work_id=work.id and order_id=p_order_id for update;
 select value into item from pg_catalog.jsonb_array_elements(gray.state->'orders') where value->>'id'=p_order_id;
 if reservation.id is null or reservation.status<>'Reserved' or item->>'status'<>'Approved'
  or exists(select 1 from d5o_hosted.graybar_job_cost_links
   where workspace_id=ws and work_id=work.id and order_id=p_order_id) then
  raise exception 'unsent_unposted_approved_po_required' using errcode='23514'; end if;
 updated_orders:=(select pg_catalog.jsonb_agg(case when value->>'id'=p_order_id then
  value||pg_catalog.jsonb_build_object('status','Cancelled','cancelledBy',actor,'cancelledAt',now(),
   'cancellationReason',p_reason) else value end order by ordinality)
  from pg_catalog.jsonb_array_elements(gray.state->'orders') with ordinality);
 updated_state:=pg_catalog.jsonb_set(gray.state,'{orders}',updated_orders);
 update d5o_hosted.graybar_states set revision=gray.revision+1,state=updated_state,updated_at=now()
  where workspace_id=ws and work_id=work.id;
 update d5o_hosted.purchase_reservations set status='Released',released_by=actor,
  released_at=now(),release_reason=p_reason where id=reservation.id;
 update d5o_hosted.purchase_authority_positions set revision=position.revision+1,updated_at=now()
  where workspace_id=ws and work_id=work.id;
 insert into d5o_hosted.graybar_events(workspace_id,work_id,revision,command_id,action,actor_user_id,membership_id,source,state)
  values(ws,work.id,gray.revision+1,p_command_id,'cancel-unsent-po',actor,member.id,
   pg_catalog.jsonb_build_object('orderId',p_order_id,'reason',p_reason,'reservationId',reservation.id),updated_state);
 result:=pg_catalog.jsonb_build_object('orderId',p_order_id,'graybarRevision',gray.revision+1,
  'authorityRevision',position.revision+1,'reservationStatus','Released');
 insert into d5o_hosted.purchase_authority_events(workspace_id,work_id,revision,action,command_id,actor_user_id,membership_id,subject_id,basis)
  values(ws,work.id,position.revision+1,'cancel-unsent-po',p_command_id,actor,member.id,reservation.id,
   pg_catalog.jsonb_build_object('reason',p_reason,'graybarRevision',gray.revision+1));
 insert into d5o_hosted.purchase_authority_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(ws,p_command_id,work.id,actor,fingerprint,result);
 insert into d5o_hosted.graybar_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
  values(ws,p_command_id,work.id,actor,fingerprint,pg_catalog.jsonb_build_object('revision',gray.revision+1,'state',updated_state));
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_purchase_order_my_review_v1(p_workspace_key text, p_presentation_id text, p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; role_name text; state jsonb; item jsonb;
 enabled_at timestamptz; prepared_at timestamptz; chosen uuid; enabled boolean;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 if role_name is null or w is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name<>'admin' then return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select s.state into state from d5o_hosted.graybar_states s where s.workspace_id=ws and s.work_id=w;
 select value into item from pg_catalog.jsonb_array_elements(coalesce(state->'orders','[]'::jsonb))
  where value->>'id'=p_order_id::text;
 if item is null or item->>'status'<>'Prepared' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 prepared_at:=nullif(item->>'preparedAt','')::timestamptz;
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=ws and category='purchase_order';
 enabled:=enabled_at is not null and prepared_at>=enabled_at;
 if enabled then
  chosen:=d5o_hosted.spending_delegate_selected_v1(ws,w,'purchase_order','admin',
   (item->>'amountMinor')::bigint,item->>'currency',(item->>'preparedBy')::uuid,current_date);
 end if;
 return pg_catalog.jsonb_build_object('pending',true,'configured',enabled,
  'canReview',case when enabled then coalesce(chosen=actor,false)
   else role_name='admin' and item->>'preparedBy'<>actor::text end,
  'held',enabled and chosen is null,
  'route',case when enabled and chosen is null then 'No eligible purchasing delegate or sponsor is configured.'
   when enabled and chosen=actor then 'This exact purchase decision is assigned to you.'
   when enabled then 'Waiting for the configured independent purchasing reviewer.'
   else 'Existing independent administrator review applies to this earlier draft.' end);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_schedule_labor_hours_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'scheduling_authority_required' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces
  where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name not in ('admin','project_manager','operations_leader') then
  raise exception 'scheduling_authority_required' using errcode='42501'; end if;
 return coalesce((select pg_catalog.jsonb_object_agg(i.assignment_id,i.person_hours_per_worker)
  from d5o_hosted.labor_booking_intents i where i.workspace_id=ws),'{}'::jsonb);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_spending_delegate_command_v1(p_workspace_key text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; member d5o_hosted.memberships%rowtype;
 pos d5o_hosted.spending_delegate_positions%rowtype; prior d5o_hosted.spending_delegate_receipts%rowtype;
 rule d5o_hosted.spending_delegate_rules%rowtype; target d5o_hosted.memberships%rowtype;
 fp text; result jsonb; category text; role_name text;
begin
 if current_setting('role',true)<>'authenticated' or actor is null or p_action not in ('add','revoke')
  or pg_catalog.jsonb_typeof(p_input)<>'object' or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then
  raise exception 'invalid_spending_delegate_command' using errcode='22023'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor
  and status='active' for share;
 if member.id is null or member.role<>'admin' then
  raise exception 'spending_configuration_admin_required' using errcode='42501'; end if;
 fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_action,p_input,p_expected_revision)::text);
 select * into prior from d5o_hosted.spending_delegate_receipts where workspace_id=ws and command_id=p_command_id;
 if prior.command_id is not null then
  if prior.actor_user_id<>actor or prior.fingerprint<>fp then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return prior.result; end if;
 insert into d5o_hosted.spending_delegate_positions(workspace_id) values(ws) on conflict do nothing;
 select * into pos from d5o_hosted.spending_delegate_positions where workspace_id=ws for update;
 if pos.revision<>p_expected_revision then raise exception 'stale_spending_delegate_revision' using errcode='23505'; end if;
 if p_action='add' then
  category:=p_input->>'category'; role_name:=p_input->>'role';
  if category is null or category not in ('work_authority','design_authority','design_commitment','purchase_order','subcontract_allocation','subcontract_agreement','subcontract_variation','field_labor_authority','internal_design_rate','design_cost_review','outlook_assessment')
   or role_name is null or role_name not in ('admin','operations_leader','billing_commercial_lead')
   or (category not in ('design_cost_review','outlook_assessment') and role_name='billing_commercial_lead')
   or (category in ('work_authority','purchase_order','subcontract_allocation','subcontract_agreement','subcontract_variation','field_labor_authority','internal_design_rate') and role_name<>'admin')
   or (category='internal_design_rate' and nullif(trim(coalesce(p_input->>'workTypeKey','')),'') is not null)
   or (category in ('design_cost_review','outlook_assessment') and role_name<>'billing_commercial_lead')
   or p_input->>'kind' not in ('delegate','sponsor')
   or (category<>'outlook_assessment' and coalesce(p_input->>'maxMinor','') !~ '^[1-9][0-9]*$')
   or (category='outlook_assessment' and (p_input->>'maxMinor' is not null or p_input->>'currency'<>'USD'))
   or coalesce(p_input->>'currency','') !~ '^[A-Z]{3}$'
   or coalesce(p_input->>'validFrom','') !~ '^\d{4}-\d{2}-\d{2}$'
   or coalesce(p_input->>'validUntil','') !~ '^\d{4}-\d{2}-\d{2}$'
   or length(trim(coalesce(p_input->>'sourceReference','')))<8
   or coalesce(p_input->>'priority','100') !~ '^\d{1,4}$' then
   raise exception 'invalid_spending_delegate_rule' using errcode='22023'; end if;
  if (p_input->>'validUntil')::date<current_date
   or (p_input->>'validFrom')::date>(p_input->>'validUntil')::date
   or (p_input->>'maxMinor')::bigint>1000000000000 then
   raise exception 'spending_delegate_rule_range_invalid' using errcode='23514'; end if;
  select * into target from d5o_hosted.memberships where workspace_id=ws
   and actor_user_id=(p_input->>'actorId')::uuid and status='active' for share;
  if target.id is null or target.role<>role_name then
   raise exception 'delegate_existing_role_required' using errcode='42501'; end if;
  insert into d5o_hosted.spending_delegate_categories(workspace_id,category)
   values(ws,category) on conflict do nothing;
  insert into d5o_hosted.spending_delegate_rules(workspace_id,category,kind,actor_user_id,
   role_name,currency,max_minor,work_type_key,priority,valid_from,valid_until,source_reference,configured_by)
   values(ws,category,p_input->>'kind',target.actor_user_id,role_name,p_input->>'currency',
    (p_input->>'maxMinor')::bigint,nullif(trim(coalesce(p_input->>'workTypeKey','')),''),
    coalesce((p_input->>'priority')::integer,100),(p_input->>'validFrom')::date,
    (p_input->>'validUntil')::date,trim(p_input->>'sourceReference'),actor) returning * into rule;
 else
  select * into rule from d5o_hosted.spending_delegate_rules
   where workspace_id=ws and id=(p_input->>'ruleId')::uuid and status='Active' for update;
  if rule.id is null or length(trim(coalesce(p_input->>'reason','')))<10 then
   raise exception 'active_rule_and_reason_required' using errcode='23514'; end if;
  update d5o_hosted.spending_delegate_rules set status='Revoked',revoked_at=now()
   where id=rule.id;
 end if;
 update d5o_hosted.spending_delegate_positions set revision=revision+1 where workspace_id=ws;
 insert into d5o_hosted.spending_delegate_events(workspace_id,revision,action,command_id,
  actor_user_id,membership_id,rule_id,basis)
  values(ws,pos.revision+1,p_action,p_command_id,actor,member.id,rule.id,p_input);
 result:=pg_catalog.jsonb_build_object('revision',pos.revision+1,'ruleId',rule.id,'action',p_action);
 insert into d5o_hosted.spending_delegate_receipts(workspace_id,command_id,actor_user_id,fingerprint,result)
  values(ws,p_command_id,actor,fp,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_spending_delegate_my_review_v1(p_workspace_key text, p_presentation_id text, p_category text, p_subject_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; role_name text; prepared_at timestamptz;
 amount bigint; preparer uuid; needed_until date; v_currency text; required_role text;
 enabled boolean; chosen uuid;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor and status='active';
 select work_id into w from d5o_hosted.work_identity_links where workspace_id=ws and presentation_id=p_presentation_id;
 if role_name is null or w is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if p_category='work_authority' then
  select a.parent_cap_minor,a.prepared_by,a.valid_until,a.currency,'admin',a.created_at
   into amount,preparer,needed_until,v_currency,required_role,prepared_at
   from d5o_hosted.purchase_authorities a
   where a.workspace_id=ws and a.work_id=w and a.id=p_subject_id and a.status='Prepared';
 elsif p_category='design_authority' then
  select a.cap_minor,a.prepared_by,a.valid_until,a.currency,a.source_snapshot->>'approverRole',a.created_at
   into amount,preparer,needed_until,v_currency,required_role,prepared_at
   from d5o_hosted.design_spend_authorities a
   where a.workspace_id=ws and a.work_id=w and a.id=p_subject_id and a.status='Prepared';
 elsif p_category='design_commitment' then
  select c.amount_minor,c.prepared_by,a.valid_until,c.currency,a.source_snapshot->>'approverRole',c.created_at
   into amount,preparer,needed_until,v_currency,required_role,prepared_at
   from d5o_hosted.design_spend_commitments c
   join d5o_hosted.design_spend_authorities a on a.id=c.authority_id
   where c.workspace_id=ws and c.work_id=w and c.id=p_subject_id and c.status='Prepared';
 else raise exception 'invalid_spending_category' using errcode='22023'; end if;
 if amount is null then return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select exists(select 1 from d5o_hosted.spending_delegate_categories c
  where c.workspace_id=ws and c.category=p_category and c.configured_at<=prepared_at) into enabled;
 chosen:=case when enabled then d5o_hosted.spending_delegate_selected_v1(ws,w,p_category,
  required_role,amount,v_currency,preparer,needed_until) else null end;
 return pg_catalog.jsonb_build_object('pending',true,'configured',enabled,
  'canReview',case when enabled then coalesce(chosen=actor,false) else role_name=required_role and actor<>preparer end,
  'held',enabled and chosen is null,
  'route',case when enabled and chosen is null then 'No eligible delegate or sponsor is configured.'
   when enabled and chosen=actor then 'This exact decision is assigned to you.'
   when enabled then 'Waiting for the configured independent reviewer.'
   else 'Existing role-based review applies until delegation is configured.' end);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_spending_delegate_read_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; rev integer;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 if not exists(select 1 from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor
   and status='active' and role='admin') then
  raise exception 'spending_configuration_admin_required' using errcode='42501'; end if;
 select revision into rev from d5o_hosted.spending_delegate_positions where workspace_id=ws;
 return pg_catalog.jsonb_build_object('revision',coalesce(rev,0),
  'members',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
   'actorId',m.actor_user_id,'role',m.role,'email',u.email) order by u.email)
   from d5o_hosted.memberships m join auth.users u on u.id=m.actor_user_id
   where m.workspace_id=ws and m.status='active' and m.role in ('admin','operations_leader','billing_commercial_lead')),'[]'::jsonb),
  'categories',coalesce((select pg_catalog.jsonb_agg(category order by category)
   from d5o_hosted.spending_delegate_categories where workspace_id=ws),'[]'::jsonb),
  'rules',coalesce((select pg_catalog.jsonb_agg(to_jsonb(r) order by r.created_at,r.id)
   from d5o_hosted.spending_delegate_rules r where r.workspace_id=ws),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_subcontract_actions_pre_delegation_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; role_name text; row_item record; s jsonb; item jsonb;
 out_items jsonb:='[]'::jsonb; parent_id uuid; source jsonb; action_kind text;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'subcontract_scope_denied' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 if role_name is null then raise exception 'subcontract_scope_denied' using errcode='42501'; end if;
 for row_item in select w.id,w.created_by,l.presentation_id,w.title,coalesce(s.revision,0) revision,
   coalesce(s.state,'{"allocations":[],"agreements":[],"variations":[],"deliverables":[],"invoices":[]}'::jsonb) state
  from d5o_hosted.work_records w join d5o_hosted.work_identity_links l
   on l.workspace_id=w.workspace_id and l.work_id=w.id

  left join d5o_hosted.subcontract_states s on s.workspace_id=w.workspace_id and s.work_id=w.id
  where w.workspace_id=ws loop
  s:=row_item.state;
  source:=d5o_hosted.purchase_basis_v1(ws,row_item.id);
  select id into parent_id from d5o_hosted.purchase_authorities
   where workspace_id=ws and work_id=row_item.id and status='Approved' and subcontract_enabled
    and source_digest=source->>'digest' and current_date between valid_from and valid_until
   order by created_at desc limit 1;
  if parent_id is null then continue; end if;
  if role_name='project_manager' and row_item.created_by=actor then
   if not exists(select 1 from pg_catalog.jsonb_array_elements(s->'allocations')
     where value->>'status' in ('Prepared','Approved') and value->>'parentAuthorityId'=parent_id::text) then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Prepare subcontract allocation','phase','Procurement','focus','subcontract-allocation',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId','','title',row_item.title,
     'ownership','Assigned project manager','blocker',null));
   elsif exists(select 1 from pg_catalog.jsonb_array_elements(s->'allocations')
     where value->>'status'='Approved' and value->>'parentAuthorityId'=parent_id::text)
    and not exists(select 1 from pg_catalog.jsonb_array_elements(s->'agreements')
     where value->>'status' in ('Prepared','Approved')) then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Prepare subcontract agreement','phase','Procurement','focus','subcontract-agreement',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId','','title',row_item.title,
     'ownership','Assigned project manager','blocker',null));
   end if;
  end if;
  for item in select value from pg_catalog.jsonb_array_elements(s->'allocations') loop
   if item->>'status'='Prepared' and role_name='admin' and item->>'preparedBy'<>actor::text then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Review subcontract allocation','phase','Procurement','focus','subcontract-review-allocation',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
     'title',row_item.title,'ownership','Independent administrator','blocker',null));
   end if;
  end loop;
  for item in select value from pg_catalog.jsonb_array_elements(s->'agreements') loop
   if item->>'status'='Prepared' and role_name='admin' and item->>'preparedBy'<>actor::text then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Review subcontract agreement','phase','Procurement','focus','subcontract-review-agreement',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
     'title',row_item.title,'ownership','Independent administrator','blocker',null));
   end if;
  end loop;
  for item in select value from pg_catalog.jsonb_array_elements(s->'variations') loop
   if item->>'status'='Prepared' and role_name='admin' and item->>'preparedBy'<>actor::text then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Review subcontract variation','phase','Procurement','focus','subcontract-review-variation',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
     'title',row_item.title,'ownership','Independent administrator','blocker',null));
   end if;
  end loop;
  for item in select value from pg_catalog.jsonb_array_elements(s->'deliverables') loop
   if item->>'status'='Submitted' and role_name in ('operations_leader','admin')
    and item->>'submittedBy'<>actor::text then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Review subcontract deliverable','phase','Procurement','focus','subcontract-review-deliverable',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
     'title',row_item.title,'ownership','Independent Operations receiver','blocker',null));
   end if;
  end loop;
  if role_name='project_manager' and row_item.created_by=actor then
   for item in select value from pg_catalog.jsonb_array_elements(s->'agreements')
    where value->>'status'='Approved' loop
    if (item->>'revisedMinor')::bigint>coalesce((select sum((value->>'amountMinor')::bigint)
      from pg_catalog.jsonb_array_elements(s->'deliverables')
      where value->>'agreementId'=item->>'id' and value->>'status'='Accepted'),0)
      and not exists(select 1 from pg_catalog.jsonb_array_elements(s->'deliverables')
       where value->>'agreementId'=item->>'id' and value->>'status'='Submitted') then
     out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'kind','Submit subcontract deliverable','phase','Procurement','focus','subcontract-delivery',
      'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
      'title',row_item.title,'ownership','Assigned project manager','blocker',null));
    end if;
   end loop;
  end if;
  if role_name='billing_commercial_lead' then
   for item in select value from pg_catalog.jsonb_array_elements(s->'deliverables')
    where value->>'status'='Accepted' loop
    if (item->>'amountMinor')::bigint>coalesce((select sum((value->>'amountMinor')::bigint)
      from pg_catalog.jsonb_array_elements(s->'invoices')
      where value->>'deliverableId'=item->>'id' and value->>'status' in ('Review','Matched')),0) then
     out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'kind','Record subcontract supplier invoice','phase','Finance','focus','subcontract-invoice',
      'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
      'title',row_item.title,'ownership','Finance','blocker',null));
    end if;
   end loop;
   for item in select to_jsonb(r) from d5o_hosted.subcontract_reservations r
    where r.workspace_id=ws and r.work_id=row_item.id and r.amount_minor>0 loop
    if not exists(select 1 from d5o_hosted.subcontract_cost_links
      where workspace_id=ws and work_id=row_item.id and reservation_id=(item->>'id')::uuid
       and kind='Committed') then
     out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'kind','Post subcontract commitment','phase','Finance','focus','subcontract-cost-commitment',
      'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
      'title',row_item.title,'ownership','Finance','blocker',null));
    end if;
   end loop;
  end if;  for item in select value from pg_catalog.jsonb_array_elements(s->'invoices') loop
   if item->>'status'='Review' and role_name='admin' and item->>'recordedBy'<>actor::text then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Review subcontract invoice','phase','Finance','focus','subcontract-review-invoice',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
     'title',row_item.title,'ownership','Independent Finance reviewer','blocker',null));
   elsif item->>'status'='Matched' and role_name='billing_commercial_lead' and not exists(
    select 1 from d5o_hosted.subcontract_cost_links where workspace_id=ws and work_id=row_item.id
     and invoice_id=(item->>'id')::uuid and kind='Incurred') then
    out_items:=out_items||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
     'kind','Post subcontract incurred cost','phase','Finance','focus','subcontract-cost-invoice',
     'workId',row_item.presentation_id,'revision',row_item.revision,'decisionId',item->>'id',
     'title',row_item.title,'ownership','Finance','blocker',null));
   end if;
  end loop;
 end loop;
 return out_items;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_subcontract_actions_v1(p_workspace_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare raw jsonb; entry jsonb; output jsonb:='[]'::jsonb; route jsonb;
begin
 raw:=public.d5o_subcontract_actions_pre_delegation_v1(p_workspace_key);
 for entry in select value from pg_catalog.jsonb_array_elements(raw) loop
  if entry->>'focus' in ('subcontract-review-allocation','subcontract-review-agreement',
   'subcontract-review-variation') then
   route:=public.d5o_subcontract_my_review_v1(p_workspace_key,entry->>'workId',
    entry->>'focus',(entry->>'decisionId')::uuid);
   if not coalesce((route->>'canReview')::boolean,false) then continue; end if;
  end if;
  output:=output||pg_catalog.jsonb_build_array(entry);
 end loop;
 return output;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_subcontract_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_input jsonb, p_command_id text, p_expected_revision integer, p_expected_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws d5o_hosted.workspaces%rowtype; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; position d5o_hosted.subcontract_states%rowtype;
 old_receipt d5o_hosted.subcontract_receipts%rowtype; payload_state jsonb; source jsonb; fp text;
 parent d5o_hosted.purchase_authorities%rowtype; allocation jsonb; agreement jsonb; variation jsonb;
 delivery jsonb; invoice jsonb; prior_item jsonb; company d5o_hosted.subcontract_companies%rowtype;
 subject uuid; doc uuid; new_item jsonb; result jsonb; status text; array_key text; next_rev integer;
 amount bigint; delta bigint; sub_used bigint; accepted bigint; invoiced bigint; existing_cost bigint;
begin
 if current_setting('role',true)<>'authenticated' or actor is null
  or p_action not in ('register-company','prepare-allocation','review-allocation',
   'prepare-agreement','review-agreement','prepare-variation','review-variation',
   'submit-deliverable','review-deliverable','record-invoice','review-invoice')
  or pg_catalog.jsonb_typeof(p_input)<>'object'
  or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_revision is null or p_expected_revision<0 then
  raise exception 'invalid_subcontract_command' using errcode='22023'; end if;
 select * into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and d5o_hosted.workspaces.status='active';
 select * into member from d5o_hosted.memberships
  where workspace_id=ws.id and actor_user_id=actor and d5o_hosted.memberships.status='active' for share;
 select w.* into work from d5o_hosted.work_records w join d5o_hosted.work_identity_links l
  on l.workspace_id=w.workspace_id and l.work_id=w.id
  where w.workspace_id=ws.id and l.presentation_id=p_presentation_id for update of w;
 if member.id is null or work.id is null then raise exception 'subcontract_scope_denied' using errcode='42501'; end if;
 fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,p_input,
  p_expected_revision,p_expected_source_digest)::text);
 select * into old_receipt from d5o_hosted.subcontract_receipts
  where workspace_id=ws.id and command_id=p_command_id;
 if found then
  if old_receipt.work_id<>work.id or old_receipt.actor_user_id<>actor or old_receipt.fingerprint<>fp then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return old_receipt.result; end if;
 insert into d5o_hosted.subcontract_states(workspace_id,work_id) values(ws.id,work.id) on conflict do nothing;
 select * into position from d5o_hosted.subcontract_states
  where workspace_id=ws.id and work_id=work.id for update;
 if position.revision<>p_expected_revision then
  raise exception 'stale_subcontract_revision' using errcode='23505'; end if;
 payload_state:=position.state;
 source:=d5o_hosted.purchase_basis_v1(ws.id,work.id);
 if source is null or source->>'digest' is distinct from p_expected_source_digest then
  raise exception 'subcontract_source_changed' using errcode='23514'; end if;
 select * into parent from d5o_hosted.purchase_authorities
  where workspace_id=ws.id and work_id=work.id and d5o_hosted.purchase_authorities.status='Approved'
   and source_digest=source->>'digest' and current_date between valid_from and valid_until
  order by created_at desc limit 1 for update;
 if parent.id is null then
  raise exception 'current_work_economic_authority_required' using errcode='23514'; end if;
 if p_action<>'register-company' and not parent.subcontract_enabled then
  raise exception 'subcontract_category_not_authorized' using errcode='23514'; end if;
 if p_action='register-company' then
  if member.role not in ('admin','project_manager') then
   raise exception 'subcontract_company_preparer_required' using errcode='42501'; end if;
  insert into d5o_hosted.subcontract_companies(workspace_id,name,contact_name,contact_reference,created_by)
  values(ws.id,trim(p_input->>'name'),trim(p_input->>'contactName'),
   trim(p_input->>'contactReference'),actor) returning * into company;
  subject:=company.id; array_key:='companies'; status:='Recorded';
 elsif p_action='prepare-allocation' then
  if member.role<>'project_manager' or work.created_by<>actor then
   raise exception 'subcontract_allocation_preparer_required' using errcode='42501'; end if;
  if coalesce(p_input->>'capMinor','') !~ '^[1-9][0-9]*$'
   or length(trim(coalesce(p_input->>'scope',''))) < 12
   or length(trim(coalesce(p_input->>'conditions',''))) < 10
   or length(trim(coalesce(p_input->>'sourceReference',''))) < 8 then
   raise exception 'subcontract_allocation_basis_invalid' using errcode='22023'; end if;
  amount:=(p_input->>'capMinor')::bigint;
  if amount>parent.parent_cap_minor then raise exception 'subcontract_sublimit_invalid' using errcode='23514'; end if;
  if exists(select 1 from pg_catalog.jsonb_array_elements(payload_state->'allocations') x
   where x->>'status'='Approved' and x->>'parentAuthorityId'=parent.id::text) then
   raise exception 'active_subcontract_allocation_exists' using errcode='23514'; end if;
  subject:=gen_random_uuid(); array_key:='allocations'; status:='Prepared';
  new_item:=pg_catalog.jsonb_build_object('id',subject,'status',status,'capMinor',amount,
   'currency','USD','scope',trim(p_input->>'scope'),'conditions',trim(p_input->>'conditions'),
   'sourceReference',trim(p_input->>'sourceReference'),'parentAuthorityId',parent.id,
   'sourceDigest',source->>'digest','preparedBy',actor,'preparedAt',now(),
   'supersedesId',p_input->>'supersedesId');
  payload_state:=pg_catalog.jsonb_set(payload_state,'{allocations}',payload_state->'allocations'||pg_catalog.jsonb_build_array(new_item));
 elsif p_action='review-allocation' then
  if member.role<>'admin' then raise exception 'independent_subcontract_authority_required' using errcode='42501'; end if;
  select value into allocation from pg_catalog.jsonb_array_elements(payload_state->'allocations')
   where value->>'id'=p_input->>'allocationId';
  if allocation is null or allocation->>'status'<>'Prepared' or allocation->>'preparedBy'=actor::text
   or allocation->>'parentAuthorityId'<>parent.id::text
   or allocation->>'sourceDigest'<>source->>'digest'
   or p_input->>'decision' not in ('Approved','Returned')
   or length(trim(coalesce(p_input->>'reason','')))<10 then
   raise exception 'independent_subcontract_authority_required' using errcode='23514'; end if;
  if p_input->>'decision'='Approved' then
   select coalesce(sum(amount_minor),0) into sub_used from d5o_hosted.subcontract_reservations
    where workspace_id=ws.id and work_id=work.id;
   if sub_used>(allocation->>'capMinor')::bigint then
    raise exception 'subcontract_sublimit_below_commitments' using errcode='23514'; end if;
  end if;
  subject:=(allocation->>'id')::uuid; array_key:='allocations'; status:=p_input->>'decision';
  new_item:=allocation||pg_catalog.jsonb_build_object('status',status,'reviewedBy',actor,
   'decidedAt',now(),'reviewReason',trim(p_input->>'reason'));
  payload_state:=pg_catalog.jsonb_set(payload_state,'{allocations}',(select pg_catalog.jsonb_agg(
   case when value->>'id'=subject::text then new_item else value end)
   from pg_catalog.jsonb_array_elements(payload_state->'allocations')));
 else
  select value into allocation from pg_catalog.jsonb_array_elements(payload_state->'allocations')
   where value->>'status'='Approved' and value->>'parentAuthorityId'=parent.id::text
   order by (value->>'decidedAt')::timestamptz desc limit 1;
  if allocation is null or allocation->>'sourceDigest'<>source->>'digest' then
   raise exception 'approved_subcontract_allocation_required' using errcode='23514'; end if;
  select coalesce(sum(amount_minor),0) into sub_used from d5o_hosted.subcontract_reservations
   where workspace_id=ws.id and work_id=work.id;
  if p_action='prepare-agreement' then
   if member.role<>'project_manager' or work.created_by<>actor then
    raise exception 'subcontract_agreement_preparer_required' using errcode='42501'; end if;
   if coalesce(p_input->>'amountMinor','') !~ '^[1-9][0-9]*$'
    or length(trim(coalesce(p_input->>'agreementReference','')))<8
    or length(trim(coalesce(p_input->>'scope','')))<12
    or length(trim(coalesce(p_input->>'exclusions','')))<4
    or length(trim(coalesce(p_input->>'deliverables','')))<8
    or length(trim(coalesce(p_input->>'acceptanceCriteria','')))<10
    or length(trim(coalesce(p_input->>'scheduleBasis','')))<8
    or length(trim(coalesce(p_input->>'milestoneBasis','')))<8
    or coalesce(p_input->>'documentId','') !~ '^[0-9a-f-]{36}$' then
    raise exception 'subcontract_agreement_basis_invalid' using errcode='22023'; end if;
   amount:=(p_input->>'amountMinor')::bigint;
   if amount>(allocation->>'capMinor')::bigint-sub_used then
    raise exception 'subcontract_sublimit_exceeded' using errcode='23514'; end if;
   select * into company from d5o_hosted.subcontract_companies
    where id=(p_input->>'companyId')::uuid and workspace_id=ws.id;
   doc:=(p_input->>'documentId')::uuid;
   if company.id is null or not d5o_hosted.subcontract_document_v1(ws.id,work.id,doc) then
    raise exception 'retained_subcontract_company_document_required' using errcode='23514'; end if;
   if nullif(trim(coalesce(p_input->>'packageId','')),'') is not null and
    not exists(select 1 from d5o_hosted.connected_package_states
     where workspace_id=ws.id and work_id=work.id and package_id=p_input->>'packageId') then
    raise exception 'exact_subcontract_package_required' using errcode='23514'; end if;
   if nullif(p_input->>'supersedesId','') is not null then
    select value into prior_item from pg_catalog.jsonb_array_elements(payload_state->'agreements')
     where value->>'id'=p_input->>'supersedesId' and value->>'status'='Returned';
    if prior_item is null then raise exception 'returned_subcontract_agreement_required' using errcode='23514'; end if;
   end if;
   subject:=gen_random_uuid(); array_key:='agreements'; status:='Prepared';
   new_item:=p_input||pg_catalog.jsonb_build_object('id',subject,'status',status,
    'currency','USD','amountMinor',amount,'revisedMinor',amount,'allocationId',allocation->>'id',
    'parentAuthorityId',parent.id,'sourceDigest',source->>'digest',
    'documentSha256',(select sha256 from d5o_hosted.graybar_documents where id=doc),
    'preparedBy',actor,'preparedAt',now(),'revision',1);
   payload_state:=pg_catalog.jsonb_set(payload_state,'{agreements}',payload_state->'agreements'||pg_catalog.jsonb_build_array(new_item));
  elsif p_action='review-agreement' then
   if member.role<>'admin' then raise exception 'independent_subcontract_approval_required' using errcode='42501'; end if;
   select value into agreement from pg_catalog.jsonb_array_elements(payload_state->'agreements')
    where value->>'id'=p_input->>'agreementId';
   if agreement is null or agreement->>'status'<>'Prepared' or agreement->>'preparedBy'=actor::text
    or agreement->>'allocationId'<>allocation->>'id'
    or agreement->>'sourceDigest'<>source->>'digest'
    or p_input->>'decision' not in ('Approved','Returned')
    or length(trim(coalesce(p_input->>'reason','')))<10 then
    raise exception 'independent_subcontract_approval_required' using errcode='23514'; end if;
   if p_input->>'decision'='Approved' then
    amount:=(agreement->>'amountMinor')::bigint;
    if amount>(allocation->>'capMinor')::bigint-sub_used then
     raise exception 'subcontract_sublimit_exceeded' using errcode='23514'; end if;
    if not d5o_hosted.subcontract_document_v1(ws.id,work.id,(agreement->>'documentId')::uuid) or
     (select sha256 from d5o_hosted.graybar_documents where id=(agreement->>'documentId')::uuid)
       <>agreement->>'documentSha256' then
     raise exception 'subcontract_document_changed' using errcode='23514'; end if;
    insert into d5o_hosted.subcontract_reservations(workspace_id,work_id,allocation_id,
     agreement_id,amount_minor,currency,source_digest,approved_by)
    values(ws.id,work.id,(allocation->>'id')::uuid,(agreement->>'id')::uuid,
     amount,'USD',source->>'digest',actor);
   end if;
   subject:=(agreement->>'id')::uuid; array_key:='agreements'; status:=p_input->>'decision';
   new_item:=agreement||pg_catalog.jsonb_build_object('status',status,'reviewedBy',actor,
    'decidedAt',now(),'reviewReason',trim(p_input->>'reason'));
   payload_state:=pg_catalog.jsonb_set(payload_state,'{agreements}',(select pg_catalog.jsonb_agg(
    case when value->>'id'=subject::text then new_item else value end)
    from pg_catalog.jsonb_array_elements(payload_state->'agreements')));
  elsif p_action in ('prepare-variation','review-variation','submit-deliverable','review-deliverable','record-invoice','review-invoice') then
   select value into agreement from pg_catalog.jsonb_array_elements(payload_state->'agreements')
    where value->>'id'=p_input->>'agreementId' and value->>'status'='Approved';
   if agreement is null or agreement->>'sourceDigest'<>source->>'digest'
    or agreement->>'allocationId'<>allocation->>'id' then
    raise exception 'current_subcontract_agreement_required' using errcode='23514'; end if;
   if p_action='prepare-variation' then
    if member.role<>'project_manager' or work.created_by<>actor then
     raise exception 'subcontract_variation_preparer_required' using errcode='42501'; end if;
    if coalesce(p_input->>'deltaMinor','') !~ '^-?[1-9][0-9]*$'
     or length(trim(coalesce(p_input->>'scopeDifference','')))<10
     or length(trim(coalesce(p_input->>'scheduleImpact','')))<5
     or length(trim(coalesce(p_input->>'rationale','')))<10
     or coalesce(p_input->>'documentId','') !~ '^[0-9a-f-]{36}$' then
     raise exception 'subcontract_variation_basis_invalid' using errcode='22023'; end if;
    doc:=(p_input->>'documentId')::uuid;
    if not d5o_hosted.subcontract_document_v1(ws.id,work.id,doc) then
     raise exception 'retained_subcontract_variation_required' using errcode='23514'; end if;
    if nullif(p_input->>'supersedesId','') is not null then
     select value into prior_item from pg_catalog.jsonb_array_elements(payload_state->'variations')
      where value->>'id'=p_input->>'supersedesId' and value->>'agreementId'=agreement->>'id'
       and value->>'status'='Returned';
     if prior_item is null then raise exception 'returned_subcontract_variation_required' using errcode='23514'; end if;
    end if;
    subject:=gen_random_uuid(); array_key:='variations'; status:='Prepared';
    new_item:=p_input||pg_catalog.jsonb_build_object('id',subject,'status',status,
     'baseAgreementRevision',coalesce(agreement->>'revision','1'),'sourceDigest',source->>'digest',
     'documentSha256',(select sha256 from d5o_hosted.graybar_documents where id=doc),
     'preparedBy',actor,'preparedAt',now(),'revision',1);
    payload_state:=pg_catalog.jsonb_set(payload_state,'{variations}',payload_state->'variations'||pg_catalog.jsonb_build_array(new_item));
   elsif p_action='review-variation' then
    if member.role<>'admin' then raise exception 'independent_subcontract_approval_required' using errcode='42501'; end if;
    select value into variation from pg_catalog.jsonb_array_elements(payload_state->'variations')
     where value->>'id'=p_input->>'variationId' and value->>'agreementId'=agreement->>'id';
    if variation is null or variation->>'status'<>'Prepared' or variation->>'preparedBy'=actor::text
     or variation->>'sourceDigest'<>source->>'digest'
     or variation->>'baseAgreementRevision'<>coalesce(agreement->>'revision','1')
     or p_input->>'decision' not in ('Approved','Returned')
     or length(trim(coalesce(p_input->>'reason','')))<10 then
     raise exception 'independent_subcontract_approval_required' using errcode='23514'; end if;
    if p_input->>'decision'='Approved' then
     delta:=(variation->>'deltaMinor')::bigint;
     if delta>0 and delta>(allocation->>'capMinor')::bigint-sub_used then
      raise exception 'subcontract_sublimit_exceeded' using errcode='23514'; end if;
     if (agreement->>'revisedMinor')::bigint+delta<=0 then
      raise exception 'subcontract_reduction_invalid' using errcode='23514'; end if;
     select coalesce(sum((value->>'amountMinor')::bigint),0) into accepted
      from pg_catalog.jsonb_array_elements(payload_state->'deliverables')
      where value->>'agreementId'=agreement->>'id' and value->>'status'='Accepted';
     select coalesce(sum((value->>'amountMinor')::bigint),0) into invoiced
      from pg_catalog.jsonb_array_elements(payload_state->'invoices')
      where value->>'agreementId'=agreement->>'id' and value->>'status'='Matched';
     if delta<0 and ((agreement->>'revisedMinor')::bigint+delta<greatest(accepted,invoiced)
      or exists(select 1 from d5o_hosted.subcontract_cost_links l
       join d5o_hosted.subcontract_reservations r on r.id=l.reservation_id
       where r.agreement_id=(agreement->>'id')::uuid and l.kind='Committed')) then
      raise exception 'subcontract_reduction_requires_cost_reconciliation' using errcode='23514'; end if;
     if not d5o_hosted.subcontract_document_v1(ws.id,work.id,(variation->>'documentId')::uuid) or
      (select sha256 from d5o_hosted.graybar_documents where id=(variation->>'documentId')::uuid)
       <>variation->>'documentSha256' then
      raise exception 'subcontract_document_changed' using errcode='23514'; end if;
     insert into d5o_hosted.subcontract_reservations(workspace_id,work_id,allocation_id,
      agreement_id,variation_id,amount_minor,currency,source_digest,approved_by)
     values(ws.id,work.id,(allocation->>'id')::uuid,(agreement->>'id')::uuid,
      (variation->>'id')::uuid,delta,'USD',source->>'digest',actor);
     agreement:=agreement||pg_catalog.jsonb_build_object('revisedMinor',(agreement->>'revisedMinor')::bigint+delta,
      'revision',coalesce((agreement->>'revision')::integer,1)+1);
     payload_state:=pg_catalog.jsonb_set(payload_state,'{agreements}',(select pg_catalog.jsonb_agg(
      case when value->>'id'=agreement->>'id' then agreement else value end)
      from pg_catalog.jsonb_array_elements(payload_state->'agreements')));
    end if;
    subject:=(variation->>'id')::uuid; array_key:='variations'; status:=p_input->>'decision';
    new_item:=variation||pg_catalog.jsonb_build_object('status',status,'reviewedBy',actor,
     'decidedAt',now(),'reviewReason',trim(p_input->>'reason'));
    payload_state:=pg_catalog.jsonb_set(payload_state,'{variations}',(select pg_catalog.jsonb_agg(
     case when value->>'id'=subject::text then new_item else value end)
     from pg_catalog.jsonb_array_elements(payload_state->'variations')));
   elsif p_action='submit-deliverable' then
    if member.role<>'project_manager' or work.created_by<>actor then
     raise exception 'subcontract_delivery_recorder_required' using errcode='42501'; end if;
    if coalesce(p_input->>'amountMinor','') !~ '^[1-9][0-9]*$'
     or length(trim(coalesce(p_input->>'description','')))<10
     or coalesce(p_input->>'documentId','') !~ '^[0-9a-f-]{36}$' then
     raise exception 'subcontract_delivery_basis_invalid' using errcode='22023'; end if;
    doc:=(p_input->>'documentId')::uuid;
    if not d5o_hosted.subcontract_document_v1(ws.id,work.id,doc) then
     raise exception 'retained_subcontract_deliverable_required' using errcode='23514'; end if;
    amount:=(p_input->>'amountMinor')::bigint;
    select coalesce(sum((value->>'amountMinor')::bigint),0) into accepted
     from pg_catalog.jsonb_array_elements(payload_state->'deliverables')
     where value->>'agreementId'=agreement->>'id' and value->>'status'='Accepted';
    if amount+accepted>(agreement->>'revisedMinor')::bigint then
     raise exception 'subcontract_delivery_exceeds_agreement' using errcode='23514'; end if;
    if nullif(p_input->>'supersedesId','') is not null then
     select value into prior_item from pg_catalog.jsonb_array_elements(payload_state->'deliverables')
      where value->>'id'=p_input->>'supersedesId' and value->>'agreementId'=agreement->>'id'
       and value->>'status'='Returned';
     if prior_item is null then raise exception 'returned_subcontract_deliverable_required' using errcode='23514'; end if;
    end if;
    subject:=gen_random_uuid(); array_key:='deliverables'; status:='Submitted';
    new_item:=p_input||pg_catalog.jsonb_build_object('id',subject,'status',status,
     'amountMinor',amount,'agreementRevision',coalesce((agreement->>'revision')::integer,1),
     'documentSha256',(select sha256 from d5o_hosted.graybar_documents where id=doc),
     'submittedBy',actor,'submittedAt',now());
    payload_state:=pg_catalog.jsonb_set(payload_state,'{deliverables}',payload_state->'deliverables'||pg_catalog.jsonb_build_array(new_item));
   elsif p_action='review-deliverable' then
    if member.role not in ('operations_leader','admin') then
     raise exception 'independent_subcontract_receipt_required' using errcode='42501'; end if;
    select value into delivery from pg_catalog.jsonb_array_elements(payload_state->'deliverables')
     where value->>'id'=p_input->>'deliverableId' and value->>'agreementId'=agreement->>'id';
    if delivery is null or delivery->>'status'<>'Submitted' or delivery->>'submittedBy'=actor::text
     or p_input->>'decision' not in ('Accepted','Returned')
     or length(trim(coalesce(p_input->>'reason','')))<10 then
     raise exception 'independent_subcontract_receipt_required' using errcode='23514'; end if;
    if delivery->>'agreementRevision'<>coalesce(agreement->>'revision','1')
     or not d5o_hosted.subcontract_document_v1(ws.id,work.id,(delivery->>'documentId')::uuid)
     or (select sha256 from d5o_hosted.graybar_documents where id=(delivery->>'documentId')::uuid)
       <>delivery->>'documentSha256' then
     raise exception 'subcontract_delivery_source_changed' using errcode='23514'; end if;
    if p_input->>'decision'='Accepted' then
     select coalesce(sum((value->>'amountMinor')::bigint),0) into accepted
      from pg_catalog.jsonb_array_elements(payload_state->'deliverables')
      where value->>'agreementId'=agreement->>'id' and value->>'status'='Accepted';
     if accepted+(delivery->>'amountMinor')::bigint>(agreement->>'revisedMinor')::bigint then
      raise exception 'subcontract_delivery_exceeds_agreement' using errcode='23514'; end if;
    end if;
    subject:=(delivery->>'id')::uuid; array_key:='deliverables'; status:=p_input->>'decision';
    new_item:=delivery||pg_catalog.jsonb_build_object('status',status,'reviewedBy',actor,
     'decidedAt',now(),'reviewReason',trim(p_input->>'reason'));
    payload_state:=pg_catalog.jsonb_set(payload_state,'{deliverables}',(select pg_catalog.jsonb_agg(
     case when value->>'id'=subject::text then new_item else value end)
     from pg_catalog.jsonb_array_elements(payload_state->'deliverables')));
   elsif p_action='record-invoice' then
    if member.role<>'billing_commercial_lead' then
     raise exception 'subcontract_finance_role_required' using errcode='42501'; end if;
    select value into delivery from pg_catalog.jsonb_array_elements(payload_state->'deliverables')
     where value->>'id'=p_input->>'deliverableId' and value->>'agreementId'=agreement->>'id'
      and value->>'status'='Accepted';
    if delivery is null or coalesce(p_input->>'amountMinor','') !~ '^[1-9][0-9]*$'
     or length(trim(coalesce(p_input->>'invoiceNumber','')))<5
     or coalesce(p_input->>'documentId','') !~ '^[0-9a-f-]{36}$' then
     raise exception 'accepted_subcontract_delivery_required' using errcode='23514'; end if;
    if exists(select 1 from pg_catalog.jsonb_array_elements(payload_state->'invoices')
     where value->>'invoiceNumber'=p_input->>'invoiceNumber'
      and value->>'companyId'=agreement->>'companyId') then
     raise exception 'duplicate_subcontract_invoice' using errcode='23505'; end if;
    doc:=(p_input->>'documentId')::uuid;
    if not d5o_hosted.subcontract_document_v1(ws.id,work.id,doc) then
     raise exception 'retained_subcontract_invoice_required' using errcode='23514'; end if;
    amount:=(p_input->>'amountMinor')::bigint;
    select coalesce(sum((value->>'amountMinor')::bigint),0) into invoiced
     from pg_catalog.jsonb_array_elements(payload_state->'invoices')
     where value->>'deliverableId'=delivery->>'id' and value->>'status' in ('Review','Matched');
    if amount+invoiced>(delivery->>'amountMinor')::bigint then
     raise exception 'subcontract_invoice_exceeds_accepted_delivery' using errcode='23514'; end if;
    subject:=gen_random_uuid(); array_key:='invoices'; status:='Review';
    new_item:=p_input||pg_catalog.jsonb_build_object('id',subject,'status',status,
     'companyId',agreement->>'companyId','currency','USD','amountMinor',amount,
     'deliveryRevision',delivery->>'agreementRevision','agreementRevision',coalesce(agreement->>'revision','1'),
     'documentSha256',(select sha256 from d5o_hosted.graybar_documents where id=doc),
     'recordedBy',actor,'recordedAt',now());
    payload_state:=pg_catalog.jsonb_set(payload_state,'{invoices}',payload_state->'invoices'||pg_catalog.jsonb_build_array(new_item));
   elsif p_action='review-invoice' then
    if member.role not in ('admin','billing_commercial_lead') then
     raise exception 'independent_subcontract_invoice_review_required' using errcode='42501'; end if;
    select value into invoice from pg_catalog.jsonb_array_elements(payload_state->'invoices')
     where value->>'id'=p_input->>'invoiceId' and value->>'agreementId'=agreement->>'id';
    if invoice is null or invoice->>'status'<>'Review' or invoice->>'recordedBy'=actor::text
     or p_input->>'decision' not in ('Matched','Hold')
     or length(trim(coalesce(p_input->>'reason','')))<10 then
     raise exception 'independent_subcontract_invoice_review_required' using errcode='23514'; end if;
    select value into delivery from pg_catalog.jsonb_array_elements(payload_state->'deliverables')
     where value->>'id'=invoice->>'deliverableId' and value->>'status'='Accepted';
    if delivery is null or invoice->>'agreementRevision' is distinct from coalesce(agreement->>'revision','1')
     or invoice->>'companyId'<>agreement->>'companyId'
     or not d5o_hosted.subcontract_document_v1(ws.id,work.id,(invoice->>'documentId')::uuid)
     or (select sha256 from d5o_hosted.graybar_documents where id=(invoice->>'documentId')::uuid)
      <>invoice->>'documentSha256' then
     raise exception 'subcontract_invoice_source_changed' using errcode='23514'; end if;
    subject:=(invoice->>'id')::uuid; array_key:='invoices'; status:=p_input->>'decision';
    new_item:=invoice||pg_catalog.jsonb_build_object('status',status,'reviewedBy',actor,
     'decidedAt',now(),'reviewReason',trim(p_input->>'reason'));
    payload_state:=pg_catalog.jsonb_set(payload_state,'{invoices}',(select pg_catalog.jsonb_agg(
     case when value->>'id'=subject::text then new_item else value end)
     from pg_catalog.jsonb_array_elements(payload_state->'invoices')));
   end if;
  end if;
 end if;
 next_rev:=position.revision+1;
 update d5o_hosted.subcontract_states set revision=next_rev,state=payload_state
  where workspace_id=ws.id and work_id=work.id;
 insert into d5o_hosted.subcontract_events(workspace_id,work_id,revision,action,command_id,
  actor_user_id,membership_id,subject_id,basis)
 values(ws.id,work.id,next_rev,p_action,p_command_id,actor,member.id,subject,
  pg_catalog.jsonb_build_object('input',p_input,'source',source,'status',status));
 result:=pg_catalog.jsonb_build_object('revision',next_rev,'action',p_action,
  'subjectId',subject,'status',status);
 insert into d5o_hosted.subcontract_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
 values(ws.id,p_command_id,work.id,actor,fp,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_subcontract_cost_command_v1(p_workspace_key text, p_presentation_id text, p_action text, p_subject_id uuid, p_command_id text, p_expected_subcontract_revision integer, p_expected_finance_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws d5o_hosted.workspaces%rowtype; member d5o_hosted.memberships%rowtype;
 work d5o_hosted.work_records%rowtype; s d5o_hosted.subcontract_states%rowtype;
 f d5o_hosted.connected_job_finance_states%rowtype; prior d5o_hosted.subcontract_receipts%rowtype;
 reservation d5o_hosted.subcontract_reservations%rowtype; invoice jsonb; agreement jsonb;
 commit_row record; remaining bigint; capacity bigint; amount bigint; cost_id uuid;
 source text; fp text; ids jsonb:='[]'::jsonb; result jsonb;
begin
 if current_setting('role',true)<>'authenticated' or actor is null
  or p_action not in ('post-commitment','post-invoice') or p_subject_id is null
  or length(coalesce(p_command_id,'')) not between 8 and 120
  or p_expected_subcontract_revision is null or p_expected_finance_revision is null then
  raise exception 'invalid_subcontract_cost_command' using errcode='22023'; end if;
 select * into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select * into member from d5o_hosted.memberships
  where workspace_id=ws.id and actor_user_id=actor and status='active' for share;
 select w.* into work from d5o_hosted.work_records w join d5o_hosted.work_identity_links l
  on l.workspace_id=w.workspace_id and l.work_id=w.id
  where w.workspace_id=ws.id and l.presentation_id=p_presentation_id for update of w;
 if member.id is null or member.role<>'billing_commercial_lead' or work.id is null then
  raise exception 'subcontract_cost_finance_role_required' using errcode='42501'; end if;
 if d5o_hosted.job_finance_award_v1(ws.id,work.id) is null then
  raise exception 'awarded_job_cost_basis_required' using errcode='23514'; end if;
 if exists(select 1 from d5o_hosted.connected_operate_states o
  where o.workspace_id=ws.id and o.work_id=work.id and o.state#>>'{finance,status}'='Closed') then
  raise exception 'finance_closed_requires_reopen' using errcode='23514'; end if;
 insert into d5o_hosted.connected_job_finance_states(workspace_id,work_id,currency)
  values(ws.id,work.id,'USD') on conflict do nothing;
 select * into s from d5o_hosted.subcontract_states
  where workspace_id=ws.id and work_id=work.id for update;
 select * into f from d5o_hosted.connected_job_finance_states
  where workspace_id=ws.id and work_id=work.id for update;
 fp:=pg_catalog.md5(pg_catalog.jsonb_build_array(p_workspace_key,p_presentation_id,p_action,
  p_subject_id,p_expected_subcontract_revision,p_expected_finance_revision)::text);
 select * into prior from d5o_hosted.subcontract_receipts
  where workspace_id=ws.id and command_id=p_command_id;
 if found then
  if prior.work_id<>work.id or prior.actor_user_id<>actor or prior.fingerprint<>fp then
   raise exception 'command_reuse_conflict' using errcode='23505'; end if;
  return prior.result; end if;
 if s.revision is distinct from p_expected_subcontract_revision or
  f.revision<>p_expected_finance_revision then
  raise exception 'stale_subcontract_cost_source' using errcode='23505'; end if;
 if p_action='post-commitment' then
  select * into reservation from d5o_hosted.subcontract_reservations
   where id=p_subject_id and workspace_id=ws.id and work_id=work.id for update;
  if reservation.id is null or reservation.amount_minor<=0 or
   exists(select 1 from d5o_hosted.subcontract_cost_links
    where workspace_id=ws.id and work_id=work.id
     and reservation_id=reservation.id and kind='Committed') then
   raise exception 'subcontract_commitment_already_posted_or_invalid' using errcode='23505'; end if;
  select value into agreement from pg_catalog.jsonb_array_elements(s.state->'agreements')
   where value->>'id'=reservation.agreement_id::text and value->>'status'='Approved';
  if agreement is null then raise exception 'approved_subcontract_agreement_required' using errcode='23514'; end if;
  source:='Subcontract reservation '||reservation.id::text;
  insert into d5o_hosted.connected_job_costs(workspace_id,work_id,package_id,kind,category,
   amount_minor,cost_date,source,recorded_by)
  values(ws.id,work.id,nullif(agreement->>'packageId',''),'Committed','Subcontract',
   reservation.amount_minor,current_date,source,actor) returning id into cost_id;
  insert into d5o_hosted.subcontract_cost_links(workspace_id,work_id,reservation_id,kind,cost_id,recorded_by)
   values(ws.id,work.id,reservation.id,'Committed',cost_id,actor);
  ids:=ids||pg_catalog.jsonb_build_array(cost_id);
 else
  select value into invoice from pg_catalog.jsonb_array_elements(s.state->'invoices')
   where value->>'id'=p_subject_id::text and value->>'status'='Matched';
  if invoice is null or exists(select 1 from d5o_hosted.subcontract_cost_links
    where workspace_id=ws.id and work_id=work.id and invoice_id=p_subject_id and kind='Incurred') then
   raise exception 'matched_unposted_subcontract_invoice_required' using errcode='23514'; end if;
  select value into agreement from pg_catalog.jsonb_array_elements(s.state->'agreements')
   where value->>'id'=invoice->>'agreementId' and value->>'status'='Approved';
  if agreement is null then raise exception 'approved_subcontract_agreement_required' using errcode='23514'; end if;
  remaining:=(invoice->>'amountMinor')::bigint;
  for commit_row in select c.id,c.amount_minor from d5o_hosted.subcontract_cost_links l
   join d5o_hosted.subcontract_reservations r on r.id=l.reservation_id
   join d5o_hosted.connected_job_costs c on c.id=l.cost_id
   where l.workspace_id=ws.id and l.work_id=work.id and r.agreement_id=(invoice->>'agreementId')::uuid
    and l.kind='Committed' and r.amount_minor>0
   order by r.approved_at,r.id for update of c loop
   select commit_row.amount_minor-coalesce(sum(amount_minor),0) into capacity
    from d5o_hosted.connected_job_costs where reconciles_id=commit_row.id;
   amount:=least(remaining,capacity);
   if amount>0 then
    source:='Subcontract invoice '||p_subject_id::text||' commitment '||commit_row.id::text;
    insert into d5o_hosted.connected_job_costs(workspace_id,work_id,package_id,kind,category,
     amount_minor,cost_date,source,reconciles_id,recorded_by)
    values(ws.id,work.id,nullif(agreement->>'packageId',''),'Incurred','Subcontract',
     amount,current_date,source,commit_row.id,actor) returning id into cost_id;
    insert into d5o_hosted.subcontract_cost_links(workspace_id,work_id,invoice_id,kind,cost_id,recorded_by)
     values(ws.id,work.id,p_subject_id,'Incurred',cost_id,actor);
    ids:=ids||pg_catalog.jsonb_build_array(cost_id);
    remaining:=remaining-amount;
   end if;
   exit when remaining=0;
  end loop;
  if remaining<>0 then raise exception 'subcontract_invoice_commitment_reconciliation_invalid' using errcode='23514'; end if;
 end if;
 update d5o_hosted.connected_job_finance_states set revision=f.revision+1
  where workspace_id=ws.id and work_id=work.id;
 result:=pg_catalog.jsonb_build_object('action',p_action,'financeRevision',f.revision+1,
  'subcontractRevision',s.revision,'costIds',ids);
 insert into d5o_hosted.connected_job_finance_events(workspace_id,work_id,revision,command_id,
  actor_user_id,membership_id,action,result)
 values(ws.id,work.id,f.revision+1,p_command_id,actor,member.id,p_action||'-subcontract',result);
 insert into d5o_hosted.subcontract_receipts(workspace_id,command_id,work_id,actor_user_id,fingerprint,result)
 values(ws.id,p_command_id,work.id,actor,fp,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_subcontract_my_review_v1(p_workspace_key text, p_presentation_id text, p_focus text, p_subject_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; role_name text; state jsonb;
 item jsonb; agreement jsonb; array_key text; review_category text; amount bigint;
 currency text; enabled_at timestamptz; prepared_at timestamptz; chosen uuid; enabled boolean;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'workspace_forbidden' using errcode='42501'; end if;
 array_key:=case p_focus when 'subcontract-review-allocation' then 'allocations'
  when 'subcontract-review-agreement' then 'agreements'
  when 'subcontract-review-variation' then 'variations' else null end;
 if array_key is null then raise exception 'invalid_subcontract_review_target' using errcode='22023'; end if;
 review_category:=case array_key when 'allocations' then 'subcontract_allocation'
  when 'agreements' then 'subcontract_agreement' else 'subcontract_variation' end;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 select role into role_name from d5o_hosted.memberships
  where workspace_id=ws and actor_user_id=actor and status='active';
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 if role_name is null or w is null then raise exception 'workspace_forbidden' using errcode='42501'; end if;
 if role_name<>'admin' then return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 select s.state into state from d5o_hosted.subcontract_states s
  where s.workspace_id=ws and s.work_id=w;
 select value into item from pg_catalog.jsonb_array_elements(coalesce(state->array_key,'[]'::jsonb))
  where value->>'id'=p_subject_id::text;
 if item is null or item->>'status'<>'Prepared' then
  return pg_catalog.jsonb_build_object('pending',false,'canReview',false); end if;
 if array_key='allocations' then
  amount:=(item->>'capMinor')::bigint; currency:=item->>'currency';
 elsif array_key='agreements' then
  amount:=(item->>'amountMinor')::bigint; currency:=item->>'currency';
 else
  amount:=abs((item->>'deltaMinor')::bigint);
  select value into agreement from pg_catalog.jsonb_array_elements(coalesce(state->'agreements','[]'::jsonb))
   where value->>'id'=item->>'agreementId';
  currency:=agreement->>'currency';
 end if;
 select configured_at into enabled_at from d5o_hosted.spending_delegate_categories
  where workspace_id=ws and category=review_category;
 prepared_at:=nullif(item->>'preparedAt','')::timestamptz;
 enabled:=enabled_at is not null and prepared_at is not null and prepared_at>=enabled_at;
 if enabled and amount>0 and currency is not null then
  chosen:=d5o_hosted.spending_delegate_selected_v1(ws,w,review_category,'admin',amount,currency,
   (item->>'preparedBy')::uuid,current_date);
 end if;
 return pg_catalog.jsonb_build_object('pending',true,'configured',enabled,
  'canReview',case when enabled then coalesce(chosen=actor,false)
   else item->>'preparedBy'<>actor::text end,
  'held',enabled and chosen is null,
  'route',case when enabled and chosen is null then 'No eligible subcontract delegate or sponsor is configured.'
   when enabled and chosen=actor then 'This exact subcontract decision is assigned to you.'
   when enabled then 'Waiting for the configured independent subcontract reviewer.'
   else 'Existing independent administrator review applies to this earlier draft.' end);
end; $function$

CREATE OR REPLACE FUNCTION public.d5o_subcontract_read_v1(p_workspace_key text, p_presentation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); ws uuid; w uuid; s d5o_hosted.subcontract_states%rowtype;
 source jsonb; parent_id uuid; parent_cap bigint; design_used bigint; po_used bigint; sub_used bigint;
 alloc jsonb; alloc_cap bigint;
begin
 if current_setting('role',true)<>'authenticated' or actor is null then
  raise exception 'subcontract_scope_denied' using errcode='42501'; end if;
 select id into ws from d5o_hosted.workspaces where workspace_key=p_workspace_key and status='active';
 if not exists(select 1 from d5o_hosted.memberships where workspace_id=ws and actor_user_id=actor
  and status='active' and role in ('admin','project_manager','operations_leader','billing_commercial_lead')) then
  raise exception 'subcontract_scope_denied' using errcode='42501'; end if;
 select work_id into w from d5o_hosted.work_identity_links
  where workspace_id=ws and presentation_id=p_presentation_id;
 if w is null then raise exception 'subcontract_scope_denied' using errcode='42501'; end if;
 select * into s from d5o_hosted.subcontract_states where workspace_id=ws and work_id=w;
 source:=d5o_hosted.purchase_basis_v1(ws,w);
 select id,parent_cap_minor into parent_id,parent_cap from d5o_hosted.purchase_authorities
  where workspace_id=ws and work_id=w and status='Approved'
   and source_digest=source->>'digest' and current_date between valid_from and valid_until
  order by created_at desc limit 1;
 select coalesce(sum(amount_minor),0) into design_used from d5o_hosted.design_spend_commitments
  where workspace_id=ws and work_id=w and status='Approved';
 select coalesce(sum(amount_minor),0) into po_used from d5o_hosted.purchase_reservations
  where workspace_id=ws and work_id=w and status='Reserved';
 select coalesce(sum(amount_minor),0) into sub_used from d5o_hosted.subcontract_reservations
  where workspace_id=ws and work_id=w;
 select value into alloc from pg_catalog.jsonb_array_elements(coalesce(s.state->'allocations','[]'::jsonb))
  where value->>'status'='Approved' and value->>'parentAuthorityId'=parent_id::text
  order by (value->>'decidedAt')::timestamptz desc limit 1;
 alloc_cap:=(alloc->>'capMinor')::bigint;
 return pg_catalog.jsonb_build_object('revision',coalesce(s.revision,0),
  'state',coalesce(s.state,'{"allocations":[],"agreements":[],"variations":[],"deliverables":[],"invoices":[]}'::jsonb),
  'source',source,'parentAuthorityId',parent_id,'parentCapMinor',parent_cap,
  'designConsumedMinor',design_used,'purchaseConsumedMinor',po_used,'subcontractConsumedMinor',sub_used,
  'parentRemainingMinor',case when parent_cap is null then null else parent_cap-design_used-po_used-sub_used end,
  'subcontractCapMinor',alloc_cap,
  'subcontractRemainingMinor',case when alloc_cap is null then null else alloc_cap-sub_used end,
  'companies',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
   'id',id,'name',name,'contactName',contact_name,'contactReference',contact_reference) order by name)
   from d5o_hosted.subcontract_companies where workspace_id=ws),'[]'::jsonb),
  'reservations',coalesce((select pg_catalog.jsonb_agg(to_jsonb(r) order by approved_at)
   from d5o_hosted.subcontract_reservations r where workspace_id=ws and work_id=w),'[]'::jsonb),
  'costLinks',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
   'reservationId',l.reservation_id,'invoiceId',l.invoice_id,'kind',l.kind,
   'amountMinor',c.amount_minor,'costId',c.id,'reconcilesId',c.reconciles_id) order by l.recorded_at)
   from d5o_hosted.subcontract_cost_links l join d5o_hosted.connected_job_costs c on c.id=l.cost_id
   where l.workspace_id=ws and l.work_id=w),'[]'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.enforce_bucket_name_length()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, next_token_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, next_token_version text DEFAULT ''::text)
 RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;

    -- Configuration
    v_is_asc BOOLEAN;
    v_prefix TEXT;
    v_start TEXT;
    v_start_relative TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;
    v_version_filter TEXT;

    -- true when noncurrent_versions can return >1 row per name; keeps them
    -- ordered most-recent-first and lets pagination resume mid-key
    v_multi_row BOOLEAN;
    v_name_order TEXT;
    v_exact_range_predicate TEXT;
    v_strict_range_predicate TEXT;
    v_inclusive_range_predicate TEXT;

    -- Seek state for the current name. archived_at is normalized to JavaScript's
    -- millisecond precision and version breaks ties within the same millisecond.
    -- Current rows use 'infinity'; NULL means no tiebreak has been established.
    v_next_seek TEXT;
    v_next_seek_at TIMESTAMPTZ;
    v_next_seek_version TEXT;
    v_next_seek_strict BOOLEAN := false;
    v_cursor_is_folder BOOLEAN;
    v_count INT := 0;
    v_previous_seek TEXT;
    v_previous_seek_at TIMESTAMPTZ;
    v_previous_seek_version TEXT;
    v_previous_count INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;
    v_batch_query_strict TEXT;
    v_delete_marker_peek_query TEXT;
    v_delete_marker_peek_query_strict TEXT;

BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';
    v_prefix := coalesce(prefix_param, '');
    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;
    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);
    v_next_seek_at := NULL;
    v_next_seek_version := '';

    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a
    -- bare NOT IN check silently leaves an explicit NULL argument unreset.
    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');
    delete_markers := COALESCE(delete_markers, 'exclude');
    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN
        noncurrent_versions := 'exclude';
    END IF;
    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN
        delete_markers := 'exclude';
    END IF;

    v_multi_row := noncurrent_versions IN ('only', 'include');
    v_name_order := CASE WHEN v_is_asc THEN 'ASC' ELSE 'DESC' END;

    v_version_filter := '';
    IF noncurrent_versions = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';
    ELSIF noncurrent_versions = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';
    END IF;
    IF delete_markers = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';
    ELSIF delete_markers = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.is_delete_marker';
    END IF;

    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE "C")
    IF v_prefix = '' THEN
        v_upper_bound := NULL;
    ELSE
        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);
    END IF;

    -- Keep caller-provided cursors inside the requested prefix range.
    IF v_start <> '' AND v_upper_bound IS NOT NULL THEN
        IF v_is_asc THEN
            IF v_start COLLATE "C" < v_prefix COLLATE "C" THEN
                v_start := '';
            ELSIF v_start COLLATE "C" >= v_upper_bound COLLATE "C" THEN
                RETURN;
            END IF;
        ELSE
            IF v_start COLLATE "C" < v_prefix COLLATE "C" THEN
                RETURN;
            ELSIF v_start COLLATE "C" >= v_upper_bound COLLATE "C" THEN
                v_start := '';
            END IF;
        END IF;
    END IF;

    v_start_relative := substring(v_start FROM length(v_prefix) + 1);

    -- Direction affects only the indexed name range and its ordering. Cursor
    -- state transitions and within-key version ordering stay shared.
    IF v_is_asc THEN
        v_exact_range_predicate := 'TRUE';
        v_strict_range_predicate := 'o.name COLLATE "C" > $2';
        v_inclusive_range_predicate := 'o.name COLLATE "C" >= $2';
        IF v_upper_bound IS NOT NULL THEN
            v_exact_range_predicate := 'o.name COLLATE "C" < $3';
            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE "C" < $3';
            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE "C" < $3';
        END IF;
    ELSE
        v_exact_range_predicate := 'TRUE';
        v_strict_range_predicate := 'o.name COLLATE "C" < $2';
        v_inclusive_range_predicate := 'o.name COLLATE "C" < $2';
        IF v_prefix <> '' THEN
            v_exact_range_predicate := 'o.name COLLATE "C" >= $3';
            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE "C" >= $3';
            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE "C" >= $3';
        END IF;
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    -- The multi-row order matches the externally serialized cursor exactly:
    -- archived_at at millisecond precision, then version as the final tiebreak.
    --
    -- When v_multi_row, the seek is a keyset tuple comparison ("name > $2 OR
    -- (name = $2 AND tiebreak)") - Postgres won't split that OR into indexable
    -- form (confirmed even with fully literal values), so as one WHERE clause
    -- it forces a full bucket scan filtered row-by-row. Splitting it into two
    -- independently-indexable branches (exact name match with the tiebreak
    -- filter, vs. strictly-past names) combined with UNION ALL lets each
    -- branch keep name as a real index condition; the outer ORDER BY/LIMIT
    -- re-merges them into the same page the single query used to produce.
    IF v_multi_row THEN
        v_batch_query := format(
            $sql$
            SELECT *
            FROM (
                (
                    SELECT o.name, o.id, o.updated_at, o.created_at,
                           o.last_accessed_at, o.metadata, o.version,
                           o.archived_at, o.is_delete_marker, o.is_versioned
                    FROM storage.objects o
                    WHERE o.bucket_id = $1
                      AND o.name COLLATE "C" = $2
                      AND %s
                      AND NOT $7::boolean
                      AND (
                          $5::timestamptz IS NULL
                          OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < $5
                          OR (
                              COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = $5
                              AND COALESCE(o.version, '') > $6
                          )
                      )
                      %s
                    ORDER BY
                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,
                        COALESCE(o.version, '') ASC
                    LIMIT $4
                )
                UNION ALL
                (
                    SELECT o.name, o.id, o.updated_at, o.created_at,
                           o.last_accessed_at, o.metadata, o.version,
                           o.archived_at, o.is_delete_marker, o.is_versioned
                    FROM storage.objects o
                    WHERE o.bucket_id = $1
                      AND %s
                      %s
                    ORDER BY
                        o.name COLLATE "C" %s,
                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,
                        COALESCE(o.version, '') ASC
                    LIMIT $4
                )
            ) sub
            ORDER BY
                sub.name COLLATE "C" %s,
                COALESCE(date_trunc('milliseconds', sub.archived_at), 'infinity'::timestamptz) DESC,
                COALESCE(sub.version, '') ASC
            LIMIT $4
            $sql$,
            v_exact_range_predicate,
            v_version_filter,
            v_strict_range_predicate,
            v_version_filter,
            v_name_order,
            v_name_order
        );
    ELSE
        v_batch_query := format(
            $sql$
            SELECT o.name, o.id, o.updated_at, o.created_at,
                   o.last_accessed_at, o.metadata, o.version,
                   o.archived_at, o.is_delete_marker, o.is_versioned
            FROM storage.objects o
            WHERE o.bucket_id = $1
              AND %s
              %s
            ORDER BY o.name COLLATE "C" %s, o.archived_at DESC
            LIMIT $4
            $sql$,
            v_inclusive_range_predicate,
            v_version_filter,
            v_name_order
        );

        -- Strict counterpart of the query above: used once the single-row
        -- ASC batch advance (below) has left v_next_seek pointing at the
        -- last row already emitted, so an inclusive predicate would
        -- re-match it forever. Only single-row mode ever sets strict mode,
        -- so this variant is never needed when v_multi_row.
        v_batch_query_strict := format(
            $sql$
            SELECT o.name, o.id, o.updated_at, o.created_at,
                   o.last_accessed_at, o.metadata, o.version,
                   o.archived_at, o.is_delete_marker, o.is_versioned
            FROM storage.objects o
            WHERE o.bucket_id = $1
              AND %s
              %s
            ORDER BY o.name COLLATE "C" %s, o.archived_at DESC
            LIMIT $4
            $sql$,
            v_strict_range_predicate,
            v_version_filter,
            v_name_order
        );
    END IF;

    -- The static peek predicates cannot use the partial delete-marker index
    -- once PL/pgSQL switches to a generic plan because whether
    -- is_delete_marker is required remains parameter-dependent. Reuse the
    -- already-specialized batch query with a one-row limit for this sparse
    -- filter so the plan sees a literal `o.is_delete_marker` predicate.
    IF delete_markers = 'only' THEN
        v_delete_marker_peek_query :=
            'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';
        IF NOT v_multi_row THEN
            v_delete_marker_peek_query_strict :=
                'SELECT marker_page.name FROM (' || v_batch_query_strict || ') marker_page LIMIT 1';
        END IF;
    END IF;

    -- ========================================================================
    -- SEEK INITIALIZATION: Determine starting position
    -- ========================================================================
    IF v_start = '' THEN
        IF v_is_asc THEN
            v_next_seek := v_prefix;
        ELSE
            -- DESC without cursor performs one specialized initial seek so
            -- partial current-version and delete-marker indexes remain available.
            EXECUTE format(
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY o.name COLLATE "C" DESC LIMIT 1',
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND o.name COLLATE "C" >= $2 AND o.name COLLATE "C" < $3'
                    ELSE ''
                END,
                v_version_filter
            )
            INTO v_next_seek
            USING _bucket_id, v_prefix, v_upper_bound;

            IF v_next_seek IS NOT NULL THEN
                v_next_seek := v_next_seek || delimiter_param;
            ELSE
                RETURN;
            END IF;
        END IF;
    ELSE
        -- Folder continuation tokens retain their trailing delimiter. A
        -- delimiter-less startAfter is always a literal key boundary.
        v_cursor_is_folder := delimiter_param <> ''
            AND v_start_relative <> ''
            AND right(v_start_relative, length(delimiter_param)) = delimiter_param;

        IF v_cursor_is_folder THEN
            v_next_seek := CASE
                WHEN right(v_start, length(delimiter_param)) = delimiter_param
                    THEN v_start
                ELSE v_start || delimiter_param
            END;
            IF v_is_asc THEN
                v_next_seek := left(v_next_seek, -1)
                    || chr(ascii(right(v_next_seek, 1)) + 1);
            END IF;
            v_next_seek_strict := NOT v_is_asc;
        ELSE
            -- leaf object: when v_multi_row, stay on v_start with the
            -- caller-supplied tiebreak so a page boundary mid-key resumes
            -- that key's remaining rows instead of skipping them. Truncate
            -- to milliseconds like every other v_next_seek_at assignment -
            -- harmless today since object.ts's cursor always round-trips
            -- through JS Date first, but this shouldn't rely on that.
            IF v_multi_row THEN
                v_next_seek := v_start;
                v_next_seek_at := date_trunc('milliseconds', next_token_archived_at);
                v_next_seek_version := coalesce(next_token_version, '');
                v_next_seek_strict := coalesce(next_token, '') = '';
            ELSIF v_is_asc THEN
                v_next_seek := v_start;
                v_next_seek_strict := true;
            ELSE
                v_next_seek := v_start;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= max_keys;

        v_previous_seek := v_next_seek;
        v_previous_seek_at := v_next_seek_at;
        v_previous_seek_version := v_next_seek_version;
        v_previous_count := v_count;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        -- v_multi_row is branched here (rather than folded into the WHERE
        -- clause as a bound parameter) so each concrete query keeps an
        -- unconditional seek predicate - once PL/pgSQL switches to its
        -- cached generic plan (after 5 calls), a parameter-gated
        -- "(NOT v_multi_row AND name >= $x) OR (v_multi_row AND ...)"
        -- predicate stops the planner from using name as an index
        -- condition at all, degrading every subsequent peek to a full
        -- index scan filtered row-by-row instead of a bounded range scan.
        -- v_multi_row's seek predicate is a keyset tuple comparison
        -- ("name > x OR (name = x AND tiebreak)") - Postgres does not
        -- split this OR into indexable form even with fully literal
        -- values, so it falls back to a full scan filtered row-by-row.
        -- Splitting it into two independently-indexable branches (exact
        -- name match with the tiebreak filter, vs. strictly-past name)
        -- combined with UNION ALL lets each branch keep name as a real
        -- index condition; the outer ORDER BY/LIMIT picks whichever of
        -- the (at most 2) rows sorts first.
        IF delete_markers = 'only' THEN
            EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row
                THEN v_delete_marker_peek_query_strict
                ELSE v_delete_marker_peek_query
            END
                INTO v_peek_name
                USING _bucket_id, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END,
                    1, v_next_seek_at, v_next_seek_version, v_next_seek_strict;
        ELSIF v_multi_row THEN
            IF v_is_asc THEN
                IF v_upper_bound IS NOT NULL THEN
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND o.name COLLATE "C" < v_upper_bound
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" > v_next_seek AND o.name COLLATE "C" < v_upper_bound
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" ASC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" ASC LIMIT 1;
                ELSE
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" > v_next_seek
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" ASC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" ASC LIMIT 1;
                END IF;
            ELSE
                IF v_upper_bound IS NOT NULL THEN
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND o.name COLLATE "C" >= v_prefix
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" DESC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" DESC LIMIT 1;
                ELSE
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" DESC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" DESC LIMIT 1;
                END IF;
            END IF;
        ELSE
            -- Single-row mode is always noncurrent_versions='exclude'. Keep
            -- this predicate literal so generic plans use the current index.
            IF v_is_asc THEN
                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" > v_next_seek
                      AND o.name COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                ELSIF v_next_seek_strict THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" > v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                ELSIF v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" >= v_next_seek
                      AND o.name COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                ELSE
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" >= v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                END IF;
            ELSE
                IF v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" < v_next_seek
                      AND o.name COLLATE "C" >= v_prefix
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" DESC LIMIT 1;
                ELSE
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" < v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" DESC LIMIT 1;
                END IF;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Emit and skip to next folder (no heap access needed)
            name := v_common_prefix;
            id := NULL;
            updated_at := NULL;
            created_at := NULL;
            last_accessed_at := NULL;
            metadata := NULL;
            version := NULL;
            archived_at := NULL;
            is_delete_marker := NULL;
            is_versioned := NULL;
            RETURN NEXT;
            v_count := v_count + 1;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := left(v_common_prefix, -1)
                    || chr(ascii(right(v_common_prefix, 1)) + 1);
            ELSE
                v_next_seek := v_common_prefix;
            END IF;
            v_next_seek_at := NULL;
            v_next_seek_version := '';
            v_next_seek_strict := NOT v_is_asc;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row THEN v_batch_query_strict ELSE v_batch_query END
                USING _bucket_id, v_next_seek,
                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size, v_next_seek_at, v_next_seek_version,
                v_next_seek_strict
            LOOP
                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it. Reset
                    -- strict mode too it may have been set by an earlier
                    -- row in this same batch (see the single-row ASC advance
                    -- below), and v_next_seek here is the folder-triggering
                    -- row's own name, which the next peek must find inclusively.
                    v_next_seek := CASE
                        WHEN v_is_asc THEN v_current.name
                        ELSE v_current.name || delimiter_param
                    END;
                    v_next_seek_at := NULL;
                    v_next_seek_version := '';
                    v_next_seek_strict := false;
                    EXIT;
                END IF;

                -- Emit file
                name := v_current.name;
                id := v_current.id;
                updated_at := v_current.updated_at;
                created_at := v_current.created_at;
                last_accessed_at := v_current.last_accessed_at;
                metadata := v_current.metadata;
                version := v_current.version;
                archived_at := v_current.archived_at;
                is_delete_marker := v_current.is_delete_marker;
                is_versioned := v_current.is_versioned;
                RETURN NEXT;
                v_count := v_count + 1;

                -- when v_multi_row, stay on this name and record its
                -- archived_at as the new tiebreak so remaining rows for the
                -- same key are picked up before moving to the next name
                IF v_multi_row THEN
                    v_next_seek := v_current.name;
                    v_next_seek_at := COALESCE(date_trunc('milliseconds', v_current.archived_at), 'infinity'::timestamptz);
                    v_next_seek_version := COALESCE(v_current.version, '');
                    v_next_seek_strict := false;
                ELSIF v_is_asc THEN
                    -- Appending the delimiter as a fake lexical successor
                    -- would skip a real key like `name || '!'` (or any
                    -- character sorting below the delimiter), which sorts
                    -- between `name` and `name || delimiter`. Track the real
                    -- name and mark the next comparison strict instead.
                    v_next_seek := v_current.name;
                    v_next_seek_strict := true;
                ELSE
                    v_next_seek := v_current.name;
                END IF;

                EXIT WHEN v_count >= max_keys;
            END LOOP;
        END IF;

        IF v_count = v_previous_count
           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek
           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at
           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN
            RAISE EXCEPTION 'storage.list_objects_with_delimiter made no progress at seek (%, %, %)',
                v_next_seek, v_next_seek_at, v_next_seek_version;
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION storage.protect_bucket_control_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  configuration_changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.lifecycle_configuration IS NOT NULL
       OR NEW.lifecycle_configuration_generation IS NOT NULL THEN
      IF NOT pg_has_role(current_user, TG_ARGV[0], 'MEMBER') THEN
        RAISE EXCEPTION 'only members of the configured storage service role may insert lifecycle policy state'
          USING ERRCODE = '42501',
                HINT = format(
                  'Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.',
                  TG_ARGV[0]
                );
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  configuration_changed =
    OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration
    OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;

  IF NOT configuration_changed THEN
    RETURN NEW;
  END IF;

  IF NEW.type IS DISTINCT FROM 'STANDARD' THEN
    RAISE EXCEPTION 'bucket versioning and lifecycle controls require a Standard bucket'
      USING ERRCODE = '0A000';
  END IF;

  IF NEW.lifecycle_configuration IS NULL
     AND NEW.lifecycle_configuration_generation IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.lifecycle_configuration IS NULL
     OR NEW.lifecycle_configuration_generation IS NULL
     OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration
     OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN
    RAISE EXCEPTION 'a changed lifecycle policy requires a new non-null generation'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text)
 RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_prefix_len INT;
    v_prefix_start INT;
    v_combined_levels INT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;
    v_version_filter TEXT;
    v_multi_row BOOLEAN;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;
    v_delete_marker_peek_query TEXT;
    v_delete_marker_peek_query_strict TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_next_seek_at TIMESTAMPTZ;
    v_next_seek_version TEXT;
    v_next_seek_strict BOOLEAN := false;
    v_count INT := 0;
    v_skipped INT := 0;
    v_previous_seek TEXT;
    v_previous_seek_at TIMESTAMPTZ;
    v_previous_seek_version TEXT;
    v_previous_count INT;
    v_previous_skipped INT;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_prefix_len := length(coalesce(prefix, ''));
    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);
    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);
    v_next_seek_at := NULL;
    v_next_seek_version := '';

    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a
    -- bare NOT IN check silently leaves an explicit NULL argument unreset.
    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');
    delete_markers := COALESCE(delete_markers, 'exclude');
    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN
        noncurrent_versions := 'exclude';
    END IF;
    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN
        delete_markers := 'exclude';
    END IF;

    v_multi_row := noncurrent_versions IN ('only', 'include');

    v_version_filter := '';
    IF noncurrent_versions = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';
    ELSIF noncurrent_versions = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';
    END IF;
    IF delete_markers = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';
    ELSIF delete_markers = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.is_delete_marker';
    END IF;

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT array_to_string(path_tokens[$1:$2], '/') AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $3 || '%%'
                  AND bucket_id = $4
                  AND array_length(objects.path_tokens, 1) <> $2
                  AND ($7 != 'exclude' OR objects.archived_at IS NULL)
                  AND ($7 != 'only' OR objects.archived_at IS NOT NULL)
                  AND ($8 != 'exclude' OR NOT objects.is_delete_marker)
                  AND ($8 != 'only' OR objects.is_delete_marker)
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata,
                   NULL::text AS version,
                   NULL::timestamptz AS archived_at,
                   NULL::boolean AS is_delete_marker,
                   NULL::boolean AS is_versioned FROM folders)
            UNION ALL
            (SELECT array_to_string(path_tokens[$1:$2], '/') AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata,
                   version, archived_at, is_delete_marker, is_versioned
             FROM storage.objects
             WHERE objects.name ILIKE $3 || '%%'
               AND bucket_id = $4
               AND array_length(objects.path_tokens, 1) = $2
               AND ($7 != 'exclude' OR objects.archived_at IS NULL)
               AND ($7 != 'only' OR objects.archived_at IS NOT NULL)
               AND ($8 != 'exclude' OR NOT objects.is_delete_marker)
               AND ($8 != 'only' OR objects.is_delete_marker)
             -- name, then version, as tiebreaks so two versions of the same
             -- key tying on the sort column still sort deterministically
             ORDER BY %I %s, name COLLATE "C" %s, COALESCE(version, '') %s)
            LIMIT $5 OFFSET $6
            $sql$, v_sort_order, v_order_by, v_sort_order, v_sort_order, v_sort_order
        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets, noncurrent_versions, delete_markers;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build a resume-safe batch query. The exact-name branch returns remaining
    -- versions after the current (archived_at, version) boundary; the strict
    -- name branch returns subsequent keys. UNION ALL keeps both predicates
    -- independently indexable.
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" > $2 AND lower(o.name) COLLATE "C" < $3' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" > $2' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 AND lower(o.name) COLLATE "C" >= $3' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        END IF;
    END IF;

    -- Keep the delete-marker predicate literal so the cached generic
    -- plan can use idx_objects_delete_markers during the main-loop peek.
    IF delete_markers = 'only' THEN
        IF v_multi_row THEN
            v_delete_marker_peek_query :=
                'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';
        ELSIF v_is_asc THEN
            -- Two separate literal query strings, not one gated by a bound
            -- boolean: folding "$n AND op1 OR NOT $n AND op2" into a single
            -- query defeats the generic plan's ability to push either
            -- comparison into the index. Branching in PL/pgSQL control flow
            -- instead keeps each query's index condition intact.
            v_delete_marker_peek_query :=
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
                'AND lower(o.name) COLLATE "C" >= $2' ||
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND lower(o.name) COLLATE "C" < $3'
                    ELSE ''
                END ||
                v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1';
            -- Strict variant: used once the single-row ASC batch advance
            -- (below) has left v_next_seek pointing at the last row already
            -- emitted, so a plain >= would re-match it forever.
            v_delete_marker_peek_query_strict :=
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
                'AND lower(o.name) COLLATE "C" > $2' ||
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND lower(o.name) COLLATE "C" < $3'
                    ELSE ''
                END ||
                v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1';
        ELSE
            v_delete_marker_peek_query :=
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
                'AND lower(o.name) COLLATE "C" < $2' ||
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND lower(o.name) COLLATE "C" >= $3'
                    ELSE ''
                END ||
                v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC performs one specialized initial seek so partial current-version
        -- and delete-marker indexes remain available.
        EXECUTE format(
            'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1',
            CASE WHEN v_upper_bound IS NOT NULL
                THEN ' AND lower(o.name) COLLATE "C" >= $2 AND lower(o.name) COLLATE "C" < $3'
                ELSE ''
            END,
            v_version_filter
        )
        INTO v_peek_name
        USING bucketname, v_prefix_lower, v_upper_bound;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch and
    -- the delete-marker-only path
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        v_previous_seek := v_next_seek;
        v_previous_seek_at := v_next_seek_at;
        v_previous_seek_version := v_next_seek_version;
        v_previous_count := v_count;
        v_previous_skipped := v_skipped;

        -- STEP 1: PEEK
        v_peek_name := NULL;
        IF delete_markers = 'only' THEN
            EXECUTE CASE WHEN v_next_seek_strict
                THEN v_delete_marker_peek_query_strict
                ELSE v_delete_marker_peek_query
            END
                INTO v_peek_name
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END,
                    1, v_next_seek_at, v_next_seek_version;
        ELSIF v_multi_row AND v_next_seek_at IS NOT NULL THEN
            SELECT o.name INTO v_peek_name
            FROM storage.objects o
            WHERE o.bucket_id = bucketname
              AND lower(o.name) COLLATE "C" = v_next_seek
              AND (COALESCE(o.archived_at, 'infinity'::timestamptz) < v_next_seek_at
                   OR (COALESCE(o.archived_at, 'infinity'::timestamptz) = v_next_seek_at
                       AND COALESCE(o.version, '') > v_next_seek_version))
              AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
              AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
              AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
              AND (delete_markers != 'only' OR o.is_delete_marker)
            ORDER BY COALESCE(o.archived_at, 'infinity'::timestamptz) DESC,
                     COALESCE(o.version, '') ASC
            LIMIT 1;

            -- The current key is exhausted. Clear its version boundary and
            -- make the following ASC name peek strict. Appending '/' is not a
            -- valid lexical successor because keys ending in characters such
            -- as '!' sort between the exhausted name and name || '/'.
            IF v_peek_name IS NULL THEN
                IF v_is_asc THEN
                    v_next_seek_strict := true;
                END IF;
                v_next_seek_at := NULL;
                v_next_seek_version := '';
            END IF;
        END IF;

        -- Single-row mode is always noncurrent_versions='exclude'. Keep the
        -- current-row predicate literal so generic plans use the current index.
        IF delete_markers != 'only' AND v_peek_name IS NULL AND NOT v_multi_row THEN
            IF v_is_asc THEN
                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                ELSIF v_next_seek_strict THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                ELSIF v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                ELSE
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                END IF;
            ELSIF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                  AND o.archived_at IS NULL
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                  AND o.archived_at IS NULL
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        ELSIF delete_markers != 'only' AND v_peek_name IS NULL AND v_is_asc THEN
            IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSIF v_next_seek_strict THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSIF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSIF delete_markers != 'only' AND v_peek_name IS NULL THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- If the peek landed on a different key than we were tracking, any
        -- version boundary belongs to the OLD key and must not leak into the
        -- new one - e.g. the deleteMarkers='only' peek doesn't know or care
        -- whether it's continuing the same key or jumping to a new one, so
        -- it never clears these itself.
        IF lower(v_peek_name) IS DISTINCT FROM v_next_seek THEN
            v_next_seek_at := NULL;
            v_next_seek_version := '';
        END IF;

        -- The peek is authoritative for the next key to process. This is
        -- especially important after exhausting a multi-version key: the
        -- version boundary has been cleared, so executing the batch against
        -- a stale v_next_seek would replay every version of that old key.
        v_next_seek := lower(v_peek_name);
        v_next_seek_strict := false;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                version := NULL;
                archived_at := NULL;
                is_delete_marker := NULL;
                is_versioned := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
            v_next_seek_at := NULL;
            v_next_seek_version := '';
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size,
                    v_next_seek_at, v_next_seek_version
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it. Reset
                    -- strict mode too - it may have been set by an earlier
                    -- row in this same batch (see the single-row ASC advance
                    -- below), and v_next_seek here is the folder-triggering
                    -- row's own name, which the next peek must find inclusively.
                    v_next_seek := CASE
                        WHEN v_is_asc THEN lower(v_current.name)
                        ELSE lower(v_current.name) || v_delimiter
                    END;
                    v_next_seek_at := NULL;
                    v_next_seek_version := '';
                    v_next_seek_strict := false;
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := substring(v_current.name from v_prefix_len + 1);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    version := v_current.version;
                    archived_at := v_current.archived_at;
                    is_delete_marker := v_current.is_delete_marker;
                    is_versioned := v_current.is_versioned;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Multi-row mode must remain on this key until all of its
                -- versions have crossed the internal batch boundary.
                IF v_multi_row THEN
                    v_next_seek := lower(v_current.name);
                    v_next_seek_at := COALESCE(v_current.archived_at, 'infinity'::timestamptz);
                    v_next_seek_version := COALESCE(v_current.version, '');
                ELSIF v_is_asc THEN
                    -- Appending the delimiter as a fake lexical successor would
                    -- skip a real key like `name || '!'` (or any character
                    -- sorting below the delimiter), which sorts between `name`
                    -- and `name || delimiter`. Track the real name and mark the
                    -- next comparison strict instead - same fix as the
                    -- exhausted-key case above.
                    v_next_seek := lower(v_current.name);
                    v_next_seek_strict := true;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;

        IF v_count = v_previous_count
           AND v_skipped = v_previous_skipped
           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek
           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at
           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN
            RAISE EXCEPTION 'storage.search made no progress at seek (%, %, %)',
                v_next_seek, v_next_seek_at, v_next_seek_version;
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION storage.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$function$
